  chapters = {
    ["ages-past"] = { "Eras pasadas", "La historia del mundo, desde los titanes hasta la última guerra, tal como la cuentan los viejos libros de sus bibliotecas." },
    ["alterac"] = { "Montañas de Alterac", "Un reino caído entre la nieve, Dalaran junto al lago y un valle que dos pueblos reclaman." },
    ["arathi"] = { "Tierras Altas de Arathi", "La cuna de los reinos humanos, arruinada y aún disputada." },
    ["ashenvale"] = { "Vallefresno", "El antiguo bosque de los elfos de la noche y las hachas orcas en su linde." },
    ["azshara"] = { "Azshara", "La tierra de la reina, a orillas del mar que se la tragó." },
    ["badlands"] = { "Tierras Inhóspitas", "Un yermo rojo de cañones y, debajo, la bóveda de los titanes: Uldaman." },
    ["barrens"] = { "Los Baldíos", "La gran sabana seca del corazón de Kalimdor y todos los que luchan por ella." },
    ["blackrock-mountain"] = { "Montaña Roca Negra", "La montaña del Señor del Fuego y la guerra de su interior." },
    ["blasted-lands"] = { "Las Tierras Devastadas", "El yermo rojo que rodea el Portal Oscuro." },
    ["burning-steppes"] = { "Las Estepas Ardientes", "La llanura de ceniza al sur de la montaña, donde antes se alzaba Crestagrana." },
    ["callings"] = { "Las vocaciones", "Los caminos de las armas, la fe y la magia que puede seguir un viajero, y el origen de cada uno." },
    ["darkshore"] = { "Costa Oscura", "Una larga costa brumosa de ruinas de los elfos de la noche, al otro lado del agua frente al Árbol del Mundo." },
    ["deadwind-pass"] = { "Paso de la Muerte", "El valle muerto del último Guardián." },
    ["desolace"] = { "Desolace", "Una tierra gris y muerta de centauros, huesos y demonios." },
    ["dun-morogh"] = { "Dun Morogh y Forjaz", "Los valles nevados que rodean Forjaz, cuna del clan Barbabronce." },
    ["durotar"] = { "Durotar y Orgrimmar", "La tierra roja que Thrall dio a su pueblo y la ciudad llamada como el Jefe de Guerra que lo liberó." },
    ["duskwood"] = { "Bosque del Ocaso", "Un bosque donde la noche nunca termina del todo y los muertos no permanecen enterrados." },
    ["dustwallow"] = { "Marjal Revolcafango", "La ciudad insular de lady Valiente, un pantano lleno de dragones y una posada que ardió." },
    ["eastern-plaguelands"] = { "Tierras de la Peste del Este", "El antiguo Bosque del Este, Stratholme y la necrópolis del cielo." },
    ["elwynn"] = { "Bosque de Elwynn y Ventormenta", "El corazón del reino humano: su bosque, sus granjas y la ciudad blanca reconstruida de sus cenizas." },
    ["felwood"] = { "Frondavil", "El bosque envenenado donde se encontró la Calavera de Gul'dan." },
    ["feralas"] = { "Feralas", "Árboles gigantes, ogros y las ruinas de los Altonato." },
    ["hillsbrad"] = { "Laderas de Trabalomas", "Colinas verdes donde los vivos y los Renegados luchan por cada granja." },
    ["hinterlands"] = { "Tierras del Interior", "Las colinas salvajes de los enanos Martillo Salvaje y los templos trols con los que las comparten." },
    ["loch-modan"] = { "Loch Modan", "La comarca del lago al este de Forjaz, retenido por una presa y vigilado por reyes de piedra." },
    ["moonglade"] = { "Claro de la Luna", "El valle sagrado de los druidas." },
    ["mulgore"] = { "Mulgore y Cima del Trueno", "Las llanuras verdes de los tauren y la ciudad sobre las mesetas." },
    ["peoples"] = { "Pueblos y poderes", "Los pueblos, órdenes y facciones que un viajero encuentra en muchas tierras, reunidos en un solo lugar." },
    ["redridge"] = { "Montañas Crestagrana", "Colinas rojas, un lago tranquilo y una población asediada desde el norte." },
    ["searing-gorge"] = { "La Garganta de Fuego", "La cara norte quemada de la montaña y la gran fosa de los Hierro Negro." },
    ["shen-dralas"] = { "Shen'dralas", "La tierra maldita del Valle de los Huesos, donde los centauros han encontrado a los muertos." },
    ["silithus"] = { "Silithus", "El desierto de los insectos, el Muro del Escarabajo y lo que duerme detrás." },
    ["silverpine"] = { "Bosque de Argénteos", "Pinos grises entre los Renegados y la puerta cerrada de Gilneas." },
    ["soundtrack"] = { "La banda sonora", "Las melodías de la música del juego." },
    ["stonetalon"] = { "Sierra Espolón", "Altas cumbres y bosques antiguos que arden bajo las sierras goblins." },
    ["stranglethorn"] = { "Vega de Tuercespina", "La jungla del antiguo imperio trol, donde piratas, cazadores y goblins buscan fortuna." },
    ["swamp-of-sorrows"] = { "Pantano de las Penas", "Una tierra anegada de niebla y lodo, y un templo hundido por sus pecados." },
    ["tanaris"] = { "Tanaris", "El gran desierto del sur y las puertas de los Vigías." },
    ["teldrassil"] = { "Teldrassil y Darnassus", "El nuevo Árbol del Mundo de los elfos de la noche y la ciudad de su copa." },
    ["thousand-needles"] = { "Las Mil Agujas", "Un cañón de agujas de piedra y una llanura salina donde compiten goblins y gnomos." },
    ["tirisfal"] = { "Claros de Tirisfal y Entrañas", "El corazón del reino caído de Lordaeron y los Renegados que gobiernan bajo su capital en ruinas." },
    ["ungoro-crater"] = { "Cráter de Un'Goro", "Un mundo perdido en un cráter y sus misteriosos cristales." },
    ["western-plaguelands"] = { "Tierras de la Peste del Oeste", "El corazón muerto de Lordaeron, donde comenzó la peste." },
    ["westfall"] = { "Páramos de Poniente", "El granero de Ventormenta, reducido a polvo y bandidos." },
    ["wetlands"] = { "Los Humedales", "Las marismas entre Khaz Modan y Arathi, donde los caminos enanos se cruzan con viejas guerras." },
    ["winterspring"] = { "Cuna del Invierno", "Nieve, goblins y la maldición de los Altonato." },
    ["zephras-isle"] = { "Isla de Zephras", "La isla flotante de los cielonatos, en la Muro Celeste." },
  },
  -- the game's own texts, by their English titles: each text's pages, and
  -- the start of its English first page (to tell apart those sharing a title)
  books = {
    ["A Bloodstained Envelope"] = { { ids = { "i22930" }, first = "myemilyafewshortdaysagow", pages = { "Mi querida Emily:\n\nHace pocos días abandonamos el campamento en este lugar dejado de la mano de la Luz, siguiendo las órdenes del rey de regresar a casa. A pesar de lo inhóspito del paisaje, mi corazón estaba henchido de gozo, ya que sabía que tras el frío y penoso viaje hacia la costa y más allá, podría solazarme entre tus brazos.\n\nHoy alcanzamos la costa y descubrimos que nuestros barcos, con los que íbamos a regresar, se habían convertido en cascajos quemados. No podemos irnos y no tenemos otra opción que internarnos en el corazón de esta abismal tierra baldía.\n\nHe ido hasta el mismo fin del mundo para mantenerte a salvo, Emily... y ahora... desearía con todo mi corazón haberme quedado contigo en Lordaeron.\n\nEstás presente en cada momento de vigilia. En esta tierra gélida, tú eres mi fuente de calor, mi amada, y nadie podrá quitarme eso.\n\nMaxwell" } } },
    ["A Bloodstained Journal Page"] = { { ids = { "i939" }, first = "downwardspiralofdespairf", pages = { "... he entrado en una espiral de desesperación. Primero se burla de mí y ahora está comprometida. Esa charlatana descortés fingía que me amaba cuando en realidad solo deseaba herirme. Me abruma un oscuro vacío que crece con el tiempo y se hace más intenso al despertar. La sangre que derramaré palidece frente a las lágrimas que he vertido..." } } },
    ["A Careworn Note"] = { { ids = { "i22945" }, first = "dearestameliatonightihav", pages = { "Queridísima Amelia:\n\nEsta noche he visto cosas que me rondarán hasta el final de mis días.\n\nStratholme está en llamas... y nosotros somos los causantes del incendio.\n\nNuestro príncipe nos condujo a las calles de la ciudad por la noche. Ordenó entrar en las casas del pueblo y... matarlos mientras dormían. Estaban apestados, según Lord Arthas y, antes de que nos mataran, debían ser asesinados.\n\nFue una carnicería. Cientos murieron silenciosamente bajo las espadas de aquellos que habían jurado protegerlos. No pude permanecer ni un minuto más allí:\n\nHuí. Aunque me haya convertido en un desertor, no puedo cometer semejantes atrocidades. En cada casa no veía más que tu rostro o los de nuestros niños, confundidos con los de las víctimas. Si estar contra esto significa ser un traidor, entonces lo soy.\n\nEspero poder encontrar el camino de regreso que me lleve a estar contigo, pero los caminos son inseguros. Transmite a nuestros hijos mi amor en mi ausencia.\n\nJames" } } },
    ["A Clue to Sander's Treasure"] = { { ids = { "i1358" }, first = "goodworkmateynowyeneedto", pages = { "¡Buen trabajo, colega! Ahora tienes que dirigirte al este. A los acantilados del este (orientales?), al este del camino. Busca las viejas ruinas de la chimenea que están al pie del camino. Allí encontrarás un viejo barril con la siguiente pista." } } },
    ["A Crumpled Missive"] = { { ids = { "i22944" }, first = "helianaivargusyetlivedes", pages = { "Heliana:\n\nYo, Vargus, vivo, a pesar de que tú desees lo contrario. Desprecio profundamente ir de un lado a otro metido en esta ridícula armadura.\n\nNuestras últimas órdenes nos hicieron marchar hacia Andorhal en busca de grano o cualquier otra idiotez. ¿Por qué habrían de importarme los almacenes de alimento en Andorhal? Estar en el ejército es completamente absurdo.\n\nTía Heliana, ten la seguridad de que regresaré para hacerme con tu herencia. Aunque quedara gravemente herido y sin alimento, el puro rencor me llevaría en andas para hacerme con la recompensa.\n\nVargus" } } },
    ["A Dusty Unsent Letter"] = { { ids = { "i889" }, first = "tothehonorableheadmaster", pages = { "Para el honorable Rector Crillian:\n\nMi antiguo maestro, os escribo para que sepáis lo que vuestro antiguo alumno ha estado haciendo últimamente. Siguiendo vuestro consejo, he procurado cultivar mis conocimientos y aumentar mi sabiduría viajando fuera de nuestra amada Ventormenta. Los viajes me han llevado a muchos lugares, pero he decidido instalarme en el bello poblado de Arrollo de la Luna. Los campos que rodean los Páramos de Poniente son más bellos a medida que se avecina la cosecha.", "A los pocos días de mi visita, ya estaba dando clases a los niños que habitan los cultivos vecinos. Las lecciones tuvieron tanto éxito, que el alcalde del pueblo me encargó que abriera una escuela, de manera que se inició la construcción de unas aulas totalmente nuevas. De Argénteos a Ventormenta, y ahora Arrollo de la Luna. ¡Quién iba a imaginar que conocería tanto Azeroth!\n\nUn saludo afectuoso,\n\nStalvan Mantoniebla" } } },
    ["A Faded Journal Page"] = { { ids = { "i921" }, first = "moststrangeanduncontroll", pages = { "... qué sentimiento tan extraño e incontrolable. No había sentido nunca lo que sentí hoy. Mientras ayudaba a Giles con sus lecciones de historia, Tilloa cuidaba del jardín de flores. Transcurridos unos minutos, entró en casa y colocó una begonia escarlata en la palma de mi mano y me sonrió de un modo tan especial, que sentí cómo mi corazón palpitaba con fuerza..." } } },
    ["A Letter to Grelin Whitebeard"] = { { ids = { "i2188" }, first = "grelinmytimeisshortandma", pages = { "Grelin:\n\nMe queda poco tiempo y muchos asuntos me preocupan, así que espero que tu investigación sobre los trols no sea una preocupación más. Por esta razón, permitiré que utilices mi autoridad como mejor te parezca para tratar con los trols, sobre todo si te permite encontrar una solución oportuna.\n\nMagni Barbabronce" } } },
    ["A Mysterious Message"] = { { ids = { "i1381" }, first = "blacknailstheseaawaitsus", pages = { "Uñasnegras,\n\nLa mar nos aguarda. Necesitamos tus suministros procedentes del norte. Desmantélalo todo: rieles de ferrocarril, cubos de agua... Necesitamos metal. Hace tiempo que tenía que haber llegado un cargamento de BB. No me falles, Uñasnegras. Esta vez, envía tus provisiones directamente al \"granero\". No hay tiempo que perder.\n\nVanCleef" } } },
    ["A Ragged Page"] = { { ids = { "i22946" }, first = "samlaaswefollowourlordar", pages = { "Samla:\n\nA medida que seguimos a Lord Arthas en dirección al norte, siempre hacia el norte, mi corazón se entristecía cada vez más. Si bien una vez estuvo tocado por la Luz, ahora siento la oscuridad del espíritu del joven paladín. Su celo está oscurecido por una inquietante y extraña pesadilla que inunda su alma, imposible de adivinar...\n\nPronto avistaremos tierra en los gélidos páramos. Aunque muchos de sus hombres han enfermado por el frío y por las batallas con las pútridas bestias, Arthas nos comunicó que lo que está buscando en el hielo cambiará el sentido de la batalla. Pero sus palabras no me han tranquilizado, porque después de pronunciarlas... la macabra sonrisa que se dibujó en sus ondulados labios me provocó un escalofrío más profundo que el de cualquier ventisca.\n\nReza por nosotros, Samla, y reza por nuestro mundo,\n\nTorgal" } } },
    ["A Short Note"] = { { ids = { "i9329" }, first = "curgleihavebeeneagerlyaw", pages = { "Curgle,\n\nLlevo esperando tu nuevo invento con ansiedad. No puedo esperar a usarlo para documentar mis estudios.\n\nPor favor, confíaselo a mi $gmensajero:mensajera;.\n\nUn saludo,\n\nDaryn Brisela" } } },
    ["A Smudged Document"] = { { ids = { "i22948" }, first = "dearpamelatomorrowwemake", pages = { "Querida Pamela:\n\nMañana entraremos en batalla en Andorhal y me temo, amor mío, que esta va a ser mi última carta. Los no-muertos no se cansan y nosotros solo somos humanos. No podemos enfrentarnos a ellos. Pero no te inquietes, ya que, aunque estamos seguros de que vamos a morir, nuestras esperanzas permanecen firmes. ¡La Luz vencerá!\n\nY, querida mía, me alegra saber que, mientras estos oscuros terrores derriban nuestros muros y caen sobre nosotros, mis últimos pensamientos no serán de muerte. Te recordaré entre mis brazos y, finalmente, tendré paz.\n\nChristoph" } } },
    ["A Torn Journal Page"] = { { ids = { "i916" }, first = "gilestheboyseemsabitramb", pages = { "... Giles, el chico, parece un poco arrogante y su educación será todo un desafío. No obstante, Tilloa, la hija mayor, parece extraordinariamente inteligente. Por otra parte, no he podido obviar su cautivadora belleza. Está en la flor de la edad. Al parecer, el señor ha fijado su boda para el próximo año. Pero cambio de tema. Esta semana acompañaré a la familia a su casita de verano junto al aserradero de la Vega del Este en Elwynn, cerca de las montañas Crestagrana. Espero escribir con mayor asiduidad cuando esté allí." } } },
    ["A Torn Letter"] = { { ids = { "i22932" }, first = "reubeniwritethisletterkn", pages = { "Reuben,\n\nte escribo a sabiendas que quizás nunca leas esto. No puedo permanecer inmóvil escuchando los golpes contra los muros de la Vega del Amparo. Los no-muertos rodean nuestra aldea y nos atacan constantemente. Tenemos que defender a nuestra gente hasta que lleguen los refuerzos.\n\nMe rompí la pierna durante el último ataque y aquí me ves, inútil y dejando una brecha en nuestras filas. No se escucha otro sonido que el de la batalla y la muerte. El miedo se huele en el aire.\n\nEl príncipe Arthas está aquí, peleando en el frente con sus hombres. Si él no estuviese aquí ya hubiésemos muerto hace tiempo. Su amor por este territorio y su gente es abrumante. Sigo sus órdenes con esmero, con mi pierna rota o no, y por ello no puedo quedarme aquí. Tengo que ayudar con mi espada en el frente. Espero que estas palabras te lleguen en un mejor momento.\n\nTu amigo,\nLeagrem" } } },
    ["A Treatise on Military Ranks"] = { { ids = { "o179706", "i18664" }, first = "atreatiseonmilitaryranks", pages = { "TRATADO SOBRE LOS RANGOS MILITARES\n\nLo que sigue son\n\nlos rangos militares\n\nde la Alianza,\n\nprecedido por la\n\ninformación tal y como\n\nla conocen las razas\n\nde la Horda. Cada rango\n\nse muestra en dos\n\nsecciones: los oficiales y luego, los soldados rasos, con los rangos correspondientes a cada uno, enumerados en orden descendente, del superior al inferior. ¡Larga vida a la Alianza!", "RANGOS DE LOS OFICIALES DE LA ALIANZA\n\nParte 1\n\nGran mariscal\n\nMariscal de campo\n\nMariscal\n\nComandante\n\nTeniente coronel", "RANGOS DE OFICIALES DE LA ALIANZA\n\nParte 2\n\nCampeón caballero\n\nCapitán caballero\n\nTeniente caballero\n\nCaballero", "RANGOS DE SOLDADOS DE LA ALIANZA\n\nAlférez\n\nSargento primero\n\nSargento\n\nCabo\n\nSoldado", "RANGOS DE OFICIALES DE LA HORDA\n\nParte 1\n\nGran Señor de la Guerra\n\nSeñor de la Guerra\n\nGran general\n\nGeneral\n\nCampeón", "RANGOS DE OFICIALES DE LA HORDA\n\nParte 2\n\nCenturión\n\nLegionario\n\nGuardia de sangre\n\nGuardia de piedra", "RANGOS DE SOLDADOS DE LA HORDA\n\nGran capataz\n\nCapataz primero\n\nCapataz\n\nBruto\n\nExplorador" } } },
    ["Acolyte's Note"] = { { ids = { "i205184" }, first = "gakin", pages = { "<La página está manchada de sangre, pero consigues distinguir un nombre>.\n\nGakin" } }, { ids = { "i208224" }, first = "carendin", pages = { "<El texto de la página está casi cubierto de sangre, pero se distingue un nombre.>\n\nCarendin" } } },
    ["Admiral Barean Westwind"] = { { ids = { "o175772" }, first = "admiralbareanwestwindgra", pages = { "Almirante Barean Viento Oeste\nGran almirante de la Flota Escarlata\nCiudadano de Kul'Tiras\nPerdido en la Costa Helada de Rasganorte" } } },
    ["Admiral Proudmoore's Orders"] = { { ids = { "i4883" }, first = "officialordersforthekult", pages = { "Órdenes oficiales para la flota Kul Tiras\n\nYo, el almirante Valiente, dirigiré el primer desembarco en las costas de Kalimdor.\n\nEn mi ausencia, el teniente Benedict será el segundo en la cadena de mando. Todas las cuestiones militares de Kul Tiras de carácter doméstico serán gestionadas por él. Si no envío mensaje alguno desde el Fuerte de Tiragarde transcurridos 12 meses, el teniente Benedict dirigirá la segunda oleada para conquistar la posición.", "Mientras tanto, envío al teniente Alverold en una misión de exploración por el continente de Kalimdor. Sus fuerzas deben completar la misión y luego deben reunirse con nuestras fuerzas en el Fuerte de Tiragarde.\n\nSe da por supuesto que la misión del teniente Alverold tardará tiempo en realizarse. La nueva tierra parece vasta y peligrosa. Pero si la mala fortuna nos alcanza a Benedict o a mí, las tropas de Alverold volverán a tomar el Fuerte.\n\n¡Enviaremos oleada tras oleada hasta que el fuerte sea nuestro!\n\nAlmirante Valiente" } } },
    ["Advisor Emerson's Instructions"] = { { ids = { "i285356" }, first = "greetingsasaguestoftheal", pages = { "Saludos:\n\nLa Alianza se alegra de tu llegada y te otorga permiso para viajar con total libertad por sus tierras.\n\nEste documento te servirá como guía para llegar al resto de ciudades pertenecientes a nuestra alianza.", "Tu primera parada debería ser Forjaz, a la que puedes llegar gracias a esa maravilla tecnológica que es el Tranvía Subterráneo.\n\nLa entrada del tranvía se encuentra en el Distrito de los Enanos, aquí, en Ventormenta, justo al sudoeste del castillo. El tranvía te llevará de forma segura al corazón de Forjaz.\n\nCuando llegues, explora la ciudad y habla con el manitas mayor Mekkatorque y con el rey Magni Barbabronce en Ciudad Manitas y en la Gran Forja respectivamente. Preséntate como agente de los célicos y te mostrarán su hospitalidad.", "Darnassus está al otro lado del mar, en la costa del norte de Kalimdor. La propia ciudad descansa sobre la copa del gran árbol Teldrassil.\n\nLa ruta más segura para ti es por el puerto al oeste de Ventormenta. Sube al barco del muelle más al sur hasta el puerto de Auberdine.\n\nAl llegar, dirígete a la parte norte de los muelles de Auberdine y toma otro barco hasta la aldea de Ru'theran, donde encontrarás un transportador mágico que te llevará a la ciudad.\n\nExplora Darnassus y habla con Tyrande Susurravientos, la suma sacerdotisa de Elune.", "Cuando hayas conocido al resto de líderes de la Alianza, lord Fordragón quiere que te presentes ante él aquí, en el castillo.\n\nTe deseo buena suerte en tus viajes, visitante de los célicos." } } },
    ["Advisor Nazgrel's Instructions"] = { { ids = { "i285357" }, first = "elfasaguestofthehordethe", pages = { "Trotamundos de los elfos:\n\nLa Horda ha tenido a bien invitarte, y el Jefe de Guerra te ha otorgado permiso para viajar con libertad por nuestro territorio.\n\nUsa esta guía para ubicarte en nuestras tierras.", "En esta misma sala encontrarás a Vol'jin de la tribu Lanza Negra.\n\nLos trols Lanza Negra son amigos leales de los orcos. Nuestro vínculo se selló con sangre en el fragor de la batalla durante nuestra huida de las tierras humanas hasta el continente del este.\n\nTrátalo con respeto y él hará lo mismo. Si le faltas al respeto... Bueno, yo de ti no lo haría.", "A continuación, te recomiendo que vuelvas a Mulgore y te reúnas con Cairne Pezuña de Sangre en Cima del Trueno.\n\nCairne es el jefe de la tribu Pezuña de Sangre de los tauren y, gracias a él, tu gente y el Anillo de la Tierra habéis recibido permiso para estableceros en Mulgore.\n\nYa tendrías que conocer el camino a Cima del Trueno. Habla con el maestro de vuelo en el centro de Orgrimmar y sube a lomos de un dracoleón hasta Cima del Trueno. Cairne estará en la meseta central, justo al este del gran tótem que sirve de alcándara de dracoleones en la ciudad.", "Nuestros aliados renegados tienen su hogar en la región conocida como Claros de Tirisfal, en el continente del este. Encontrarás la ciudad de Entrañas bajo las ruinas de lo que antaño fue Lordaeron.\n\nPara llegar a Tirisfal, sal de la ciudad por la puerta del sur y dirígete al este, hacia la torre del zepelín.\n\nEmbarca en el zepelín de la zona sur de la torre y, tras cruzar el gran mar, llegarás a Rémol. Desde allí, solo debes dirigirte al norte hasta las ruinas de Lordaeron.\n\nEncuentra el ascensor, desciende hasta las profundidades de Entrañas y busca a la Dama Oscura en el Barrio Real.\n\nUn aviso: La capital de los renegados puede llegar a ser... inquietante." } } },
    ["Aegwynn and the Dragon Hunt"] = { { ids = { "o175738" }, first = "asthepoliticsandrivalrie", pages = { "Mientras las relaciones políticas y las rivalidades de las siete naciones humanas experimentaban altibajos, la línea de los guardianes mantuvo una vigilancia constante contra el caos. Durante años, hubo muchos guardianes, pero solo uno mantuvo siempre los poderes mágicos de Tirisfal. Una de las últimas guardianas de la era destacó como una poderosa guerrera en la lucha contra el mal.", "Aegwynn, una humana muy temperamental, obtuvo la aprobación de la orden que le concedió el manto de la custodia. Aegwynn luchó valerosamente para dar caza y erradicar a los demonios allí donde los encontró, pero, a menudo, cuestionó la autoridad del Consejo de Tirisfal.", "Creía que los elfos antiguos y los elfos ancianos que presidían el consejo eran demasiado rígidos en su forma de pensar y que, a la hora de terminar de una vez por todas con el conflicto contra el caos, resultaban cortos de miras. Mostrándose impaciente cuando se trataba de discutir largamente, siempre quería probarse a sí misma ante sus pares y sus superiores y, como resultado de todo ello, frecuentemente escogió el valor antes que la sabiduría en situaciones cruciales.", "A medida que creció su dominio sobre el poder cósmico de Tirisfal, Aegwynn se dio cuenta de la existencia de un gran número de poderosos demonios que acechaban la helada parte norte del continente de Rasganorte. Viajando al distante norte, Aegwynn rastreó a los demonios en las montañas. Allí cayó en la cuenta de que los demonios estaban cazando a uno de los últimos Vuelos supervivientes, despojando a las antiguas criaturas de su magia innata.", "Los poderosos dragones, que habían huido de las amenazantes sociedades mortales, se encontraron enfrentados en igualdad de condiciones a los siniestros poderes de la Legión. Aegwynn se enfrentó a los demonios y, con la ayuda de los nobles dragones, terminó por erradicarlos. Aun así, cuando el último demonio desapareció del mundo mortal, se desató una gran tormenta por todo el norte.", "Un enorme rostro oscuro apareció en el cielo por encima de Rasganorte. Sargeras, el rey demonio y señor de la Legión Ardiente, apareció ante Aegwynn y manifestó su infernal cólera. Comunicó a la joven guardiana que el tiempo de Tirisfal estaba a punto de llegar a su fin y que pronto el mundo perecería a manos de la Legión.", "La orgullosa Aegwynn, creyendo estar a la altura del dios amenazante, dio rienda suelta a sus poderes contra el avatar de Sargeras. Con una facilidad desconcertante, Aegwynn batió al señor de los demonios con sus poderes y logró acabar con su envoltura física. Ante el temor de que el espíritu de Sargeras sobreviviera, Aegwynn encerró los despojos de su cuerpo en una de las antiguas salas de Kalimdor que se habían hundido en las profundidades del mar cuando el Pozo de la Eternidad se desintegró.", "Aegwynn nunca llegaría a saber que hizo justamente lo que Sargeras pretendía. Sin saberlo, selló el destino del mundo mortal, ya que Sargeras, en el momento de su muerte corpórea, transfirió su espíritu al debilitado cuerpo de Aegwynn. Sin que la joven guardiana fuera consciente de ello, Sargeras permanecería encubierto en las profundidades más oscuras de su alma durante muchos años." } } },
    ["Aftermath of the Second War"] = { { ids = { "o21581" }, first = "thedevastatingsecondwara", pages = { "La devastadora Segunda Guerra contra la horda orca dejó la Alianza de Lordaeron en un estado de desolación y confusión. Los sanguinarios orcos, dirigidos por el poderoso jefe de guerra Orgrim Martillo Maldito, no solo destrozaron todo lo que encontraron a su paso en las tierras de Khaz Modan, en poder de los enanos, sino que también arrasaron muchas provincias centrales de Lordaeron. Los orcos implacables llegaron a arrasar el\nremoto reino elfo de Quel'Thalas antes de que les pararan los pies.", "Los ejércitos de la Alianza, dirigidos por Sir Anduin Lothar, Uther el Iluminado y el almirante Valiente, expulsaron a los orcos hacia el sur, hasta la tierra desolada de Azeroth, el primer reino que cayó ante el ataque despiadado de los orcos.\n\nLas fuerzas de la Alianza, bajo las órdenes de Sir Lothar, lograron expulsar a los clanes de Martillo Maldito de Lordaeron, confinándolos en las tierras de Azeroth controladas por los orcos. Las fuerzas de Lothar rodearon la ciudadela volcánica de la Cumbre de Roca Negra y sitiaron sus defensas.", "En su encarnizada defensa, Martillo Maldito y sus lugartenientes llevaron a cabo una audaz ofensiva desde la Cumbre y combatieron a los paladines de Lothar en el centro de las Estepas Ardientes. Martillo Maldito y Lothar se enzarzaron en una titánica batalla que dejó a los dos poderosos combatientes apaleados y exhaustos. Si bien por poco Martillo Maldito derrota a Lothar, la muerte del gran héroe no tuvo el efecto que el jefe de guerra habría deseado.", "Turalyon, el lugarteniente más leal de Lothar, cogió el escudo de este manchado de sangre y convocó a sus hermanos apesadumbrados para emprender un atroz contraataque. Bajo los raídos estandartes de Lordaeron y Azeroth, las tropas de Turalyon masacraron a casi todas las fuerzas restantes de Martillo Maldito, sometiéndolas a una gloriosa, pero terrible derrota.", "Para los andrajosos y dispersos supervivientes orcos no quedaba otra opción que escapar al último bastión de las fuerzas orcas: el Portal Oscuro.\n\nTuralyon y sus guerreros persiguieron a los orcos supervivientes por el inmundo Pantano de las Penas, hasta las corruptas Tierras Devastadas en las que se hallaba el Portal Oscuro. Allí, junto al colosal portal, la horda destrozada y la inquebrantable Alianza se enfrentaron en lo que sería la última y más sangrienta batalla de la Segunda Guerra.", "Inferiores en número y enloquecidos por la maldición de su sed de sangre, los orcos sucumbieron inevitablemente a la ira de la Alianza. A Martillo Maldito lo hicieron prisionero y lo escoltaron hasta Lordaeron, mientras sus clanes rotos fueron acorralados y expulsados al norte, de nuevo en Lordaeron." } } },
    ["Alexston's Reply"] = { { ids = { "i279048" }, first = "iknowhowthisletterwillfi", pages = { "Sé en qué circunstancias te llegará esta carta y lo lamento de veras, anciano.\n\nSin duda enviaré a vuestra hermosa villa a cuantos aventureros capaces encuentre. Espero que su ayuda compense la falta de otro apoyo que pueda ofrecer ahora.\n\nNuestras tierras sufren la presión de muchos enemigos. Seguro que conoces bien ese mundo, pero ha agotado dolorosamente nuestros recursos.\n\nSi eso cambia, me encantaría ayudar, aunque incluso entonces hay muchos proyectos cerca de casa que tendrán prioridad.\n\nResistid. Estamos todos juntos en esto.\n\n-- Baros Alexston\nArquitecto urbano, Ventormenta" } } },
    ["Alliance Military Ranks"] = { { ids = { "o179735" }, first = "alliancemilitaryranksoff", pages = { "RANGOS MILITARES DE LA ALIANZA\n\nOFICIALES\n\nGran mariscal\n\nMariscal de campo\n\nMariscal\n\nComandante\n\nTeniente coronel\n\nCampeón caballero\n\nCapitán caballero\n\nTeniente caballero\n\nCaballero\n\nTROPA\n\nAlférez\n\nSargento primero\n\nSargento\n\nCabo\n\nSoldado" } } },
    ["Altar of Zanza"] = { { ids = { "o180367" }, first = "wecalluponyouzanzaofzuld", pages = { "Te convocamos, Zanza de Zuldazar.\n\nBendice a los que pidan tu ayuda, Loa Zanza. Bendice a aquellos que establecerían una alianza con el pueblo de Zandalar.\n\nAyúdanos en tiempo de necesidad. Ayúdanos, Loa. Danos el poder para derrotar a nuestros enemigos. Danos el poder para derrotar una vez más al Dios de la Sangre." } } },
    ["An Exotic Cookbook"] = { { ids = { "i5428" }, first = "getoneoreightmanhitmanha", pages = { "1. Toma uno u ocho hombres\n2. Golpea al hombre con fuerza\n3. Golpea más al hombre\n4. Coloca al hombre en el fuego\n5. Cómete al hombre" } } },
    ["An Undelivered Letter"] = { { ids = { "i910" }, first = "dearnoblesirwordofyourne", pages = { "Querido y noble señor:\n\nA la Posada Orgullo de León de Villadorada, donde resido temporalmente, me han llegado noticias de vuestra necesidad de un tutor para vuestros hijos. Debido a los desafortunados acontecimientos que han tenido lugar en la región, me he visto obligado a abandonar mi cargo de rector de la escuela de Arrollo de la Luna. Os ruego que aceptéis mi solicitud para trabajar como tutor de vuestros hijos. Si es necesario, el rector Crillian de la Academia os proporcionará referencias de mi trabajo.", "Iré a conoceros en persona cuando las lluvias invernales amainen y los caminos vuelvan a ser transitables.\n\nHasta pronto,\n\nStalvan Mantoniebla de Argénteos" } } },
    ["Ancient Inscription"] = { { ids = { "o19025" }, first = "theshrineofmelthandrisma", pages = { "El Santuario de Mel'Thandris\n\n\"Que la Luz de Elune brille sobre este valle eterno e ilumine los caminos del bosque como ha ocurrido desde tiempo inmemorial.\"" } } },
    ["Ancient Tablet"] = { { ids = { "i9242" }, first = "themalletofzulfarraktocr", pages = { "La maza de Zul'Farrak\n\nPara crear la maza de Zul'Farrak, primero hay que viajar al Altar de Zul y obtener la maza sagrada de un guardián trol.\n\nA continuación, debes llevar la maza sagrada al altar, en lo alto de la ciudad trol de Jintha'alor.\n\nSi usas esta maza sagrada en el altar, adquirirá los poderes necesarios y se convertirá en la maza de Zul'Farrak." } } },
    ["Annals of Darrowshire"] = { { ids = { "i12900" }, first = "theannalsofdarrowshireda", pages = { "Las crónicas de Villa Darrow\n\nVilla Darrow, nombrada así por el lago Darrowmere, situado al oeste, es una ciudad que se encuentra entre las estribaciones sureñas de Lordaeron. Conocida por sus humildes pero trabajadores residentes, Villa Darrow permaneció en segundo plano en la historia de Lordaeron hasta la Segunda Guerra.\n\nLos héroes se forjaron durante la guerra. Y allí perecieron.", "La Batalla de Villa Darrow\n\nLa Batalla de Villa Darrow tuvo lugar en mitad de la Segunda Guerra, cuando las fuerzas de la Plaga arrasaron Lordaeron. Villa Darrow quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por un cuerpo de tropas, un contingente de paladines Mano de Plata y un incondicional grupo de milicia local dirigido por el capitán Joseph Rutagrana.", "Los primeros asaltos de la Plaga sobre Villa Darrow fueron espaciados. Pequeños grupos de esqueletos y cadáveres merodeadores anduvieron por las afueras de la ciudad y fueron repelidos.\n\nPero la Plaga no fue derrotada debido a la tenacidad de los defensores y respondió adecuadamente. Poco después de producirse la primera ola de atacantes, apareció una segunda. Necrófagos campeones, sirvientes del señor necrófago Horgus, aullaron desde las colinas y chocaron con los asediados defensores de Villa Darrow.", "Los defensores quedaron debilitados, pero fueron liberados por paladines, discípulos de los Mano de plata. Su líder, Davil Vasijan, había nacido en Villa Darrow. Condujo a sus seguidores a la ciudad cuando supo del inminente ataque y, junto con los defensores, rechazaron a los siervos de Horgus.\n\nCuando el propio Horgus entró en batalla, se encontró con Davil. Lucharon durante varios minutos y, finalmente, Davil venció, pero sufrió una herida mortal y, poco después de derrotar al señor necrófago, murió.", "La batalla continuó y el capitán Rutagrana dirigió a su milicia valientemente. Si el oscuro caballero de la Muerte Marduk el Negro no hubiera corrompido al capitán, habrían podido ganar.\n\nEn medio de la refriega, Marduk se acercó a Rutagrana y, con ayuda de la magia negra, liberó el espíritu de este, convirtiéndolo en una sombra maligna del valiente capitán.", "Luego, el corrupto capitán Rutagrana esparció su influencia maligna entre los defensores de Villa Darrow, que traicionaron a sus aliados y los asesinaron. A continuación, volvieron a la ciudad de Villa Darrow y mataron a todos aquellos que estaban ocultos en sus casas.\n\nEl ejército restante de la Plaga, junto con el espíritu corrupto del capitán Rutagrana, abandonó posteriormente la devastada ciudad de Villa Darrow y arremetió contra Lordaeron, provocando el dolor y la muerte de la Segunda Guerra." } } },
    ["Another Clue to Sander's Treasure"] = { { ids = { "i1361" }, first = "nowfromthisherebarrelfac", pages = { "Cuando hayas llegado hasta el barril, dirígete hacia el norte. Recto como el vuelo de un cuervo, sigue tu camino hasta la tinaja vacía que está junto al molino de viento del acantilado. Si husmeas en la tinaja, tal vez encuentres lo que estabas buscando." } } },
    ["Arathor and the Troll Wars"] = { { ids = { "o175734" }, first = "asthehighelvesfoughtfort", pages = { "Cuando los altos elfos hacían frente al feroz ataque de los trols, los dispersos humanos nómadas de Lordaeron lucharon por consolidar sus propias tierras tribales. Las antiguas tribus humanas atacaban asentamientos hermanos sin contemplar valores tales como la unificación racial o el honor.", "No obstante, una tribu conocida como los arathi advirtió que los trols se estaban convirtiendo en una amenaza demasiado importante como para ignorarla. Los arathi deseaban dominar a las demás tribus para unificar fuerzas contra el ejército trol.", "En seis años, los astutos arathi se mostraron más hábiles y derrotaron a las tribus rivales. Tras cada victoria, los arathi ofrecieron paz e igualdad al pueblo conquistado, obteniendo la lealtad de los pueblos derrotados. Finalmente, la tribu de los arathi conquistó numerosas tribus dispares, logrando que su ejército creciera de forma significativa.", "Confiando en su capacidad de contener a las bandas de los trols con sus tropas o, incluso, con los aislados elfos si era necesario, los señores de la guerra arathi decidieron construir una poderosa ciudad fortificada en las tierras del sur de Lordaeron. La ciudad estado, llamada Strom, se convirtió en la capital de la nación arathi, Arathor. A medida que Arathor prosperaba, los humanos que habitaban en todo el continente viajaban hacia el sur para garantizar la protección y la seguridad de Strom.", "Unidos bajo la misma bandera, las tribus humanas desarrollaron una cultura sólida y optimista. Thoradin, rey de Arathor, sabía que los elfos misteriosos de las tierras del norte padecían el constante asedio de los trols, pero se negó a arriesgar la seguridad de su gente en defensa de los desconocidos. Varios meses después, llegaron rumores del norte sobre una supuesta derrota de los elfos. De no ser porque los embajadores de Quel'Thalas llegaron agotados a Strom, Thoradin no se habría percatado de la magnitud de la amenaza de los trols.", "Los elfos informaron a Thoradin acerca del tamaño de los ejércitos de los trols, asegurando que una vez que estos hubieran destruido Quel'Thalas, irían a las tierras del sur para atacarlas. Los elfos, desesperados, ante la necesidad real de ayuda militar, accedieron a enseñar a unos cuantos humanos escogidos a utilizar la magia a cambio de su ayuda para combatir a las bandas trol.", "Thoradin, receloso ante cualquier tipo de magia, aceptó ayudar a los elfos. Casi de inmediato, los hechiceros élficos llegaron a Arathor y empezaron a instruir a un grupo de humanos en las artes de la magia.", "Los elfos observaron que, si bien los humanos eran torpes por naturaleza en el uso de la magia, mostraban, por el contrario, una natural afinidad hacia todo lo mágico. Cien hombres adquirieron conocimientos básicos sobre los secretos mágicos de los elfos: solo los que eran absolutamente necesarios para combatir a los trols. Convencidos de que sus discípulos humanos estaban preparados para ayudarles en la lucha, los elfos abandonaron Strom y viajaron hacia el norte junto con los poderosos ejércitos del rey Thoradin.", "Los ejércitos unidos de los elfos y los humanos se enfrentaron a las incontenibles bandas de guerra trol al pie de las montañas de Alterac. La batalla duró varios días, pero los constantes ejércitos de Arathor no se cansaban ni cedían un ápice de terreno al ataque trol. Los señores élficos consideraron que había llegado el momento de liberar los poderes de su magia sobre el enemigo.", "Los cien magos humanos y la multitud de hechiceros élficos invocaron la furia de los cielos, prendiendo fuego a los ejércitos de los trols. Los fuegos elementales impidieron que los trols regeneraran sus heridas y quemaron sus cuerpos torturados desde las entrañas hasta la superficie.", "Cuando los ejércitos trol se desmoronaron e intentaron huir, las tropas de Thoradin les dieron caza y aniquilaron hasta el último de los soldados trol. Los trols jamás se recuperarían por completo de su derrota y la historia jamás volvería a presenciar su ascenso como nación. Seguros de que Quel'Thalas estaba a salvo de la destrucción, los elfos prometieron lealtad y amistad hacia la nación de Arathor y el linaje de su rey, Thoradin. Los humanos y los elfos establecerían una relación pacífica durante los próximos siglos." } } },
    ["Archaic Rune"] = { { ids = { "i282400" }, first = "youalreadyfeltthecallofs", pages = { "Ya has escuchado la llamada de algo más grandioso que tú: la de los elementos. Los enanos tenemos una fuerte conexión con la tierra, pero, con el debido entrenamiento, podemos aprender a hablar con todos los elementos. Los elementales pueden ser exigentes y difíciles, pero estoy aquí para enseñarte a comunicarte con ellos. Reúnete conmigo en Yunquemar y te enseñaré a escuchar y hacerte oír por los elementos.\n\n-Teo Mazatormenta, instructor de chamanes" } } },
    ["Archbishop Alonsus Faol"] = { { ids = { "o177199" }, first = "archbishopalonsusfaolben", pages = { "Arzobispo Alonsus Faol\n\nBenevolente patrón de la Iglesia de la Luz.\n\nAunque inició su excelente trabajo en Stratholme, Lordaeron, el arzobispo Faol fue un gran amigo del pueblo de Ventormenta. En los peores momentos tras la Segunda Guerra, ayudó a reformar la Hermandad de Villanorte y consiguió muchos fondos para reconstruir la propia ciudad de Ventormenta.\n\nEsta catedral no solo se alza como bastión de la Luz Sagrada, sino como testamento duradero del noble espíritu y la generosidad de un hombre." } } },
    ["Archimonde's Return and the Flight to Kalimdor"] = { { ids = { "o175758" }, first = "oncekelthuzadwaswholeaga", pages = { "Una vez que Kel'Thuzad volvió a ser un todo, Arthas condujo a la Plaga hasta el sur de Dalaran. Allí, el exánime obtendría el poderoso libro de hechizos de Medivh y lo usaría para invocar a Archimonde y traerlo de regreso al mundo. De aquí en adelante, Archimonde en persona comenzaría a realizar la invasión final de la Legión. Incluso los zahoríes del Kirin Tor se mostraban incapaces de detener a las fuerzas de Arthas, impidiéndoles que robaran el libro de Medivh y pronto, Kel'Thuzad reunió todos los elementos para realizar su encantamiento.", "Transcurridos diez mil años, el poderoso demonio Archimonde y su anfitrión emergieron una vez más en el mundo de Azeroth. Aun así, Dalaran no iba a ser su destino final. Bajo las órdenes del propio Kil'jaeden, Archimonde y sus demonios siguieron a la Plaga de los no-muertos hasta Kalimdor, con el propósito de destruir Nordrassil, el Árbol del Mundo.", "En medio de este caos, un solitario y misterioso profeta apareció para guiar a las razas mortales. Este profeta resultó ser Medivh, el último guardián, que había regresado milagrosamente del Más Allá para redimirse de sus pasados pecados. Medivh alertó a la Horda y a la Alianza acerca de los peligros a los que se enfrentaban y los conminó a que unieran sus fuerzas.", "Ahítos de generaciones de odio, los orcos y los humanos no tenían nada en común. Medivh se vio obligado a tratar con cada raza por separado, utilizando las profecías y su habilidad para guiarlos a través del mar, hacia la legendaria tierra de Kalimdor. Pronto, los orcos y los humanos encontraron la civilización de los kaldorei, oculta durante mucho tiempo.", "Los orcos, dirigidos por Thrall, sufrieron una serie de reveses hacia los baldíos de Kalimdor. Aunque contaban con la amistad de Cairne Pezuña de Sangre y sus poderosos guerreros tauren, muchos orcos empezaron a sucumbir a la demoníaca sed de sangre que los había contaminado durante años. El lugarteniente más importante de Thrall, Grom Grito Infernal, llegó incluso a traicionar a la Horda, abandonándose a sus más bajos instintos.", "Mientras Grito Infernal y sus leales guerreros Grito de Guerra merodeaban por los bosques de Vallefresno, se enfrentaron a los antiguos centinelas y elfos de la noche. Persuadidos de que los orcos habían vuelto por sus fueros, retomando sus viejas costumbres, el semidiós Cenario apareció para lograr que Grito Infernal y sus orcos regresaran. No obstante, Grito Infernal y sus orcos, vencidos por una rabia y un odio sobrenaturales, asesinaron a Cenario y corrompieron los antiguos bosques.", "Finalmente, Grito Infernal consiguió redimir su honor, ayudando a Thrall a derrotar a Mannoroth, el señor demonio que lanzó por vez primera sobre la línea de sangre de los orcos una maldición de odio y rabia. Con la muerte de Mannoroth, la maldición de sangre de los orcos llegó a su fin.", "Mientras Medivh intentaba convencer a los orcos y a los humanos de la necesidad de una alianza, los elfos de la noche luchaban contra la Legión, utilizando sus propias tácticas secretas. Tyrande Susurravientos, la inmortal suma sacerdotisa de los centinelas y elfos de la noche, combatió desesperadamente para evitar que los demonios y los gnomos arrasaran los bosques de Vallefresno. Tyrande se dio cuenta de que necesitaba ayuda y se dispuso a despertar a los druidas de los elfos de la noche de su profundo sueño de mil años.", "Invocando a su antiguo amor, Malfurión Tempestira, Tyrande logró galvanizar sus defensas y hizo volver a la Legión. Con la ayuda de Malfurión, la propia naturaleza logró derrotar a la Legión y a sus aliados de la Plaga.", "Mientras buscaba más druidas en hibernación, Malfurión encontró la antigua prisión-túmulo en la que había encadenado a su hermano Illidan. Convencido de que Illidan los ayudaría contra la Legión, Tyrande lo liberó. Aunque Illidan los ayudó durante un tiempo, finalmente huyó para perseguir sus propias metas.", "Los elfos de la noche se prepararon y lucharon contra la Legión Ardiente con gran determinación. La Legión nunca había abandonado su deseo de conquistar el Pozo de la Eternidad, durante mucho tiempo fuente de poder del Árbol del Mundo y corazón del reino de los elfos de la noche. Si el asalto que planeaban contra el Árbol tenía éxito, los demonios acabarían literalmente con el mundo." } } },
    ["Archmage Khadgar of the Kirin Tor"] = { { ids = { "o25333" }, first = "archmagekhadgarofthekiri", pages = { "Archimago Khadgar del Kirin Tor\n\nAntiguo aprendiz de Medivh. Comandante en Jefe de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido.\n\n\"Nadie exploró tan altruistamente las oscuras entrañas de la magia y la guerra. Te deseamos lo mejor, audaz aventurero... estés donde estés.\"\n\n- Antónidas - Archimago de Dalaran" } } },
    ["Arellas Fireleaf"] = { { ids = { "o175771" }, first = "arellasfireleafhighwizar", pages = { "Arellas Hojafuego\nAlto zahorí de la Cruzada Escarlata\nCiudadano de Quel'Thalas\nAtrapado en combate eterno con el necromante Diesalven" } } },
    ["Baelog's Journal"] = { { ids = { "o123463" }, first = "ihavefoundamethodtoenter", pages = { "¡He encontrado un método para entrar en la cámara de Khaz'mul!\n\nCoge el medallón de Gni'kiv que hay en mi cofre.\n\nDerrota al trogg Revelosh en la cámara, delante del cuarto de mapas, y recupera el bastón de Tsol.\n\nUne el medallón y el bastón para formar el Bastón de Prehistoria.\n\nUsa el bastón en el cuarto de mapas para abrir la puerta que conduce a la cámara de Khaz'mul.\n\n¡Haz todo esto y la cámara será tuya!\nBaelog" } } },
    ["Bath'rah's Parchment"] = { { ids = { "i6929" }, first = "belowyouwillfindthatwhic", pages = { "A continuación, encontrarás los ingredientes necesarios para el hechizo de invocación del gran Cicloniano. ¡Que la fortuna te acompañe!\n\nBath'rah el Cazavientos", "Vidarraíz:\n\nSe encuentra en estado salvaje o puede obtenerse de las lodobestias parramustias del marjal Revolcafango. Su poder será necesario para extraer la esencia vital de Cicloniano.", "Colmillos de Sangrapellejo:\n\nLos colmillos de los trols Sangrapellejo de la Vega de Tuercespina tienen una extraña cualidad. La perversidad de los Sangrapellejo se concentra en sus colmillos que, cuando se muelen hasta obtener un fino polvo, sus poderes se desencadenan.", "Esencia del exilio:\n\nEsta esencia se obtiene mediante la fusión de tres talismanes de los exilios elementales de las Tierras Altas de Arathi. Reúne talismanes tronadores, ardientes y coronadores de los elementales y luego vierte ocho de cada uno en mi caldera.\n\nA partir de los talismanes se formará la esencia del exilio." } } },
    ["Beginnings of the Undead Threat"] = { { ids = { "i5861" }, first = "theundeadsbeginningsupon", pages = { "La llegada de los no-muertos a Azeroth no se produjo inicialmente con la corrupción del príncipe Arthas, sino mucho antes de aquel acontecimiento. Los hechos que provocaron la caída de Lordaeron se desencadenaron mucho antes de ese momento: con la llegada de los clanes orcos y la Legión Ardiente.", "Los orcos de Draenor (el mundo del que procedían originalmente) eran nobles y chamánicos. Eran poderosos guerreros, corpulentos y de férrea voluntad. Esta era la razón por la que la Legión Ardiente los buscaba. Kil'jaeden, un demonio de gran poder en la Legión, deseaba someter a los clanes orcos y usarlos como escudo contra los mundos que la Legión Ardiente pretendía conquistar.", "Kil'jaeden se dirigió al líder de los clanes, un poderoso chamán llamado Ner'zhul. Prometió transmitirle a Ner'zhul infinitos poderes místicos y conocimientos ocultos si hacía un pacto con el demonio capaz de someter a los clanes de la Legión Ardiente. Este pacto no solo selló para siempre su destino, sino el de todo su mundo.", "El tiempo transcurrió y Ner'zhul se dio cuenta de que el destino de los clanes estaba en manos de la Legión Ardiente, por lo que el chamán orco empezó a desafiar a Kil'jaeden. El demonio, disgustado con Ner'zhul, se dirigió a Gul'dan, el propio aprendiz del chamán, mucho más propenso a la corrupción que Ner'zhul.", "De hecho, fue Gul'dan el responsable del declive del chamanismo entre los clanes. Las promesas de poder y control sobre el enemigo hicieron sus ofertas aún más tentadoras. Con la ayuda de Kil'jaeden, Gul'dan empezó a manipular a los clanes. Los orcos, otrora nobles, se convirtieron en bestias salvajes y corruptas. Con sangre demoníaca inoculada en sus cuerpos, los orcos fueron mucho más despiadados y bárbaros.", "Aunque Kil'jaeden había corrompido a Gul'dan tras fracasar con Ner'zhul, odiaba al chamán, por lo que juró respetar su pacto original. Kil'jaeden capturó a Ner'zhul y sometió al chamán a una tortura física increíblemente lenta. Mientras Ner'zhul suplicaba que lo matasen, Kil'jaeden le recordó que su pacto original seguía vigente. Kil'jaeden mató al orco, pero solo físicamente. Kil'jaeden capturó el espíritu del chamán orco antes de que partiera al Vacío Abisal.", "Encerró el espíritu de Ner'zhul en un bloque de hielo procedente del Vacío Abisal. Atrapado en el hielo, infundió aún más poder al témpano. La pérdida de su cuerpo físico y la absorción de aquel increíble poder marcaron el inicio de la transformación de Ner'zhul.", "Kil'jaeden arrojó el bloque de hielo a través de múltiples dimensiones hasta Azeroth, aterrizando en el continente de Rasganorte e implantando su inmensa maldad en nuestro mundo. Ner'zhul se había ido para siempre, dejando tras de sí un trono de hielo y odio. El antaño respetado líder de los chamanes se había convertido en el increíblemente poderoso rey Exánime.", "Puesto que Kil'jaeden no confiaba en el rey Exánime, envió a sus aterradores guerreros a vigilar su espíritu, para así asegurarse de que el rey siguiera sus órdenes. Los vampíricos esbirros vinieron a Azeroth de buen grado, atraídos por la destrucción y el poder del rey Exánime, ante la posibilidad borrar toda una raza de la faz del planeta.", "Transcurrió más de una década. Durante ese tiempo, el rey Exánime usó sus vastos poderes para controlar las mentes de las criaturas de Rasganorte, a quienes ordenó construir una gran ciudad sobre su trono congelado. Una vez que Rasganorte fue conquistado, el rey Exánime sabía que tenía que empezar a infiltrarse en Lordaeron. Atrapado en el hielo, el antiguo chamán orco halló nuevas mentes para manipularlas y controlarlas. Su llamada atravesó continentes enteros.", "Las invocaciones del rey Exánime no pasaron desapercibidas, especialmente para un puñado de poderosos individuos. Entre ellos estaba el archimago Kel'Thuzad, miembro de la junta de gobierno de Dalaran, el Kirin Tor. Su interés por las fuerzas ocultas infringía la política del Kirin Tor, que se oponía al aprendizaje de la magia negra. Kel'Thuzad abandonó el Kirin Tor y todos sus vínculos con el pensamiento convencional y juró aprender todos los secretos del rey Exánime.", "Ambos sellaron un pacto. A cambio de servir al rey Exánime, Kel'Thuzad obtendría la inmortalidad e inmensos poderes. La primera tarea que Kel'Thuzad habría de realizar consistía en usar su inmensa riqueza e influencia en Lordaeron para fundar el Culto de los Malditos. El Culto prometía igualdad y vida eterna a todos sus miembros, siempre y cuando juraran obediencia a Ner'zhul, el dios del Culto de los Malditos.", "Ner'zhul creó, a continuación, artefactos diseñados para diseminar la peste entre las civilizaciones humanas de Lordaeron. Entregó los artefactos a Kel'Thuzad y ordenó al zahorí que los extendiera por todo el territorio. Los seguidores de su culto debían proteger estos artefactos a toda costa.", "Una vez extendida, la peste empezará a filtrarse en la tierra, afectando a sus ignorantes moradores. Kel'Thuzad pudo advertir cómo el ejército del rey Exánime crecía rápidamente, haciéndose con el control de grandes extensiones de tierra. Este ejército se conoció como la Plaga, pues su único propósito era el exterminio de la humanidad de la tierra de Azeroth." } } },
    ["Bel'dugur's Note"] = { { ids = { "i4650" }, first = "thestarofxilyehanogreina", pages = { "La Estrella de Xil'yeh\n\nUn ogro de Alterac, Grel'borg el Avaro, fue el último poseedor de esta gema. Se dice que transmite a su dueño la facultad de entrar en contacto con otros mundos. Hay fuentes que afirman que Grel'borg merodea en las Ruinas de Alterac en las montañas del mismo nombre, rebuscando más reliquias entre los escombros y las basuras.", "La Mano de Dagun\n\nDagun es una criatura de aguas profundas, adorada por los múrlocs en Marjal Revolcafango. La atraen a la superficie con un alga marina especial, encantada por sus chamanes. Atrapa a los múrlocs, recoge sus algas encantadas y luego colócalas sobre el altar de los múrlocs. Dagun aparecerá y le estarás esperando.\n\nQuiero esa mano.", "El Corazón Heredado\n\nLos viejos textos afirman que quien posea el Corazón Heredado no debe tener temor a la tumba. Tal vez esto sea cierto, ya que el dueño del corazón, el trol Mogh, es conocido como Mogh el Eterno. Mogh, médico brujo de la tribu Machacacráneos, habita en Tuercespina en las Ruinas de Zul'Mamwe.", "Tráeme estos objetos: la Estrella, la Mano y el Corazón, y tendrás una copia del Compendio de Yagyin.\n\nEl guardián" } } },
    ["Belamoore's Research Journal"] = { { ids = { "i3711" }, first = "kegandarkmarleaderofthes", pages = { "Kegan Darkmar, líder de una pequeña banda de no-muertos que vino a vernos en busca de asilo para escapar de sus \"hermanos\", desafía nuestras actitudes habituales en relación a los de su especie. Puede que su piel se esté pudriendo o que la sangre haga tiempo que no fluya por sus venas, pero actúa con nobleza, mostrando más preocupación por la seguridad de sus compatriotas que por la suya propia.\nDe hecho, percibo en él una humanidad que, siendo franco, a veces echo de menos en algunos humanos que conozco.", "Pero, ¿por qué digo todo esto? Lo afirmo para dar credibilidad a lo que voy a escribir, ya que estas fueron palabras de Kegan y es mi deseo que, después de leer este diario, mis compañeros entiendan por qué creo en ellas:\n\n\"Vestigios de dioses antiguos yacen en las huecas profundidades del mundo. Ahora, nuevas fuerzas intentan utilizar aquel antiguo poder, por lo que aquellos que lo consigan, tendrán en sus manos un arma terrible para combatir a sus enemigos.\"", "Tales fueron las palabras pronunciadas por Kegan cuando extendió su colgante de sangrita hacia mí, y había temor, y tal vez reverencia, en sus ojos al hacerlo. Cuando sus manos se unieron a las mías, permanecieron inmóviles, como si se negara a entregar el colgante. Sentí cierta repugnancia, pero no recuerdo si mi rechazo se debió a la carne muerta apretando mi mano o si fue el colgante el que me hizo estremecer.\n\nPero puedo asegurar que noté una fuerza en su interior. Una fuerza profunda, oculta, sedienta. Anhelando ser liberada.", "Aunque mis compañeros en Dalaran tomaron precauciones al estudiar las sangritas que Kegan y sus seguidores llevaban encima, en lugar de poner a los cuatro refugiados en cuarentena y dejar las sangritas con ellos, la sinceridad de Kegan me obligó a estudiar su colgante.", "Deseaba comunicar a mis compañeros que este tipo de piedra tenía propiedades mágicas, y si nosotros, los zahoríes de Dalaran, no teníamos la intención de aprovechar los poderes de las sangritas, al menos debíamos conocer sus propiedades, porque estaba claro que nuestros enemigos las utilizarían contra nosotros tarde o temprano.\n\nY así fue como inicié mi investigación.", "Realicé algunas pruebas, suponiendo que la sangrita era un tipo de roca, como el cuarzo o la obsidiana. Por ello llevé a cabo una serie de procedimientos para determinar lo siguiente: qué minerales contenía la sangrita, qué fuerzas actuaban para producir su color y dureza, así como otras propiedades comunes a las rocas y a los minerales. Pero para mi decepción, el colgante de sangrita no reaccionó a mis pruebas como lo haría un mineral corriente.", "De hecho, ¡solía reaccionar de la forma contraria a la esperada! Era como si el colgante estuviera boicoteando mis experimentos deliberadamente.\n\nComo si tuviera vida y mente propias.\n\nEnfadada, pero sin desanimarme, descarté la idea de que el colgante fuera un trozo de roca inerte, cobrando mayor fuerza la teoría de que se trataba de un ser vivo.\n\nPero me equivoqué de nuevo.", "Ninguna de mis pruebas reveló información alguna sobre el origen de la sangrita. Aquella vez, lo único que saqué en claro era que la sangrita no estaba ni viva... ni muerta.\n\nPero fue en ese momento, a punto de fracasar, cuando se produjo el mayor avance. En mi última prueba, utilicé un vaso de precipitados cuyo borde estaba roto, quedando un pequeño orificio irregular en la parte superior. Al acabar la prueba, sin resultado alguno, fui a limpiar la mesa de trabajo y me corté con el vaso.", "El corte no era profundo, sin embargo, brotó mucha sangre de la herida. Antes de ponerme un vendaje, buena parte de mi sangre cayó sobre la mesa de trabajo.\n\nY cuando volví a limpiarla, advertí algo muy extraño...", "La sangre que había derramado cerca del colgante de sangrita se desplazaba lentamente hacia la gema, como si esta tuviera una extraña fuerza de atracción. La sangre que había entrado en contacto con el colgante aparentemente desapareció y el tono púrpura de la piedra aumentaba a medida que bebía de mi sangre.", "Después de presenciar este fenómeno, la cabeza empezó a darme vueltas, quizás por mi herida reciente (aunque realmente no creí que fuera la causa, puesto que no había perdido tanta sangre) o quizás por mi descubrimiento, tras innumerables intentos, de una de las propiedades de la sangrita. Tanteando a mis espaldas, arrastré mi taburete, me senté y cavilé durante un rato. Numerosas preguntas rondaban mi cabeza, mareándome y amenazando con hacerme perder el equilibrio.\n\n¿Acaso la sangrita bebe sangre? ¿Está sedienta de sangre? ¿Atrae la sangre?", "¿O acaso está hecha la sangrita de sangre? Y si es así, ¿de quién es la sangre? ¿La mía? ¿O la de cualquier humano? ¿La de algún animal?\n\nO quizás esta gema sea la sangre de algo desconocido, algo que Kegan temía y veneraba al mismo tiempo cuando me dio su colgante.\n\nEsta es la pregunta que necesita respuesta. Es la clave.", "La llama de la curiosidad se reavivó en mi interior y volví a mis experimentos. Esta vez no hice conjeturas, realizando las pruebas de forma metódica. Esto requirió mucho más trabajo, pero había mayores probabilidades de hacer descubrimientos.\n\nY aunque mi laboratorio es pequeño y no dispongo de ayudantes, descubrí otra cualidad más inquietante en la sangrita...", "Además de sangre, hay fuerzas elementales fundidas en la piedra. Fuego, agua, truenos y piedra se mezclan con la sangre (sí, pero ¿la sangre de quién?) y, si bien esta mezcla es inerte en el exterior, todas estas fuerzas parecen chocar entre sí en el interior. Este sorprendente y premonitorio material planteaba nuevas preguntas.", "Pero para responder a estas preguntas, era necesario realizar más estudios y experimentos en el colgante y mucho me temo que el Campo de Reclusión de Lordamere no puede conseguir ni la mano de obra ni el equipo para llevar a cabo esta tarea. Así que envié el colgante de sangrita con un mensajero a Dalaran con instrucciones específicas sobre el tipo de pruebas que era necesario realizar para evitarles mis iniciales decepciones.", "Mientras esperaba los resultados de estas pruebas, me dediqué a hablar con Kegan. Aunque le presioné constantemente para que me revelara lo que sabía sobre las sangritas, nunca me contó nada distinto de lo que me dijo el día que me entregó el colgante. Y no solía hablar sobre la época que pasó con el grupo de \"Renegados\", nombre con el que se refería a su clan de no-muertos.", "Pero Kegan estaba ansioso de hablar de otras cosas, particularmente de su infancia en Lordaeron, antes de su caída.\n\nSigue amando aquel reino perdido, aunque ahora esté arruinado y muerto.\n\nMi creciente afecto por Kegan me llenó de paciencia, mientras esperaba los resultados de mis pruebas.", "Pero transcurridas varias semanas sin tener noticias, mi paciencia se agotó, así que, tras realizar varias averiguaciones sobre Dalaran, supe que la sangrita nunca había llegado a su destino. Mi emisario se había perdido en el camino y el colgante de sangrita ¡se había perdido con él!\n\nEran graves noticias, porque, aunque Kegan y sus seguidores aún tienen ejemplares de sangrita con los que hacer experimentos, temo que el colgante haya caído en las manos equivocadas.", "He enviado a otro mensajero a Dalaran y he oído que, hasta el momento, siguen buscando el colgante en las ruinas que están fuera de nuestra esfera de protección.\n\nSolo espero que no sea demasiado tarde." } } },
    ["Benedict's Orders"] = { { ids = { "i270151" }, first = "corporaladamoreatfirstli", pages = { "Cabo Adamore:\n\nAl amanecer reunirás una fuerza de no más de diez infantes de marina y te presentarás ante un cazarrecompensas llamado Terry Tragolargo. Lo acompañaréis en la persecución de un desertor peligroso al que debéis suponer armado y hostil.\n\nEste cazarrecompensas fue un aliado de confianza del almirante antes de su muerte. Espero que mostréis a Tragolargo la misma deferencia que a cualquier oficial superior.\n\n--Teniente Benedict" } } },
    ["Berard's Journal"] = { { ids = { "i3255" }, first = "throughstudyofvariousfos", pages = { "Mediante el estudio de diversas criaturas fosilizadas he deducido que, en la antigüedad, una gran peste recorrió las aguas del Lago Lordamere. ¿Cuál fue la causa? Quizá nunca lo sepamos. Pero la tasa de contaminación parece haber sido extremadamente alta, a juzgar por las densas concentraciones de restos distribuidos por el lecho del lago.", "En un intento de descubrir el pasado, he empezado a examinar las criaturas del presente con la esperanza de encontrar la pista que falta para resolver este misterio. Los Vigilantes del Lago y los Trepadores del Lago son bestias antiguas que habitan las islas del centro del Lago Lordamere. Sobre ellas crece un musgo parecido a los materiales que quedan en algunos fósiles. Hará falta investigar más antes de aventurar qué significa esta conexión.", "Mientras intentaba recoger muestras de musgo, encontré el escenario de una batalla sangrienta. Una banda de gnolls había atacado a la tribu múrloc Anca Vil. Los cadáveres de ambos cubrían el campo de batalla. Al pasar junto al cuerpo destrozado de un múrloc, advertí un extraño tumor endurecido que sobresalía de la herida. Al estudiarlo quedó claro que poseía propiedades parecidas al musgo que recogía. Por desgracia, no encontré ningún otro tumor." } } },
    ["Beyond the Dark Portal"] = { { ids = { "o21582" }, first = "onlyafewmonthsafternethe", pages = { "Unos pocos meses tras el final de la batalla de Nethergarde, las fuerzas del Portal Oscuro se unieron y abrieron una nueva entrada a Draenor. Los clanes orcos restantes, bajo el mando del anciano chamán Ner'zhul, volvieron a atacar Azeroth. En el intento de robar ciertos artefactos mágicos que aumentarían el poder de Ner'zhul, los orcos planearon abrir nuevos portales en Draenor que les permitieran escapar a su mundo maldito para siempre.", "Convencidos de que Ner'zhul estaban planeando una nueva ofensiva contra la Alianza, el rey Terenas de Lordaeron envió sus tropas a Draenor para acabar con la amenaza orca de una vez por todas. Bajo las órdenes de Khadgar y el general Turalyon, las fuerzas de la Alianza pelearon contra los orcos en las tierras ardientes. Aun con la ayuda de la élfica capitana especialista Alleria, el enano Kurdran y el soldado veterano Danath, Khadgar no pudo evitar que Ner'zhul abriera sus portales a otros mundos.", "Las terribles tormentas mágicas causadas por las energías convergentes de los portales empezaron a destruir el mundo, ya devastado. Ner'zhul, seguido de sus más fieles siervos, logró escapar a través de uno de los portales, mientras Khadgar luchaba desesperadamente para devolver a sus compañeros a Azeroth. Ante la certeza de que estaban atrapados en el mundo agonizante, Khadgar y sus compañeros decidieron destruir el Portal Oscuro para evitar que Azeroth fuera destruido por el violento ataque de Draenor.", "Según cuentan todos, los héroes lograron destruir el portal y salvar a Azeroth, pero tanto si escaparon como si no, el terrible final de Draenor resulta evidente." } } },
    ["Blackrat's Note"] = { { ids = { "i208205" }, first = "ivegotthegoodsillbehidin", pages = { "Tengo la mercancía. Me esconderé cerca del Refugio Brumapino, junto a la barca vieja. Si envías a uno de los tuyos a recogerla, ¡asegúrate de que no lo vean!\n\n- Ratanegra" } } },
    ["Blood-Stained Letter"] = { { ids = { "i251522" }, first = "mydearesttabithahowstran", pages = { "Mi queridísima Tabitha:\n\nQué extraño es prever mi propia muerte. Escribo esta nota porque no sé a qué hora me reclamará el destino. Aunque sé que es un pobre sustituto de unas palabras adecuadas, mi pluma no logra expresar el dolor que me produce separarme de ti.\n\nCada día despierto ante la pena de la que no supe protegerte. Lamento no haber podido proteger a nuestro querido hijo y lamento que mi dolor haya caído en una trampa de la que no puede escapar.\n\nEres mi amor y mi confidente, y mi vida ha valido más de lo que habría valido sola. Cada semana, cuando me adentro en las ruinas de nuestro hogar antaño orgulloso, temo que sea la última, y cada vez agradezco tenerte esperándome al volver.\n\nRezo para que nos reunamos, aunque solo sea un instante." } } },
    ["Bloodsail Orders"] = { { ids = { "i3921" }, first = "bloodsailorderspayattent", pages = { "Pedidos de los Vela de Sangre\n\nPoned atención a estas palabras, mis valientes, ya que solo podremos echar un trago en la Bahía del Botín.\n\nHe enviado al viejo Dunken para que explore el norte y le he dicho que espere a la señal.\n\nLa Damisela Afortunada fondeará en el cabo del sur por motivos de reabastecimiento. El retaco del Capitán Aguaserena va a preparar a su tripulación para reunir todo el botín robado. Estoy seguro de que el burro de Brutus estará al frente de todo.", "Quiero que el capitán Volcayecto lleve el Mareas Vivas a la costa desde el sudeste. Enviaremos a su tripulación a pie cuando se dé la señal.\n\nEl bruto de Fausal puede convencer a los hombres fácilmente. Quiero que marquéis a Revilgaz y a Cuernomarino. Por mí que se pudran en el fondo del mar.\n\nOs hago responsables de que rescatéis todo lo que podamos usar en nuestro pequeño proyecto con VanCleef en las Minas de la Muerte.", "Daré la orden a Parchierro para que abra fuego. La descarga de artillería evitará que los barcos de los Aguasnegras entren o salgan del puerto.\n\nDespués de que el Velo Carmesí haya descargado sus cañones, lo llevaré junto al Mareas Vivas para que sirva de apoyo y proporcione suministros.\n\nUna vez que Fausal y sus hombres hayan bombardeado la ciudad y todos estén en cubierta, zarparemos y cañonearemos la bahía una vez más desde la Costa Salvaje para asegurarnos.\n\nMaestro de flota Firallon" } } },
    ["Bloodstained Journal"] = { { ids = { "i7668" }, first = "onlyportionsofthejournal", pages = { "(Solo resultan visibles algunos fragmentos del diario a causa de las manchas).\n\nUldaman, Tercer día\n\nNo puedo creer lo idiota que he sido. Dejar que los enanos Forjatiniebla me atacaran por sorpresa solo le ocurre a los novatos. Mis heridas se curan lentamente y estoy infectado por su veneno. Noto cómo la energía me abandona. No obstante, tengo que seguir explorando...\n\n... para empeorar las cosas, ¡el collar que $gel:la; gnomo hizo para mí se ha hecho añicos! Tres de las gemas más grandes engarzadas en él se han perdido. Debo encontrarlas, ya que, sin ellas, el collar carece de todo poder...", "Uldaman, cuarto día\n\nPude encontrar la primera en las profundidades de Uldaman, ya que uno de los troggs más salvajes que he visto estaba blandiendo un gran zafiro que habría encajado perfectamente en el collar. Escuché a los enanos Forjatiniebla mencionar el nombre de las bestias: Grimlok. Vaya panda de guardianes que tiene el tosco de Grimlok, no obstante...", "Uldaman, quinto día\n\n... el trogg, cuando arrancó el topacio a sus \"hermanos\" asesinados, se dirigió a la caverna lateral que hay cerca de la entrada de la sala...\n\n... rápidamente para colocar el topacio en una urna grande y llamativa que había en la parte trasera de la cámara...\n\n... ¡sobre todo, enanos! Además, había tres de ellos. Actualmente los utilizan como escudos vivientes contra los troggs. Llamarlos habría sido un suicido, ya que esto habría atraído a los apestosos troggs... y yo en este estado calamitoso... Sin embargo, en cuanto dé con la tercera gema, voy a...", "Uldaman, Sexto día\n\n... ¡qué hambre! Me he quedado sin provisiones, hasta tal punto que un pan mohoso sería ahora un festín. De hecho, vi cómo la cabeza de un trogg se convertía en un jugoso filete delante de mí...", "Uldaman, Séptimo día\n\n... es mi última oportunidad para reparar mis errores. Creo que el rubí está cerca de las últimas barricadas que los enanos construyeron contra los troggs. Las batallas que libran, sin duda por el control de las gemas y otros artefactos de este sitio, son continuas. Lo más probable es que esos viles enanos lo hayan escondido por esa zona. De todas maneras, tengo que hacer algo al respecto. Tal vez sea mejor salir a la superficie repentinamente..." } } },
    ["Bloody Map"] = { { ids = { "i271745" }, first = "mogodunzkostahinetagolgg", pages = { "<Una representación rudimentaria del paisaje, con un punto de interés claramente señalado.>\n\nMogodun- z kost a-hine\nta golg\ngar thon- kha z'ta gor weard-hald\n\n<El mapa está demasiado deteriorado para distinguir cualquier otra inscripción.>" } } },
    ["Bloody Missive"] = { { ids = { "i219929" }, first = "ourspiestellusthatsiandt", pages = { "Nuestros espías nos dicen que el IS:8 y la Mano de Plata han mordido el anzuelo y que tu objetivo debería estar de camino. Averigua lo que saben y después encárgate de eliminarlos sin hacer ruido, preferiblemente fuera de la ciudad. Debemos ver muertos a estos entrometidos y recuperar lo que nos pertenece por cualquier medio necesario. No falles." } } },
    ["Bloody Note"] = { { ids = { "i254871" }, first = "theculthitusbysurprisera", pages = { "El culto nos tomó por sorpresa. Raani no lo vio venir y Arvensus recibió una espada en el vientre. Yo me llevé un rayo en el pecho y perdí el conocimiento. Ni se molestaron en rematarme... Supongo que creyeron que las heridas acabarían conmigo. Cuando todo termine, sospecho que quizá tengan razón.", "En cuanto cesaron los combates, empezaron a subir unas cajas enormes de piedras de viento a lo alto de la torre. El líder, una especie de sacerdote, mencionó algo acerca de un ritual.\n\nEscribo esta nota para avisar a Aonda en caso de que no consiga volver a Shen'dar, pero aquí están tramando algo. Algo malo.", "Si alguien encuentra esto, por favor, haz cuanto puedas para detenerlos. Solo quedaban unos pocos en la torre cuando garabateé esta nota y me alejé arrastrándome.\n\nIntenta también recuperar del cuerpo de Raani su pluma de la suerte. Le gustaba contar historias exageradas sobre cómo se la arrancó a una especie de ave de fuego. Creo que querría asegurarse de que volviera a casa.\n\nSi también puedes recuperar del cuerpo de Arvensus Cantosombrío el sello de su familia, hazlo. El sumo anciano Cantosombrío es su tío y querrá que vuelva a la familia." } } },
    ["Bloody Parchment"] = { { ids = { "i273658", "i273659" }, first = "itisencouragingtoheartha", pages = { "Es alentador saber que la nueva magia que nos dio nuestro señor ha superado las expectativas. Si el veneno es tan eficaz como afirmas, será una herramienta poderosa para el conflicto que se acerca. Te dije que había mucho que aprender de los no-muertos que llenan nuestra montaña. No te preocupes, no te reprocharé tu escepticismo inicial.\n\nTermina tus asuntos allí y vuelve a la cumbre con tus muestras. No hace falta matar a las bestias. Si se extienden a las zonas vecinas, solo sembrarán caos, confusión y miedo. Al final, eso favorecerá los objetivos del Pacto.\n\nBuen trabajo. Sin duda, el Rey Salvaje estará complacido con lo que has conseguido." } } },
    ["Blue Punch Card"] = { { ids = { "i9282" }, first = "donotletthisinformationf", pages = { "¡NO dejes que esta información caiga en manos enemigas!\n\" } } },
    ["Bolvar's Decree"] = { { ids = { "i11368" }, first = "solomonthecarrierofthisd", pages = { "Salomón,\n\n$gAl portador:A la portadora; de este decreto ha sido oficialmente nombrado ayudante del alguacil de Ventormenta. Puedes $gusarlo:usarla; para encontrar pruebas de la relación entre el Vuelo Negro y los orcos Roca Negra. En el caso de hallar dichas pruebas, el ayudante del alguacil puede traérmelas a Ventormenta, momento en el que daré la orden de desplegar suficientes fuerzas militares para ayudar a Villa del Lago.\n\nUn cordial saludo,\n\nAlto Señor Bolvar Fordragon" } } },
    ["Bonegrip's Note"] = { { ids = { "i4649" }, first = "thestarofxilyehgrelborgt", pages = { "La Estrella de Xil'yeh\n\nGrel'borg el Avaro tiene la Estrella. Es un ogro avaricioso que pasa sus días en las montañas Alterac, en las Ruinas de Alterac, buscando adornos. La mayor parte de su colección es inútil, pero un objeto, la Estrella de Xil'yeh, tiene valiosas propiedades.", "La Mano de Dagun\n\nLos textos antiguos afirman que las zarpas de Dagun excretan un veneno que no mata a sus presas, pero las hace mutar en algo distinto: un miembro de las razas antiguas. Su valor para nosotros está fuera de cuestión.\n\nDagun vive en las profundidades del mar, pero es atraído regularmente por una tribu de murlocs Ancalodos en el Marjal Revolcafango. Sus oráculos lo invocaron con una alga marina encantada. Si matas suficientes oráculos, podrás encontrar el alga. Luego, colócala en el altar múrloc y Dagun aparecerá.", "El Corazón Heredado\n\nMogh el Eterno es un médico brujo trol de Tuercespina. Posee el Corazón Heredado, del que se afirma que aquellos que desvelen sus secretos pueden sortear a la muerte. Encontrarás a Mogh en las Ruinas de Zul'Mamwe. Derrótalo, si puedes, y tráeme el Corazón Heredado.", "Tráeme estos tres objetos: la Estrella, la Mano y el Corazón, y el Compendio de Yagyin será tuyo.\n\nG.B." } } },
    ["Book from Sven's Farm"] = { { ids = { "i2161" }, first = "theterrorofthesepastfeww", pages = { "El terror de estas últimas semanas ha supuesto más de lo que puedo soportar, sin embargo, siento que escribir lo que he vivido me reconforta en cierta medida. Por eso lo hago y es el único consuelo que tengo en estos días aciagos.", "Todo empezó con el hallazgo de esa maldita guadaña en la Condena de Roland. Antes de que apareciera la guadaña, los terrores de este lugar parecían tan mansos como el valle de Villanorte.\n\nPero desde que encontré el mango de la guadaña sobresaliendo entre la pila de escombros en la mina y lo saqué de ahí, ¡ay de mí!, ¡la Condena de Roland se ha convertido en un lugar de destrucción y muerte!", "Después de liberar la Guadaña, emergieron desde todos los rincones, clavando sus zarpas en nuestros tobillos desde ocultos agujeros, o cayendo sobre nosotros desde lo alto. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, entre los que me incluyo, intentaron escapar. A medida que corría, veía a mis hermanos atrapados por la zarpa y el colmillo, oí tantos alaridos truncados o desvaneciéndose en el silencio.", "Solo puedo suponer por qué sobreviví aquella noche. Siempre he sido cuidadoso, rápido a la hora de escapar de las fauces de alguna bestia, o cuando se trataba de saltar algún escollo. Mi sobrenombre tiene que ver con esta característica. Así que tal vez fue el don de la prudencia el que me salvó...\n\nO tal vez fue la guadaña que extraje de los escombros. No puede ser la guadaña, puesto que la perdí durante mi frenética huida. Pero si fui yo quien atrajo a los ferocanis al Bosque del Ocaso, quizás me hayan hecho un extraño obsequio. ¡Los maldigo!", "Tras sobrevivir a la huida de la Condena de Roland, me oculté en el granero de un hombre llamado Sven. Pasé unos cuantos días en el granero y aquel horror caló tan hondo en mí que nunca me presenté ante Sven o su familia. Pero considerando lo que vi desde mi escondite, me di cuenta de que aquellos granjeros eran personas bastante decentes. De haber salido de mi refugio, seguramente me habrían aceptado, pero me cuesta confiar en los demás. Y mucho más después de aquella impresión en la mina.\n\nAsí que permanecí escondido.", "<El resto del libro está en blanco>" } } },
    ["Brazier of Invocation: User's Manual"] = { { ids = { "i22344" }, first = "brazierofinvocationusers", pages = { "BRASERO DE INVOCACIÓN: MANUAL DEL USUARIO\n\nDónde encontrar lugares embrujados\n\nINTRODUCCIÓN\n\nEstas páginas contienen las ubicaciones de los espíritus y almas caídos y corruptos implicados en el incidente del amuleto de lord Valthalak. Aunque ya has salvado a esos antiguos compañeros míos, conjeturo que en esos lugares aún permanecen ecos repugnantes del mal que retorció sus espíritus. Tal era el poder malévolo del espíritu de lord Valthalak.\n\nAdemás, el brasero puede usarse para invocar a lord Valthalak, aunque, como antes, debe hacerse con extrema cautela.", "INTRODUCCIÓN, continuación...\n\nEl brasero funciona igual que el Brasero de Señalización. Basta con colocarlo al alcance de cualquiera de los cinco lugares embrujados para invocar a los espíritus de los muertos.\n\nComo apunte, porque sé que te interesará, el Estandarte de Provocación puede utilizarse de forma parecida en la arena de las Profundidades de Roca Negra. No dejes de dar una lección de mi parte a Theldren y sus matones siempre que tengas ocasión de pasar por allí.\n\nSigue leyendo si deseas saber más.", "ISALIEN\n\nSacerdotisa de la Luna de los elfos de la noche\n\nCuando Isalien decidió dejar la compañía, lo hizo con intención de peregrinar a La Masacre, la ciudad ancestral caída de los elfos de la noche antes conocida como Eldre'Thalas. Allí aún hay una biblioteca de grandes conocimientos, un santuario que un pequeño grupo de elfos de la noche ha logrado preservar. Quería encontrar respuestas sobre su herencia y quizá sobre los fragmentos del amuleto. Cabe señalar que también era buena amiga de Falrin Tallarbol.", "ISALIEN, continuación...\n\nPor desgracia, cuando ella y su compañero hipogrifo Empíreo entraban en la ciudad, Alzzin el Formaferal y sus esbirros los atacaron. Allí cayó para no volver a levantarse. Quizá sea mejor que Isalien nunca descubriera más secretos de la magia maligna con la que lord Valthalak encerró parte de su esencia en el amuleto.\n\nLa cámara al aire libre donde reside Alzzin es uno de estos lugares embrujados.", "MOR PEZUÑA GRIS\n\nDruida tauren y primero en caer\n\nMor Pezuña Gris fue siempre un compañero firme y de confianza en La Hoja Velada. Es una desgracia que fuera el primero en caer ante los malvados esbirros de lord Valthalak.\n\nMientras huíamos de Valthalak, nos perseguía un auténtico ejército de sus asesinos y acechadores espectrales. La huida de la Cumbre de Roca Negra fue caótica, por decirlo suavemente. Por desgracia, Mor perdió pie por el camino, aunque sospecho que lo empujaron. En cualquier caso, cayó hasta las profundidades de la parte inferior de la Cumbre.", "MOR PEZUÑA GRIS, continuación...\n\nDespués descubrimos que Mor había sobrevivido a la caída. Pero mi buen amigo no tendría un final feliz: los trols de Tazz'Alaor lo hicieron prisionero. Poco después, mientras el maestro de guerra Voone lo torturaba, un grupo de asesinos de Valthalak irrumpió y terminó el trabajo.\n\nSi quieres invocar el eco del espíritu de Mor Pezuña Gris, la cámara del maestro de guerra Voone es un lugar embrujado.", "JARIEN Y SOTHOS\n\nHermanos y aspirantes a la Cruzada Escarlata\n\nJarien y Sothos eran dos de las personas más intolerantes que conocía. Sin embargo, su destreza en combate era excepcional y venían de una familia adinerada, lo que supongo que explica por qué Anthion, dirigente de La Hoja Velada, los conservaba.\n\nLos hermanos acabaron prendados de las enseñanzas y la filosofía de la Cruzada Escarlata. Siempre habían mostrado un celo especial al aniquilar a cualquier miembro de la Plaga que encontráramos en nuestros viajes. Se sospechaba que su familia tenía vínculos con la organización.", "JARIEN Y SOTHOS, continuación...\n\nAsí llegaron a afrontar las pruebas exigidas a quienes quieren unirse a la Cruzada. Les interesaba especialmente ser caballeros en sus filas, algo que al parecer exigía pruebas más difíciles. Después se supo que Sothos había fallado la prueba final. Jarien no lo aceptó y, desafiándolos abiertamente, insistió en que le permitieran unirse a ella entre los caballeros. Por lo que hemos averiguado, el gran cruzado Dathrohan los mató allí mismo, en mitad de sus aposentos.\n\nAsí, otro de estos lugares embrujados es el Trono Carmesí, dentro del Bastión Escarlata de Stratholme.", "KORMOK\n\nNigromante ogro de dos cabezas\n\n¿Qué puede decirse de Kormok? Era un ogro de dos cabezas de los que lanzan hechizos y antes no era tan malo. Cuando lo acogimos, era un prisionero de un encargo que habíamos aceptado en Las Estepas Ardientes. Sin embargo, resultó inestimable para salir de un buen apuro en el que caímos allí y se convirtió en uno de los principales magos de la compañía.\n\nLo extraño era la naturaleza completamente distinta de sus dos cabezas. Una siempre estaba alegre, aunque fuera un poco tonta. La otra era astuta, calculadora y tenía una mirada casi muerta. Daba bastante miedo, la verdad.", "KORMOK, continuación...\n\nMás tarde, en nuestros viajes, Kormok entró en contacto con la vertiente nigromántica de la magia. Por desgracia, la cabeza siniestra mostró afinidad para levantar espíritus muertos y un placer perverso al hacerlo, sobre todo al invocar a los espíritus exiliados de la Isla del Purgatorio para que lo obedecieran.\n\nCuando se disolvió la compañía, Kormok ingresó en Scholomance para continuar su 'educación'. Los asesinos espectrales entraron en la escuela con demasiada facilidad y lo mataron ante su nuevo maestro, Ras Murmuhielo.\n\nPor ello, la cámara de Ras Murmuhielo es uno de los lugares embrujados donde puede utilizarse el brasero con éxito.", "LORD VALTHALAK\n\nNoble dracónido y antiguo general de la Cumbre de Roca Negra\n\nAntes del general Drakkisath estuvo lord Valthalak, un brujo dracónido de inmenso poder. Es habitual que cambie el mando de la Cumbre y, por desgracia para nosotros, íbamos a participar en el último relevo.\n\nUn mago contrabandista goblin de Bahía del Botín, Gremnik Saltatrabas, nos encargó robar el libro de hechizos de Valthalak. No sabemos si quería estudiarlo, venderlo o ambas cosas, y ya no importa. Lo que importa es que nos infiltramos en lo alto de la Cumbre de Roca Negra y matamos a lord Valthalak en su guarida. Ahí empezó la diversión de verdad.", "LORD VALTHALAK, continuación...\n\nNo teníamos idea de lo profundo que era el conocimiento mágico de Valthalak sobre la manipulación de almas. De haberlo sabido, probablemente nunca habríamos aceptado el encargo. Pero lo aceptamos y resultó ser el último.\n\nTras matar a lord Valthalak y llevarnos su libro de hechizos, Kormok debió de notar algo en su amuleto. Insistió en tomarlo como su parte del botín, lo que pronto degeneró en una discusión acalorada y casi una pelea por el objeto. No sabíamos entonces que el amuleto albergaba buena parte del espíritu de Valthalak. Lo descubrimos después, para nuestro disgusto.", "LORD VALTHALAK, continuación...\n\nDividimos el amuleto en fragmentos y huimos del recién alzado fantasma de Valthalak y de su ejército de asesinos espectrales. ¡Y el ruido que hicimos discutiendo por el amuleto había despertado a varios defensores que quedaban en la Cumbre!\n\nCasi todos salimos de Roca Negra y creímos estar a salvo. Pero, incluso desde el más allá, Valthalak nos envió a sus esbirros sin importar dónde nos ocultáramos. La Hoja Velada se disolvió poco después de aquella misión y entonces fuimos presas fáciles.\n\nComo ya debes saber, esto convierte la morada de lord Valthalak, hoy la cámara de La Bestia en la Cumbre de Roca Negra, en el último de los lugares embrujados." } } },
    ["Brock's List"] = { { ids = { "i16310" }, first = "belowistheliststudentswh", pages = { "A continuación, adjunto la lista de los estudiantes que han obtenido la Estrella de Platino en la Escuela de Minas y Topografía de Brock, adquiriendo un Pico de Minero Honorario:\n\nMelia Agitapiedras\nBardin Vetaferro\nUmi Voltiflop\nRumi Voltiflop\nVorel Agujacero" } } },
    ["Call to Arms Announcement"] = { { ids = { "i22595" }, first = "toallablebodiedmenandwom", pages = { "A todos los hombres y mujeres sanos:\n\nLa Plaga ha regresado y, para hacer frente a esta amenaza, debemos dejar a un lado todos nuestros conflictos. El Alba Argenta acabará con todos aquellos que no empuñen las armas contra la amenaza de la Plaga.\n\nLos que han decidido defender nuestras tierras están reunidos en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este. Juntos, venceremos.\n\nGuardián de los Pergaminos\nEl Alba Argenta" } } },
    ["Calor's Note"] = { { ids = { "i2113" }, first = "mastercarevinthebearerof", pages = { "Maestro Carevin,\n\n$g:El portador:La portadora; de esta nota ha probado su integridad al amparo de la Luz, demostrando su destreza en el combate de los no-muertos y los demonios que asolan las lindes del Bosque del Ocaso, $gdeseoso:deseosa; de unirse a la familia Carevin en la causa de la Luz.\n\nPor esta razón sugiero que asignes a $geste guerrero:esta guerrera; de la Luz nuevas tareas, por ejemplo, investigar a algunos de los habitantes del lugar, sospechosos de colaborar con los enemigos de la Luz.\n\nOs saluda atentamente,\nCalor" } } },
    ["Captain's Documents"] = { { ids = { "i5882" }, first = "daytroopmovementnearther", pages = { "El Gorrión Sangrante: Manifiesto\n\n (20) barriles de ron. Destino: Theramore\n(50) sacos de harina. Destino: Theramore\n(2) cajas de herramientas gnómicas variadas. Destino: Trinquete\n(30) rollos de paño de algodón. Destino: Theramore\n(4) cajas de especias. Destino: Theramore\n(3) pasajeros. Destino: Theramore", "Capitán,\n\nte deseo suerte en tus viajes. Desafortunadamente, la fortuna no nos favoreció en nuestro primer intento de secuestro.\n\nCuando nuestro equipo divisó el objetivo en los túneles que unen Ventormenta con Forjaz, solo encontró un señuelo. Él demostró ser más listo de lo que creímos.\n\nPero nuestro segundo plan ya está en marcha. Los agentes de Defias están preparados para interceptar el objetivo a medida que se acerque a Theramore. Pronto sorprenderemos a Ventormenta con un ataque feroz.\n\n-M" } } },
    ["Certificate of Thievery"] = { { ids = { "i7907" }, first = "thebearerofthiscertifica", pages = { "$gEl portador:La portadora; de este certificado obtendrá el respeto y la consideración que merece un ratero o un ladrón." } } },
    ["Charge of the Dragonflights"] = { { ids = { "o175726" }, first = "satisfiedthatthesmallwor", pages = { "Satisfechos con el pequeño universo que habían creado, los titanes se prepararon para abandonar Azeroth. No obstante, antes de partir, encomendaron a las grandes especies del planeta la tarea de vigilar Kalimdor, para evitar que fuerzas adversas amenazaran su perfecta armonía. En aquella época, existían muchas clases de dragones.", "Sin embargo, había cinco grupos que dominaban a sus hermanos. Estos cinco grupos fueron elegidos por los titanes para guiar al mundo naciente. Los miembros más destacados del Panteón transmitieron parte de su poder a los jefes de las bandadas de dragones. Estos dragones majestuosos (que se describen a continuación) eran conocidos como los Grandes Aspectos o los Aspectos Dragones.", "Aman'Thul, Alto Padre del Panteón volcó parte de su poder cósmico sobre el gigantesco dragón de bronce Nozdormu. El Alto Padre otorgó poderes a Nozdormu para que vigilara él mismo el transcurrir del tiempo y supervisara los intrincados caminos de la fortuna y el destino. El estoico y honorable Nozdormu era conocido con el nombre de El Atemporal.", "Eonar, guardiana de la vida, otorgó parte de su poder a la gigantesca Alexstrasza. Mucho tiempo después, Alexstrasza recibió el nombre de la Protectora, pues su misión era defender a todas las criaturas vivientes del planeta. Gracias a su suprema sabiduría y a su ilimitada compasión por todos los seres vivos, Alexstrasza fue nombrada reina de los dragones por los de su especie.", "Eonar también bendijo a la hermana menor de Alexstrasza, la ágil dragona verde Ysera, con una porción de su influencia sobre la naturaleza. Ysera cayó en un trance eterno, atada al Sueño de la Creación. Conocida como la Soñadora, vigilaría las extensas áreas salvajes del mundo desde su reino verde, el Sueño Esmeralda.", "Norgannon, titán guardián del conocimiento y mago maestro, cedió al dragón azul Malygos parte de su vasto poder. A partir de entonces, Malygos fue conocido como el Tejechizos, el guardián de la magia y el arcano oculto.", "Khaz'goroth, creador de titanes y forjador del mundo, confirió parte de su extenso poder al poderoso wyrm negro Neltharion. Al bondadoso Neltharion, conocido posteriormente como el Guardián de la Tierra, se le otorgó el dominio de la tierra y los rincones más recónditos del orbe. Encarnaba la fortaleza del mundo y actuaba como gran protector de Alexstrasza.", "Con estos poderes, los Cinco Aspectos tenían la misión de defender al mundo en ausencia de los titanes. Cuando los dragones ya estaban preparados para vigilar su creación, los titanes abandonaron Azeroth para siempre. Desafortunadamente, el descubrimiento del nuevo mundo por parte de Sargeras era solo cuestión de tiempo." } } },
    ["Charred Note"] = { { ids = { "i205864" }, first = "adaimpleasedtohearisland", pages = { "<La página está chamuscada en varios puntos, como si alguien hubiera intentado quemarla con prisa. Parte de lo que queda es legible.>\n\nAda:\n\nMe alegra saber -------- isla en la orilla oscurecida. ----- Uno de nuestros agentes ------------ contraseña ----\n\n\"Cuando una vela se apaga, otra se enciende.\"\n\n- Mitchells" } } },
    ["Civil War in the Plaguelands"] = { { ids = { "o175761" }, first = "nerzhulthelichkingknewth", pages = { "Ner'zhul, el rey Exánime, sabía que le quedaba poco tiempo. Prisionero en el Trono de Hielo, sospechaba que Kil'jaeden enviaría a sus agentes para destruirlo. El daño causado por el encantamiento de Illidan había roto el Trono de Hielo. De esa manera, el rey Exánime perdía su poder diariamente. Desesperado por salvarse, trajo a su lado a su mayor sirviente mortal: el caballero muerto, el príncipe Arthas.", "Aunque sus poderes fueron consumidos por la debilidad del rey Exánime, Arthas participó en una guerra civil en Lordaeron. La mitad de las fuerzas de no-muertos aún en pie, conducidos por el alma en pena Sylvanas Brisaveloz, dieron un golpe de mano para controlar el imperio de los no-muertos. Arthas, llamado por el rey Exánime, fue obligado a abandonar la Plaga en manos de su lugarteniente, Kel'Thuzad, cuando la guerra se extendió por las Tierras de la Peste.", "Finalmente, Sylvanas y sus no-muertos rebeldes (conocidos como los Renegados) reclamaron la propiedad de la destruida ciudad capital de Lordaeron. Tras construir su propio bastión bajo la ciudad en ruinas, los Renegados juraron derrotar a la Plaga y expulsar a Kel'Thuzad y a sus esbirros de aquellas tierras.", "Debilitado, pero decidido a salvar a su maestro, Arthas llegó a Rasganorte para descubrir que los nagas y los elfos de sangre de Illidan estaban esperándole. Él y sus aliados nerubianos lucharon contra las fuerzas de Illidan para alcanzar el glaciar de Corona de Hielo y defender el Trono de Hielo." } } },
    ["Cliffwatcher Longhorn Report"] = { { ids = { "i13507" }, first = "natakaalliswellinthousan", pages = { "Nataka, todo está bien en las Mil Agujas. La irritación del centauro no es más que eso... ocasionales ataques, nada sustancial que suponga una amenaza real. Sin embargo, parece que se están uniendo nuevos clanes centauros.\n\nSiempre hemos tenido en cuenta la amenaza que supondría la unión de una raza despiadada como la de los centauros... Como bien sabes, intento no pensar demasiado en esta clase de ideas... nada puede competir con el odio puro que destilan... incluso entre ellos.\n\nVigiarrisco Cuernolargo" } } },
    ["Cloth Request"] = { { ids = { "i2724" }, first = "totheschneidersgooddayit", pages = { "A los Schneider,\n\nBuenos días: Confío en que hacer negocios en el distrito del canal resulta conveniente. Estamos en auge, en la plaza de los comerciantes.\n\nNecesitamos prendas de vestir tejidas, ya que nuestras existencias se han acabado. Por favor, envía un cargamento estándar tan pronto como puedas.\n\nBuena suerte y confío en que los estudios de tu hijo Thurman progresen adecuadamente,\n\nHarlan Bagley" } } },
    ["Compendium of the Fallen"] = { { ids = { "i5535" }, first = "withkelthuzadssuccessinl", pages = { "Con el éxito de Kel'Thuzad en Lordaeron, el rey Exánime realizó los preparativos finales para asaltar la civilización humana. Tras volcar su energía corrupta sobre diversos artefactos portátiles llamados calderas de la peste, Ner'zhul ordenó a Kel'Thuzad que llevara las calderas a Lordaeron, ocultándolas en varios poblados leales.", "Las calderas, protegidas por fieles seguidores, actuarían como generadores de peste, dispersándola a través de los indefensos campos y ciudades del norte de Lordaeron.\n\nEl plan del rey Exánime funcionó perfectamente. Muchos poblados del norte de Lordaeron se contaminaron casi de inmediato. Como ocurrió en Rasganorte, los ciudadanos que contrajeron la peste murieron y renacieron como esclavos voluntarios.", "Los seguidores de Kel'Thuzad deseaban morir para renacer al servicio del señor de las tinieblas. Se regocijaban ante la perspectiva de la inmortalidad de los no-muertos. Con la propagación de la peste, cada vez más zombis ferales se alzaron en las tierras del norte. Kel'Thuzad observó el ejército del rey Exánime y lo nombró la Plaga, pues pronto marcharía hasta las puertas de Lordaeron... borrando a la humanidad de la faz del mundo." } } },
    ["Confidential Message"] = { { ids = { "i210967" }, first = "brotheresolonshouldyoune", pages = { "Hermano Esolon:\n\nSi necesitas entrar en el relicario, he ocultado una llave en el cementerio. Está en un cofre de piedra, bajo el suelo del mausoleo norte.\n\nHay un mecanismo para alzar el cofre. Para activarlo debes sentarte en los dos bancos que hay entre los pares de estatuas a ambos lados del cementerio.\n\nTe ruego que trates esta información con la máxima reserva.\n\nBendiciones,\nHermano Seramus" } } },
    ["Consecrated Letter"] = { { ids = { "i9570" }, first = "ihopethisletterfindsyouw", pages = { "Espero que cuando recibas esta carta, estés bien, $C. Digo esto con mucho orgullo, ya que muchos no profesan una fe tan profunda, pero también saben que están entre la élite de los protectores de Azeroth. Recuerda siempre, por encima de todo, que tu deber consiste en luchar contra todos aquellos que quieran dañar nuestro mundo y llevar la corrupción a nuestros hogares.\n\nHe recibido autorización para ocuparme de tu instrucción. Cuando estés $gpreparado:preparada;, búscame en la Abadía de Rasganorte.\n\nHermano Sammuel, instructor de paladines" } } },
    ["Consecrated Rune"] = { { ids = { "i9563" }, first = "somefearourkindmorethand", pages = { "Algunos nos temen más que a los dragones. Algunos nos envidian más que a los herreros más diestros. Algunos alaban nuestra fuerza en combate. Otros se deleitan con nuestra fe. ¡Y algunos solo envidian que podamos beber más que ellos! Pero debes saber, $c, que formas parte de los protectores más selectos de Azeroth. La Luz Sagrada nos da fuerza tanto como nosotros la fortalecemos.\n\nTe contaré más cuando conozcas un poco estas tierras. Búscame dentro de Yunquemar, sobre el Valle.\n\n-Bromos Grummner, instructor de paladines" } } },
    ["Consecrated Scroll"] = { { ids = { "i282423" }, first = "welcomebackiunderstandal", pages = { "Te doy la bienvenida de nuevo, $N.\n\nComprendo muy bien la conmoción de encontrarse en tu situación actual. Haber llegado hasta aquí te distingue de muchos otros paladines recién alzados.\n\nDescubrirás que lo más difícil de tu nueva vida será redescubrir lo que perdiste en vida... y soportar el dolor que te cause.\n\nHabla conmigo en Camposanto y te ayudaré a encontrar la determinación para dar tus primeros pasos.\n\n-Aramis Manomartillo, instructor de paladines" } } },
    ["Control Console Operating Manual"] = { { ids = { "i5088" }, first = "thesamophlangecontrolcon", pages = { "La consola de control de samoflange puede utilizarse para regular automáticamente el flujo de los combustibles, gases, líquidos y otra maquinaria relacionada. Una vez que se ha completado la configuración inicial, debería funcionar sin problemas, con un mantenimiento mínimo.\n\nBreve listado de los componentes de la consola de control (de izquierda a derecha)\n\nI. Palanca de potencia principal\n\nLa posición de conexión activa el samoflange. Cuando la palanca esté en posición desactivada, el mecanismo de control no se desconectará de forma automática. Simplemente, esto hará que", "comienza el proceso de enfriamiento y, a partir de entonces, tardará aproximadamente uno o dos minutos en desactivarse, dependiendo de la situación.\n\nNOTA IMPORTANTE: La palanca de alimentación principal solo puede utilizarse cuando se hayan desconectado las tres válvulas de control en la maquinaria real. Dichas válvulas pueden desconectarse en cualquier orden.\n\nLa primera es la VÁLVULA DE CONTROL PRINCIPAL, que se encuentra en la base de la gran chimenea vertical. A continuación, la VÁLVULA DE CONTROL DE COMBUSTIBLE se encuentra en la gran tubería que conecta los", "tanques de combustible (debe haber tres) con la chimenea. Finalmente, la VÁLVULA REGULADORA se encuentra en la parte inferior de los dos grandes tanques cilíndricos que se introducen en la chimenea.\n\nII. Indicadores de combustible\n\nMuestra la presión actual en los tanques de combustibles primario, secundario y terciario.\n\nIII. Indicador de flujo\n\nMuestra la tasa de flujo actual dentro del sistema.", "IV. Controles de flujo\n\nAumentan o disminuyen las tasas de flujo. Es controlado automáticamente por el mecanismo de control del samoflange.\n\nV. Indicador de temperatura\n\nMuestra la temperatura operativa del sistema en general." } } },
    ["Covert Ops Plans: Alpha & Beta"] = { { ids = { "i5737" }, first = "okayyoushouldhaveyourngc", pages = { "Vale, deberás tener tus cargas NG-5 y tus detonadores preparados. Los he etiquetado para ti... El azul corresponde a la serrería. El rojo, a la mina Cortaviento.\n\nHe reconocido un poco el terreno y he encontrado suficientes explosivos en el risco Cortaviento, de manera que no debería ser un problema para ti llegar hasta allí, colocar los explosivos y marcharte antes de detonarlos.\n\nRecuerda, esto es una distracción. Aléjate de los carros antes de que los goblins vaya a ver qué ha ocurrido, y luego escabúllete detrás suyo.", "Por cierto, ten cuidado con ellos. Basta el nitromirgliceronio para reducirte a polvo. He colocado parte del líquido en tubos de cobre para mantenerlo estable y seguro.\n\nHe utilizado en las cajas del detonador el pergamino que te entregó Collin. Ahora, ellos enviarán un mensaje silencioso a las cargas NG-5 después de que las hayas preparado. He utilizado un sencillo mecanismo Stalthwargon para garantizar que la conductividad sea óptima y el flujo de nitromirgliceronio entre el fluido diferencial sea superior a la media.", "Antes de que pueda volver a los detalles sobre mi diseño, déjame explicarte dónde debes colocar los explosivos.\n\nPlan A: la serrería.\nHay un carro justo en frente de la serrería (está al noreste de la zona deforestada y del constructo para el almacenamiento de la madera). Sospecho que los planes de ingeniería se encuentran dentro de la serrería.\n\nPara colocar la carga, dirígete a la parte trasera del carro. Una vez que esté colocada, date prisa y aléjate del lugar.", "Cuando estés $glisto:lista;, pulsa el detonador.\n\nMe he asegurado que haya una señal fuerte, canalizando cables de cobre y plata con un conjunto de antenas meltusianas bajo la cubierta de la caja. Esto debería garantizar que todo vaya perfectamente. Simplemente, ten cuidado de los goblins que estén cerca. Si te cogen con las manos en la masa, no creo que aprecien mucho mi creación.\n\nAh, por si aún no lo tienes claro, trata de alejarte del carro cuando explote. Puede hacerte bastante daño.", "Plan B: Mina Cortaviento:\n\nHe visto que los goblins utilizan otro carro de explosivos situado al norte de la entrada de la mina. Creo que es un sitio bastante bueno para colocar una carga de NG-5 (roja). Una vez que hayas colocado la carga en la parte trasera del carro, toma distancia y pulsa el botón.\n\nSi los goblins no vienen corriendo a ver qué ha sucedido, probablemente es porque la montaña se les haya venido encima.", "Las cartas de Ventura y Cía. están situadas fuera de la mina... Creo que están sobre unos cajones que están en el nivel inferior.\n\nBuena suerte... y recuerda...\n\nCarga azul: serrería\nCarga roja: mina\n\nAh, y, una vez que hayas cumplido esta misión, destruye esta carta. Mmm, debería inventar un medio para que estas cosas se autodestruyan una vez leídas. No es mala idea..." } } },
    ["Crate of Horseshoes"] = { { ids = { "i1284" }, first = "anoteisattachedtothecrat", pages = { "El cajón lleva una nota adjunta. La nota dice:\n\n\"Verner, lamento saber que Crestagrana tiene tantos problemas. Aquí están las herraduras que necesitas. Por favor, no olvides pagarme 100 monedas de plata en cuanto te sea posible.\"\n\n\"O bien, si lo prefieres, puedes pagarme con escamas de vientre de cría (he oído que las crías de dragón son comunes en las montañas Crestagrana). Porque somos amigos... 4 escamas serán suficiente. Gracias, Argus\"" } } },
    ["Crude Map"] = { { ids = { "i21037" }, first = "", pages = { "" } } },
    ["Crumpled Note"] = { { ids = { "i4100" }, first = "fleeingfromthezanzilinth", pages = { "Escapar de Zanzil en ese buque destartalado parecía buena idea en otros tiempos, pero creo que la muerte habría sido un destino más apropiado.\n\nPensé que mis ancestros me han ayudado al permitirme escapar de su ira. Pero ahora me pregunto qué gano con vivir aquí encarcelado." } }, { ids = { "i282419" }, first = "youvegotagoodswordarmand", pages = { "$N, tienes buen brazo con la espada y me he fijado en ello.\n\nNo cabe duda de que las cosas están bastante revueltas aquí en la Isla de Zephras. Necesitamos a nuestros combatientes shen'dorei en plena forma si queremos sobrevivir a lo que viene. Ya es hora de dejar de jugar a ser un guerrero de verdad y convertirte en uno.\n\nBúscame dentro de la base de la atalaya de Thendal. Me aseguraré de que recibas la instrucción adecuada.\n\n-Maestra del acero Ren, instructora de guerreros" } } },
    ["Crystal Pylon User's Manual"] = { { ids = { "i11482" }, first = "crystalpylonusersmanuala", pages = { "MANUAL DEL USUARIO DE LA TORRE DE CRISTAL\n\n \"Una guía para coleccionar y usar los cristales de poder del cráter de Un'Goro\"\n\nCapítulo 1: La torre del norte\n\nCapítulo 2: La torre del este\n\nCapítulo 3: La torre del oeste", "Capítulo 1: LA TORRE DEL NORTE\n\nLa torre del norte\nacepta cristales\namarillos, rojos,\ny verdes\n.\n\nLa torre se centra en la energía que se puede generar usando los cristales amarillos como fuente principal de poder.", "Combinación de cristales del norte\n\nHay dos efectos posibles: uno produce daño y el otro lo anula.\n\nCARGA DE CRISTAL: Requiere cristales rojos y amarillos.\nEsto produce una gran explosión.\n\nCRISTAL DE RECUPERACIÓN: Requiere cristales amarillos y verdes.\nEste cristal te proporcionará un aura de curación.", "DIAGRAMA DE LA TORRE DEL NORTE", "Capítulo 2: LA TORRE DEL ESTE\n\nLa torre del este\nacepta cristales\nazules,amarillos\ny verdes\n.\n\nLa torre se centra en la energía que se puede generar usando los cristales azules como fuente principal de poder.", "Combinación de cristales del este\n\nHay dos efectos posibles: uno proporciona puntos adicionales para el espíritu y el otro crea un escudo de ataque.\n\nFUERZA DE LOS CRISTALES: Requiere el uso de cristales azules y verdes.\nEsto aumentará tu espíritu.\n\nAGUJA DE CRISTAL: Requiere cristales azules y amarillos.\nCreará un escudo que hará daño a los atacantes.", "DIAGRAMA DE LA TORRE DEL ESTE", "Capítulo 3: THE WESTERN PYLON\n\nLa torre del oeste\nacepta cristales\nrojos, verdes\ny azules\n.\n\nLa torre se centra en la energía que se puede generar usando los cristales rojos como fuente principal de poder.", "Combinación de cristales del oeste\n\nHay dos efectos posibles: uno para aumentar la protección frente al daño y otro para debilitar las defensas del enemigo.\n\nCUSTODIA DE CRISTAL: Requiere el uso de cristales rojos y verdes.\nEsto aumentará tu armadura.\n\nRENDIMIENTO DE CRISTAL: Requiere cristales azules y rojos.\nPuede reducir la armadura de un objetivo específico.", "DIAGRAMA DE LA TORRE DEL OESTEn" } } },
    ["Crystallized Note"] = { { ids = { "i10839" }, first = "towhomitmayconcernifyoua", pages = { "A quien corresponda:\n\nSi lees esta nota, significa que estás en uno de estos dos lugares:\n\n(1) En la península del sur de Azshara.\n\n(2) En las entrañas de un gigante del acantilado.\n\nAmbas opciones son poco deseables.\n\nDebo señalar que anteriormente fui el primero y mientras escribo esta carta, el último.", "Permanecer en el interior de un gigante le da a uno tiempo para reflexionar.\n\nMientras mi cuerpo se cristaliza, he llegado a la conclusión de que tal vez no hagan falta más héroes en este mundo. ¡Cuando salga de este apuro, voy a agarrar a ese orco por su fantasmagórico cuello!\n\nWindan Shay" } }, { ids = { "i10840" }, first = "whatwasithinkingperhapsa", pages = { "¿En qué estaba pensando?\n\nQuizás sería mejor preguntar: ¿Qué hago escribiendo una nota mientras estoy aquí atrapado en el vientre de un gigante?\n\nSon dos buenas preguntas para las que no tengo una respuesta inmediata...\n\nTengo que admitir que la mía no era una misión conciliadora. Vine en busca de azsharita, un cristal único en el sur de Azshara. ¡Ah, cuántas riquezas podría tener!\n\n¡Bah! Ahora miradme...", "Si algún ser con vida inteligente encuentra esta nota, deberá preguntarse lo siguiente: \"¿Cómo es posible que ellos estén jugando con violentos gigantes de casi diez metros de altura?\"\n\n- Mook" } } },
    ["Cutty's Note"] = { { ids = { "i203723" }, first = "ivegotthegoodsillbehidin", pages = { "Tengo el material. Me esconderé río arriba, subiendo desde el lago, cerca del muro. Si mandas a uno de tus agentes a recoger la mercancía, ¡dile que se asegure de que no lo vea nadie!\n\n- Cutty" } } },
    ["Damp Diary Page (Day 4)"] = { { ids = { "i6304" }, first = "diarydayihavebeenstrande", pages = { "Diario - Día 4\n\nLlevo cuatro días varado en la isla, solo con mis pensamientos. Los plátanos están bastante ricos, pero hay que trepar mucho para alcanzarlos. Cuando no busco comida o me protejo de la lluvia ocasional, no pienso más que en el rescate.\n\nNo tendría tantas esperanzas de no ser por las cajas de papel y las botellas que llegaron a la orilla conmigo. Ahora me río al pensar en todo el tiempo que pasé en aquel barco maldiciendo mi suerte por estar atrapado con un cargamento de alquimistas y escribas." } } },
    ["Damp Diary Page (Day 512)"] = { { ids = { "i6306" }, first = "diarydaythebananashavest", pages = { "Diario - Día 512\n\nLos plátanos han empezado a hablarme y he aprendido mucho sobre su cultura. He cesado en mi absurda destrucción de sus hogares y en el consumo de sus pequeños. Qué poco sabía entonces de la gran civilización que estaba destruyendo.\n\nPor otro lado, parece que me quedan pocas botellas y poco papel. Cuando vi por primera vez aquellos enormes montones que llegaron a la orilla, pensé que serían inagotables. Ay de mí, mi diario pronto tendrá que terminar." } } },
    ["Damp Diary Page (Day 87)"] = { { ids = { "i6305" }, first = "thesemonthshavegivenmeti", pages = { "En estos meses he podido reflexionar y he cuestionado mis antiguas creencias e intolerancias. ¿Alianza? ¿Horda? ¿Bien? ¿Mal? El significado de estas palabras, que antes parecía tan claro, ahora se difumina mientras mis ojos se pierden en el mar infinito.\n\nAhora sé lo que importa. Los plátanos me persiguen.\n\nColgados en sus árboles, me observan con fría malevolencia. ¡Y el último que intenté comerme me produjo arcadas! Creo haber oído cómo gritaba mientras lo arrojaba, a medio comer, sobre las rocas marinas.\n\nEs la guerra, y la ganaré." } } },
    ["Danath Trollbane"] = { { ids = { "o25332" }, first = "danathtrollbanemilitiaco", pages = { "Danath Aterratrols\n\nComandante de Milicia de Stromgarde. Consejero táctico del general Turalyon, Comandante de Fuerza de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido.\n\n\"Querido sobrino, honramos tu memoria y valoramos tu sacrificio. Desde la fundación de nuestro glorioso imperio, la senda del valor siempre se ha abonado con la sangre de los héroes.\"\n\n- Thoras Aterratrols, Señor de Stromgarde" } } },
    ["Dark Iron Script"] = { { ids = { "i6847" }, first = "dirtytroggsaresoeasytofo", pages = { "Es tan fácil engañar a esos sucios troggs. Su odio hacia nuestros parientes hace aún más sencillo dirigirlos y usarlos como peones. Me asombra que haya podido forjarse alianza alguna, pero nuestros parientes suponen una amenaza mucho mayor para su existencia... al menos por ahora.\n\nCuando empiecen los ataques, ambos bandos quedarán debilitados y expuestos a nuestra propia ofensiva. Tomad la granja al sur del Lago de Helm y esperad nuevas instrucciones.\n\nForjaz será nuestra." } } },
    ["Dark Keeper Nameplate"] = { { ids = { "o164820" }, first = "vorfalkirongourdvorfalkw", pages = { "Vorfalk Irongourd\n\nVorfalk trabaja en el almacén del Tragapenas, y sus sacrificios en nombre de los Guardas oscuros ha dejado honda huella.\n\nQue su espíritu conserve la fuerza." } }, { ids = { "o164821" }, first = "bethekstormbrowbethekswa", pages = { "Bethek Tormenceño\n\n Las andanzas de Bethek le llevan a adentrarse en Roca Negra. Los secretos de la montaña lo atraen.\n\nQue su espíritu nunca decaiga." } }, { ids = { "o164822" }, first = "uggelhammerhanduggelisas", pages = { "Uggel Manomartillo\n\n Uggel es un diestro y solemne grabador, y cuando no está poseído por la llave oscura, sus manos modelan grandes piezas en la Sala de los Oficios." } }, { ids = { "o164823" }, first = "zimreldarktoothwhenthema", pages = { "Zimrel Dienteoscuro\n\nCuando Zimrel recibe el influjo de la llave oscura, solo los gritos de los moribundos lo calman.\n\nPara su sacrificio, siempre tendrá un banco en el coliseo. Que nuestros deportes de sangre aplaquen la furia de su corazón." } }, { ids = { "o164824" }, first = "ofgutstonefistthosefalle", pages = { "Ofgut Puñopiedra\n\n Son incontables los caídos bajo el martillo del guarda oscuro Ofgut.\n\nLos soldados del Cuartel del Este se inclinan sobrecogidos a su paso. ¿Quién ha podido escudriñar los ojos de Ofgut para conocer los secretos que la llave oscura le susurra?" } }, { ids = { "o164825" }, first = "pelverdeepstompdarkkeepe", pages = { "Pelver Pasofuerte\n\nEl guarda oscuro Pelver es nuestro discípulo más honorable. Ha soportado la carga de la llave durante más tiempo que ninguno y esto le ha costado muy caro. Cuando se le pide el cargamento, es custodiado en el Domicilio.\n\nSu sacrifico es muy apreciado y él permanecerá en nuestros corazones por muchos años... cuando la oscuridad se lo lleve." } } },
    ["Deathstalker Report"] = { { ids = { "i3252" }, first = "deathstalkermissionrepor", pages = { "Informe de misión del Mortacechador\n\nAgentes: Rane Yorick, Quinn Yorick, Erland McKree\n\nMisión principal: llevar a cabo un reconocimiento a través de los argénteos del norte y determinar los niveles de amenaza que suponen la vida salvaje y la Plaga.", "Los agentes efectuaron un reconocimiento, encontrando presencia significativa de lupo. Recomendaron el envío de escuadrones de caza para reducir esta amenaza.\n\nSe encontraron gnolls no-muertos en los establos de la granja conocida como el Campo Muerto. Su propósito en la granja se desconoce, si bien sus movimientos y su nivel de preparación sugieren una acción militar inminente. Cuando fueron observados, no se encontraron líderes destacables entre los gnolls. Se supone que esperan la llegada de un líder, o bien de refuerzos.", "En pleno reconocimiento, nuestros agentes fueron detenidos en la granja de Ivar. Ivar, casi toda su familia y sus trabajadores sucumbieron a la Plaga y se convirtieron en sus esbirros.\n\nNuestros agentes fueron atacados y, aunque tuvieron éxito, combatiendo sus emboscadas, sufrieron graves heridas, particularmente el agente Quinn.", "Se tomó una posición defensiva en la vieja casa de Ivar y, mientras Rane vigilaba en previsión de futuros ataques, Erland continuó la misión de reconocimiento.\n\nLuego, Erland fue inmovilizado por lupos en un huerto situado en el norte, pudiendo escapar solo con la ayuda de otro agente Renegado. Dicho agente es $gel portador:la portadora; del presente informe.", "Hay que señalar que $gel portador:la portadora; del mensaje no solamente es un elemento importante en el éxito de nuestra misión, sino que también juega un gran papel en la derrota de Ivar el Hediondo, el rescate de Erland y la entrega de este informe.\n\nQueremos extender nuestra gratitud y recomendar que el mando reconozca los méritos de esta persona con las distinciones correspondientes.\n\nMortacechador Rane Yorick,\nLíder de la misión" } } },
    ["Decoded Tablet Transcription"] = { { ids = { "i20405" }, first = "dayourpilgrimageisoverwe", pages = { "Día 1\nNuestra peregrinación ha terminado. Por fin hemos llegado a Silithus, donde debemos establecer contacto. Hemos venido de muchos lugares para colaborar en lo que será una empresa monumental.\n\nEn el aire se respira una emoción inmensa. Mañana dedicaremos toda nuestra energía a construir lo que permitirá comunicarnos con ELLOS.\n\n¡Mañana construiremos una piedra de viento!", "Día 2\nLa ubicación de la piedra de viento ha sido objeto de un gran debate. Ni los más sabios pueden determinar con certeza a qué lugar se refiere realmente la antigua profecía.\n\nMe he quedado con el grupo original del norte y el tiempo sin duda nos dará la razón. El argumento de que las líneas de energía se cruzan en ángulos perjudiciales en este lugar es necio e ingenuo.\n\nYa reunimos los materiales necesarios a gran velocidad.", "Día 15\nNuestra dedicación ha dado fruto. Somos el primer campamento en terminar una piedra de viento. ¡Si los otros necios se hubieran quedado, habríamos acabado en menos de una semana!\n\nMañana comenzaremos los rituales para invocar al propio barón Kazum. Exigió ser el primero en probar el sistema y no pudimos contradecirlo, pues se enfada con facilidad.\n\nEspero que quede muy satisfecho con nosotros." } } },
    ["Decoded Twilight Text"] = { { ids = { "i20541" }, first = "forimmediatedisseminationtoalltwilightshammermembersthes", pages = { "Para entrega inmediata a todos los miembros del Martillo Crepuscular.\n\nLa búsqueda del traidor, Ortell, progresa de forma muy satisfactoria. Nuestros exploradores están estrechando el cerco en relación con una red de cavernas situadas en los Páramos de Poniente.\n\nLa traición de Ortell no caerá en el olvido y la posibilidad de que se fugue representa un gran riesgo para la seguridad de nuestra organización.\n\nCualquier individuo que oculte información sobre el paradero de Ortell será castigado debidamente.\n\nSeñor Crepuscular Everun" } }, { ids = { "i20545" }, first = "forimmediatedisseminationtoalltwilighth", pages = { "Para entrega inmediata a todos los miembros del Martillo Crepuscular.\n\nConsiderando el estado actual de las cosas en Silithus, la distribución de todos los textos de El creyente verdadero debe realizarse utilizando una escolta de no menos de cuatro miembros armados del Martillo Crepuscular.\nCualquier miembro que infrinja esta nueva política será castigado sumariamente.\n\nSeñor Crepuscular D'Sak" } }, { ids = { "i20552" }, first = "forimmediatedisseminationtoalltwilightshammermembersthef", pages = { "Para difusión inmediata entre todos los miembros del Martillo Crepuscular.\n\nLa información siguiente describe el uso de las piedras de viento para comunicarnos con nuestros amos del Consejo Abisal.\n\nTodo uso frívolo de las piedras de viento se castigará de la manera más dolorosa.\n\n-Guardián Crepuscular Havunth", "Templarios abisales\n\nComo iniciado, se te permite contactar con los templarios abisales para los rituales habituales. Recuerda llevar siempre la vestimenta adecuada al utilizar las piedras de viento para no activar nuestros encantamientos defensivos.\n\nEn caso de emergencia imprevista y sin supervisores presentes, tienes permiso para invocar a un templario abisal.\n\nPara los detalles de los rituales de invocación, consulta el Verdadero Creyente del mes pasado.", "Duques abisales\n\nSolo los acólitos que posean un medallón de estatus pueden contactar con los duques abisales. Los medallones solo pueden ser usados por las personas a las que se entregaron originalmente.\n\nYo mismo disciplinaré a los miembros del Martillo Crepuscular que establezcan comunicaciones no autorizadas con los duques abisales o utilicen medallones de estatus sin permiso.", "El Alto Consejo de los Señores Abisales\n\nSolo los señores del Crepúsculo pueden contactar con el príncipe Skaldrenox, el alto mariscal Eje Torbellino, el barón Kazum o lord Skwol.\n\nBajo ninguna circunstancia podrán los miembros de bajo rango del Martillo Crepuscular iniciar comunicaciones con el Alto Consejo. Cualquier extraño que utilice así una piedra de viento quedará reducido a cenizas en el acto." } }, { ids = { "i20676" }, first = "thestateofthecultvolumei", pages = { "El estado del culto, volumen 92\n\nCon el corazón exultante os saludo, hermanos míos, pues la situación de nuestro culto no podría ser más dichosa. Somos legión y nuestras metas se acercan cada vez más a su cumplimiento.\n\nSe nos unen nuevos reclutas. Todo son alabanzas a nuestros señores en Costa Oscura, se inclinan con reverencia en la Garganta de Fuego, abrazan al sirviente de nuestros maestros, Aku'mai, en las Cavernas de Brazanegra. ¡Ciertamente, hermanos y hermanas, pronto un enjambre de creyentes cubrirá todo Azeroth!" } }, { ids = { "i20677" }, first = "stateofthecultvolumeitis", pages = { "Estado del culto, volumen 127\n\n¡Es un día verdaderamente feliz! ¡Hemos sido puestos a prueba en Silithus y la hemos superado!\n\nLas noticias de la destrucción de nuestro campamento más septentrional quizá conmuevan a los infieles, pero esta matanza no debe verse como una tragedia. ¡No!", "¡Que uno de los miembros del Alto Consejo Abisal derrame nuestra sangre es una bendición! Debemos envidiar a nuestros camaradas caídos, ¡pues sus espíritus residen ahora en el vientre de una bestia justísima!\n\n¡Alabados sean los dioses antiguos! ¡Alabados sean sus sirvientes! ¡Alabado sea el Martillo Crepuscular!" } }, { ids = { "i20678" }, first = "stateofthecultvolumeoppo", pages = { "Estado del culto, volumen 233\n\n¡La oportunidad vuelve a llamar, hermanos y hermanas! El Círculo Cenarion, un culto vil de amantes de la naturaleza, envía ahora agentes contra nosotros. Deben de querer impedir que invoquemos piedras de atracción rojas. ¡No podemos permitirlo!\n\nLas piedras rojas son cruciales para nuestros nuevos aliados. No debemos dejar que triunfen los perros falderos del Círculo Cenarion. Manteneos firmes, amigos fieles. ¡Manteneos firmes!" } }, { ids = { "i20679" }, first = "howdoweknowtheyloveussom", pages = { "¿Cómo sabemos que nos aman?\n\nAlgunos se preguntarán cómo pueden amarnos los dioses antiguos y sus esbirros. ¿Acaso no nos matan? ¿No causan dolor y sufrimiento a todos? ¿Cómo pueden seres tan entregados a la maldad conocer el amor en sus corazones?\n\nLa respuesta es sencilla. ¿Tan sencilla que no hace falta pronunciarla?", "Fe. La fe es el manantial del que nos llueve la alegría de servir. La fe nos dará calor en las noches más frías de Silithus. La fe nos mantendrá en la gracia de nuestros señores cuando lleguen los Días del Fin.\n\nLa fe nos salvará." } } },
    ["Decorated Headstone"] = { { ids = { "o175933" }, first = "inlovingmemoryofjessemor", pages = { "Con cariño, en recuerdo de Jesse Morales" } } },
    ["Decrypted Letter"] = { { ids = { "i3518" }, first = "greetingsmasterforgiveme", pages = { "Saludos, maestro:\n\nTe pido disculpas por el sistema de envío de este mensaje. Mis magos de la sombra en Alterac están concentrados en sus tareas, obligándome a utilizar un mensajero extraño, reclutado entre nuestros nuevos \"aliados\", para hacerte llegar este informe. Pero he encriptado esta carta con uno de nuestros cifrados más esotéricos. Sus palabras están a salvo de estos palurdos.", "Nuestros planes avanzan adecuadamente: como dije antes, nos aliamos con un grupo de humanos que se hacen llamar la Hermandad. Sus líderes son antiguos nobles de Alterac y ansían volver a dominar estos territorios.\n\nPor eso hemos llegado a un acuerdo. Un acuerdo que lamentarán.", "La Hermandad apenas tiene influencia en estas tierras, pero conocen bien la zona y cuentan con suficiente mano de obra para realizar los próximos trabajos. Con un buen guía, confío en que pronto la Hermandad volverá a reinar en Alterac.\n\nAdemás, les hemos pedido que vuelvan a tomar la ciudad de Stromgarde, cerca de las Tierras Altas de Arathi. Esta ciudad es campo de batalla para nuestras fuerzas, ogros y humanos de Stromgarde, pero creemos que con tácticas bien coordinadas recuperaremos nuestra ciudad, antiguamente hermosa.", "Y cuando esto ocurra, podremos iniciar la siguiente etapa de nuestro plan. Con una nación propia y una base de poder en esta región, allanaremos el camino para el Tercer Ejército.\n\n¡Pronto, los Señores de la Legión nos volverán a recompensar con su lluvia de fuego!", "El Consejo fue sabio al nombrarte líder del Despertar de Argus para defender sus estrategias en tierra de humanos y enanos. Y me honra servirte en Alterac.\n\nEn el nombre de Sargeras,\n\nNagaz,\nHeirofante de Argus" } } },
    ["Deepfury's Orders"] = { { ids = { "i4429" }, first = "bumblingfoolsmyplanscall", pages = { "¡Estúpidos inútiles!\n\nMis planes exigían destruir ambos puentes al mismo tiempo. ¿Y qué hacéis vosotros, matones descerebrados? Solo termináis la mitad del trabajo y alertáis a toda la Alianza de nuestras intenciones. ¡Os digo que sois unos necios!\n\nTenéis una oportunidad de reparar vuestras acciones. Hay una reserva de explosivos en Tierras Altas de Arathi, no lejos del puente.\n\n¡Terminad el trabajo si apreciáis vuestras miserables vidas!\n\n--Kam Furiahonda" } } },
    ["Defias Docket"] = { { ids = { "i5947" }, first = "ourfirstplanhasalreadyfa", pages = { "¡Nuestro primer plan ya ha fracasado!\n\nPuño tuvo éxito al cambiar los turnos de los guardias que patrullaban los túneles esa noche, pero debido a movimientos imprevistos de ciertos ciudadanos de Ventormenta, nuestro objetivo pudo escapar del lugar antes de que pudiéramos capturarlo. No obstante, esto ya lo habíamos previsto. El plan B ya estaba en marcha incluso antes de realizar nuestra emboscada en Ventormenta.", "Este plan es igualmente sencillo, pero requiere más paciencia. Ya hemos pagado a nuestro hombre en Menethil por este trabajo y lo ha llevado a cabo de forma brillante. Una vez que hayamos zarpado, no debería existir ningún problema en la captura de nuestro objetivo.", "El ataque está previsto a unos cuantos kilómetros de su destino. Allí es donde nuestros \"aliados\" estarán esperando. No sé por qué nos hemos visto obligados a formar una alianza con las criaturas, pero no dejo de pensar que nos están coaccionando. En última instancia, no importa. ¡Siempre que el objetivo esté bajo nuestra custodia, estaremos un paso más cerca de recuperar Ventormenta de las manos de quienes nos la robaron!" } } },
    ["Defias Script"] = { { ids = { "i6846" }, first = "theplanissetinmotiontake", pages = { "El plan se ha puesto en marcha.\n\nUtiliza como campamento base el que antaño fuera el gran bastión de fe, la Vigilia de los Héroes, y empezaremos a enviarte refuerzos desde los Páramos de Poniente cuando nos mandes un mensaje que indique que ya está preparado.\n\nEl área en cuestión no ha sido olvidada por los ciudadanos y soldados de Ventormenta y debería ser un centro de operaciones perfecto desde el cual realizar nuestros ataques.\n\n¡Los Defias recuperarán Ventormenta!\n\nAguardo tu respuesta." } } },
    ["Diary of Weavil"] = { { ids = { "i21130" }, first = "deardiarytodaymyarchenem", pages = { "Querido diario:\n\nHoy, mi archienemigo Narain Sabelotodo intentó engañarme enviando secuaces a ocupar su lugar en la ejecución. SU ejecución. ¿Te lo puedes creer?\n\n¡Después de todo el trabajo de idear este plan diabólico para sacarlo de esa maldita cabaña, me hace esto! En fin... Estoy demasiado furioso para seguir escribiendo. Volveré luego.", "Querido diario:\n\nSalí de mi escondite hecho una furia tras la última entrada. Vaya si estaba furioso. Decidí rediseñar los uniformes de mis esbirros para que reflejaran mejor mi angustia. Me siento algo mejor, pero falta algo. Vuelvo enseguida...", "Querido diario:\n\nVale, ya estoy bien. He pegado a uno de mis esbirros hasta que lloró como una niña.\n\nMmm... Ahora me siento un poco mal. ¡Un momento! ¡Maldita sea, soy un genio MALVADO! ¡Malvado, entiendes! Qué decepción conmigo mismo. Ahora vuelvo.", "Querido diario:\n\nLe di un abrazo y le dije que siguiera trabajando así de bien. Ahora me siento mejor. Que quede entre nosotros, diario.\n\n¿Por dónde iba? ¡Ah, sí, NARAIN! ¡¡¡ARGH!!! Odio a ese tipo. Al fin y al cabo, fue Narain quien arruinó la curva de notas en todos los exámenes cuando estudiábamos en el Instituto de Ingeniería de Gnomeregan.\n\n¿Conque me suspenden y me expulsan? ¡Por mí, Gnomeregan tuvo lo que merecía!\n\nEso es todo por hoy. ¡Que duermas bien, diario!", "Querido diario:\n\nDebo de estar haciéndome viejo. Había olvidado por completo que te contaba lo de Narain y su engaño. En fin, al ver un señuelo disfrazado de Narain en lugar de Narain, me enfadé tanto que ordené a Número Dos que destruyera al necio.\n\nSubí a mi máquina voladora y empecé a destrozar su precioso, estúpido y memo libro de dracónico. ¡Qué presumido! ¿Quién lee dracónico? ¡Cuánto lo odio!", "Querido diario:\n\nPerdona, me dormí. Así que volaba enfadado y tiraba capítulos de ese libro estúpido. Vi un demonio debajo, en Susurro Oscuro, y decidí convertir el primer capítulo en un tornado mágico de papel que le despedazara el cuerpo en un millón de trozos. Fue liberador. Magia + papel = diversión.\n\nEso me alegró bastante, así que decidí volar a los Reinos del Este. Mi primera parada fue el Núcleo de Magma. ¡Narain siempre hablaba de ese sitio! 'Que si el Núcleo de Magma esto, que si Ragnaros aquello...'", "¿Pues sabes qué? Si tanto le gusta, ¡quizá le guste reconstruir su libro yendo al Núcleo de Magma y resucitando el capítulo de un montón de cenizas! ¡Ja!\n\nYa que estaba por allí, pensé que algunos de esos técnicos babosos del laboratorio del viejo Víctor Nefarius quizá aprovecharan el dracónico. ¡Bombas fuera!", "Esto empezaba a ser una especie de deporte. ¡Le estaba cogiendo el gusto a repartir ese maldito libro!\n\nLas siguientes entregas fueron fáciles.\n\nEntrañas, hogar de los muertos pútridos y fétidos y quizá del mejor chili que he probado, recibió un capítulo. Ventormenta, capital del queso, otro. Diario, ¿alguna vez has puesto queso de Ventormenta en chili de Entrañas? ¿HOLA? Eso debería hacer saltar alguna alarma.", "Ya me estaba cansando, así que di la vuelta a la máquina voladora y volví a casa, pero antes haría dos paradas más. Pasé volando junto a lord Kazzak y sus demonios en Escara Impía (odia que haga eso) y metí otro por la chimenea de Onyxia.\n\nCansado. Me voy a dormir." } } },
    ["Dillinger's Report"] = { { ids = { "i286200" }, first = "scourgehavecontinuedtosl", pages = { "La Plaga ha seguido atravesando tanto El Baluarte como el puesto oriental y sus filas crecen cada día. No alcanzo a comprender cómo se permite que persista semejante fallo en nuestras defensas.\n\nComo señalé en mis informes anteriores, la mísera dotación de guardias de Rémol es insuficiente para lo que nos espera. No es cuestión de si nos arrollarán, sino de cuándo. Y, cuando Rémol caiga, servirá como base perfecta para asediar Entrañas.\n\nNo recomiendo, sino que exijo, el envío de refuerzos desde sus lujosos puestos de Entrañas para resolver la situación mientras aún tenemos oportunidad.\n\n--Guardia de la Muerte Dillinger" } } },
    ["Divined Scroll"] = { { ids = { "i5455" }, first = "anevilforcecreatedtheseh", pages = { "Una fuerza maligna los creó,\nSe sienta cómodamente en la Cima Calígine,\nSe ríe de ti y de tu amigo,\nSus elementales no tienen fin,\n\nPronto deberás enfrentarte a este mago,\nSu furia solo se aplacará con la muerte." } } },
    ["Dorgar Stoenbrow"] = { { ids = { "o175773" }, first = "dorgarstoenbrowwarriorof", pages = { "Dorgar Petrocejas\n\nGuerrero de la Cruzada Escarlata\n\nSeñor de las Cavernas Rojas\n\nVisto por última vez en las Montañas de Alterac" } } },
    ["Dragonmaw Dispatch"] = { { ids = { "i284844" }, first = "findwhatthealliancehaved", pages = { "Averiguad qué ha desenterrado la Alianza. Sabemos lo que hay en estas colinas. Con ello llevaremos un tributo digno a Desgarro.\n\nJefe Nek'rosh" } } },
    ["Ebonlocke's Response to Solomon"] = { { ids = { "i1410" }, first = "yourhonoriregrettoinform", pages = { "Su Señoría:\n\nLamento informaros que en estos momentos, la Guardia Nocturna no puede abandonar su posición en Villa Oscura. Tal vez no os han informado que Ventormenta ya no presta apoyo militar en esta región. La Guardia Nocturna está formada en su totalidad por los habitantes del bosque para defender Villa Oscura en ausencia de Ventormenta. Sin la Guardia Nocturna, la ciudad sucumbiría. Os deseo suerte en vuestra crisis.\n\nSeñor Ello Ebonlocke" } } },
    ["Eliza's Tombstone"] = { { ids = { "o37" }, first = "elizabelovedwifemaytheea", pages = { "Eliza\n\nAmada esposa, que la tierra sacie tu apetito." } } },
    ["Empires' Fall"] = { { ids = { "o175855" }, first = "asidefromtheirshadowyori", pages = { "Aparte de sus orígenes oscuros, resulta obvio que los elfos de la noche obtuvieron el poder poco después de su descubrimiento del Pozo de la Eternidad. A pesar de los intentos de los trols de impedir que aumentaran sus territorios, los elfos de la noche construyeron un poderoso imperio que se expandió rápidamente a lo largo del Kalimdor primordial. Utilizando artes de magia nunca antes imaginada por los supersticiosos trols, los elfos de la noche lograron fácilmente aquello que los malvados aqir nunca pudieron conseguir: derrotar a los dos imperios más importantes del mundo.", "Sistemáticamente, los elfos de la noche desmantelaron las defensas y las líneas de abastecimiento de los trols. Los trols, incapaces de contrarrestar la magia destructiva de los elfos, se replegaron ante las arremetidas. Los elfos de la noche demostraron ser tan astutos y sanguinarios como los salvajes trols: provocando el eterno odio y el desdén racial de estos últimos. Transcurridos pocos años, los imperios Gurubashi y Amani se fragmentaron.", "Finalmente, los elfos de la noche fueron quemados por los fuegos arcanos que habían intentado controlar. El uso constante que hacían de la magia atrajo al mundo a la demoníaca Legión Ardiente. Los demonios destrozaron una gran parte de la civilización de los elfos de la noche. Aunque no hay registros que indiquen que la Legión atacó a la civilización trol, es muy probable que se produjeran batallas en todo el continente.", "Al finalizar el terrible conflicto, conocido como la Guerra de los Ancestros, el Pozo de la Eternidad implosionó. La onda expansiva resultante destrozó la mayor parte de la tierra de Kalimdor. El centro del continente quedó sumergido bajo el mar, dejando atrás numerosos continentes fragmentados.", "Así, grandes porciones tanto del Imperio Amani como Gurubashi existen aún en las actuales tierras de Quel'Thalas y Tuercespina, respectivamente. Los reinos Azj'Aqir de Azjol-Nerub y Ahn'Qiraj también han sobrevivido hasta el presente en Rasganorte y Tanaris, respectivamente.\n\nAmbas civilizaciones trol retrocedieron debido a la gran destrucción del mundo primordial que habían conocido. Los intrépidos trols reconstruyeron sus devastadas ciudades y progresaron para recuperar parte de su antiguo esplendor." } } },
    ["Encrypted Letter"] = { { ids = { "i9555" }, first = "neverbeenmoreproudtobepa", pages = { "Nunca he sentido tanto orgullo de pertenecer al oficio como en estos últimos años. Jamás ha habido tanta necesidad de asesinos, espías y exploradores. Pensarías que habría más demanda en tiempos de guerra, pero, sorprendentemente, no prosperamos tanto durante la guerra como ahora, cuando la paz empieza a deteriorarse.\n\nMe dijeron que estarías por aquí para aprender algunas cosas. Cuando tengas tiempo, ven a verme junto a los establos de detrás de la abadía.\n\n-Jorik Kerridan, instructor de pícaros" } } },
    ["Encrypted Memorandum"] = { { ids = { "i9558" }, first = "youwereexpectingthistobe", pages = { "Apuesto a que esperabas que esta fuera una nota normal escrita por tu rey o por cualquier otra persona. Bueno, digamos que algo sé acerca de cómo forjar notas y quería asegurarme de que recibieras esta. No puedo ir llamando la atención, ¿verdad?\n\nMe he refugiado en Yunquemar, así que me encontrarás cerca de la fosa de lava. Cuando estés $gpreparado:preparada;, ven a hablar conmigo. Solo quiero presentarme ahora que tenemos tiempo.\n\nSolm Hargrin, instructor de pícaros" } } },
    ["Encrypted Parchment"] = { { ids = { "i9560" }, first = "isendgreetingsiwaslostin", pages = { "Te envío mis saludos, $N. Estaba absorto en mis pensamientos cuando reparé en que tenía que escribirte.\n\nMuchos en nuestra cultura alaban a los chamanes como dirigentes espirituales, igual que nuestro gran Jefe de Guerra. Otros creen que la espada y el hacha son ocupaciones aún más nobles. Pero nunca olvides que las batallas, incluso las guerras, se ganan gracias a quienes tienen habilidades más especializadas. De eso quiero hablarte, $N. Búscame en lo profundo del Cubil del Valle de los Retos.\n\n-Rwag, instructor de pícaros" } } },
    ["Encrypted Rune"] = { { ids = { "i9550" }, first = "brothersisterihopethisru", pages = { "$gHermano:Hermana;, espero que esta runa te encuentre bien. Quería dedicar un momento a decirte que estoy dentro de Yunquemar, sobre el Valle de Crestanevada.\n\nSé lo importante que es mantenernos unidos. En estos tiempos de paz tensa es aún más importante tener cerca a los nuestros. Búscame cuando tengas tiempo.\n\n-Solm Hargrin, instructor de pícaros" } } },
    ["Encrypted Scroll"] = { { ids = { "i9559" }, first = "takecarenottoignoremywor", pages = { "No tomes mis palabras a la ligera, $N. Ha llegado la hora de llevar nuestras artimañas de engaño a todas las naciones… incluso a nuestra grandiosa Entrañas. Todos los fieles de Sylvanas se esfuerzan por crear un área nueva bajo el control exclusivo de los Renegados. Incluso aunque no poseamos habilidades mágicas, nuestro papel sigue siendo igual de importante.\n\nVen a verme a la posada de Camposanto y seguiremos hablando.\n\n-David Trias, intructor de pícaros" } } },
    ["Encrypted Sigil"] = { { ids = { "i9551" }, first = "saelahmyfriendihopethiss", pages = { "Sael'ah, espero que cuando recibas este sigilo te encuentres bien. Me han pedido que te ofrezca mis servicios. También estoy en Cañada Umbría, en el gran árbol de Aldrassil, y deseaba comunicarte que si necesitas instrucción, no tienes más que pedírmela.\n\nEn estos tiempos tan cuestionables, creo que es prudente que aquellos que actúan furtivamente permanezcan unidos. ¿Qué otro ser sería capaz de proteger Teldrassil y nuestros caminos?\n\nCuando puedas, ven a verme.\n\nFrahun Sombrusurro, instructor de pícaros" } } },
    ["Encrypted Tablet"] = { { ids = { "i9554" }, first = "greetingsbrothersisterth", pages = { "Saludos, $ghermano:hermana;. Los Mano Destrozada te saludamos y esperamos que este valle sea un lugar agradable en el que puedas desarrollar tus negocios. Es un periodo de prueba para ti, así que no pienses que no te estamos vigilando constantemente.\n\nEs mi deber evaluar tus habilidades y luego informar sobre el momento en que crea que estás preparado para aceptar retos mayores.\n\nCuando estés $gpreparado:preparada;, localízame en las profundidades de El Cubil. Te estaré esperando.\n\nRwag, instructor de pícaros" } } },
    ["Etched Note"] = { { ids = { "o174746" }, first = "thisanvilisthepropertyof", pages = { "Este yunque es propiedad de Jordan Fontana. ¡NO lo utilicéis!\n\nJordan" } }, { ids = { "i9565" }, first = "mightywarriorsdefendourh", pages = { "Poderosos guerreros defienden nuestro hogar. Nuestros chamanes guían nuestros espíritus y nos muestran el pasado de nuestros antepasados. Y nuestros druidas nos ayudan a descubrir la voluntad de la Madre Tierra.\n\nPero tú eres uno de nuestros cazadores. Los cazadores aprenden muchos aspectos de esas funciones y los combinan. Descubrirás que representas el corazón de nuestro pueblo: algunos buscarán en ti orientación, otros protección. Es mi deber asegurarme de que estés a la altura. Búscame en el Campamento Narache.\n\n-Lanka Tirolejano, instructora de cazadores" } } },
    ["Etched Parchment"] = { { ids = { "i9553" }, first = "yabeingoodhandsnowmonjen", pages = { "Tú estas en buenas manos, colega. Jen'shan sabe que quieres conocer los trucos del cazador y está preparada para enseñarte... si estás $gpreparado:preparada; para escuchar.\n\nVen a buscarme en el Valle de los Retos. Jen'shan empezará a instruirte y a mostrarte lo poderosas que pueden llegar a ser las artes de la caza.\n\nJen'shan, instructora de cazadores" } } },
    ["Etched Rune"] = { { ids = { "i9566" }, first = "tamerofbeastsmastermarsk", pages = { "$gDomador:domadora; de bestias, $gmaestro:maestra; de la puntería, $gprobado rastreador:probada rastreadora;: ¿qué más quieres ser en esta vida? Estos dones implican inteligencia y grandes dosis de paciencia.\n\nLa vida del cazador no es fácil, tenlo por seguro. Si quieres ser tan bueno como incluso el peor de nuestros tiradores, tendrás que entrenarte a conciencia. Pero esa es la razón por la que estoy aquí.\n\nBúscame en Yunquemar, frente al Valle de Crestanevada. Te estaré esperando.\n\nThorgas Grimson, instructor de cazadores" } } },
    ["Etched Sigil"] = { { ids = { "i9567" }, first = "eluneiswithyouthewindwhi", pages = { "Elune está contigo, $N. El viento me lo ha susurrado y estoy $gcontento:contenta; de poder tomar parte directamente en la formación de nuestra próxima generación de cazadores.\n\nSegún me han dicho, estás cerca de Aldrassil. Cuando tengas tiempo, nos reuniremos en el gran árbol.\n\nNuestros mayores me han pedido que me asegure de que nuestros nuevos cazadores reciban la instrucción necesaria para hacer frente a los retos que tienen por delante. Eres uno de los estudiantes que se ha incorporado más recientemente, de manera que es inexcusable que me visites. Hasta entonces, que te vaya bien.\n\nAyanna Semprerguida, $ginstructor:instructora; de cazadores" } } },
    ["Etched Tablet"] = { { ids = { "i9564" }, first = "itbegoodtohearthatoneofj", pages = { "Es bueno saber que $gun hermano:una hermana; de Jen'shan ha venido al valle para probar su destreza. ¡Jen'shan espera con impaciencia!\n\nNo tengo que decirte que eres $gun cazador:una cazadora; fuerte y $gastuto:astuta;: tú ya lo sabes. A Jen'shan le corresponde la tarea de lograr que seas más fuerte y más $gastuto:astuta;.\n\nEncontrarás a Jen'shan en el Valle de los Retos. Ella te enseñará lo que tienes que saber. Entre otras cosas, te enseñará a domesticar a las bestias más temibles.\n\nJen'shan, instructora de cazadores" } } },
    ["Exile of the High Elves"] = { { ids = { "o175731" }, first = "asthecenturiespassedthen", pages = { "Con el transcurso de los siglos, la nueva sociedad de los elfos de la noche se fortaleció y se expandió por el bosque en ciernes conocido como Vallefresno. Muchas de las criaturas y especies que abundaban antes del Gran Diluvio, como los furbolgs y los jabaespines, reaparecieron y prosperaron en aquellas tierras. Bajo la benévola mirada de los druidas, los elfos de la noche disfrutaron de una era de paz y tranquilidad sin precedentes bajo las estrellas.", "No obstante, muchos de los altonatos supervivientes estaban cada vez más inquietos. Al igual que Illidan, tuvieron que retirarse ante la pérdida de sus codiciados poderes. Se vieron tentados a extraer las energías del Pozo de la Eternidad y reiniciar sus prácticas en el terreno de la magia. Dath'Remar, el extrovertido líder de los altonatos, empezó a burlarse abiertamente de los druidas, llamándolos cobardes por negarse a utilizar la magia que consideraban suya por derecho.", "Malfurión y los druidas hicieron caso omiso a los argumentos de Dath'Remar y advirtieron a los altonatos que cualquier uso de la magia sería castigado con la muerte. En un insolente y desventurado intento de convencer a los druidas de revocar sus leyes, Dath'Remar y sus seguidores desataron una terrible tormenta mágica sobre Vallefresno.", "Los druidas no podían soportar la idea de ver morir a los suyos, por lo que decidieron desterrar a los insensatos altonatos de sus tierras. Dath'Remar y sus seguidores, satisfechos por librarse al fin de sus primos conservadores, embarcó en varios navíos especialmente diseñados y se fue a recorrer los mares. Si bien ninguno de ellos sabía lo que les aguardaba al otro lado de las aguas de la tempestuosa Vorágine, deseaban fundar un nuevo territorio en donde poner en práctica sus codiciados poderes con total impunidad.", "Los altonatos o Quel'dorei, como Azshara los había llamado en épocas pasadas, desembarcaron en la tierra del este llamada Lordaeron por sus habitantes. Planearon construir allí su propio reino mágico llamado Quel'Thalas, rechazando los preceptos de los elfos de la noche que los hacía venerar a la luna y a desarrollar actividades nocturnas. De ahí en adelante, adoraron al sol y se llamaron a sí mismos altos elfos." } } },
    ["Extended Annals of Darrowshire"] = { { ids = { "i13202" }, first = "theannalsofdarrowshireda", pages = { "Los anales de Villa Darrow\n\nVilla Darrow, nombrada así por el lago Darrowmere, situado al oeste, es una ciudad que se encuentra entre las estribaciones sureñas de Lordaeron. Conocida por sus humildes pero trabajadores residentes, Villa Darrow permaneció en segundo plano en la historia de Lordaeron hasta la Segunda Guerra.\n\nLos héroes se forjaron durante la guerra. Y allí perecieron.", "La Batalla de Villa Darrow\n\nLa Batalla de Villa Darrow tuvo lugar en mitad de la Segunda Guerra, cuando las fuerzas de la Plaga arrasaron Lordaeron. Villa Darrow quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por un cuerpo de tropas, un contingente de paladines Mano de Plata y un incondicional grupo de milicia local dirigido por el capitán Joseph Rutagrana.", "Los primeros asaltos de la Plaga sobre Villa Darrow fueron espaciados. Pequeños grupos de esqueletos y cadáveres merodeadores anduvieron por las afueras de la ciudad y fueron repelidos fácilmente.\n\nPero la Plaga percibió la tenacidad de los defensores y respondió adecuadamente. Poco después de producirse la primera ola de atacantes, apareció una segunda. Necrófagos campeones, sirvientes del señor necrófago Horgus, aullaron desde las colinas y chocaron con los asediados defensores de Villa Darrow.", "Los defensores quedaron debilitados, pero fueron liberados por paladines, discípulos de los Mano de plata. Su líder, Davil Vasiján, había nacido en Villa Darrow. Condujo a sus seguidores a la ciudad cuando supo del inminente ataque y, junto con los defensores, rechazaron a los siervos de Horgus.\n\nCuando el propio Horgus entró en batalla, se encontró con Davil. Lucharon durante varios minutos y, finalmente, Davil venció, pero sufrió una herida mortal y, poco después de derrotar al señor necrófago, murió.", "La batalla continuó y el capitán Rutagrana dirigió a su milicia valientemente. Habrían podido ganar, si el oscuro caballero de la muerte Marduk el Negro no hubiera corrompido al capitán.\n\nEn medio de la refriega, Marduk se acercó a Rutagrana y, con ayuda de la magia negra, liberó el espíritu de este, convirtiéndolo en una sombra maligna del valiente capitán.", "Luego, el corrupto capitán Rutagrana esparció su influencia maligna entre los defensores de Villa Darrow, que traicionaron a sus aliados y los asesinaron. A continuación, volvieron a la ciudad de Villa Darrow y mataron a todos aquellos que estaban ocultos en sus casas.\n\nEl ejército restante de la Plaga, junto con el espíritu corrupto del capitán Rutagrana, abandonó posteriormente la devastada ciudad de Villa Darrow y arremetió contra Lordaeron, provocando el dolor y la muerte de la Segunda Guerra.", "El destino de Horgus el Devastador\n\nHorgus el Devastador cayó en la Batalla de Villa Darrow. Pero el mal que residía en él no se consumió del todo. Las fuerzas victoriosas de la Plaga trasladaron su cráneo desde el campo de batalla de Villa Darrow y lo llevaron con ellos para sembrar el terror entre todos los seres vivientes que encontraron.\n\nDías después, la compañía de la Plaga que poseía el cráneo fue derrotada por los paladines de la Mano de Plata. El cráneo de Horgus fue lanzado al lago Bosque Negro.", "El destino de Marduk el Negro\n\nMarduk sobrevivió a la Segunda Guerra, provocando mucho sufrimiento y muerte con su nauseabunda espada de runas. Aunque Marduk continúa con vida, su espada se perdió en una batalla cerca del Cruce de Corin. Un capitán enano hizo añicos la espada en su escudo encantado, obligando a Marduk a abandonar el campo, ganando la partida para la Alianza.\n\nLa espada de Marduk se hundió en la tierra y la corrompió, creando un desfiladero conocido hoy con el nombre de la Cicatriz Purulenta.", "El destino de Davil Forjaluz\n\nDavil Forjaluz murió en la Batalla de Villa Darrow, pero su valentía inspiró a la Alianza durante toda la guerra.\n\nSu libro, el tratado del paladín, fue recuperado por las tropas de la Cruzada Escarlata. Actualmente, permanece en el concejo de la Vega del Amparo, controlada por la Cruzada Escarlata, donde lo consultan los cruzados que desean inspirarse en la fuerza de Davil.", "El destino de Joseph Rutagrana\n\nJoseph Rutagrana murió durante la Batalla de Villa Darrow. Su espíritu se corrompió y tomó una nueva forma, extendiendo el mal por Lordaeron.\n\nEn la Gangrena de Gahrron, al este de Andorhal, el corrupto Rutagrana fue finalmente derrotado por las fuerzas de la Alianza. Su escudo aún descansa cerca del granero de la granja apestada y los esbirros de la Plaga aún evocan el recuerdo de este ser diabólico.", "El destino de Carlin Rutagrana\n\nHermano del capitán Joseph Rutagrana, Carlin cayó durante la Batalla de Villa Darrow. Pero, aunque resultó terriblemente herido, no murió.\n\nDías después de la batalla, agentes del Alba Argenta encontraron a Carlin vagando, debilitado por la sed y la fiebre, cerca del Cruce de Corin. Curaron sus heridas y lo llevaron a la Capilla de la Esperanza de la Luz.\n\nAgradecido por su caridad, Carlin se unió a las filas del Alba Argenta y ahora libra una batalla de venganza contra la Plaga." } } },
    ["Faded Photograph"] = { { ids = { "i11108" }, first = "", pages = { "" } } },
    ["Fel Tracker Owner's Manual"] = { { ids = { "i10832" }, first = "theconjuringofthebeastto", pages = { "Los conjuros de la bestia:\n\nPara conjurar al rastreador manáfago, deberás usar el Orbe de inferi.\n\nNotas:\n\nEl rastreador manáfago solo permanecerá como entidad en este mundo durante treinta minutos.\n\nEl rastreador manáfago mágico solo te ayudará a encontrar formaciones de azsharita.\n\nEl rastreador manáfago mágico NO hará lo siguiente: Trucos, atacar, ayudar, bailar, destruir seres arcanos.\n\nSiguiente página...", "El control de la bestia:\n\nLos rastreadores manáfagos solo responden a los gruñidos de la bestia. Para que tu rastreador manáfago rastree formaciones de azsharita, ¡deberás rugirle con fuerza! (Apunta al rastreador manáfago y /rugir).\n\nCuando un rastreador manáfago encuentra una formación, corre velozmente hacia ella, sin tener en cuenta los seres que lo rodean. Si bien no resulta necesario proteger al rastreador, tal vez convenga estar cerca de él para que no se pierda.", "Pérdida de la bestia:\n\nTranscurridos treinta minutos, la bestia regresará a su hogar en el Vacío Abisal.\n\nNota:\n\nEn su afán, la bestia PODRÍA caer por el acantilado o rodar por la ladera de una montaña. No lamentes la pérdida de un rastreador manáfago, mejor invoca a otro." } } },
    ["Fellari Swiftarrow"] = { { ids = { "o175774" }, first = "fellariswiftarrowrangerc", pages = { "Harthal Vistarreal\nSeñor Paladín de la Cruzada Escarlata\nCiudadano de Azeroth, caballero de la Mano de Plata\nVisto por última vez entrando en la ciudad maldita de Stratholme" } } },
    ["Ferren Marcus"] = { { ids = { "o175775" }, first = "ferrenmarcushighabbotoft", pages = { "Ferren Marcus\n\nAlto abad del Monasterio Escarlata\n\nCiudadano de Stratholme\n\nMuerto defendiendo el Monasterio Escarlata durante el primer Asalto del Solsticio" } } },
    ["Field Guide"] = { { ids = { "i213563" }, first = "arbortarantulaorderarane", pages = { "Arbor Tarantula\n\nOrden: Araneae\nClima: tropical\n\nConstruye nidos dentro de madera muerta y podrida. Suele encontrarse cerca de las talas, pues busca excavar en los tocones recién cortados.", "Flesh Picker\n\nOrden: Scorpiones\nClima: árido\n\nComo indica su nombre, este escórpido arranca y come la carne de los huesos de otros animales. Es carroñero y prefiere alimentarse de cadáveres grandes.", "Hay Weevil\n\nOrden: Coleoptera\nClima: templado\n\nUna amenaza enorme en un caparazón diminuto. Un solo gorgojo puede comerse una bala de heno en menos de una hora. Las plagas son raras, pero suelen registrarse en el norte de los Reinos del Este." } } },
    ["Final Clue to Sander's Treasure"] = { { ids = { "i1362" }, first = "nowthatyefoundmeolwhiske", pages = { "¡Ahora que has encontrado la vieja jarra de whisky, estás a punto de dar con el tesoro! Mira hacia el oeste desde ahí y camina hasta llegar a la costa. Cuando hayas llegado al agua, ¡no te detengas! ¡Nada hacia el oeste hasta que encuentres la isla con mi arqueta!" } } },
    ["Fishing Tournament!"] = { { ids = { "i19978" }, first = "stranglethornfishingtour", pages = { "¡Torneo de pesca de Tuercespina!\nDomingo por la tarde de las 14.00 a las 16.00.\n\nPesca en cualquier punto situado en la costa de Tuercespina (exceptuando la Bahía del Botín) y fíjate en los cardúmenes de pezrico que aparecerán a lo largo de la costa. Asegúrate de que tu boya de pesca cae en medio del cardumen y, en lugar de pescar la variedad habitual de Tuercespina, obtendrás un pez especial. ¡La primera persona que capture cuarenta pezricos puede pedir al maestro de pesca Anzuelo, que está en la Bahía del Botín, que se los cambie por un premio!\n\nIncluso si no eres la primera persona que capture los cuarenta pezricos, aún puedes cambiarlos por dinero en efectivo. Además, aquellos que pesquen otras variedades especiales ¡también recibirán premios!" } } },
    ["Fizzle Brassbolts' Letter"] = { { ids = { "i5827" }, first = "goodmartekiminajamandine", pages = { "Mi buen Martek:\n\nEstoy en un problema y necesito tu ayuda.\n\nMi hermano y yo estamos intentando organizar una carrera de coches y necesitamos pistones robustos. Nada de lo que hemos probado es lo suficientemente resistente. Nada soporta la velocidad de nuestro nuevo coche. De esta manera, ¡el motor se rompe constantemente!\n\nEres un gran experto trabajando el metal. Debes ayudarnos. Eres el único que puede hacerlo.", "Estas son las especificaciones del pistón:\n\nLongitud: 32 EB\nAncho: 12 EB\nPeso: 23,5 GD a 25,5 GD\nConducción: 70 RDP\nFuerza de corte: 98 o superior\nTasa de combobulación: \"Superfuerte\" o superior\n\nEn caso de que hayas olvidado las medidas gnómicas:\nEB = \"Extensión de los bigotes\"\nGD = \"Gramos diminutos\"\nRDP = \"Rizos de los dedos de los pies\"" } } },
    ["Fizzlefuse's Shopping List"] = { { ids = { "i239246" }, first = "dearfuturemedontforgetth", pages = { "Querido yo del futuro: no olvides el pan esta vez.\n\n- 2 galones de leche fría como el hielo\n- 20 cuñas de cheddar bien curado (las ratas se lo comen todo)\n- 1 delicioso pastel de chocolate\n- En realidad, mejor 2 pasteles\n- 4 peligros de combustible de cohete goblin\n- 2 tubos de torio\n- 1 transformador de veraplata\n- <la escritura está emborronada e ilegible>\n- 2 girocronátomos" } } },
    ["Folded Parchment"] = { { ids = { "i282420" }, first = "greetingssincetheelement", pages = { "Saludos, $N:\n\nDesde que desaparecieron los espíritus elementales del viento, Zephras está al borde de un precipicio mortal. Las aves, las bestias e incluso las raíces bajo nuestros pies nos piden ayuda.\n\nBúscame en la planta baja del gran árbol de Thendal. Te aconsejaré e instruiré en las artes druídicas.\n\n-Xyton Ventargento, instructor de druidas" } } },
    ["Fool's Stout Report"] = { { ids = { "i5807" }, first = "mrfizzlebubthebeverageyo", pages = { "Sr. Pinchabujas:\n\nLa bebida que entregaste a mi socio ha tenido un gran éxito. No solo se trata de una bebida fuerte, que adormece los sentidos, sino que parece tener cierta cualidad adictiva. Estoy seguro de que los que la han probado querrán repetir.\n\nEstamos en deuda contigo, Loquillo.\n\nTe invito a venir al Desierto de Sal, o a alguien de tu confianza, para aprovechar las nuevas oportunidades en relación con el juego.\n\nKravel" } } },
    ["For the Light!"] = { { ids = { "i20009" }, first = "hisnamebroughtlighttodar", pages = { "Su nombre llevó Luz a Azeroth más oscuro.\n\nSu valor derribó los muros del dolor.\n\nJamás haría la Mano de Plata mayor bien\n\nque dar al mundo al caballero que se entregaría a él.", "No buscaba acrecentar su fama\n\nni ejercer señorío sobre los suyos.\n\nEligió, en cambio, luchar por Lordaeron\n\ncon la esperanza de que su pueblo no luchara más.", "La trágica historia de este caballero sagrado\n\nno acabará jamás con su muerte impía.\n\n¡Lo honramos y le damos las gracias!\n\n¡Uther conocerá siempre gloria y Luz!" } } },
    ["Foreboding Plans"] = { { ids = { "i3718" }, first = "theywouldhavelifeeternal", pages = { "L. F. ordenó incrementar la agresión contra los tontos de la Alianza. A continuación, ha un listado de los materiales necesarios para una importante misión contra Costasur:\n\nraciones de viaje de 1 semana para 20 hombres\n20 trajes de noche de color negro\n20 pares de zapatos nuevos\n25 espadas nuevas\n30 cuchillos para lanzar\n20 máscaras negras\n10 viales de aceite inflamatorio\n50 dosis de veneno paralizante\n5 uniformes de guardias de Costasur robados, si están disponibles\n100 monedas de plata\n\nBaron V.\nIntendente" } } },
    ["Forestlord and the first Druids"] = { { ids = { "o177205" }, first = "intimethechildcenariusgr", pages = { "Con el tiempo, el niño, Cenarius, alcanzó la estatura de su orgulloso padre. Hermano de los árboles y las estrellas, el gran cazador recorrió los lugares remotos del mundo cantando las armoniosas canciones del alba. Todas las criaturas se inclinaban ante su gracia y belleza: ninguna era tan astuta como el hijo de la luna y el ciervo blanco.", "Con el tiempo, Cenarius trabó amistad con los shu'halo y les habló del mundo cambiante. Los hijos de la tierra lo conocieron como hermano y juraron ayudarlo a cuidar los campos de la vida y las criaturas predilectas de su gran Madre Tierra.", "Cenarius enseñó a los hijos de la tierra a hablar con árboles y plantas. Los shu'halo se convirtieron en druidas y realizaron grandes proezas mágicas para sanar la tierra. Durante muchas generaciones cazaron con Cenarius y protegieron al mundo de las sombras que se agitaban debajo." } } },
    ["Fossilized Egg"] = { { ids = { "o175680" }, first = "foundintheswelteringwast", pages = { "Hallado en los sofocantes restos del desierto de Tanaris, este peculiar huevo sigue siendo un misterio para los ecologistas modernos. Las pruebas sugieren que el huevo podría tener hasta mil años de antigüedad. Si bien ciertos elementos indican estructuras insectoides, no resulta posible determinar sus verdaderos orígenes. Las especies que pusieron huevos tan distintos siguen sin conocerse." } } },
    ["From the Desk of Lord Victor Nefarius"] = { { ids = { "i21142" }, first = "towhomitmayconcernhowilo", pages = { "A quien corresponda:\n\nCuánto me gustan estos juegos nuestros.\n\nSolo puedo suponer que, si lees esta carta, de algún modo, por milagro o intervención divina, has logrado vencerme. Absurdo, lo sé, pero cosas más extrañas han ocurrido en la historia de este mundo.", "Como todo en la vida, esta triste historia tiene un glorioso lado bueno de tragedia, caos y maldad. Aunque me has matado, lo has hecho de forma tan lenta y desordenada que he tenido tiempo de escribir esta carta DESPUÉS de destruir tu única esperanza de salvar este mundo. El polvo de cristal rojo triturado es todo lo que queda de tu fragmento de cetro.", "Disfruta de las armaduras de Némesis y Tempestira que puedas encontrar en mi tesoro. Créeme cuando te digo que me produce un gran placer saber que hice lo que mi padre no pudo...\n\nAtentamente,\n\nLord Víctor Nefarius\n\"Nefarian\"" } } },
    ["Furen's Instructions"] = { { ids = { "i6842" }, first = "inthefollowingpagesyoull", pages = { "En las páginas siguientes, encontrarás un listado con todo el material necesario para fabricar una armadura templada al fuego. Buena suerte, guerrero.\n\nFuren Barbalarga", "Colmillos de araña abrasados:\n\nEl mineral de incendicita que se encuentra en una cueva situada en las inmediaciones de Roca Thelgen ha abrasado a las arañas que allí habitan.\n\nEl veneno de sus colmillos hierve y hace reacción con los propios colmillos, dando lugar a una sustancia muy resistente.", "Cuernos carbonizados:\n\nAl igual que los colmillos de araña quemados, los cuernos carbonizados de las quimeras que habitan en la Vega Carbonizada, en la Cima del Espolón de Kalimdor, poseen cualidades muy apreciadas.\n\nTras ser aplanadas a golpes y tratadas, se vuelven extremadamente resistentes a la tensión física.", "Cuerno galvanizado:\n\nLa dureza del escaso cuerno galvanizado es la clave fundamental de la armadura que voy a crear, así que es preciso conseguirlo.\n\nSe puede obtener de la también escasa quimera matriarca que habita en la Vega Carbonizada.", "Vial de flogisto:\n\nLa última fase de la creación e la armadura requiere una forja a temperaturas extremas. Para obtener la temperatura necesaria, necesito un vial de flogisto.\n\nEl único fabricante de esta sustancia es el legendario jabaespín Roogug, y no te la dará sin antes luchar. Roogug habita en el Horado Rajacieno, en el sur de los Baldíos." } } },
    ["Furlbrow's Deed"] = { { ids = { "i1971" }, first = "thisisadeedtoanexpanseof", pages = { "Estas son las escrituras de un terreno en la región de los Páramos de Poniente. Otorga a los firmantes derechos de propiedad sobre el área en cuestión, así como sobre todos los objetos fabricados y todas las estructuras construidas dentro de sus fronteras.\n\nFirman este documento:\n\n Theodore Furlbrow\n Verna Furlbrow", "[Las palabras que aparecen a continuación fueron garabateadas en la otra cara de las escrituras]\n\nPresionamos a Furlbrow y conseguimos estas escrituras. Pensé que, si quieres falsificar una para ti, te vendría bien. Los Furlbrow no nos darán problemas. La última vez que los vi, abandonaban los Páramos de Poniente con un carro roto." } } },
    ["General Turalyon"] = { { ids = { "o25330" }, first = "generalturalyonformerlie", pages = { "General Turalyon\n\nAntiguo teniente de Lord Anduin Lothar. Caballero de la orden de la Mano de Plata. Alto general de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido.\n\n\"Esarus thar no'Darador' - Servimos por la sangre y el honor.\nViejo amigo, fuiste la mano derecha de la justicia y la virtud. Honraremos tu nombre en nuestras salas… por siempre.\"\n\n- Lord Uther el Iluminado, Caballero de la orden de la Mano de Plata" } } },
    ["Geru Strider"] = { { ids = { "o175682" }, first = "thelargestoftheplainstri", pages = { "Los Geru, los mayores de los zancudos, son escasos y rara vez se los encuentra." } } },
    ["Glowing Recall Crystal"] = { { ids = { "i282416" }, first = "thehighorderhasbeenwatch", pages = { "<Al tocar el cristal brillante, una corriente de aire se arremolina a tu alrededor y trae un tenue indicio de palabras.>\n\nLa Orden Eminente te ha observado, $N, y ve un gran porvenir en tus habilidades.\n\nLos espíritus del viento han abandonado la Isla de Zephras. Ahora más que nunca hacen falta magos prometedores como tú. Si nuestro pueblo quiere valerse por sí mismo y sobrevivir a esta crisis, debemos usar nuestros conocimientos arcanos para descubrir los secretos de este reino.\n\nBúscame en Thendal, en la planta baja del gran árbol. Comenzaremos tu instrucción en serio.\n\n-Dorii Susurro Brillante, instructora de magos" } } },
    ["Glyphic Letter"] = { { ids = { "i9571" }, first = "therearefourrulestomagic", pages = { "La magia tiene cuatro reglas:\n\n La Magia es poderosa.\n La magia corrompe.\n La magia es adictiva.\n La magia acerca a los moradores del Vacío Abisal a aquellos que empuñan lo arcano.\n\nEstas reglas son siempre seguras. Si decides continuar tu camino como mago, gobernarán tu destino.\n\nSi eres tan $giluso:ilusa; como para ignorar esta advertencia, ven nuevamente a hablar conmigo en el ala de la biblioteca de la abadía de Rasganorte. Te esperaré arriba.\n\nKhelden Bremen, instructor de magos" } } },
    ["Glyphic Memorandum"] = { { ids = { "i9573" }, first = "tonewstudentsofthearcane", pages = { "A: Los nuevos estudiantes de las artes arcanas:\nSe os pide que marchéis y estudiéis con el gnomo Marryk Nurribit, hasta que llegue el momento de que se os llame para que ayudéis a nuestro pueblo a reasentarse en una nueva morada. Os pido que os preparéis sin miedo alguno a someteros a pruebas muy rigurosas y a un proceso de aclimatación muy complejo cuando os acomodéis y/o desarrolléis cualquier tipo de relación social con los habitantes locales.\n\nTodos los asuntos relacionados con vuestros deberes y facultades deberán dirigirse a Marrek Nurribit." } } },
    ["Glyphic Parchment"] = { { ids = { "i282380" }, first = "youseewhatotherorcscanno", pages = { "Tú ves lo que otros orcos no ven, sientes el pulso del universo a tu alrededor. Tienes el don de la magia y ha llegado la hora de aprender a controlarlo.\n\nBusca a Mai'ah cuando estés listo. Ella te enseñará mucho de magia y los hechizos que necesitas para destruir a quienes se enfrenten a ti.\n\nMai'ah está cerca del Cubil del Valle de los Retos. Ven, encuéntrala y serás fuerte. Después mostrarás a los otros magos cómo la magia se dobla a tu voluntad... y no al revés." } } },
    ["Glyphic Scroll"] = { { ids = { "i9574" }, first = "thecorruptionandevilthat", pages = { "La corrupción y el mal que, según los rumores, acompañan a lo arcano no son nada comparados con el dolor que ya hemos sentido. Ya no somos víctimas, $N. Somos quienes controlan su destino. Sylvanas nos ha abierto el camino: ha demostrado que nuestra voluntad es nuestra, que ya no somos esclavos de ese bastardo de Arthas.\n\nBúscame en la iglesia y te instruiré más... si ese es tu deseo.\n\n- Isabella, instructora de magos" } } },
    ["Glyphic Tablet"] = { { ids = { "i9575" }, first = "welcometoyourawakeningmo", pages = { "Bienvenido a tu despertar, colega. Los secretos de lo arcano están a tu alcance si tienes fuerza para aferrarte a ellos.\n\nBusca a Mai'ah cuando estés listo. Ella te enseñará mucho de magia y los hechizos que necesitas para destruir a quienes se enfrenten a ti.\n\nMai'ah está cerca del Cubil del Valle de los Retos. Ven, encuéntrala y serás fuerte. Después mostrarás a los otros magos cómo la magia se dobla a tu voluntad... y no al revés." } } },
    ["Goblin Rumors"] = { { ids = { "i5804" }, first = "thegoblinnazzsteamboilis", pages = { "El goblin Nazz Vaporio es realmente el hijo de un príncipe mercante goblin (¿Qué príncipe? El precio de esta información es alto).\n\nParece que le gusta mucho más gastar el dinero que ha hecho su familia que ganarlo por sí mismo. Así que ha robado una pequeña fortuna del tesoro familiar y ahora se oculta en el Desierto de Sal.\n\nSi su padre supiera dónde está, seguro que iría a buscarlo y lo volvería a llevar a casa... castigándolo por su insolencia." } } },
    ["Goodsteel Ledger"] = { { ids = { "i11727" }, first = "greetingsandsalutationsa", pages = { "¡Saludos, $gaventureros:aventureras;!\n\nYo, Krinkle Buenacero, necesito gente dispuesta a arriesgarse para realizar algunas de mis tareas más arduas. Debido a mis numerosas obligaciones y al volumen de trabajo que he logrado asumir, garantizo que cualquiera que sea lo suficientemente valiente como para recoger esta lista de objetos y traérmelos intactos será generosamente recompensado.\n\nLa lista se detalla en las siguientes páginas...", "Patas de cristal sólido -\n\nLas arañas cristalderma de la Garganta de Fuego están hechas de un material muy similar al cristal. Sus patas, si no se dañan cuando se las mata, constituyen excelentes conductores en algunos experimentos de ingeniería de algunos de mis compañeros.\n\nVoy a necesitar unas cuantas para realizar pruebas. Las arañas, al tener ocho patas, no deberían suponer problema alguno para un fornido guerrero o para un mago experimentado.", "Un paquete que no llega a tiempo a su destino\n\nHe contratado a alguien a quien creí un piloto fiable para que me trajera un paquete desde Theramore. Por lo visto, me equivoqué. Y, a pesar de que el piloto vivió para contarla, abandonó su zeppelín y todo su cargamento para salvar su pellejo.\n\nLo cierto es que necesito ese paquete. Según me ha dicho Beezil, se estrelló al oeste de la bahía en el marjal Revolcafango. Yo bajé justo después de que él atravesara las colinas, bordeando la costa.\n\nMmm... nunca me dijo cuál fue la causa de que se estrellara...", "Flameberge equilibrada de Buenacero -\n\nFinalmente, deseo recuperar una de mis obras más finas creadas hasta la fecha. Esta Flameberge fue una espada increíble que otorgué a quien consideraba un honorable y excelente guerrero. Sí, pero ¿no fue derrotado por un múrloc llamado Jarquai? Más o menos eso ocurrió.\n\nOcurrió cuando viajaba por la costa del Pantano de las Penas cuando tuvo la idea de atacar a la criatura. Fracasó en su intento y, aparentemente, huyó, pero no sin antes abandonar el arma a merced del múrloc.", "Búscame esos objetos y regresa a Gadgetzan con todos ellos, junto con este libro de contabilidad, y te recompensaré." } } },
    ["Gordo's Report"] = { { ids = { "i286202" }, first = "appleyumyummepickflowers", pages = { "<Por increíble que parezca, hay una talla casi legible en la piel de la manzana>.\n\nManzana ñam ñam. Ahora coger flores yo." } } },
    ["Gozwin's Mechanic's Log"] = { { ids = { "i277976" }, first = "mechanicslogthiscommissi", pages = { "Registro de mecánico\n\n<El pequeño diario con tapa de cuero está cubierto de aceite y manchas de grasa. Contiene bocetos de diseños y configuraciones mecánicas, con anotaciones y descripciones. Abres una página al azar>.\n\nEste encargo me pagará las facturas durante años. Solo hace falta que se me ocurra algo para evitar que el neutralizador de oscilaciones se sobrecaliente o se haga añicos. Lo que tengo que hacer es transferir por un vórtice el exceso de calor al núcleo de combustión, pero lo he estado posponiendo porque tengo que desmantelar todo el caminante y desmontar el motor entero.\n\nPágina 17", "<Sigues hojeando el libro y das con un diagrama que ocupa dos páginas enteras>.\n\nModificaciones del sistema de armas\n\nTorreta de hielo: operativa\nLanzallamas: operativo\nPulso eléctrico: operativo\nAerosol radiactivo: operativo\nRifle automático: operativo\nHaz láser cercenador: EXPERIMENTAL\nCañón sónico: EXPERIMENTAL\nRayo fásico: SOLO CONCEPTO\n\nPágina 34                                      Página 35", "LISTA DE TAREAS\n\nPreparar el equipo para salir de caza\nFabricar ganchos para el cinturón de Grund\nReparar las gafas de soldar\nEnviar una carta a mamá\n\nPágina 45" } } },
    ["Gramma Stonefield's Note"] = { { ids = { "i1252" }, first = "hellowilliamitsbeenyears", pages = { "Hola, William,\n\nHan pasado años desde que hablamos la última vez, pero espero que tú y tu hermano estéis bien y que prosperes como boticario.\n\nWilliam, tengo que pedirte un favor. Para ser breve, mi hijo Tommy Joe se ha enamorado locamente de la joven Maybell Maclure. Y a pesar del gran amor que siente el uno por el otro, nuestras familias... verás, nuestras familias llevan años enemistadas.", "Temo que la guerra entre los Campopétreo y los Maclure acabe con el incipiente romance entre Tommy Joe y Maybell, así que, en tiempos como estos, en los que los rumores de guerra se ciernen sobre nosotros, es preciso cultivar la juventud y el amor.\n\nDe ahí el favor que te pido: Te pido que uses tus habilidades y fabriques una poción o elixir para ayudar a estos dos jóvenes en su misión de reunirse.\n\nGracias, William. Y por favor, si puedes apartarte un poco del trabajo, ven a visitarme. Te invito a que nos riamos un poco recordando el pasado.\n\nMildred" } } },
    ["Grand Admiral Daelin Proudmoore"] = { { ids = { "o177201" }, first = "commanderofthealliancefl", pages = { "Comandante de las flotas de la Alianza\n\nAmigo de Ventormenta" } } },
    ["Grape Manifest"] = { { ids = { "i11125" }, first = "brothernealsmygrapesares", pages = { "Hermano Neals,\n\n¡Mis uvas se han salvado! $N, $gel portador:la portadora; de este manifiesto, entró en mi viñedo lleno de matones y recogió todas las uvas que yo no pude cosechar. Si bien los Defias siguen deambulando por el río, casi toda mi cosecha se ha salvado.\n\nPuedes agregar a tus almacenes un cargamento de varias fanegas de uvas.\n\nQue la Luz nos proteja,\nMilly Osworth" } } },
    ["Green Hills of Stranglethorn - Chapter I"] = { { ids = { "i2756" }, first = "ourfirstdaywentaswellaso", pages = { "Nuestro primer día fue todo lo bien que se puede esperar que vayan los primeros días. La mayor parte del tiempo nos preocupamos de realizar los preparativos necesarios para establecer un campamento base. Encontré un lugar ideal, junto a la ensenada de un río de agua dulce. A juzgar por los viejos y abandonados muelles que hay cerca, este emplazamiento estuvo habitado hace algún tiempo. Por lo que respecta a los habitantes primitivos, solo el tiempo puede contar esa historia.", "Para esta expedición he reunido a Ajeck Rouack y a Sir S. J. Erlgadin, junto con mi sirviente de confianza, Barnil Jarropetra. Libré muchas batallas al lado del padre de Ajeck en defensa de la Alianza. Verla crecida es bastante especial. Su padre la instruyó bien en las artes de las armas. Su habilidad con el arco me hace preguntarme si corre sangre élfica por esas venas.", "Sir S. J. Erlgadin proviene de la aristocracia humana. Su padre, el conde Erlgadin, era célebre por su generosidad. Fue el conde quien presionó por una mejora en las condiciones de trabajo de la Hermandad de los Albañiles durante la restauración de Ventormenta después de la Segunda Gran Guerra.", "En los años que siguieron, después de que Ventormenta traicionara a la hermandad de los albañiles, Sir Erlgadin se fue volviendo más rencoroso respecto del papel de los nobles en el Reino. Ya no deseaba defender la posición que la estirpe de su padre había ganado para él en la Casa de Nobles. Pero me estoy yendo por las ramas. El propósito de esta historia no es que sirva como tratado político o biografía. Este es el relato de mis experiencias en busca de caza mayor por las verdes colinas de Tuercespina.", "Nos levantamos al amanecer. Barnil empezó a preparar el desayuno. Advertí que Ajeck estaba un poco distraída. La caminata del día prometía ser larga y nos esperaban peligrosos episodios de caza. Cualquier descuido podía ponernos en una situación difícil. No obstante, Ajeck parecía incapaz de desviar su mirada de Barnil, que estaba de pie frente al río, limpiando su equipo.", "Justo cuando estaba a punto de cuestionar la falta de interés de Ajeck en la estrategia de caza del día, alargó la mano hacia su arco, lo tensó con una flecha y la soltó justo hacia el pobre Barnil. Pero no era a Barnil a quien Ajeck disparaba, pues, cuando Barnil se echó a un lado boquiabierto, un gran crocolisco de río flotó a la superficie con la flecha de Ajeck perfectamente colocada entre sus grandes ojos.", "Nos pusimos en camino hacia el oeste, a través de la espesa maleza de la enmarañada jungla. Con pasos lentos y cuidadosos, avanzamos a través de un espeso follaje en busca de presa. La mañana pasó en un silencio frustrante. Nada se agitaba en la Vega, ni una brisa. Hacia la tarde, la expedición se mostraba impaciente. Barnil ya no andaba con los pasos cautelosos de un depredador que rastrea a su presa. En su lugar, caminaba pesada y torpemente por el camino, a menudo pisando ruidosamente hojas secas o ramas caídas.", "Durante semejante tropiezo, Erlgadin posó su mano pesadamente sobre el hombro de Barnil. Ajeck y yo apenas advertimos la escena, suponiendo que el hombre solo estaba dando una merecida reprimenda a Barnil por su descuido. No obstante, Erlgadin hizo un gesto lento con la cabeza en dirección a un árbol caído. Desde allí nos acechaban dos ojos negros penetrantes justo encima de un par de afilados colmillos." } } },
    ["Green Hills of Stranglethorn - Chapter II"] = { { ids = { "i2757" }, first = "thebeastwasamalestrangle", pages = { "La bestia era un tigre macho de Tuercespina. Antes de que pudiera amartillar el rifle, Erlgadin levantó la ballesta y disparó en dirección al animal. El virote dejó su marca y sorprendió a la bestia con fuerza en el costado izquierdo. El tigre hizo un intento en vano por huir, pero la herida era demasiado grave. La bestia fue dando traspiés durante varios trágicos segundos, hasta que Barnil lo remató lanzando un hacha.", "La matanza provocó un ánimo festivo en la expedición. Barnil sirvió aguamiel para disfrute de todos. Pero nuestros festejos fueron efímeros. Mientras preparábamos el cadáver para transportarlo de vuelta al campamento base, un rugido espantoso nos cogió desprevenidos a todos. En todos mis años nunca he oído nada que helara la sangre de tal modo.", "En un rocoso precipicio en lo alto, perfilado por el sol poniente, podía distinguir el felino depredador más grande que he visto jamás. Pude liberar una descarga con mi rifle, pero el felino siguió su camino. Rugió una vez más, en esta ocasión vez con más fuerza que la anterior, y desapareció.\n\nRecogimos nuestras pertenencias y nos dirigimos solemnemente de vuelta al campamento.", "Había prometido a la expedición que pasaríamos el día siguiente cazando panteras, ya que sus pieles son muy valoradas en Azeroth. Esta demanda se debe a que todos los cazadores, tramperos y comerciantes de pieles arriesgan valientemente su vida en nombre de la Alianza.", "Ajeck y Sir Erlgadin estaban ansiosos por aprender a cazar eficazmente con un rifle de los enanos. Hice que los dos humanos dejaran sus primitivas armas en el campamento base. Barnil y yo los equipamos con algunas de las mejores armas de fuego de Forjaz.", "Ese día nos aventuramos al sur, siguiendo algunos rastros recientes de pantera. Pronto llegamos a un barranco que se cruzaba por un enorme puente colgante. No pude evitar pensar en la descriptiva obra de Brann sobre aquella región cuando vi aquella maravilla de la ingeniería. Se suponía tan a menudo que los trols nativos eran una raza primitiva e inculta, pero, mientras observaba fijamente la artesanía maestra del puente, pude reconocer la habilidad con la que los albañiles trols superaron la hazaña, aparentemente imposible.", "Al poco tiempo, Ajeck rastreó a la pantera en dirección al sudoeste. Anduvimos en silencio, con las armas preparadas, anticipándonos a nuestra presa. Un chasquido de ramas en un bosquecillo cercano llamó nuestra atención de inmediato. Allí había algo. Una mirada seria a Barnil bastó para transmitirle mis pensamientos. Barnil bajó su rifle lentamente. Esta presa no era para nosotros, sino para nuestros compañeros humanos. Innumerables panteras habían perdido la vida al enfrentarse a nuestros humeantes cañones. Esta presa era para los humanos.", "Tanto Ajeck como Sir Erlgadin se mantuvieron erguidos, con las armas al nivel de la hirsuta maleza que había bajo unos árboles que se mecían de un lado a otro. El sol del mediodía ardía con fuerza sobre nosotros. Una lenta gota de sudor rodó por la sien de Erlgadin, al tiempo que retiraba el gatillo. Tras el chasquido, el follaje exuberante se abrió en dos y una pantera negra, espécimen hermoso, saltó veloz sobre la llanura." } } },
    ["Green Hills of Stranglethorn - Chapter III"] = { { ids = { "i2758" }, first = "thehumanstrainedtheirsit", pages = { "Los humanos tenían la mira puesta en la pantera mientras esta corría rodeando la arboleda. Los cañones de los rifles se movían en paralelo con el animal. Barnil me miró impaciente y yo negué con la cabeza para que no abriera fuego. Esta caza era para los humanos, no para Barnil ni para mí. Erlgadin lanzó un disparo, sin dar en el blanco. Por lo visto, no estaba preparado para soportar el efecto de la descarga.", "El arma dio una violenta sacudida. El cañón rodó lateralmente y cayó bajo el rifle de Ajeck. Ajeck había elegido ese preciso momento para apretar el gatillo. El rifle, con el mira orientada torpemente hacia la fila de árboles, se disparó con un estruendo inconfundible. Una bandada de pájaros chilló desde la copa de un árbol, dispersándose. Una columna de humo emergió del árbol. Sobrecogidos, vimos cómo una tremenda rama caía sobre la pantera que intentaba escapar, partiéndole el lomo.", "Unas semanas después, nuestras reservas de piel de pantera y tigre crecieron ostensiblemente. Decidí que era hora de que la expedición cambiara de objetivo: Raptores.\n\nLos humanos, valorando la instrucción que Barnil y yo les proporcionamos, decidieron abstenerse de cazar con armas de fuego. Ajeck estaba mucho más cómoda con un arco de cuerda fina, mientras que Sir Erlgadin nunca abandonaba el campamento sin su maciza ballesta.", "Nos fuimos al alba en dirección al sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación ante la posibilidad de encontrarnos con miembros de la tribu Sangrapellejo. Recordé a Barnil que los Sangrapellejo estaban ocupados intentando destruir a su enemigo tribal, los Machacacráneos. De más está decir que Barnil no estaba en absoluto tranquilo. Yo, por mi parte, tenía el rifle cargado, un saco lleno de pólvora y tres cazadores infalibles que me acompañaban para aplacar mis preocupaciones ante una posible emboscada.", "Una vez, en el campo de batalla, tuve delante a un inferno altísimo, con el ejército de la Legión Ardiente avanzando desde todas partes. Una banda de trols revoltosos parece tan inofensiva como una liebre en las colinas de Dun Morogh.\n\nPasamos por las ruinas de Tkashi sin contratiempos, lo que tranquilizó a Barnil en gran medida. El grupo avanzó hacia el oeste, en dirección al Mare Magnum, bordeando las ruinas de Zul'Kunda, situadas al sur. Al subir por los altos acantilados, divisamos al primer raptor.", "La bestia ni siquiera detectó nuestra presencia. De hecho, el único saludo que recibió por parte de la expedición fue una bala en medio de la frente. Sir Erlgadin lanzó un grito de alegría, mientras Ajeck asentía y me miraba, haciendo un gesto de entusiasta aprobación. Revolví mi mochila en busca de mi pipa, esperando celebrar la hazaña con el humo de la victoria. Barnil empezó a correr por la cuesta para recuperar el cadáver del raptor. Miré a la bestia abatida con la satisfacción que produce una caza importante.", "Sin embargo, no pude disfrutar de la victoria del cazador por mucho tiempo, pues al contemplar el horizonte, numerosas siluetas aparecieron en la cresta de la colina, justo encima del pobre Barnil.\n\n*¡Huye, Barnil!*, grité. Ajeck, Sir Erlgadin y yo lanzamos una descarga de balas y flechas por encima de Barnil, directo sobre los raptores. Alguien soltó la presa en medio de la confusión.", "Nuestros disparos apresurados fueron suficientes para provocar la huida de Barnil. Este regresó gritando por la colina y se reincorporó al grupo. Nos internamos en la selva a toda prisa, con una panda de feroces raptores Colazote vigilando cada uno de nuestros movimientos.\n\nLos cazadores se habían convertido en la presa." } } },
    ["Green Hills of Stranglethorn - Chapter IV"] = { { ids = { "i2759" }, first = "iledthepartytowardthesea", pages = { "Conduje a la expedición hasta el mar, con el fin de que la costa nos protegiera de los raptores. Con nuestro apresuramiento, nos habíamos desviado demasiado al norte, a una altitud peligrosamente elevada. Nos habíamos equivocado. Fue culpa mía. Nos detuvimos delante de un escarpado acantilado, con los raptores justo detrás de nosotros.", "Avancé lentamente con el arma levantada. Había conducido a estos valientes cazadores a su fin. Tenía que morir defendiéndolos. Los raptores colazote son particularmente feroces, conocidos por ser unos sanguinarios implacables. Eran muchos más que nosotros. Pero si hubiera dejado que nos mataran a mis camaradas y a mí, sin antes derramar parte de su propia sangre, no me lo habría perdonado.", "Ajeck y Sir Erlgadin dispusieron sus armas, flanqueándome a cada lado, de espaldas al mar. Barnil dejó escapar un suspiro derrotado y blandió su hacha. Los colazotes estaban casi sobre nosotros. Su firme zancada se había hecho más lenta. Ahora acechaban a su presa, pues sabían que nos tenían atrapados.", "Entonces ocurrió algo milagroso. Desde donde estábamos escuchamos el inconfundible y aterrador rugido del gran tigre blanco. A pesar de ser numerosos, los raptores dieron media vuelta y se dispersaron. Solo vimos el breve destello blanco de un tigre que salió disparado junto a nosotros, abalanzándose sobre uno de los raptores. No fue necesario dar ninguna orden. Los cuatro miembros de la expedición sabíamos que era el momento de salir corriendo.", "Corrimos a toda velocidad hasta el campamento base, sin reducir la marcha en ningún momento. Más tarde aquella noche, nos sentamos en silencio alrededor de la hoguera, sabiendo que un extraño golpe de suerte nos había salvado la vida. Esos son los riesgos que corre el cazador de caza mayor. Jugamos con el destino. No obstante, todos, en algún momento de nuestras vidas, debemos afrontar las afiladas garras del destino. Este enano se alegra, porque ese momento aún no ha llegado a las verdes colinas de Tuercespina." } } },
    ["Green Hills of Stranglethorn - Page 1"] = { { ids = { "i2725" }, first = "thegreenhillsofstranglet", pages = { "Las verdes colinas de Tuercespina\n\nNuestro primer día transcurrió perfectamente, como era de esperar. La mayor parte del tiempo lo dedicamos a instalar el campamento base. Encontré un paraje ideal junto a un río de aguas cristalinas. A juzgar por los muelles viejos y abandonados, este lugar fue habitado en el pasado. En cuanto a los primeros habitantes, su historia solo puede contarse ahora que el tiempo ha transcurrido." } } },
    ["Green Hills of Stranglethorn - Page 10"] = { { ids = { "i2734" }, first = "thekillbroughtaboutafest", pages = { "La caza generó euforia en la expedición. Barnil sirvió hidromiel a todos los presentes. Sin embargo, la alegría duró poco. Cuando preparábamos el cadáver para llevarlo al campamento base, un espantoso gruñido nos cogió desprevenidos. Jamás había oído nada capaz de helarme la sangre como aquello." } } },
    ["Green Hills of Stranglethorn - Page 11"] = { { ids = { "i2735" }, first = "onarockyprecipiceabovesi", pages = { "Sobre un precipicio rocoso situado encima de nosotros, la silueta marcada por el sol crepuscular reveló el gato de presa más descomunal que hubiera visto jamás. Solo fui capaz de disparar una torpe descarga con mi rifle, pero el gato permaneció inmóvil. Volvió a gruñir, esta vez con mayor intensidad, y desapareció.\n\nRecogimos nuestras cosas y regresamos solemnemente al campamento." } } },
    ["Green Hills of Stranglethorn - Page 14"] = { { ids = { "i2738" }, first = "onthisdayweventuredtothe", pages = { "Ese día nos aventuramos al sur, siguiendo algunos rastros recientes de pantera. Pronto llegamos a un barranco que se cruzaba por un enorme puente colgante. No pude evitar pensar en la descriptiva obra de Brann sobre aquella región cuando vi aquella maravilla de la ingeniería. Se suponía tan a menudo que los trols nativos eran una raza primitiva e inculta, pero, mientras observaba fijamente la artesanía maestra del puente, pude reconocer la habilidad con la que los albañiles trols superaron la hazaña, aparentemente imposible." } } },
    ["Green Hills of Stranglethorn - Page 16"] = { { ids = { "i2740" }, first = "bothajeckandsirerlgadins", pages = { "Tanto Ajeck como Sir Erlgadin se mantuvieron erguidos, con las armas al nivel de la hirsuta maleza que había bajo unos árboles que se mecían de un lado a otro. El sol del mediodía ardía con fuerza sobre nosotros. Una lenta gota de sudor rodó por la sien de Erlgadin, al tiempo que retiraba el gatillo. Tras el chasquido, las hojas exuberantes se dividieron y una pantera negra, espécimen hermoso, saltó veloz sobre la llanura." } } },
    ["Green Hills of Stranglethorn - Page 18"] = { { ids = { "i2742" }, first = "hisguntossedbackviolentl", pages = { "El arma dio una violenta sacudida. El cañón rodó lateralmente y cayó bajo el rifle de Ajeck. Ajeck había elegido ese preciso momento para apretar el gatillo. El rifle, con el mira orientada torpemente hacia la fila de árboles, se disparó con un estruendo inconfundible. Una bandada de pájaros chilló desde la copa de un árbol, dispersándose por todas partes. Una columna de humo emergió del árbol. Sobrecogidos, vimos cómo una tremenda rama caía sobre la pantera que intentaba escapar, partiéndole el lomo." } } },
    ["Green Hills of Stranglethorn - Page 20"] = { { ids = { "i2744" }, first = "wesetoutatfirstlighthead", pages = { "Nos fuimos al alba en dirección al sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación sobre la posibilidad de encontrarnos con miembros de la tribu Sangrapellejo. Recordé a Barnil que los Sangrapellejo estaban ocupados intentando destruir a su enemigo tribal, los Machacacráneos. De más está decir que Barnil no estaba en absoluto tranquilo. Yo, por mi parte, tenía el rifle cargado, un saco lleno de pólvora y tres cazadores infalibles que me acompañaban para aplacar mis preocupaciones sobre una posible emboscada." } } },
    ["Green Hills of Stranglethorn - Page 21"] = { { ids = { "i2745" }, first = "ivestoodbeforeatoweringi", pages = { "Me he encontrado ante un infernal enorme en el campo de batalla, mientras el ejército de la Legión Ardiente avanzaba desde todas direcciones. Un grupo rebelde de trols me parece tan inofensivo como una liebre en las colinas de Dun Morogh.\n\nPasamos ante las ruinas de Tkashi sin suceso alguno, para alivio de Barnil. El grupo procedió a dirigirse hacia el oeste, hacia el Mare Magnum, bordeando las ruinas de Zul'Kunda justo al sur. Mientras ascendíamos los altos riscos del mar, vimos a nuestro primer raptor." } } },
    ["Green Hills of Stranglethorn - Page 24"] = { { ids = { "i2748" }, first = "ourhastilyaimedshotswere", pages = { "Nuestros disparos apresurados bastaron para lograr la huida de Barnil. Barnil lanzó un clamor colina abajo y se volvió a unir al grupo. Corrimos a refugiarnos en la jungla, una manada de feroces raptores colazote acechaba todos nuestros movimientos.\n\nLos cazadores eran, ahora, los cazados." } } },
    ["Green Hills of Stranglethorn - Page 25"] = { { ids = { "i2749" }, first = "iledthepartytowardthesea", pages = { "Con el fin de que la costa nos protegiera de los raptores, conduje a la expedición hasta el mar. En nuestro apresuramiento, nos desviamos y acabamos en el norte, en un monte peligrosamente elevado. Pero nos equivocamos. Fue culpa mía. Nos detuvimos delante de un escarpado acantilado, con los raptores justo detrás de nosotros." } } },
    ["Green Hills of Stranglethorn - Page 26"] = { { ids = { "i2750" }, first = "isteppedslowlyforwardgun", pages = { "Avancé lentamente con el arma levantada. Había conducido a estos valientes cazadores a su fin. Tenía que morir defendiéndolos. Los raptores colazote son particularmente feroces, conocidos por ser unos sanguinarios implacables. Eran muchos más que nosotros. Pero si hubiera dejado que nos mataran a mis camaradas y a mí, sin antes derramar parte de su propia sangre, no me lo habría perdonado." } } },
    ["Green Hills of Stranglethorn - Page 27"] = { { ids = { "i2751" }, first = "ajeckandsirerlgadinreadi", pages = { "Ajeck y Sir Erlgadin dispusieron sus armas, flanqueándome a cada lado, de espaldas al mar. Barnil dejó escapar un suspiro derrotado y blandió su hacha. Los colazotes estaban casi sobre nosotros. Su firme zancada se había hecho más lenta. Ahora acechaban a su presa, pues sabían que nos tenían atrapados." } } },
    ["Green Hills of Stranglethorn - Page 4"] = { { ids = { "i2728" }, first = "intheyearsthatfollowedaf", pages = { "En los años siguientes, después de que Ventormenta traicionara a la Hermandad de los Albañiles, Sir Elrgadin estaba cada vez menos de acuerdo con el papel de los nobles en el Reino. Ya no deseaba ostentar la posición que la línea de sangre de su padre le había legado en la Casa de Nobles.\n\nPero me estoy apartando del tema. Esta historia no pretende ser un tratado político o una biografía. Este es el relato de mis experiencias de caza en las verdes colinas de Tuercespina..." } } },
    ["Green Hills of Stranglethorn - Page 6"] = { { ids = { "i2730" }, first = "justasiwasabouttoquestio", pages = { "Justo cuando iba a cuestionar la falta de interés de Ajeck por la estrategia a seguir ese día, ella extrajo una flecha de su carcaj y la lanzó directamente hacia el pobre Barnil. Sin embargo, Barnil no era el objetivo de Ajeck. Cuando este se apartó boquiabierto, un gran crocolisco de río flotaba en la superficie con la flecha perfectamente clavada en medio de sus grandes ojos." } } },
    ["Green Hills of Stranglethorn - Page 8"] = { { ids = { "i2732" }, first = "duringonesuchmissteperlg", pages = { "Durante semejante tropiezo, Erlgadin posó su mano pesadamente sobre el hombro de Barnil. Ajeck y yo apenas advertimos la escena, suponiendo que el hombre solo estaba dando una merecida reprimenda a Barnil por su descuido. No obstante, Erlgadin hizo un gesto lento con la cabeza en dirección a un árbol caído. Desde allí nos acechaban dos ojos negros penetrantes justo encima de un par de afilados colmillos." } } },
    ["Grelin Whitebeard's Journal"] = { { ids = { "i2004" }, first = "dayonetheapprenticeandih", pages = { "PRIMER DÍA\n\nMi aprendiz y yo hemos llegado hoy al Valle de Crestanevada. El recorrido por la caverna prácticamente no tuvo incidencias. Acampamos bastante lejos de la cueva en la que, según nos dijeron, se habían reunido los trols.\n\nSEGUNDO DÍA\n\nEl aullido de un maldito lobo me mantuvo despierto toda la noche.\n\nEn un par de días tendré un nuevo traje de piel de lobo.\n\nEl chico se enfrascó en una pelea con un trogg hoy y", "logró extraer lo mejor de la bestia espantosa, pero ahora se está curando de una herida inmunda en el brazo. Todo indica que tendré que ocuparme de las tareas domésticas durante un tiempo.\n\\TERCER DÍA\n\nHace frío. Ha nevado un poco cerca del mediodía.\n\nCUARTO DÍA\n\nEl chico volvió hoy y de buen humor, así que echamos un primer vistazo a los trols. Pertenecían al clan Peloescarcha, a juzgar por las marcas en la piel y los diversos abalorios que llevaban en el cuerpo.", "QUINTO DÍA\n\nEncargué al chico que vigilara el campamento mientras yo husmeaba en la cueva y echaba un vistazo por los alrededores. Son muchos trols y esto genera ciertos problemas. Tal vez haya que convocar a los montaraces por si resulta necesario limpiar la cueva de la plaga de trols.\n\\Soy consciente de no haber mencionado a los troggs últimamente. Aparecen por la zona en grandes grupos, pero son tan primitivos que no suponen una amenaza. El tiempo dirá si esto es verdad o no.", "Ni gota de cerveza durante casi una semana.\n\nSEXTO DÍA\n\nVuelve a hacer frío. Nieva. Trols y nada de cerveza.\n\nSÉPTIMO DÍA\n\nLa nieve es blanca,\nel cielo es añil,\nlos lobos aúllan de noche,\ny yo sin cerveza de barril.\n\nOCTAVO DÍA\n\nQuizás los trols no representen un problema tan grande como el que inicialmente supusimos. Son bastantes,", "pero no están bien armados ni organizados. Una pequeña demostración de fuerza deberá ser más que suficiente para neutralizarlos." } } },
    ["Grelin's Report"] = { { ids = { "i2619" }, first = "areportonthestateofthefr", pages = { "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada\n\nElaborado por Grelin Barbablanca, enviado especial del senado\n\nDesde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenazas que pueden eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en", "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto.\n\nEsta acción ha sido autorizada mediante la sanción que me otorgó el rey Barbabronce." } } },
    ["Gryshka's Letter"] = { { ids = { "i16307" }, first = "dearzarghthesteaksyousen", pages = { "Querido Zargh:\n\nLos filetes que enviaste están muy buenos. Tienen sus buenas vetas de grasa, son anchos y están recubiertos de grasa de jabalí. Justo como a mí me gustan. Cuando vaya a comerlos, pensaré en ti mientras me dedique a roer hasta el tuétano. Cerraré los ojos y veré tus fuertes manos llenas de cicatrices picando y cortando...\n\n¡Ja! Esto me recuerda aquella vez que tuviste el accidente y perdiste un dedo... ¡Oh, Zargh! Pensar en aquel día hace que me ría como una niña pequeña.\n\n¡Estás tan guapo cuando sangras!\n\nGryshka" } } },
    ["Hallowed Letter"] = { { ids = { "i9548" }, first = "yourconnectiontotheworld", pages = { "Tu conexión con el mundo y la suya contigo son esenciales para tu éxito como sacerdote. La sabiduría y la compasión te permitirán ayudar a quienes de verdad lo necesiten. El exceso de entusiasmo y las decisiones torpes solo impiden que los demás se fortalezcan o causan daño.\n\nCuando empieces a comprender lo que significa, necesitarás nuevas habilidades y hechizos para ayudarte. Ahí empieza mi papel: búscame en el ala de la biblioteca de la Abadía de Villanorte cuando quieras instruirte.\n\n-Sacerdotisa Anetta, instructora de sacerdotes" } } },
    ["Hallowed Memorandum"] = { { ids = { "i282338" }, first = "whileyoumaybearefugeewho", pages = { "Quizá hayas llegado a Forjaz como refugiado por desesperación, pero la Luz nunca rechaza a quien la necesita. Con el tiempo crecerá tu devoción y aprenderás a sentir su calor. Nuestros primos gnomos son tan bienvenidos en nuestras filas como cualquier enano robusto.\n\nVeo que tienes el don de canalizar la Luz. Es una cualidad especial que debes cultivar.\n\nBúscame cuando tengas tiempo. Estaré al fondo de Yunquemar, colina arriba.\n\n- Branstock Khalder, instructor de sacerdotes" } } },
    ["Hallowed Rune"] = { { ids = { "i9556" }, first = "withtheholylightwarminou", pages = { "Al calor de Luz Sagrada y con tantos descubrimientos hechos por nuestra gente, ser $ghijos:hijas; de Forjaz constituye todo un orgullo. La Liga de Expedicionarios progresa cotidianamente en su búsqueda de respuestas duraderas incluso a las preguntas más antiguas. Y ahora te tenemos a ti entre nuestros fieles para ayudarnos en la batalla contra los troggs o cualquier otra amenaza para nuestras fronteras.\n\nCuando tengas tiempo, ven a buscarme. Estaré en la parte trasera de Yunquemar, justo encima de la colina.\n\nBranstock Khalder, $ginstructor:instructora; de sacerdotes" } } },
    ["Hallowed Scroll"] = { { ids = { "i9569" }, first = "feelblessedthatyourespir", pages = { "Siéntete $gbendecido:bendecida;, ya que tu espíritu no ha sido arrojado al Abismo Abisal, $N. Incluso, siéntete más $gbendecido:bendecida; aún, ya que he decidido que tú vales la pena y escribir este pergamino tiene sentido.\n\nEl pueblo que una vez conociste, incluso que quizás cuidaste, ¡ya no existe! Debes aprender a \"vivir\" con este convencimiento durante el resto de tu vida no natural. Sugiero que asumas esto cuanto antes.\n\nSi piensas que estás $gpreparado:preparada; para los retos que tienes por delante, búscame en la iglesia de Camposanto.\n\nClérico oscuro Duesten, instructor de sacerdotes" } } },
    ["Hallowed Sigil"] = { { ids = { "i9557" }, first = "ihopethissigilfindsyouwe", pages = { "Espero que cuando recibas este sigilo, te encuentres bien, $N. Los espíritus me han dicho que vas a venir y te he enviado este mensaje inmediatamente. Estoy ansioso por compartir mis experiencias contigo y guiarte de tal manera que puedas prepararte para abandonar Teldrassil y realizar cometidos más importantes.\n\nCon todo lo que ha pasado en los últimos años, es mucho lo que podemos hacer para ayudar a otras razas de Azeroth. Cuando estés $glisto:lista;, búscame en Aldrassil, en el segundo nivel.\n\nShanda, $ginstructor:instructora; de sacerdotes" } } },
    ["Hallowed Tablet"] = { { ids = { "i9561" }, first = "ahhopedaspiritshaveprote", pages = { "Espero que los espíritus te hayan protegido hasta ahora, colega. Tienes muchas pruebas por delante y, cuando estés $gpreparado:preparada;, estoy <dispuesto/dispuesta a compartir mis experiencias contigo. Depende de ti decidir cuán $grápido y poderoso:rápida y poderosa> quieres ser. Solo podré guiarte cuando estés $gpreparado:preparada;.\n\nPara algunos, esto puede llevar poco tiempo, mientras que para otros, mucho más. Pero, por el momento, no te preocupes de eso. Cuando vengas a mi encuentro, hablaremos más ampliamente.\n\nKen'jai, $ginstructor:instructora; de sacerdotes" } } },
    ["Harthal Truesight"] = { { ids = { "o175776" }, first = "fellariswiftarrowrangerc", pages = { "Harthal Vistarreal\nSeñor Paladín de la Cruzada Escarlata\nCiudadano de Azeroth, caballero de la Mano de Plata\nVisto por última vez entrando en la ciudad maldita de Stratholme" } } },
    ["Hatred of the Centaur"] = { { ids = { "o177209" }, first = "asthemistsofdawnfadedand", pages = { "Al disiparse las brumas del alba y avanzar la Era de la Memoria, el semidiós Cenarius siguió su camino por los campos del mundo. Los shu'halo, los tauren, lamentaron su marcha y olvidaron gran parte del druidismo que les había enseñado. Con el paso de las generaciones olvidaron cómo hablar con los árboles y los seres salvajes de la tierra. Los susurros oscuros de las profundidades del mundo volvieron a llegar a sus oídos.", "Aunque los hijos de la tierra rechazaron los susurros malignos, una terrible maldición cayó sobre sus tribus errantes. De las tierras negras del oeste llegó una horda de criaturas asesinas: los centauros. Caníbales y devastadores, cayeron sobre los shu'halo como una peste. Aunque los valientes y cazadores combatían con la bendición de la Madre Tierra en el corazón, no lograron derrotarlos.", "Los shu'halo tuvieron que abandonar sus tierras ancestrales y recorrer las llanuras sin fin como nómadas desde entonces. Se creía que un día volvería la esperanza y las tribus dispersas encontrarían un nuevo hogar bajo los brazos amorosos de la Madre Tierra." } } },
    ["Here Lies King Terenas Menethil II"] = { { ids = { "o175659" }, first = "herelieskingterenasmenet", pages = { "Aquí yace el rey Terenas Menethil II, último rey verdadero de Lordaeron.\n\nGrandes fueron sus hazañas, largo su reinado, inconcebible su muerte.\n\n \"Que el padre no sea inculpado por los actos de su hijo.\n Que la corona manchada de sangre permanezca en el olvido.\"" } } },
    ["Highborne Astrolabe"] = { { ids = { "o175686" }, first = "recoveredfromtheundersea", pages = { "Recuperado de las ruinas submarinas de Suramar, este astrolabio funcional fue fabricado por los elfos de la noche altonatos hace doce mil años. Los altonatos, obsesionados con la magia, lo oculto y la astronomía, desarrollaron una serie de ingeniosos aparatos. Este dispositivo proporciona valiosa información sobre el saber científico de los antiguos elfos de la noche." } } },
    ["Hildelve's Journal"] = { { ids = { "i3117" }, first = "daymytankisbrokenbutikno", pages = { "Primer día\n\nSe me ha roto el depósito, pero sé que por estas colinas encontraré el mineral de Quiron. Le dije a Podomartillo que se quedara para vigilar nuestros depósitos.\n\nContinuaré buscando yo solo. Si no logro regresar, este diario será mi último testamento.\n\nBuron Hondocuesta, piloto\nBrigada de Tanques de Vapor de Forjaz", "Segundo día\n\nMi búsqueda continúa y sigo sin encontrar el mineral. Me pregunto si lo del mineral es solo un rumor o una broma de Roscapiedra. Si es así, ¡cuando vuelva al Almacén de Brasacerada le voy a partir el cráneo!\n\nAnoche, cuando preparaba mi campamento, escuché el eco de un gruñido desde los cañones.\n\nNo era un lobo. Antes parecía un oso.", "Tercer día\n\nLos gruñidos se prolongaron durante toda la noche y me han seguido a lo largo del día, distrayéndome de mi labor de búsqueda del mineral. ¡Creo que un oso me está siguiendo!\n\nEspero que se acerque todo lo posible. ¡Así podré enterrarle mi pico en la cabeza!", "Cuarto día\n\nMis provisiones se están agotando. Aún me queda bastante comida, pero no había planeado quedarme tanto tiempo en la selva, lejos de mi tanque, con tan solo dos barriles de cerveza.\n\nHe permanecido despierto las últimas dos noches, escuchando ese maldito gruñido y ¡casi me bebo los barriles enteros!\n\nTengo que regresar mañana con Podomartillo y nuestros tanques de vapor. No quiero perderme aquí, sin cerveza.", "Quinto día\n\n¡El maldito oso me dejó destrozado! Me atacó al mediodía, gruñendo y embistiéndome por la espalda.\n\nDe haberse aproximado contra el viento, habría percibido su olor... ¡su hedor era espantoso! ¡El olor de su pelaje roñoso y su aliento podrido bastaban para aniquilar a cualquiera!\n\n¡Luché contra esa bestia, pero al final dio un buen bocado a mi pierna. Ahora no puedo moverme, me he quedado sin cerveza y, finalmente, no he logrado encontrar el mineral. ¡Maldición!", "Sexto día\n\nEl oso aún no ha vuelto... ¡Debí darle una buena paliza! Pero sigo escuchando sus gruñidos. ¡Creo que está esperando a que muera!\n\nSi encuentras este libro, debo encomendarte una tarea. Mata a ese oso asqueroso. Mátalo y luego lleva el libro a mi amigo Podomartillo. Él querrá saber qué ocurrió.\n\nTambién puedes coger mi armadura. ¡La necesitarás para luchar contra Sarnagarra!" } } },
    ["Hillsbrad Town Registry"] = { { ids = { "i3657" }, first = "hillsbradtownregistrywet", pages = { "Registro de la ciudad de Trabalomas\n\nNosotros, el pueblo de Trabalomas, juramos solemnemente lealtad y devoción hacia la Alianza, gobernada por grandes monarcas, el rey Magni Barbabronce de Forjaz y el rey Anduin Wrynn de Ventormenta.\n\nEste registro sirve al propósito de gobernar esta bella ciudad en las estribaciones de las grandiosas Montañas de Alterac, sirviendo al mismo tiempo de documento para inscribir a aquellos que hayan pagado sus impuestos en nombre de los reyes y la todopoderosa Alianza.", "Magistrado Rutherford Ladoquemao\nTodas las deudas saldadas.\n\nHerrero Avery Verrintan\nTodas las deudas saldadas.\n\nDependiente Horracio Corzalbal\nTodas las deudas saldadas.\n\nConcejal Giligil\nTodas las deudas saldadas.\n\nConcejal Garfios\nTodas las deudas saldadas.\n\nGranjero Getz\nTodas las deudas saldadas.\n\nGranjero Ray\nDeuda pendiente. Promesa de pago en productos agrícolas durante la cosecha.\n\nGranjero Lyion\n\nDeuda pendiente. Expulsado de sus tierras.", "Granjero Kalaba\nDeudas pendientes. Promesa de pago en productos agrícolas durante la cosecha.\n\nCiudadano Wilkes\n\nTodas las deudas saldadas.\n\nCiudadano Bonoan\n\nTodas las deudas saldadas.\n\nMinero Wellty\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral desde la mina Azur.\n\nMinero Sidney\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral de la mina Azur.\n\nMinero Hackett\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral de la mina Azur.", "Minero Orwell\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral de la mina Azur.\n\nMinero Fitzgerald\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral de la mina Azur.\n\nCiudadano Netherand\nTodas las deudas saldadas.\n\nSupervisor Bonds\nDeuda pendiente. El pago debe hacerse efectivo en la próxima entrega de mineral de la mina Azur." } } },
    ["Holia Sunshield"] = { { ids = { "o175777" }, first = "holiasunshielddefenderof", pages = { "Holia Escusol\n\nDefensora de la Cruzada Escarlata\n\nMuerta al abatir al señor del terror Beltheris" } } },
    ["Hollee's Note"] = { { ids = { "i281243" }, first = "tarrelmybelovednotadaygo", pages = { "Tarrel, amado mío:\n\nNo pasa un día sin que me pierda pensando en esas trenzas de bronce, esa risa atronadora o esos antebrazos musculosos.\n\nDebes venir a Auberdine en el próximo barco. Estamos hechos el uno para el otro. ¡Sabes que es verdad si escuchas a tu corazón!\n\nTuya, si me aceptas,\n\nHollee" } } },
    ["Horatio Montgomery, M.D."] = { { ids = { "o124374" }, first = "inmemoryofmydearmentorho", pages = { "A la memoria de mi querido mentor, Horatio M. Montgomery, M.D. curandero, maestro y amigo.\n\n50 BTFT - 25 ATFT\n\n\"El mundo está lleno de gente enferma y cansada. Nuestra labor, como curanderos, o mejor dicho, como hombres y mujeres del mundo de la medicina, es librarlos a todos de sus males imaginarios.'\"\n\n- H.M.M., Médico, JD, gran maestro agricultor, bailarín extraordinario, amigo de los animales" } } },
    ["Horde Catapult"] = { { ids = { "o175688" }, first = "thisremnantfromthesecond", pages = { "Estos restos de la Segunda Guerra constituyen un conmovedor recuerdo de lo cerca que la Horda estuvo de conquistar la montaña de Forjaz." } } },
    ["Horde Military Ranks"] = { { ids = { "o179741" }, first = "hordemilitaryranksoffice", pages = { "RANGOS MILITARES DE LA HORDA\n\nOFICIALES\n\nGran señor de la guerra\nSeñor de la guerra\nGeneral\nTeniente general\nCampeón\nCenturión\nLegionario\nGuardia de sangre\nGuardia de piedra\n\nSOLDADOS\n\nPrimer sargento\nCapataz\nSargento\nBruto\nExplorador" } } },
    ["Humming Recall Crystal"] = { { ids = { "i282418" }, first = "thewindshapershavebeenwa", pages = { "<Al tocar el cristal resplandeciente, sientes una ráfaga de viento a tu alrededor que te hace llegar las siguientes palabras>:\n\nLos Formavientos te han estado observando con atención, y ha llegado el momento de que des el siguiente paso como chamán.\n\nLos espíritus de viento han desaparecido de la Isla de Zephras, y recae en nosotros el deber de enfrentarnos a los peligros del plano elemental para traerlos de vuelta. No hay deber más sagrado que este, y nuestra supervivencia depende de ello.\n\nBúscame en Thendal, cerca del centro urbano. Me encargaré de que recibas entrenamiento.\n\n-Formavientos Boro, instructor de chamanes" } } },
    ["Icecrown and the Frozen Throne"] = { { ids = { "o175749" }, first = "kiljaedencastnerzhulsicy", pages = { "Kil'jaeden volvió a emplazar la urna congelada de Ner'zhul en el mundo de Azeroth. El cristal endurecido centelleaba bajo la noche estrellada y chocó en el desolado continente ártico de Rasganorte, enterrándose en las profundidades del glaciar Corona de Hielo. El cristal congelado, deformado y marcado por su violento descenso, adquirió el aspecto de un trono y el vengativo espíritu de Ner'zhul pronto comenzó a moverse en su interior.", "Desde los confines del Trono Helado, Ner'zhul comenzó a expandir su vasta conciencia y a entrar en contacto con las mentes de los habitantes de Rasganorte. Casi sin esfuerzo, logró esclavizar la mente de muchas criaturas indígenas, incluyendo trols de hielo wendigo, y atrajo a sus maléficos hermanos hacia su creciente sombra. Sus poderes psíquicos resultaron prácticamente ilimitados y los utilizó para crear un pequeño ejército que habitó en los intrincados laberintos de Corona de Hielo.", "A medida que el rey Exánime aprendía a dominar sus crecientes facultades bajo la persistente vigilancia de los Señores del Terror, descubrió un remoto asentamiento humano situado en la periferia del vasto territorio de Desolación de los dragones. En un abrir y cerrar de ojos, Ner'zhul decidió probar sus poderes con los despreocupados humanos.", "Ner'zhul propagó una peste de los no-muertos, que se había originado desde las profundidades, en el interior del Trono Helado, en los páramos del ártico. Controlando la peste con su sola voluntad, la lanzó directamente hacia el poblado humano. En un plazo de tres días, todos los habitantes del asentamiento estaban muertos, pero poco después, los pobladores empezaron a revivir como cadáveres zombis. Ner'zhul podía sentir sus espíritus y pensamientos individuales, como si fueran suyos.", "La colérica cacofonía en su mente hizo que Ner'zhul acumulara aún más poder, como si sus espíritus le proporcionaran el alimento necesario. Descubrió que era un juego de niños controlar las acciones de los zombis y hacer que realizaran todo aquello que deseaba.", "En los siguientes meses, Ner'zhul continuó experimentando con su peste de los no-muertos, sometiendo a todos los habitantes humanos de Rasganorte. Con su ejército de no-muertos creciendo a diario, sabía que se acercaba el momento de realizar la verdadera prueba." } } },
    ["Important Blackrock Documents"] = { { ids = { "i12562" }, first = "wyrmthalakihavebeengiven", pages = { "Vermiothalak:\n\nHe recibido órdenes directas de tu maestro, Nefarian, para castigarte como crea conveniente en el caso de que más forasteros entren en la ciudadela.\n\nNo olvides quién te manda, reptil.\n\nEl hijo de Puño Negro: Maestro de la espada y la batalla. El verdadero Jefe de Guerra.\n\nRend" } } },
    ["In Loving Memory"] = { { ids = { "o181062" }, first = "anthonyraystark", pages = { "Anthony Ray Stark\n\n1961 - 2005" } } },
    ["Invar One-Arm"] = { { ids = { "o175778" }, first = "invaronearmthefirstchief", pages = { "Invar Unibrazo\n\nPrimer asesino jefe de la Cruzada Escarlata\n\nCiudadano de Dalaran\n\nVisto por última vez en las costas de Rasganorte" } } },
    ["Ironband's Progress Report"] = { { ids = { "i2637" }, first = "honorablecolleaguesandtr", pages = { "Honorables compañeros y sabios buscaverdad\n\nLa excavación continúa, pero su ritmo ha disminuido debido a los troggs que mencioné en mi último informe. Confío en que los neutralizaremos, aunque algunos son más agresivos de lo habitual.\n\nRecientemente se encontraron más artefactos, si bien en todos los casos, salvo en uno (que en breve detallaré), los recientes hallazgos tienen la misma relevancia que los anteriores: son interesantes, pero no esclarecedores.", "Hubo una excepción. Los ídolos tallados recientemente encontrados (una breve descripción de los mismos aparece en mi último informe) parecen afectar de algún modo a los troggs. Se sienten atraídos por la talla en piedra y algunos troggs enloquecen ante su presencia.\n\nEs preciso estudiar este fenómeno con mayor profundidad para llegar a una conclusión válida en relación con estos ídolos, si bien espero que el estudio arroje luz sobre un posible vínculo entre los troggs y los titanes.", "Finalmente, debo reiterar mi petición para que se me suministre más pólvora. Mis suministros son muy escasos, lo que dificulta seriamente el éxito de la excavación. Me dijeron que un nuevo suministro de pólvora estaba en camino, sin embargo aún no he recibido nada.\n\n¿Puedo preguntar a qué se debe este retraso?\n\nRespetuosamente,\nProspector Darteus Vetaferro" } } },
    ["Ironforge - the Awakening of the Dwarves"] = { { ids = { "o175736" }, first = "intheancienttimesafterth", pages = { "En la antigüedad, cuando los titanes partieron de Azeroth, sus hijos, conocidos como los terráneos, continuaron dando forma y vigilando los oscuros recovecos del planeta. Los terráneos eran indiferentes a los asuntos de las razas que poblaban la superficie y solo les interesaba sondear las lóbregas profundidades de la tierra.", "Los terráneos quedaron muy afectados tras la implosión del Pozo de la Eternidad que había destruido el planeta. Al no poder recuperarse del dolor causado por la destrucción de la tierra, los terráneos perdieron gran parte de su identidad y se encerraron en las cámaras de piedra en las que habían sido creados inicialmente. Uldaman, Uldum, Ulduar... eran los nombres de las antiguas ciudades de los titanes que los terráneos habían construido inicialmente. Enterrados en las profundidades del planeta, los terráneos descansaron en paz durante casi ocho mil años.", "Aunque se desconoce qué fue lo que los despertó, los terráneos confinados en Uldaman finalmente despertaron de su sueño autoimpuesto. Se dieron cuenta de que habían cambiado significativamente durante la hibernación. Sus rocosos pelajes se habían suavizado, convirtiéndose en tersas pieles, mientras que sus poderes sobre la piedra y la tierra habían menguado. Se habían convertido en criaturas mortales.", "Los últimos terráneos se hicieron llamar enanos y abandonaron las salas de Uldaman para aventurarse en el mundo de los seres despiertos. Adormecidos aún por la paz y las maravillas de las profundidades, fundaron un vasto reino bajo la montaña más alta de la tierra.", "Llamaron a su tierra Khaz Modan, o \"Montaña de Khaz\", en honor a su creador, el titán Khaz'goroth. Al construir un altar para su padre titán, los enanos crearon una gran fragua en el corazón de la montaña. Por ello, la ciudad que creció en torno a la fragua recibió el nombre de Forjaz.", "Los enanos, fascinados por la talla de la piedra y las gemas, se dedicaron a excavar las montañas vecinas para encontrar ricos y preciosos minerales. Satisfechos con sus trabajos subterráneos, permanecían aislados de lo que acontecía a sus vecinos de la superficie." } } },
    ["Jitters' Completed Journal"] = { { ids = { "i2560" }, first = "myjournaltheterrorofthes", pages = { "Mi diario:\n\nEl terror experimentado durante las últimas semanas casi supera lo que soy capaz de soportar. ¿Por qué cuando lo escribo todo en este libro, de alguna manera evito caer en la locura? Quizás sea como confesar mis pecados a un compañero silencioso, liberando mi mente de tortuosos pensamientos y confinándolos en el papel.\n\nEmpecé un diario antes de escribir este, pero permanece en un lugar al que no podré regresar. Por eso empezaré desde cero. Pero esta vez, empezaré desde el verdadero principio.", "Todo empezó con el hallazgo de esa maldita hoz en la mina conocida como Condena de Roland. Sí, ahí empezó todo. Antes de que aquello ocurriera, la Hermandad Defias estaba satisfecha con nuestros avances en el Bosque del Ocaso. Antes de que apareciera la guadaña, los terrores de este lugar parecían tan mansos como el valle de Villanorte.\n\nPero desde que encontré el mango de la guadaña sobresaliendo entre la pila de escombros en la mina y lo saqué de ahí, ¡ay de mí!, ¡la Condena de Roland se ha convertido en un lugar de destrucción y muerte!", "Si hubiera sabido lo que iba a suceder, habría cortado mi propia mano antes de tocar ese trozo de madera tallada con runas. ¡Cuánto arrepentimiento! Pensé que ese era solo un privilegio de los ancianos. Ahora sé que no son los ancianos, sino los desesperados, los que visten el manto del arrepentimiento, incapaces y sin deseos de quitárselo de los hombros, encorvados por el sufrimiento.\n\nAhora basta de poesía barata. Debo continuar con esta crónica...", "Tras el rescate de la guadaña, en la mina empezaron a ocurrir cosas extrañas. La luz procedente de nuestras antorchas parpadeantes se deformaba y la fuerza de nuestras voces parecía escapar a nuestro control. A veces, el susurro de un hombre provocaba un estruendo que atravesaba los túneles, obligando a los demás a taparse los oídos y, en otras ocasiones, nuestros gritos apenas se oían a unos cuantos metros antes de apagarse como un soplo en el viento.\n\nCiertamente, era desconcertante, pero rápidamente dejamos de extrañarnos por lo insólito del asunto. Lo que en realidad nos apartó de la mina, fue un presagio. El ferocanis.", "Emergieron desde todos los rincones, clavando sus zarpas en nuestros tobillos desde ocultos agujeros y cayendo sobre nosotros desde lo alto. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, entre los que me incluyo, intentaron escapar. A medida que corría, veía a mis hermanos atrapados por la zarpa y el colmillo, oí tantos alaridos truncados o desvaneciéndose en el silencio.\n\nHasta donde tengo conocimiento, fui el único humano que escapó de aquel lugar.", "Solo puedo suponer por qué sobreviví aquella noche. Siempre he sido cuidadoso, rápido a la hora de escapar de las fauces de alguna bestia, o cuando se trataba de saltar algún escollo. Mi sobrenombre, Gato, obedece a esta característica. Así que tal vez fue el don de la prudencia lo que me salvó...\n\nO tal vez fue la guadaña que extraje de los escombros. No puede ser la guadaña, puesto que la perdí durante mi frenética huida. Pero si fui yo quien atrajo los ferocanis al Bosque del Ocaso, quizás me hayan hecho un extraño obsequio. ¡Los maldigo!", "O quizás, estoy condenado a presenciar los cambios que he traído al Bosque del Ocaso. Quizás sea mi destino contemplar la invasión de ferocanis en estas tierras, contaminándolas paulatinamente con su podredumbre.\n\nSi esa es mi suerte, tiene dos caras. Porque los ferocanis no son la única fuerza que se ha apoderado del Bosque del Ocaso: los demonios del Paso de la Muerte también han reclamado su parte.\n\nEse será el último capítulo de mi historia, y rezo porque sea el último...", "Tras sobrevivir a la huida de la Condena de Roland, me oculté en el granero de un hombre llamado Sven. Pasé unos cuantos días en el granero y aquel horror caló tan hondo en mí que nunca me presenté ante Sven o su familia. Pero considerando lo que vi desde mi escondite, me di cuenta de que aquellos granjeros eran personas bastante decentes. De haber salido de mi refugio, seguramente me habrían aceptado, pero me cuesta confiar en los demás. Y mucho más después de aquella impresión en la mina.\n\nAsí que permanecí escondido. Y por ello salvé mi vida.", "Pocos días después de llegar al granero, Sven abandonó su granja para partir a Villa Oscura. Besó a su mujer, sonrió a sus hijos y prometió volver pronto con regalos y golosinas. Pobre hombre. Fue la última vez que vio a su familia sana y entera.\n\nAl menos se despidieron contentos. Y por suerte, su mujer fue la primera en morir, evitando el dolor de ver cómo asesinaban a sus hijos. Pero estas supuestas contrapartidas no me compensarán tanto dolor. Vi lo que ocurrió y la escena siempre me perseguirá en sueños.", "Me tiemblan las manos cuando recuerdo los detalles de aquella noche, Sven estaba ausente y su familia tuvo que enfrentarse sola a los jinetes negros. El remordimiento vuelve a consumirme, pues yo estaba allí y pude haber luchado contra aquellos demonios del Paso de la Muerte. Pero es falso remordimiento. Es el mismo que abruma a cualquier superviviente de una tragedia. Sé que de haber abandonado mi escondite también habría muerto desgarrado y descuartizado, los miembros esparcidos por todas partes hasta quedar irreconocible.", "Pero a pesar de saber que no habría podido hacer nada para detener aquel atroz asesinato, perdura el sentimiento de culpabilidad: Fui yo quien atrajo a los jinetes negros hasta la granja de Sven. Mi descubrimiento de la guadaña no solo desató a los ferocanis hasta el Bosque del Ocaso, sino que atrajo a los jinetes del Paso de la Muerte.\n\nLo sé porque antes de iniciar la masacre, formularon una pregunta a la mujer de Sven mientras esta aferraba a sus hijos, ofreciéndoles consuelo, a pesar de presentir la inminencia de su muerte.", "\"La Guadaña de Elune\", gritó uno de los jinetes en un tono áspero y estridente a la vez, como el chirrido de un hacha sobre la piedra. La última palabra, Elune, brotó en un grito ahogado.\n\nEl terror se apoderó de mí cuando escuché aquella voz, no solo por su tono espantoso, sino porque sabía a qué guadaña se refería el jinete. Debe de tratarse del mismo objeto abominable que extraje de las rocas en la Condena de Roland hace unos días, pensé. ¡Es lo que los jinetes negros estaban buscando!\n\nY es lo que mató a la familia de Sven.", "\"Nunca supe el nombre de la mujer de Sven, ya que su marido y sus hijos solo la llamaban \"querida\", \"mi amor\" o \"mami\". Pero me habría gustado saberlo. Soy el único recuerdo viviente de su valerosa actuación aquel fatídico día y, a pesar de tratarse tan solo de la mujer de un granjero, jamás vi a hombre o mujer proceder con tanta valentía. Si tan solo hubiera servido para algo\".", "\"¿La Guadaña?\", dijo tranquilamente. \"Claro que sí. ¿Quién no la ha visto por aquí?\" Miró a los jinetes con firmeza y, de no conocer los hechos, yo habría jurado que decía la verdad. ¡Era imposible que supiera lo de la Guadaña.\n\nSu estrategia daba resultado. El mismo jinete que formuló la pregunta se inclinó ligeramente hacia ella y chilló: \"¿Dónde?\"\n\n\"Te llevaré hasta ella. Todos vosotros,\" dijo, y pude observar un destello de esperanza que asomaba a sus ojos.", "\"Pero el camino es largo y mis hijos solo nos harán ir más despacio. Debemos dejarlos aquí.\"\n\nSu coartada era simple, pero son ese tipo de coartadas las que mayor éxito tienen. Si funcionaba, al menos alejaría a los jinetes de la granja. Ella habría sucumbido, pero sus hijos estarían a salvo. Y, de no ser porque los jinetes se creyeron sus nobles mentiras, habría funcionado.\n\nA pesar de que nunca he sido estudioso de la Luz, recé con fuerza por la vida de la mujer de Sven mientras plantaba cara a aquellos terribles jinetes.\n\n\"Por favor\", recé. \"Haz que se lo crean.\"", "Se quedaron ahí, paralizados, mientras ella los miraba a los ojos con tranquilidad. Uno de los jinetes miró hacia arriba, como si escuchase una llamada a lo lejos. Extrajo de sus ropajes una pequeña gema y miró en su interior. Luego hizo un gesto, apuntando con la gema hacia la mujer de Sven. Una luz se deslizó desde el jinete hasta la mujer, adquiriendo la forma de una mano blanca y lúgubre. Ella contempló la luz, inmutable, pero pude observar cierta incertidumbre tras su máscara de confianza. Cuando la mano la alcanzó, rodeó su cabeza con los dedos.\n\nLuego la apretó con fuerza.", "La mujer de Sven permaneció rígida como una tabla y sus ojos se abrieron al máximo. A pesar de que sus labios hicieron la mueca de un grito, no dejaron escapar sonido alguno. Tras unos minutos de tortura, la mano soltó a la mujer, dejándola caer de rodillas. El jinete que sujetaba el abalorio se irguió sobre su silla y una potente voz emergió de su interior.\n\n\"Esta mujer miente\", afirmó en un tono que aún retumba en mis sueños. \"No ha visto la Guadaña.\"", "Tras este suceso, los hombros del jinete se encorvaron ligeramente, como si un espíritu hubiese abandonado su cuerpo. Luego, en el antiguo tono chirriante, pronunció las siguientes palabras:\n\n\"El Señor ha hablado. Matadlos.\"", "No puedo describir lo que ocurrió a continuación. Los recuerdos son vívidos, pero mi alma desgraciada no puede plasmar sobre el papel lo que allí sucedió en aquellos espeluznantes momentos.\n\nSolo puedo escribir que la familia de Sven fue asesinada. Poco después, Sven regresó a este escenario de muerte y horror. Estaba tan destrozado, que tuve miedo de salir de mi escondite. Tanto temía que me encontrara, que huí de mi refugio en el granero. No sé dónde está Sven ahora, pero espero que, algún día encuentre la paz.", "He pasado las últimas semanas de un lado para otro, sin permanecer mucho tiempo en ningún sitio por miedo a los jinetes. Ahora me encuentro en la ciudad abandonada de Cerro del Cuervo, oculto, como siempre. No podría enfrentarme al poder que utilizaron contra la mujer de Sven y sé que continúan buscando la Guadaña en el Bosque del Ocaso. La he perdido y, gracias a la Luz esto es así, puesto que, de conservarla, sé que me habrían encontrado. De hecho, en lo más profundo sigo convencido de que me encontrarán.\n\nEstoy tan cansado." } } },
    ["Jordan's Weapon Notes"] = { { ids = { "i6996" }, first = "beforeigoanyfurtherletme", pages = { "$N,\nAntes de continuar, permíteme que te vuelva a dar las gracias por todo lo que hiciste por mi mujer. Le salvaste la vida y no me bastan cien vidas para agradecértelo. Ella lo es todo para mí. Si hubiera muerto... no sé qué habría hecho.\n\nAquí tienes un listado con todo lo que tienes que reunir para fabricarte un arma sagrada. He puesto todos los elementos ordenados según lo fácil que resulta conseguirlos. Espero que eso te facilite las cosas.", "Un poco de madera de roble de Piedrablanca: Esta madera abundaba en las minas que hay debajo de Arroyo de la Luna, en los Páramos de Poniente, antes de que fueran usurpadas. De hecho, la usaban para construir algunos de los enrejados y herramientas más importantes, debido a su resistencia al calor y a la presión.\n\nFue llevada hasta allí después de que la trajeran en barco desde algún lugar de ultramar. Se trata de una madera escasa suficientemente resistente como para usarla en la fabricación de tu arma. En el caso de que aún haya restos de esta madera en las minas, lo más probable es que los goblins Tallamadera tengan un poco.", "Mineral refinado: Hay un enano en Thelsamar, un herrero al que he instruido durante un tiempo, llamado Bailor Petramano. Obtiene una aleación muy especial que creo que sería perfecta para tu arma. Esperaba un cargamento de esa aleación cuando estaba en Forjaz, pero aún no he recibido noticias de él.\n\nEncuéntralo y averigua qué ha pasado con ese cargamento. Y si mi antiguo maestro ya no está en Loch Modan, al menos me gustaría saber qué ha sido de él.", "Martillo de herrería: Antes de la llegada de la Peste y de la traición de Arthas, yo vivía en una ciudad llamada Piroleño, enclavada en el hermoso bosque de Argénteos. El bosque ha perdido el esplendor del pasado, y el fuerte en el que aprendí los secretos del acero ya no es lo que era, pues ahora lo habitan criaturas de maldad inimaginable.\n\nCuando mi mujer y yo escapamos de lo que ahora se conoce como el Castillo de Colmillo Oscuro, abandonando algunas de nuestras más queridas pertenencias.", "Entre ellas estaba el martillo de herrería que mi dejó mi padre. Cuando era joven no hice caso a sus palabras al afirmar que ese martillo estaba encantado. Fue el último recuerdo que tuve de él antes de que la Plaga lo matara.\n\nTráeme mi martillo, $N, para que vuelva a infundirme todo el entusiasmo. Si realmente está encantado, solo nos será útil a ambos.\n\nLo dejé en los establos en el patio principal del fuerte. A menos que las criaturas que allí viven hayan decidido dedicarse a la herrería, espero que siga ahí.", "Una gema Kor - Según me ha contado, estas gemas las utilizan algunos hechiceros para obtener su energía y sus poderes, lo que los hace aún más peligrosos. Un elfo de la noche a quien un día ayudé, Thundris Tejevientos, podrá darte más detalles, pues irás de mi parte. Creo que ciertas energías almacenadas en la gema pueden servir para crear tu arma.\n\nCuando hablamos por última vez, Thundris estaba en Auberdine, un pueblo en medio de Costa Oscura, el bosque corrupto que salpica la costa bajo la sombra de la tierra de los elfos de la noche." } } },
    ["Journal Page"] = { { ids = { "i5839" }, first = "itneverceasestoamazemeho", pages = { "No deja de maravillarme lo útil que resulta el odio para que los demás cedan a tus deseos. Los orcos y los trols fueron los más fáciles de engañar, ya que su odio a la Alianza los convierte en serviles sujetos de la Facción Oscura. ¿Acaso tienen idea del poder superior al que sirven?\n\nEse paladín exasperante, Delgren el Purificador, se ha estado metiendo en nuestros asuntos del bosque de Vallefresno, mientras que su lacayo, Balthule, espía mi torre, creyendo que no me percato de su presencia. Delgren nos considera", "una amenaza menor, tal vez otro culto a la muerte. No sabe que somos nada más y nada menos que... una de las facciones del Consejo de la Sombra.\n\nCuando era niño, me hablaron de un insecto cuya picadura era mortal, pero cuyo aspecto era el de una simple mosca, un puntito difícil de reconocer. Son las cosas que subestimas las que más te hieren, si dejas que la herida se encone." } } },
    ["Kearnen's Journal"] = { { ids = { "i8046" }, first = "theguardsofthistowerseem", pages = { "Los guardias de esta torre parecen ser especialmente vulnerables a mis ataques. Mientras observaba la parte trasera de la torre, una patrullera me vio y me atacó. Pude matarla de un disparo, asestándole después una puñalada por la espalda.\n\nMe oculté y esperé a que llegara su compañero para averiguar qué había pasado. El patrullero se acercó a los arbustos hasta donde yo había arrastrado el cadáver e inició la búsqueda. Lentamente y con cuidado, me le acerqué por detrás, procurando evitar que descubriera mi emboscada.", "Cuando tuve la oportunidad, ¡clavé muy puñal en su espalda! Sus pulmones fallaron rápidamente ante la fuerza del ataque, mientras su cadáver caía al suelo con un ruido sordo.\n\nFue una emboscada tan rápida y violenta, que el pobre idiota no tuvo siquiera tiempo de gritar de dolor. Curiosamente, cuando extraje el puñal de su espalda, el cuerpo del patrullero acuchillado desprendió un hedor espantoso.", "Al parecer, lo que Klaven ha guardado en el cofre bajo llave está afectando negativamente a los habitantes de la torre. Sospecho que los demás guardias presentan un decaimiento similar y, tal vez, incluso el propio Klaven también está afectado.\n\nAgente Amber Kearnen\nSI:7 Espía sobre el nivel del suelo, R8" } } },
    ["Kel'Thuzad and the Forming of the Scourge"] = { { ids = { "o175754" }, first = "therewereahandfulofpower", pages = { "Había un puñado de individuos poderosos esparcidos por el mundo, que oyeron las peticiones mentales del rey Exánime desde Rasganorte. El más destacable de estos personajes era el archimago de Dalaran, Kel'Thuzad, que era uno de los miembros principales del consejo de gobierno de Dalaran, el Kirin Tor. Durante años, había sido considerado un inconformista, debido a su insistencia en estudiar las prohibidas artes de la necromancia.", "Decidido a aprender todo lo que pudiera del mundo mágico y de sus oscuras maravillas, se vio frustrado por lo que consideró una serie de preceptos pasados de moda y carentes de imaginación de sus pares. Tras oír las poderosas invocaciones procedentes de Rasganorte, el archimago concentró toda su voluntad, intentando comunicarse con la misteriosa voz. Convencido de que el Kirin Tor era demasiado impresionable como para adoptar el poder y el conocimiento inherente a las artes oscuras, se resignó a aprender todo cuanto podía del inmensamente poderoso rey Exánime.", "Olvidando su fortuna y su prestigio político, Kel'Thuzad abandonó los caminos del Kirin Tor, dejando Dalaran para siempre. Empujado por la persistente voz del rey Exánime que oía en su mente, vendió sus vastas posesiones y guardó su fortuna. Atravesando a solas muchas leguas tanto por tierra como por mar, finalmente alcanzó las heladas costas de Rasganorte.", "Intentando llegar a Corona de Hielo para ofrecer sus servicios al rey Exánime, el archimago atravesó las saqueadas y destruidas ruinas de Azjol-Nerub. Kel'Thuzad comprobó de primera mano el alcance y la ferocidad del poder de Ner'zhul. Empezó a darse cuenta de que aliarse con el misterioso rey Exánime podía ser al mismo tiempo una decisión sabia y potencialmente fructífera.", "Tras arduos meses recorriendo las duras y baldías tierras árticas, finalmente Kel'Thuzad llegó al oscuro glaciar de Corona de Hielo. Con audacia, se acercó a la ciudadela negra de Ner'zhul y quedó muy impresionado cuando los guardias no-muertos le dejaron pasar silenciosamente, como si estuvieran esperándole.", "Kel'Thuzad descendió a las profundidades de la tierra helada y se dirigió hacia la base del glaciar. Allí, en la interminable caverna de hielo y sombras, se postró ante el Trono Helado y ofreció su alma al oscuro señor de los muertos.", "El rey Exánime estaba muy complacido con su más reciente adepto. Prometió a Kel'Thuzad la inmortalidad y grandes poderes a cambio de su lealtad y obediencia. Hambriento de conocimientos y poderes oscuros, Kel'Thuzad aceptó su primera gran misión: adentrarse en el mundo de los hombres y fundar una nueva religión que adoraría al rey Exánime como a un dios.", "Para ayudar al archimago a cumplir su misión, Ner'zhul dejó intacta la humanidad de Kel'Thuzad. El viejo, pero aún carismático mago, recibió el don de utilizar sus poderes de ilusión y persuasión para adormecer a las oprimidas masas de Lordaeron y lograr que confiaran y creyeran de nuevo. Luego, una vez que lograra captar su atención, les ofrecería una nueva visión de lo que podría ser la sociedad - y un nuevo mascarón de proa al que pudieran considerar rey.", "Kel'Thuzad regresó a Lordaeron disfrazado y, por espacio de tres años, utilizó su fortuna y su intelecto para reunir a una hermandad clandestina de hombres y mujeres de ideas afines. La hermandad, a la que denominó el Culto de los Malditos, prometió a sus acólitos igualdad social y la vida eterna en Azeroth a cambio de su servicio y obediencia a Ner'zhul.", "A medida que pasaron los meses, Kel'Thuzad encontró muchos voluntarios ansiosos para su nuevo culto entre los cansados y explotados trabajadores de Lordaeron. Kel'Thuzad alcanzó sus objetivos con sorprendente facilidad: concretamente, logró convertir la fe de los ciudadanos en la Luz Sagrada en una creencia en la oscura sombra de Ner'zhul. A medida que el Culto de los Malditos creció en tamaño e influencia, Kel'Thuzad se aseguró de que sus actividades quedaran ocultas a ojos de las autoridades de Lordaeron.", "Gracias al éxito de Kel'Thuzad en Lordaeron, el rey Exánime realizó los preparativos finales para asaltar la civilización humana. Tras volcar su energía corrupta sobre diversos artefactos portátiles llamados calderas de la peste, Ner'zhul ordenó a Kel'Thuzad que llevara las calderas a Lordaeron, ocultándolas en varios poblados leales.", "Las calderas, protegidas por fieles seguidores, actuarían como generadores de peste, dispersándola a través de los indefensos campos y ciudades del norte de Lordaeron.", "El plan del rey Exánime funcionó a la perfección. Muchos poblados del norte de Lordaeron se contaminaron casi de inmediato. Como ocurrió en Rasganorte, los ciudadanos que contrajeron la peste murieron y renacieron como esclavos del rey Exánime.", "Los seguidores de Kel'Thuzad deseaban morir para renacer al servicio del señor de las tinieblas. Se regocijaban ante la perspectiva de alcanzar la inmortalidad de los no-muertos. Con la propagación de la peste, cada vez más zombis ferales se alzaron en las tierras del norte. Kel'Thuzad observó el ejército del rey Exánime y lo nombró la Plaga, pues pronto marcharía hasta las puertas de Lordaeron... borrando a la humanidad de la faz de la tierra." } } },
    ["Keldara's Log"] = { { ids = { "i221017" }, first = "dayibelieveivediscovered", pages = { "Día 14:\n\nCreo que he descubierto una forma de revertir la corrupción que trajo el sátiro: ¡una tintura preparada con su propio añublo!\n\nCon muestras de hierba de sátiro de los alrededores, se podría crear un extracto que proteja contra la corrupción total por medio de la exposición a una pequeña cantidad. Podría considerarse casi un antídoto.\n\nMe gustaría probar la cura en la fauna local, pero las bestias de la zona son demasiado agresivas. Ojalá pudiera tranquilizarlas de algún modo." } } },
    ["Khazgorm's Journal"] = { { ids = { "i5006" }, first = "theexcavationofbaelmodan", pages = { "La excavación de Bael Modan\n\nEl equipo de exploración original enviado por la Liga de Expedicionarios acertó en sus descubrimientos. El suelo oculta artefactos de valor ilimitado para nuestra gente. Indudablemente, encontraremos muchas respuestas en nuestra búsqueda de sabiduría entre las arenas y las rocas de Bael Modan.\n\nSin embargo, la geología de la región implica que debemos extremar la precaución. Muchos de los depósitos de arena se han solidificado, debido a las duras condiciones y al cambiante clima.", "Sin embargo, la solución resulta muy simple. Utilizando pasta de madera como absorbente, podemos combinar partes de nitroglicerina con nitrato sódico para desarrollar una potente carga explosiva, capaz de pulverizar incluso las masas más densas.\n\nTodo esto será ruidoso y perturbador, pero nuestra búsqueda tiene mucha más importancia que la comodidad de los habitantes locales. De hecho, ya hemos expulsado a una banda de minotauros de la zona, que resultaron ser un incordio.", "El hecho de que estemos tratando con verdaderos bribones me lleva a creer que necesitaremos la ayuda del ejército del rey. La excavación no solo requerirá apoyo militar. En realidad, teniendo en cuenta el mundo de la política en su estado actual, tengo la sensación de que la propia situación de Bael Modan podría tener un alto valor estratégico para la Alianza.\n\nVaya, me he apartado de la cuestión. Bajo estas rocas, hay mucho trabajo que hacer. He estado demasiado tiempo escribiendo, en lugar de excavar..." } } },
    ["Kil'jaeden and the Shadow Pact"] = { { ids = { "o175741" }, first = "aroundthetimeofmedivhsbi", pages = { "En la época del nacimiento de Medivh en Azeroth, Kil'jaeden el Impostor daba vuelta entre sus seguidores en el vacío abisal. El astuto señor de los demonios, bajo las órdenes de su maestro Sargeras, estaba planeando la segunda invasión de Azeroth por parte de la Legión Ardiente.", "Ahora no se podía cometer ningún error. Kil'jaeden suponía que necesitaban nuevas fuerzas para debilitar las defensas de Azeroth incluso antes de que la Legión pudiera poner un pie en el mundo. Si las razas mortales, como los elfos de la noche y los dragones, fueran obligadas a hacer frente a una nueva amenaza, estarían demasiado debilitadas para oponer resistencia real cuando llegara la verdadera invasión de la Legión.", "Fue entonces cuando Kil'jaeden descubrió el exuberante mundo de Draenor flotando apaciblemente en el interior de la Gran Oscuridad del Más Allá. Hogar de los orcos organizados en clanes de inspiración chamánica y de los pacíficos draenei, Draenor era tan idílico como extenso.", "Los nobles clanes de los orcos vagaban por las extensas praderas y cazaban por deporte, mientras los curiosos draenei construían rudimentarias ciudades dentro de los altísimos acantilados y picos del mundo. Kil'jaeden sabía que, en el caso de que fueran adecuadamente adiestrados, los moradores de Draenor tenían un gran potencial para servir a la Legión Ardiente.", "De las dos razas, Kil'jaeden vio que los orcos guerreros eran más susceptibles de sucumbir a la corrupción de la Legión. Se ocupó de embelesar al chamán orco más viejo, Ner'zhul, de la misma manera que, en el pasado, Sargeras puso a la reina Azshara bajo su control. Utilizando al astuto chamán como su conducto, el demonio extendió el deseo de lucha y el salvajismo entre los clanes orcos.", "No pasó mucho tiempo antes de que la raza espiritual se transformara en un pueblo sediento de sangre. Luego, Kil'jaeden urgió a Ner'zhul y a su gente a que dieran el último paso: dedicarse en cuerpo y alma a la guerra y a la muerte. Aun así, el viejo chamán, sintiendo que su gente iba a ser esclavizada en el odio para siempre, mostró resistencia ante las órdenes del demonio.", "Frustrado por la resistencia de Ner'zhul, Kil'jaeden buscó a otro orco que pudiera poner a su pueblo en las manos de la Legión. Finalmente, el astuto señor de los demonios encontró al discípulo dispuesto que buscaba: Gul'dan, el ambicioso aprendiz de Ner'zhul. A cambio de su obediencia ciega, Kil'jaeden prometió a Gul'dan poderes inefables.", "El joven orco se convirtió en un ávido estudiante de magia demoníaca y se transformó en el brujo mortal más poderoso de la historia. Enseñó a otros jóvenes orcos las artes arcanas y se esforzó por erradicar las tradiciones chamánicas de los orcos. Gul'dan enseñó una nueva clase de magia a sus hermanos, un nuevo poder terrible que apestaba a condena.", "Kil'jaeden, en el deseo de aumentar su dominio sobre los orcos, ayudó a Gul'dan a encontrar al Consejo de la Sombra, una secta secreta que manipulaba a los clanes y extendía el uso de la brujería por todo Draenor. A medida que más y más orcos ejercieron las artes de brujería, los suaves campos y las corrientes de Draenor comenzaron a mancillarse y a desvanecerse. Con el tiempo, las vastas praderas que los orcos habían considerado su hogar durante generaciones, se marchitaron, dejando exclusivamente estériles suelos rojizos. Lentamente, las energías demoníacas estaban acabando con el mundo." } } },
    ["King Llane I of the House of Wrynn"] = { { ids = { "o177200" }, first = "kingllaneiofthehouseofwr", pages = { "Rey Llane I de la Casa de Wrynn\n\nSeñor Feudal de Ventormenta\n\nDefensor de Azeroth" } } },
    ["Klaven Mortwake's Journal"] = { { ids = { "i7908" }, first = "theventurecompanyitwould", pages = { "La empresa Ventura y Cía. <texto ilegible> Al parecer, esos idiotas casi eliminan toda la operación, intentando estabilizar la mezcla.\n\n<muchas páginas parecen haber sido arrancadas>", "Lo que he notado es que la carga radiactiva es absolutamente letal. Imagina si <texto ilegible> ¡Ja, ja, ja, ja!", "¿Estoy perdiendo el juicio? Hoy le abrí la cabeza a uno de mis patrulleros más fieles para poder ver mejor dentro de su alma. Mientras observaba detenidamente su conducto respiratorio destrozado, pensé: ¡No he comido nada en varios días!", "Mathias Shaw había mandado a su chico de los recados para que me matara. <texto ilegible>\n\nÉl ahora patrulla el exterior. Esclavo autómata descerebrado y sin vida.\n\n¡Ja, ja, ja. ja!", "VanCleef...<texto ilegible>\n\n¿Me ha llamado para que ENTRARA?? ¿¿QUIÉN SE CREE QUE ES?? ¡Soy Klaven Mortoalerta! ¡Un insecto como él no puede decirme lo que tengo que hacer!\n\n<faltan las páginas restantes del libro>" } } },
    ["Kodo Skin Scroll"] = { { ids = { "i5838" }, first = "tofacefrostmawyoumustent", pages = { "Para enfrentarte a Faucehielo, debes atraerlo con la carne de su presa favorita.\n\nDirígete a las montañas de Alterac en Azeroth y caza un león de montaña de gran tamaño. Mátalo y luego lleva su cuerpo a la Caverna Estrecha, un lugar que los bestiales wendigo consideran sagrado.\n\nColoca el cuerpo sobre la Llama de Uzel para que el olor de la carne quemada se disperse en el aire, hacia el exterior de la caverna.\n\nComprobarás que, transcurrido un tiempo, Faucehielo vendrá." } } },
    ["Kravel's Parts Order"] = { { ids = { "i5799" }, first = "ordernumbertkbuyerkravel", pages = { "NÚMERO DE ENCARGO: 45TK-3\nCOMPRADOR: Kravel Karbarbán\n\nFACTURA:\n\nCarraca hidráulica (3)\nPernos de repetición (50)\n30\" tubos de cobre calibre 20 (12)\nTabaco marca Furiahonda (1)\nPrismas de alta graduación (3)" } } },
    ["Kravel's Scheme"] = { { ids = { "i5826" }, first = "mrfizzlebubthebearerofth", pages = { "Sr. Pinchabujas:\n\n$gEl portador:La portadora; de esta carta y yo mismo estamos montando un negocio conjunto en el que nos gustaría que participaras.\n\nComo bien sabes, he pasado mucho tiempo en el Desierto de Sal (el negocio mencionado anteriormente está relacionado con las carreras que se organizan en este desierto).\n\nSi te interesan las carreras y, para ser más específicos, apostar a ellas, querrás continuar leyendo, ya que creo que tus conocimientos sobre Tuercespina serían muy útiles en nuestro negocio.", "Los coches cohete que compiten por los desiertos han sido preparados y requieren bastante mantenimiento. Por eso no debe sorprender que haya equipos de boxes por todas partes.\n\nEstos equipos comprueban constantemente el estado de sus coches y efectúan reparaciones y modificaciones cuando es necesario. Es la única manera de que los coches alcancen el máximo rendimiento.\n\nPor esta razón, buscamos la manera de provocar algún fallo en las maniobras del equipo de boxes para que el coche se averíe rápidamente.", "Si somos capaces de controlar qué coche está en plena forma y cuál no, entonces... No tengo que explicarte las ventajas que esto nos proporciona en el juego.\n\nPor eso, Pinchabujas, necesitamos que nos proporciones algo para hacer que el equipo de boxes cometa fallos.\n\n¿Hay en Tuercespina alguna planta, hierba o bebida que pueda usarse para trastocar la mente de los gnomos y los goblins?\n\nK. Karbarbán" } } },
    ["Kristof's Report"] = { { ids = { "i286201" }, first = "executorzyganditismyopin", pages = { "Ejecutor Zygand:\n\nEn mi humilde opinión, las fuerzas de la Plaga presentes en nuestras tierras no son resultado de una defensa negligente. Llevo un tiempo observando a nuestras fuerzas en El Baluarte y la estación oriental, y sería necesario un verdadero ejército para atravesarlas.\n\nEn lugar de ello, sospecho que la Plaga está siendo creada dentro de nuestras fronteras por algún enemigo oculto. Seguiré investigando este asunto con la esperanza de erradicar este problema.\n\nKristof" } } },
    ["Kurdran Wildhammer"] = { { ids = { "o25329" }, first = "kurdranwildhammerrenowne", pages = { "Kurdran Martillo Salvaje\n\nCélebre combatiente de dragones. Maestro de grifos de Pico Nidal. Comandante de la división de jinetes de grifos de la Expedición de la Alianza que marchó al mundo natal de los orcos, Draenor. Presuntamente fallecido.\n\nOiremos las llamadas de Sky-Ree en el viento. Oiremos tronar tu martillo sobre las cumbres. Cabalga con fuerza hacia el más allá, hermano. Los salones de nuestros antepasados te esperan.\n\n- Gran señor feudal Falstad Martillo Salvaje" } } },
    ["Lady Mara Fordragon"] = { { ids = { "o177202" }, first = "ladymarafordragonhighcle", pages = { "Lady Mara Fordragon\n\nAlta sacerdotisa de Ventormenta\n\nPatrona de los refugiados que huyeron de Lordaeron tras la Primera Guerra.\n\nFue la brillante madre de nuestro futuro. Que descanse en la Luz." } } },
    ["Laird's Response"] = { { ids = { "i16263" }, first = "nessaitisgoodtohearfromy", pages = { "Nessa,\n\nMe alegra tener noticias tuyas.\n\nLa colección de huesos y escamas que me enviaste era increíble. Nunca había visto peces de ese tamaño cerca del continente. ¡Los pescadores de Rut'theran deben conseguir toneladas de pescados por día sin esfuerzo!\n\nMe da envidia el tamaño de sus presas, pero también hay algo que me inquieta. ¿Qué tal si nuestro nuevo Árbol del Mundo hace que los peces crezcan hasta ese tamaño? Y en ese caso, ¿qué otros efectos podría tener?\n\nTantas preguntas...\n-Laird" } } },
    ["Legacy of the Aspects"] = { { ids = { "i5860" }, first = "ihavedoneagreatdealofres", pages = { "He investigado a fondo a los Aspectos y a sus creadores titanes, profundizando en lo que a un humano le llevaría toda la vida. Había cinco Aspectos cuando los titanes dejaron este mundo, se trataba de poderosos dragones cuyo cometido era proteger el mundo de Azeroth. Sus historias son extensas y variadas y, aún hoy, a pesar de toda la información que he recogido, sé que tengo mucho que aprender sobre estas magníficas criaturas.", "Gran parte del conocimiento que poseo ahora no lo habría podido adquirir por mi cuenta. Por esta razón, siento una infinita gratitud hacia los elfos de la noche. Ahora conozco muchísimos detalles exclusivamente gracias a su ayuda. Como resultado de nuestra relación, tengo la impresión de que sus orígenes guardan un vínculo mucho más estrecho con los Aspectos que lo que creía inicialmente. No obstante, guardan sus secretos con tanto celo, que incluso a mí me ocultan toda la verdad.", "Todos mis conocimientos sobre los Aspectos los comparto aquí para que sirvan como referencia en el futuro. Sé que serán de extrema utilidad, pues presiento que los dragones tendrán un impacto mucho mayor en el mundo con el paso del tiempo.", "Alexstrasza:\nAlexstrasza fue la antigua y poderosa Reina de los Dragones, llamada la Protectora por los titanes. Fue la primera en ser creada por los titanes para proteger el mundo tras su partida. Se dice que presenció el nacimiento de todas las razas modernas en toda la faz de Azeroth. Su Vuelo Rojo, conocido por su orgulloso comportamiento, gobernó antiguamente sobre las demás especies de dragones.", "Corrían ciertos rumores entre los elfos de la noche que sugerían que a Alexstrasza y al semidiós Cenario los unía una fuerte amistad, y que fue él quien la llamó durante la primera invasión de la Legión Ardiente.", "Ysera:\nYsera, la Soñadora, representa el subconsciente de los mortales. Es ella quien induce al Sueño Esmeralda. Aunque aprecia la imaginación y la creatividad, aprobando la ambición de las razas mortales, ella y su Vuelo consideran el mundo real como una mera ilusión. Ysera es una de las criaturas más agraciadas y poderosas que cualquier mortal haya podido contemplar.", "Malygos:\nMalygos se conoce como Administrador de la Magia o Tejedor de Hechizos. Su aspecto natural no es el de un dragón al uso y se dice que puede cambiar de forma a voluntad. Se le ha visto muy pocas veces tras su retiro en el extremo norte y casi siempre guarda la apariencia de una suerte de insecto, pero cuando adquiere forma de dragón, él y sus vástagos se distinguen por ser de color azul, en toda su gama.", "Nozdormu:\nNozdormu se conoce como Maestro del Tiempo o el Atemporal. Él y su escuadrilla tienen una tonalidad broncínea y son muy astutos. Nozdormu siempre se ha interesado en coleccionar artefactos del pasado, ya que poco le importa la realidad de las razas mortales o incluso los asuntos de sus compañeros, los Aspectos. Sin embargo, su indiferencia hacia los asuntos políticos de los demás no supone displicencia frente a lo que ocurre en el resto del mundo.", "Considerados protectores, el Vuelo de Bronce siente una fuerte atracción por ciertos aspectos de la civilización. El dragón y su escuadrilla son muy pacientes por naturaleza y se basan siempre en la observación, por lo que, antes de apresurarse, actúan siguiendo un plan. Nozdormu siempre intentará proteger el fluir del tiempo y a las razas mortales cuando se vean amenazadas por enemigos más poderosos.", "Neltharion:\nNeltharion, llamado, tras su creación, el Guardián de la Tierra, fue el Aspecto más leal y protector de Azeroth. Su Vuelo Negro fue el responsable de la creación de las montañas y otras formaciones rocosas, incluyendo las fronteras entre las razas mortales. Qué provocó su descomposición sigue siendo un misterio, ciertamente, se desconoce si fue una influencia externa o algo que se corrompió en su interior. Me pregunto si tal vez los dioses antiguos no tuvieron que ver con la corrupción del gran dragón negro.", "El dragón negro sufrió una transformación completa y, finalmente, Neltharion dejó de existir. Se convirtió en Alamuerte, una criatura llena de odio y maldad. Cuando abandonó el nombre de Guardián de la Tierra, tal y como lo conocían los elfos de la noche, se hizo llamar Aspecto de la Muerte o Xaxas, nombre distinto del que los titanes le había otorgado. Alamuerte es la personificación del caos y el mal, siempre sediento de destrucción. Podría decirse que es el primer mal que apareció en Azeroth tras el destierro de los dioses antiguos." } } },
    ["Legends of the Gurubashi, Volume 3"] = { { ids = { "i3899" }, first = "legendsofthetrollsvolume", pages = { "LEYENDAS DE LOS TROLS, VOLUMEN III\nPiedra de las Mareas\n\nEscrito por\nArchimago Ansirem Tejepista\nDalaran\n\nINTRODUCCIÓN\n\nEl antiguo Imperio Gurubashi alimentó leyendas inquietantes y fascinantes que, sin duda, pueden rastrearse en la zona, ya que el estudio de sus sistemas de creencias y prácticas sociales han señalado la gran importancia del entorno natural.\n\nMientras ahondaba en muchos", "aspectos de su adoración a las serpientes en volúmenes anteriores de este estudio, analizo aquí la interesante y peculiar relación de los trols con el mar.\n\nEL MARE MAGNUM\n\nEl Imperio Gurubashi estaba rodeado por el mar en tres de sus costados, así que no resulta sorprendente que el agua jugara un papel preponderante en su sociedad. Si bien los trols eran capaces de ir de un lado a otro y controlar vastas extensiones de jungla dentro de su imperio, el mar los eludía. Era vasto e inconmensurable, sin", "duda un vecino desconcertante para los poderosos trols.\n\nEs preciso aclarar que recientes descubrimientos sugieren que los trols no mostraban demasiado interés en explorar las tierras que había más allá del Mare Magnum. Aunque se han hallado especies de trols en toda la extensión de Azeroth, Khaz Modan y Lordaeron, apenas se han encontrado vestigios de su civilización en las tierras recientemente descubiertas de Kalimdor o en las islas de los Mares del Sur. Tanto si esto demuestra la nula disposición de", "los trols a aventurarse fuera de sus tierras, como si se trata de la ausencia de tecnologías para acometer tal empresa, es preciso una investigación y un análisis que escapan al alcance de estos escritos.\n\nNo obstante, resulta difícil ignorar una presencia tan importante. De hecho, nuevos hallazgos en las extensas ruinas trol de la Vega de Tuercespina muestran un aspecto de su relación con el mar anteriormente desconocido y no documentado.\n\nLA PIEDRA DE LAS MAREAS\n\nRecientes descubrimientos efectuados durante el reconocimiento", "de las ruinas trol de la Vega de Tuercespina contienen referencias a un objeto conocido como la \"Piedra de las Mareas\". Diversos fragmentos de leyendas trol pueden unirse para pintar un cuadro bastante completo de la Piedra y establecer su significado para el Imperio Gurubashi.\n\nAl parecer, la Piedra de las Mareas ofrecía a su portador el control del agua en sus diversas formas: ríos, lluvia y mareas. Dadas las historias relacionadas con el uso de la Piedra de las Mareas, he conjeturado que se trata", "en realidad, de una manifestación física de los poderes del Señor del Agua, un poderoso elemental de los mares. La razón y la manera en que un objeto de estas características escapa al control del Señor del Agua y cae en manos de los trols es otra cuestión que está fuera de mi alcance.\n\nEL PORTAMAREAS\n\nImitando el movimiento de las olas, la Piedra de las Mareas entró y salió del mundo de los trols, sin permanecer en manos de ellos más de una generación cada vez.", "Según las leyendas trol, la primera vez que la Piedra de las Mareas entró en el Imperio Gurubashi, fue encontrada por un guerrero trol que caminaba por la costa de Tuercespina. Halló una misteriosa piedra azul que contenía unos filamentos lechosos que flotaban y fluían en su interior. Intrigado por la piedra, el guerrero la guardó y continuó su camino.\n\nTras unas semanas, o quizás meses, el guerrero descubrió que la piedra le había otorgado el control sobre el agua. Podía invocar", "elementales de agua, criaturas hechas totalmente de agua, realizando hazañas solo propias de los poderosos magos del Kirin Tor.\n\nEl guerrero viajó a Zul'Gurub, en pleno corazón del Imperio, para mostrar sus nuevas habilidades al Emperador. Le escucharon en la corte tras demostrar sus poderes en el centro de la capital imperial. Estos poderes sorprendieron al Emperador Gurubashi, quien de inmediato le otorgó un sitio de honor en la corte, nombrándolo guerrero \"Portamareas\", dejando atrás su", "antiguo nombre.\n\nDurante años, el Portamareas sirvió al Imperio Gurubashi, invocando en la batalla a los elementales de agua sometidos a su voluntad y manipulando el cauce del agua en la Vega de Tuercespina para beneficio del Imperio. Pero con el paso de los años, el Portamareas se volvió cada vez más solitario, tendiendo a permanecer largos periodos fuera de la corte.\n\nEl Portamareas ocultaba un secreto a la atenta mirada la corte. Las cualidades que le otorgaba la Piedra de las Mareas incluían una maldición. Con el paso de", "los años, el Portamareas se fue desvaneciendo. Cada vez que la marea subía y bajaba, el Portamareas iba perdiendo paulatinamente su forma corpórea original, cobrando y perdiendo vida de forma intermitente. Hasta que, en el ocaso de su existencia, viajó al lugar en el que había encontrado la Piedra, se internó en el mar y desapareció para siempre.\n\nGeneraciones más tarde, la Piedra de las Mareas regresó a las playas de Tuercespina y eligió a otro Portamareas, un trol que la condujo hasta", "Zul'Gurub. Este proceso se repitió durante generaciones: la Piedra aparecía con la marea y, posteriormente, el Portamareas desaparecía en el mar.\n\nEn varios sitios se cuentan versiones modernas del mito de la Piedra de las Mareas, pero lo cierto es que resulta sorprendente que un objeto tan poderoso apareciera con tanta regularidad, por designios de un ser desconocido." } } },
    ["Lethargy of the Orcs"] = { { ids = { "o175751" }, first = "monthspassedandmoreorcpr", pages = { "Pasaron los meses y más prisioneros orcos fueron capturados, tras lo cual fueron conducidos a los campos de internamiento. Cuando los campos empezaron a estar superpoblados, la Alianza tuvo que construir nuevos campos en las planicies del sur de las montañas de Alterac. Para mantener adecuadamente el creciente número de campos, el rey Terenas impuso un nuevo impuesto a las naciones de la Alianza.", "Este impuesto, junto con el incremento de las tensiones políticas sobre disputas fronterizas, crearon intranquilidad en toda la región. Parecía como si el frágil pacto que habían forjado las naciones humanas en sus peores momentos pudiera romperse en cualquier momento.", "En medio de los disturbios políticos, muchos de los guardianes de los campos empezaron a observar inquietantes cambios en sus orcos cautivos. Con el tiempo, los esfuerzos de los orcos por escapar de los campos o, incluso, las luchas entre ellos, habían descendido enormemente. Los orcos parecían cada vez más distantes y aletargados.", "Aunque era difícil de creer, los orcos, considerados la raza más agresiva jamás vista en Azeroth, habían perdido por completo su voluntad de luchar. El extraño letargo confundió a los líderes de la Alianza y continuó cobrando su peaje sobre los orcos cada vez más debilitados.", "Como causa del desconcertante letargo, algunos especularon con la posibilidad de una extraña enfermedad que solo podían contraer los orcos. Pero el archimago Antónidas de Dalaran formuló una hipótesis distinta. Investigando detalladamente acerca de la historia de los orcos, Antónidas descubrió que estos habían sufrido la atroz influencia del poder demoníaco durante generaciones.", "Especuló que los orcos habían sido corrompidos por estos poderes incluso antes de su primera invasión de Azeroth. Claramente, los demonios habían contaminado la sangre de los orcos y estos, a su vez, habían sido dotados de una fuerza, una resistencia y una capacidad de agresión ciertamente fuera de lo normal.", "Antónidas consideró que el letargo colectivo de los orcos no era en realidad una enfermedad, sino la consecuencia de la abstinencia racial en relación con la volátil magia del brujo, que los había convertido en guerreros temibles y sanguinarios.", "Aunque los síntomas eran claros, Antónidas fue incapaz de encontrar una cura para la enfermedad de los orcos. Posteriormente, muchos de sus compañeros magos, así como algunos notables líderes de la Alianza, argumentaron que encontrar una cura para los orcos podía ser una aventura imprudente. Considerando el misterioso estado de los orcos, Antónidas concluyó que la cura de los orcos debía tener un carácter espiritual." } } },
    ["Letter to Delgren"] = { { ids = { "i5354" }, first = "masterdelgrenitisasyoufe", pages = { "Maestro Delgren,\n\nEs como te temías. Tu teoría acerca de la Torre de Althalaxx ha resultado ser cierta. Se ha reunido un culto en la torre, incluyendo a muchos brujos, así como a un nauseabundo sátiro. Se llaman a sí mismos el Culto de la Facción Oscura. No puedo imaginarme qué vil propósito los ha reunido, pero me preocupa.\n\nDisculpa el carácter lacónico de esta carta, pero el peligro merodea en el bosque y solo puedo decir un par de palabras para describir la situación. Yo...", "te debería entregar este mensaje en mano, pero debo irme, no sea que me pierda algún acontecimiento de gran importancia. Si deseas saber más acerca de mis observaciones sobre la torre de Althalaxx, $gel portador:la portadora; de este mensaje me ha servido de gran ayuda y creo que se puede confiar en $gél:ella;.\n\nA toda prisa,\nBalthule Golpesombra" } } },
    ["Letter to Ello"] = { { ids = { "i1637" }, first = "thelettersonthisnoteseem", pages = { "Las letras de esta nota parecen parpadear y bailar sobre la superficie. Resulta imposible encontrarles significado..." } } },
    ["Letter to Jin'Zil"] = { { ids = { "i5594" }, first = "jinzilithasbeenawhilebut", pages = { "Jin'Zil,\n Sé que hace un tiempo que no te escribo, pero pensé que te gustaría saber que el último de los Sangrepluma ha sido asesinado. No me lo agradezcas, la persona que entrega la carta es la asesina. Si quieres, puedo entregarte su cabeza después de que la caravana haga sus rondas por los Baldíos. Sé que te gustan esta clase de cosas para tus ceremonias vudú. Cuídate, viejo amigo.\n\n-Darsok Movedaga" } } },
    ["Letter to Jorgen"] = { { ids = { "i5948" }, first = "jorgenmyfearshavecometru", pages = { "Jorgen,\\Mis temores se han materializado: han actuado de un modo del que no los creía capaces. Jamás pensé que pudieran llegar tan cerca, y lo han hecho.\n\nTe pido ayuda para el portador de esta nota y que lo envíes hacia ÉL. Honestamente, dada la gravedad de este asunto, creo que nos ayudará. Si se tratara de cualquier otro peligro, probablemente continuaría ignorándonos, desdeñando los problemas de nuestra bella ciudad.\n\nGracias, viejo pescador. Siempre estaré en deuda contigo.\n\nTu amigo,\nDeLavey" } } },
    ["Lewis' Note"] = { { ids = { "i15998" }, first = "osricpleasefindbelowthel", pages = { "Osric,\n\nA continuación, encontrarás un listado de las armaduras que necesitamos:\n\n10 cotas de malla\n20 yelmos\n30 refuerzos de armadura\n15 botas de malla\n\nComo siempre, estamos en deuda contigo. Y cuando Páramos de Poniente sea libre de los ladrones que lo amenazan, sería un verdadero alivio para la culpa en mi corazón invitarte al hogar de mi familia, donde compartiremos una cena preparada con las riquezas por las que estas tierras fueron conocidas.\n\n-Lewis\nIntendente, Colina del Centinela" } } },
    ["Libram of Constitution"] = { { ids = { "i11733" }, first = "thepageshereincontainmem", pages = { "<Las páginas aparecen cubiertas por antiguas runas élficas.>\n\nEstas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor.\n\nQue nuestros enemigos jamás tengan acceso a estos tratados.\n\nDeseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas.\n\nDeseo morir por la gracia de Kael'thas.\n\nDeseo matar por la gloria de Illidan.\n\nMaestro Kariel Winthalus", "", "", "", "" } } },
    ["Libram of Focus"] = { { ids = { "i18333" }, first = "thepageshereincontainmem", pages = { "<Las páginas están cubiertas por antiguas runas élficas.>\n\nLas páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor.\n\nQue nuestros enemigos nunca tengan acceso a estos tratados.\n\nQuisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas.\n\nSi muero, que sea por la gracia de Kael'thas.\n\nSi muero asesinado, que sea por la gloria de Illidan.\n\nMaestro Kariel Winthalus", "<Nada de lo que hay escrito en estas páginas resulta inteligible.>" } } },
    ["Libram of Protection"] = { { ids = { "i18334" }, first = "thepageshereincontainmem", pages = { "<Las páginas están cubiertas por antiguas runas élficas.>\n\nLas páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor.\n\nQue nuestros enemigos nunca tengan acceso a estos tratados.\n\nQuisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas.\n\nSi muero, que sea por la gracia de Kael'thas.\n\nSi muero asesinado, que sea por la gloria de Illidan.\n\nMaestro Kariel Winthalus", "<La tinta se desplaza, formando remolinos sobre la página. Tienes la sensación de que el libro se está burlando de ti.>" } } },
    ["Libram of Rapidity"] = { { ids = { "i18332" }, first = "thepageshereincontainmem", pages = { "<Las páginas están cubiertas por antiguas runas élficas>.\n\nLas páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor.\n\nQue nuestros enemigos nunca tengan acceso a estos tratados.\n\nQuisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas.\n\nSi muero, que sea por la gracia de Kael'thas.\n\nSi mato, que sea por la gloria de Illidan.\n\nMaestro Telmius Buscasueños", "<Cuando contemplas estas páginas, sientes un dolor agudo.>" } } },
    ["Libram of Resilience"] = { { ids = { "i11736" }, first = "thepageshereincontainmem", pages = { "<Las páginas aparecen cubiertas por antiguas runas élficas>.\n\nEstas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor.\n\nQue nuestros enemigos jamás tengan acceso a estos tratados.\n\nDeseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas.\n\nDeseo morir por la gracia de Kael'thas.\n\nDeseo matar por la gloria de Illidan.\n\nMaestro Telmius Buscasueños", "", "", "" } } },
    ["Libram of Rumination"] = { { ids = { "i11732" }, first = "thepageshereincontainmem", pages = { "<Las páginas aparecen cubiertas por antiguas runas élficas>.\n\nEstas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor.\n\nQue nuestros enemigos jamás tengan acceso a estos tratados.\n\nDeseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas.\n\nDeseo morir por la gracia de Kael'thas.\n\nDeseo matar por la gloria de Illidan.\n\nMaestro Telmius Buscasueños", "", "", "" } } },
    ["Libram of Tenacity"] = { { ids = { "i11734" }, first = "thepageshereincontainmem", pages = { "<Las páginas aparecen cubiertas por antiguas runas élficas.>\n\nEstas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor.\n\nQue nuestros enemigos jamás tengan acceso a estos tratados.\n\nDeseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas.\n\nDeseo morir por la gracia de Kael'thas.\n\nDeseo matar por la gloria de Illidan.\n\nMaestro Kariel Winthalus", "", "", "", "" } } },
    ["Libram of Voracity"] = { { ids = { "i11737" }, first = "thepageshereincontainmem", pages = { "<Las páginas aparecen cubiertas por antiguas runas élficas.>\n\nEstas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor.\n\nQue nuestros enemigos jamás tengan acceso a estos tratados.\n\nDeseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas.\n\nDeseo morir por la gracia de Kael'thas.\n\nDeseo matar por la gloria de Illidan.\n\nMaestro Kariel Winthalus", "", "", "", "" } } },
    ["List of Components"] = { { ids = { "i236002" }, first = "inordertonavigatethemagi", pages = { "Necesitaremos crear una poderosa fuente de magia capaz de atravesar la noche artificial si queremos navegar por la oscuridad mágica que encontraste en la cripta. Esta magia es muy delicada, y requiere unos componentes muy específicos.", "El primer componente es la llama de la vida. Esta llama es la esencia pura y ardiente de la creación y el renacimiento. Se rumorea que los dragonantes rojos son capaces de crearla porque son hijos de la dragona Aspecto Alexstrasza, progenitora de dicha magia. Puede que Grim Batol sea un buen punto de partida.", "El siguiente componente es una rama de maderaférrea antigua. Los Ancianos del Conocimiento están hechos de este maravilloso material, pero una sola muestra sería mortal para estas majestuosas criaturas.\n\nHe oído rumores sobre un anciano corrupto que acecha en el Barranco del Demonio, al sureste de Vallefresno. Quizás puedas encontrar a esta pobre criatura, liberarla de su tormento y, de paso, conseguir la rama de maderaférrea que necesitamos.", "El último componente es un espíritu puro y benévolo al que la llama haya dado forma y esté dispuesto a vincularse a la maderaférrea antigua para así repeler la oscuridad.\n\nEste mundo está lleno de espíritus, por supuesto, pero encontrar el adecuado puede resultar todo un reto. Debe ser independiente y obstinado, pero en busca de un propósito. La mayoría de los espíritus son distantes e inconscientes, pero, en raras ocasiones, se puede encontrar uno que anhela un motivo superior...", "Otros miembros de mi orden que estuvieron presentes en la batalla final en el Monte Hyjal hablan de una lucha culminante entre los antiguos espíritus de los kaldorei y el señor demoníaco Archimonde. No se me ocurre un propósito más digno para un espíritu que la defensa de nuestro mundo, pero habiendo pasado tanto tiempo desde aquella fatídica batalla, puede que algún espíritu que aún permanece en el árbol esté buscando un nuevo y noble propósito.\n\nSe dice que hay muchos espíritus como estos en la Garganta Negro Rumor.\n\nCuando lo hayas reunido todo, combinaremos los materiales y crearemos una fuente de llamas mágicas que disipen la oscuridad y te permitan adentrarte en la cripta." } } },
    ["Lonebrow's Journal"] = { { ids = { "i5790" }, first = "dayonemyjourneyfromironf", pages = { "--Primer día:\n\n¡Finalmente, mi viaje a Forjaz me ha traído hasta Kalimdor!\n\nEl prospector Khazgorm de Bael Modan está haciendo grandes progresos. Hoy descubrió un fósil que los sabios del lugar consideran un fragmento de hueso de un antiguo dios. Khazgorm está seguro de que el fósil forma parte de un misterio aún mayor. Mientras supervisa la excavación, me ha encomendado descubrir más fósiles para unir las piezas del rompecabezas.\n\nMi misión es la siguiente: dirigirme hacia el sur en busca de nuevas pistas.", "--Segundo día:\n\n Las tierras de los Baldíos son extensas. Mi viaje ha sido largo y arduo y, hasta el momento, no ha producido nada de interés para la Liga de Exploradores.\n\nEl único incidente notable tuvo lugar cerca del Camino de Oro. A la distancia, pude ver algunas criaturas extrañas: me parecieron una combinación de cerdo y hombre. Me oculté rápidamente y dejé que las hediondas bestias pasaran de largo. ¡Vaya hedor más nauseabundo que dejaron!", "--Tercer día:\n\n ¡Qué gran descubrimiento!\n\nMientras exploraba, he descubierto algo fascinante: muchos restos de lo que parece haber sido una criatura semejante a un jabalí. Su cráneo era mucho más grande que yo. Cada diente de la bestia podría compararse a un enano. Debido al tamaño del descubrimiento, me inclino a pensar que se trata de los restos de uno de los dioses antiguos.", "De regreso en el puesto de mando de la Liga de Exploradores en Forjaz, recuerdo una conferencia que pronunció el arqueólogo jefe Mostachogris. En ella mencionó un dios de esta clase, que fue adorado por extraños elfos de Darnassus, debido a su supuesta naturaleza altruista.\n\n¡Bah! Un momento. He oído cómo resoplaban fuera de la tienda. Seguramente, se trata de algunos jabalíes intentando coger las manzanas que tengo escondidas...", "--Cuarto día:\n¡Capturado!\n\nDebo... escribir... rápidamente.\n\nMe han atacado hombres jabalí de la tribu Rajacieno. Creía que me iban a llevar a los grandes restos de jabalí del dios caído. En su lugar, bordearon los grandes fósiles y fueron directamente hacia el oeste de la gigantesca calavera, hacia el Camino del Oro.", "Me han arrastrado violentamente hasta un apestoso y espinado zarzal llamado Horado Rajacieno. Me han arrojado a una rústica cabaña y me han hecho $gprisionero:prisionera; junto con un elfo de la noche moribundo.\n\nNo tengo otras posesiones salvo este diario, mi pluma y mi reloj de bolsillo...\n\nAlguien se acerca...", "--Quinto día:\n\n Mi compañero de celda, el elfo de la noche, sufre grandes heridas. Los hombres jabalí le han pegado repetidamente y creo que, a menos que, por algún milagro, una partida de rescate nos libre de este traicionero lugar, morirá en breve. Pasa de la conciencia a la inconsciencia constantemente. Cuando está consciente, intento darle un poco de agua.", "La última noche, fue capaz de hablar por primera vez. Es un druida, llamado Heralath, enviado a este lugar para verificar los rumores acerca de la existencia del dios jabalí caído.\n\nCon su débil voz, me contó que creía que la gran calavera de jabalí estaba situada en el lugar en el que el gran dios jabalí Agamaggan cayó combatiendo contra la Legión Ardiente hace unos 10.000 años durante la Guerra de los Ancestros. Su voluminoso cuerpo quedó aplastado contra el suelo y su sangre penetró en la tierra. En el lugar bañado por su sangre crecieron retorcidos arbustos espinosos...", "Heralath y su gente intentaban descubrir la fuente de la corrupción de este sitio. Me dijo que se creía que Agamaggan era un dios puro. Ciertamente, la razón por la que estas hediondas criaturas y los malignos arbustos marcaban esta tierra es un misterio.\n\nAntes de que pudiera obtener más información, Heralath volvió a caer en su sueño intermitente...", "--Sexto día:\n\n El estado de Heralath empeora.\n\nHoy, sus ojos solo se abrieron una vez. Habló con dolor, pero su mensaje fue claro. Si pudiera escapar de mi condena aquí en Horado Rajacieno, Díscolo Falfindel, que está en Thalanaar, debería saber que Charlga Filonavaja ha estado reuniendo esbirros en la zona sur de los Baldíos. Su poder crece cada día. Hay que detener a la bruja antes de que se extienda la peste corrupta desde el Horado.", "El pobre Heralath tiene la palidez de un hueso. Su fiebre empeora por minutos. Mientras tanto, los hombres jabalí se están preparando para una gran acción militar. Me temo que si no intento escapar rápido, mi destino será el mismo que el de mi compañero de celda.\n\nMi plan es escabullirme cuando los hombres jabalí partan a realizar su próxima batida. Mis guardianes son perezosos y, a menudo, duermen en sus turnos.", "Una vez que me escape del Horado, iré hacia las Mil Agujas y, a continuación, hacia Thalanaar, en los confines del misterioso bosque de Feralas. Allí buscaré al druida llamado Díscolo Falfindel.\n\nLo que comenzó como un intento de explorar el pasado de mi gente se ha convertido en algo mucho más grande. La protección de la Alianza está en mis manos..." } } },
    ["Longwalker Malah's Report"] = { { ids = { "i286104" }, first = "dayventurecoactivitycont", pages = { "Día 1\n\nLa actividad de Ventura y Cía. sigue siendo preocupante. Sus explotaciones mineras no han dejado de crecer y oigo un nuevo ruido de molienda que sugiere que han descargado allí algún ensamblaje horrible.\n\nAún no los considero una amenaza capaz contra Cima del Trueno, pero, si se los provoca, podrían atacar con éxito el Poblado Pezuña de Sangre desde el sur.", "Día 2\n\nOigo un estruendo de estampida que resuena en los riscos del este, donde nuestro hogar se encuentra con las llanuras de Los Baldíos. Podría ser otra manada de cebras o gacelas, o quizá un truenagarto enfurecido, pero continúa hasta más entrada la noche de lo que esas bestias suelen permanecer activas.\n\nAvanzaré para investigar, pero mantendré una distancia segura.", "Día 3\n\n¡Los centauros han invadido Mulgore! Nuestro enemigo más vil y antiguo ha osado volver a estas llanuras tras ser expulsado. ¡La furia del gran jefe caerá sobre ellos!\n\nDebo saber qué planean para que podamos contrarrestarlo con la mayor eficacia. Si guardo silencio, creo que podré acercarme lo suficiente para oírlos.\n\nParece que planean...\n\n<El resto del texto está cubierto de sangre.>" } } },
    ["Lorgalis Manuscript"] = { { ids = { "i5359" }, first = "ourworldbrimswithhistory", pages = { "Nuestro mundo está cargado de historia. Una historia de razas modernas y antiguas. Una historia de guerras pasadas y presentes.\n\nUna historia de dioses que vienen del cielo. Y una historia de dioses antiguos que dormitan sobre la tierra.\n\nAhora hablaré de esos seres, los dioses antiguos. Aquellos que habitaron y rugieron por todo el territorio de Azeroth cuando el mundo estaba en ciernes.", "Los antiguos dioses son la voluntad de nuestro mundo. En cada tormenta se escucha la risa estruendosa de un dios antiguo. Sus penetrantes miradas son teas incandescentes. A su paso, la tierra retumba y se resquebraja, mientras las criaturas menores gritan de pánico y rasgan su propia carne en medio de la desesperación.\n\nSu desesperación tiene razón de ser, pues, al igual que el fuego no se detiene ante la mano curiosa de un niño, los antiguos dioses no se preocupan por los seres inferiores. Con suerte, nos tratan como peones. A veces, incluso, somos sus juguetes.", "Fueron los primeros amos del mundo y reinaron sembrando el terror. Pero ahora duermen encadenados, mientras sus siervos vagan por el mundo y nosotros, insignificantes mortales, no estamos a la altura de su poder.\n\nAquellos que intentan enfrentarse a ellos son devorados. Pero los que son conscientes de su situación, los que suplican de rodillas a los siervos de los antiguos dioses, los que sacrifican su mente y su alma, solo ellos son bien recibidos.", "Aku'mai, Princesa de la Profundidad, sirve a los antiguos dioses. Habita en las cavernas de Brazanegra, bendiciéndolas con su antigua sabiduría. Conducida hasta las Profundidades por mortales antiguos, Aku'mai es símbolo de divinidad. Apenas goza de una pequeña parte del poder y la fiereza de los dioses antiguos y, aún así, estas cualidades son inconmensurables en ella.\n\n Y por ello es venerada. Y también es temida y amada.\n\nLorgalis" } } },
    ["Maggran's Reserve Letter"] = { { ids = { "i16189" }, first = "grishyourrequestforsomet", pages = { "Grish:\n\nTu petición de un tiempo de descanso ha sido aceptada. Te envío un guerrero tauren de reserva para que vigile tu puesto mientras pasas una temporada con tu familia. ¡Vuelve a presentarte en una semana!\n\nLigaterra Maggran" } } },
    ["Magical Ledger"] = { { ids = { "i20949" }, first = "", pages = { "" } } },
    ["Manual of Engineering Disciplines"] = { { ids = { "i10789" }, first = "theengineeringdiscipline", pages = { "Las disciplinas de ingeniería\n\nSi bien resulta discutible qué raza creó la ciencia de la ingeniería en Azeroth, apenas si cabe duda de cuáles son sus principales razas defensoras en la actualidad: los gnomos y los goblins. Su dedicación a la ingeniería como colectivo no solo ha dado lugar a fantásticos inventos durante lo que podría considerarse la asombrosa Era de la Invención, sino que también ha alimentado su intensa rivalidad racial. Esto resulta especialmente evidente en sus disciplinas divergentes.", "Ingeniería gnómica\n\nLos gnomos, como raza, suelen ser excelentes diseñadores de objetos destinados a manipular y controlar el mundo que los rodea. Si bien los gnomos tienen conocimientos elementales de explosivos y armamento, la ingeniería gnómica se centra en aquellos objetos que hacen la vida más fácil y accesible. Su disciplina se basa en la materialización de probabilidades teóricas fundadas en la experiencia gnómica. Sin embargo, algunas no se materializan jamás.", "Ingeniería de los goblins\n\nComo raza que adopta una posición neutral en casi todos los conflictos, los goblins han hecho avances importantes a la hora de rentabilizar sus logros científicos. De esta manera, dominan las aplicaciones prácticas de la ingeniería, como demuestran sus innovadores diseños de explosivos, armas de fuego y maquinaria. La ingeniería goblin solo evidencia un interés superficial por la teoría. De hecho, sus inventos no suelen presentar problemas de funcionamiento, antes al contrario, funcionan demasiado bien. Ciertamente no es una materia apta para pusilánimes.", "Estudio de la disciplina\n\nLos gnomos y los goblins no comparten sus conocimientos entre sí hasta tal punto, que resulta casi imposible acceder a ambas disciplinas simultáneamente. Cada raza, independientemente de su afiliación política, solo transmite el conocimiento de su disciplina a aquellos que renuncian a la disciplina de los otros. Así, por ejemplo, si un estudiante elige la ingeniería gnómica, no se le transmitirán nunca conocimientos de ingeniería de los goblins.", "Decisiones permanentes\n\nEn la sección anterior se destacó un aspecto importante sobre las dos disciplinas de ingeniería que conviene resaltar. Si alguien opta por una de las dos disciplinas, los modelos de la otra disciplina no estarán a su disposición para su estudio. Aunque esta finalidad puede resultar desalentadora para el ingeniero neófito, el experto comprende que los gnomos y los goblins guardan sus secretos con absoluto celo, pues afirman que es mejor tener algún conocimiento que ninguno.", "Citas\n\n\"¿Deseas aprender ingeniería de los goblins? Intenta pedírselo a uno de los mejores y más brillantes ingenieros. Creo que lo llaman Nubby Muñoncitos. ¿Quieres saber por qué lo llaman así? ESO ES ingeniería goblin.\"\n-- Ringo Tragedicción, ingeniero gnomo\n\n\"Podrás pensar lo que quieras sobre los gnomos, pero una cosa sí te voy a decir: ¡TENEMOS EXPLOSIVOS!\"\n-- Yazz Nitrocerdo, bombardero goblin", "¡Más citas!\n\n\"¿Conoces la sensación que te produce fabricar algo y encenderlo por primera vez, experimentando el poder y la alegría de inventar una máquina que cobra vida gracias a tu ingenio? Los gnomos no.\"\n-- Nixx Muellepiñón, maestro ingeniero goblin de Gadgetzan\n\n\"¡La ingeniería consiste en utilizar la fantasía para crear lo fantástico!\"\n-- Rovis McCrankenspank, inventor gnomo" } } },
    ["Marshal McBride's Documents"] = { { ids = { "i745" }, first = "reportkoboldstheactivity", pages = { "INFORME: Kobolds\n\nLa actividad de los kobolds ha aumentado en las cercanías del valle de Villanorte. Un alarmante número de ellos acampa al norte de la abadía y dentro de la Mina del Eco. He reunido a paladines y a otros habitantes de la zona para limpiarla de estas alimañas.\n\nLa labor progresa adecuadamente. Yo, por mi parte, modernizaré el sistema si es necesario.", "INFORME: Ladrones\n\nMás peligrosos que los kobolds, una banda de ladrones humanos ha surgido del valle. Llevan pañuelos rojos y se consideran una hermandad. Su nivel de organización puede generar problemas, aquí y en el bosque de Elwynn.\n\nHemos identificado a uno de sus líderes, un tal Garrick Piesuaves, al que esperamos llevar pronto ante el tribunal.", "INFORME: Lobos\n\nSegún los informes, los ataques de estos animales han aumentado en Villanorte. Eagan cree que los lobos que hay en el valle fueron desterrados desde el Bosque del Ocaso.\n\nAunque los lobos rara vez cazan humanos, su elevado número provocó ciertos incidentes con los granjeros. Y varias piezas de ganado desaparecieron.", "DISTINCIÓN:\n\nEl portador de estos documentos será condecorado con el rango de Ayudante de Alguacil del ejército de Ventormenta, por haber servido a Villanorte con entusiasmo y especial atención. Confío en que esta persona os resulte útil en el bosque de Elwyyn.\n\nFirmado:\nAlguacil Douglas McBride,\nEjército de Ventormenta, Villanorte" } } },
    ["Maybell's Love Letter"] = { { ids = { "i1208" }, first = "tommyjoewitheachpassingh", pages = { "Tommy Joe,\n\nCada hora que pasa, mi corazón se marchita sin tu presencia. Oh, si nuestra gente pudiera comprender el trasfondo de los crímenes que han cometido con sus semejantes, sabría que el único verdadero crimen es el odio. El odio consume, y me temo que, en estos tiempos oscuros, se apoderará no solo de nuestras familias.\n\nSi simplemente se dieran cuenta de ello, al menos podríamos estar juntos al fin. Sueño con que llegue ese día, vivo para ese día.\n\nCon todo mi amor,\nMaybell" } } },
    ["Memories of Valor"] = { { ids = { "i281149" }, first = "memoriesofvalorarecounto", pages = { "Memorias de los Valor\nUna crónica de la familia Valor y su servicio al Cerro del Cuervo\n\nNo había familia más grandiosa en todos los Reinos del Este que los Valor. Sus hazañas en defensa del pueblo al que juraron proteger fueron auténticos milagros, y su pérdida es una tragedia para el Cerro del Cuervo.\n\nEscribo este relato para que quede constancia de lo brillantes que fueron Grant, Ira, Silvia y Merrick. Que estas líneas sirvan de pequeño consuelo ante lo mucho que lamento su ausencia.", "Merrick Valor, guardia de Villa Oscura\n\nMerrick era el hijo menor de los Valor. Al ver cómo llegaba la corrupción a su patria, eligió unirse a la Guardia en un intento desesperado de proteger a sus seres queridos.\n\nAunque era el más inexperto de la familia, pronto se hizo un nombre entre los guardias. Tenía talento para el arco y se convirtió en uno de los defensores más firmes de Villa Oscura.\n\nSu misión personal era mantener seguros los caminos, atento a las criaturas cada vez más hostiles que llegaban a los bosques.", "Silvia Valor, guardia del Cerro del Cuervo\n\nSilvia Valor ya era toda una heroína local cuando le ofrecieron unirse a la guardia. Si había algo que no podía soportar más que nada en el mundo, eran los oportunistas que se aprovechaban de la gente en apuros.\n\nBandidos, estafadores, agitadores... Daba igual. Silvia acababa con ellos por tratar de sembrar el caos en su querido hogar. Era lógico que se le asignara un puesto de verdadera autoridad para que pudiera llevar a la práctica su visión de la justicia.\n\nSe dice que, hasta su último aliento, nunca abandonó las granjas y los hogares del Bosque del Ocaso. Y que quizá su vigilia tampoco acabara tras su muerte...", "Ira Valor, acechadora del bosque\n\nCuando el padre de Ira enfermó, ella se encargó de recoger comida y provisiones en los bosques cercanos. Aunque no faltaban recursos, era tan probable encontrar alimento como convertirse en él.\n\nCon los años se adaptó a los bosques y prefirió pasar el tiempo entre los árboles oscuros en vez de en el Cerro del Cuervo. Los viajeros perdidos contaban historias de una sombra que parecía abrirles el camino de vuelta a la carretera. Nadie confirmó quién era, pero los rumores corrieron deprisa.\n\nSe dice que Ira sigue en los bosques, ofreciendo una mano que guía a quienes caen presa de sus bestias.", "Lord Grant Valor, patriarca de la familia Valor\n\nLord Grant (que en paz descanse) fue el máximo exponente de la excelencia de la Alianza. Un líder nato, cuya mano firme guio a los habitantes del Cerro del Cuervo hacia la prosperidad. Cuando la oscuridad comenzó a tomar los bosques, fue el primero en movilizar a nuestro pueblo.\n\nPara lord Grant no existía enemigo más repugnante que los no-muertos. Patrullaba personalmente los cementerios del Bosque del Ocaso para mantener a raya a los siervos de la oscuridad. El día que recibió un golpe mortal, todos en la ciudad compartieron su dolor.\n\nGracias al cuidado de su familia, logró volver a sus obligaciones, pero, desde entonces, una persistente dolencia le acompañaría durante el resto de sus días.", "Lady Cassandra Valor, madre amantísima y amada esposa\n\nPoco se sabe sobre Cassandra, salvo su amor por su familia. Crio a unos hijos valientes y cuidó de un marido poderoso, lo que ha llevado a algunos a pensar que la grandeza de la familia se debía exclusivamente a ella. Un halago que la misma Cassandra siempre rechazaba con elegancia.\n\nSi no se la recuerda por nada más, que quede claro que todo lo que hizo fue por su familia." } } },
    ["Merrin's Letter"] = { { ids = { "i2639" }, first = "mydearesttarrelexcusethe", pages = { "Mi querido Tarrel:\n\nTe ruego disculpes las prisas con las que escribo esta carta, pero el tiempo no es un lujo del que dispongamos por aquí.\n\nEl equipo de excavación ha realizado grandes avances desenterrando importantes artefactos de los titanes. Pero empezamos a descubrir otros objetos antiguos, especialmente huesos largos.", "Poco después de excavar los huesos, fuimos víctimas del ataque de raptores. El batallón de hombres del regimiento Largatrenza luchó valientemente. Pero, finalmente, fueron arrollados. Casi todos murieron. Solo 3 de nosotros sobrevivimos. Un peón llamado Ormer Trenzaferro demostró mayor valentía, pues se encargó de velar por mi seguridad y la del prospector Whelgar.", "Ahora nos hemos refugiado en una cueva protegida, al parecer a salvo del peligro. Pero, sin duda, hasta que no recibamos refuerzos para hacer frente a los raptores, estamos atrapados. Whelgar intenta continuar trabajando, pero sospecho que sigue bastante asustado. Esa es nuestra situación, Tarrel. Dile a Largatrenza que reúna un comando de rescate inmediatamente.\n\nMi amor por ti sigue siendo fuerte, incluso en estos azarosos tiempos.\n\nMerrin" } } },
    ["Message from Emily"] = { { ids = { "i209029" }, first = "thegetawayplanisagowelea", pages = { "El plan de huida está en marcha. Salimos esta noche.\n\nSolo queda una última cosa. He escondido un alijo con equipo en las Colinas Afiladas, en la entrada trasera de las Minas de la Muerte. La llave para abrirlo está en este sobre. Espero que no lo necesitemos, pero nunca se sabe.\n\nCuánto me alegro de que por fin podamos dejar atrás todo este asunto de los Defias. Mañana a esta hora estaremos tomando el sol en las playas de Tuercespina.\n\nSiempre tuya,\nEmily" } } },
    ["Metzen's Letters and Notes"] = { { ids = { "i21314" }, first = "onbehalfofsmokywoodpastu", pages = { "En nombre de los Pastos de Bosquehumeante, te vuelvo a dar las gracias por ocuparte de esto. No estamos seguros de cuál es el grupo que tiene a Metzen, pero investigar cualquiera de los dos puede constituir un buen punto de partida.\n\nEl tiempo es dinero, $gamigo mío:amiga mía; y, en este caso, tenemos muy poco. Sé rápido en tus tareas de rescate, ya que estos grupos no deben ser subestimados en lo que respecta a lo que son capaces de hacer.\n\nEn cualquier caso, las dos páginas siguientes son las notas de rescate que hemos recibido. ¡Buena suerte!", "Si quieres que el reno vuelva con vida, deberás ser rápido con la recompensa. Los Piratas de los Mares del Sur no se muestran amables cuando hay retrasos en el pago y sabemos lo valiosa que resulta esta bestia para TU forma de piratería.\n\nTrae la suma de 100 piezas de oro a la entrada de la cala del Aparejo Perdido en Tanaris. Cualquier intento por rescatar al reno hará que Metzen dé un paseo muy largo sobre una plancha muy corta.\n\nSí...\n\nLos Piratas de los Mares del Sur", "Tu apreciada mascota no lo está pasando demasiado bien con el implacable calor de la Garganta de Fuego... Si eres listo, deberás cumplir nuestras peticiones sin demora.\n\nDebes traernos cinco rubíes estrellados y la suma de 700 piezas de oro. Coloca todo en un solo paquete sin marca alguna. Deja el paquete en las puertas del Paso de Fraguapiedra en el plazo de una semana.\n\nSi no accedes a nuestras peticiones, Metzen se convertirá en el plato principal del Festival de Invierno de los enanos Hierro Negro.\n\nMmmm... reno...", "Más rápido que las águilas llegaron sus corceles,\n\ny él silbó, grito y los llamó por su nombre, \"¡Arre, Mercer! ¡Arre, Chilton! ¡Arre, Jordan y Kaplan!\n\n¡Adelante, Nagle! ¡Adelante, Pardo! ¡Adelante, Goodman y Metzen!\n\n¡Hacia lo alto del porche! ¡Hacia lo alto del muro!\n\n¡Ahora salid de aquí! ¡Fuera de aquí! ¡Fuera de aquí todos!\"" } } },
    ["Military Ranks of the Horde & Alliance"] = { { ids = { "o179707", "i18675" }, first = "militaryranksofthehordea", pages = { "RANGOS MILITARES DE LA HORDA Y DE LA ALIANZA\n\n¡Throm'ka! En este\n\nlibro encontrarás\n\nmuchas listas de\n\nrangos militares\n\nde la Horda y\n\nde la insignificante Alianza.\n\nPrimero aparecen los rangos de la\n\nHorda y luego de la Alianza,\n\ncada una con listados de rangos de oficiales y de soldados. Está ordenada de tal manera que los más poderosos aparecen al principio y los más débiles al final.", "RANGOS DE OFICIALES DE LA HORDA\n\nParte 1\n\nGran Señor de la Guerra\n\nSeñor de la Guerra\n\nGran general\n\nGeneral\n\nCampeón", "RANGOS DE OFICIALES DE LA HORDA\n\nParte 2\n\nCenturión\n\nLegionario\n\nGuardia de sangre\n\nGuardia de piedra", "RANGOS DE SOLDADOS DE LA HORDA\n\nGran capataz\n\nCapataz primero\n\nCapataz\n\nBruto\n\nExplorador", "RANGOS DE LOS OFICIALES DE LA ALIANZA\n\nParte 1\n\nGran mariscal\n\nMariscal de campo\n\nMariscal\n\nComandante\n\nTeniente coronel", "RANGOS DE OFICIALES DE LA ALIANZA\n\nParte 2\n\nCampeón caballero\n\nCapitán caballero\n\nTeniente caballero\n\nCaballero", "RANGOS DE SOLDADOS DE LA ALIANZA\n\nAlférez\n\nSargento primero\n\nSargento\n\nCabo\n\nSoldado" } } },
    ["Missing: Corporal Keeshan"] = { { ids = { "o1726" }, first = "missingcorporalkeeshanla", pages = { "Desaparecido: Cabo Keeshan\n\nFue visto por última vez durante la sangrienta batalla del Fuerte de Petravista. Según los informes, fue arrastrado por los orcos Roca Negra.\n\nSe cree que permanece retenido como prisionero de guerra en el campamento Roca Negra, al norte de Villa del Lago, justo al oeste del paso que conduce a las Estepas Ardientes.\n\nPor mandato del magistrado Salomón, todo aquel que colabore en el rescate del cabo Keeshan será recompensado por el Alguacil Marris." } } },
    ["Mists of Dawn"] = { { ids = { "o177207" }, first = "beforetheageofmemorytheg", pages = { "Antes de la Edad de la Memoria, la suave Madre Tierra lanzó su soplo sobre las doradas neblinas de la aurora. Cuando las ambarinas nubes se detuvieron, aparecieron interminables campos de fino trigo y cebada. Este era el cuenco de sus obras: la gran cesta de la vida y la esperanza.", "Los ojos de la Madre Tierra iluminaban las tierras en las que había insuflado la creación. Su ojo derecho, An'she (el sol), proporcionaba luz y calor a la tierra. Su ojo izquierdo, Muy'sha (la luna), proporcionaba paz y sueño a las conmovedoras criaturas de la aurora. Tal era el poder de su mirada, que la Madre Tierra cerraba un ojo soñador en cada giro del cielo. De esta manera, su amorosa mirada convirtió el día en noche para la primera alborada del mundo.", "Mientras el ojo derecho iluminaba la dorada aurora, las suaves manos de la Madre Tierra se extendían a lo largo de las doradas planicies. Allí por donde se extendía la sombra de sus brazos, surgía un pueblo en el rico suelo. Los Shu'halo (los tauren) surgieron para dar gracias y para orar por su amada madre. Allí, en los interminables campos de la aurora, los hijos de la tierra juraron rendirle pleitesía y bendecir su nombre hasta el ocaso final del mundo." } } },
    ["Monument to Grom Hellscream"] = { { ids = { "o21004" }, first = "hereliesgrommashhellscre", pages = { "Aquí yace Grommash Grito Infernal, jefe del clan Grito de Guerra\n\nEn muchos sentidos, la maldición de nuestro pueblo empezó y acabó con Grom.\nSu nombre significa 'corazón de gigante' en nuestra antigua lengua. Se ganó ese nombre, y con mucho honor, cuando se enfrentó solo al demonio Mannoroth\ny obtuvo nuestra libertad con su sangre.\n\nLok'Tar ogar, hermano. Que el clan Grito de Guerra nunca desaparezca.\n\nThrall, Jefe de Guerra de la Horda" } } },
    ["Mor'zul's Instructions"] = { { ids = { "i18818" }, first = "tobindadreadsteedyoumust", pages = { "Para matar a un terrorecus, debes realizar estas tres tareas:\n\nCrear un círculo de invocación superior.\n\nDentro del círculo, abre un portal hacia Xoroth y conduce al terrorecus a través del portal.\n\nDerrota al terrorecus y luego domina su espíritu.\n\nEn las siguientes páginas encontrarás una explicación detallada de cómo realizar esta tarea. Puede que no sea fácil, pero has demostrado ser muy capaz. Sin duda, con concentración y habilidad, el terrorecus será tuyo.\n\nContinúa leyendo,\nMor'zul Sangredoble", "Instrumentos de un ritual\n\nAntes de que inicies tu trabajo, deberás disponer de los siguientes instrumentos mágicos:\n\nTarro de J'eevee\nMagnetita\nGlifos xorotianos\n\nMi sirviente Gorzeeki lo tiene y te lo puede ofrecer a buen precio. No intentes siquiera realizar el ritual si no dispones de todos estos instrumentos. Todos resultan esenciales.\n\nEn las siguientes páginas, describiré cómo utilizar cada uno de ellos.", "Círculo de vínculo superior\n\nEs preciso crear un círculo de vínculo superior en un lugar en el que la magia tenga fuerza. En medio de las ruinas de Eldre'Thalas, encontrarás un sitio de estas características, también llamado La Masacre. En Eldre'Thalas se encuentra prisionero un ser de gran poder, Immol'thar. En el pedestal de su prisión debes realizar el ritual para crear el círculo.\n\nEncuentra tu camino hasta el pedestal y luego deja que J'eevee salga de su tarro.", "La Campana, la Rueda y la Vela\n\nCuando liberes a J'eevee, este colocará la Campana, la Rueda y la Vela, y aparecerá un círculo. Este es el comienzo del ritual. Debes estar alerta. Los objetos antes mencionados transmiten una gran cantidad de energía y son propensos a fallar. Cuando esto ocurra, deberás usar la magnetita para reiniciarlos, antes de que fracase todo el ritual.\n\nSi los tres objetos han fallado antes de que logres reiniciarlos, el ritual terminará y deberás comenzar de cero.", "Además de transmitir las energías del ritual, la Campana, la Rueda y la Vela tienen propiedades únicas.\n\nCuando suena, la Campana de Dethmoora confiere vigor y energía a los brujos que estén dentro del círculo.\n\nCuando gira, la Rueda de la Marcha Negra protege de cualquier daño a los que están dentro del círculo.\n\nLa Vela del Apocalipsis, cuando arde, envía una extraña energía a los enemigos que entran en el círculo.\n\nGracias a estos dones, es muy importante que todos estos objetos funcionen durante el ritual.", "Tienes que tener en cuenta que la magnetita, utilizada para reiniciar la Campana, la Rueda o la Vela si fracasan, requiere fragmentos de alma. Cada vez que reinicies un objeto ritual con la magnetita, se consumirá uno de tus fragmentos de alma, así que asegúrate de tener suficientes reservas de fragmentos antes de iniciar el ritual.", "Cómo completar el ritual\n\nPuedes anotar tus progresos utilizando las runas mágicas situadas a lo largo del borde del círculo. Cuando aparezcan nueve runas, el ritual se habrá completado y verás cómo surge la energía desde el círculo recargado.\n\nDesde aquí, podrás invocar a los glifos xorotianos y abrir un portal hacia Xoroth para hacer pasar un terrorecus por él.\n\nDerrota al terrorecus y libera su espíritu. Enfréntate al espíritu y este quedará embelesado. Entonces, será recompensado con el secreto de su invocación." } } },
    ["Mount Hyjal and Illidan's Gift"] = { { ids = { "o175729" }, first = "thefewnightelvesthatsurv", pages = { "Los escasos elfos de la noche que sobrevivieron a la explosión se subieron a rústicas balsas y lentamente se dirigieron a la única masa de tierra visible. De algún modo, por la gracia de Elune, Malfurión, Tyrande y Cenario sobrevivieron al Gran Diluvio. Los maltrechos héroes guiaron a sus compañeros supervivientes y se establecieron en un nuevo lugar.", "Mientras viajaban en silencio, examinaron los restos de la catástrofe y comprendieron que sus pasiones habían sido la causa de la destrucción del planeta. Aunque Sargeras y su Legión habían sido aniquilados por la destrucción del Pozo, Malfurión y sus compañeros sobrevivieron para reflexionar sobre el terrible precio de la victoria.", "Por su parte, muchos altonatos salieron ilesos del cataclismo. Se dirigieron a las costas de la nueva tierra, junto con los otros elfos de la noche. Aunque Malfurión desconfiaba de los altonatos, estaba tranquilo porque no podían causar verdadero daño sin las energías del Pozo.", "Cuando los elfos de la noche arribaron a las costas de la nueva tierra, advirtieron que Hyjal, la montaña sagrada, había sobrevivido a la catástrofe. Con la intención de establecer un nuevo hogar para todos, Malfurión y los elfos de la noche subieron por las laderas del Monte Hyjal y llegaron a la cima azotada por el viento. Al descender en la boscosa hondonada, entre los enormes picos de las montañas encontraron un pequeño lago de aguas mansas. Aterrorizados, descubrieron que las aguas del lago estaban contaminadas por la magia.", "Illidan, que también había sobrevivido al Diluvio, había subido a la cima del Monte Hyjal mucho antes que Malfurión y sus elfos de la noche. En su locura por conservar un reducto para la magia en el mundo, Illidan volcó en el lago de la montaña el contenido de sus viales: las preciosas aguas del Pozo de la Eternidad.", "Las potentes energías del Pozo ardieron rápidamente y se fusionaron para crear un nuevo Pozo de la Eternidad. El exultante Illidan, que creía que el nuevo Pozo era un regalo para las futuras generaciones, se sorprendió al advertir la ira de Malfurión. Este explicó a su hermano que la magia era inherentemente caótica y que su uso conduciría inevitablemente a la propagación de la corrupción y la guerra. No obstante, Illidan se negó a renunciar a sus poderes mágicos.", "Conociendo de sobra hacia dónde conducirían los implacables planes de Illidan, Malfurión decidió neutralizar de una vez por todas a su hermano enloquecido por el poder. Con la ayuda de Cenarius, Malfurión encerró a Illidan en un gran túmulo subterráneo, en el que permanecería encadenado e impotente hasta el final de sus días. Para garantizar el confinamiento de su hermano, Malfurión encargó al joven guardián Maiev Cantosombrío la tarea de vigilar personalmente a Illidan.", "Preocupado ante la certeza de que la destrucción del nuevo Pozo conllevaría una catástrofe aún mayor, los elfos de la noche decidieron dejarlo en su lugar. No obstante, Malfurión declaró que nadie volvería jamás a practicar las artes de la magia. Bajo la mirada atenta de Cenarius, empezaron a estudiar las antiguas artes de los druidas con el propósito de sanar el planeta herido y replantar sus bosques amados en la base del Monte Hyjal." } } },
    ["Mountaineer Gretchen's Report"] = { { ids = { "i280430" }, first = "areportonthestateofwendi", pages = { "Informe sobre el estado de los wendigos en las cuevas cercanas a Kharanos\n\nEscrito por la montaraz Gretchen según los hallazgos del montaraz Cornelius\n\nLos wendigos rara vez abandonan sus cuevas, pero hay informes de ataques contra civiles alrededor de asentamientos cercanos como Kharanos y Las Birras. Parecen cada vez más agitados en su búsqueda de alimento. Ya hemos perdido a uno de los nuestros en los esfuerzos por contenerlos. Aunque eliminar por completo a estas bestias resulta impracticable, los montaraces solicitan", "recursos adicionales para limitar su expansión. No podemos seguir enviando aventureros contra el problema y esperar lo mejor. Tarde o temprano se acabará la comida y los wendigos se verán obligados a atacar directamente nuestras ciudades. Quizá incluso la propia Forjaz.\n\nTransmitid mis condolencias a la familia del montaraz Cornelius, que luchó con valor para proteger a los habitantes de Dun Morogh." } } },
    ["Muddy Journal Pages"] = { { ids = { "i938" }, first = "mostcertainthatsheshares", pages = { "... estoy tan seguro de eso como que ella me corresponde. Esta mañana, incluso, posó su mano en la mía. Cuando sonríe, sus ojos brillan como diamantes. Nos entendemos con solo mirarnos. Puedo sentirla en los latidos de mi corazón y en mis acaloradas venas.", "... ¡Me invadió una ira hasta ahora desconocida! ¡Cómo se atreve! Cuando enseñaba a Giles el misterio de los números, Tilloa apareció con un pretendiente... ¡los dos cogidos de la mano, y en público! Qué joven más zafio. En lugar de presentarnos como es debido, Tilloa simplemente dijo: \"Oh, este es el tío Stalvan, mi tutor. Es un viejo muy agradable\". ¡Viejo! Esa palabra hizo que la sangre estallara en mis mejillas. Si solo soy unos cuantos años mayor que ella y, aún así, ella me traiciona de esa manera..." } } },
    ["Muddy Note"] = { { ids = { "i2720" }, first = "dayamtoamuppercampamtoam", pages = { "Primer día:\n6am a 11am: campamento alto\n11am a 11:30am: descanso para comer\n11:30am a 4:00pm: paso del cañón\n4:00pm a 7:30pm: campamento alto\n\nSegundo día:\nEl mismo itinerario que el del primer día\n\nTercer día:\nEl mismo itinerario\n\nCuarto día:\nEl mismo itinerario, con una excepción. Justo antes del atardecer, Thorsen me pidió que lo cubriera mientras atravesaba el paso del cañón. Supongo que fue a encontrarse con nuestros agentes.\n\nPero regresó una hora más tarde. Esto me sorprendió. Esperaba que se reuniera con nuestros agentes y que se reincorporara a Kurzen. Algo va mal.", "Quinto día:\nThorsen estuvo muy inquieto hoy. Aquello que vio o la persona que encontró en su excursión de ayer debió de asustarle mucho.\n\nCreí que nuestros agentes habían hablado con él, pero cuando pregunté a Thorsen adónde había ido mientras yo lo cubría, permaneció callado. Él se considera mi amigo y cree que me está protegiendo de un secreto peligroso.\nSu lealtad es errónea, pero fuerte. Cuando se reincorpore a nosotros, será una adquisición valiosa para las fuerzas de Kurzen.", "Sexto día:\nA primera hora de la mañana, Thorsen habló largamente con el sargento Yohwa. Tuve que fingir que dormía para permanecer cerca y oír la conversación. Pero supongo que hablaron de la excursión de Thorsen.\n\nLo observé atentamente durante la comida y vi que Yohwa hacía lo mismo. Más adelante, Doren llamó a Thorsen. Los tres comparten un secreto. Doren y Yohwa deben saber que Thorsen se está quedando con tus agentes.\n\nHace de espía para los rebeldes.", "No podemos darle a Thorsen más información y debemos matarlo. Ya no es útil para nuestro Coronel.\n\nAcabaré con Thorsen en cuanto tenga la oportunidad, pero si recibes esta carta, sabrás que aún no he podido hacerlo.\n\nEn tal caso, propongo que la siguiente reunión de Thorsen con nuestros agentes sea decisiva.\n\nSalve Kurzen,\nM" } } },
    ["Mysterious Orders"] = { { ids = { "i265782" }, first = "brotherhaalienitistimeto", pages = { "Hermano Haalien:\n\n¡Ha llegado el momento de demostrar tu valía a los Al'Aketh! Adéntrate en Ventosombra y localiza el pilón. Has expresado tus inquietudes acerca de los druidas, y la plana mayor de nuestra orden te ha escuchado.\n\nLlévate a estos fieles soldados en tu justa misión, y dad muerte a los druidas con presteza, no sea que interfieran en nuestros planes. Tenemos ojos y oídos en Valanaar que nos confirmarán si habéis tenido éxito.\n\n¡Se acerca la hora de la verdad! ¡No habrá quien nos detenga!\n\n-N" } } },
    ["Mythology of the Titans"] = { { ids = { "i5536" }, first = "nooneknowsexactlyhowtheu", pages = { "Nadie sabe exactamente cómo se originó el universo. Algunos conjeturan que una terrible explosión cósmica lanzó hacia la vasta inmensidad de la Gran Oscuridad mundos infinitos que giraron en órbita, mundos que posteriormente albergarían diversas formas de vida, extraordinarias y terribles a la vez. Otros creen que el universo, tal como existe hoy, fue creado como un todo por una entidad singular y todopoderosa.", "Si bien los orígenes exactos del caótico universo siguen sin esclarecerse, existe la certeza sobre el nacimiento de una raza de seres poderosos que puso orden en los mundos, para garantizar un futuro seguro para las criaturas que seguirían sus pasos.\n\nLos titanes, dioses colosales de piel metálica procedentes de los confines del cosmos, llegaron hasta aquí y empezaron a ocuparse de los planetas que encontraron. Configuraron estos espacios, levantando poderosas montañas y formando vastos océanos.", "Originaron cielos y atmósferas tormentosas, siguiendo un plan insondable para crear orden a partir del caos. Incluso otorgaron poderes a las razas primitivas para que se ocuparan de sus trabajos y mantuvieran la integridad de sus respectivos universos.\n\nLos titanes, gobernados por una secta de élite conocida como Panteón, llevaron el orden a cientos de millones de mundos diseminados por la Gran Oscuridad del Más Allá durante los primeros años de la creación.", "El benevolente Panteón, con la intención de salvaguardar las estructuradas sociedades de estas razas, estaba siempre atento a la amenaza de seres malignos y extradimensionales del Vacío Abisal. El Vacío Abisal, una dimensión etérea de magia caótica que interconectaba miríadas de planetas, albergaba un número infinito de seres malignos y demoníacos cuya única finalidad era destruir la vida y agotar las energías del universo viviente." } } },
    ["Naga Manuscript"] = { { ids = { "i211777" }, first = "", pages = { "<El manuscrito muestra un mapa de tres cristales de la Ensenada de Zoram. Entre ellos hay trazado un camino ordenado, de sur a norte. Junto a cada cristal aparece el dibujo de una explosión de magia arcana.>" } } },
    ["Nat Pagle's Guide to Extreme Anglin'"] = { { ids = { "i18229" }, first = "andsothatswhereyoullfind", pages = { "... y, de esta manera, allí es donde encontrarás la legendaria espada del Alto Señor Escarlata, conocido como Crematoria.\n\n¿No es increíble lo que puedes encontrarte en un día de pesca cualquiera?" } } },
    ["Neeka's Report"] = { { ids = { "i6167" }, first = "helgrummycomplimentstowh", pages = { "Helgrum,\n\nDeseo dar mi enhorabuena a aquel que haya dado la orden de establecer nuestra base en Kargarth, en las Tierras Inhóspitas. Es un lugar perfecto para adiestrar a nuestras tropas. El clima riguroso, su fauna salvaje y la falta absoluta de asistencia convierten a este enclave en un crisol que solo dará lugar a los mejores guerreros.\n\nBien pensado. Bien hecho.", "Describiré las tierras vecinas teniendo en cuenta las tareas de reconocimiento de los exploradores de Kargath.\n\nSe trata de colinas rojizas y rocosas y de planicies secas, resultando poco habitables.\nEl sol es abrasador y hay fuertes vientos.\nNo hay lagos ni corrientes. Ni siquiera charcas aisladas. Para encontrar agua, los nativos deben cavar pozos profundos y llenos de barro, o bien succionar la escasa humedad de los cactus o hierbajos espinosos.\n\nEn resumen: aquí la vida es difícil, en un entorno muy caluroso.", "Las Tierras Inhóspitas están llenas de enemigos. Los ogros vagan por las arenas ardientes, tendiendo emboscadas a los incautos. Los enanos Hierro Negro habitan unos cuarteles al este de Kargath y luchan contra sus primos de tez clara en Loch Modan, situado al norte. Unas bestias brutales y primitivas llamadas troggs dan caza a todo ser vivo y lo atacan salvajemente.\n\nY en las Tierras Inhóspitas del este, en el barranco Lethlor, habitan los dragones. No sabemos cuántos son ni qué tamaño tienen, pues los exploradores que se acercan demasiado nunca regresan.", "No hace falta decir que los que acampamos en Kargath estamos muy contentos con nuestra misión. Aquí nos hacemos fuertes, porque si nos descuidamos, morimos.\n\nY no quisiera que fuera distinto.\n\nNeeka Marca de Sangre\nJefa de exploradores, Kargath" } } },
    ["Nostro's Compendium of Dragon Slaying"] = { { ids = { "i18401" }, first = "fororscompendiumofdragon", pages = { "El Compendio de matar dragones de Foror es un grueso libro lleno de escritura. Por desgracia, el texto parece confuso y no tiene sentido para ti." } } },
    ["Note from Ba'so"] = { { ids = { "i207098" }, first = "ivegotthegoodsillbehidin", pages = { "Tengo la mercancía. Me esconderé al oeste del Fuerte de Tiragarde, bajo un árbol de hojas oscuras. Si envías a uno de tus agentes a recogerla, ¡asegúrate de que no lo vean!\n\n- Ba'so" } } },
    ["Of Love and Family"] = { { ids = { "i14679" }, first = "", pages = { "" } } },
    ["Old Hatreds - The Colonization of Kalimdor"] = { { ids = { "o175763" }, first = "thoughvictorywastheirsth", pages = { "Aunque la victoria fue suya, las razas mortales se encontraron con un mundo destruido por la guerra. La Plaga y la Legión Ardiente lo tenían todo, pero destruyeron las civilizaciones de Lordaeron y casi dieron por terminado su trabajo en Kalimdor. Había bosques que replantar, rencores que enterrar y hogares que fundar. La guerra había provocado profundas heridas en todas las razas, pero todas ellas habían hecho causa común para intentar un nuevo comienzo, empezando por la precaria tregua entre la Alianza y la Horda.", "Thrall condujo a los orcos hacia el continente de Kalimdor, en donde fundaron un nuevo hogar con la ayuda de sus hermanos tauren. Llamándolo Durotar, para recordar al padre asesinado de Thrall, los orcos se asentaron para reconstruir su sociedad antaño gloriosa.", "Ahora que la maldición del demonio había terminado, la Horda pasó de ser un gigante bélico preparado para la guerra a ser una coalición más flexible, dedicada a la supervivencia y la prosperidad antes que la conquista. Ayudado por el noble tauren los astutos trols de la tribu Lanza Negra, Thrall y sus orcos miraron hacia el futuro, esperanzados en una nueva era de paz en su propia tierra.", "Las restantes fuerzas de la Alianza, bajo la égida de Jaina Valiente, se asentaron en el sur de Kalimdor. Desde la costa oriental del Marjal Revolcafango, construyeron la tosca ciudad portuaria de Theramore. Allí, los humanos y sus aliados enanos trabajaron para sobrevivir en una tierra que siempre les había sido hostil. Aunque los defensores de Durotar y Theramore trataron de mantener la tregua en vigor, la frágil paz colonial no habría de durar mucho.", "La paz entre los orcos y los humanos se quebró debido a la llegada de una gran flota de la Alianza a Kalimdor. La poderosa flota, bajo las órdenes del gran almirante Daelin Valiente (el padre de Jaina), había abandonado Lordaeron antes de que Arthas destruyera el reino. Habiendo navegado penosamente durante meses, el almirante Valiente buscaba a todos los posibles supervivientes que quedaran de la Alianza.", "La armada de Valiente resultó ser una seria amenaza para la estabilidad de la región. Como héroe reconocido de la Segunda Guerra, el padre de Jaina era acérrimo enemigo de la Horda y estaba decidido a destruir Durotar antes de que los orcos llegaran a poner un pie en su tierra.", "El gran almirante obligó a Jaina a tomar una terrible decisión: Debía apoyarlo en la batalla contra los orcos y traicionar a sus nuevos aliados, o bien luchar contra su propio padre para mantener la frágil paz que la Alianza y la Horda habían suscrito. Tras mucho cavilar, Jaina escogió la última opción y ayudó a Thrall a derrotar a su enloquecido padre.", "Desafortunadamente, el almirante Valiente murió en la batalla, antes de que Jaina pudiera reconciliarse con él o demostrarle que los orcos ya no eran aquellos monstruos sedientos de sangre. Por su lealtad, los orcos permitieron que las fuerzas de Jaina regresaran sanos y salvos a Theramore." } } },
    ["Orders from the Grand Crusader"] = { { ids = { "i216610" }, first = "byorderofgrandcrusaderda", pages = { "Por orden del gran cruzado Dathrohan:\n\nEl hereje conocido como Aeonas el Callado queda condenado por los graves delitos de aliarse con demonios y no-muertos, renunciar a la Luz, hurto y asesinato. Se sabe que esta vil criatura ha matado al menos a dos de nuestros firmes hermanos de la Luz mientras robaba bienes importantes de la Cruzada Escarlata. Cuando lo encuentren, se trasladará al hereje al Monasterio de Tirisfal para interrogarlo y ejecutarlo. Cualquier paquete o artefacto que tenga al ser apresado deberá devolverse con toda rapidez al Gran Cruzado como prueba.\n\nSi capturáis a Aeonas, amordazadlo. Nadie salvo el Alto Inquisidor podrá hablar con él, no sea que sus mentiras insidiosas siembren caos y dudas en corazones rectos. Estad atentos, hermanos y hermanas, pues no sabemos qué magias viles ha obtenido Aeonas en sus tratos perversos con los enemigos de la Luz." } } },
    ["Orman of Stromgarde"] = { { ids = { "o175779" }, first = "ormanofstromgardethefirs", pages = { "Orman de Stromgarde\nPrimer Capitán General de la Cruzada Escarlata\nCiudadano de Stromgarde\nPerdido en la boca del Glaciar Corona de Hielo" } } },
    ["Peeling the Onion"] = { { ids = { "i19483" }, first = "peelingtheonionthehowtog", pages = { "Pelar la cebolla\nGuía para desmantelar a los Pico Tormenta\n-Por Drek'Thar\n\nEn estas páginas encontrarás amplios conocimientos sobre tácticas de guerra y política. Un soldado instruido es un soldado que se apoya en la experiencia. Utiliza este libro como guía en tu batalla por el Valle de Alterac.", "Capítulo 1 - El frente\n\nDesmantelar el ejército de los Pico Tormenta es una tarea similar a la de pelar una cebolla. Para llegar al núcleo, hay que empezar eliminando las capas exteriores.\n\nLas líneas del frente, que comprenden fundamentalmente a los montaraces Pico Tormenta y los Centinelas de la Alianza, están ligadas al búnker del capitán. Es el capitán Balinda Corapernal el que da poder a estas unidades y proporciona los refuerzos necesarios cuando las líneas están bajo sitio. Golpea al capitán y las líneas del frente se quebrarán.", "Capítulo 2 - Las Torres Gemelas\n\nNo te equivoques, Vanndar Pico Tormenta es un enemigo astuto y, ciertamente, no es nada tonto. Una vez rota la línea del frente, es preciso destruir los objetivos defensivos de carácter secundario. Se trata de las torres gemelas de Piedrahogar y Ala Gélida, que controlan los Soldados de Pico Tormenta, lejos de Dun Baldar y de las patrullas Pico Tormenta.", "Ten cuidado, Soldado, ya que ambas torres están muy bien fortificadas y están capitaneadas por uno de los Comandantes de élite de Vanndar. Cuando tus fuerzas rompan las fortificaciones, asegúrate de que el Comandante que está en su interior haya sido... silenciado. Esta última tarea también forma parte del desmantelamiento de Pico Tormenta.", "Capítulo 3 - Los cuatro Comandantes\n\nLa tercera capa de cebolla del ejército Pico Tormenta comprende a los cuatro Comandantes. A este respecto, Vanndar ha imitado a nuestras gloriosas defensas Lobo Gélido. Lógicamente, él te diría otra cosa... Pero me estoy desviando de la cuestión.\n\nLos cuatro Comandantes controlan el flujo y reflujo de los Soldados de Pico Tormenta que defienden Dun Baldar con valentía. Ocúpate de silenciarlos y los Soldados Pico Tormenta caerán.\n\nAhora solo queda una capa por pelar.", "Capítulo 4 - Los búnkeres de Dun Baldar\n\nComo ya habrás advertido, las capas defensivas de Pico Tormenta están colocadas de tal manera que impidan que un movimiento enérgico pueda desmantelar todo el ejército. Antes de que preguntes, sí, coincide exactamente con la forma en que están desplegadas nuestras fuerzas... y no, no pienso modificar nuestra estructura defensiva. Ellos nos copiaron a nosotros, ¿por qué habría de cambiar?", "¿Por dónde iba? Ah, sí, los búnkeres de Dun Baldar (situados en Dun Baldar), controlan a los defensores Pico Tormenta, las unidades de guardia de élite y los hombres de mayor confianza de Vanndar. Destruye las dos torres y los refuerzos enviados para ayudar a Vanndar dejarán de existir.", "Epílogo\n\nUna vez que hayas hecho todo esto, te queda el centro de la cebolla: El dulce núcleo. Vanndar Pico Tormenta estará solo e indefenso. Las reglas de conducta militar requieren que, antes de realizar tareas de limpieza, le preguntemos si desea rendirse. En cuanto le veas, asegúrate de mencionarle lo de la rendición y luego... mátalo." } } },
    ["Petrified Bark"] = { { ids = { "i18708" }, first = "simonetheseductressyouwi", pages = { "Simone la Seductora:\n\nEncontrarás a Simone contaminando el cráter Un'Goro. No te dejes engañar por su disfraz. Aproxímate a ella con cuidado y rétala a un combate.", "Klinfran el Enloquecido:\n\nKlinfran vaga por las Estepas Ardientes. Acércate a él con precaución y oblígale a mostrarte su verdadera forma.", "Solenor el Destripador:\n\nEn los áridos parajes de Silithus vaga el desalmado Solenor el Destripador. Indudablemente, aparecerá disfrazado y, definitivamente, es un peligro. Acércate a él y oblígale a transformarse.", "Artorius el Fatídico:\n\nArtorius trae la corrupción y la maldición a todo lo que toca en Cuna del Invierno. Encuéntralo y mátalo.", "Ten cuidado, cazador, debes combatir a estos demonios según sus reglas. Si sienten que no son superiores a ti, sin duda huirán.\n\nVE SOLO." } } },
    ["Podrig's Order"] = { { ids = { "i16209" }, first = "byorderofhighexecutorhad", pages = { "Por orden el Sumo Ejecutor Hadrec, he aquí un listado de los elementos necesarios para mantener las existencias de El Sepulcro:\n\n12 espadas largas\n9 dagas\n8 escudos redondos\n15 hachas\n1000 flechas\n\nEsta orden debe considerarse como una orden directa de la Dama Oscura y los responsables serán llevados ante Su presencia, como ocurriría con cualquiera que se opusiera u obstaculizara Sus deseos." } } },
    ["Prismatic Punch Card"] = { { ids = { "i9316" }, first = "thesecurityratingofthisd", pages = { "¡El nivel de seguridad de estos datos es TAN alto, que aún no se ha inventado una cifra que sirva para describirlo!", "" } } },
    ["Proof of Deed"] = { { ids = { "i10022" }, first = "thisproofofdeedistoverif", pages = { "Este documento sirve para verificar si $N asesinó a Margol la Furiosa, miembro de la Plaga en la Garganta de Fuego.\n\nEl museo de Forjaz reconoce esta hazaña y agradece $gal portador:a la portadora; por su generosa contribución.\n\nComisario principal, Thorius Tienrroca" } } },
    ["Pteradon Skeleton"] = { { ids = { "o175685", "o177222" }, first = "thisintactpteradonskelet", pages = { "Este esqueleto de pteradon intacto fue descubierto en el remoto cráter de Un'Goro. Basándonos en la estructura del esqueleto, resulta evidente que aún no se ha determinado su género. Este esqueleto quizás se conservó durante varios siglos bajo el rico suelo de la región." } } },
    ["Quel'Thalas Registry"] = { { ids = { "i15847" }, first = "entrydateunknownnamenath", pages = { "Fecha de entrada: Desconocida\n\nNombre: Nathanos Marris, Especialista humano, señor de Lordaeron.\n\nEntrada:\n\nLa oposición de Kael'thas Caminante del Sol en relación con mi decisión de permitir a Nathanos Marris ingresar en la orden resulta evidente. Asimismo, hay que tener en cuenta que Nathanos, si bien es un humano, es uno de los especialistas mejor dotados que he tenido el placer de formar.\n\n(continuación)", "Durante milenios, hemos estado aislados de los extraños. Seré el primero de los nuestros que admita los errores que se han cometido en el pasado. Los humanos nunca deberían haberse expuesto al influjo de la magia. No negaré esto último, pero no pienso ser el que nos condene a una existencia cautelosa a causa de los errores de nuestros predecesores. Es mucho lo que la coexistencia entre los Quel'dorei y otras razas de este mundo puede aportar. Debemos practicar la tolerancia.\n\n(continuación)", "Con estas palabras, niego la petición de Kael en relación con Nathanos Marris. Demostrará ser un valioso aliado. Ya verás.\n\nSylvanas Brisaveloz\nGeneral especialista de Lunargenta" } } },
    ["Rabine's Letter"] = { { ids = { "i17355" }, first = "layowehavereceivedthegen", pages = { "Layo:\n\nHemos recibido la generosa ayuda de nuestro valiente aventurero. Te he enviado al aventurero a Silithus para que dispongas de él como un recurso más. Asegúrate de que este recurso tan valioso no se desperdicie en tus esfuerzos por descubrir los secretos que hay allí. El Círculo espera ansiosamente noticias sobre nuevos avances.\n\nQue Cenario vele por ti...\nRabine" } } },
    ["Ranger Captain Alleria Windrunner"] = { { ids = { "o25331" }, first = "rangercaptainalleriawind", pages = { "Capitana forestal Alleria Brisaveloz\n\nCélebre cazadora de trols de Quel'Thalas. Exploradora jefe y agente de inteligencia de la Expedición de la Alianza que marchó al mundo natal de los orcos, Draenor. Presuntamente fallecida.\n\nTu corazón volaba tan certero como cualquier flecha en el viento, hermana. Eras la más brillante de nuestra Orden. Eras la más querida de los nuestros.\n\n- Sylvanas Brisaveloz, general forestal de Quel'Thalas" } } },
    ["Raven Hill Tome"] = { { ids = { "i281046" }, first = "memoriesofvalorarecounto", pages = { "Memorias de los Valor\nUna crónica de la familia Valor y su servicio al Cerro del Cuervo\n\nNo había familia más grandiosa en todos los Reinos del Este que los Valor. Sus hazañas en defensa del pueblo al que juraron proteger fueron auténticos milagros, y su pérdida es una tragedia para el Cerro del Cuervo.\n\nEscribo este relato para que quede constancia de lo brillantes que fueron Grant, Ira, Silvia y Merrick. Que estas líneas sirvan de pequeño consuelo ante lo mucho que lamento su ausencia.", "Merrick Valor, guardia de Villa Oscura\n\nMerrick era el hijo menor de los Valor. Al ver cómo llegaba la corrupción a su patria, eligió unirse a la Guardia en un intento desesperado de proteger a sus seres queridos.\n\nAunque era el más inexperto de la familia, pronto se hizo un nombre entre los guardias. Tenía talento para el arco y se convirtió en uno de los defensores más firmes de Villa Oscura.\n\nSu misión personal era mantener seguros los caminos, atento a las criaturas cada vez más hostiles que llegaban a los bosques.", "Silvia Valor, guardia del Cerro del Cuervo\n\nSilvia Valor ya era toda una heroína local cuando le ofrecieron unirse a la guardia. Si había algo que no podía soportar más que nada en el mundo, eran los oportunistas que se aprovechaban de la gente en apuros.\n\nBandidos, estafadores, agitadores... Daba igual. Silvia acababa con ellos por tratar de sembrar el caos en su querido hogar. Era lógico que se le asignara un puesto de verdadera autoridad para que pudiera llevar a la práctica su visión de la justicia.\n\nSe dice que, hasta su último aliento, nunca abandonó las granjas y los hogares del Bosque del Ocaso. Y que quizá su vigilia tampoco acabara tras su muerte...", "Ira Valor, acechadora del bosque\n\nCuando el padre de Ira enfermó, ella se encargó de recoger comida y provisiones en los bosques cercanos. Aunque no faltaban recursos, era tan probable encontrar alimento como convertirse en él.\n\nCon los años se adaptó a los bosques y prefirió pasar el tiempo entre los árboles oscuros en vez de en el Cerro del Cuervo. Los viajeros perdidos contaban historias de una sombra que parecía abrirles el camino de vuelta a la carretera. Nadie confirmó quién era, pero los rumores corrieron deprisa.\n\nSe dice que Ira sigue en los bosques, ofreciendo una mano que guía a quienes caen presa de sus bestias.", "Lord Grant Valor, patriarca de la familia Valor\n\nLord Grant (que en paz descanse) fue el máximo exponente de la excelencia de la Alianza. Un líder nato, cuya mano firme guio a los habitantes del Cerro del Cuervo hacia la prosperidad. Cuando la oscuridad comenzó a tomar los bosques, fue el primero en movilizar a nuestro pueblo.\n\nPara lord Grant no existía enemigo más repugnante que los no-muertos. Patrullaba personalmente los cementerios del Bosque del Ocaso para mantener a raya a los siervos de la oscuridad. El día que recibió un golpe mortal, todos en la ciudad compartieron su dolor.\n\nGracias al cuidado de su familia, logró volver a sus obligaciones, pero, desde entonces, una persistente dolencia le acompañaría durante el resto de sus días.", "Lady Cassandra Valor, madre amantísima y amada esposa\n\nPoco se sabe sobre Cassandra, salvo su amor por su familia. Crio a unos hijos valientes y cuidó de un marido poderoso, lo que ha llevado a algunos a pensar que la grandeza de la familia se debía exclusivamente a ella. Un halago que la misma Cassandra siempre rechazaba con elegancia.\n\nSi no se la recuerda por nada más, que quede claro que todo lo que hizo fue por su familia." } } },
    ["Recruitment Letter"] = { { ids = { "i4992" }, first = "hordeconscriptionregistr", pages = { "Registro de Reclutamiento de la Horda\n\nEsta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería ser asignado para trabajar inmediatamente en El Cruce.\n\nRespetuosamente,\n\nMe parece bien.\n- Takrin Abrecaminos" } } },
    ["Red Punch Card"] = { { ids = { "i9281" }, first = "securityratingsupersensi", pages = { "Nivel de seguridad 10^10000 ¡datos súper confidenciales!\n\" } } },
    ["Report on the Defias Brotherhood"] = { { ids = { "i2956" }, first = "fromthehandofbarosalexst", pages = { "\"De la mano de Baros Alexston,\nOficina del arquitecto de la ciudad\nVentormenta\n\nVuestra Majestad,\n\nHay muchas razones por las que consideré que era preciso presentar un informe sobre los asuntos recientes de la Hermandad Defias y sus actividades en todo el reino.\n\nPara poneros en antecedentes, haré un poco de historia. Como sabréis, o quizás desconocéis, empecé a servir a la ciudad de Ventormenta como miembro de la Hermandad de los Albañiles. Durante años de intenso trabajo, terminamos la reconstrucción de", "Ventormenta, momento en el que las facturas y los honorarios de la Hermandad de los Albañiles quedaron sin pagar y sin explicación alguna.\n\nEn aquella época, Edwin VanCleef había sido elegido Maestro de la Hermandad de los Albañiles y exigió las retribuciones por el trabajo realizado. En respuesta, la Casa de Nobles de Ventormenta ordenó la disolución de la Hermandad de los Albañiles, lo que molestó a VanCleef, como es de suponer. VanCleef encabezó un motín de los Albañiles en las afueras de la ciudad.\n\nAntes de continuar, debo mencionar otros acontecimientos que tuvieron lugar durante", "esta época, que conviene resaltar.\n\nEn primer lugar, fue en aquel momento cuando me ofrecieron trabajar como arquitecto de la ciudad si no me unía a VanCleef. Debido a ciertas diferencias ideológicas, elegí permanecer en Ventormenta.\n\nDurante el levantamiento, el teniente y hombre de confianza de VanCleef, Bazil Thredd, fue capturado y recluido en prisión. A la espera de ser juzgado e interrogado, Thredd estuvo a punto de ser olvidado en las mazmorras.\n\nAl regresar con VanCleef, después de dirigir lo que quedaba de", "los Albañiles fuera de Ventormenta, aprovechó la relativa falta de protección de los Páramos de Poniente y utilizó su mano de obra considerable para expulsar a muchos granjeros y tomar posesión de un puñado de minas de oro.\n\nUtilizando los recursos de que disponía, VanCleef urdió un plan de retribución contra el gobierno de Ventormenta.\n\nEsta información fue revelada recientemente con la ayuda del portador de este documento, cuya actuación resultó decisiva a la hora de esclarecer esta importante conspiración." } } },
    ["Rexxar's Testament"] = { { ids = { "i16785" }, first = "thispagedocumentisblank", pages = { "Este documento de 3 páginas está en blanco." } } },
    ["Ripped Note"] = { { ids = { "i4101" }, first = "thatbeastthatreignsovert", pages = { "La bestia que gobierna esta isla es terriblemente poderosa. Las otras criaturas que la habitan se encogen de miedo ante su presencia: El gorila Cieloleno y el acechador Jaguero, ambos por igual. Todavía puedo oír esos rugidos que me hacen estremecer.\n\nEstas criaturas seguro que detendrían a cualquiera que viniera a la isla. Debo tener fe en mis ancestros." } } },
    ["Rise of the Blood Elves"] = { { ids = { "o175760" }, first = "atthistimetheundeadscour", pages = { "En ese tiempo, la Plaga de los no-muertos había convertido Lordaeron y Quel'Thalas en las tóxicas Tierras de la Peste. Hubo muy pocas bolsas de resistencia de la Alianza que le hicieran frente. Uno de estos grupos, que constaba fundamentalmente de elfos nobles, estaba dirigido por el último miembro de la dinastía Caminante del Sol: el príncipe Kael'thas.", "Kael, un experimentado zahorí, se mostró receloso ante el fracaso de la Alianza. Los elfos nobles se lamentaron por la pérdida de su hogar y decidieron llamarse a sí mismos elfos de sangre, en honor a sus caídos. Aun así, como intentaron mantener a la Plaga a raya, sufrieron enormemente al quedar aislados de la Fuente del Sol que les había transmitido su poder.", "Desesperado al intentar encontrar un remedio para la adicción racial de su gente hacia la magia, Kael hizo lo impensable: adoptó al ancestro altonato de su pueblo y se unió con Illidan y sus nagas con la esperanza de encontrar una nueva fuente de poder mágico que les transmitiera su energía. Los demás comandantes de la Alianza consideraron traidores a los elfos de sangre y los desterraron por el bien de la comunidad.", "Sin ningún lugar adonde ir, los elfos de sangre siguieron a Lady Vashj hasta Terrallende para combatir a la carcelera Maiev, que había vuelto a capturar a Illidan. Con las fuerzas conjuntas de los nagas y los elfos de sangre, lograron derrotar a Maiev y liberar a Illidan. Instalado en Terrallende, Illidan reunió a sus fuerzas para golpear por segunda vez al rey Exánime y a su fortaleza de Corona de Hielo." } } },
    ["Rise of the Horde"] = { { ids = { "o175742" }, first = "theorcsbecameincreasingl", pages = { "Bajo el secreto control de Gul'dan y su Consejo de la Sombra, los orcos se volvieron cada vez más agresivos. Construyeron grandes estadios en donde ponían a punto sus virtudes guerreras en pruebas de combate y muerte. Durante este periodo, algunos jefes del clan clamaron contra la creciente depravación de su raza.", "Uno de ellos, Durotar, del clan Lobo Gélido, advirtió contra la posibilidad de que los orcos se perdieran por completo en el odio y la furia. Sin embargo, sus palabras cayeron en saco roto cuando jefes más fuertes como Grom Grito Infernal del clan Grito de Guerra dieron la bienvenida a la nueva era de guerra y dominación.", "Kil'jaeden sabía que los clanes orcos estaban prácticamente preparados, pero necesitaba estar totalmente seguro de su lealtad. En secreto, hizo que el Consejo de la Sombra llamara a Mannoroth el Destructor, la imagen viviente de la destrucción y la ira. Gul'dan convocó al clan de los jefes y les convenció de que beber la hirviente sangre de Mannoroth les haría virtualmente invencibles.", "Conducidos por Grom Grito Infernal, todos los jefes de clan, exceptuando a Durotan, bebieron y, de esta manera, sellaron sus destinos como esclavos de la Legión Ardiente. Gracias al poder de la rabia de Mannoroth, los jefes involuntariamente extendieron su yugo a sus desprevenidos hermanos.", "Consumidos por la maldición de su nueva sed de sangre, los orcos intentaron dar rienda suelta a su furia ante todo aquel que se cruzara en su camino. Sintiendo que había llegado el momento, Gul'dan reunió a los clanes guerreros en una única e imparable horda.", "Sin embargo, sabiendo que varios jefes como Grito Infernal y Orgrim Martillo Maldito competían por lograr la supremacía, Gul'dan creó una marioneta para dirigir a esta nueva horda. Puño Negro el Destructor, un Señor de la Guerra orco particularmente depravado y vicioso, fue el escogido para convertirse en la marioneta de Gul'dan. Bajo la égida de Puño Negro, la Horda salió para probar su valía contra los simples draenei.", "Transcurridos algunos meses, la Horda erradicó casi por completo todos los draenei que vivían en Draenor. Solo un pequeño puñado de supervivientes consiguió evitar la extraordinaria ira de los orcos. Exaltado por la victoria, Gul'dan se deleitaba con el poder y la fuerza de la Horda. Aun así, sabía que, sin enemigos que batir, la Horda se consumiría en luchas intestinas sin fin en su imparable apetito de matanza.", "Kil'jaeden sabía que, finalmente, la Horda estaba preparada. Los orcos se habían convertido en el arma más poderosa de la Legión Ardiente. El astuto demonio compartió su conocimiento con su maestro y Sargeras admitió que, finalmente, había llegado el tiempo de la venganza." } } },
    ["Roc Talon"] = { { ids = { "o175681" }, first = "thispetrifiedtalonwasfou", pages = { "Esta garra petrificada se encontró en las costas del sur de Tuercespina. Los ecologistas creen que la garra pertenece a un antiguo roca de sol. Si bien las criaturas juegan un papel preponderante en la primitiva mitología tauren, la existencia de esta garra sugiere que realmente existieron en algún momento de la historia." } } },
    ["Rock of Durotan"] = { { ids = { "o179909" }, first = "hereliesdurotanfirstchie", pages = { "Aquí yace Durotan, primer jefe del clan Lobo Gélido y padre de nuestro honrado Jefe de Guerra, Thrall. Fue el más valiente de los nuestros, traicionado por quienes querían ver esclavizado a nuestro pueblo. Durotan dio su vida para que pudiéramos alcanzar la libertad. Lo honramos a él y al legado que nos transmitió a través de su hijo.\n\nDrek'Thar, clarividente de los Lobo Gélido" } } },
    ["Rune-Inscribed Note"] = { { ids = { "i9552" }, first = "igreetyouyoungthewindsto", pages = { "Te saludo, joven $C. Los vientos me anunciaron tu llegada. La tierra ha elogiado tu fuerza. Ahora, los viejos espíritus susurran las tareas que tienes por delante. Nuestro pueblo siempre necesita líderes sabios y con grandeza de espíritu. A menudo, miran a los de nuestra clase en busca de ambas virtudes. Si lo deseas, te enseñaré más sobre nuestros métodos.\n\nBúscame en el Campamento Narache, en Mesa de la Nube Roja, donde hablaremos más a fondo sobre estas cosas.\n\nMeela Caminalba, $ginstructor:instructora; de chamanes" } } },
    ["Rune-Inscribed Parchment"] = { { ids = { "i9568" }, first = "loktarbrothersistertheel", pages = { "Lok-tar, $ghermano:hermana;. Los elementos te han traído hasta aquí y me han encargado que te muestre el camino del chamán. Los espíritus de nuestros ancestros nos vigilan desde el más allá y están henchidos de orgullo, sabiendo que te has unido a nuestras filas.\n\nCuando estés $gpreparado:preparada;, búscame cerca de El Cubil. Allí es donde instruyo a otros individuos de nuestra clase. Hasta entonces, que tengas vientos favorables.\n\nShikrik, $ginstructor:instructora; de chamanes" } } },
    ["Rune-Inscribed Tablet"] = { { ids = { "i9562" }, first = "greetingstoyoubrothasist", pages = { "Saludos, $ghermano:hermana;. Los espíritus me han dicho que estás $gpreparado:preparada; para ayudar a nuestros aliados. Tienes fuertes lazos con los elementos, así que eres mucho más poderoso que cuando empezaste a tomar lecciones conmigo.\n\nAhora te envío para que te encuentres con Shikrik, instructora de chamanes orcos en el Valle de los Retos. Ella ya sabe que irás a estudiar con ella. Haz que nuestros ancestros estén orgullosos. Hasta que nos volvamos a ver, que la llama te dé calor y el viento te sea favorable.\n\nIshi-yo" } } },
    ["Sara Balloo's Plea"] = { { ids = { "i4514" }, first = "tomyhonorablekingtisnott", pages = { "A mi honorable rey:\n\nNo corresponde a la esposa de un humilde soldado cuestionar las acciones de grandes dirigentes como vos. Las batallas que asolan nuestras tierras se libran para preservar la gran vida que conocemos y amamos, desde las aguas frescas de Loch Modan hasta las cumbres nevadas de Dun Morogh.", "Pero ¿a qué precio libramos estas guerras en nombre de la preservación? ¿Con la muerte de qué soldado caído comprendemos que la vida que intentamos salvar se nos escapa en el campo de batalla?\n\n¿Bajo cuántas espadas y hachas debemos arrojar nuestro futuro? ¿Bajo cuántos pies de tierra empapada debemos enterrar nuestro pasado?", "No corresponde a la esposa de un humilde soldado hacer tales preguntas.\n\nPero ahora os escribo como viuda de ese humilde soldado. Para vos, mi marido quizá fuera un soldado entre miles. Para mí era el gran Sully Balloo, padre de mis hijos y mi único compañero en esta vida.\n\nPerdonadme si mis preguntas os resultan impropias, gran señor. Pero los muertos no pueden hacerlas por sí mismos...\n\nVuestra leal súbdita,\nSara Balloo" } } },
    ["Sargeras and the Betrayal"] = { { ids = { "o175724" }, first = "overtimedemonicentitiesm", pages = { "Con el tiempo, seres demoníacos lograron entrar en los mundos de los titanes desde el Vacío Abisal y el Panteón eligió a Sargeras, su guerrero más destacado, para combatir en primera línea. Noble gigante de bronce fundido, Sargeras desempeñó su papel durante incontables milenios, buscando y destruyendo a los demonios allí por donde iba. Durante millones de años, Sargeras se enfrentó a dos poderosas razas demoníacas, las cuales se habían propuesto obtener el poder y el dominio sobre el universo físico.", "Los eredar, una raza insidiosa de malignos hechiceros, utilizó la brujería para invadir y dominar diversos mundos. Las razas autóctonas de estos planetas experimentaron mutaciones causadas por los malignos poderes de los eredar y se convirtieron en demonios.", "Si bien los poderes casi ilimitados de Sargeras fueron más que suficientes para derrotar a los malvados eredar, tuvo grandes problemas generados por la corrupción de las criaturas y al mal que todo lo consume. Incapaz de comprender tanta depravación, el gran titán cayó en una amarga depresión. A pesar de su creciente malestar, Sargeras liberó al universo de la presencia de los brujos, recluyéndolos en un rincón del Vacío Abisal.", "Mientras su confusión y tristeza crecían, Sargeras se vio obligado a luchar contra otro intento del grupo de perturbar el orden de los titanes: los Nathrezim. Esta raza oscura de demonios vampíricos (también conocidos como señores del terror), conquistó varios planetas densamente poblados, poseyendo a sus habitantes y convirtiéndolos en sombras.", "Los nefastos e intrigantes señores del terror enfrentaron a todas las naciones entre sí, manipulándolas hasta el odio irreflexivo y la desconfianza. Sargeras derrotó a los Nathrezim fácilmente, pero su corrupción lo afectó profundamente.", "Puesto que la duda y la desesperación ensombrecieron los sentidos de Sargeras, perdió toda la fe no solo en su misión, sino también en la visión que los titanes tenían de un universo ordenado. Finalmente, llegó a creer que el concepto de orden era una locura, y que el caos y la depravación eran los valores absolutos del oscuro y solitario universo.", "Sus compañeros titanes intentaron persuadirlo de su error y apaciguar su trastorno, pero él no creyó en las afirmaciones optimistas de los titanes, considerándolas engaños y artimañas interesadas. Abandonando a sus compañeros para siempre, Sargeras partió en busca de su propio lugar en el universo. Si bien el Panteón lamentaba su partida, los titanes no podían imaginar hasta dónde llegaría su hermano extraviado.", "Cuando la locura de Sargeras había consumido los últimos vestigios de su valiente espíritu, llegó a creer que los propios titanes eran los responsables del error de la creación. Finalmente, decidió cambiar las cosas en todo el universo, creando un ejército imparable capaz de destruir todo el universo físico.", "Incluso la forma titánica de Sargeras experimentó una deformación ocasionada por la corrupción que había poseído su otrora noble corazón. Sus ojos, sus cabellos y su barba desprendían fuego, y su piel color bronce se cuarteó, revelando un manantial de furia abrasadora.", "En su ira, Sargeras echó abajo las prisiones de los eredar y los Nathrezim, liberando a los repugnantes demonios. Estas malvadas criaturas se inclinaban ante la inconmensurable furia del titán oscuro y ofrecieron servirle de todas las formas posibles. Entre las filas de los poderosos eredar, Sargeras eligió a dos campeones para dirigir a su demoníaco ejército de destrucción.", "Kil'jaeden el Impostor fue elegido para reclutar a las razas más oscuras del universo y alistarlas en las filas de Sargeras. El segundo campeón, Archimonde el Rapiñador, fue elegido para dirigir los vastos ejércitos de Sargeras en la lucha contra todo el que se resistiera a la voluntad del titán.", "La primera medida de Kil'jaeden fue esclavizar a los vampíricos señores del terror bajo su terrible poder. Los señores del terror actuaban como agentes personales del titán por todo el universo, eligiendo para su maestro razas primitivas susceptibles de ser corrompidas y doblegadas. El primer señor del terror era Tichondrius el Ensombrecedor. Tichondrius era el soldado perfecto de Kil'jaeden y accedió a propagar el mal abrasador de Sargeras por todos los rincones oscuros del universo.", "Archimonde también otorgó poderes a sus propios agentes. Congregando a los malvados señores del infierno y a su bárbaro líder Mannoroth el Destructor, Archimonde preparó una élite de guerra capaz de exterminar todo rastro de vida de la creación.", "Cuando Sargeras vio que tenía un ejército poderoso y listo para seguir todas sus órdenes, lo hizo rastrear todos los rincones de la Gran Oscuridad. Llamó a su ejército la Legión Ardiente. Hasta el momento, no se sabe cuántos planetas han sido exterminados por este ejército en su nefasta Cruzada Ardiente por todo el universo." } } },
    ["Saurial Egg"] = { { ids = { "o175684" }, first = "foundintheremoterainfore", pages = { "Encontrado en la remota selva del Cráter de Un'Goro, este huevo albergó un embrión de demosaurio. El material genético del saurio ha resultado inestimable para los ecólogos de la Liga, que están más cerca que nunca de elaborar un suero contra el veneno debilitante de los demosaurios." } } },
    ["Scarlet Crusade Attack Plans"] = { { ids = { "i264693" }, first = "wewillattackthecityofbri", pages = { "Atacaremos Rémol justo antes del amanecer. La fuerza auxiliar prenderá fuego a la torre de zepelines como distracción. Cuando el fuego esté encendido y los defensores se hayan alejado, la fuerza principal dirigida por el teniente entrará desde el norte. El magistrado y los civiles son los objetivos principales. Destruid todo lo que veáis e incinerad los cuerpos.\n\nDicen que los Renegados no sienten miedo. Volveremos a infundirles el temor a la Luz, hermanos y hermanas. ¡Por Lordaeron!" } } },
    ["Scarlet Crusade Documents"] = { { ids = { "i2885" }, first = "disperseinformationasyou", pages = { "Difundid esta información todo que consideréis necesario.\n\nComando Regional de Tirisfal\nCapitán Melrose\nCapitán Vachon\nCapitán Perrine\n\nÓrdenes del Gran Señor.\n\nCapitán Perrine, es preciso reforzar vuestras posiciones en la torre del sudoeste (tal como se especificó anteriormente). En envíos posteriores mandaremos suministros adicionales. Mientras tanto, deberán obtenerse en las granjas vecinas. Asimismo, es preciso realizar nuevos trabajos de reconocimiento, al tiempo que", "deberá reunirse información sobre la organización de los no-muertos en Brill.\n\nCapitán Vachon, al parecer, los no-muertos han intensificado sus maniobras cerca de la torre del norte. Hay que contener esta rebelión de forma rápida y contundente.\n\nCapitán Melrose, nos preocupa el nivel de organización de los no-muertos cerca de las fronteras de las Tierras de la Peste. En las próximas semanas le enviaremos un nuevo contingente de hombres.\n\nGloria a todos en la Luz" } } },
    ["Scribbled Letter"] = { { ids = { "i251941" }, first = "oiyougetoffyerduffandcom", pages = { "Eh, tú, $C. Levanta el trasero y ven a verme detrás de la abadía. Un cazador blandengue y novato como tú no puede esperar sobrevivir, y mucho menos prosperar, en estas tierras sin orientación. ¡Y el viejo Tordrin está aquí para dártela, si tienes agallas!\n\nTordrin Hojadusta, instructor de cazadores (extremadamente guapo)" } } },
    ["Scribbled Note"] = { { ids = { "i282421" }, first = "greetingsyouveshowngreat", pages = { "Saludos, $N.\n\nHas demostrado ser <un cazador prometedor/una cazadora prometedora>, y me gustaría asegurarme de que recibes el entrenamiento adecuado.\n\nLos forestales hacen un buen trabajo manteniendo a la naturaleza a raya en la Arboleda Thendal, pero no podemos decir lo mismo más allá de nuestras fronteras.\n\nBúscame por el centro de la ciudad tan pronto como te sea posible. La naturaleza te llama.\n\n-Tai'ree Vista Lejana, instructora de cazadores" } } },
    ["Sealed Research Report"] = { { ids = { "i23008" }, first = "helloasitturnsoutiveunea", pages = { "Hola, $N. Al parecer, he extraído cierta información procedente de esta nota.\n\nSobre James, me temo que apenas he encontrado nada. Sin embargo, he descubierto ciertos datos familiares sobre Amelia.\n\nSi bien ni ella ni sus hijos sobrevivieron a la guerra, su hermano, un hombre llamado Alexander Calder, sí sobrevivió. Puedes encontrarlo en la Caverna Abandonada en Forjaz, estudiando la peligrosa magia de la Legión Ardiente.\n\nElla tenía una prima a la que estaba muy unida, una mujer conocida ahora como Deze Delirioníveo, que apoyó la batalla por la Cuenca de Arathi, en el territorio de Orgrimmar.\n\nCuando estés cerca de cualquiera de ellos, deberías ir a visitarlos. Estoy $gseguro:segura; de que estarán muy interesados en recibir noticias de la pobre Amelia." } }, { ids = { "i23010" }, first = "greetingsithoughtyoumigh", pages = { "Saludos, $N. He pensado que los resultados de mi investigación podrían ser de tu interés.\n\nAl parecer, tanto a Reuben como a Leagrem los sobrevivieron, por así decirlo, sus familiares. Incluso si ya saben lo que ocurrió con el soldado perdido, visitar a cualquiera de ellos puede valer la pena.\n\nPuedes encontrar a la ex mujer de Reuben, Joanna Salablanca, en el Barrio de la Guerra de Entrañas, en donde pasa la mayor parte del tiempo. No estoy seguro de cómo recibirá la noticia sobre su ex marido.\n\nEn lo que respecta a Leagrem, su tía es la supervisora del orfanato de Ventormenta, un trabajo ciertamente admirable.\n\nHagas lo que hagas en la vida, te deseo la mejor de las suertes en tus empeños." } }, { ids = { "i23011" }, first = "ihopethisletterfindsyouw", pages = { "$N, espero que cuando recibas esta carta te encuentres bien. Tras investigar un poco, he descubierto ciertos datos sobre aquellos que escribieron la nota que recuperaste.\n\nEl padre de Samla conduce a los Renegados y a los Trols durante el peregrinaje a Cima del Trueno, siguiendo los caminos de su fe. Su nombre es Miles Galés y puedes encontrarlo junto con sus fieles no-muertos en las Pozas de las Visiones.\n\nMientras tanto, a Torgal lo sobrevivió su prima Elissa Dumas. Según he sabido, es una ermitaña y pasa sus días en el Templo de la Luna en Darnassus.\n\nTe ruego que visites a cualquiera de estas personas, $N. Quizás nadie les haya traído noticias sobre la suerte de Torgal o de Samla." } }, { ids = { "i23012" }, first = "thekeeperpassedonthelett", pages = { "\"El Guardián me entregó la carta que descubriste, $N, y creo que apreciarás en lo que vale tener noticias frescas.\n\nEl último \"Vargus\" superviviente que se menciona en la carta ha sido encontrado en el desierto de Silithus, en el Fuerte Cenarion. Se le conoce como Garon Hutchins.\n\nLa próxima vez que vayas a los páramos, deberías hablar con él. Está muy interesado en conocer los datos que obran en nuestro poder." } }, { ids = { "i23013" }, first = "salutationsiveatlastfoun", pages = { "Saludos. Por fin he encontrado un poco de tiempo para examinar la carta que encontraste sobre la Plaga. Aunque me tomó cierto trabajo, creo haber descubierto a un pariente vivo de los fallecidos.\n\nLa hermana de Maxwell, una tal Zarena Cromvento, dirige una pequeña armería en la Bahía del Botín. Desconozco cuál era el grado de relación con su hermano, pero si pasas por ahí, deberías concertar una cita con ella. Poder disponer de datos fehacientes sobre estas cuestiones es algo muy valioso y poco habitual en estos tiempos." } }, { ids = { "i23016" }, first = "ivefinallyunearthedsomei", pages = { "Finalmente he descubierto ciertos datos sobre el antiguo soldado que combatiste. El rastro ha sido difícil de seguir, ya que su árbol genealógico no está debidamente documentado, pero he logrado encontrar a un pariente consanguíneo.\n\n¿Puedes creer que el Supervisor Alen, de la Capilla de la Esperanza de la Luz, es en realidad el hijo de Christoph? Oír noticias sobre su padre seguro que le agradará mucho. Si alguna vez vuelves a estar de servicio en el Alba Argenta en las Tierras de la Peste, por favor, habla con él. Sería todo un detalle." } } },
    ["Secret Note #1"] = { { ids = { "i12765" }, first = "agashamourplansmustbekep", pages = { "Agasham,\n\n¡Nuestros planes deben continuar en secreto a cualquier precio! Sería desastroso si alguna otra tribu tauren descubriese nuestra afiliación.\n\nFirmado,\n\nHeraldo Elm" } } },
    ["Secret Note #2"] = { { ids = { "i12766" }, first = "agashamworkingtogetherou", pages = { "Agasham,\n\n¡Trabajando juntos, nuestras fuerzas serán mas poderosas que las de todas las tribus tauren juntas! Aun así, necesitamos vuestra total obediencia. Recuerda, ¡tu gente solo será recompensada después de que nuestros planes hayan alcanzado el éxito!\n\nFirmado,\n\nHeraldo Rex" } } },
    ["Secret Note #3"] = { { ids = { "i12768" }, first = "agashamouragentsfromlord", pages = { "Agasham,\n\nNuestros agentes pronto se encontrarán con nuestros delegados. Cuando encontremos un lugar apropiado para nuestra cita, te informaremos al respecto.\n\nFirmado,\n\nHeraldo Grakus" } } },
    ["Senir's Report"] = { { ids = { "i2628" }, first = "areportonthestateofthefr", pages = { "Informe sobre el estado de los trols Peloescarcha en el área general de Dun Morogh\n\nLos trols situados en Dun Morogh están fundamentalmente ubicados en el poblado Peloescarcha, una cueva de montaña en la frontera oeste. Son lo suficientemente numerosos como para causar cierta preocupación, no obstante, parecen estar más que contentos dentro de su cueva. Sin duda, esto se debe a que no desean volver a desatar la ira de los enanos, arriesgándose al exterminio total de su raza. Sus acciones pueden considerarse de carácter territorial, por así decirlo, y creo", "que no suponen una verdadera amenaza para nosotros, siempre que no invadamos su territorio. Esta situación puede resultar poco agradable para el pueblo de los enanos, pero dada la dispersión de los recursos militares, puede ser prudente relegar el exterminio de los trols a un segundo plano, para poder centrarnos en la amenaza de los troggs y los Hierro Negro.\n\nAdjunto copia del informe de mi hermano Grelin sobre Yunquemar.", "Informe sobre el estado de los wendigos en las cuevas cercanas a Kharanos\n\nEscrito por la montaraz Gretchen según los hallazgos del montaraz Cornelius\n\nLos wendigos rara vez abandonan sus cuevas, pero hay informes de ataques contra civiles alrededor de asentamientos cercanos como Kharanos y Las Birras. Parecen cada vez más agitados en su búsqueda de alimento. Ya hemos perdido a uno de los nuestros en los esfuerzos por contenerlos. Aunque eliminar por completo a estas bestias resulta impracticable, los montaraces solicitan", "recursos adicionales para limitar su expansión. No podemos seguir enviando aventureros contra el problema y esperar lo mejor. Tarde o temprano se acabará la comida y los wendigos se verán obligados a atacar directamente nuestras ciudades. Quizá incluso la propia Forjaz.\n\nTransmitid mis condolencias a la familia del montaraz Cornelius, que luchó con valor para proteger a los habitantes de Dun Morogh.", "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada\n\nElaborado por Grelin Barbablanca, enviado especial del senado\n\nDesde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenaza que puede eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en", "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto.\n\nEsta acción ha sido autorizada por la sanción otorgada por el rey Barbabronce." } } },
    ["Sevren's Orders"] = { { ids = { "i3017" }, first = "lordbethoriceshardaspery", pages = { "Lord Bethor Duroyelo,\n\nSiguiendo vuestras instrucciones, os mando al agente que habéis solicitado. Es el portador de esta nota.\n\nEsta persona ha demostrado ser de fiar, es capaz de seguir órdenes y puede enfrentarse a las fuerzas de la Plaga, por lo que lo he elegido para vuestra misión.\n\nPor la gloria de la Reina,\nMagistrado Sevren" } } },
    ["Shadowsworn Note"] = { { ids = { "i227658" }, first = "weneedmorewillingsacrifi", pages = { "¡Necesitamos más sacrificios voluntarios!\n\nEse altar debe de tener algún truco. Hasta ahora no ha dado nada.\n\nInforma en Serpiente Enroscada cuando encuentres algo útil." } } },
    ["Shaw's Report"] = { { ids = { "i1353" }, first = "lordstoutmantleledbyedwi", pages = { "Señor Mantorrecio:\n\nLa Hermandad de los Albañiles, encabezada por Edwin VanCleef, estaba compuesta por los albañiles más hábiles entre los hombres. Los Albañiles ayudaron a reconstruir los restos de la ciudad de Ventormenta, levantada por los orcos durante la Primera Guerra. VanCleef y sus mercaderes fueron inigualables albañiles: su obra y su arte se ponen de manifiesto en la grandeza de la Catedral de la Luz y en el propio Castillo de Ventormenta.", "No obstante, los nobles de Ventormenta acumularon una gran deuda al aumentar la presencia militar del reino en Elwynn y en Tuercespina. Esta enorme deuda paralizó la economía del reino y despojó a VanCleef y a sus Albañiles de sus prometidas recompensas. Tras varios años de intenso trabajo para reconstruir el antiguo esplendor de la ciudad, los Albañiles se arruinaron y fueron olvidados por los funcionarios corruptos que la gobernaban.", "Habiendo conocido a Edwin VanCleef durante toda mi vida, puedo deciros que resulta sobrecogedor tenerlo de enemigo. Verás, él fue mi amigo de infancia y yo personalmente lo instruí en el pensamiento oscuro cuando decidió iniciar una carrera paralela a la mía. Si VanCleef dirige la Hermandad Defias, que la Luz se apiade de nuestras almas.\n\nMaestro Mathias Shaw\nHermandad de Asesinos de Ventormenta" } } },
    ["Signed Recruitment Letter"] = { { ids = { "i4995" }, first = "hordeconscriptionregistr", pages = { "Registro de Reclutamiento de la Horda\n\nEsta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería ser asignado para trabajar inmediatamente en El Cruce.\n\nRespetuosamente:\n- Kargal Marca de Guerra\n\nMe parece bien.\n Takrin Abrecaminos" } } },
    ["Simple Letter"] = { { ids = { "i9542" }, first = "tellmehaveyouheardanorcs", pages = { "Dime, $C, ¿has oído el grito de un orco? ¿No defendías tal vez tu casa de los gnolls mientras ellos intentaban cortarte el cuello? Sí, suena horrible, ¿verdad?\n\nBueno, si deseas proteger a los tuyos, necesitarás mi ayuda. Me encontrarás en la abadía de Rasganorte. Mis conocimientos no son fáciles de obtener, pero si tienes suficiente experiencia, puedo instruirte, enseñándote una serie de estilos y movimientos que te ayudarán a hacer frente a las amenazas de Ventormenta y más allá.\n\nLlane Beshere, instructor de guerreros" } } },
    ["Simple Memorandum"] = { { ids = { "i9544" }, first = "attentionyoumustreportto", pages = { "ATENCIÓN:\nDebes informar a Thran Khorman inmediatamente. Está en el edificio A3, también conocido como Yunquemar por los habitantes locales. Una vez que hayas logrado contactar con Khorman, deberás prepararte para la guerra que está por venir, ¡la guerra que nos permitirá recuperar nuestro hogar en Gnomeregan!\n\nTodos los esfuerzos y las tareas esenciales deberán centrarse en conseguir este propósito. Una vez cumplido, se te asignará una nueva misión." } } },
    ["Simple Note"] = { { ids = { "i9547" }, first = "manytribesclaimthatitisa", pages = { "Muchas tribus afirman que es un don ser bendecido con la capacidad de utilizar la magia o de hablar con nuestros ancestros, pero deberás saber, $C, que tú también tienes este don. Algunos no tienen suficiente fuerza en sus brazos como para blandir armas poderosas. Algunos no tienen la destreza suficiente para esquivar el golpe de un asesino o incluso para sufrir los castigos físicos de un encantador arcano, pero tú sí. Tú eres fuerte. Te ayudaré a ser más fuerte. Encuéntrame en el Campamento Narache.\n\nHarutt Tronacuerno, instructor de guerreros" } }, { ids = { "i282422" }, first = "illmakethisshortyouvegot", pages = { "Seré breve, $N.\n\nTienes una astucia y una gracia que respeto, y te he estado observando.\n\nPero la astucia y la gracia no siempre bastan para seguir con vida. Si quieres aprender a ser un pícaro de verdad, puedo enseñarte.\n\nVen a buscarme dentro de la atalaya.\n\n-Akeri Hoja Umbría, instructora de pícaros" } } },
    ["Simple Parchment"] = { { ids = { "i12635" }, first = "thromkawarrioriwontfawno", pages = { "Throm-Ka, guerrero. No te adularé por tus hazañas, tu fortaleza o tu valor. Ya son historia. ¿Has matado a algún humano últimamente? Apuesto a que no han sido muchos. Te estás haciendo viejo. Necesito otro par de manos y me da igual si me das coba: necesitas la instrucción que solo yo puedo darte. Cuando eso te entre en la mollera, te estaré esperando bajo el dosel que está en el exterior del Cubil.\n\nFrang, entrenador de guerreros" } } },
    ["Simple Rune"] = { { ids = { "i9543" }, first = "bymagnisbeardtheresmucht", pages = { "Por las barbas de Magni, hay mucho que discutir y muy poco tiempo, $N. Búscame en Yunquemar, frente al Valle de Crestanevada tan pronto como puedas. Tenemos que empezar.\n\nTengo que decirte muchas cosas sobre cómo ganar velocidad, pero nada de eso tiene que ver con nosotros... por ahora. Lo que ahora debe centrar nuestra atención es la empuñadura de un hacha, el peso de nuestra armadura y el olor de nuestro propio sudor rodando por la frente cuando nos enfrentamos al enemigo. Empezaremos por ahí.\n\nThran Khorman, instructor de guerreros" } } },
    ["Simple Scroll"] = { { ids = { "i9546" }, first = "manyofourkindresorttothe", pages = { "Muchos de nosotros recurren a lo arcano y lo divino como medios para obtener poder, pero nosotros lo hacemos mejor, ¿no es verdad, $C? Sabemos que nuestras armas son nuestros símbolos sagrados, nuestro escudo es nuestro libro de hechizos y nuestra malla es nuestra sabiduría.\n\nIncluso en la no-muerte somos fuertes, y solo podemos hacernos más fuertes.\n\nEncuéntrame en la posada de Camposanto. Seguiré hablándote de estas cuestiones y de otras muchas.\n\nDannal Stern, instructor de guerreros" } } },
    ["Simple Sigil"] = { { ids = { "i9545" }, first = "ihopemysigilfindsyouwell", pages = { "Espero que cuando recibas este sigilo te encuentres bien, $C. Te escribo porque nuestra gente necesita esa fuerza con la espada, la guja y otras armas. Han ocurrido muchas cosas desde que nuestro pueblo volvió a enfrentarse a las otras razas de Azeroth, de manera que tenemos una necesidad aún mayor de protectores de todas las clases.\n\nAquí es donde apareces tú. Ya te contaré, pero creo que debo hacerlo en persona. Puedes encontrarme en Aldrassil... en los niveles inferiores.\n\nAlyissia, instructora de guerreros" } } },
    ["Simple Tablet"] = { { ids = { "i6488" }, first = "ayemontakedislettertofra", pages = { "Eh, colega. Lleva esta carta a Frang, en el Valle de los Retos. Suele estar fuera del Cubil, entrenando a jóvenes guerreros que desean luchar por la Horda.\n\nNecesita guerreros astutos como tú para enseñar a los orcos a pelear usando algo más que sus músculos. Eres más rápido y listo que la mayoría, pero no te jactes de eso: a los orcos no les gusta que los insulten. Son buenos aliados y quizás te enseñen un par de cosas.\n\nTar'sere" } } },
    ["Snapshot of Gammerita"] = { { ids = { "i9330" }, first = "", pages = { "" } } },
    ["Snufflenose Owner's Manual"] = { { ids = { "i5897" }, first = "congratulationsyouarethe", pages = { "¡ENHORABUENA!\n\n¡Eres la primera persona en poseer el asombroso husmeador taltuza! Aunque se trata de una criatura asustadiza, estamos seguros de que su mullido pelaje y su increíble poder olfativo te atraparán.\n\nEn las siguientes páginas, encontrarás información sobre tu husmeador taltuza:\n\n1. Alimentación y cuidados\n2. Comportamiento excéntrico (y adorable)\n3. Uso de la vara de mando del Husmeador(marca registrada)\n\nNuevamente, enhorabuena. No te defraudará,\n\n-Marwig Pernoxidado\nPropietario de Snuff Inc.", "ALIMENTACIÓN Y CUIDADOS:\n\nNos comprometemos a proporcionarte todo lo que necesitas para cuidar a tu mascota. Nuestros clientes esperan este nivel de servicio de Snuff Inc, ¡y estamos de acuerdo en ofrecerlo!\n\nPara ello, hemos diseñado unos robustos cajones para husmeador taltuza con pequeños orificios, perfectos para mantener a tu mascota en un lugar seguro, alejado de la luz.\n\nPara tu comodidad, dentro de cada cajón hay un recipiente con gránulos de comida, ¡impregnados con el atrayente aroma de los tubérculos hojazul (el alimento favorito de husmeadores taltuza)!", "SACAR A PASEAR AL HUSMEADOR TALTUZA\n\nAl husmeador taltuza le gustan los lugares oscuros y pequeños. Y es muy asustadizo.\n\nSi deseas sacar a pasear al tu husmeador taltuza, deberás llevarlo a lugares en los que se sienta a gusto. ¡Y DEBES llevarlo allí donde pueda oler su comida favorita: tubérculos hojazul!\n\nEl lugar que más adecuado es la zona de las \"zanjas\" del Horado Rajacieno. Si abres la caja del husmeador taltuza cerca de la zanja y el animalillo huele los tubérculos hojazul que hay cerca de ahí, se atreverá a salir y te seguirá.", "LA VARA DE MANDO DEL HUSMEADOR (mr)\n\nEl husmeador taltuza es un animal sorprendente. No solo inspira amor y afecto en el zancudo de llanura más irritable, ¡sino que puede oler un tubérculo hojazul enterrado a unos 45 metros!\n\nSi deseas que tu husmeador taltuza vaya a buscar un tubérculo hojazul, puedes usar tu vara de mando patentada (se adquiere por separado).\n\nEn la página siguiente encontrarás la dirección...", "\"Todos nuestros husmeadores están altamente adiestrados. Un simple movimiento de la vara de mando hará que cualquier husmeador taltuza que esté cerca entre en el \"modo de búsqueda.\" A continuación, olfateará el suelo en busca de tubérculos hojazul y, si encuentra uno, irá a buscarlo y lo desenterrará.\n\nSi vuelves a mover el mando mientras el husmeador busca su tubérculo, abandonará la búsqueda y regresará contento a tu lado.\n\n¡Confiamos en que nuestros husmeadores taltuza te parezcan animales bien adiestrados, útiles y esponjosos, que querrás apretujar a todas horas\".", "Lamentamos tener que informar que en Snuff Inc. sabemos de la existencia de ciertos glotones cazadores de tubérculos a los que poco importa la seguridad de sus adorables mascotas, enviándolas a lugares oscuros y peligrosos en busca de tubérculos.\n\nNo aprobamos esta conducta irresponsable, así que con el propósito de satisfacer a nuestros clientes, hemos incluido una garantía con cada husmeador taltuza vendido, ofreciendo a los nuevos dueños la posibilidad de volver al punto de venta y recuperar a su husmeador taltuza perdido.\n\n¡Feliz caza!" } } },
    ["Solomon's Plea to Darkshire"] = { { ids = { "i1409" }, first = "lordebonlockethetownship", pages = { "Señor Ebonlocke: --\n\nEl municipio de Villa del Lago solicita humildemente la ayuda de la Guardia Nocturna. Estamos bajo el asedio de los orcos Roca Negra y los gnolls Pellejo Negro de Morganth. No haría esta petición si nuestra situación no fuera límite. Esperamos ayuda de Ventormenta, pero hasta que la recibamos, os ruego vuestro apoyo. Si el Reino se resquebraja, toda la humanidad estará en peligro.\n\nMagistrado Salomón" } } },
    ["Solomon's Plea to Farholde"] = { { ids = { "i266895" }, first = "lordebonlockethetownship", pages = { "Señor Ebonlocke: --\n\nEl municipio de Villa del Lago solicita humildemente la ayuda de la Guardia Nocturna. Estamos bajo el asedio de los orcos Roca Negra y los gnolls Pellejo Negro de Morganth. No haría esta petición si nuestra situación no fuera límite. Esperamos ayuda de Ventormenta, pero hasta que la recibamos, os ruego vuestro apoyo. Si el Reino se resquebraja, toda la humanidad estará en peligro.\n\nMagistrado Salomón" } } },
    ["Solomon's Plea to Westfall"] = { { ids = { "i1407" }, first = "lordstoutmantlethetownsh", pages = { "Señor Mantorrecio: --\n\nEl municipio de Villa del Lago solicita humildemente la ayuda de vuestra milicia. Mientras escribo estas líneas, estamos bajo el asedio de los orcos Roca Negra y los gnolls Pellejo Negro de Morganth. No haría esta petición si nuestra situación no fuera límite. Esperamos ayuda de Ventormenta, pero mientras no la recibamos, os ruego vuestro apoyo. Si el Reino se derrumba, toda la humanidad estará en peligro.\n\nMagistrado Salomón" } } },
    ["Sorrow of the Earthmother"] = { { ids = { "o177204" }, first = "asthechildrenoftheearthr", pages = { "Mientras los hijos de la tierra recorrían los campos del alba, oyeron susurros oscuros de las profundidades del mundo. Los susurros les hablaron de las artes de la guerra y el engaño. Muchos shu'halo cayeron bajo la influencia de la sombra y abrazaron la malicia y la perversidad. Se volvieron contra sus hermanos puros y dejaron que su inocencia se perdiera por las llanuras.", "La Madre Tierra, con el corazón apesadumbrado por la desgracia de sus hijos, no pudo soportar verlos caer. En su dolor se arrancó los ojos y los hizo girar por los cielos estrellados sin fin. An'she y Mu'sha, buscando aliviar el dolor del otro, solo podían perseguir su tenue resplandor por el cielo. Los gemelos aún se persiguen con cada giro del mundo.", "Aunque ciega, la Madre Tierra no podía apartarse mucho tiempo del mundo de su corazón. Mantuvo el oído en los vientos y escuchó todo lo que ocurría en los campos del alba. Su gran corazón siempre estuvo con sus hijos y su sabiduría amorosa nunca los abandonó." } } },
    ["Spy's Report"] = { { ids = { "i5917" }, first = "daytroopmovementnearther", pages = { "--Decimotercer día\nHa aumentado la actividad entre las tropas cerca de Theramore. Un gran número de humanos abandonaron la ciudad y se trasladaron rápidamente al oeste.\n\n--Decimocuarto día\nMás tropas abandonan la ciudad. Seguí a un pequeño grupo y vi cómo se quitaban los uniformes y salían disparados de Theramore. ¿Serán desertores?\n\n--Decimoquinto día\nNo pude evitar escuchar a las tropas de Theramore cuando hablaban sobre guardias que abandonaban sus puestos. Mis sospechas sobre los desertores deben ser ciertas", "--Decimosexto día\nUleg y Thargil regresaron de su misión al puerto de Theramore. Vieron un nuevo barco en el puerto: el Gorrión Sangrante. El barco partió del puerto de Menethil en Azeroth.\n\nMañana, Uleg y Thargil regresarán al puerto y entrarán sigilosamente en el barco. Esperan encontrar documentos de carácter político, que demuestren la relación entre Theramore y la Alianza.", "--Decimoséptimo día\nUleg regresó de su misión. Fracasó y Thargil fue capturado. Envié a Uleg para que entregara este informe a Nazeer.\n\nPermaneceré aquí. He observado una actividad creciente de barcos frente a la costa de Theramore. Continuaré observando e informaré personalmente sobre cualquier acontecimiento importante." } } },
    ["Stormpike's Request"] = { { ids = { "i5998" }, first = "masterlongbeardasyouknow", pages = { "Maestro Barbalarga\n\nComo podrás saber, los Pico Tormenta sabemos apreciar lo bueno y la calidad de tus escudos es famosa entre nosotros.\n\nPor ello, es un placer para mí encomendarte la fabricación de un escudo. He incluido las especificaciones en la siguiente página:", "-Totalmente redondo, cubre toda el área, desde el puño hasta el codo.\n\n- Clavos en los bordes. Pieza de plata.\n\n- Un clavo grande de plata en el centro, con un ancho de tres dedos.\n\n- De roble, reforzado con hierro.\n\n- Mi nombre, Gringer Pico Tormenta, grabado en el borde superior.", "El pago se realizará por los medios habituales. Abona al portador de esta petición una remuneración estándar por la entrega. Puedes cargarlo en el precio del escudo.\n\nUn cordial saludo y muchas gracias,\n--Gringer Pico Tormenta" } } },
    ["Stormwind Armor Marker"] = { { ids = { "i748" }, first = "thisarmormarkerisgoodfor", pages = { "Este marcador de armaduras es útil para marcar una armadura de cuero o tela, canjeable en el la casa de los Timberlain, en el Aserradero de la Vega del Este." } } },
    ["Stoutmantle's Response to Solomon"] = { { ids = { "i1408" }, first = "yourhonorallofwestfallmo", pages = { "Su Señoría:\n\nEn los Páramos de Poniente lloramos vuestra pérdida, pero también libramos nuestra propia guerra. Los granjeros han sido atacados por ladrones y golems mecánicos. Ventormenta retiró sus tropas, dejando a la gente desprotegida. He reunido a las Milicias del Pueblo tras el abandono de Ventormenta para preservar lo que ha quedado de esta tierra. Conducir a las milicias hasta Crestagrana supone una catástrofe para los Páramos de Poniente.\n\nRecibid mis condolencias,\nGryan Mantorrecio" } } },
    ["Strange Note"] = { { ids = { "i228144" }, first = "thecrystalhasshownmevisi", pages = { "El cristal me ha mostrado visiones de su pasado. Fue arrancado de un todo perfecto, algo de glorioso poder divino.\n\nLos conflictos feroces entre las razas de Azeroth no dejan de crecer. Si se reúnen ahora los fragmentos, podrían usarse como un arma de destrucción aterradora.\n\nSi intentas reunirlos, te lo ruego: usa su poder para unir a los hijos de Azeroth, no para librar más guerras." } } },
    ["Studies in Spirit Speaking"] = { { ids = { "i15790" }, first = "oooooooooooooooooooooooo", pages = { "OoOoOoO OOoOOoo OOOoOoo OOoOooO OOoOOoO OOooooO Oooooo OooOOOO OOoOOOo OOoOOoo OOoOooO OOoOOOo OOooOoO Oooooo OooOOOo OOooooO OOOoooo OOooooO Oooooo OoOoOOo OOooooO OOoOOoo OOoOOoo OOooOoO OOOOooO Oooooo OooOoOO OOoOOOo OOoOooO OOooOOO OOoOooo OOOoOoo OOOooOO Oooooo OOoOOOO OOooOOo Oooooo OooooOO OOoOooo OOooooO OOoOOOO OOOooOO" } } },
    ["Sully Balloo's Letter"] = { { ids = { "i4432" }, first = "dunmodrofthewetlandsmyde", pages = { "Dun Modr de los Humedales\n\nMi querida Sara,\n\nHay grandes probabilidades de que partamos en unos días al puente Thandol para vigilarlo. Te escribo estas líneas, por si no puedo volver a hacerlo más. Siento el impulso de escribirte esta nota, que puede llegar a tus manos cuando yo ya no exista.", "Nuestra tarea puede ser breve y placentera o difícil y mortal para mí. Si es necesario que caiga en la batalla por la Alianza, estoy preparado para ello.\n\nNo me falta un ápice de confianza en la causa que defiendo y tampoco ha decaído mi ánimo ni me falta valor.", "Sé la importancia que tiene el triunfo de la Alianza para el Reino de Forjaz, al tiempo que reconozco nuestra enorme deuda hacia nuestros predecesores por su sufrimiento y la sangre derramada en las Grandes Guerras. Por eso estoy dispuesto, totalmente dispuesto, a dejar de lado mis placeres en esta vida para conservar nuestra Alianza y saldar nuestra deuda.", "Sara, mi amor por ti es eterno, me ata a ti mediante lazos poderosos que nada, salvo el Omnipotente, podría romper. Pero mi amor por el Reino sopla sobre mí como un fuerte viento y me arrastra de un modo irresistible, con todas estas cadenas, hacia el campo de batalla.", "Me embargan los recuerdos de todos los momentos sublimes que hemos pasado y siento profunda gratitud hacia la Luz y hacia ti por haberlos disfrutado durante tanto tiempo. Por eso, ahora me resulta difícil renunciar a ellos y reducir a cenizas todas las esperanzas de compartir, enamorados, un futuro que aún era posible, viendo crecer a nuestros hijos hasta la plenitud de su juventud enana.", "Sé que poco puedo pedir a la Divina Providencia, pero algo me dice, quizás la dulce plegaria de mi pequeño Edgar, que debo regresar sano y salvo con mis seres queridos. Pero si no regreso, mi querida Sara, no olvides nunca cuánto te amo y, cuando exhale mi último suspiro en el campo de batalla, susurraré tu nombre.\n\nPerdóname por todos los errores que he cometido y por todo el dolor que te haya podido causar... ¡Cuán desconsiderado e insensato fui en ocasiones!", "Con mucho gusto borraría con mis lágrimas todas las manchas que ensombrecieron tu felicidad y lucharía contra todas las desgracias de este mundo para protegeros a ti y a mis queridos hijos de cualquier peligro.\n\nPero no puedo.\n\nTendré que vigilarte desde el Vacío Abisal y rondarte mientras sorteas las tormentas con tu preciosa carga, esperando con resignada paciencia el momento en que nos encontremos para no separarnos nunca más.", "Pero oh, Sara, si los muertos pudieran volver a Azeroth y rodearan, sin ser vistos, a aquellos que aman, siempre estaría a tu lado en el día más feliz y en la noche más oscura, entremezclándome entre tus horas más felices y las más oscuras, y si sintieras una suave brisa en tus mejillas, sería mi aliento, y si sintieras una fresca sensación en tus vibrantes sienes, sería mi espíritu atravesando el lugar.\n\nSara, no llores mi muerte, piensa que me he ido y espero por ti, hasta que volvamos a estar juntos otra vez.\n\nSully" } } },
    ["Sunwell - The Fall of Quel'Thalas"] = { { ids = { "o175757" }, first = "thoughhehaddefeatedallof", pages = { "Si bien derrotó a todos aquellos a quienes ahora veía como enemigos, el fantasma de Kel'Thuzad siguió rondándolo. El fantasma le comunicó que necesitaba revivir para llevar a cabo la siguiente fase del plan del rey Exánime. Para este propósito, Arthas debía llevar los restos de Kel'Thuzad a la mística Fuente del Sol, oculta en el eterno reino de Quel'Thalas de los elfos nobles.", "Arthas y su Plaga invadieron Quel'Thalas y pusieron sitio a las desmoronadas defensas de los elfos. Sylvanas Brisaveloz, General Especialista de Lunargenta, mostró fiera resistencia, pero finalmente, Arthas acabó con el ejército de los elfos nobles hasta llegar a la Fuente del Sol. En un cruel gesto de dominio, utilizó el cuerpo exánime de Sylvanas como estandarte, que quedaría condenada a ser un alma en pena no-muerta, al servicio del conquistador de Quel'Thalas.", "Finalmente, Arthas sumergió los restos de Kel'Thuzad en las aguas sagradas de la Fuente del Sol. Si bien las poderosas aguas de la Eternidad quedaron contaminadas por este acto, Kel'Thuzad renació como un hechicero exánime. Tras renacer como un ser mucho más poderoso, Kel'Thuzad explicó la siguiente fase del plan del rey Exánime.", "Cuando Arthas y su ejército de muerte se dirigieron hacia el sur, no quedaba ni un solo elfo vivo en Quel'Thalas. La gloriosa patria de los elfos nobles, que había permanecido en pie durante más de nueve mil años, había dejado de existir." } } },
    ["Survivor Journal"] = { { ids = { "i227748" }, first = "undertheprotectionofthes", pages = { "Bajo la protección del fragmento de Luz, huimos a la cripta y nos atrincheramos dentro. Pero Wescott y Billina salieron a buscar provisiones y se lo llevaron para protegerse. Han pasado tres días y no han vuelto. Sin el poder del fragmento, la Plaga no tardará en caer sobre nosotros..." } } },
    ["Syndicate Missive"] = { { ids = { "i3601" }, first = "valikguardtheslaveuntilo", pages = { "Valik,\nVigila $gal esclavo:a la esclava; hasta que regresemos. No es seguro $gmantenerlo:mantenerla; aquí por más tiempo. Lo llevaremos al norte, lo más lejos posible para evitar que lo vean.\n\nSon animales, sin embargo son despiadados. Si son bastantes, tendremos suficientes motivos de preocupación. Lo mejor es evitar cualquier señal que pueda entenderse como una provocación. Lo último que queremos es darles razones para que nos ataquen en masa." } } },
    ["Tabetha's Instructions"] = { { ids = { "i7516" }, first = "getajadetheyhideinmanydi", pages = { "Consigue un trozo de jade. Se ocultan en diversos lugares. Se trata de una piedra escasa, pero si hablas con un herrero o un ingeniero, es posible que les quede alguna.", "Busca una zarza electrificada. Para obtenerla, reúne 10 palos de tótem de los trols Secacorteza procedentes de las Tierras Altas de Arathi. Lleva los palos al Círculo de Vínculo Exterior, un círculo de piedras que hay en las tierras altas. Coloca los palos sobre la piedra central del círculo y espera a que un rayo caiga encima de ellos. Cuando esto ocurra, se formará la zarza electrificada." } } },
    ["Tainted Letter"] = { { ids = { "i9576" }, first = "toooftenpeoplelikethefol", pages = { "A menudo, algunos, como los seguidores de la Luz Sagrada, asustan a los profanos sobre lo que significa el verdadero poder, haciéndoles creer que no pueden tener acceso a ninguna de las facetas de lo arcano. Lo cierto es que no todo lo que hay en el más allá es maligno. No todas las entidades buscan dominar o subyugar a otros. Si eres bastante poderoso, estas mismas entidades pueden convertirse en tus seguidores.\n\nEsto es algo que quiero analizar más en detalle contigo. Búscame en el cementerio, a la derecha de la abadía.\n\nDrusilla La Salle, instructora de brujos" } } },
    ["Tainted Memorandum"] = { { ids = { "i9577" }, first = "attentionremainsilentdon", pages = { "ATENCIÓN:\n\n¡Guarda silencio! ¡No mires a tu alrededor! Es posible que alguien te esté vigilando.\n\nMi nombre es Alamar Grimm, $N. Entreno a aquellos que buscan el conocimiento y obtener un mayor poder de... los mundos del más allá. Me han pedido que entre en contacto contigo de forma discreta y que te haga saber que puedo instruirte más a fondo, enseñándote una variante real de la magia.\n\nCuando puedas, búscame en la parte trasera de Yunquemar.\n\nAlamar Grimm, $ginstructor:instructora; de brujos" } } },
    ["Tainted Parchment"] = { { ids = { "i9579" }, first = "iwritethismessageinthemo", pages = { "Escribo este mensaje con las tintas más poderosas que soy capaz de crear, $N. Maldeciré instantáneamente a todo aquel que ose leerlo, exceptuándote a ti. Así de $gpoderoso:poderosa; soy. Puedo invocar demonios procedentes del Vacío Abisal a voluntad. Acabo con mis enemigos mientras duermen y en el campo de batalla. Y ahora tú también has podido comprobar hasta dónde llega mi poder. Mis hermanos no caben en sí de gozo.\n\nBúscame en las profundidades de El Cubil, una vez que hayas encontrado el camino. Tengo que contarte cosas muy importantes.\n\nNartok, instructor de brujos" } } },
    ["Tainted Scroll"] = { { ids = { "i9578" }, first = "anawfulpredicamenttofind", pages = { "Estamos en un grave aprieto, ¿no es verdad, $N? Apestados por el Príncipe Hediondo. Rechazados y condenados al ostracismo por los nuestros. Finalmente, hacemos lo que nos place gracias a la bella Sylvanas, pero ¿de qué nos sirve ahora? Somos $gesclavos:esclavas; de un amo distinto, pero $gesclavos:esclavas; al fin.\n\nPero ¿qué tal si nosotros fuéramos los amos? Sí, sabes lo que quiero decir, ¿no?\n\nEstamos incluso más apartados del resto de los Renegados, $N. Y esta es la razón por la que debemos comentar la jugada. Me encontrarás en la iglesia de Camposanto." } } },
    ["Tainted Tablet"] = { { ids = { "i282346" }, first = "yournascentskillsaretoor", pages = { "Tus incipientes habilidades son demasiado rudimentarias para advertir que esta tablilla está impregnada de poderosas maldiciones de sufrimiento que impiden leerla a ojos no deseados.\n\nMediante mi poder he sentido tus primeros pasos hacia una tenue conexión con el Vacío Abisal. Ahora me pongo en contacto contigo para ofrecerte el don de mi tutela. Bajo mi guía aprenderás a mandar demonios e invocar las llamas de más allá de la vida mortal.\n\nBúscame en las profundidades del Cubil cuando hayas aprendido a orientarte. Quiero hablar contigo de asuntos importantes.\n\n-Nartok, instructor de brujos" } } },
    ["Tattered Note"] = { { ids = { "i272319" }, first = "guldanagreedanddecidedth", pages = { "Gul'dan accedió y decidió que, una vez que los moradores de Azeroth fueran derrotados, localizaría la legendaria tumba y reclamaría su recompensa. Persuadido de que la Horda serviría a sus propósitos, Sargeras ordenó que comenzara la invasión.", "Mediante un esfuerzo conjunto, Medivh y los brujos del Consejo de la Sombra lograron abrir la puerta dimensional conocida como Portal Oscuro. Este portal unía la distancia que mediaba entre Azeroth y Draenor y era suficientemente extenso como para que los ejércitos atravesaran su interior. Gul'dan envió exploradores orcos a través del portal para supervisar las tierras que habrían de conquistar. Al regresar, los exploradores aseguraron al Consejo de la Sombra que el mundo de Azeroth estaba listo para ser conquistado.", "Aun convencido de que la corrupción de Gul'dan destruiría a su gente, Durotan habló una vez más en contra de los brujos. El valiente guerrero afirmó que los brujos estaban destruyendo la pureza del espíritu orco y que esta insensata invasión sería su condena. Gul'dan, que no estaba dispuesto a acabar con un héroe tan popular, envió a Durotan y a su clan Lobo Gélido hacia los confines de este nuevo mundo.", "Una vez que los exiliados Lobo Gélido arremetieron contra el portal, solo unos pocos clanes orcos les siguieron. Dichos orcos montaron rápidamente una base de operaciones dentro de la Ciénaga Negra, un área oscura e insana situada en el extremo oriental del reino de Ventormenta. Cuando los orcos comenzaron a dividirse y a explorar nuevas tierras, entraron directamente en conflicto con los defensores humanos de Ventormenta.", "Si bien estas escaramuzas solían acabar rápidamente, ilustran en gran medida las debilidades y los poderes de ambas especies rivales. Llane y Lothar nunca lograron reunir datos ciertos sobre el número de los orcos y solo podían suponer la magnitud de la fuerza con la que se enfrentaban.", "Transcurridos algunos años, la mayor parte de los orcos se habían introducido en Azeroth, por lo que Gul'dan consideró que había llegado el momento de asestar el primer golpe contra la humanidad. La Horda lanzó toda su fuerza contra el desprevenido reino de Ventormenta.", "Cuando las fuerzas de Azeroth y la Horda se enfrentaron por todo el reino, los conflictos internos comenzaron a cobrar su peaje en ambos ejércitos. El rey Llane, que creía que sus bestiales orcos eran incapaces de conquistar Azeroth, desdeñosamente mantuvo su posición en su capital de Ventormenta. Sin embargo, Lothar se convenció de que la batalla debía plantearse directamente al enemigo y se vio obligado a escoger entre sus propias convicciones y su lealtad al rey.", "Decidido a seguir sus propios instintos, Lothar asaltó la torre-fortaleza de Karazhan de Medivh con la ayuda del joven aprendiz de zahorí Khadgar. Khagdar y Lothar lograron derrotar al guardián poseído, que consideraron la fuente del conflicto.", "Sin darse cuenta, al acabar con el cuerpo de Medivh, Lothar y el joven aprendiz desterraron el espíritu de Sargeras al abismo. Como consecuencia de ello, el espíritu puro y virtuoso de Medivh pudo vivir... permitiéndose deambular por el plano astral durante muchos años.", "Aunque Medivh había sido derrotado, la Horda continuó dominando a los defensores de Ventormenta. Cuando la victoria de la Horda parecía cercana, Orgrim Martillo Maldito, uno de los jefes orcos más grandes, empezó a comprobar por sí mismo la terrible corrupción que se había extendido entre los clanes desde su existencia en Draenor.", "Su viejo camarada, Durotan, regresó del exilio y le previno una vez más contra la traición de Gul'dan. Reaccionando rápidamente, los asesinos de Gul'dan acabaron con Durotan y su familia, dejando con vida únicamente a su hijo. Martillo Maldito no supo que el hijo de Durotan fue encontrado por el oficial humano Aedelas Lodonegro y que fue hecho esclavo.\n\nUn día, este niño orco llegaría a convertirse en el líder más grande que vería su pueblo.", "Indignado por la muerte de Durotan, Orgrim intentó liberar a la Horda de la corrupción demoníaca y, finalmente, asumió el rol de jefe de la Horda, eliminando a la marioneta corrupta de Gul'dan, Puño Negro. Bajo su decisivo liderazgo, la implacable Horda finalmente puso sitio al Castillo de Ventormenta.", "El rey Llane había subestimado en gran medida el poder de la Horda y pudo observar inerme cómo su reino caía ante los invasores de piel verde. Finalmente, el rey Llane fue asesinado por uno de los asesinos más hábiles del Consejo de la Sombra: el medio orco Garona.", "Lothar y sus guerreros, regresando a casa desde Karazhan, tenían la intención de contener la pérdida de vidas y salvar su otrora glorioso hogar. Pero regresaron demasiado tarde y encontraron su amado reino convertido en humeantes ruinas. La Horda de orcos continuó asolando el país y reclamando la propiedad de las tierras circundantes. Obligados a ocultarse, Lothar y sus compañeros hicieron un solemne juramento para reclamar su patria natal a cualquier precio." } }, { ids = { "i274463" }, first = "thetunnelshavereachedthe", pages = { "Los túneles han llegado a los riscos de Las Mil Agujas y nuestros preparativos han pasado inadvertidos, pero debemos actuar deprisa. No podemos permitir que los necios del Poblado Viento Libre nos descubran antes de estar listos para avanzar.\n\nEnvía a tu chamán. Con todo lo que Hirzek ha conseguido, estamos preparados para empezar.\n\nLa tormenta rugirá, la tierra temblará y la marea subirá, dejando solo cadáveres que animar a nuestro paso. Sus huesos abrirán un camino hasta...\n\n<La nota termina de golpe al pie de la página rota.>" } } },
    ["Teronis' Journal"] = { { ids = { "i5505" }, first = "istartedthisjournalsoico", pages = { "Comencé a escribir este diario para guardar notas acerca de mi investigación para ayudar a Vallefresno. Estos acontecimientos ocurridos no hace mucho están envueltos en un misterio y, con suerte, podré desvelar algunos de ellos para así ayudar a mi gente.\n\nEmpezaré comentando ciertos hechos para evitar olvidarlos más adelante.\n\nMe he dado cuenta de que los rumores acerca de los esfuerzos del zahorí Dartol son ciertos.", "Si bien antes pensé que sería absurdo que un humano llegara a nuestras tierras y aprendiera nuestras costumbres, este zahorí, este hombre malvado, llegó aquí y no solo sobrevivió, sino que obtuvo parte de nuestra sabiduría. Todavía no sé bien cómo lo hizo...\n\nDurante mi investigación, no he podido descubrir hasta ahora sus objetivos, pero su plan parece simple: utilizar magia druídica, intentó primero hacer amigos y luego controlar a los furbolgs. Si hubo un intento de causar daño a mis parientes o cualquier otro propósito malicioso, espero encontrar la explicación antes de acabar mis pesquisas.", "En cualquier caso, aparentemente tuvo éxito a la hora de poner a punto sus planes. ¿Acaso intentó poner en práctica sus maquinaciones en los furbolgs antes de intentarlo con mi gente? ¿Los furbolgs tenían algo que codiciaba? ¿Quién sabe?\n\nUtilizando un objeto creado por él mismo (una vara o un bastón), intentó infiltrarse en las tribus fúrbolg de Vallefresno. En algún punto (y aquí es donde muchos detalles resultan oscuros), fue descubierto por los furbolgs mientras intentaba manipularlos para que actuaran uno contra", "otros. Como estoy seguro de que ocurriría con los elfos, los furbolgs estaban airados, pero reaccionaron con mucha mayor fuerza y mataron a Dartol.\n\nLos furbolgs, al menos en ese momento, no eran las mismas criaturas corruptas que llegaron a ser posteriormente. Entonces, aún eran racionales e inteligentes, y su relación con nuestra gente era amistosa.\n\nTengo la esperanza de que si vuelvo a crear la vara con la ayuda de un dríade llamado Shael'dryn, podré utilizar su poder para ayudar a nuestra gente... y a los furbolgs.", "No todos los furbolgs han sido corrompidos. Algunos aún viven en el bosque e intentan protegerlo. Durante el periodo en el que se corrompieron, algunos de los furbolgs huyeron, muchos fueron asesinados y otros fueron desterrados de sus tribus.\n\nEncontré a un venerables fúrbolg de la tribu Corrupto, viviendo por encima del lago Mystral. Su nombre es Krolg.\n\nEstuve observándolo durante días y creo que, si me hubiera acercado a él disfrazado de fúrbolg, podría haberle ayudado y habría descubierto una forma de restablecer los lazos entre nuestros pueblos.", "Además de matar al Dartol, el fúrbolg partió la vara en tres partes para que no pudiera volver a usarse en su contra. Fue difícil, pero tengo una idea bastante clara de dónde se colocaron las tres partes.\n\nLa gema\nLa primera parte de la vara, una gema brillante, se ocultó en un Santuario del noroeste de Vallefresno. Creo que ahora este santuario está en ruinas en el centro del lago Falathim. $gLos:Las; centinelas me han dicho que ahora está habitado por murlocs.", "Si no puedo localizar la gema oculta en el santuario, puede que se encuentre en posesión de uno de los murlocs.\n\nLa parte de la vara\nEsta vara fue confiada a los antárboles cerca de lo que hoy se conoce como Frondavil. Ni los furbolgs ni los míos podríamos haber sospechado nunca que estas magníficas criaturas pudieran caer en las garras de la corrupción que asoló la tierra.\n\nMis investigaciones me indican que los guardianes conservan la pieza en un pequeño claro, dentro de un arcón. Para averiguar más detalles, tendré que hablar con Shael'dryn.", "Shael'dryn es una dríade que protege la poza de la luna de la luna al noreste del Lago Iris. Se niega a abandonar el bosque o a dejarlo caer en la corrupción. Sé que ella tiene el poder y los conocimientos necesarios para reparar la vara o, al menos, decirme cómo puedo hacerlo por mí mismo.\n\nEl pomo\nSe entregó el pomo de la vara a los druidas de Dor'danil. No obstante, esto supone un problema importante: los druidas están muertos.\n\nAhora, sus espíritus ocupan el área y ya no se muestran hospitalarios.", "Puede que esto requiera más investigación. No estoy seguro de tener poder suficiente para luchar contra los espíritus de mis parientes muertos... Intentaré escarbar las profundidades de Dor'danil y encontrar el pomo.\n\n(Nota: Durante mis preparativos en Astranaar, me he encontrado recientemente con un cazador de enanos que pasó bastante tiempo en Vallefresno, intentando ayudar a mi gente. Procedía de un lugar llamado Ventormenta.\n\nUna noche estuvimos hablando, mientras tomábamos algunas cervezas, y sus relatos me han dado nuevas esperanzas de poder encontrar el pomo...", "Me dijo que recorrió todo Dor'danil y que nunca vio un cofre o cualquier otra clase de contenedor que pudiera albergar el pomo.\n\nAsimismo, me dijo que babosas de la podredumbre habitaban el área y que devoraban prácticamente todo aquello que era más pequeño que ellas. Vio cómo \"comían\" mesas, esculturas, osos ¡e incluso gnomos!\n\nLas babosas parecen obtener gran parte del alimento a partir de objetos mágicos. Si el cofre que contiene el pomo estuviera encantado, habría muchas posibilidades de que las babosas se lo comieran.", "Se trata de un juego, pero en este momento no dispongo de otras pistas...\n\nCuando averigüe más, lo escribiré en estas páginas, pero hasta entonces, intentaré localizar las partes de la vara y trataré de ayudar a Vallefresno." } } },
    ["The Alliance of Lordaeron"] = { { ids = { "o175746" }, first = "lordlotharralliedtheremn", pages = { "Lothar reunió los restos de los ejércitos de Azeroth tras su derrota en el Castillo de Ventormenta y luego puso en marcha un éxodo masivo por mar hacia el norteño reino de Lordaeron. Convencido de que si no se controlaba a la Horda, derrotaría a toda la humanidad, los líderes de las siete naciones humanas se reunieron y acordaron unir esfuerzos en lo que se conocería como la Alianza de Lordaeron.", "Por primera vez en prácticamente tres mil años, las naciones separadas de Arathor estaban unidas una vez más bajo un estandarte común. Nombrado Comandante Supremo de las Fuerzas Aliadas, Lord Lothar preparó a sus ejércitos para hacer frente a la llegada de la Horda.", "Ayudado por sus lugartenientes, Uther el Luminoso, el almirante Daelin Valiente y Turalyon, Lothar fue capaz de convencer a las razas semihumanas de Lordaeron de la inminente amenaza. La Alianza obtuvo el apoyo de los estoicos enanos de Forjaz y de un pequeño número de elfos nobles de Quel'Thalas.", "Los elfos, dirigidos en aquel tiempo por Anasterian Caminante del Sol, no estaban interesados en modo alguno en el conflicto que se aproximaba. Sin embargo, estaban dispuestos a ayudar a Lothar, ya que se trataba del último descendiente de la línea de sangre arathi, que había ayudado a los elfos en el pasado.", "La Horda, ahora dirigida por el Jefe de Guerra Martillo Maldito, trajo ogros procedentes de su hogar de Draenor y reclutó trols procedentes del bosque de Amani. Comprometidos en una campaña masiva para borrar el reino enano de Khaz Modan y los límites sureños de Lordaeron, la Horda diezmó casi sin esfuerzo cualquier clase de oposición.", "Las épicas batallas de la Segunda Guerra incluyeron desde escaramuzas navales a gran escala hasta ataques aéreos masivos. De alguna manera, la Horda logró desenterrar un poderoso artefacto conocido como Alma Demoníaca y lo utilizó para esclavizar a Alexstrasza, antigua reina de los dragones. Amenazando destruir sus preciosos huevos, la Horda obligó a Alexstrasza a enviar a sus hijos mayores a la guerra. Los nobles dragones rojos fueron obligados a luchar para la Horda y eso es lo que hicieron.", "La guerra rugió a través de los continentes de Khaz Modan, Lordaeron y el propio Azeroth. Como parte de su campaña en el norte, la Horda consiguió incendiar las tierras fronterizas de Quel'Thalas y, de esta manera, se aseguraron el compromiso final de los elfos con la causa de la Alianza. Las ciudades y los pueblos más grandes de Lordaeron quedaron destruidos y devastados por el conflicto. A pesar de la ausencia de refuerzos y de que todas las probabilidades estaban en contra, Lothar y sus aliados lograron mantener a sus enemigos a raya.", "Sin embargo, durante los días finales de la Segunda Guerra, cuando la victoria de la Horda parecía casi garantizada, una terrible contienda surgió entre los dos orcos más poderosos de Azeroth. Cuando Martillo Maldito preparaba su asalto final a la ciudad capital de Lordaeron, un asalto que habría de destruir las últimas reservas de la Alianza, Gul'dan y sus seguidores abandonaron sus puestos y marcharon hacia el mar.", "El perplejo Martillo Maldito, habiendo perdido prácticamente la mitad de sus fuerzas a causa de la traición de Gul'dan, se vio obligado a retroceder y a olvidar la posibilidad de obtener la mayor victoria contra la Alianza.", "Gul'dan, hambriento de poder y obsesionado con convertirse en un dios, se lanzó a una carrera desesperada para llegar hasta la tumba sumergida de Sargeras, que creía guardaba los secretos de un gran poder. Habiendo condenado a sus compañeros orcos a convertirse en esclavos de la Legión Ardiente, Gul'dan consideraba que no le debía nada a Martillo Maldito.", "Con el apoyo de los clanes Cazatormentas y Martillo Crepuscular, Gul'dan logró extraer la tumba de Sargeras del lecho marino. Sin embargo, cuando abrió la antigua e inundada bóveda, solo halló demonios enloquecidos que lo aguardaban.", "Con la intención de castigar a los díscolos orcos por su costosa traición, Martillo Maldito envió sus fuerzas para acabar con Gul'dan y traer a los renegados de vuelta al redil. Por su imprudencia, Gul'dan fue destrozado por los demonios enloquecidos que había liberado. Con su líder muerto, los clanes renegados cayeron rápidamente ante las enfurecidas legiones de Martillo Maldito.", "Aunque la rebelión había sido aplastada, la Horda fue incapaz de recuperarse de las terribles pérdidas que había sufrido. La traición de Gul'dan había permitido que la Alianza no solo renovara sus esperanzas, sino que le había concedido tiempo para reagruparse y contraatacar.", "Lothar, viendo que la Horda estaba fracturada desde dentro, reunió al resto de sus fuerzas y empujó a Martillo Maldito hacia el sur, obligándole a internarse en el destruido corazón de Ventormenta. Allí, las fuerzas de la Alianza atraparon a la Horda en retirada, dentro de la fortaleza volcánica Cumbre de Roca Negra. Aunque Lord Lothar cayó en la batalla en la base de la cumbre, su lugarteniente Turalyon volvió a reunir a las fuerzas de la Alianza en la hora undécima y empujó nuevamente a la Horda hacia el abismo del Pantano de las Penas.", "Las fuerzas de Turalyon lograron destruir el Portal Oscuro, la puerta mística que conectaba a los orcos con su hogar de Draenor. Sin posibilidades de obtener refuerzos y fracturada por las luchas internas, la Horda finalmente se derrumbó y terminó sucumbiendo al poder de la Alianza.", "Los dispersos clanes orcos fueron rápidamente rodeados y conducidos a campos de internamiento vigilados. Aunque parecía que la Horda había sido derrotada para bien, algunos fueron muy escépticos acerca de la posibilidad de la paz. Khadgar, convertido en archimago de cierto renombre, persuadió al alto mando de la Alianza para que construyera la Fortaleza de Nethergarde, que vigilaría las ruinas del Portal Oscuro y garantizaría que no se produjeran futuras invasiones procedentes de Draenor." } } },
    ["The Armor of Mannoroth"] = { { ids = { "o175658" }, first = "thesedemonplateswereworn", pages = { "Estas placas demoníacas fueron utilizadas por la criatura que por primera vez inoculó en nuestra gente la sed de sangre. Por el heroico acto de un valiente orco, que fue derrotado. Mannoroth el destructor ha desaparecido para siempre. Que estas placas nos recuerden siempre lo lejos que llegamos y lo mucho que luchamos para recuperar nuestro honor.\n\n-Thrall, Jefe de Guerra de la Horda" } } },
    ["The Battle of Grim Batol"] = { { ids = { "o175750" }, first = "meanwhileinthewartornlan", pages = { "Mientras tanto, en las atormentadas tierras del sur, los dispersos supervivientes de la Horda luchaban por su mera supervivencia. Aunque Grom Grito Infernal y su clan Grito de Guerra habían logrado evitar ser capturados, Mortojo y su clan Foso Sangrante fueron rodeados y conducidos a campos de internamiento en Lordaeron. A pesar de estos costosos levantamientos, pronto los guardianes de los campos lograron recuperar el control sobre sus salvajes prisioneros.", "Sin embargo, sin que la Alianza lo supiera, una gran fuerza de orcos aún vagaba libre en los páramos del norte de Khaz Modan. El clan Faucedraco, dirigido por el infame brujo Nekros, estaba utilizando un viejo artefacto conocido como Alma Demoníaca para controlar a la reina de los dragones Alexstrasza y a su Vuelo. Teniendo a la reina de los dragones como rehén, Nekros creó un ejército secreto en el interior de la abandonada fortaleza de Martillo Salvaje de Grim Batol (algunos decían que estaba maldita).", "Con la intención de liberar sus fuerzas y a los poderosos dragones rojos de la Alianza, Nekros esperaba reunir a la Horda y continuar su conquista de Azeroth. Su visión no llegó a realizarse: un pequeño grupo de luchadores de la resistencia, dirigido por el mago humano Rhonin, logró destruir el Alma Demoníaca y liberar a la reina de los dragones del yugo de Nekros.", "En su furia, los dragones de Alexstrasza destruyeron Grim Batol e incineraron a la mayor parte del clan Faucedraco. Los grandes planes de reunificación de Nekros cayeron por los suelos cuando las tropas de la Alianza rodearon a los orcos supervivientes y los arrojaron a los campos de internamiento. La derrota del clan Faucedraco señaló el fin de la Horda y el fin de la furiosa sed de sangre de los orcos." } } },
    ["The Betrayer Ascendant"] = { { ids = { "o175759" }, first = "duringthelegionsinvasion", pages = { "Durante la invasión de Vallefresno por la Legión, Illidan fue liberado de su prisión en un túmulo tras diez mil años de cautiverio. Aunque intentó complacer a sus camaradas, pronto volvió a su verdadera naturaleza y consumió las energías de un poderoso artefacto de brujo conocido como la Calavera de Gul'dan.", "Al hacerlo, desarrolló rasgos demoníacos y un poder enormemente amplificado. También obtuvo algunos recuerdos antiguos de Gul'dan, sobre todo los de la Tumba de Sargeras, la mazmorra insular que, según los rumores, contenía los restos del titán oscuro Sargeras.", "Rebosante de poder y libre para recorrer de nuevo el mundo, Illidan buscó su propio lugar en el gran orden de las cosas. Sin embargo, Kil'jaeden lo abordó con una oferta que no podía rechazar. La derrota de Archimonde en el Monte Hyjal había enfurecido al demonio, pero tenía preocupaciones mayores que la venganza.", "Al sentir que su creación, el Rey Exánime, se hacía demasiado poderosa para controlarla, Kil'jaeden ordenó a Illidan destruir a Ner'zhul y acabar de una vez por todas con la Plaga. A cambio recibiría un poder incalculable y un verdadero puesto entre los señores restantes de la Legión Ardiente.", "Illidan aceptó y se dispuso de inmediato a destruir el Trono Helado, el recipiente de cristal helado que albergaba el espíritu del Rey Exánime. Sabía que necesitaría un artefacto poderoso. Con los conocimientos obtenidos de los recuerdos de Gul'dan, decidió buscar la Tumba de Sargeras y reclamar los restos del titán oscuro.", "Cobró antiguas deudas de los Altonato y atrajo a los serpentinos nagas de sus guaridas submarinas. Dirigidos por la astuta bruja lady Vashj, lo ayudaron a llegar a las Islas Abruptas, donde se rumoreaba que estaba la Tumba de Sargeras.", "Mientras Illidan partía con los nagas, la celadora Maiev Cantosombrío comenzó a perseguirlo. Había sido su carcelera durante diez mil años y disfrutaba ante la idea de capturarlo de nuevo. Pero Illidan burló a Maiev y sus vigilantes y consiguió apoderarse del Ojo de Sargeras pese a sus esfuerzos. Con el poderoso Ojo en su poder viajó a la antigua ciudad de los magos, Dalaran.", "Reforzado por las líneas Ley de la ciudad, Illidan usó el Ojo para lanzar un hechizo destructivo contra la ciudadela del Rey Exánime en Corona de Hielo, en el lejano Rasganorte. Su ataque quebró las defensas del Rey Exánime y rompió el propio techo del mundo. En el último momento, el hechizo fue detenido cuando su hermano Malfurion y la sacerdotisa Tyrande llegaron para ayudar a Maiev.", "Sabiendo que a Kil'jaeden no le agradaría su fracaso al destruir el Trono Helado, Illidan huyó a la dimensión estéril llamada Terrallende, los últimos restos de Draenor, antiguo mundo natal de los orcos. Allí pensaba eludir la ira de Kil'jaeden y planear sus siguientes movimientos.", "Tras detener a Illidan, Malfurion y Tyrande regresaron al Bosque de Vallefresno para velar por su pueblo. Maiev, sin embargo, no se rindió tan fácilmente. Siguió a Illidan a Terrallende, decidida a llevarlo ante la justicia." } } },
    ["The Birth of the Lich King"] = { { ids = { "o175748" }, first = "nerzhulandhisfollowersen", pages = { "Ner'zhul y sus seguidores penetraron en El Vacío Abisal, el plano etéreo que conecta todos los mundos desperdigados a través de la Gran Oscuridad del Más Allá. Desafortunadamente, Kil'jaeden y sus esbirros estaban esperándole. Kil'jaeden, que había jurado vengarse de Ner'zhul por su orgullosa rebeldía, se dedicó a despedazar lentamente el cuerpo del viejo chamán, pieza a pieza.", "Kil'jaeden mantuvo el espíritu del chamán vivo e intacto y, de esta manera, dejó que Ner'zhul fuera totalmente consciente del desmembramiento que sufría su cuerpo. Aunque Ner'zhul suplicó al demonio que liberara su espíritu y le diera muerte, este replicó que el Pacto de Sangre que habían suscrito hacía mucho tiempo aún los unía y que Ner'zhul tenía un propósito que cumplir.", "El fracaso de los orcos a la hora de conquistar el mundo para la Legión Ardiente obligó a Kil'jaeden a crear un nuevo ejército para sembrar el caos sobre los reinos de Azeroth. Este nuevo ejército no podría ser presa de las mismas rivalidades y luchas internas que habían diezmado a la Horda. Tendría que ser despiadado y estar enfocado únicamente en su misión. Esta vez, Kil'jaeden no podía fracasar.", "Manteniendo el espíritu de Ner'zhul indefenso, Kil'jaeden le dio la última oportunidad de servir a la Legión o sufrir tormento por toda la eternidad. Una vez más, Ner'zhul accedió temerariamente a sellar el pacto con el demonio. El espíritu de Ner'zhul fue colocado en el interior de un bloque de hielo, duro como el diamante, especialmente elaborado, procedente de los lejanos confines de El Vacío Abisal.", "Confinado en su urna helada, Ner'zhul sintió que su conciencia se expandía diez mil veces más. Deformado por los caóticos poderes del demonio, Ner'zhul se convirtió en un ser espectral de poder insondable. En ese momento, el orco conocido como Ner'zhul se hizo pedazos para siempre y nació el Rey Exánime.", "Los caballeros muertos leales de Ner'zhul y los seguidores de Sombraluna también fueron transformados por las energías caóticas del demonio. Los debilitados taumaturgos fueron destrozados, siendo reconstituidos como exánimes esqueléticos. Los demonios garantizaron que, incluso en la muerte, los seguidores de Ner'zhul le sirvieran de forma incuestionable.", "Cuando llegó el momento, Kil'jaeden explicó la misión para la cual había creado al Rey Exánime. Ner'zhul debía extender una peste de muerte y terror por Azeroth que habría de acabar para siempre con la civilización humana. Todos aquellos que murieran a causa de la terrible peste volverían como no-muertos y sus espíritus estarían ligados a la voluntad de hierro de Ner'zhul para siempre.", "Kil'jaeden prometió que si Ner'zhul cumplía su oscura misión, exterminando la humanidad del mundo, sería liberado de su maldición y obtendría un nuevo y saludable cuerpo.", "Si bien Ner'zhul accedía de buen grado y se mostraba incluso ansioso por cumplir su papel, Kil'jaeden se mostró escéptico acerca de la lealtad de su siervo. Manteniendo al Rey Exánime sin cuerpo y atrapado en una urna de cristal, garantizaba su buena conducta a corto plazo, pero el demonio sabía que debía mantenerlo bajo estricta vigilancia. Para este fin, Kil'jaeden convocó a su guardia demoníaca de élite, los Señores del Terror vampíricos, para que controlaran a Ner'zhul y se aseguraran de que cumplía su terrible tarea.", "Tichondrius, el más poderoso y astuto de los Señores del Terror, se entusiasmó con el desafío. Estaba fascinado por la dureza de la peste y el desenfrenado potencial genocida del Rey Exánime." } } },
    ["The Book of Ur"] = { { ids = { "i6283" }, first = "thelandofazerothishostto", pages = { "La tierra de Azeroth alberga incontables maravillas. Flora, fauna, culturas y magia pueblan su superficie. Ciertamente, los curiosos encontrarán aquí una ilimitada variedad de formas de vida y maravillas sorprendentes. Basta echar un ligero vistazo.\n\nSi se mira con suficiente detenimiento, se abre una ventana a mundos desconocidos y cada uno alberga sus propios secretos.\n\nDe la misma manera que cada uno guarda sus propios horrores.", "Este es el propósito de mi libro: catalogar a aquellos seres, extraños mefistos decididos a destruir nuestras tierras, para que los exploradores que los encuentren sepan lo que tienen delante.\n\nSi te consideras un guardián de Azeroth, sigue leyendo. y conoce a tu enemigo.\n\nUr\nMago de Dalaran", "El mefisto sobre el que escribo es el ferocanis.\n\nEl folklore popular recoge historias sobre estas criaturas, pues ¿qué hijo de granjero no ha oído historias de lobizones bestiales acechando en los bosques y las marismas, fuera de este poblado?\n\nEstas historias encierran cierta verdad, tal vez nos advierten acerca de la presencia de los ferocanis, convertidos en mito para asustarnos.", "Pero antes de rechazar tales historias, debo asegurar al lector: los ferocanis son reales. Quizás no sean de este mundo, pero existen caminos entre sus moradas y las nuestras, ocultos poderes que los atraen hasta nosotros.\n\nEs mejor no pronunciar los conjuros que invocan a estas bestias, pues allí donde van, siembran el terror y la destrucción.", "Los ferocanis se reconocen por su similitud con los lobos de nuestro mundo. Los ferocanis se distinguen fácilmente por su grueso pelaje, sus orejas puntiagudas y sus alargados hocicos, similares a los de los lobos que conocemos.\n\nPero las diferencias también son claras: el grueso pelaje cubre el cuerpo musculoso de la bestia, que luce dos largos colmillos y zarpas afiladas como puñales. Su aullido esconde una malevolencia que ninguna otra bestia natural posee.", "El hábitat del ferocanis es un lugar oscuro, un lugar de pesadilla. Si en este mundo existen espacios a salvo de los malignos ferocanis, mis investigaciones no reflejan tales bastiones.\n\nSi tenemos en cuenta la ferocidad y la maldad de los ferocanis, lo más probable es que estos bastiones no existan.\n\nSe dice que los ferocanis viven a gusto en su mundo, pues, aunque algunos poseen mágicos poderes, no han intentado acercarse a Azeroth por impulso propio.\n\nEso nos hace afortunados.", "Como he dicho anteriormente, algunos ferocanis son diestros en las artes místicas, utilizando poderes oscuros y siniestros.\n\nSon habituales en ellos las maldiciones y los venenos sobrenaturales, de modo que queda advertido: aquellos que se enfrenten a un mago ferocanis deberán protegerse del poder de la sombra.", "Realmente deseo que ningún zahorí de Dalaran busque a los ferocanis, aun cuando sean plenamente conscientes de lo que hacen. Pues no hay acuerdo posible, no revelarán secreto alguno y nada bueno puede obtenerse de estas bestias.\n\nEs mejor dejarlas en paz en su mundo. Si llegan al nuestro y no son destruidos, estaremos en grave peligro..." } } },
    ["The Collector's Schedule"] = { { ids = { "i2223" }, first = "belowistheprocessandsche", pages = { "Abajo se describe el proceso y el programa de excavación y transporte del oro de las minas de Elwynn a nuestro puesto de mando en los Páramos de Poniente.\n\nPrograma de excavación:\n\nDomingo: 12.30\nMiércoles: 12.30\n\nDurante todos los días señalados, el oro extraído de las minas de Elwynn se recogerá en la plantación de calabazas de Brackwell. El agente encargado de estos cargamentos o \"Recolector\" se reconocerá por su anillo grabado. Un anillo que yo le di.", "Un grupo procedente del puesto de mando de los Defias se pondrá en contacto con el Coleccionista y él trasladará el oro recogido.\n\nAsegúrate de que este proceso se lleve a cabo cuidadosamente y con la mayor discreción. El Coleccionista es responsable del traslado del oro, pero, en última instancia, es responsable de todos los miembros de la Hermandad Defias, garantizando así que sus órdenes sean acatadas con atención y disciplina.", "Recordad, $ghermanos míos:hermanas mías;, que un día fuimos $gartesanos:artesanas;. Realizaremos nuestro trabajo con la misma precisión que utilizamos en nuestro oficio anterior.\n\nEVC" } } },
    ["The Dark Portal and the Fall of Stormwind"] = { { ids = { "o175745" }, first = "askiljaedenpreparedtheho", pages = { "Mientras Kil'jaeden preparaba a la Horda para su invasión de Azeroth, Medivh continuaba luchando por su alma contra Sargeras. El rey Llane, noble monarca de Ventormenta, recelaba de la oscuridad que parecía contaminar el espíritu de su nuevo amigo.", "El rey Llane compartió sus preocupaciones con Anduin Lothar, el último descendiente de la línea de sangre arathi, a quien nombró su lugarteniente. Aun así, ningún hombre podía imaginar que el lento descenso de Medivh hacia la locura causaría los horrores que estaban por llegar.", "Como incentivo final, Sargeras prometió otorgar un gran poder a Gul'dan si accedía a conducir la Horda a Azeroth. A través de Medivh, Sargeras dijo al brujo que se podía convertir en un dios viviente si localizaba la tumba sumergida donde la guardiana Aegwynn había colocado el cuerpo inútil de Sargeras hacía casi mil años.", "Gul'dan accedió y decidió que, una vez que los moradores de Azeroth fueran derrotados, localizaría la legendaria tumba y reclamaría su recompensa. Persuadido de que la Horda serviría a sus propósitos, Sargeras ordenó que comenzara la invasión.", "Mediante un esfuerzo conjunto, Medivh y los brujos del Consejo de la Sombra lograron abrir la puerta dimensional conocida como Portal Oscuro. Este portal unía la distancia que mediaba entre Azeroth y Draenor y era suficientemente extenso como para que los ejércitos atravesaran su interior. Gul'dan envió exploradores orcos a través del portal para supervisar las tierras que habrían de conquistar. Al regresar, los exploradores aseguraron al Consejo de la Sombra que el mundo de Azeroth estaba listo para ser conquistado.", "Aun convencido de que la corrupción de Gul'dan destruiría a su gente, Durotan habló una vez más en contra de los brujos. El valiente guerrero afirmó que los brujos estaban destruyendo la pureza del espíritu orco y que esta insensata invasión sería su condena. Gul'dan, que no estaba dispuesto a acabar con un héroe tan popular, envió a Durotan y a su clan Lobo Gélido hacia los confines de este nuevo mundo.", "Una vez que los exiliados Lobo Gélido arremetieron contra el portal, solo unos pocos clanes orcos les siguieron. Dichos orcos montaron rápidamente una base de operaciones dentro de la Ciénaga Negra, un área oscura e insana situada en el extremo oriental del reino de Ventormenta. Cuando los orcos comenzaron a dividirse y a explorar nuevas tierras, entraron directamente en conflicto con los defensores humanos de Ventormenta.", "Si bien estas escaramuzas solían acabar rápidamente, ilustran en gran medida las debilidades y los poderes de ambas especies rivales. Llane y Lothar nunca lograron reunir datos ciertos sobre el número de los orcos y solo podían suponer la magnitud de la fuerza con la que se enfrentaban.", "Transcurridos algunos años, la mayor parte de los orcos se habían introducido en Azeroth, por lo que Gul'dan consideró que había llegado el momento de asestar el primer golpe contra la humanidad. La Horda lanzó toda su fuerza contra el desprevenido reino de Ventormenta.", "Cuando las fuerzas de Azeroth y la Horda se enfrentaron por todo el reino, los conflictos internos comenzaron a cobrar su peaje en ambos ejércitos. El rey Llane, que creía que sus bestiales orcos eran incapaces de conquistar Azeroth, desdeñosamente mantuvo su posición en su capital de Ventormenta. Sin embargo, Lothar se convenció de que la batalla debía plantearse directamente al enemigo y se vio obligado a escoger entre sus propias convicciones y su lealtad al rey.", "Decidido a seguir sus propios instintos, Lothar asaltó la torre-fortaleza de Karazhan de Medivh con la ayuda del joven aprendiz de zahorí Khadgar. Khagdar y Lothar lograron derrotar al guardián poseído, que consideraron la fuente del conflicto.", "Sin darse cuenta, al acabar con el cuerpo de Medivh, Lothar y el joven aprendiz desterraron el espíritu de Sargeras al abismo. Como consecuencia de ello, el espíritu puro y virtuoso de Medivh pudo vivir... permitiéndose deambular por el plano astral durante muchos años.", "Aunque Medivh había sido derrotado, la Horda continuó dominando a los defensores de Ventormenta. Cuando la victoria de la Horda parecía cercana, Orgrim Martillo Maldito, uno de los jefes orcos más grandes, empezó a comprobar por sí mismo la terrible corrupción que se había extendido entre los clanes desde su existencia en Draenor.", "Su viejo camarada, Durotan, regresó del exilio y le previno una vez más contra la traición de Gul'dan. Reaccionando rápidamente, los asesinos de Gul'dan acabaron con Durotan y su familia, dejando con vida únicamente a su hijo. Martillo Maldito no supo que el hijo de Durotan fue encontrado por el oficial humano Aedelas Lodonegro y que fue hecho esclavo.\n\nUn día, este niño orco llegaría a convertirse en el líder más grande que vería su pueblo.", "Indignado por la muerte de Durotan, Orgrim intentó liberar a la Horda de la corrupción demoníaca y, finalmente, asumió el rol de jefe de la Horda, eliminando a la marioneta corrupta de Gul'dan, Puño Negro. Bajo su decisivo liderazgo, la implacable Horda finalmente puso sitio al Castillo de Ventormenta.", "El rey Llane había subestimado en gran medida el poder de la Horda y pudo observar inerme cómo su reino caía ante los invasores de piel verde. Finalmente, el rey Llane fue asesinado por uno de los asesinos más hábiles del Consejo de la Sombra: el medio orco Garona.", "Lothar y sus guerreros, regresando a casa desde Karazhan, tenían la intención de contener la pérdida de vidas y salvar su otrora glorioso hogar. Pero regresaron demasiado tarde y encontraron su amado reino convertido en humeantes ruinas. La Horda de orcos continuó asolando el país y reclamando la propiedad de las tierras circundantes. Obligados a ocultarse, Lothar y sus compañeros hicieron un solemne juramento para reclamar su patria natal a cualquier precio." } } },
    ["The Eye of Divinity"] = { { ids = { "i18646" }, first = "whenyoupeerintotheeyeima", pages = { "Al mirar dentro del Ojo, las imágenes de una gran batalla llenan tu mente...\n\nEste conflicto aterrador parece ocurrir en algún lugar de Lordaeron...\n\nApenas distingues a una mujer sola entre mil cadáveres, resistiendo a un mar de la Plaga...\n\nEstá desesperadamente superada en número...\n\nZarcillos de luz escapan de sus manos y atraviesan a cientos de no-muertos.", "Todo parece en vano...\n\nMomentos después, los cadáveres de los campesinos que la rodeaban se abalanzan sobre la sacerdotisa...\n\nLos caídos se han alzado." } } },
    ["The Feast of Winter Veil"] = { { ids = { "i17735" }, first = "thefeastofwinterveilthel", pages = { "El Festival de Invierno\n\nLas últimas estaciones de Azeroth se consideran tiempo de cambio en muchas culturas. Los enanos y los tauren atienden a una leyenda del próximo Festival de Invierno: la tierra se cubre de nieve y, de esta manera, anuncia un tiempo de renovación: como una época propicia para la celebración. Si bien la interpretación de las leyendas que comparten las razas de Azeroth es similar, la forma en que responden a ellas es tan distinta como las propias razas.", "La Leyenda del Gran Padre Invierno\n\nSe considera que la expresión \"Festival de Invierno\" está relacionada con un ser sobrenatural citado en muchas culturas como el Gran Padre Invierno. Cuando este personaje recorre la tierra en las estaciones, el propio invierno es su manto de nubes. En su despertar, la tierra está cubierta de nieve y, de esta manera, se dice que el Gran Padre Invierno cubre la tierra con su gélido velo. Aunque ciertas zonas de Azeroth estén cubiertas de nieve, esto otorga a la tierra tiempo para el renacimiento y la renovación.", "Los enanos\n\nAun consumidos por la búsqueda de sus orígenes, los enanos eligieron celebrar la estación como un reconocimiento al propio Gran Padre Invierno. Lo consideran como la personificación de uno de los ancestros de Azeroth: los titanes. Sea cual sea el grado de parentesco que los une a estos seres místicos, consideran su nevado hogar de Dun Morogh como el principal ejemplo de las bendiciones del Gran Padre Invierno.", "Los tauren\n\nLos tauren y su concepción chamánica del invierno, junto con sus recientes esfuerzos de carácter druídico, casan perfectamente con la leyenda del Festival de Invierno. Sin embargo, se encuentran casi por entero en los aspectos renovadores de la tradición, dejando el tema de la adoración para otras razas (como las contemplan ellos) que tengan una sintonía menor con la naturaleza de las cosas. Muchos tauren escogen esta época como el tiempo adecuado para dar gracias por las bendiciones de su nuevo hogar en Mulgore.", "Festejos\n\nLa idea de los festejos durante esta época del año hunde sus raíces en el terreno de la propia leyenda. Cuando el Gran Padre Invierno atravesaba Azeroth, mientras lo cubría todo con su gélido mando, se decía que otorgaría el premio a aquellos que le dieran la bienvenida. Por ello, la idea de organizar festejos durante el Festival de Invierno uniría a las comunidades que compartieran lo que tenían. Habitualmente, un único día de júbilo y festejos daba la bienvenida al cambio, como anticipo a la renovación de la tierra.", "Observación desde al modernidad\n\nOtras culturas han empezado a reconocer el Festival de Invierno como una época digna de ser celebrada, si bien no siempre siguen las mismas tradiciones en las cuales se basa la leyenda. Las costumbres, a menudo sin otro propósito que reservar un día para la celebración y el intercambio de regalos, han llegado hasta la observación moderna de la estación. Incluso se suele utilizar la imagen del Gran Padre Invierno, pero antes que un titán sobrenatural, se ha convertido en un reclamo comercial." } } },
    ["The First Tablet of I'lalai"] = { { ids = { "i270308" }, first = "amoonoverthevaleshinesca", pages = { "Brilla la luna sobre el valle,\nresplandeciendo sobre la selva\nvalientes guerreros escuchan el clamor\npara defender nuestra nación y sus sagradas tierras.\n\nBrilla la luna sobre el valle\nen lo alto, sobre el fragor de la batalla\nallí donde se funde la sangre\ndel enemigo con la del compañero.", "Cuando nuestros hermanos marchen\nhacia reinos de otro mundo,\nel alma y el espíritu se curtirán\nen las profundidades del valle.\n\nCuando nuestros hermanos marchen\nhasta el templo de la montaña,\nprotegeremos su espíritu eterno\ntallado en el sagrado añil del cristal.\n\nCuando nuestros hermanos marchen,\nla luna brillará sobre el valle." } } },
    ["The First Troll Legend"] = { { ids = { "i2005" }, first = "amoonoverthevaleshinesca", pages = { "Brilla la luna sobre el valle,\nresplandeciendo sobre la selva\nvalientes guerreros escuchan el clamor\npara defender nuestra nación y sus sagradas tierras.\n\nBrilla la luna sobre el valle\nen lo alto, sobre el fragor de la batalla\nallí donde se funde la sangre\ndel enemigo con la del compañero.", "Cuando nuestros hermanos marchen\nhacia reinos de otro mundo,\nel alma y el espíritu se curtirán\nen las profundidades del valle.\n\nCuando nuestros hermanos marchen\nhasta el templo de la montaña,\nprotegeremos su espíritu eterno\ntallado en el sagrado añil del cristal.\n\nCuando nuestros hermanos marchen,\nla luna brillará sobre el valle." } } },
    ["The Founding of Quel'Thalas"] = { { ids = { "o175733" }, first = "thehighelvesledbydathrem", pages = { "Los elfos nobles, dirigidos por Dath'Remar, abandonaron Kalimdor y desafiaron las tormentas de la Vorágine. Sus flotas recorrieron las ruinas del mundo durante muchos años, descubriendo a su paso nuevos misterios y reinos perdidos. Dath'Remar, que había adoptado el nombre de Caminante del Sol (o \"el que camina de día\"), buscó lugares que resultaran aptos para construir en ellos un nuevo hogar para su gente.", "Su flota finalmente desembarcó en las playas del reino cuyos habitantes denominaron Lordaeron. Tomando posiciones en tierra, los elfos nobles fundaron su sede en los tranquilos Claros de Tirisfal. Transcurridos unos años, muchos de ellos empezaron a enloquecer. Existía la teoría de que bajo aquellas tierras se ocultaba una fuerza maligna, pero estos rumores nunca se confirmaron. Los elfos nobles llevaron su campamento a otra parte y se dirigieron al norte en dirección a otras tierras ricas en energías naturales.", "Durante el trayecto de los elfos nobles por las escarpadas montañas de Lordaeron, el viaje se hizo cada vez más peligroso. Puesto que fueron totalmente privados de las energías vivificadoras del Pozo de la Eternidad, muchos de ellos enfermaron a causa del gélido clima o murieron de hambre. Sin embargo, el hecho más desconcertante era que ya no eran inmortales ni inmunes a los elementos.", "También encogieron de tamaño y su piel perdió la tonalidad violeta que los caracterizaba. A pesar de las penurias, conocieron maravillosas criaturas jamás vistas en Kalimdor. Asimismo, encontraron tribus de humanos primitivos que cazaban en los antiguos bosques. No obstante, la mayor amenaza que los acechaba la constituían los voraces y maliciosos trols del bosque de Zul'Aman.", "Estos trols con la piel recubierta de musgo tenía el poder de regenerar sus miembros mutilados y curar graves heridas físicas, pero conformaban, sin duda, una raza bárbara y maligna. El Imperio Amani se extendió por la mayor parte del territorio del norte de Lordaeron y sus trols lucharon incansablemente para mantener a los forasteros alejados de sus tierras. Los elfos desarrollaron una profunda aversión contra los despiadados trols y los mataban siempre que podían.", "Transcurridos muchos años, los elfos nobles finalmente encontraron una tierra que les recordaba a Kalimdor. En el interior del bosque que había al norte del continente, fundaron el reino de Quel'Thalas y prometieron crear un vasto imperio que eclipsaría al de sus primos kaldorei. Desafortunadamente, pronto descubrieron que Quel'Thalas había sido fundada sobre una antigua ciudad trol que esta raza aún consideraba sagrada. Casi de inmediato, los trols empezaron a atacar en masa los asentamientos de los elfos.", "Los tozudos elfos, que no estaban dispuestos a ceder su nuevo territorio, utilizaron la magia que habían obtenido del Pozo de la Eternidad y mantuvieron a raya a los salvajes trols. Liderados por Dath'Remar, pudieron derrotar a las bandas de guerra Amani, que eran diez veces más numerosas. Algunos elfos, que recordaban las antiguas advertencias de los kaldorei, temían que el uso de la magia pudiera atraer la atención de la desterrada Legión Ardiente.", "Por ello, decidieron proteger sus tierras con una barrera que les permitiera seguir desarrollando sus encantamientos. Construyeron una serie de runas monolíticas en varios puntos de los alrededores de Quel'Thalas, marcando las fronteras de la barrera mágica. Las runas no solo encubrían la magia de los elfos ante amenazas extradimensionales, sino que también les ayudaban a ahuyentar a las supersticiosas bandas trol.", "Transcurrido cierto tiempo, Quel'Thalas se convirtió en un bello monumento a los esfuerzos de los elfos nobles y a sus hazañas mágicas. Sus hermosos palacios fueron construidos siguiendo el mismo estilo arquitectónico que el de las antiguas salas de Kalimdor, si bien se entremezclaban con la topografía natural de la tierra. Quel'Thalas se había convertido en una joya que los elfos siempre habían deseado crear.", "A continuación, se fundó la Asamblea de Lunargenta para gobernar Quel'Thalas, si bien la dinastía de los Caminante del Sol conservaba cierto poder político. Compuesto por siete elfos nobles mayores, la Asamblea se encargó de velar por la seguridad de la tierra de los elfos y de sus gentes. Rodeados por su barrera protectora, los elfos nobles hicieron caso omiso a las advertencias de los kaldorei y continuaron usando la magia con total libertad en todos los aspectos de sus vidas.", "Durante unos cuatro mil años, los elfos nobles vivieron pacíficamente en su reino aislado y protegido. No obstante, los vengativos trols no se conformaban fácilmente con su derrota. Planearon su venganza en las profundidades de los bosques y esperaron a que sus tropas crecieran. Finalmente, un poderoso ejército de trols partió de los oscuros bosques y, nuevamente, sitiaron las relucientes cumbres de Quel'Thalas." } } },
    ["The Fourth Troll Legend"] = { { ids = { "i2008" }, first = "bymoonandfirebyfleshandb", pages = { "Bajo la luna y el fuego,\nen la carne y el hueso,\nescrito con sangre,\ngrabado en la piedra.\n\nAbandona este lugar\no aguarda tu fin.\nLa muerte vigila\nla tumba del Emperador." } } },
    ["The Frostwolf Artichoke"] = { { ids = { "i19484" }, first = "thefrostwolfartichoketal", pages = { "La alcachofa de los Lobo Gélido: Relatos sobre la gloria de Pico Tormenta\nPor Vanndar Pico Tormenta\n\n¿Qué son los Lobo Gélido? La respuesta es sencilla: Los Lobo Gélido son salvajes que intentan acabar con nuestra imprescindible soberanía imperial. Al igual que ocurre con una alcachofa, los Lobo Gélido cuentan con un espinoso conjunto de defensas acorazadas y también, como ocurre con la alcachofa, una vez que se extrae la capa exterior, el corazón queda expuesto y listo para ser engullido con una suave salsa de ajo.\n\n¡Delicioso!", "Capítulo 1 - El frente\n\nLas líneas del frente de las defensas de los Lobo Gélido están formadas por los guerreros Lobo Gélido. Estos guerreros están desplegados en las líneas del frente, desde la fortaleza del capitán Galvangar: Baluarte Sangre Fría. La forma más eficaz de eliminar esta capa de las defensas consiste en destruir el Baluarte Sangre Fría.\n\nPon la fortaleza bajo sitio y destruye al capitán Galvangar. Una vez que lo hayas logrado, las líneas del frente se desmoronarán.", "Capítulo 2 - Sangre Fría y Punta de la Torre\n\nUna vez desaparecida la primera capa, la segunda capa de la \"alcachofa\" quedará expuesta. Mediante la destrucción de las torres Lobo Gélido, situadas cerca de las líneas del frente, lograrás neutralizar a los legionarios y a las patrullas que se apiñan en la retaguardia.\n\nLas torres están bien fortificadas y cada una de ellas alberga uno de los comandantes de élite de Drek'Thar. Hay que eliminarlos. De esta manera, el camino para desmantelar las defensas Lobo Gélido quedará expedito.", "Capítulo 3 - Los cuatro comandantes\n\nSi has seguido sabiamente esta guía, en este momento, dos de los comandantes de Drek'Thar deberían estar muertos. ¡Buen trabajo, soldado! No obstante, su resolución continúa siendo un problema. Debes completar la tarea de romper la cadena de mando, acabando con los dos comandantes restantes.\n\nUna vez que hayan desaparecido los cuatro comandantes, los legionarios Lobo Gélido que cuidan el Bastión Lobo Gélido quedarán aislados y sin superiores. ¡La fruta estará madura!", "Capítulo 4 - Las torres Lobo Gélido del este y el oeste\n\nSolo te queda una capa para alcanzar la victoria. Las unidades de guardianes más poderosas y en quienes más confía Drek'Thar: Los Guardianes Lobo Gélido.\n\nLos Guardianes Lobo Gélido proceden de pelotones de la reserva situados en las torres Lobo Gélido del este y el oeste. Destruye estas torres y verás cómo los guardianes Lobo Gélido restantes huyen de forma vergonzosa.", "Epílogo\n\n\"Sumerge la alcachofa en crema de ajo y mayonesa. Acompaña la comida con una reposada y embriagadora cerveza.\"\n\nAhora Drek'Thar está solo, con los dos perros que lo acompañan. Captura el Puesto de auxilio de Lobo Gélido para que te sirva de ayuda en la batalla y destruye a Drek'Thar. Cuando el general caiga, esta tierra volverá finalmente a su legítimo dueño: Los Pico Tormenta." } } },
    ["The General's Response"] = { { ids = { "i1294" }, first = "honorablemagistratesolom", pages = { "Honorable Magistrado Solomon:\n\nTe acompaño en el sentimiento por la muerte de nuestros compañeros. Me encargaré personalmente de informar al Rey sobre esta situación y deseo fervientemente poder llevar refuerzos a Villa del Lago. Últimamente, Su Majestad ha resultado inaccesible y actúa de un modo bastante extraño. Te comento esto por la confianza que te tengo.\n\nHasta pronto,\n\nGeneral Marcus Jonathan\nReino de Ventormenta" } } },
    ["The Green Hills of Stranglethorn"] = { { ids = { "o182203" }, first = "thegreenhillsofstranglet", pages = { "LAS VERDES COLINAS DE TUERCESPINA\n\npor Hemet Decautela", "Nuestro primer día fue todo lo bien que se puede esperar que vayan los primeros días. La mayor parte del tiempo nos preocupamos de realizar los preparativos necesarios para establecer un campamento base. Encontré un lugar ideal, junto a la ensenada de un río de agua dulce. A juzgar por los viejos y abandonados muelles que hay cerca, este emplazamiento estuvo habitado hace algún tiempo. Por lo que respecta a los habitantes primitivos, solo el tiempo puede contar esa historia.", "Para esta expedición he reunido a Ajeck Rouack y a Sir S. J. Erlgadin, junto con mi sirviente de confianza, Barnil Jarropetra. Libré muchas batallas al lado del padre de Ajeck en defensa de la Alianza. Verla crecida es bastante especial. Su padre la instruyó bien en las artes de las armas. Su habilidad con el arco me hace preguntarme si corre sangre élfica por esas venas.", "Sir S. J. Erlgadin proviene de la aristocracia humana. Su padre, el conde Erlgadin, era célebre por su generosidad. Fue el conde quien presionó por una mejora en las condiciones de trabajo de la Hermandad de los Albañiles durante la restauración de Ventormenta después de la Segunda Gran Guerra.", "En los años siguientes, después de que Ventormenta traicionara al Gremio de Canteros, sir Erlgadin se amargó por el papel de los nobles en el reino. Ya no deseaba mantener la posición que el linaje de su padre le había otorgado en la Casa de Nobles.\n\nPero me desvío. Esta historia no pretende ser un tratado político ni una biografía. Es el relato de mis experiencias de caza mayor en las verdes colinas de Tuercespina...", "Nos levantamos al amanecer. Barnil empezó a preparar el desayuno. Advertí que Ajeck estaba un poco distraída. La caminata del día prometía ser larga y nos esperaban peligrosos episodios de caza. Cualquier descuido podía ponernos en una situación difícil. No obstante, Ajeck parecía incapaz de desviar su mirada de Barnil, que estaba de pie frente al río, limpiando su equipo.", "Justo cuando estaba a punto de cuestionar la falta de interés de Ajeck en la estrategia de caza del día, alargó la mano hacia su arco, lo tensó con una flecha y la soltó justo hacia el pobre Barnil. Pero no era a Barnil a quien Ajeck disparaba, pues, cuando Barnil se echó a un lado boquiabierto, un gran crocolisco de río flotó a la superficie con la flecha de Ajeck perfectamente colocada entre sus grandes ojos.", "Partimos al oeste, por la espesura enmarañada de la jungla. Avanzamos con pasos lentos y deliberados entre el follaje denso en busca de presas. La mañana pasó en un silencio frustrante. Nada se movía en la vega, ni una brisa. Por la tarde, la expedición estaba inquieta. Barnil ya no andaba con los pasos cautelosos de un depredador que sigue a su presa. Avanzaba torpemente por el sendero, pisando a menudo con ruido hojas secas y ramas caídas.", "Durante semejante tropiezo, Erlgadin posó su mano pesadamente sobre el hombro de Barnil. Ajeck y yo apenas advertimos la escena, suponiendo que el hombre solo estaba dando una merecida reprimenda a Barnil por su descuido. No obstante, Erlgadin hizo un gesto lento con la cabeza en dirección a un árbol caído. Desde allí nos acechaban dos ojos negros penetrantes justo encima de un par de afilados colmillos.", "La bestia era un tigre macho de Tuercespina. Antes de que pudiera amartillar el rifle, Erlgadin levantó la ballesta y disparó en dirección al animal. El virote dejó su marca y sorprendió a la bestia con fuerza en el costado izquierdo. El tigre hizo un intento en vano por huir, pero la herida era demasiado grave. La bestia fue dando traspiés durante varios trágicos segundos, hasta que Barnil lo remató lanzando un hacha.", "La matanza provocó un ánimo festivo en la expedición. Barnil sirvió aguamiel para disfrute de todos. Pero nuestros festejos fueron efímeros. Mientras preparábamos el cadáver para transportarlo de vuelta al campamento base, un rugido espantoso nos cogió desprevenidos a todos. En todos mis años nunca he oído nada que helara la sangre de tal modo.", "En un precipicio rocoso, recortado contra el sol poniente, distinguí al mayor felino de presa que he visto jamás. Logré disparar torpemente con mi rifle, pero el felino no se movió. Volvió a gruñir, esta vez más fuerte, y desapareció.\n\nRecogimos nuestras cosas y regresamos al campamento en silencio solemne.", "Había prometido a la expedición que pasaríamos el día siguiente cazando panteras, ya que sus pieles son muy valoradas en Azeroth. Esta demanda se debe a que todos los cazadores, tramperos y comerciantes de pieles arriesgan valientemente su vida en nombre de la Alianza.", "Ajeck y Sir Erlgadin estaban ansiosos por aprender a cazar eficazmente con un rifle de los enanos. Hice que los dos humanos dejaran sus primitivas armas en el campamento base. Barnil y yo los equipamos con algunas de las mejores armas de fuego de Forjaz.", "Ese día nos aventuramos al sur, siguiendo algunos rastros recientes de pantera. Pronto llegamos a un barranco que se cruzaba por un enorme puente colgante. No pude evitar pensar en la descriptiva obra de Brann sobre aquella región cuando vi aquella maravilla de la ingeniería. Se suponía tan a menudo que los trols nativos eran una raza primitiva e inculta, pero, mientras observaba fijamente la artesanía maestra del puente, pude reconocer la habilidad con la que los albañiles trols superaron la hazaña, aparentemente imposible.", "Al poco tiempo, Ajeck rastreó a la pantera en dirección al sudoeste. Anduvimos en silencio, con las armas preparadas, anticipándonos a nuestra presa. Un chasquido de ramas en un bosquecillo cercano llamó nuestra atención de inmediato. Allí había algo. Una mirada seria a Barnil bastó para transmitirle mis pensamientos. Barnil bajó su rifle lentamente. Esta presa no era para nosotros, sino para nuestros compañeros humanos. Innumerables panteras habían perdido la vida al enfrentarse a nuestros humeantes cañones. Esta presa era para los humanos.", "Tanto Ajeck como Sir Erlgadin se mantuvieron erguidos, con las armas al nivel de la hirsuta maleza que había bajo unos árboles que se mecían de un lado a otro. El sol del mediodía ardía con fuerza sobre nosotros. Una lenta gota de sudor rodó por la sien de Erlgadin, al tiempo que retiraba el gatillo. Tras el chasquido, el follaje exuberante se abrió en dos y una pantera negra, espécimen hermoso, saltó veloz sobre la llanura.", "Los humanos apuntaron a la pantera mientras corría por la linde de los árboles. Los cañones de sus armas se movían juntos, perfectamente paralelos. Barnil me lanzó una mirada apremiante, pero negué con la cabeza. Esta cacería era de los humanos, no de Barnil ni mía. Erlgadin disparó con un estruendo y falló por completo. Al parecer no estaba preparado para el violento retroceso del rifle.", "El arma dio un fuerte salto hacia atrás entre sus brazos. El cañón se desvió y subió por debajo del rifle de Ajeck. Ella había elegido justo ese instante para apretar el gatillo. El rifle, ahora desviado torpemente hacia los árboles, sonó con un estruendo inconfundible. Una bandada salió de las copas gritando y se dispersó en todas direcciones. Del árbol subió una nube de humo. Miramos asombrados cómo una rama enorme caía de lleno sobre la pantera que huía y le rompía el espinazo", "Unas semanas después, nuestras reservas de piel de pantera y tigre crecieron ostensiblemente. Decidí que era hora de que la expedición cambiara de objetivo: Raptores.\n\nLos humanos, valorando la instrucción que Barnil y yo les proporcionamos, decidieron abstenerse de cazar con armas de fuego. Ajeck estaba mucho más cómoda con un arco de cuerda fina, mientras que Sir Erlgadin nunca abandonaba el campamento sin su maciza ballesta.", "Nos fuimos al alba en dirección al sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación ante la posibilidad de encontrarnos con miembros de la tribu Sangrapellejo. Recordé a Barnil que los Sangrapellejo estaban ocupados intentando destruir a su enemigo tribal, los Machacacráneos. De más está decir que Barnil no estaba en absoluto tranquilo. Yo, por mi parte, tenía el rifle cargado, un saco lleno de pólvora y tres cazadores infalibles que me acompañaban para aplacar mis preocupaciones ante una posible emboscada.", "Una vez, en el campo de batalla, tuve delante a un inferno altísimo, con el ejército de la Legión Ardiente avanzando desde todas partes. Una banda de trols revoltosos parece tan inofensiva como una liebre en las colinas de Dun Morogh.\n\nPasamos por las ruinas de Tkashi sin contratiempos, lo que tranquilizó a Barnil en gran medida. El grupo avanzó hacia el oeste, en dirección al Mare Magnum, bordeando las ruinas de Zul'Kunda, situadas al sur. Al subir por los altos acantilados, divisamos al primer raptor.", "La bestia ni siquiera detectó nuestra presencia. De hecho, el único saludo que recibió por parte de la expedición fue una bala en medio de la frente. Sir Erlgadin lanzó un grito de alegría, mientras Ajeck asentía y me miraba, haciendo un gesto de entusiasta aprobación. Revolví mi mochila en busca de mi pipa, esperando celebrar la hazaña con el humo de la victoria. Barnil empezó a correr por la cuesta para recuperar el cadáver del raptor. Miré a la bestia abatida con la satisfacción que produce una caza importante.", "Sin embargo, no pude disfrutar de la victoria del cazador por mucho tiempo, pues al contemplar el horizonte, numerosas siluetas aparecieron en la cresta de la colina, justo encima del pobre Barnil.\n\n*¡Huye, Barnil!*, grité. Ajeck, Sir Erlgadin y yo lanzamos una descarga de balas y flechas por encima de Barnil, directo sobre los raptores. Alguien soltó la presa en medio de la confusión.", "Nuestros disparos apresurados bastaron para permitir la huida de Barnil. Bajó como pudo de la colina y volvió al grupo. Nos internamos a toda prisa en la jungla, con una manada de feroces raptores Colazote siguiendo cada movimiento.\n\nLos cazadores eran ahora los cazados.", "Conduje a la expedición hasta el mar, con el fin de que la costa nos protegiera de los raptores. Con nuestro apresuramiento, nos habíamos desviado demasiado al norte, a una altitud peligrosamente elevada. Nos habíamos equivocado. Fue culpa mía. Nos detuvimos delante de un escarpado acantilado, con los raptores justo detrás de nosotros.", "Avancé lentamente con el arma levantada. Había conducido a estos valientes cazadores a su fin. Tenía que morir defendiéndolos. Los raptores colazote son particularmente feroces, conocidos por ser unos sanguinarios implacables. Eran muchos más que nosotros. Pero si hubiera dejado que nos mataran a mis camaradas y a mí, sin antes derramar parte de su propia sangre, no me lo habría perdonado.", "Ajeck y Sir Erlgadin dispusieron sus armas, flanqueándome a cada lado, de espaldas al mar. Barnil dejó escapar un suspiro derrotado y blandió su hacha. Los colazotes estaban casi sobre nosotros. Su firme zancada se había hecho más lenta. Ahora acechaban a su presa, pues sabían que nos tenían atrapados.", "Entonces ocurrió algo milagroso. Desde donde estábamos escuchamos el inconfundible y aterrador rugido del gran tigre blanco. A pesar de ser numerosos, los raptores dieron media vuelta y se dispersaron. Solo vimos el breve destello blanco de un tigre que salió disparado junto a nosotros, abalanzándose sobre uno de los raptores. No fue necesario dar ninguna orden. Los cuatro miembros de la expedición sabíamos que era el momento de salir corriendo.", "Corrimos sin frenar hasta el campamento base. Más tarde, aquella noche, nos sentamos en silencio alrededor del fuego, sabiendo que un giro extraño del destino nos había salvado la vida. Tales son los riesgos de la caza mayor. Jugamos con el destino al repartirlo. Pero cada uno de nosotros afrontará alguna vez sus dientes afilados. Este enano se alegra de que ese momento no llegara en las verdes colinas de Tuercespina.\n\n--Fin--" } } },
    ["The Guardians of Tirisfal"] = { { ids = { "o175735" }, first = "withtheabsenceoftrollsin", pages = { "Sin la presencia de los trols en las tierras del norte, los elfos de Quel'Thalas centraron sus esfuerzos en reconstruir su gloriosa tierra. Los ejércitos victoriosos de Arathor volvieron a casa, en las tierras del sur de Strom.", "La sociedad humana de Arathor creció y prosperó, no obstante Thoradin, temeroso de que su reino se desintegrase al adquirir un tamaño demasiado grande, afirmó que Strom sería el centro del imperio de Arathor. Tras muchos años de paz y crecimiento económico, el poderoso Thoradin murió en edad avanzada, ofreciendo a las jóvenes generaciones de Arathor libertad para expandir el imperio más allá de las fronteras de Strom.", "Los cien magos originales, que fueron instruidos en la magia por los elfos, ampliaron sus poderes y estudiaron con mayor detenimiento las disciplinas místicas de los hechizos. Estos magos, inicialmente escogidos por su fuerza de voluntad y nobleza de espíritu, siempre habían practicado su magia con cuidado y responsabilidad. No obstante, transmitieron sus secretos y poderes a una nueva generación que no tenía idea de los rigores de la guerra o del principio de moderación.", "Estos jóvenes magos empezaron a practicar la magia para darle un uso personal, sin tener en cuenta su responsabilidad hacia sus congéneres.", "A medida que el imperio creció y adquirió nuevas tierras, los jóvenes magos también se establecieron en las tierras del sur. Mediante el uso de sus poderes místicos, los magos protegían a sus hermanos de las criaturas salvajes de la tierra e hicieron posible la construcción de nuevas ciudades estado en medio de la jungla. No obstante, a medida que aumentaba su poder, los magos se hicieron cada vez más engreídos y se aislaron del resto de la sociedad.", "La segunda ciudad estado de Arathor, Dalaran, fue fundada en las tierras del norte de Strom. Muchos magos noveles abandonaron los confines de Strom y viajaron a Dalaran, en donde esperaban usar sus poderes con mayor libertad. Así, emplearon sus habilidades para construir las cimas encantadas de Dalaran y centrarse en la continuación de sus estudios.", "Los ciudadanos de Dalaran toleraron los esfuerzos de los magos y consolidaron una economía ágil bajo la protección de sus defensores magos. Sin embargo, a medida que aumentaba el número de magos que ponían en práctica sus artes, el manto de realidad que rodeaba Dalaran empezó a resquebrajarse.", "Los siniestros agentes de la Legión Ardiente, que habían sido desterrados durante la desaparición del Pozo de la Eternidad, se interesaron nuevamente por el planeta, gracias a la atención que en ellos despertaron los hechizos de los magos de Dalaran. Si bien estos demonios relativamente débiles no manifestaban su poder, sí sembraban la confusión y el caos en las calles de Dalaran.", "La mayoría de estos encuentros demoníacos eran acontecimientos aislados, de manera que los magócratas en el poder hicieron lo que pudieron para mantener estas ceremonias en secreto. Los magos más poderosos fueron enviados a capturar a los escurridizos demonios, pero muchas veces se vieron superados por los solitarios agentes de la imponente Legión.", "Transcurridos unos cuantos meses, los supersticiosos campesinos empezaron a sospechar que sus hechiceros gobernantes les estaban ocultando algo terrible. Rumores de revolución empezaron a extenderse por las calles de Dalaran, al tiempo que los ciudadanos paranoicos cuestionaban los motivos y las prácticas de los magos a quienes habían admirado en el pasado. Los magócratas, temiendo que los campesinos se levantarían y que Strom actuaría en su contra, acudieron al único grupo que consideraron capaz de comprender su particular problema: los elfos.", "Tras conocer las actividades demoníacas de los magócratas en Dalaran, los elfos rápidamente enviaron a sus zahoríes más poderosos hacia tierras humanas. Los zahoríes élficos estudiaron las corrientes energéticas que fluían en Dalaran y realizaron informes detallados sobre toda la actividad demoníaca que encontraron. Concluyeron que, si bien solo había unos cuantos demonios dispersos por aquel territorio, la Legión sí constituía una verdadera amenaza si los humanos continuaban utilizando poderes mágicos.", "El Consejo de Lunargenta, que gobernaba sobre los elfos de Quel'Thalas, firmó un pacto secreto con los señores magócratas de Dalaran. Los elfos contaron a los magócratas la historia del antiguo continente de Kalimdor y la Legión Ardiente, historia que aún amenazaba al planeta. Advirtieron a los humanos que, siempre que utilizaran la magia, debían proteger a sus ciudadanos de los agentes malvados de la Legión.", "Los magócratas propusieron la idea de asignar poderes a un solo campeón mortal para librar una guerra secreta interminable contra la Legión. Resaltaron que la mayor parte de los humanos no debía saber nada acerca de los Guardianes o de la amenaza de la Legión, para evitar disturbios causados por el miedo y la paranoia. Los elfos aceptaron la propuesta y fundaron una sociedad secreta para supervisar la elección del Guardián, ayudando a contener el aumento del caos en el mundo.", "La sociedad mantuvo sus reuniones secretas en los Claros de Tirisfal, donde los altos elfos se habían establecido por primera vez en Lordaeron. Así, llamaron a su secta secreta los Guardianes de Tirisfal. Los campeones mortales que fueron elegidos por los Guardianes recibieron increíbles poderes élficos y humanos. Si bien solo podía existir un Guardián cada vez, su poder era tan inconmensurable que podía responder a los ataques de la Legión sin ayuda de nadie en cualquier parte del planeta.", "El poder del Guardián era tal, que solo el Consejo de Tirisfal podía elegir a los potenciales sucesores. Cada vez que un Guardián envejecía demasiado, o se cansaba de guardar los secretos de guerra contra el caos, el Consejo elegía a un nuevo campeón y, bajo un estricto control, transmitían formalmente los poderes del Guardián a su nuevo agente.", "Con el transcurso de las generaciones, los Guardianes defendieron a la humanidad de la invisible amenaza de la Legión Ardiente por todo el territorio de Arathor y Quel'Thalas. Arathor creció y prosperó, al tiempo que el uso de la magia se extendió por todo el imperio. Mientras tanto, los Guardianes vigilaban cuidadosamente cualquier señal de actividad demoníaca." } } },
    ["The Horde's Hellscream"] = { { ids = { "i20010" }, first = "hisnamewillnotdiehissacr", pages = { "Su nombre nunca morirá.\nSu sacrificio siempre\nnos mostrará el camino.\n\nUna vez rotas las cadenas\n\nque estrangulaban nuestro honor,\n\nya no podrán esclavizarnos.", "¿Puedes oír ese grito?\nEs un grito de batalla de la Horda:\n¡Victoria o muerte!\n\nDebemos recordar\n\nsu fuerza cara a la muerte.\nSu sueño ahora se ha hecho realidad.", "¡Peligros por todas partes!\nLos enemigos intentan\nencadenarnos de nuevo.\n\nCuando luchemos, pensad en\naquel que sabía lo que había que hacer.\n¡Grito Infernal por siempre!" } } },
    ["The Invasion of Draenor"] = { { ids = { "o175747" }, first = "asthefiresofthesecondwar", pages = { "Al apagarse los fuegos de la Segunda Guerra, la Alianza tomó medidas enérgicas para contener la amenaza orca. En el sur de Lordaeron se construyeron grandes campos de internamiento para los orcos cautivos. Vigilados por paladines y soldados veteranos de la Alianza, los campos resultaron un gran éxito.", "Aunque los orcos cautivos estaban tensos y deseaban volver a combatir, los distintos guardianes de los campos, establecidos en la antigua fortaleza prisión de Durnholde, conservaron la paz y una firme apariencia de orden.", "Sin embargo, en el mundo infernal de Draenor, un nuevo ejército orco se preparaba para atacar a la desprevenida Alianza. Ner'zhul, antiguo mentor de Gul'dan, reunió a los clanes restantes bajo su estandarte oscuro. Con ayuda del clan Sombraluna, el viejo chamán planeaba abrir portales en Draenor que llevaran a la Horda a mundos nuevos e intactos.", "Para alimentar los nuevos portales necesitaba varios artefactos encantados de Azeroth. Para conseguirlos, Ner'zhul reabrió el Portal Oscuro y envió a sus voraces sirvientes a la carga por él.", "La nueva Horda, dirigida por jefes veteranos como Grom Grito Infernal y Kilrogg Mortojo, del clan Foso Sangrante, sorprendió a las defensas de la Alianza y arrasó la comarca. Bajo el mando preciso de Ner'zhul, los orcos reunieron rápidamente los artefactos necesarios y huyeron de vuelta a la seguridad de Draenor.", "El rey Terenas de Lordaeron, convencido de que los orcos preparaban otra invasión de Azeroth, reunió a sus lugartenientes de mayor confianza. Ordenó al general Turalyon y al archimago Khadgar dirigir una expedición a través del Portal Oscuro para acabar de una vez con la amenaza orca. Sus fuerzas entraron en Draenor y se enfrentaron repetidamente a los clanes de Ner'zhul en la devastada Península del Fuego Infernal.", "Ni siquiera con ayuda de la alta elfa Alleria Brisaveloz, el enano Kurdran Martillo Salvaje y el soldado veterano Danath Aterratrols pudo Khadgar impedir que Ner'zhul abriera sus portales a otros mundos.", "Ner'zhul abrió por fin los portales, pero no previó el terrible precio. Sus enormes energías empezaron a desgarrar el tejido mismo de Draenor. Mientras las fuerzas de Turalyon luchaban desesperadamente por volver a Azeroth, Draenor comenzó a derrumbarse sobre sí mismo. Grom Grito Infernal y Kilrogg Mortojo, al comprender que los planes demenciales de Ner'zhul condenarían a toda su raza, reunieron a los orcos restantes y escaparon a la seguridad relativa de Azeroth.", "En Draenor, Turalyon y Khadgar acordaron hacer el sacrificio definitivo: destruir el Portal Oscuro desde su lado. Aunque les costara la vida y la de sus compañeros, sabían que era la única forma de asegurar la supervivencia de Azeroth. Mientras Grito Infernal y Mortojo se abrían paso entre las filas humanas en busca desesperada de libertad, el Portal Oscuro estalló a sus espaldas. Para ellos y los orcos que quedaban en Azeroth ya no habría vuelta atrás.", "Ner'zhul y su fiel clan Sombraluna cruzaron el mayor de los portales recién creados mientras enormes erupciones volcánicas empezaban a romper los continentes de Draenor. Los mares ardientes se alzaron y agitaron el paisaje destrozado, hasta que el mundo torturado fue consumido en una explosión apocalíptica gigantesca." } } },
    ["The Kaldorei and the Well of Eternity"] = { { ids = { "o21583" }, first = "tenthousandyearsbeforeth", pages = { "Diez mil años antes de que los orcos y los humanos se enfrentaran en la Primera Guerra, el mundo de Azeroth era un vasto continente rodeado por mares infinitos. Aquella masa de tierra, conocida como Kalimdor, albergaba numerosas razas y criaturas dispares, pugnando por sobrevivir entre los salvajes elementos del mundo naciente. En el centro del continente oscuro había un lago misterioso de energías incandescentes.", "El lago, conocido posteriormente como el Pozo de la Eternidad, fue el corazón de la magia y de los poderes naturales del mundo: Absorbiendo la energía de la Gran Oscuridad infinita del más allá, el Pozo actuaba como fuente mística, lanzando sus poderosos flujos por todo el espacio, diseminando la vida en todas sus formas, variadas y sorprendentes.\n\nA través del tiempo, una tribu primitiva de humanoides nocturnos llegó cautelosamente hasta los confines del fascinante lago encantado.", "Los nómadas humanoides ferales, atraídos por las extrañas energías del Pozo, fabricaron rudimentarias casas junto a sus serenas orillas. Con el paso del tiempo, el poder cósmico del Pozo afectó a la extraña tribu, haciéndola fuerte, sabia y prácticamente inmortal. La tribu adoptó el nombre de Kaldorei, que en su lengua significaba \"hijos de las estrellas\". Para celebrar el nacimiento de su sociedad, construyeron magníficas estructuras y templos en la periferia del lago.", "Los kaldorei, o elfos de la noche, tal como se les conoció posteriormente, adoraban a la diosa de la luna Elune, convencidos de que, durante el día, dormía en las refulgentes profundidades del Pozo. Los antiguos sacerdotes y profetas de los elfos de la noche estudiaron el Pozo con insaciable curiosidad, dedicándose a desentrañar sus insondables secretos y poderes. A medida que su sociedad prosperó, los elfos de la noche exploraron las\n tierras de Kalimdor y descubrieron a sus innumerables moradores.", "Las únicas criaturas que les dieron tregua fueron los antiguos y poderosos dragones. Aunque\nlas enormes bestias serpenteantes solían recluirse, ayudaban en gran medida a proteger las tierras conocidas de potenciales enemigos. Los elfos de la noche creían que los dragones se consideraban los protectores del mundo y que era mejor dejarlos solos con sus secretos.", "Con el tiempo, la curiosidad de los elfos de la noche les condujo a conocer y entablar amistad con diversos seres poderosos, entre los cuales estaba Cenario, un semidiós de los bosques primigenios. El benévolo Cenario simpatizaba con los inquisitivos elfos de la noche y pasaba largas horas instruyéndolos en el conocimiento del mundo natural. Los serenos kaldorei desarrollaron una fuerte empatía por los bosques vivientes de Kalimdor y se deleitaban en el armonioso equilibrio de la naturaleza.", "Sin embargo, con el paso del tiempo, que parecía eterno, la civilización de los elfos de la noche se expandió territorial y culturalmente. Sus templos, caminos y viviendas poblaban la totalidad del continente oscuro. Azshara, la bella e inteligente reina de los elfos de la noche, construyó un magnífico e inmenso palacio a la orilla del Pozo, en el que habitaba su servidumbre selecta, rodeada de fastuosas riquezas.", "La selecta servidumbre, llamada Quel'dorei o nobleza, estaba al servicio de la reina y se consideraba superior al resto de sus hermanos de casta inferior. Si bien la reina Azshara era amada por todos sus súbditos, la nobleza era odiada en secreto por las masas envidiosas.\n\nAzshara, que compartía con los sacerdotes la curiosidad por conocer los secretos del Pozo de la Eternidad, ordenó a la educada nobleza que desentrañara sus misterios y los difundieran por todas partes.", "Los nobles se enfrascaron en su trabajo y estudiaron el Pozo incansablemente. Con el tiempo, desarrollaron la habilidad de manejar y controlar las energías cósmicas del Pozo. A medida que sus insensatos experimentos avanzaron, los miembros de la nobleza advirtieron que podían usar sus nuevos poderes para crear o destruir a voluntad. Los desafortunados nobles se tropezaron con la magia primitiva y habían resuelto dominarla.", "Si bien sabían que, si se manipulaba irresponsablemente, la magia era inherentemente peligrosa, Azshara y sus nobles empezaron a practicar sus hechizos con imprudente abandono. Cenario y muchos de los viejos y eruditos elfos de la noche advirtieron que jugar con las volátiles artes del encantamiento solo podría traer la ruina. Pero Azshara y sus seguidores continuaron extendiendo tenazmente sus incipientes poderes.", "A medida que sus poderes crecieron, se produjo un cambio evidente en Azshara y los nobles. Los altivos y distantes aristócratas se volvieron cada vez más insensibles y crueles con los demás elfos de la noche. Un oscuro y perturbador manto envolvió la otrora fascinante belleza de Azshara. Se distanció de sus súbditos más cercanos y se negó a tratar con nadie que no fuera sus fieles sacerdotes aristócratas.", "Un joven y audaz estudiante llamado Furion Tempestira, que había dedicado gran parte del tiempo al estudio de los efectos del Pozo, empezó a sospechar que un terrible poder estaba corrompiendo a los nobles y a su amada reina. Si bien consideraba inconcebible el mal que los acechaba, sabía que las vidas de los elfos de la noche pronto cambiarían para siempre..." } } },
    ["The Last Guardian"] = { { ids = { "o175740" }, first = "theguardianaegwynngrewpo", pages = { "Con el paso de los años, la guardiana Aegwynn se hizo cada vez más poderosa y utilizó las energías de Tirisfal para extender con mucho el alcance de su vida. Creyendo erróneamente que había derrotado a Sargeras para bien, continuó salvaguardando el mundo de los esbirros del rey de los demonios durante aproximadamente novecientos años. Sin embargo, el Consejo de Tirisfal decretó que su administración había llegado a su fin.", "El consejo ordenó a Aegwynn que regresara a Dalaran, de manera que pudieran elegir un nuevo sucesor para la guardiana. Aun así, Aegwynn, desconfiando del consejo, decidió escoger a un sucesor por sí misma.", "La orgullosa Aegwynn decidió traer un hijo al mundo al que transferir su poder. No tenía intención alguna de permitir que la orden de Tirisfal manipulara a su sucesor de la misma forma que intentaron manipularla a ella. Dirigiéndose a la nación sureña de Azeroth, Aegwynn encontró al hombre perfecto para convertirlo en padre de su hijo: un hábil mago humano conocido como Nielas Aran.", "Aran era el mago y consejero de la corte del rey de Azeroth. Aegwynn sedujo al mago y tuvo un hijo de él. La afinidad natural hacia la magia de Nielas habría de influir profundamente en el niño aún no nacido y terminaron por definir los trágicos pasos que posteriormente seguiría el niño. Asimismo, el poder de Tirisfal pasó al niño, si bien no fue consciente de ello hasta alcanzar la madurez física.", "Pasó el tiempo y Aegwynn dio a luz a su hijo en un bosquecillo apartado. Dándole el nombre de Medivh, que significa \"guardián de los secretos\" en la lengua de los elfos nobles, Aegwynn creyó que cuando el niño creciera, se convertiría en el próximo guardián. Desafortunadamente, el espíritu maligno de Sargeras, que se ocultaba en ella, tomó posesión del indefenso niño mientras permanecía en el seno materno. Aegwynn no tenía la menor idea de que el próximo guardián del mundo ya estaba poseído por su mayor enemigo.", "Habiéndose asegurado de que su hijo estaba sano, Aegwynn envió al joven Medivh a la corte de Azeroth y lo dejó allí para que creciera junto a su padre mortal y a su gente. Luego, se internó en la jungla y se preparó para acudir a la cita con el más allá. Medivh creció hasta convertirse en un joven fuerte y no tenía idea del potencial que implicaba su derecho de nacimiento en Tirisfal.", "Sargeras esperó el momento oportuno, hasta que los poderes del joven se manifestaron por sí solos. Cuando Medivh alcanzó la adolescencia, se convirtió en un personaje muy popular en Azeroth debido a sus poderes mágicos y, a menudo, corrió aventuras junto con sus dos amigos: Llane, príncipe de Azeroth, y Anduin Lothar, uno de los últimos descendientes de la línea de sangre arathi. Los tres muchachos no hacían más que meterse constantemente en líos, pero eran muy apreciados por el pueblo.", "Cuando Medivh cumplió la edad de catorce años, el poder cósmico que residía en él despertó y chocó con el espíritu invasor de Sargeras que acechaba en su alma. Medivh entró en un estado catatónico que se prolongó durante varios años.", "Cuando despertó de su estado de coma, cayó en la cuenta de que se había convertido en un adulto y vio que sus amigos eran los regentes de Azeroth. Si bien deseaba utilizar sus increíbles poderes para proteger la tierra que consideraba su casa, el oscuro espíritu de Sargeras tergiversó sus propósitos y emociones, conduciéndole a un final insidioso.", "Sargeras se rebeló en el corazón de Medivh, ya que sabía que sus planes para una invasión del mundo estaban a punto de materializarse y el último guardián del mundo los llevaría a buen término." } } },
    ["The Lich King Triumphant"] = { { ids = { "o175762" }, first = "evenweakenedashewasartha", pages = { "A pesar de su debilidad, Arthas finalmente se mostró más hábil que Illidan y llegó primero hasta el Trono de Hielo. Utilizando su hojarruna Agonía de Escarcha, Arthas destrozó la prisión helada del Rey Exánime y, de esta manera, liberó el yelmo encantado y la coraza de Ner'zhul.", "Arthas se colocó el yelmo de inimaginable poder sobre su cabeza y se convirtió en el nuevo Rey Exánime. Los espíritus de Ner'zhul y Arthas se fundieron en un único ser poderoso, tal como Ner'zhul había planeado. Illidan y sus tropas fueron obligados a huir hacia Terrallende, mientras que Arthas se convirtió en una de las entidades más poderosas que el mundo jamás había conocido.", "Actualmente, Arthas, el nuevo e inmortal Rey Exánime, reside en Rasganorte. Se rumorea que está reconstruyendo la Ciudadela de la Corona de Hielo. Su fiel lugarteniente, Kel'Thuzad, dirige la Plaga en las Tierras de la Peste. Sylvanas y sus rebeldes Renegados solo conservan los Claros de Tirisfal, una pequeña parte del reino destrozado por la guerra." } } },
    ["The New Horde"] = { { ids = { "o175752" }, first = "thechiefwardenoftheinter", pages = { "El guardián jefe de los campos de internamiento, Aedelas Lodonegro, vigilaba a los orcos cautivos desde su prisión-fortaleza Durnholde. Un orco en particular había llamado siempre su atención: el niño huérfano que había encontrado aproximadamente hacía dieciocho años. Lodonegro se ocupó de que el joven, aunque esclavo, tuviera un trato de favor y lo llamó Thrall. Lodonegro enseñó a los orcos táctica, filosofía y técnicas de combate. Incluso, Thrall fue entrenado como gladiador. Durante todo el tiempo, el guardián corrupto trató de moldear al orco, convirtiéndolo en un arma.", "A pesar de la dureza de su educación, el joven Thrall se convirtió en un orco fuerte y mentalmente ágil, pero en su corazón sabía que la vida de esclavo no era para él. Cuando alcanzó la madurez, aprendió la historia de su pueblo, los orcos, a quienes nunca había encontrado: tras su derrota, casi todos habían sido confinados en campos de internamiento. Había rumores de que Martillo Maldito, el líder de los orcos, había escapado de Lordaeron y se había ocultado. Solo un solitario clan aún actuaba en secreto, intentando evitar la atenta mirada de la Alianza.", "El resuelto pero aún inexperto Thrall decidió escapar de la fortaleza de Lodonegro y marchar en busca de otros de su clase. Durante sus viajes, Thrall visitó los campos de internamiento y vio que su raza, otrora poderosa, estaba extrañamente intimidada y aletargada. Al no encontrar a los orgullosos guerreros que esperaba descubrir, Thrall marchó en busca del último jefe orco que aún no había sido derrotado, Grom Grito Infernal.", "Perseguido sin descanso por los humanos, Grito Infernal nunca perdió el insaciable apetito de la Horda por la lucha. Con la única ayuda de su devoto clan Grito de Guerra, Grito Infernal continuó librando una guerra subterránea contra la opresión de su sitiado pueblo. Desafortunadamente, Grito Infernal nunca encontró un medio de liberar a los orcos capturados de su aletargamiento. El impresionable Thrall, inspirado por el idealismo de Grito Infernal, desarrolló una fuerte empatía por la Horda y sus tradiciones guerreras.", "Buscando la verdad de sus propios orígenes, Thrall viajó hacia el norte para localizar al legendario clan Lobo Gélido. Thrall supo que Gul'dan se había separado de los Lobo Gélido durante el comienzo de la Primera Guerra. Asimismo, descubrió que era el hijo y heredero del héroe orco Durotan, el verdadero jefe de los Lobo Gélido que había sido asesinado en los bosques hacía veinte años.", "Bajo la tutela del venerable chamán Drek'Thar, Thrall estudió la antigua cultura chamánica de su pueblo, que había sido olvidada bajo la égida maligna de Gul'dan. Con el tiempo, Thrall se convirtió en un poderoso chamán y ocupó su lugar por derecho como jefe de los Lobo Gélido exiliados. Gracias a los poderes que le conferían los propios elementos y decidido a encontrar su propio destino, Thrall partió con el propósito de liberar a los clanes cautivos y librar a su raza de la corrupción demoníaca.", "En el transcurso de sus viajes, Thrall encontró al viejo jefe guerrero Orgrim Martillo Maldito, que había estado viviendo como un ermitaño durante muchos años. Martillo Maldito, que había sido un amigo muy próximo del padre de Thrall, decidió seguir al joven y visionario orco y ayudarle en su propósito de liberar a los clanes cautivos. Con el apoyo de muchos de los jefes veteranos, finalmente Thrall alcanzó el éxito revitalizando a la Horda y proporcionando a su pueblo una nueva identidad espiritual.", "Para simbolizar el renacimiento de su pueblo, Thrall regresó a la fortaleza de Lodonegro en Durnholde y puso fin, de una vez por todas, a los planes de su antiguo maestro, sitiando los campos de internamiento. Esta victoria no fue gratuita: durante el proceso de liberación de un campo, Martillo Maldito cayó en la batalla.", "Thrall recogió el legendario martillo de guerra del afamado Martillo Maldito y se puso su armadura negra para convertirse en el nuevo jefe guerrero de la Horda. En el transcurso de los meses siguientes, la pequeña pero volátil Horda de Thrall liberó los campos de internamiento y frustró los mejores esfuerzos de la Alianza para contrarrestar sus inteligentes estrategias. Alentado por su mejor amigo y mentor, Grom Grito Infernal, Thrall trabajó para asegurarse de que su pueblo nunca volviera a ser esclavizado." } } },
    ["The Old Gods and the Ordering of Azeroth"] = { { ids = { "o175725" }, first = "unawareofsargerasmission", pages = { "Desconociendo el empeño de Sargeras en destruir sus grandes hazañas, los titanes continuaron viajando de un planeta a otro, ordenando y sembrando de paz los sitios a los que iban. Durante el trayecto, hallaron un pequeño planeta cuyos habitantes llamaron Azeroth.", "Cuando los titanes iniciaron la exploración del universo primigenio, encontraron a su paso numerosos enemigos elementales. Estos elementales, que veneraban a una raza de seres de insondable maldad conocida como los antiguos dioses, juraron detener a los titanes y proteger su entorno de la presencia metálica de los invasores.", "El Panteón, inquieto por las inclinaciones malignas de los antiguos dioses, declararon la guerra a los elementales y a sus maestros oscuros. Los ejércitos de los antiguos dioses actuaban bajo las órdenes de los tenientes elementales más poderosos: Ragnaros el Señor de Fuego, Therazane la Madre Pétrea, Al'Akir el Señor del Viento y Neptulon el Cazamareas.", "Sus caóticas fuerzas rugieron por todo el universo y se enfrentaron a los colosales titanes. Aunque los elementales tenían un poder más allá de toda comprensión, sus fuerzas conjuntas no podían detener a los invencibles titanes. Uno a uno, los señores elementales cayeron y sus fuerzas se dispersaron.", "Los miembros del Panteón arrasaron los reductos de los antiguos dioses y encadenaron a los cinco dioses malignos en el subsuelo del planeta. Sin el poder de los antiguos dioses para mantener sus furiosos espíritus atados al mundo físico, los elementales fueron desterrados a un plano abisal, donde lucharían entre sí por toda la eternidad. Tras la partida de los elementales, la naturaleza se apaciguó y en el mundo reinó una pacífica armonía. Al acabar con la amenaza, los titanes se pusieron manos a la obra.", "Así, otorgaron poderes a numerosas razas para que les ayudaran a construir un nuevo mundo. Para ayudarles a cavar las insondables cavernas subterráneas, los titanes crearon a los terráneos enanoides utilizando mágicas piedras vivientes. Para crear los mares y elevar la tierra por encima del nivel del mar, los titanes crearon a los inmensos, pero gentiles gigantes marinos. Durante varias eras, los titanes moldearon la tierra hasta crear un continente perfecto.", "En el centro del continente, los titanes crearon un lago misterioso de energías incandescentes. El lago, llamado Pozo de la Eternidad, constituía la fuente de la vida de todos los seres que habitaban el planeta. Sus poderosas energías alimentaron los huesos de todo ser viviente y sembraron de vida aquel rico suelo. Con el tiempo, plantas, árboles, monstruos y criaturas de todas las clases empezaron a prosperar en el continente primigenio.", "En el crepúsculo del última día de su obras de creación del mundo, los titanes dieron al continente el nombre de Kalimdor: \"tierra de eterna luz estelar\"." } } },
    ["The Pariah's Instructions"] = { { ids = { "i17781" }, first = "setfarbackinthevalleyofs", pages = { "En las profundidades del Valle de las Lanzas está situado el templo sagrado de Maraudon. Si no fuera suficiente con esta trasgresión, pronto descubrirás por qué le pedí a un no centauro que me ayudara en tan difícil situación.\n\nAllí, más allá de las puertas donde solo hay espíritus y solo nuestros más elevados sacerdotes y sacerdotisas pueden viajar, se encuentra uno llamado el profeta sin nombre. Es el ser más elevado de cualquier tribu en cuestiones espirituales y, al mismo tiempo, es uno de los más ancianos.", "El profeta es poderoso y se comunica con los espíritus de nuestros ancestros. ¡Pero es un idiota! No tiene ni idea del verdadero poder que posee. En su persona recae el amuleto de los espíritus: de ahí procede la mayor parte de su poder.\n\nHe aprendido que el amuleto es poderoso, pero está incompleto.", "Al amuleto le faltan cinco gemas. Y si dichas gemas estuvieran colocadas dentro del símbolo, su poder sería muchísimo mayor de lo que es en la actualidad. He localizado las cinco gemas, pero necesito a alguien con tu talento para que me ayude a colocarlas. Matar al profeta sin nombre es, seguramente, una herejía, como sería saquear su cadáver, pero lo que voy a pedirte a continuación condenaría a cualquier centauro aun cuando solo pensara en ello.", "Por el interior de las cavernas de Maraudon deambulan los espíritus de nuestros primeros khans. Los primeros hijos de nuestra Madre y nuestro Padre, y nuestros más grandes líderes, son Gelk, Kolk, Magra, Maraudos y Veng. Cada uno de estos espíritus alberga una de las gemas perdidas.", "¡Utiliza el poder del amuleto de los espíritus para obligarlos a manifestarse y quítales las gemas! Luego, coloca las gemas en el amuleto de los espíritus y devuélvemelo. Una vez que tenga el Amuleto de Unidad, tendré suficiente poder como para reformar las tribus, de tal manera que, finalmente, ¡podamos llegar a ser lo que deseaban nuestros ancestros!" } } },
    ["The Scourge of Lordaeron"] = { { ids = { "o175756" }, first = "afterpreparingformanylon", pages = { "Tras largos meses de preparación, Kel'Thuzad y su Culto de los Malditos finalmente dieron el primer golpe, lanzando la peste de los no-muertos sobre Lordaeron. Uther y sus compañeros paladines investigaron las regiones infectadas con la esperanza de encontrar un medio de detener la peste. A pesar de sus esfuerzos, la peste continuó extendiéndose, amenazando con destrozar la Alianza.", "Cuando las filas de no-muertos marcharon sobre Lordaeron, el único hijo de Terenas, el príncipe Arthas, asumió la dirección de la lucha contra la Plaga. Arthas logró acabar con Kel'Thuzad, pero, incluso así, los ejércitos de no-muertos aumentaron con cada uno de los soldados que caía defendiendo la tierra. Frustrado y descorazonado por enfrentarse a un enemigo aparentemente imposible de detener, Arthas tomó una serie de medidas extremas para conquistarlos. Finalmente, los compañeros de Arthas le advirtieron que estaba perdiendo su propia humanidad.", "El miedo y la resolución de Arthas resultaron ser su perdición. Siguió el rastro del origen de la peste hasta Rasganorte, intentado acabar con esta amenaza para siempre. En su lugar, el príncipe Arthas sucumbió ante el tremendo poder del rey Exánime. Creyendo que esto salvaría a su gente, tomó la espada rúnica maldita, Pica de Escarcha.", "Aunque la espada le concedió un poder inefable, también robó su alma y lo transformó en el más grande de los caballeros de la muerte del rey Exánime. Con su alma apartada de sí y perdida su cordura, Arthas dirigió a la Plaga contra su propio reino. Finalmente, Arthas mató a su propio padre, el rey Terenas, y aplastó Lordaeron bajo la bota de hierro del rey Exánime." } } },
    ["The Second Troll Legend"] = { { ids = { "i2006" }, first = "taleofgrilekthewanderert", pages = { "Cuento de Gri'lek el Trotamundos\n\n[...El comienzo de la tablilla estaba desgastado y borrado. Pero el final era legible...]\n\nGri'lek caminaba ruidosamente por la jungla. Sus ojos eran dos llamas y su pecho rugía, pues la ira lo consumía.\n\nEnfurecido, rugió mirando al cielo y levantó un brazo. Alzó el brazo izquierdo, que era fuerte y certero porque cazaba sin su gemelo.\n\nY es que el brazo derecho de Gri'lek ya no estaba y no volvería nunca más.", "Y así deambuló y continuó buscando. Y su brazo permaneció perdido. Y, mientras andaba, maldijo y rugió.\n\nPero hace mucho tiempo que Gri'lek dejó de escuchar a los espíritus, y estos estaban airados y no querían atender sus maldiciones.\n\nGri'lek estaba condenado. Condenado a vagar inerme." } } },
    ["The Sentinels and the Long Vigil"] = { { ids = { "o175732" }, first = "withthedepartureoftheirw", pages = { "Con la partida de sus caprichosos primos, los elfos de la noche volvieron a centrarse en la protección de su tierra encantada. Los druidas, conscientes de que se acercaba el momento de hibernar, se prepararon para su largo sueño y abandonaron temporalmente a sus seres queridos y familiares.", "Tyrande, que se había convertido en la suma sacerdotisa de Elune, pidió a su amado Malfurión que no la abandonara para partir al Sueño Esmeralda de Ysera. Pero Malfurión ponía en juego su honor si no penetraba en las cambiantes sendas de los sueños, de modo que se despidió de la sacerdotisa y le juró que no se separarían jamás si mantenían vivo su amor.", "Sola, ante la perspectiva de proteger a Kalimdor de los peligros que acechaban al nuevo mundo, Tyrande reunió a un poderoso ejército de hermanas elfas de la noche. Las intrépidas y diestras guerreras, decididas a defender Kalimdor, eran conocidas como las Centinelas. Aunque preferían patrullar los frondosos bosques de Vallefresno ellas mismas, contaban con muchos aliados a los que podían recurrir en momentos difíciles.", "El semidiós Cenario permaneció cerca de los Claros de la Luna del Monte Hyjal. Sus hijos, conocidos como los Guardianes de la Arboleda, vigilaron de cerca a los elfos de la noche y ayudaron constantemente a las Centinelas a mantener la paz en aquellas tierras. Incluso las tímidas hijas de Cenario, o dríades, salían al exterior con mayor frecuencia.", "La tarea de vigilar Vallefresno mantuvo ocupada a Tyrande, pero sin Malfurión a su lado, apenas sonreía. A medida que los siglos transcurrieron, los druidas seguían inmersos en su sueño y el temor de Tyrande creció ante la posibilidad de una segunda invasión demoníaca. No la abandonaba la turbadora sensación de que la Legión Ardiente seguía merodeando al otro lado de la Gran Oscuridad, planeando su venganza contra los elfos de la noche y el reino de Azeroth." } } },
    ["The Seven Kingdoms"] = { { ids = { "o175737" }, first = "stromcontinuedtoactasthe", pages = { "Strom continuaba siendo el centro de Arathor, pero como ocurrió con Dalaran, aparecieron nuevas ciudades estado por todo el continente de Lordaeron. Gilneas, Alterac y Kul Tiras fueron las primeras ciudades estado y, aunque cada una tenía sus propias costumbres y sistemas de intercambio, todas se sometían a la autoridad indiscutible de Strom.", "Bajo la atenta mirada de la Orden de Tirisfal, Dalaran se convirtió en el centro principal de enseñanza de la magia en todo el territorio. Los magócratas, que gobernaban Dalaran, fundaron el Kirin Tor, una secta especializada, encargada de catalogar e investigar cada hechizo, artefacto y objeto mágico conocido hasta el momento.", "Gilneas y Alterac se convirtieron en fuertes defensores de Strom y formaron poderosos ejércitos que exploraron las tierras montañosas del sur de Khaz Modan. Durante este periodo, los humanos se encontraron por vez primera con la antigua raza de los enanos y viajaron a su cavernosa ciudad subterránea de Forjaz. Los humanos y los enanos compartieron muchos secretos acerca de la metalurgia y la ingeniería, al tiempo que descubrieron que sentían un amor común por las batallas y la narración de historias.", "La ciudad estado de Kul Tiras, fundada sobre una gran isla situada al sur de Lordaeron, desarrolló una próspera economía basada en la pesca y la industria naviera. Con el tiempo, Kul Tiras armó una poderosa flota de buques mercantes que navegaron recorriendo las tierras conocidas en busca de productos exóticos para comerciar con ellos. Si bien la economía de Arathor floreció, sus elementos más poderosos comenzaron a desintegrarse.", "Con el tiempo, los señores de Strom intentaron trasladar sus propiedades a las exuberantes tierras del norte de Lordaeron, abandonando las áridas tierras del sur. Los herederos del rey Thoradin, los últimos descendientes de la línea de sangre arathi, alegaron que Strom no debía ser abandonada y, de esta manera, provocaron el descontento de la mayor parte de la ciudadanía, ya que la mayoría estaba ansiosa por marcharse.", "Los señores de Strom, intentando lograr la pureza y la iluminación en el norte virgen, decidieron abandonar su antigua ciudad. Hacia el norte, lejos de Dalaran, los señores de Strom construyeron una nueva ciudad estado que denominaron Lordaeron. Todo el continente adoptó este nombre a partir de la denominación de la ciudad estado. Lordaeron se convirtió en la meca de los peregrinos religiosos y de todos aquellos que buscaban la paz interior y la seguridad.", "Los descendientes de los arathi, abandonados tras los desmoronados muros de la vieja Strom, decidieron marcharse hacia el sur, más allá de las rocosas montañas de Khaz Modan. Finalmente, su viaje terminó tras largas jornadas y se asentaron en la región norteña del continente que denominarían Azeroth. En un fértil valle fundaron el reino de Ventormenta, que rápidamente se transformó en una potencia autosuficiente por derecho propio.", "Los escasos guerreros que quedaron en Strom decidieron guardar los viejos muros de su ciudad. Strom ya no era el centro del imperio, sino que se convirtió en una nueva nación conocida como Stromgarde. Si bien cada una de las ciudades-estado alcanzó la prosperidad por sí misma, el imperio de Arathor terminó por desintegrarse. A medida que cada nación desarrolló sus propias costumbres y creencias, comenzaron a estar cada vez más separadas una de la otra. Finalmente, la visión del rey Thoradin acerca de una humanidad unificada se desvaneció." } } },
    ["The Skull of Tyrannistrasz"] = { { ids = { "o175679" }, first = "theremainsofthegargantua", pages = { "Los restos del pantagruélico dragón rojo se encontraron en los Humedales poco después de la batalla de Grim Batol. Se dice que Tyrannistrasz fue el consorte más anciano de Alextrasza, reina de los dragones." } } },
    ["The State of Lakeshire"] = { { ids = { "i1293" }, first = "mylordwarisuponusdoomhar", pages = { "Mi señor:\n\nLa guerra se cierne sobre nosotros. La fatalidad nos acecha.\n\nComo magistrado del municipio de Villa del Lago, es mi deber informar acerca de la reciente actividad militar que ha tenido lugar en la colonia de Vuestra Majestad, situada en el extremo este.\n\nEn estas páginas encontraréis un informe sobre el estado de Villa del Lago, enclavado en las montañas Crestagrana.", "La pérdida del Fuerte de Petravista nos ha afectado terriblemente. Anteriormente os informé acerca de la alianza existente entre el clan de orcos Roca Negra y el brujo conocido como Morganth. Los orcos Roca Negra lucharon salvajemente, reforzados por la magia perversa de Morganth. Muchos de los más valientes soldados de Vuestra Majestad perecieron intentando defender el fuerte, pero finalmente no se pudo hacer nada.", "Curiosamente, Morganth se volvió contra sus seguidores orcos tras su nefasta victoria. El brujo construyó una torre arcana en el noreste y usó sus poderes para crear un pequeño ejército de gnolls Pellejo Negro a su servicio. Tanto los orcos como los hombres fueron víctimas de las bestias viscosas que servían al brujo. En cuanto a la traición entre Morganth y Gath'Ilzogg, Señor de la Guerra Roca Negra, solo caben especulaciones.", "Para nuestra preocupación, los apestosos orcos parecen dedicarse a matar a los honrados ciudadanos de Su Majestad. Durante la última quincena, el clan Roca Negra desató una implacable ofensiva sobre Villa del Lago. Muchos hombres valientes perdieron la vida aquel aciago día. Las fuerzas orcas avanzaron tan rápidamente y con tanta furia, que destruyeron el puente sobre el lago Sempiterno. Nuestros suministros de guerra disminuyeron ostensiblemente. Carecemos de vendas para curar las heridas de los caídos.", "Ahora solicito a Vuestra Majestad el apoyo para esta buena gente de Villa del Lago en estos aciagos momentos. Necesitamos nuevos soldados para defender el territorio, así como nuevas armas de guerra para sustituir las que hemos perdido en el campo de batalla. Asimismo, escasean los alimentos y los suministros para la construcción. Mi señor, os ruego nos ayudéis a mantener en pie el último bastión que queda entre los hombres y los orcos. El enemigo debe permanecer fuera del Reino de Ventormenta.", "Temo que un mal aún más siniestro y terrible se cierna sobre la caldera fétida de las tierras del norte. Resulta crucial que el Reino de Ventormenta entre en acción para evitar convertirnos en un triste recuerdo para los vivos o en esclavos del enemigo.\n\nFirmado,\n\nMagistrado Salomón\nMunicipio de Villa del Lago\nReino de Ventormenta" } } },
    ["The Story of Morgan Ladimore"] = { { ids = { "i2154" }, first = "morganladimorewasagreata", pages = { "Morgan Masdama fue un noble caballero que luchó en defensa de los inocentes, los pobres y los afligidos. Durante años, trabajó diligentemente en la periferia de Azeroth, aliviando a las víctimas y castigando a los malhechores.\n\nEn el verano, al cumplir dieciocho años, contrajo matrimonio con una joven llamada Lys. Estaban muy enamorados y tuvieron tres hijos, un varón y dos chicas.\n\nMorgan tenía treinta y dos años cuando estalló la guerra en", "Lordaeron. Morgan fue reclutado por el legendario Uther el Iluminado para combatir a los orcos y a los no-muertos. Tras dejar a su mujer y a sus hijos a salvo en su hogar, Morgan partió hacia la guerra.\n\nPasaron los años y la guerra se prolongó, Morgan presenció espantosas escenas, incluyendo la desbandada de los paladines de la Mano de Plata, la muerte de Uther y la propagación de la peste. Lo único que lo mantenía a salvo de la locura era la certeza de que algún día", "se reuniría con su mujer y sus hijos.\n\nMorgan regresó finalmente a su hogar, pero lo que encontró nada tenía que ver con lo que recordaba. El bosque que antes era verde ahora estaba contaminado, infestado de no-muertos y otras fuerzas oscuras. Por doquier había casas y granjas destruidas y el Cementerio del Cerro del Cuervo cubría gran parte del territorio. Morgan, indignado y perplejo, llegó hasta su casa, encontrándola en ruinas. Ignorando lo que le había ocurrido a su tierra,", "se dirigió al pueblo para encontrar respuesta, deseoso de hallar a su mujer y a sus hijos.\n\nMorgan preguntó por su familia, pero no recibió respuesta alguna. Un sacerdote de Villa Oscura, nombre con el que ahora se designaba al lugar, le sugirió que buscara una lápida en el Cerro del Cuervo. Morgan se negó a aceptar que su familia había muerto y continuó buscando en vano por todas las granjas y casas de Bosque del Ocaso.\n\nAsí, cabalgó desde Villa Oscura hasta las afueras de Villa del Lago, deseando que su familia hubiera podido escapar. En el camino,", "obviando el sentido común, decidió parar en el cementerio del Cerro del Cuervo. Morgan paseó durante horas entre las lápidas. Reconoció los nombres de muchas personas que había conocido y cada vez estaba más consternado por el dolor. Entonces los vio: una descuidada parcela en medio de tantas otras, con tres pequeñas lápidas. A medida que se acercaba, una ola de pánico se apoderaba de él. Morgan quitó el polvo de la lápida más grande para leer el nombre grabado en su superficie. Las letras sobre la tumba constataron", "el temido presagio:n\nLys Masdama\nAmada esposa y madre\n\nEl temor de Morgan se transformó en consternación y luego en dolor, postrándolo de rodillas mientras vertía lágrimas amargas. Permaneció durante horas frente a la tumba, suplicando perdón a la fría piedra y disculpándose entre sollozos. Luego, horas más tarde, algo se resquebrajó en su interior y la emprendió a golpes contra todo lo que lo rodeaba. Desenfundó la espada y empezó a golpear las lápidas una y otra vez, gritando de rabia. Ciego de ira, intentaba golpear algo y arremetía contra todo, llamando la atención", "de tres guardas del cementerio. Cuando intentaron detenerlo, se abalanzó sobre ellos, acusando a los pobres guardas inocentes, y luego les dio muerte.\n\nMás tarde, cuando la ira se había disipado, Morgan tomó conciencia de lo ocurrido y vio su espada ensangrentada, clavada en el pecho de uno de los guardas. Al borde del límite, extrajo el puñal de su cinturón y lo hundió en su propio pecho.\n\nEl cuerpo de Morgan Masdama y los de sus víctimas fueron hallados", "al día siguiente. Fue enterrado rápidamente, sin ceremonia, en una tumba excavada en las afueras del cementerio. Puesto que había cometido asesinato contra personas inocentes, algo que iba totalmente en contra de sus creencias y su naturaleza, y por el dolor que sentía por haber sido incapaz de salvar a su familia, Morgan no tuvo una muerte pacífica y vagó por el mundo como un muerto viviente.\n\nPocos días más tarde, su tumba fue profanada y su cuerpo había desaparecido. Quien un día fuera Morgan ahora", "vaga por el Bosque del Ocaso, consumido por la pena de haber perdido a su mujer y sus hijos, así como por el desprecio hacia sí mismo. Mor'Ladim, nombre actual de Morgan, vaga ciego de venganza y odio por el Bosque del Ocaso, cometiendo asesinatos indiscriminadamente." } } },
    ["The Third Troll Legend"] = { { ids = { "i2007" }, first = "risingfromtheoceanatower", pages = { "Una torre de agua se eleva desde el océano... Neptulon ha enviado descomunales Krakken al desolado I'lalai. Eran tan descomunales sus formas que selvas de algas colgaban de sus miembros, y estos leviatanes nadaban entre los cuerpos.\n\nEl Krakken más grande levantó sus brazos y los estrelló contra el océano, lanzando enormes olas a su alrededor. Y estas azotaron las costas de I'lalai.", "Los krakken rugieron y sus voces resonaron como una tormenta marina:\n\n\"Allá vamos\".\n\nSin titubear, Min'loth invocó su magia. Las olas que llegaron hasta I'lalai se separaron a ambos lados e inundaron la jungla en toda su extensión. Min'loth pidió entonces a sus esbirros que pronunciaran hechizos de vínculo y se escuchó un intenso barullo cuando decenas de trols elevaron sus cánticos.\n\nUna voz destacó sobre las demás.", "Min'loth bramó y su magia recogió el poder de los hechizos de su esbirro, lanzándolos hacia los Krakken que se aproximaban.\n\nLas aguas se separaron y el hechizo de Min'loth viajó veloz hacia los siervos de Neptulon. Los relámpagos desgarraron el cielo y el hechizo alcanzó a los monstruos. Miles de truenos cayeron sobre el agua hirviendo y los cráteres ardieron en la tierra.\n\nMin'loth aulló victorioso, seguro de que su hechizo derrotaría a las enormes bestias.", "Pero los Krakken son viejos, muy viejos. Recordaban cuando la tierra había surgido por primera vez del mar.\n\nRecordaban cuando los Antiguos reinaban y cuando los Viajeros llegaron y los expulsaron. Recordaban cuando la magia era una novedad.\n\nSon viejos y guardan muchos secretos. Y aunque el hechizo de Min'loth era poderoso, al igual que el trol, era mortal.\n\nPor eso falló.", "No pudo atrapar a los Krakken, pero logró enfurecerlos. Durante miles de años, ningún mortal les había causado daño y el encantamiento de los trols resultó doloroso.\n\nY así, se liberaron de los vínculos del encantamiento de Min'loth, pero luego, bramaron y se enfurecieron.\n\nSe oyó un gran estruendo cuando se elevaron grandes olas desde las profundidades, dirigiéndose a la tierra. Cuando alcanzaron l'lalai, proyectaron una sombra sobre la ciudad.\n\nPero antes de destruirla, los Krakken se detuvieron, quedando suspendidos.", "Los médicos brujos trol temblaron y profirieron gritos a su maestro. Minloth contempló las montañas del mar, con aire fatal y desafiante. Se volvió hacia sus adeptos y susurró unas palabras, y los trols grabaron sus últimas palabras en piedra. Luego, Min'loth se volvió hacia los Krakken que se avecinaban.\n\nHizo una mueca y agitó su báculo, su último acto enérgico.\n\nLuego, los Krakken hicieron caer toda su furia en Min'loth y el océano se precipitó sobre l'lalai.\n\nY desapareció.", "A continuación, las aguas cayeron sobre la jungla, inundándolo todo a su paso. Los trols y las bestias gritaron mientras las aguas los golpeaban y los sumergían.\n\nMuchos Gurubashi se preguntaban por qué el océano se los tragaba, pero morían igualmente, sin conocer la causa.\n\nY, finalmente, cuando las aguas alcanzaron las montañas, se detuvieron. Cuando se aplacaron, se retiraron hacia la costa y dejaron un rastro de muerte.\n\nLas aguas se retiraron, pero rodearon completamente l'lalai, que permaneció anegada para siempre.", "Y el jefe Var'gazul, a salvo tras las montañas en Zul'Gurub, se dirigió a la jungla y vio que su gente había desaparecido.\n\nSe sintió desesperado, ya que sus sueños de conquista se habían roto.\n\nY Min'loth, la Serpiente, nunca fue encontrada." } } },
    ["The Twin Empires"] = { { ids = { "o175854" }, first = "aboutyearsagolongbeforet", pages = { "Hace aproximadamente unos 16,000 años, antes de que los elfos de la noche provocaran imprudentemente la ira de la Legión Ardiente, los trols se enseñoreaban sobre la mayor parte de Kalimdor (entonces, un solo continente). Había dos imperios trol, el imperio Gurubashi de las junglas del sudeste y el Imperio Amani de las tierras boscosas del interior.", "Había tribus más pequeñas que habitaban el extremo norte (en la región conocida actualmente como Rasganorte). Dichas tribus fundaron una pequeña nación llamada Gundrak, que nunca alcanzó el tamaño ni la prosperidad de los imperios del sur.", "Los imperios Gurubashi y Amani no se tenían en gran estima, pero casi nunca entraban en guerra. En aquel tiempo, su mayor enemigo común era un tercer imperio: la civilización de Azj'Aqir. Los aqir eran inteligentes insectoides que ocupaban las tierras del lejano oeste. Estos astutos insectoides se expandían de forma permanente y eran increíblemente malvados. Los aqir estaban obsesionados con erradicar todos los seres vivientes que no fueran insectos de los campos de Kalimdor.", "Los trols lucharon contra ellos durante miles de años, pero nunca pudieron conseguir una verdadera victoria sobre los aqir. Finalmente, debido a la persistencia de los trols, el reino aqiri se dividió en dos mitades cuando sus ciudadanos formaron colonias separadas en las regiones del extremo norte y el extremo sur del continente.", "Emergieron dos ciudades-estado aqiri: Azjol-Nerub, en las tierras baldías del norte, y Ahn'Qiraj, en el desierto del sur. Aunque los trols sospechaban que había otras colonias aqiri bajo Kalimdor, su existencia nunca fue verificada.", "Cuando los insectoides marcharon al exilio, los imperios gemelos trol volvieron a sus asuntos cotidianos. A pesar de su gran victoria, ninguna civilización consiguió expandirse mucho más allá de sus fronteras originales. Sin embargo, existen textos antiguos que hablan de una pequeña facción de trols que se desgajó del Imperio Amani y fundó su propia colonia en el corazón del oscuro continente.", "Allí, estos valientes pioneros descubrieron el Pozo de la Eternidad cósmico, que los transformó en seres provistos de un inmenso poder. Algunas leyendas sugieren que estos trols aventureros fueron los primeros elfos de la noche, si bien esta teoría nunca ha sido demostrada." } } },
    ["The Walks of Shaman"] = { { ids = { "i274483" }, first = "azerothishometoahostofbr", pages = { "Azeroth alberga un sinfín de criaturas brillantes. No tiene favoritos. Si aprendes a escucharla, sentir su presencia y responder a su llamada, es sencillo recurrir a sus fuerzas.\n\nCon tiempo y paciencia, cualquiera puede oír a los elementos, pero nuestros tótems nos proporcionan un conducto para canalizar ese poder. Las culturas más civilizadas solo entregan un tótem a quienes se han mostrado dignos, aunque un chamán suficientemente poderoso puede crear uno a voluntad.\n\nHemos visto criaturas que usan los elementos para el mal. Cuando la corrupción de la tierra es suficiente, Azeroth clama por protectores contra esos tótems retorcidos. Con bastantes de esos conductos corruptos, se puede incluso invocar a los elementos contaminados y desterrarlos de nuevo a los planos.", "Los centauros Maraudine de Desolace.\n\nCuando usas el chamanismo para fortalecer a tu pueblo, hace falta armonía con la naturaleza. El viento responde porque así lo elige. Eres su campeón y él se convierte en el poder que permite a tu pueblo alzarse. Los Maraudine, sin embargo, no respetan ese equilibrio.\n\nEste clan solo ha usado el poder para su propio beneficio. Partidas de caza que vuelan por las llanuras tras sus enemigos, hechiceros que canalizan grandes tormentas para quemar aldeas. Ni siquiera eso les basta. Han creado tótems de poder espantoso que obligan a los elementos a someterse a su voluntad.\n\nNo nos corresponde decidir los deseos de Azeroth, pero una cosa está clara: los Maraudine no son amigos de los elementos.", "Los múrlocs Ancalodo de Marjal Revolcafango.\n\nLos múrlocs tienen una conexión innata con el agua, como todo pueblo marino, pero de una forma curiosa. Muchas especies reconocen los elementos en la naturaleza sin recurrir directamente a ellos. Los múrlocs no solo pueden invocar el agua, sino usarla con una inteligencia sorprendente.\n\nSus oráculos tienen una afinidad curiosa con la magia restauradora. El agua es fuente de curación para todas las criaturas, desde la hidratación hasta la medicina, pero los múrlocs han logrado acceder a fuentes de poder aún más profundas. Algunos parecen nacer con un don que a ciertos adeptos les lleva décadas dominar.\n\nEn cualquier otro chamán se consideraría una bendición. Pero, al fin y al cabo, son múrlocs. Su magia curativa es un arma como cualquier otra, que mantiene alerta a sus cazadores y sus costas listas para combatir. El uso de tótems resulta curioso en una especie así, pero no te equivoques. Son tan corruptos como sus amos.", "Los troggs Grutacanto de Tierras Inhóspitas.\n\nA menudo se entiende mal el fuego como fuente de destrucción. Aunque el fuego descontrolado sí es señal de un espíritu sin control, una llama concentrada ilumina hogares y aleja el frío amargo. Un pueblo que domina este elemento sin duda prosperará, tanto en combate como en casa.\n\nLos troggs Grutacanto no son una excepción.\n\nLos troggs son criaturas bastante sencillas. No destacan por grandes demostraciones de poder ni por una agresividad especialmente coordinada. Hasta que descubrieron el fuego, ni siquiera se los consideraba una cultura digna de estudio. Pero los elementos no tienen favoritos.\n\nA medida que han evolucionado, han aprendido a aprovechar el fuego para su barbarie tribal. Recibir un garrotazo es una cosa, pero un trogg agresivo con un tótem de fuego es otra muy distinta. El elemento del fuego quizá respete mantener viva su cultura, pero desde luego no el uso de sus tótems para una crueldad ciega.", "Los Perdidos del Pantano de las Penas.\n\nLa tierra es el elemento de la fortaleza y la firmeza. Un chamán capaz de aprovechar su poder puede garantizar hogares sólidos y guerreros resistentes para su pueblo. Un golpe que derribaría a otro combatiente puede no afectar a quien recibe los dones de la tierra.\n\nTambién puede usarse para derrumbar a otros.\n\nCuando se los deja a su aire, Los Perdidos rara vez interfieren en los asuntos de otras culturas. Merodean en un estado de ensimismamiento vacío, como si no pertenecieran a ningún sitio. Solo los elementos les ofrecen algo a lo que aferrarse.\n\nA diferencia de los demás mencionados, no se cree necesariamente que Los Perdidos deseen de verdad hacer daño. La tierra les ofrece consuelo en su vagar sin rumbo. Pero con él llega su dependencia.\n\nPedir ayuda a los elementos es una cosa y exigir su presencia es otra. Son nuestros guías, no nuestras muletas. Ahora sus tótems están tan retorcidos como los propios Perdidos." } } },
    ["The War of the Ancients"] = { { ids = { "o175727" }, first = "thehighbornesrecklessuse", pages = { "El uso temerario de la magia de los altonatos envió ondas energéticas desde el Pozo de la Eternidad hasta la Gran Oscuridad en el más allá. Las ondas expansivas de energía fueron percibidas por terribles mentes de otros mundos. Sargeras, el Gran Enemigo de la vida y Destructor de los Mundos, percibió las poderosas ondas y se sintió atraído por su distante punto de origen.", "Al descubrir el mundo primigenio de Azeroth y las energías ilimitadas del Pozo de la Eternidad, Sargeras experimentó un apetito insaciable. El gran dios oscuro del Vacío sin nombre decidió destruir el mundo en ciernes y reclamar las energías como suyas.", "Sargeras reunió a su vasta Legión Ardiente y se dirigió hacia el desprevenido mundo de Azeroth. La Legión estaba formada por un millón de demonios que vociferaban, todos procedentes de los reinos más apartados del universo, ávidos de conquista. Los tenientes de Sargeras, Archimonde el Rapiñador y Mannoroth el Destructor, prepararon a sus esbirros infernales para el ataque.", "La reina Azshara, inmersa en el terrible éxtasis de la magia, fue víctima del innegable poder de Sargeras y accedió a concederle la entrada en su mundo. Incluso sus siervos altonatos se rindieron ante la inevitable corrupción de la magia y veneraron a Sargeras como a un dios. Para demostrar su lealtad a la Legión, los altonatos ayudaron a su reina a abrir un enorme portal en las profundidades del Pozo de la Eternidad.", "Una vez realizados todo los preparativos necesarios, Sargeras inició la devastadora invasión de Azeroth. Los demonios guerreros de la Legión Ardiente invadieron el planeta a través del Pozo de la Eternidad y sitiaron las ciudades dormidas de los elfos de la noche. Dirigidos por Archimonde y Mannoroth, la Legión irrumpió sobre las tierras de Kalimdor, dejando a su paso cenizas y dolor.", "Los demonios brujos invocaron malignos infernos que cayeron como mortíferos meteoros sobre las cimas de los templos de Kalimdor. Una banda de matones sanguinarios conocidos como Guardias apocalípticos arrasaron los campos de Kalimdor, asesinando a todo el que se cruzaba en su camino. Manadas de canes manáfagos saquearon el campo sin encontrar resistencia. No obstante, los valientes guerreros kaldorei defendieron su antigua tierra natal, pero poco a poco se vieron obligados a ceder terreno ante el ataque furibundo de la Legión.", "Malfurión Tempestira decidió buscar ayuda para su gente asediada. Tempestira, cuyo propio hermano Illidan practicaba la magia de los altonatos, estaba indignado por la creciente corrupción entre estos nobles. Convenciendo a Illidan de que abandonara su peligrosa obsesión, Malfurión buscó a Cenario y reunió fuerzas para iniciar la resistencia.", "La bella y joven sacerdotisa Tyrande accedió a acompañar a los hermanos en nombre de Elune. Aunque Malfurión e Illidan amaban por igual a la idealista sacerdotisa, el corazón de Tyrande pertenecía solo a Malfurión. Illidan sentía celos por el romance de su hermano con Tyrande, pero sabía que su mal de amores no era nada comparado con el dolor que le causaba la adicción a las artes de la magia.", "Illidan, que sentía una creciente dependencia de las poderosas energías de la magia, luchó para controlar su abrumador deseo de volver a vaciar las energías del Pozo. No obstante, con el paciente apoyo de Tyrande, pudo dominarse y ayudó a su hermano a encontrar al solitario semidiós Cenario.", "Cenario, que habitaba en los Claros de Luna sagrados del distante del Monte Hyjal, accedió a ayudar a los elfos de la noche, encontrando a los antiguos dragones y enviándolos en su ayuda. Los dragones, dirigidos por la colosal Alexstrasza, ordenaron a sus poderosos vuelos enfrentarse a los demonios y a sus infernales maestros.", "Cenario, invocando a los espíritus de los bosques encantados, armó un ejército de antiguos hombres árbol y los condujeron hacia el combate contra la Legión en un temerario asalto terrestre. Cuando los aliados de los elfos de la noche se reunieron en el templo de Azshara y en el Pozo de la Eternidad, se desató la guerra total. A pesar de la fortaleza de sus nuevos aliados, Malfurión y sus compañeros se dieron cuenta de que la Legión no podía ser derrotada solo mediante el poder militar.", "Cuando la titánica batalla tuvo lugar en torno a la capital de Azshara, la reina ya estaba esperando la llegada de Sargeras. El señor de la Legión estaba preparándose para atravesar el Pozo de la Eternidad e irrumpió en aquel planeta en guerra. Cuando su sombra inconmensurable se acercó a la superficie del Pozo, Azshara reunió a sus más poderosos seguidores altonatos. La unión de sus poderes mágicos en un solo hechizo fue el único medio capaz de crear una entrada lo suficientemente grande para permitir la entrada a Sargeras.", "Cuando la batalla asolaba los campos en llamas de Kalimdor, se produjo un hecho insólito. Los detalles se han perdido en el tiempo, pero se sabe que Neltharion, el Dragón Aspecto de la Tierra, enloqueció en un combate feroz contra la Legión Ardiente. Empezó a desmoronarse al tiempo que las llamas y la ira brotaban de su oscuro pelaje. Adoptando el nombre de Alamuerte, el dragón ardiente se volvió en contra de sus hermanos y retiró a las cinco bandadas de dragones del campo de batalla.", "La repentina traición de Alamuerte fue tan destructiva, que las cinco bandadas de dragones jamás se recuperaron. Herida y conmocionada, Alexstrasza y otros nobles dragones se vieron obligados a abandonar a sus mortales aliados. Malfurión y sus compañeros, ahora terriblemente diezmados, apenas sobrevivieron a la matanza que sobrevino a continuación.", "Malfurión, convencido de que el Pozo de la Eternidad era el cordón umbilical de los demonios con el mundo físico, insistió en que debía ser destruido. Sus compañeros, que sabían que el Pozo era la fuente de su inmortalidad y sus poderes, estaban horrorizados ante tal perspectiva. No obstante, Tyrande comprendió la sabia teoría de Malfurión y convenció a Cenario y a sus compañeros a que atacaran el templo de Azshara y encontraran la manera de cerrar el Pozo por el bien de todos." } } },
    ["The War of the Shifting Sands"] = { { ids = { "i20415" }, first = "ithasbeennearlyathousand", pages = { "Han pasado casi mil años desde la Guerra del Mar de Dunas. Durante aquella guerra, en el corazón del desierto de Silithus, una gran tragedia y una carga aún mayor cayeron sobre Fandral Corzocelada. Se cree que los hechos aquí descritos acabaron moldeando el desagradable carácter del archidruida.", "Una antigua raza insectoide consciente, los qiraji, disputó en otro tiempo el dominio de buena parte de Kalimdor. Fueron el pomposo e imperialista Corzocelada y su ejército de elfos de la noche quienes se enfrentaron directamente a ellos.", "Padre e hijo combatieron con fervor para contener la marea creciente del enjambre en Silithus. De la fortaleza de Ahn'Qiraj salía un flujo aparentemente interminable de silítidos que reforzaba a los invasores qiraji. Todo Silithus estaba sitiado.", "En una decisión que Corzocelada lamentaría, se ordenó al joven Valstann defender el puesto de los elfos de la noche en la Aldea del Viento del Sur. Por desgracia, Valstann perdería la vida aquel día y la aldea caería ante los ejércitos de Ahn'Qiraj.", "Sin dejarse vencer y con el corazón apesadumbrado, Fandral Corzocelada siguió adelante, sediento de venganza. La derrota en Silithus supondría una gran pérdida para los elfos de la noche y quizá para el mundo.\n\nLa batalla continuó durante meses. Los qiraji tomaron todo Silithus y empujaron a Corzocelada y su ejército hasta Tanaris. Con sus fuerzas diezmadas e incontables inocentes muertos, la arrogancia que lo había impulsado quedó completamente extinguida.", "Con el orgullo hecho pedazos, Corzocelada sintió por segunda vez en su vida ese vuelco en el estómago que solo produce el miedo. Allí, en Tanaris, se acercó a Anacronos, vástago de Nozdormu, y suplicó la ayuda del Vuelo Bronce.", "Al principio, Anacronos se negó a involucrar al Vuelo Bronce en los asuntos de las razas menores. Solo cuando los qiraji atacaron con insolencia las Cavernas del Tiempo aceptó unir sus fuerzas a las de los elfos de la noche.", "Anacronos pronto comprendió que ni siquiera el poderoso Vuelo Bronce podía contener a los invasores. Por cada cincuenta insectos aniquilados por su aliento, cien esperaban para sustituirlos. Con las líneas élficas flaqueando y la amenaza constante de retroceder aún más al norte, hasta Feralas, decidió que los hijos de los Aspectos debían saberlo.", "Llamó primero al Vuelo de Ysera. Merithra del Sueño respondió y, desde allí, los vuelos de Alexstrasza y Malygos fueron informados.", "Los dragones se reunieron en la estratosfera sobre Silithus, a miles de pies de altura sobre Ahn'Qiraj.\n\nAllí estaba Anacronos, hijo de Nozdormu, Aspecto del Tiempo.\n\nDel Sueño Esmeralda llegó Merithra, hija de Ysera, Aspecto de la Naturaleza.\n\nCaelestrasz, hijo de Alexstrasza, Aspecto de la Vida, representaba al Vuelo Rojo.\n\nArygos, hijo de Malygos, Aspecto de la Magia, representaba al Vuelo Azul.", "Los dragones observaron el flujo interminable de silítidos y qiraji que salía de Ahn'Qiraj. Comprendieron que ninguna fuerza podría poner fin a aquella guerra. Dentro del templo principal esperaban decenas de miles de qiraji. A cada segundo nacían más y quedaban preparados para ser liberados sobre el mundo.", "Arygos fue el primero en advertir las extrañas emanaciones. El templo monolítico del sector sur de Ahn'Qiraj irradiaba una magia tenue, distinta de todo lo que habían sentido en los qiraji. Por más que lo intentaron, ninguno pudo penetrar más en el templo para encontrar su origen. Solo algo de un poder inmenso podía protegerse de forma tan completa. Quizá... algo que controlaba a los insectos. Algo que controlaba incluso a los qiraji.", "Los dragones sabían que debían reaccionar pronto para evitar otra catástrofe épica al mundo. Tras deliberar con cuidado, decidieron que lo mejor sería detener a las huestes en su origen o cerca de él.", "Crearían una gran barrera tomando la esencia tanto de los elfos de la noche como de los dragones. Una barrera mágica que contuviera a los silítidos y a sus amos dentro de los muros de Ahn'Qiraj e impidiera futuras incursiones. La propia Ahn'Qiraj se convertiría en prisión." } } },
    ["The White Stag and the Moon"] = { { ids = { "o177208" }, first = "intothebraveheartsofherp", pages = { "En los valientes corazones de sus hijos puros la Madre Tierra insufló el amor por la caza. Las criaturas de la primera aurora eran salvajes y fieras. Se escondían de la Madre Tierra, encontrando la paz en las sombras y en las tierras salvajes del lugar. Los Shu'halo se dedicaron a cazar a estas bestias allí donde las encontraron y las domesticaron con la anuencia de la Madre Tierra.", "Sin embargo, un gran espíritu logró eludiros. Apa'ro (conocido como Malorne entre los elfos de la noche), era un orgulloso ciervo de pelaje blanco como la nieve. Su cornamenta hería a los mismísimos cielos y sus poderosas patas dejaban su impronta en las profundidades del mundo. Los Shu'halo empujaron a Apa'ro hacia los extremos del mundo de la aurora, creando una trampa para encerrar al orgulloso ciervo.", "Intentando escapar, el gran ciervo saltó hasta el cielo. Aun así, cuando su huida parecía asegurada, su poderosa cornamenta quedó enredada en las estrellas. Aunque luchó y dio coces, Apa'ro no logró zafarse de la trampa de los cielos. Fue entonces cuando Mu'sha atrapó a su hermano, An'she, poco antes de la aurora. Mu'sha contempló cómo luchaba el poderoso ciervo y se enamoró de él inmediatamente.", "La astuta luna hizo un trato con el gran ciervo: lo liberaría de la trampa de las estrellas si estaba dispuesto a amarla y a terminar con su soledad.\n\nMu'sha amó a Apa'ro y concibió un hijo de él. El hijo, considerado por algunos un semidiós, nació en los oscuros bosques de la noche. Se llamó Cenario y vagó por el estrellado camino que conduce del mundo de la vigilia al reino de los cielos." } } },
    ["The World Tree and the Emerald Dream"] = { { ids = { "o175730" }, first = "formanyyearsthenightelve", pages = { "Durante muchos años, los elfos de la noche trabajaron incesantemente para reconstruir su antigua tierra natal. Abandonando sus templos destruidos a merced de la maleza, construyeron sus nuevos hogares en medio de frondosos árboles y frescas colinas junto al Monte Hyjal. Con el tiempo, los dragones que habían sobrevivido al gran Diluvio salieron de sus secretas moradas.", "Alexstrasza la roja, Ysera la verde y Nozdormu el broncíneo descendieron por los serenos claros de los druidas y supervisaron los frutos del trabajo de los elfos de la noche. Malfurión, que se había convertido en un archidruida de inmenso poder, saludó a los magníficos dragones y les habló de la creación del nuevo Pozo de la Eternidad.", "Los grandes dragones, alarmados al escuchar tan nefasta noticia, creyeron que, mientras el Pozo de la Eternidad existiera, la Legión podría volver con el propósito de destruir el planeta nuevamente. Malfurión y los tres dragones hicieron un pacto para proteger el Pozo y asegurarse de que los agentes de la Legión Ardiente jamás volvieran a poner pie en el planeta.", "Alexstrasza la Protectora, colocó una bellota encantada en el corazón del Pozo de la Eternidad. La bellota, activada por las poderosas aguas mágicas, brotó rápidamente hasta convertirse en un árbol colosal. Las potentes raíces del árbol se extendieron desde las aguas del Pozo y la frondosa copa abarcó la inmensidad del cielo.", "El árbol será un símbolo eterno del vínculo de los elfos de la noche con la naturaleza y sus energías portadoras de vida se extenderán por todas partes para curar a los habitantes del planeta. Los elfos de la noche dieron al Árbol del Mundo el nombre de Nordrassil, cuyo significado era \"corona de los cielos\" en su lengua nativa.", "Nozdormu el Atemporal lanzó un encantamiento sobre el Árbol del Mundo que garantizaría que, siempre que el árbol estuviese en pie, los elfos de la noche jamás envejecerían ni enfermarían.", "Ysera la Soñadora también lanzó un hechizo sobre el árbol, vinculándolo a su propio reino, la dimensión etérea conocida como el Sueño Esmeralda. El Sueño Esmeralda, un mundo espiritual eternamente cambiante, existía más allá de las fronteras del mundo físico. Desde el Sueño, Ysera regulaba las mareas de la naturaleza y la evolución del mundo propiamente dicho.", "Los druidas de los elfos de la noche, incluyendo al propio Malfurión, crearon un vínculo con el Sueño a través del Árbol del Mundo. En un pacto místico, los druidas aceptaron dormir simultáneamente durante siglos para que sus espíritus pudieran recorrer las infinitas sendas de los sueños de Ysera. Aunque los druidas sufrían ante la perspectiva de perder tantos años de sus vidas entregándose a la hibernación, mantuvieron desinteresadamente su pacto con Ysera." } } },
    ["Thun'grim's Instructions"] = { { ids = { "i7587" }, first = "belowaretheitemsneededto", pages = { "$N, estos son los objetos necesarios para fabricar tu armadura:\n\nLingotes de hierro humeante de los kobolds Cortaviento que hay en la mina Cortaviento de la Cima del Espolón.\n\nAzurita en polvo de los mineros de Trabalomas.\n\nBarras de hierro de los mineros o de los depósitos de hierro, en el caso de que te dediques a la minería.\n\nVial de flogisto de un jabaespín llamado Roogug, en el Horado Rajacieno." } } },
    ["Thunderhorn's Report"] = { { ids = { "i281139" }, first = "archdruidhasdoneagreatse", pages = { "Archidruida:\n\n$N ha prestado hoy un gran servicio a la tierra. Gracias a su valor, los pozos Pezuña Invernal, Tronacuerno y Bravacrín han quedado limpios de los venenos goblins.\n\nCon el tiempo, las aguas renovadas nutrirán a todos los que recorren las grandes llanuras de Mulgore y la tierra sanará. Alabada sea la Madre Tierra.\n\nSi lo tenéis a bien, solicito en nombre de todos los habitantes del Poblado Pezuña de Sangre una recompensa a la altura de su esfuerzo.\n\nCon gran reverencia,\n\nMull Tronacuerno" } } },
    ["Thundris' Letter"] = { { ids = { "i279045" }, first = "mralexstonofstormwindimu", pages = { "Señor Alexston de Ventormenta:\n\nDebo felicitaros por el largo camino de restaurar la ciudad de Ventormenta. Muchos de quienes pasan por Auberdine alaban su grandeza y sus sólidos cimientos. Ese éxito me ha llevado a enviaros este mensaje.\n\nAuberdine ha encontrado su lugar en este mundo junto al mar. Donde antes estábamos aislados, ahora encontramos esperanza traída por los mismos vientos que azotan nuestras orillas.\n\nEste mensajero representa a uno de esos viajeros que los vientos me trajeron. Espero que ayude a vuestro pueblo como ha ayudado al mío.\n\nA cambio, os pido que enviéis provisiones y mano de obra a Auberdine para reforzar la villa frente a la furia de este mundo que tanto nos ha quitado.\n\n-- Thundris Tejevientos, anciano de Auberdine" } } },
    ["Thurman's Letter"] = { { ids = { "i2837" }, first = "dearestyvetteiwillentrus", pages = { "Querida Yvette,\n\nEncomendaré esta carta a $gnuestro corredor:nuestra corredora; más veloz. Espero que pueda avanzar sin contratiempos por las zonas en que habitan las fuerzas que nos rodean. También ruego para que puedas leer estas palabras, pues son lo último que sabrás de mí.\n\nMi único consuelo en estos días aciagos es el alivio que me produce saber que no tendrás la misma suerte que yo.", "Creo que mi padre cometió un grave error cuando decidió quedarse en casa para defenderla. Las fuerzas de la Plaga asolan los Claros de Tirisfal y, aunque estamos fortificados y bien abastecidos, después de la traición de mi hermano Devlin carecemos de fuerza y tropas suficientes para hacer frente a sus continuos asaltos.\n\nYvette, si recibes esta carta, deberás saber que Devlin es un traidor.", "Devlin perdió la esperanza e intentó escapar a nuestro infortunio, por lo que hizo un pacto con la Plaga. No sé qué se le prometió a cambio de su traición, pero lo que sí puedo asegurar es que estaba tejido de mentiras.\n\nSi ves a mi hermano, huye de él. Es un demonio. Hace un par de noches asesinó a dos de nuestros vigilantes y ayudó a un pequeño grupo de Soldados de la Plaga a entrar por la brecha, conduciéndolos hacia donde muchos de los nuestros dormían.", "Su emboscada fue brutal. Asesinaron a un tercio de nuestras tropas antes de que pudiéramos responder. Ahora solo contamos con hombres para vigilar nuestras fronteras. Solo es cuestión de tiempo: en cuanto bajemos la guardia, la Plaga nos atacará.\n\nY aunque vi el rostro de Devlin en medio de todos esos hombres desesperados y las fuerzas de la Plaga aquella noche maldita, se escabulló antes de que pudiera atraparlo. Tal vez esté muerto, o viva aún como agente de la Plaga.\n\nEn cualquier caso, es un monstruo.", "Devlin nos advirtió que si intentábamos enfrentarnos a la Plaga, estaríamos condenados. Nos lo dijo cuando entró por primera vez en los Claros de Tirisfal, antes de que rodearan nuestro hogar. Quizás estaba suplicando que nos marcháramos, o quizás se deleitaba.\n\nSiempre ha sido difícil comprender las razones de Devlin. Desde que era niño, siempre fue un misterio para nosotros.", "Pero tenía razón. Estábamos perdidos. La familia Agamand está condenada a la desaparición. Aunque yo viva aún, sé que pronto moriré.\n\nNo tengo miedo, y no lamento haberme quedado con los míos. Pero debes saber que mi último pensamiento te lo dedicaré a ti.\n\nSigue con vida, mi amada Yvette, para poder irme en paz,\n\nThurman" } } },
    ["Tinkee's Letter"] = { { ids = { "i12438" }, first = "hifelnokmystudiesinthebu", pages = { "¡Hola, Felnok!\n\nMis estudios en las Estepas Ardientes avanzan con éxito. ¡Y debo mucho a $N por su gran ayuda! Esto es lo que necesito para continuar:\n\nUna bobina de acero basuragorda\nUna llave de hielo calibre 17\n6 kilos de plumas de pato\nUn bote de ese pegamento que tú fabricas\n\nMuchas gracias, Felnok, y cuando nos volvamos a ver, ¡recuérdame que no vuelva a meter carbón en tus botas!\n\n-Tinkee" } } },
    ["Toothgnasher's Skeleton"] = { { ids = { "o175683" }, first = "thisisascalereplicaoftoo", pages = { "Esta es una réplica a escala de un esqueleto de rechinador. Este legendario carnero fue el asombro de Khaz Modan y el protagonista de muchas historias del folklore popular enano. Hasta el momento, los ecologistas no han podido determinar el tamaño descomunal o la resistencia física de este carnero." } } },
    ["Torn Letter"] = { { ids = { "i216956" }, first = "duetoyourcovensstaggerin", pages = { "Debido a la asombrosa ineptitud de vuestro aquelarre, no uno, sino dos grupos de intrusos lograron atravesar vuestras defensas, causar numerosas bajas y robar lo que nos pertenece. Yo me ocuparé de la Cruzada Escarlata, pero necesito que vuestro patético aquelarre reúna la competencia necesaria para encontrar al paladín y su cómplice y recuperar...\n\n<La carta está rota y falta el resto.>" } } },
    ["Torn Note"] = { { ids = { "i4102" }, first = "imissmytribeandmyhomeiwo", pages = { "Echo de menos a mi tribu, mi hogar. Prefiero mil veces el viento de las extensas planicies o el atardecer en Cima del Trueno al calor de esta jungla.\n\nPuedo ver el océano desde aquí, pero esto no refresca mi cuerpo ni alivia mi ánimo. Solo me recuerda mi encarcelamiento." } } },
    ["Torn Page"] = { { ids = { "i281347" }, first = "thecalmcomesbeforethesto", pages = { "La calma llega tras la tormenta." } } },
    ["Translated Letter"] = { { ids = { "i1656" }, first = "greetingselloebonlockema", pages = { "Saludos, Ello Ebonlocke, Alcalde de Villa Oscura. Me temo que traigo noticias para tu ciudad. Noticias graves.\n\nSabes, soy un creador. He engañado al portador de esta nota para que me ayudase en mi última y más directa creación: ¡un demonio de carne, hueso y metal retorcido! Cuando leas esto, esta bestia estará junto a mi humilde morada, rechinando sus dientes y esperando mis órdenes para masacrar a alguien.\n\nPronto tendrás noticias mías.\n\nEl embalsamador" } } },
    ["Translated Letter from The Embalmer"] = { { ids = { "i3248" }, first = "greetingselloebonlockema", pages = { "Saludos, Ello Ebonlocke, Alcalde de Villa Oscura. Me temo que traigo noticias para tu ciudad. Noticias graves.\n\nSabes, soy un creador. He engañado al portador de esta nota para que me ayudase en mi última y más directa creación: ¡un demonio de carne, hueso y metal retorcido! Cuando leas esto, esta bestia estará junto a mi humilde morada, rechinando sus dientes y esperando mis órdenes para masacrar a alguien.\n\nPronto tendrás noticias mías.\n\nEl embalsamador" } } },
    ["Trevan's Weapon Notes"] = { { ids = { "i267454" }, first = "oldfireeyeisamagicalcrea", pages = { "$N:\nEl Old Fire-Eye es una criatura mágica de la noche y, como tal, necesitamos un arma mágica que también sea de la noche. Podemos infundirla con la luz de la luna llena y usarla para volver contra la criatura la magia oscura que la impulsa. Para ello necesitamos materiales concretos con los que forjar una hoja de brillante plata lunar capaz de destruir por completo este mal.\n\nNo será fácil, pero has mostrado un gran potencial y confío en que consigas lo que necesitamos.", "Plata lunar encantada: es el ingrediente clave. La plata lunar es un material increíblemente raro, hecho de plata encantada infundida con el poder bruto de la luna. Se forjaron varias armas para combatir a los ferocanis cuando la maldición empezó a extenderse por Argénteos. Por desgracia, todas se han perdido y se desconoce dónde están los últimos lingotes de plata lunar.\n\nSe rumorea que había una reserva en el Castillo de Colmillo Oscuro, al sur. Es una posibilidad remota, pero nuestra mejor opción para encontrar algo de esa plata.", "Buena madera de roble de piedra blanca: en Páramos de Poniente hay un lugar llamado Arroyo de la Luna donde antes abundaba. Los artesanos de la Alianza la usaron para reconstruir Ventormenta tras la Segunda Guerra.\n\nArroyo de la Luna atraviesa malos tiempos, pero he oído que una banda de bandidos ha contratado a talladores goblins para construir algo en las minas de debajo. Me jugaría la bota izquierda a que se quedaron con toda la madera rara que aún había en la villa cuando llegaron.", "Una gema Kor: por lo que me han contado, algunos hechiceros las usan para guardar energía para su magia, volviéndose aún más letales. Creo que podemos aprovechar la energía almacenada en una para crear tu arma.\n\nUn mago al que conocí, Ulric Frostveil, puede contarte más sobre estas gemas. Lo último que supe es que estaba en Kalimdor, en la Avanzada de Zoram'gar, al oeste de Vallefresno." } } },
    ["Uldaman Relics"] = { { ids = { "o175687" }, first = "theseancientpiecesofeart", pages = { "Estas antiguas piezas de barro se extrajeron de las excavaciones de Uldaman. Si bien es poco probable que se trate de sugerentes runas o jeroglíficos, ofrecen un aspecto revelador de la destreza con que la antigua raza enana fabricaba sus accesorios de uso cotidiano." } } },
    ["Uldaman Reliefs"] = { { ids = { "o175689" }, first = "theseetchedreliefrunners", pages = { "Estos corredores grabados en relieve son quizás el hallazgo más importante de las primeras cámaras de Uldaman. Los grabados sugieren que existió un fuerte vínculo entre los terráneos gólem y la raza enana. En el caso de que se encontraran pruebas adicionales, se podría demostrar que las teorías de nuestra supuesta creación por parte de los míticos titanes son ciertas." } } },
    ["Ur's Treatise on Shadow Magic"] = { { ids = { "i7266" }, first = "theswirlingsymbolsandpic", pages = { "Los símbolos y pictogramas arremolinados que llenan las páginas de este manual son demasiado esotéricos para comprenderlos." } } },
    ["Urgent Message"] = { { ids = { "i11886" }, first = "urgentmessagetocliffwatc", pages = { "Mensaje urgente para Vigiarrisco Cuernolargo\n\nUn gran ejército de centauros procedentes del campamento E'thok han atacado a nuestras caravanas de suministros. Todos los miembros de la caravana se perdieron junto con todas nuestras provisiones. Fue un ataque sin precedentes de los centauros y mucho me temo que habrá más." } } },
    ["Uther the Lightbringer"] = { { ids = { "o2082" }, first = "hereliesutherthelightbri", pages = { "Aquí yace Uther el Iluminado\nPrimer paladín, fundador de la orden de la Mano de Plata\n\nUther vivió y murió para defender el reino de Lordaeron. Aunque fue traicionado por su discípulo más amado, creemos que su espíritu pervive. Continúa observándonos, aun cuando las sombras acechen nuestra tierra desolada. Su luz es la luz de toda la humanidad y, siempre que hagamos honor a su memoria, esta nunca se perderá.\n\n- Anónimo" } } },
    ["Valea Twinblades"] = { { ids = { "o175780" }, first = "valeatwinbladeswarriorof", pages = { "Valea Filosgemelos\n\nGuerrera de la Cruzada Escarlata\n\nCiudadana de Alterac\n\nVista por última vez en lo profundo de Tierras de la Peste del Este" } } },
    ["Valory Family Crest"] = { { ids = { "i281328" }, first = "memoriesofvalorarecounto", pages = { "Memorias de los Valor\nUna crónica de la familia Valor y su servicio al Cerro del Cuervo\n\nNo había familia más grandiosa en todos los Reinos del Este que los Valor. Sus hazañas en defensa del pueblo al que juraron proteger fueron auténticos milagros, y su pérdida es una tragedia para el Cerro del Cuervo.\n\nEscribo este relato para que quede constancia de lo brillantes que fueron Grant, Ira, Silvia y Merrick. Que estas líneas sirvan de pequeño consuelo ante lo mucho que lamento su ausencia.", "Merrick Valor, guardia de Villa Oscura\n\nMerrick era el hijo menor de los Valor. Al ver cómo llegaba la corrupción a su patria, eligió unirse a la Guardia en un intento desesperado de proteger a sus seres queridos.\n\nAunque era el más inexperto de la familia, pronto se hizo un nombre entre los guardias. Tenía talento para el arco y se convirtió en uno de los defensores más firmes de Villa Oscura.\n\nSu misión personal era mantener seguros los caminos, atento a las criaturas cada vez más hostiles que llegaban a los bosques.", "Silvia Valor, guardia del Cerro del Cuervo\n\nSilvia Valor ya era toda una heroína local cuando le ofrecieron unirse a la guardia. Si había algo que no podía soportar más que nada en el mundo, eran los oportunistas que se aprovechaban de la gente en apuros.\n\nBandidos, estafadores, agitadores... Daba igual. Silvia acababa con ellos por tratar de sembrar el caos en su querido hogar. Era lógico que se le asignara un puesto de verdadera autoridad para que pudiera llevar a la práctica su visión de la justicia.\n\nSe dice que, hasta su último aliento, nunca abandonó las granjas y los hogares del Bosque del Ocaso. Y que quizá su vigilia tampoco acabara tras su muerte...", "Ira Valor, acechadora del bosque\n\nCuando el padre de Ira enfermó, ella se encargó de recoger comida y provisiones en los bosques cercanos. Aunque no faltaban recursos, era tan probable encontrar alimento como convertirse en él.\n\nCon los años se adaptó a los bosques y prefirió pasar el tiempo entre los árboles oscuros en vez de en el Cerro del Cuervo. Los viajeros perdidos contaban historias de una sombra que parecía abrirles el camino de vuelta a la carretera. Nadie confirmó quién era, pero los rumores corrieron deprisa.\n\nSe dice que Ira sigue en los bosques, ofreciendo una mano que guía a quienes caen presa de sus bestias.", "Lord Grant Valor, patriarca de la familia Valor\n\nLord Grant (que en paz descanse) fue el máximo exponente de la excelencia de la Alianza. Un líder nato, cuya mano firme guio a los habitantes del Cerro del Cuervo hacia la prosperidad. Cuando la oscuridad comenzó a tomar los bosques, fue el primero en movilizar a nuestro pueblo.\n\nPara lord Grant no existía enemigo más repugnante que los no-muertos. Patrullaba personalmente los cementerios del Bosque del Ocaso para mantener a raya a los siervos de la oscuridad. El día que recibió un golpe mortal, todos en la ciudad compartieron su dolor.\n\nGracias al cuidado de su familia, logró volver a sus obligaciones, pero, desde entonces, una persistente dolencia le acompañaría durante el resto de sus días.", "Lady Cassandra Valor, madre amantísima y amada esposa\n\nPoco se sabe sobre Cassandra, salvo su amor por su familia. Crio a unos hijos valientes y cuidó de un marido poderoso, lo que ha llevado a algunos a pensar que la grandeza de la familia se debía exclusivamente a ella. Un halago que la misma Cassandra siempre rechazaba con elegancia.\n\nSi no se la recuerda por nada más, que quede claro que todo lo que hizo fue por su familia." } } },
    ["Velinde's Journal"] = { { ids = { "i5520" }, first = "elunehasgrantedmywishest", pages = { "Elune ha cumplido mis deseos. Las vidas de mis camaradas caídos no serán en vano y vengaré sus muertes con la Guadaña de Elune. Es algo antiguo, una rama de madera retorcida y nudosa que podría ser más vieja que los propios kaldorei. Durante horas examiné la herramienta que me concedió la diosa. No es un arma corriente, eso está claro, ni un simple instrumento mágico. Con ella... es como si se debilitaran las barreras del tiempo y el espacio. Al sostener la Guadaña", "entre mis manos, recibí una visión de caos. Hombres lobo... los ferocanis... combatían a un enemigo increíble. Luchaban con el salvajismo propio de su raza primitiva, pero su enemigo no cedía: los Señores de la Llama Esmeralda. Entonces comprendí el verdadero poder de la Guadaña. Al concentrarme en ella pude comunicarme con los ferocanis. Sin embargo, no usé palabras. Era algo distinto... No sabría describirlo. Lo importante era que los ferocanis me oían", "y comprendían. Al canalizar más energía en la Guadaña, las barreras se debilitaron aún más y pude traer ferocanis a nuestro mundo. Logré invocar una treintena en mi primer intento. Me siguieron al combate y, con su fuerza brutal a mis órdenes, nos lanzamos contra los demonios de Frondavil. Elune ha cumplido mis deseos. El bosque será purificado. Que sus bendiciones me acompañen hasta terminar mi trabajo.", "Todo va bien. He invocado a más ferocanis para luchar a mi lado. Aunque son de mente sencilla, han mostrado una capacidad impresionante para coordinar sus ataques y actuar como grupo. He identificado dirigentes en sus manadas y les he dado el mando de pequeños grupos de guerreros. Atacamos muchos lugares del bosque a la vez y mi campaña contra los demonios da fruto. Que las bendiciones de Elune me acompañen hasta terminar mi trabajo.", "Una manada se ha perdido. Envié a los ferocanis a recorrer el bosque y localizar zonas infestadas de demonios, pero no volvieron. Empiezo a preocuparme por los dirigentes a los que confié el control. Son de mente sencilla y llevan al extremo la pequeña autoridad que les he dado. ¿Estoy perdiendo el control? Quizá deje de invocar más ferocanis de momento. Que las bendiciones de Elune me acompañen hasta terminar mi trabajo.", "Aunque no he invocado más ferocanis, su número sigue aumentando. Es como si la Guadaña ya no necesitara mi intervención para invocarlos. Resulta inquietante. He reunido a cuantas manadas he encontrado y les he ordenado permanecer en el Santuario de Mel'Thandris. Mientras tanto, he buscado en las bibliotecas de Darnassus y consultado al Círculo de los Ancestros en Costa Oscura. No he hallado ni una pizca de información sobre estos ferocanis. He oído noticias,", "susurros, de un mago del Kirin Tor llamado Arugal. Por lo que he oído, quizá también haya invocado ferocanis. Consultaría con ese mago, por desagradable que resulte, para averiguar lo que sabe. Los ferocanis son peligrosos y deseo contener su avance. Mañana viajaré al puerto de Los Baldíos y reservaré pasaje al Nuevo Mundo. Que las bendiciones de Elune me acompañen hasta terminar mi trabajo." } } },
    ["Venture Co. Documents"] = { { ids = { "i4834" }, first = "supervisorfizsprocketple", pages = { "Supervisor Fizsprocket: adjunto encontrarás la lista del equipo solicitado, aprobada por el presidente Razdunk. Me ha pedido recordar y recalcar el gran interés de Ventura y Cía. en establecer operaciones por todo Kalimdor. Nuestros puestos de perforación y minería de Los Baldíos han demostrado ser rentables y eficaces, pero aún esperamos cifras de producción suficientes en Mulgore, tu jurisdicción. La junta asesora comprende las dificultades de establecer", "una operación a gran escala tan cerca de la patria tauren, pero no considera que supongan un gran obstáculo para nuestro plan de negocio general en la zona. Nos alegra saber que ha comenzado la minería en las llanuras ricas en minerales de Mulgore. Por ello, la junta ha aprobado tu solicitud de equipo. Además de la minería, creemos que Mulgore también tiene mucho que ofrecer en madera, así que recibirás varias de nuestras trituradoras del último modelo y materias primas para construir un", "aserradero." } } },
    ["Verdant Note"] = { { ids = { "i9581" }, first = "thespiritscametomeinmydr", pages = { "La pasada noche, los espíritus se manifestaron en mis sueños. Me dijeron que vendrías y que mi tarea consistiría en ayudarte. Tenemos mucho que hacer en un corto espacio de tiempo: disquisiciones sobre la naturaleza, los espíritus, la Madre Tierra e incluso los elfos de la noche. Pero guardaré las lecciones para cuando llegues y haré todo lo que esté en mi mano para asegurarme de que estés $gpreparado:preparada; para afrontar las pruebas que tienes por delante.\n\nQue la sabiduría te guíe. Te estaré esperando.\n\nGart Correbruma, instructor de druidas" } } },
    ["Verdant Sigil"] = { { ids = { "i9580" }, first = "whenwordreachedmethatyou", pages = { "Cuando me llegó la noticia de que estabas $gpreparado:preparada;, envié inmediatamente este sigilo. Todos los druidas de Cenarius han mostrado gran satisfacción al ver que nuestros números aumentan. Incluso, los espíritus parecen ser más fuertes, debido a nuestra presencia reforzada. Con el tiempo y con un poco de paciencia, esperemos recuperar algo de nuestro antiguo esplendor. Cuando estés $gpreparado:preparada;, búscame cerca de la cima de Aldrassil. Seré tu guía durante todo el tiempo que estés en Cañada Umbría.\n\n Mardant Cebaforte, $ginstructor:instructora; de druidas" } } },
    ["Verna's Westfall Stew Recipe"] = { { ids = { "i2832" }, first = "westfallstewpartsstringy", pages = { "Estofado de Páramos de Poniente\n\n3 partes de carne fibrosa de buitre\n3 morros de dentosangre\n3 ojos de múrloc\n3 okras\n\nMezclar todos los ingredientes y poner a hervir. Hervir a fuego lento al menos durante dos horas antes de servir." } } },
    ["Verner's Note"] = { { ids = { "i1283" }, first = "argusasyouknowimuptomyne", pages = { "Argus:\n\nComo ya sabéis, estoy harto de recibir solicitudes de reparación por parte del ejército. No puedo quejarme por tanto trabajo, pero lo cierto es que están agotando mis reservas de hierro.\n\nNo tengo suficiente hierro para herraduras. Sé que siempre dispones de abundantes reservas, por eso quería pedirte prestados 50 pares de herraduras hasta que consiga mi próximo cargamento de hierro.\n\nTe lo agradezco de antemano,\nVerner" } } },
    ["Wanted Notice"] = { { ids = { "i221314" }, first = "knowntrespasserspyinterr", pages = { "<El boceto de la cara de un enano ocupa casi toda la nota. Debajo incluye unas líneas escritas>.\n\n¡Intruso! ¡Espía! ¡Interroga a nuestros ciudadanos!\n\nVarias parejas que han visitado la Ciudad Forjatiniebla hablan sobre breves encuentros con un enano con acento extraño a quien oyeron decir repetidas veces: \"No son los dos que buscamos\".\n\n¡Informen a cualquier oficial de Yunque Colérico si tienen información!\n\nVayan con cuidado. Ningún grupo grande se ha encontrado con este sujeto misterioso.\n¡Estén atentos!" } } },
    ["War of the Spider"] = { { ids = { "o175753" }, first = "whilethrallwasliberating", pages = { "Mientras Thrall liberaba a sus hermanos en Lordaeron, Ner'zhul continuaba incrementando su base de poder en Rasganorte. Se erigió una gran ciudadela por encima del glaciar Corona de Hielo y fue ocupada por las crecientes legiones de muertos. Aun cuando el rey Exánime extendía su influencia sobre la tierra, un misterioso imperio resistió su poder.", "El antiguo reino subterráneo de Azjol-Nerub, que había sido fundado por una raza de siniestras arañas humanoides, envió a su guardia de élite para atacar Corona de Hielo y terminar con el loco apetito de dominio del rey Exánime. Para su frustración, Ner'zhul comprobó que los malvados nerubianos resultaban inmunes no solo a la peste, sino también a su dominio mediante la telepatía.", "Los señores araña nerubianos dirigían grandes ejércitos y tenían una red subterránea que abarcaba prácticamente la mitad de Rasganorte. Sus tácticas, que consistían en golpear y escapar de las fortalezas del rey Exánime, frustraron sus esfuerzos por acabar con ellos una y otra vez. Finalmente, Ner'zhul ganó la guerra contra los nerubianos mediante una estrategia de desgaste. Con la ayuda de los siniestros Señores del Terror y de innumerables guerreros no-muertos, el rey Exánime invadió Azjol-Nerub y tomó sus templos subterráneos, aplastando las cabezas de los señores araña.", "Aunque los nerubianos eran inmunes a su peste, los crecientes poderes necrománticos de Ner'zhul le permitieron resucitar los cadáveres de los guerreros araña, logrando que siguieran su voluntad. Como testamento de su tenacidad y valor, Ner'zhul adoptó el estilo arquitectónico distintivo de los nerubianos en sus propias fortalezas y estructuras.", "Pudiendo gobernar su reino sin oposición, el rey Exánime empezó a prepararse para llevar a cabo su verdadera misión en el mundo. Intentando alcanzar las tierras humanas con su vasta conciencia, el rey Exánime convocó a todas las almas oscuras que pudieron escucharle..." } } },
    ["War of the Three Hammers"] = { { ids = { "o175739" }, first = "thedwarvesofironforgemou", pages = { "Los enanos de la montaña de Forjaz vivieron en paz durante muchos siglos. Sin embargo, su sociedad creció demasiado dentro de los confines de sus montañosas ciudades. Aunque el poderoso gran rey Modimus Yunquemar reinó entre los enanos con justicia y sabiduría, tres poderosas facciones se habían rebelado contra la sociedad enana.", "El clan Barbabronce, dirigido por el señor feudal Madoran Barbabronce, mantenía estrechos lazos con el gran rey, siendo los tradicionales defensores de la montaña de Forjaz. El clan Martillo Salvaje, dirigido por el señor feudal Khardros Martillo Salvaje, habitaba en las estribaciones y los riscos situados alrededor de la base de la montaña e intentaba incrementar su grado de control sobre la ciudad.", "La tercera facción, el clan Hierro Negro, estaba dirigido por el hechicero y señor feudal Thaurissan. Los Hierro Negro se ocultaban entre las oscuras sombras de la montaña y complotaban contra sus primos Barbabronce y Martillo Salvaje.", "Durante un tiempo, las tres facciones mantuvieron una frágil paz, pero las tensiones terminaron por explotar cuando murió el gran rey Yunquemar. Los tres clanes lucharon por el control de Forjaz. La guerra civil de los enanos se desarrolló bajo tierra durante muchos años. Finalmente, los Barbabronce, que disponían del ejército más poderoso, desterraron a los Hierro Negro y a los Martillo Salvaje de las profundidades de la montaña.", "Khardros y sus guerreros Martillo Salvaje viajaron hacia el norte, atravesando las puertas de la barrera de Dun Algaz y fundaron su propio reino en las entrañas de la distante montaña de Grim Batol. Allí, los Martillo Salvaje prosperaron y volvieron a recuperar sus tesoros. A Thaurissan y a los Hierro Negro no les fue tan bien. Humillados y airados por su derrota, juraron venganza contra Forjaz. Conduciendo a su gente hacia el sur, Thaurissan fundó una ciudad (a la que puso su propio nombre) dentro de las bellas montañas Crestagrana.", "La prosperidad y el paso de los años no lograron calmar el rencor de los Hierro Negro contra sus primos. Thaurissan y su mujer hechicera Modgud, lanzó un asalto en dos flancos contra Forjaz y Grim Batol al mismo tiempo. Los Hierro Negro intentaron reclamar la posición de la totalidad de Khaz Modan.", "Los ejércitos de los Hierro Negro se lanzaron contra las fortalezas de sus primos y estuvieron muy cerca de tomar ambos reinos. No obstante, Madoran Barbabronce condujo a su clan a una victoria decisiva sobre el ejército de hechiceros de Thaurissan. Thaurissan y sus siervos huyeron para refugiarse en su ciudad, sin ser conscientes de lo que estaba ocurriendo en Grim Batol, donde el ejército de Modgud no lo estaba haciendo mejor contra Khardros y sus guerreros Martillo Negro.", "Al enfrentarse a los guerreros enemigos, Modgud utilizó sus poderes para insuflar el temor en sus corazones. Bajo sus órdenes, las sombras se pusieron en marcha y surgieron oscuros objetos desde las profundidades de la tierra que acecharon a los Martillo Salvaje en sus propias salas. Finalmente, Modgud atravesó las puertas y puso la fortaleza bajo sitio. Los Martillo Salvaje lucharon desesperadamente y el propio Khardros acometió las agitadas masas para asesinar a la reina hechicera.", "Perdida su reina, los Hierro Negro huyeron ante la furia de los Martillo Salvaje. Escaparon hacia el sur en dirección a la fortaleza de su rey y se encontraron con los ejércitos de Forjaz, que habían acudido en ayuda de Grim Batol. Cogidas entre dos fuegos, las fuerzas restantes de los Hierro Negro fueron destruidas por completo.", "Posteriormente, los ejércitos conjuntos de Forjaz y Grim Batol se dirigieron al sur, intentando destruir a Thaurissan y a sus Hierro Negro de una vez por todas. No pudieron ir muy lejos cuando la furia de Thaurissan se materializó en un encantamiento de proporciones catastróficas. Al intentar conseguir la ayuda de un esbirro sobrenatural que garantizara su victoria, Thaurissan despertó antiguos poderes que dormían en el submundo. Para su sorpresa y, finalmente, para su condena, la criatura que emergió fue más terrible que cualquier pesadilla que pudiera imaginar.", "Ragnaros, el Señor de Fuego, señor inmortal de todos los elementos flamígeros, había sido desterrado por los titanes cuando el mundo era joven. Ahora, liberado por la llamada de Thaurissan, Ragnaros volvió a la existencia una vez más. El renacimiento apocalíptico de Ragnaros en Azeroth hizo añicos las montañas Crestagrana y creó un rugiente volcán situado en el centro de la devastación.", "El volcán, conocido como la montaña Roca Negra, limitaba al norte con la Garganta de Fuego y al sur con las Estepas Ardientes. Si bien Thaurissan fue asesinado por las fuerzas que lo habían liberado, sus hermanos que le sobrevivieron finalmente fueron esclavizados por Ragnaros y sus elementales. Hasta el día de hoy, permanecen en las profundidades de Roca Negra.", "Habiendo presenciado la horrenda devastación, donde los fuegos se extendían a lo largo de las montañas del sur, el rey Madoran y el rey Khardros detuvieron sus ejércitos y regresaron a toda prisa hacia sus respectivos reinos, incapaces de hacer frente a la ira de Ragnaros.", "Los Barbabronce regresaron a Forjaz y reconstruyeron la gloriosa ciudad. Asimismo, los Martillo Salvaje regresaron a casa en Grim Batol. Sin embargo, la muerte de Modgud dejó una pátina maléfica sobre la fortaleza de la montaña y resultó ser inhabitable.", "Los corazones de los Martillo Salvaje sentían la amargura que suponía la pérdida de su amado hogar. El rey Barbabronce ofreció a los Martillo Salvaje un lugar donde vivir, situado en los límites de Forjaz, pero estos se negaron en redondo. Khardros condujo a su gente hacia el norte en dirección a las tierras de Lordaeron. Asentados en los exuberantes bosques de las tierras del interior, los Martillo Salvaje construyeron la ciudad de Pico Nidal, en donde los Martillo Salvaje crecieron cerca de la naturaleza e, incluso, se vincularon a los poderosos grifos de la región.", "Al intentar conservar las relaciones y el comercio con sus primos, los enanos de Forjaz construyeron dos grandes arcos, el Puente Thandol, que une Khaz Modan con Lordaeron. Enriquecidos mediante el comercio mutuo, los dos reinos prosperaron. Tras las muertes de Madoran y Khardros, sus hijos encargaron conjuntamente la construcción de dos grandes estatuas en honor a sus padres.", "Las dos estatuas guardarían el paso hacia las tierras del sur que, en presencia del ardiente Ragnaros, se habían convertido en tierras volcánicas. Sirvieron tanto como advertencia a aquellos que pretendían atacar los reinos de los enanos, como recordatorio del precio que pagaron los Hierro Negro por sus crímenes.", "Los dos reinos mantuvieron estrechos lazos durante años, pero los Martillo Salvaje cambiaron en gran medida a causa de los horrores que presenciaron en Grim Batol. En lugar de excavar un vasto reino en el interior de la montaña, decidieron vivir en la superficie, en las laderas de Pico Nidal. Las diferencias ideológicas entre los dos clanes de enanos que quedaban condujeron finalmente a su separación." } } },
    ["Warchief's Orders"] = { { ids = { "i8463" }, first = "commanderreturntoorgrimm", pages = { "Comandante,\n\nregresa a Orgrimmar. Tus fuerzas son insuficientes. Debemos volver a analizar nuestra posición en base a los nuevos datos.\n\nHay un gran número de miembros del clan Sombrajurado y ogros. Los demonios vigilan el Portal Oscuro.\n\n-Thrall, Jefe de Guerra de la Horda" } } },
    ["Warosh's Scroll"] = { { ids = { "i12730" }, first = "ohiamcursedonceagreatogr", pages = { "¡Oh, estoy maldito! Otrora gran mago ogro del clan Cumbrerroca, desafié a Urok Aullapocalipsis y este me robó mi magia y me maldijo. ¡Ahora debo recorrer las salas de Hordemar como una desgraciada criatura!\n\n¡Ayudadme! ¡Enfrentaos a Urok y recuperad mi magia! No será fácil, ya que Urok permanece en las sombras y solo puede ser invocado a través de un gran desafío.\n\nEste desafío será la muerte de su ayudante más fiel, Alto Señor Omokk.\n\nContinúa leyendo y verás.", "El Alto Señor Omokk gobierna a los Cumbrerroca, pero lo hace utilizando la magia de Urok. Urok embrujó a Omokk con un encantamiento que puede conducir a la muerte a cualquier ogro que ose desafiarlo. Ha utilizado este encantamiento muchas veces y apila los cráneos de sus víctimas en un recinto de poder situado encima de la cámara de Omokk.\n\nAllí es donde debes ir para enfrentarte a Urok.", "Encuentra un basto pico sobre los campos del Escudo del Estigma. Suelen clavarlos junto a sus colchones, cerca de la entrada de los dominios del ogro Cumbreroca.\n\nCuando obtengas el pico, carga contra el Alto Señor Omokk. Mátalo y coloca su cabeza sobre el pico.\n\nentonces estarás $gpreparado:preparada; para el verdadero reto.", "Ve al lugar de poder situado encima del dominio de los Cumbrerroca, más allá de los Túneles de Arácnidas. En aquel lugar están apilados los cráneos de los enemigos y rivales de Urok. ¡Aquí es donde debes colocar el pico con la cabeza de Omokk!\n\nCuando la cabeza esté en su sitio, Urok vendrá... pero primero enviará a sus esbirros que te atacarán. Derrótalos y, transcurrido un tiempo, aparecerá Urok en persona.\n\nMata a Urok y recupera mi magia. Cuando recuperes mis poderes, te recompensaré.", "Buena suerte. He aquí una pista que podrá ayudarte cuando te enfrentes a los esbirros de Urok:\n\nEl encantamiento que utiliza Omokk contra los ogros, el que los lleva a la muerte, puede continuar activo aun después de muerto Omokk. Cuando luches contra los esbirros de Urok, invoca el poder en la cabeza de Omokk. ¡Con suerte, Omokk acabará con los esbirros de Urok!\n\n¡Vaya ironía!" } } },
    ["White Punch Card"] = { { ids = { "i9279" }, first = "supercriticaltripleencod", pages = { "TARJETA DE DATOS SUPER CRÍTICA CON CODIFICACIÓN TRIPLE\n\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" } } },
    ["Wiley's Note"] = { { ids = { "i1327" }, first = "stoutmantlesomenervesend", pages = { "Mantorrecio:n\nHay que tener osadía para enviar a un total desconocido a tratar el asunto de la banda Defias. Salvaste mi vida una vez y ahora la pones gravemente en peligro.\n\nNo obstante, estoy en deuda contigo. La Hermandad Defias es más grande de lo que crees. Todas las minas de los Páramos de Poniente al bosque de Elwynn están bajo su control. Kobolds y gnolls han sido reclutados para hacer el trabajo sucio. Tienen a los goblins fabricando monstruos metálicos para colocarlos en los campos de los Páramos de Poniente y así alimentar las supersticiones de los habitantes de la zona.", "Han mandado construir una extensa red subterránea. Más grande de lo que te puedes imaginar, Mantorrecio. De la Bahía del Botín hasta el Castillo de Ventormenta. Podrás ser un valiente paladín, pero no estás en tu sano juicio si crees que puedes detenerlos. Están trabajando en la construcción de armas de destrucción masiva. Después de todo, si hay algo que la hermandad de los Albañiles sabe es cómo erigir grandes construcciones. No habrás creído que se trataba de granjas de hortalizas o de viñedos, ¿verdad? Te he devuelto el favor. ¡Ahora déjame en paz!\n\nW" } } },
    ["William's Shipment"] = { { ids = { "i957" }, first = "hellomorganbusinessingol", pages = { "Hola, Morgan,\n\nLos negocios en Villadorada van muy bien, tan bien que no he tenido tiempo de hacerte ningún envío.\n\nHe encargado al portador de esta nota que entregue un paquete de velas de cera grandes (sabes a cuáles me refiero, ¿no?, las que los kobolds suelen llevar en sus cabezas).\n\nTe ruego que se lo agradezcas a esta persona de nuestra parte y le pagues lo que sea justo." } } },
    ["Words of the High Chief"] = { { ids = { "i13158" }, first = "attackersfromallsidescan", pages = { "Nos atacan... desde todas partes.\n\nPuedo verlo en sus ojos. Fauces de Madera es el demonio. Enemigo.\n\nDebes proteger a la tribu. Debes proteger a Nevada. Debes expulsar a los intrusos de nuestras tierras.", "Nieve, cegadora...\n\nHay que proteger a la tribu. Haz que sean fuertes. Sed fuertes.\n\nNo se sabe...", "Aguardiente.\n\nHaz más. Más aguardiente.\n\nEl aguardiente fortalece al clan Nevada. Derrotemos a nuestros enemigos.\n\nLos Nevada no tenemos aliados. Los Nevada somos fuertes. Tenemos un enorme poder.", "Más. Debo tener más...\n\nNevada... no... débil..." } } },
    ["Wrath of Soulflayer"] = { { ids = { "o175856" }, first = "thelongcenturiesfollowin", pages = { "Los largos siglos que siguieron al Gran Cataclismo del mundo resultaron difíciles para la raza trol. El hambre y el terror eran moneda común en sus disgregados reinos. Los trols Gurubashi, conducidos a un final desesperado, buscaron ayuda en fuerzas místicas y ancestrales. Si bien ambos reinos trol compartían una creencia central en un gran panteón de dioses primitivos, los Gurubashi empezaron a adorar al más oscuro de ellos.", "Hakkar el Cazador de Almas, espíritu vil y sanguinario, oyó la llamada de los trols y decidió ayudarlos. Hakkar compartió sus secretos de sangre con los Gurubashi y les ayudó a extender su civilización a lo largo de la mayor parte de la Vega de Tuercespina y ciertas islas de los Mares del Sur. Si bien les proporcionó un gran poder, Hakkar quería más y más para sus propósitos.", "El dios sanguinario pidió que se sacrificaran almas en su altar diariamente. Tenía intención de lograr el acceso al mundo físico para así poder beber la sangre de todas las criaturas mortales. Con el tiempo, los Gurubashi se dieron cuenta de la clase de criatura con la que habían estado tratando y se volvieron en su contra. Las tribus más poderosas se rebelaron contra Hakkar y sus leales sacerdotes, los Atal'ai.", "La terrible guerra que siguió entre los seguidores de Hakkar y el resto de las tribus Gurubashi solo se comenta en susurros. El imperio en ciernes fue destruido por la magia desatada entre el airado dios y sus criaturas rebeldes. Cuando la batalla parecía estar perdida, los trols lograron destruir el avatar de Hakkar, desterrándolo del mundo.", "Incluso sus sacerdotes Atal'ai fueron expulsados de la capital de Zul'Gurub y obligados a sobrevivir en los ignotos pantanos del norte. En esos terrenos pantanosos construyeron un gran templo al dios caído, Atal'Hakkar, donde pudieran continuar con la obra de su maestro...", "El resto de las tribus Gurubashi se dispersaron tras la gran guerra civil que dejó sus tierras en ruinas. Las tribus Machacacráneo, Sangrapellejo y Lanza Negra marcharon con el fin de reclamar sus propias tierras en el interior de las vastas junglas de Tuercespina. Si bien hubo un momento de frágil paz en el imperio disgregado, algunos hablaban de una profecía según la cual un día Hakkar volvería a nacer en el mundo y, en ese momento, lo reduciría a cenizas." } } },
    ["Yana Bloodspear"] = { { ids = { "o175781" }, first = "yanabloodspearthesecondc", pages = { "Yana Lanza de Sangre\n\nSegunda asesina jefe de la Cruzada Escarlata\n\nCiudadana de Dalaran\n\nDesaparecida en los Claros de Tirisfal" } } },
    ["Yellow Punch Card"] = { { ids = { "i9280" }, first = "ultravitaldatasecurityra", pages = { "¡DATOS ULTRAVITALES! ¡NIVEL DE SEGURIDAD 5122!\n\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101" } } },
    ["Yuriv's Tombstone"] = { { ids = { "o24777" }, first = "thewordbetrayeriscrudely", pages = { "La palabra TRAIDOR aparece escrita toscamente sobre el epitafio finamente grabado, cuyo texto dice:\n\nAquí yace Yuriv.\nPadre, esposo y paladín.\nSus hijos deberán saber que su dedicación a la Luz fue incuestionable.\nNunca exigió a los demás nada que él no hiciera." } } },
    ["Zamah's Note"] = { { ids = { "i5628" }, first = "apothecarylydonihopethis", pages = { "Boticario Lydon,\n\nEspero que esta carta les llegue rápidamente y que su portador se encuentre sano y salvo. En el lejano Kalimdor han tenido lugar ciertos acontecimientos que hacen que requiramos de tus servicios.\n\nSeré breve.\n\nHay una crisis en la Sierra Espolón, cerca de Mulgore, tierra natal de los aliados tauren. La empresa goblin Ventura y Cía está extrayendo todo el mineral y talando toda la vegetación en aquellas montañas, enfureciendo a los espíritus de la montaña.", "Imagino que la conmoción que estos espíritus les causan a través de los chamanes y druidas tauren los distraen. Y es que los tauren consideran la presencia de Ventura y Cía. en la Sierra Espolón una seria amenaza.\n\nTanto si son una amenaza como si no lo son, debemos ayudar a nuestros aliados.\n\nLydon, posees un vasto conocimiento sobre toxinas. ¿Podrías crear una que pudiéramos usar para extender una plaga entre los goblins en la Sierra Espolón?\n\nRecibe un sabio saludo,\nP. Zamah" } } },
  },
  -- on Classic, its own names for the places Forever renamed (the longest first)
  classic = {
    { "Baños de Fuego de Escarcha", "Baños Escarchados" },
    { "El Páramo de los Ancianos", "Páramo de los Ancestros" },
    { "La Empalizada de Mor'shan", "La Muralla de Mor'shan" },
    { "Bastión Fauces de Madera", "Bastión de los Fauces de Madera" },
    { "Destilería Cebatruenos", "Destilería Thunderbrew" },
    { "Cuartel de Arroyoeste", "Cuartel Arroyoeste" },
    { "Excavación de Limugre", "Excavación de Grimesilt" },
    { "La Espada del Maestro", "El Glaive del Maestro" },
    { "La Ensenada de Zoram", "La Ensanada de Zoram" },
    { "Campamento Grom'gol", "Campamento Grom'Gol" },
    { "Guarida de Alanegra", "Guarida Alanegra" },
    { "Serpiente Enroscada", "La Escama de la Serpiente" },
    { "Tranvía Subterráneo", "Tren subterráneo" },
    { "Túmulo de Ban'ethil", "Túmulo de Ben'ethil" },
    { "Isla de Theramore", "Isla Theramore" },
    { "Zahúrda Rajacieno", "Zahúrda Rojocieno" },
    { "Escara Impía", "Escara Ímpia" },
  },
  pages = {
    ["abyssal-council"] = {
      title = "El Consejo Abisal",
      text = {
        { "Los cultores del Martillo Crepuscular se reúnen ante piedras de invocación en Silithus. Con blasones, tablillas y textos de poder llaman a templarios, duques y señores del fuego, aire, agua y tierra: los sirvientes del Consejo Abisal. Cada rito puede traer al desierto un elemental más poderoso." },
        { "El Círculo Cenarion quiere detener al culto y apoderarse de sus textos. Las piedras están en el mismo desierto que Ahn'Qiraj, una cercanía que consuela poco." },
      },
    },
    ["aerie-peak"] = {
      title = "Pico Nidal",
      text = {
        { "Pico Nidal es el hogar de los enanos Martillo Salvaje, una población de salones de piedra y nidos de grifos construida en un risco del extremo occidental de Tierras del Interior. Tiene el mejor aviario de grifos del mundo. Todo enano de Forjaz que haya volado en grifo debe agradecérselo a un Martillo Salvaje." },
        { "No es Forjaz. Aquí no hay grandes forjas, hay pocos muros y aún menos techos. Los Martillo Salvaje viven al aire libre, se tatúan la piel y hablan con los espíritus de la tierra. Un enano de Forjaz se siente algo fuera de lugar en Pico Nidal. Esa es la intención." },
      },
    },
    ["agamaggan"] = {
      title = "Agamaggan",
      text = {
        { "Durante la Guerra de los Ancestros, hace diez mil años, los semidioses de la naturaleza se alzaron contra la Legión Ardiente. Entre ellos estaba Agamaggan, un gran jabalí. Cayó. Donde su sangre empapó la tierra de Los Baldíos crecieron espinas colosales y se formaron piedras de un rojo sangriento. Los jabaespines viven entre esas espinas, se llaman sus hijos y llevan las piedras como tótems." },
        { "Sus chamanes aún recurren a su poder y un prisionero del Campamento Taurajo comparte sus bendiciones por el precio adecuado. Las grandes madrigueras espinosas del sur, Rajacieno, son su tumba y los jabaespines las consideran sagradas." },
      },
    },
    ["algaz"] = {
      title = "Algaz",
      text = {
        { "El camino que sale de Loch Modan hacia el norte atraviesa Dun Algaz, un paso estrecho abierto en las montañas hacia Los Humedales, vigilado por ambos extremos." },
        { "En nuestro lado, los montaraces de la Estación de Algaz vigilan el camino y las colinas cercanas. Los troggs aparecen en el paso más a menudo de lo deseable, y Los Humedales del otro lado no son amigos de los enanos desde que llegaron los Hierro Negro." },
        { "Cuando cruces el paso, fíjate en la piedra. Lleva muchísimo tiempo trabajada por manos enanas." },
      },
    },
    ["alonsus-faol"] = {
      title = "Alonsus Faol",
      text = {
        { "Alonsus Faol dirigía a los clérigos de Villanorte antes de la Primera Guerra. Cuando cayeron Ventormenta y su abadía, el anciano marchó al norte con los refugiados. En Lordaeron, ya como arzobispo, dio una espada a la Iglesia de la Luz Sagrada: fundó los Caballeros de la Mano de Plata y ungió a su aprendiz, Uther, como el primero de los paladines." },
        { "Su labor fue más allá del campo de batalla. Una placa de la catedral de Ventormenta dice que la comenzó en Stratholme, ayudó a reorganizar la Hermandad de Villanorte tras la Segunda Guerra y reunió los fondos para reconstruir la propia Ventormenta. Murió antes de que llegara la peste, de algo tan sencillo como la vejez, que se sepa." },
        { "Se dice que aquí descansa. Antes de la Plaga era un lugar de peregrinación. Ahora reúne a los muertos del Monasterio Escarlata y nadie viene a llorarlo. Merecía algo mejor, al igual que la orden que fundó." },
      },
    },
    ["altar-of-storms"] = {
      title = "Altar de la Tempestad",
      text = {
        { "El Altar de la Tempestad se alza a la sombra de la Cumbre de Roca Negra, un lugar superviviente de los ritos de los brujos de la antigua Horda. Durante la Segunda Guerra, la magia realizada en altares como este transformó a los ogros en ogros magos, dotándolos de astucia y del poder de lanzar hechizos." },
        { "Los brujos Roca Negra aún se reúnen aquí. Mor'zul Sangredoble, que ha estudiado el altar, acampa cerca y envía a otros brujos a cumplir sus propios encargos." },
      },
    },
    ["alterac-mountains"] = {
      title = "Montañas de Alterac",
      text = {
        { "La nieve cubre buena parte de Alterac, pero ha hecho poco por ocultar la caída del reino. Castillos derruidos dominan poblaciones del Sindicato, los ogros ocupan la antigua capital y los caminos ascienden junto a cuevas que ahora pertenecen a yetis. Estas alturas fueron un pequeño y orgulloso reino humano cuyo rey traicionó a la Alianza en la Segunda Guerra." },
        { client = "classic", "Junto al Lago Lordamere, una cúpula violeta encierra la reconstrucción de Dalaran. Los magos han sobrevivido a la destrucción de su ciudad y vuelto a empezar, aunque permiten pocos testigos de las obras." },
        { client = "forever", "Junto al Lago Lordamere, la reconstrucción de Dalaran se ha topado con otra calamidad. La alteración de las líneas Ley ha vuelto a los constructos de la ciudad contra sus habitantes. La archimaga Modera busca la ayuda exterior que el consejo preferiría no necesitar." },
        { "Más adentro de las montañas, los Lobo Gélido y los Pico Tormenta luchan por el Valle de Alterac. El reino ha desaparecido, $gviajero:viajera;. Las disputas sobre quién puede vivir en sus colinas le han sobrevivido." },
      },
    },
    ["alterac-valley"] = {
      title = "Valle de Alterac",
      text = {
        { "En el sur de las Montañas de Alterac hay un valle oculto que dos pueblos reclaman. Los orcos del clan Lobo Gélido llevan una generación en su extremo sur, desde que el brujo Gul'dan los exilió allí. Los enanos del clan Pico Tormenta llegaron después para excavar: minerales y reliquias del pasado remoto de nuestro pueblo que la Liga de Expedicionarios cree enterradas bajo el hielo." },
        { "Los Lobo Gélido vieron invasores. Los Pico Tormenta vieron orcos que entorpecían una investigación honrada, y desde entonces el rey Magni les ha dado una orden real de tomar el valle para Forjaz. Ahora ambos combaten con ejércitos, fortalezas, cementerios y minas, y piden ayuda a todos sus aliados. Ojalá pudiera decir que la Liga no tuvo nada que ver." },
      },
    },
    ["alterac-valley-tune"] = {
      title = "Valle de Alterac",
      text = {
        { "El Valle de Alterac no tiene música propia. Sus seis piezas son prestadas de los bosques viles, los poblados furbolg y las tierras de la plaga. Orcos y enanos dicen que el valle es suyo, y cada bando llama a sus aliados para conservarlo. Las órdenes de mi propio rey forman parte de esa disputa, y estoy demasiado cerca de su trono para juzgarla con justicia." },
      },
    },
    ["ambermill"] = {
      title = "Molino Ámbar",
      text = {
        { "Molino Ámbar es una aldea del este de Argénteos que aún resiste a los Renegados gracias a los magos de Dalaran. El Kirin Tor ha enviado hechiceros, protectores y carros de suministros desde Trabalomas, mucha atención para una aldea apartada." },
        { "Los Renegados han descubierto por qué: bajo Molino Ámbar hay un nodo latente de energía de las líneas Ley y Dalaran pretende despertarlo. Para qué, nadie en El Sepulcro lo sabe, y los magos no lo cuentan." },
      },
    },
    ["ancients"] = {
      title = "Los ancestros",
      text = {
        { "Los ancestros son los árboles más viejos de los bosques de los elfos de la noche, tan sabios que piensan y tan fuertes que caminan. En la Guerra de los Ancestros, Cenarius los llamó desde los bosques encantados y los condujo contra la Legión Ardiente: un ejército de hombres árbol marchando contra la propia ciudad de la reina. En la Tercera Guerra marcharon de nuevo." },
        { "Todavía vigilan. Los protectores ancianos montan guardia en Teldrassil, un Anciano del Conocimiento y un Anciano de la Guerra permanecen en Darnassus, y Onus, otro Anciano del Conocimiento, habla por el bosque en El Páramo de los Ancianos de Costa Oscura." },
        { "Hablan despacio y cambian de parecer aún más despacio. Supongo que un pueblo que plantó su capital en un árbol aprende a escuchar a los árboles." },
      },
    },
    ["andorhal"] = {
      title = "Andorhal",
      text = {
        { "Andorhal abastecía de grano al norte de Lordaeron. El Culto de los Malditos de Kel'Thuzad contaminó sus graneros y los cargamentos llevaron la peste a las aldeas de alrededor. Una población próspera se convirtió en un medio de propagar la muerte por la tierra que dependía de ella." },
        { "Arthas mató aquí a Kel'Thuzad mientras buscaba el origen de la peste. La muerte del nigromante no puso fin a su obra. Andorhal sigue en manos de la Plaga y Araj el Invocador gobierna sus ruinas. Tanto el Campamento del Orvallo como El Baluarte buscan la destrucción del exánime." },
        { side = "Horde", aside = true, sign = "P. F.", "La peste llegó al norte en el grano de Andorhal, no detrás de un ejército. Esa es la parte de la historia que primero se olvida." },
      },
    },
    ["anduin-lothar"] = {
      title = "Anduin Lothar",
      text = {
        { "Anduin Lothar fue el último del linaje Arathi, el de Thoradin, que unió por primera vez a la humanidad. Sirvió al rey Llane de Ventormenta como campeón y lugarteniente de armas. Fue Lothar quien asaltó Karazhan con el joven Khadgar y mató a Medivh, su viejo amigo, al comprender lo que había hecho el Guardián." },
        { "Volvió demasiado tarde para salvar Ventormenta, condujo a su pueblo por mar hasta Lordaeron y se convirtió en comandante supremo de la Alianza. Hasta los elfos de Quel'Thalas acudieron, aunque de mala gana, por la deuda con sus antepasados." },
        { "Murió aquí. Con la Horda encerrada en la Cumbre de Roca Negra, Orgrim Martillo Maldito salió a la carga con sus lugartenientes y se encontró con los paladines de Lothar en mitad de estas llanuras. Los dos combatieron hasta agotarse y Martillo Maldito lo mató. Su lugarteniente Turalyon recogió el escudo ensangrentado de Lothar y quebró a la Horda en la desbandada posterior. La expedición que más tarde atravesó el Portal Oscuro marchó como los Hijos de Lothar." },
      },
    },
    ["angor-fortress"] = {
      title = "Fortaleza de Angor",
      text = {
        { "La Fortaleza de Angor es el bastión del clan Forjatiniebla en las Tierras Inhóspitas, la plaza fuerte de los Hierro Negro desde la que trabajan en Uldaman. Llevan mucho tiempo tras los secretos de los titanes, y lo que más desean es el saber para construir gólems más poderosos. Grez Dedomaza también iba tras él, para que no cayera en sus manos, y él y Karnik el Historiador, de la Sala de los Exploradores, buscaban juntos los artefactos perdidos." },
        { "Los Forjatiniebla se llevaron a Dedomaza a Uldaman para averiguar lo que sabía. La ayuda que el prospector Ryedol envió tras él lo encontró moribundo. Dedomaza pidió una sola cosa, su amuleto, que Magregan Sombraprofunda le había quitado y que podía guiar a quien lo llevara hasta los pergaminos que todos buscaban. Cuando lo recuperaron, Dedomaza hizo que se lo llevaran a Ryedol, y Ryedol se lo hizo llegar a Karnik. Dedomaza buscaba el origen de nuestro pueblo, dijo Ryedol, y detener a los Forjatiniebla formaba parte de la misma obra. Karnik fue a consultar al espíritu de su viejo compañero, y el consejero Belgrum, con la autoridad del rey, ordenó atacar Angor." },
        { "El propio Ragnaros, según se supo, había enviado un embajador a Angor para supervisar las excavaciones de los Forjatiniebla. Cuando cayó el embajador Infernus, el clan perdió su vínculo con la Cumbre de Roca Negra. Después, Belgrum envió al siguiente viajero tras el último sueño de Dedomaza, la tablilla de Voluntad, un fragmento de piedra que, según la leyenda, los titanes grabaron con magia para dar voluntad propia a sus creaciones. Dedomaza murió por ella sin llegar a verla nunca." },
      },
    },
    ["anvilmar"] = {
      title = "Yunquemar",
      text = {
        { "Yunquemar, entre las nieves de Dun Morogh, es donde empiezan muchos jóvenes enanos y gnomos, y en algún rincón de su interior se encuentran dos de las piezas de Forjaz. Thran, el instructor de guerreros, tiene allí su sala. Es un buen lugar para empezar, y uno frío." },
      },
    },
    ["arathi-basin"] = {
      title = "Cuenca de Arathi",
      text = {
        { "En el sur de las Tierras Altas hay una cuenca fértil de granjas, minas y molinos, la tierra más rica que queda en Arathi. Tanto la Alianza como la Horda quieren lo que produce. La Liga de Arathor, fiel a la memoria de Stromgarde, lucha desde el oeste. Los Rapiñadores, formados por los Renegados, luchan desde el este." },
        { "Se disputan una granja, una mina, un aserradero, un establo y una herrería, izando y derribando los estandartes del otro día y noche. Arathor lo habría entendido: el primer imperio humano se construyó sobre tierras como estas." },
      },
    },
    ["arathi-highlands"] = {
      title = "Tierras Altas de Arathi",
      text = {
        { "Las Tierras Altas de Arathi son una comarca azotada por el viento entre Trabalomas y Los Humedales. Aquí Thoradin unió a las tribus humanas en Arathor, con capital en Strom. Todos los reinos humanos posteriores nacieron de aquel comienzo." },
        { "Strom se convirtió en Stromgarde. Sus ruinas se reparten ahora entre sus defensores, los ladrones del Sindicato y los ogros. Los trols Secacorteza ocupan asentamientos en las colinas, mientras gigantes custodian extraños círculos de piedras erguidas. El Refugio de la Zaga alberga el campamento de la Alianza y Sentencia el de la Horda. Sus fuerzas se disputan las granjas, minas y molinos de la cuenca del sur." },
        { "Fíjate en la antigua piedra al cruzar Arathi, $gviajero:viajera;. Los reinos humanos comenzaron aquí. Los defensores de Stromgarde aún intentan conservar una parte de aquel comienzo como propia." },
      },
    },
    ["archesonus"] = {
      title = "Historiadora real Archesonus",
      text = {
        { "Así que me has encontrado. Conservo la historia de Forjaz desde el Alto Trono, a unos pasos del trono del rey Magni, y más le vale tener una tarde libre a quien venga a preguntarme por ella." },
        { "La historia que más me piden es la de los Hierro Negro. La Guerra de los Tres Martillos terminó cuando el hechicero y señor feudal Thaurissan invocó a Ragnaros, cuyo despertar redujo su propia tierra a cenizas. Entre las ruinas de Thaurissan, en Las Estepas Ardientes, aún quedan reliquias que guardan más de esa historia de lo que he logrado descifrar. Agradeceré que alguien me traiga lo que cuentan." },
        { "Este registro es obra mía, $gviajero:viajera;, con la inestimable ayuda de la Liga de Expedicionarios, que trae a casa más de lo que una sola historiadora podría leer. Si una página te ha sido útil, me alegro. Si alguna te ha fallado, ven a decírmelo." },
        { side = "Horde", aside = true, sign = "P. F.", "Nunca la he conocido. Aun así, el suyo es el relato del mundo más ecuánime que he leído de una mano viva." },
      },
    },
    ["archmage-arugal"] = {
      title = "Archimago Arugal",
      text = {
        { "Mientras los defensores de Dalaran caían ante la Plaga, Arugal buscó un arma contra los muertos. El mago del Kirin Tor invocó ferocanis de otro mundo. Combatieron a los invasores y después se volvieron contra los vivos a los que debían proteger." },
        { "Arugal se retiró al Castillo de Colmillo Oscuro y llegó a considerar a los ferocanis sus hijos. La cercana Piroleña sufrió su maldición, que transformaba a sus habitantes al anochecer. Lo que empezó como un intento de salvar una ciudad ha dejado un castillo y una aldea a merced de su solución." },
      },
    },
    ["argent-dawn"] = {
      title = "El Alba Argenta",
      text = {
        { "El Alba Argenta recluta tanto en la Alianza como en la Horda para combatir a la Plaga. Sus caballeros, sacerdotes y estudiosos preguntan contra qué está dispuesto a luchar un viajero, en vez de qué estandarte sigue. Lord Maxwell Neófitus la dirige desde la Capilla de la Esperanza de la Luz, en Tierras de la Peste del Este." },
        { "Los oficiales del Campamento del Orvallo y del Baluarte entregan comisiones y aceptan las piedras de la Plaga que llevan los muertos. Sus enviados trabajan en Ventormenta, Darnassus y Vista Eterna. El Alba ha convertido su guerra en una causa a la que pueden sumarse personas de ambas facciones." },
        { "Comparte enemigo con la Cruzada Escarlata y poco aprecio por sus métodos. Considera que sospechar de todo extraño ayuda al Rey Exánime. La objeción tiene sentido práctico: esta lucha ya tiene enemigos suficientes." },
      },
    },
    ["arikara"] = {
      title = "Arikara",
      text = {
        { "Hagar Relampafauce, en el Poblado Viento Libre, quería examinar un huevo que las serpientes de los cañones custodiaban como si fuera uno de los suyos. Cuando por fin se lo trajeron, le bastó una mirada para mandar llamar a Motega Pirocabello, del Campamento del Tramo Blanco. Venganza había llegado a Las Mil Agujas, dijo Hagar, y Motega estuvo de acuerdo: la leyenda de Arikara era cierta." },
        { "A Arikara no se la rastrea, se la llama. El medio es el fuego sagrado de la vida, apagado desde hace mucho en la Cumbre de la Nube Negra, en la aguja aislada donde se entierra a los muertos. Se enciende con un polvo de pita incendiaria, una planta que no crece en ningún sitio más que en Las Mil Agujas. Motega envió las plantas a Magatha Tótem Siniestro, en el Alto de los Ancestros de Cima del Trueno, para que las encantara, y Magatha dio un motivo para darse prisa. Habían cambiado demasiado las tradiciones de los tauren, dijo, y temía que eso hubiera enojado a Arikara, y que la serpiente anduviera tras Cairne Pezuña de Sangre." },
        { "Una vez cumplida la tarea, Motega no le encontraba sentido. ¿Por qué iba Arikara a perseguir a Cairne? Pero Magatha no podía estar equivocada, decidió. Al fin y al cabo, era la chamán más poderosa de los tauren. Negó con la cabeza y pagó al cazador de todos modos." },
      },
    },
    ["arthas-menethil"] = {
      title = "Arthas Menethil",
      text = {
        { "Arthas Menethil era el único hijo del rey Terenas de Lordaeron, paladín de la Mano de Plata instruido por el propio Uther y, en días más felices, cercano a la joven hechicera Jaina Valiente. Cuando llegó la peste, salió a combatirla." },
        { "La siguió hasta aquí por delante de la Plaga y encontró el grano ya consumido. Antes que dejar que la ciudad se alzara contra él, pasó a sus habitantes a cuchillo. Uther y Jaina se negaron a seguirlo. El señor del terror Mal'Ganis, que lo esperaba, se retiró al norte. Arthas lo persiguió hasta Rasganorte, quemó sus propios barcos para que sus hombres no pudieran volver y empuñó la hoja rúnica Agonía de Escarcha. Con ella mató a Mal'Ganis y perdió su alma." },
        { "Volvió a casa como caballero de la muerte, mató a su padre en su propio salón del trono y condujo a la Plaga por el reino que debía gobernar. En Andorhal mató a Uther. Después fue al norte, al Trono Helado, y, según el libro de nuestra biblioteca, se convirtió en el propio Rey Exánime. Stratholme lo recuerda mejor que ningún lugar. Sus calles aún están llenas de las personas a las que quiso salvar." },
        { side = "Horde", aside = true, sign = "P. F.", "Las historias de Lordaeron tenían un capítulo reservado para él: el heredero, el paladín, el futuro rey. Ninguna se equivocaba sobre sus dones." },
      },
    },
    ["ashenvale"] = {
      title = "Vallefresno",
      text = {
        { "Vallefresno es el antiguo bosque de los elfos de la noche: árboles inmensos, luz de luna plateada, lagos quietos y ruinas más antiguas que cualquier reino humano. Durante diez mil años vivieron aquí ocultos, protegidos por sus centinelas y por el semidiós Cenarius, sin dejar entrar a nadie." },
        { "Después llegaron los orcos a Kalimdor, necesitados de madera para su nueva tierra, y desde entonces el bosque está en guerra. Durante la última guerra, el clan Grito de Guerra taló en Vallefresno y mató a Cenarius bajo la corrupción de Mannoroth. Los elfos de la noche no los han perdonado y la Horda no ha dejado de talar. Ahora centinelas y escoltas Grito de Guerra escaramuzan en el extremo oriental, mientras fúrbolgs enloquecidos, sátiros y nagas causan problemas a todos por igual." },
      },
    },
    ["astranaar"] = {
      title = "Astranaar",
      text = {
        { "Astranaar está en una isla de un lago de Vallefresno, unida al bosque por puentes. Su pozo de la luna, su posada y su cuartel de centinelas dan a los elfos de la noche un centro desde el que defender la región. Es una villa hermosa con muy poca tranquilidad." },
        { "Aquí, un padre busca ayuda para la fiebre y las pesadillas de su hija. Los remedios ordinarios han fallado. Los herboristas hablan de enfermedad en el propio bosque, mientras las centinelas culpan a la corrupción que dejaron los demonios de la guerra. Quien viene a defender Astranaar puede descubrir que sus problemas empiezan mucho antes de llegar a los accesos vigilados." },
      },
    },
    ["atiesh"] = {
      title = "Atiesh",
      text = {
        { "Atiesh fue el bastón de los Guardianes de Tirisfal, de Medivh al final, y tras su muerte quedó roto y disperso. Sus astillas se reunieron en la necrópolis de Naxxramas, donde Kel'Thuzad estaba en su trono con lo que buscaba su portador. Su base entró en Ahn'Qiraj con el explorador enano Brann Barbabronce, que salió de allí sin ella." },
        { "Un bastón que había llevado el poder de un Guardián también había llevado el de Sargeras, igual que su último Guardián, y el mal seguía dentro. Anacronos, del Vuelo Bronce, junto a las Cavernas del Tiempo, envía a quien le trae los fragmentos a Stratholme, al suelo consagrado donde asesinaron a los mayores caballeros de Lordaeron, para sacar a la criatura de su interior y destruirla." },
        { "Muy pocos lo sostendrán alguna vez. El dragón bronce dice que quien lo haga siempre estuvo destinado a ello. El Vuelo Bronce dice mucho ese tipo de cosas." },
      },
    },
    ["auberdine"] = {
      title = "Auberdine",
      text = {
        { "Auberdine es el puerto de los elfos de la noche en Costa Oscura, una aldea de casas elegantes junto a la orilla, con barcos hacia Teldrassil y hacia el Puerto de Menethil, al otro lado del mar. Para la mayoría de los viajeros de los Reinos del Este, es el primer pueblo de los elfos de la noche que ven." },
        { "Las centinelas que lo protegen no dan abasto y agradecen cualquier ayuda. La Liga también tiene un amigo aquí. Pregunta por el prospector Tripirrem y prepárate para una historia larga." },
      },
    },
    ["azshara"] = {
      title = "Azshara",
      text = {
        { "Azshara viste colores de otoño entre las ruinas blancas de los Altonato. Lleva el nombre de la reina que gobernó hace diez mil años y yace junto al mar que se tragó buena parte de su imperio. Pocos lugares ofrecen una vista más hermosa de una pérdida tan grande." },
        { "Los nagas ocupan la costa y los antiguos templos. Los sátiros rondan el bosque y los fantasmas permanecen entre los muros rotos. Valormok y Punta Talrendis son pequeños enclaves en una tierra aún llena de derechos más antiguos. Azuregos vigila las colinas del sur, mientras un archimago conserva una torre y un señor del agua habita una isla de la bahía." },
        { client = "classic", "En las colinas del norte está la puerta cerrada del Bastión Fauces de Madera. Los fúrbolgs se han reservado esa parte de su territorio." },
        { client = "forever", "La puerta de piedra del norte lleva al Bastión Faucenegra, donde la corrupción se ha apoderado de una tribu fúrbolg. No son los Fauces de Madera que custodian los túneles de Frondavil. Un viejo nombre en el mapa puede orientar mal sobre la gente que hay tras una puerta." },
      },
    },
    ["azuregos"] = {
      title = "Azuregos",
      text = {
        { "Azuregos vigila el sur de Azshara, donde los Altonato dejaron tesoros arcanos suficientes para ocupar a un dragón azul durante muchísimo tiempo. Su Vuelo protege la magia y esta costa arruinada tiene mucho que explicar sobre la necesidad de esos guardianes." },
        { "Su encargo también incluía el fragmento azul del Cetro del Mar de Dunas. Buscarlo lleva a un libro mágico y a un elaborado método para sacar de la Bahía de la Tempestad a un gran tiburón llamado Fauces. Una pieza perdida de un cetro antiguo se ha convertido en un asunto de traducción, ingeniería y dientes enormes." },
        { "Hay guardianes solemnes en el mundo, $gviajero:viajera;. Los arreglos de Azuregos sugieren que siglos de responsabilidad no tienen por qué apagar la capacidad de un dragón para dar trabajo a otros." },
      },
    },
    ["bael-modan"] = {
      title = "Bael Modan",
      text = {
        { "Los enanos del general Trenzado han construido Bael Modan junto a su excavación en el sureste de Los Baldíos, con un cañón y máquinas voladoras para apoyar el asentamiento. El prospector Khazgorm, de la Liga de Expedicionarios, trabaja entre ellos. Un yacimiento antiguo, un campamento defendido y un prospector de la Liga: el principio de una expedición conocida." },
        { "Gann Aguja de Piedra describe lo que hubo antes. Dice que este era el hogar de su tribu, hasta que las explosiones y las máquinas desgarraron las colinas y expulsaron a sus habitantes. La diplomacia le ha fallado. Ahora busca la muerte de Khazgorm y la destrucción de la máquina voladora enana." },
        { "En la propia expedición, Feegly ha sufrido una maldición de una piedra desenterrada. La excavación ha traído problemas tanto a quienes excavan como a quienes ha desplazado. Me gustaría sentir orgullo por todos los lugares donde aparece el nombre de la Liga. Bael Modan lo pone difícil." },
      },
    },
    ["balnazzar"] = {
      title = "Balnazzar",
      text = {
        { "Balnazzar era uno de los señores del terror que quedaron en Lordaeron para supervisar a la Plaga en nombre de la Legión Ardiente. Tras la derrota de la Legión desafiaron el dominio de Arthas. Arthas escapó de su rebelión y marchó a Rasganorte. Más tarde, Sylvanas les arrebató su reino. Por orden suya, Varimathras aparentemente mató a su hermano Balnazzar." },
        { "Se creyó en aquella muerte, pero el demonio sobrevivió. Adoptó la identidad del gran cruzado Dathrohan y gobernó el bastión Escarlata de Stratholme. Derrotar al supuesto cruzado revela lo que hay bajo el disfraz. Es un descubrimiento espantoso para una orden dedicada a destruir el mismo mal del que recibe órdenes." },
      },
    },
    ["baron-rivendare"] = {
      title = "Barón Osahendido",
      text = {
        { "El barón Osahendido gobierna la mitad de Stratholme de la Plaga desde su matadero, un caballero de la muerte sobre un caballo muerto. El Alba Argenta lo llama el chico de los recados de Kel'Thuzad. El duque Zverenhoff, en la Capilla de la Esperanza de la Luz, pide su cabeza." },
        { "Osahendido también mantiene cautiva a Ysida Harmon, cruzada del Alba Argenta. Su marido busca rescatarla. Recuérdala si la recompensa del duque te lleva a la ciudad, $gviajero:viajera;. Allí aún hay alguien que necesita salir con vida." },
      },
    },
    ["barrens-oases"] = {
      title = "Los oasis",
      text = {
        { "Los oasis son la vida de Los Baldíos: charcas de agua dulce entre la hierba seca a las que acuden bestias y viajeros a beber. Últimamente se han vuelto extraños. Los animales cercanos se deforman, las plantas crecen demasiado deprisa y de manera anormal. Los druidas de Cima del Trueno sintieron que un poder se filtraba en la tierra y enviaron a uno de los suyos a buscarlo." },
        { "Encontró fisuras en el fondo de las charcas que se adentraban en la tierra. Los oasis se alimentan desde abajo, desde las cavernas bajo Los Baldíos, y lo que anda mal en esas cavernas está subiendo con el agua." },
      },
    },
    ["battle-in-the-depths"] = {
      title = "Combate en las profundidades",
      text = {
        { "Tres breves piezas de batalla esperan en algún rincón de las mazmorras: el Castillo de Colmillo Oscuro, Las Minas de la Muerte, Uldaman, Maraudon y Stratholme. Ninguno de esos lugares ha carecido nunca de peleas." },
      },
    },
    ["black-dragonflight"] = {
      title = "El Vuelo Negro",
      text = {
        { "Neltharion era el Guardián de la Tierra, encargado de las profundidades del mundo. Su traición a los otros vuelos le dio el nombre de Alamuerte. Tras la Segunda Guerra entró en los consejos de los reyes humanos como lord Prestor, ocultando un dragón tras el rostro de un noble. Escapó de los Aspectos después de la lucha de Grim Batol. Se desconoce adónde se ha retirado." },
        { "Sus hijos ocupan lugares que podemos nombrar. Onyxia mantiene su progenie en Marjal Revolcafango. Nefarian domina la Cumbre de Roca Negra, manda a sus orcos y cría dragones cromáticos sobre ellos. Las crías negras habitan Crestagrana y Tierras Inhóspitas, mientras los dragonantes custodian los mayores dominios del Vuelo." },
        { "Las guaridas ya son formidables. Lord Prestor mostró lo que puede lograr un dragón negro con un asiento en la mesa de un consejo." },
      },
    },
    ["blackfathom-deeps"] = {
      title = "Cavernas de Brazanegra",
      text = {
        { "En la costa de Vallefresno, en la Ensenada de Zoram, hay cavernas inundadas por el mar. En ellas yacen las ruinas de un templo de Elune que se hundió cuando fue destruido el Pozo de la Eternidad. Primero lo encontraron los nagas. Después llegó el Martillo Crepuscular, dirigido por un señor del Crepúsculo llamado Kelris." },
        { "Sus documentos dicen lo que hacen allí. Reúnen el poder de las aguas profundas para alimentar a una criatura llamada Aku'mai, que duerme en el fondo del templo, con la esperanza de devolver un día al mundo a lo que llaman su era más gloriosa: el dominio de los dioses antiguos. Tanto los elfos de la noche como la Horda envían a sus jóvenes a detenerlos. Quizá sea lo único en lo que coinciden en Vallefresno." },
      },
    },
    ["blackrock-clan"] = {
      title = "El clan Roca Negra",
      text = {
        { "Los Roca Negra fueron el mayor clan de la antigua Horda. Su jefe Puño Negro la dirigió como Jefe de Guerra en la Primera Guerra, hasta que Orgrim Martillo Maldito le rompió el cráneo y tomó el título. Martillo Maldito también era un Roca Negra. Cuando cayó la Horda, casi todo el clan fue a los campos con los demás y muchos de los que salieron siguieron a Thrall." },
        { "No todos. Los hijos de Puño Negro, Desgarro y Maim, reunieron supervivientes dentro de la Montaña Roca Negra. Los seguidores de Desgarro conservan las viejas costumbres: conquista, crueldad y culto al Jefe de Guerra. Desgarro sigue reclamando ese título y solo tiene desprecio para Thrall. Peor aún, se ha unido a los dragones negros que anidan en la Cumbre superior." },
        { "Desde la montaña, el clan ataca al norte y al oeste. Domina Las Estepas Ardientes, ha tomado el Fuerte de Petravista en Crestagrana y los habitantes de Villa del Lago viven a la vista de sus fuegos. Sea lo que sea la Horda en Durotar, esto es lo que fue." },
      },
    },
    ["blackrock-depths"] = {
      title = "Profundidades de Roca Negra",
      text = {
        { "Las Profundidades de Roca Negra son la ciudad de los Hierro Negro bajo la montaña: Ciudad Forjatiniebla, con sus prisiones, su arena, sus cámaras, sus talleres de gólems y su taberna, el Tragapenas, donde elaboran una cerveza oscura. Al fondo, en su palacio, está el emperador, y más allá se abre el descenso al dominio del propio Señor del Fuego." },
        { "La Alianza y la Horda vienen aquí: la Horda por los gólems de los Hierro Negro y sus secretos, la Alianza por un alguacil cautivo y por la hija del rey Magni. Aquí hay muchísima historia y casi toda está ardiendo." },
      },
    },
    ["blackrock-mountain"] = {
      title = "Montaña Roca Negra",
      text = {
        { "La Montaña Roca Negra se alza entre La Garganta de Fuego y Las Estepas Ardientes, una montaña de piedra negra con fuego en su corazón. Surgió cuando llegó Ragnaros, y los Hierro Negro, sus esclavos, construyeron su ciudad dentro. Durante la Segunda Guerra fue la gran fortaleza de la Horda. Después, los orcos que escaparon de la Alianza se refugiaron en ella." },
        { "Hoy la montaña está en guerra consigo misma. Los Hierro Negro dominan las profundidades para el Señor del Fuego, mientras los orcos de la Horda Oscura y los dragones negros de Nefarian ocupan la Cumbre. Entre ambos, en mitad de la montaña, cuelgan cadenas sobre un lago de lava." },
      },
    },
    ["blackrock-spire"] = {
      title = "Cumbre de Roca Negra",
      text = {
        { "Los Hierro Negro tallaron la Cumbre de Roca Negra sobre su ciudad y después la perdieron ante los orcos. Orgrim Martillo Maldito la ocupó en la Segunda Guerra. La Alianza asedió la fortaleza al final de la contienda. Anduin Lothar cayó ante sus puertas antes de que la Horda fuera derrotada." },
        { "Ahora Desgarro Puño Negro manda a sus orcos al servicio de Nefarian. Orcos, trols y ogros llenan la parte baja de la Cumbre, mientras el dragón y sus seguidores dominan las alturas. El ascenso atraviesa una fortaleza ocupada por un amo distinto al que pretendían sus constructores." },
      },
    },
    ["blackwing-lair"] = {
      title = "Guarida de Alanegra",
      text = {
        { "Nefarian ocupa la Guarida de Alanegra en lo alto de la Cumbre de Roca Negra. Aquí cría dragones cromáticos combinando la sangre de los vuelos, en busca de un ejército capaz de arrollar a sus enemigos. La guarida es a la vez su fortaleza y el lugar donde crea a sus futuros soldados." },
        { "El dragón rojo Vaelastrasz está allí bajo el control de Nefarian. Antes amigo de los mortales, suplica a quienes llegan hasta él que pongan fin a su sufrimiento. Poco consuela encontrar aquí a un amigo cuando eso es lo que debe pedirte, $gviajero:viajera;." },
      },
    },
    ["blasted-lands"] = {
      title = "Las Tierras Devastadas",
      text = {
        { "Al sur del Pantano de las Penas, tras un único camino y un único castillo, están Las Tierras Devastadas: un yermo rojo y agrietado de polvo y árboles muertos, con bestias deformadas y suelo contaminado. Aquí entraron los orcos por primera vez en nuestro mundo a través del Portal Oscuro y aquí los hicieron retroceder. La tierra nunca se ha recuperado." },
        { "Los demonios de la Legión Ardiente aún caminan aquí. La Alianza vigila desde Nethergarde, los ogros tienen sus propios campamentos y la Horda sus propios asuntos con los demonios. Todo el que viene lo hace por el Portal o por lo que dejó atrás." },
      },
    },
    ["blood-elves"] = {
      title = "Los elfos de sangre",
      text = {
        { "Tras caer Quel'Thalas, el último de su linaje real, el príncipe Kael'thas Caminante del Sol, dirigió a los altos elfos restantes en la lucha de la Alianza contra la Plaga. Se llamaron elfos de sangre en honor a sus muertos. Separados de la Fuente del Sol que los había alimentado durante miles de años, descubrieron también cuánto necesitaban su magia y sufrieron por su ausencia." },
        { "Como la Alianza exigía batallas que sus fuerzas mermadas no podían ganar solas, Kael'thas aceptó ayuda de lady Vashj y sus nagas. Su comandante, Garithos, condenó a los elfos de sangre como traidores y los sentenció a muerte. Vashj los liberó de las mazmorras de Dalaran y los llevó a Terrallende, el resto destrozado del mundo de los orcos. Allí liberaron a Illidan Tempestira de su captora y Kael'thas se puso a su servicio a cambio de la magia que su pueblo necesitaba." },
        { "Algunos están mucho más cerca. Los elfos de sangre buscan en los riscos y ruinas de Azshara la magia que dejaron los Altonato y muelen sus hallazgos hasta convertirlos en un polvo brillante. Tanto un goblin que aceptó su dinero como una partida orca que les prestó guardias han aprendido lo que vale trabajar para ellos. Otro ha entrado en La Masacre para desangrar el poder de sus ruinas. Gershala Noctusurro, en Auberdine, teme que sigan el camino de sátiros y nagas. Temo que tenga razón." },
      },
    },
    ["bloodhoof-village"] = {
      title = "Poblado Pezuña de Sangre",
      text = {
        { "El Poblado Pezuña de Sangre es el corazón de las llanuras, una población de casas comunales y corrales de kodos en el camino entre el Campamento Narache y Cima del Trueno. Su jefe es Baine Pezuña de Sangre, hijo del gran jefe Cairne. Aquí realizan los jóvenes el segundo de los ritos, el Rito de la Visión: beben el Agua de los Videntes ante el fuego del poblado y siguen adonde los lleva la visión." },
        { "Es un lugar animado, amistoso y práctico. Los tauren de Pezuña de Sangre son agricultores y pastores tanto como cazadores, y darán de comer a un extraño antes de preguntarle qué lo trae por allí." },
      },
    },
    ["bloodsail-buccaneers"] = {
      title = "Los Bucaneros Velasangre",
      text = {
        { "Los Bucaneros Velasangre son la gran flota pirata de los mares del sur y su disputa es con Bahía del Botín. El barón y sus Asaltantes Aguasnegras les impiden saquear donde quieren y los cuelgan cuando los capturan. Los Velasangre quieren muertos al barón y a su maestro de flota y harán almirante a quien les lleve sus cabezas." },
        { "Sus barcos están frente a la costa de Tuercespina, entre ellos el Velo Carmesí, y sus campamentos ocupan las calas de la Costa Salvaje. Su maestro de flota es Firallon, del que los marineros Aguasnegras dicen que no podría cruzar un lago en una barca. Aún no lo han derrotado." },
      },
    },
    ["bloodscalp-and-skullsplitter"] = {
      title = "Los Cabellesangre y los Machacacráneos",
      text = {
        { "Los Cabellesangre dominan el noroeste de Tuercespina. Los Machacacráneos ocupan la jungla central. Ambos viven entre las ruinas de sus antepasados Gurubashi. Sus cazadores de cabezas recorren el norte en busca de cabezas y trofeos, y las dos tribus se miran con considerable hostilidad." },
        { "Nimboya sospecha que los Cabellesangre retienen a Yenniku, el hijo menor de su jefe. La búsqueda lleva a otro lugar: Zanzil el Desarraigado lo tiene bajo control mágico. Sigue esa distinción, $gviajero:viajera;. El primer enemigo señalado en una investigación no siempre es el responsable." },
      },
    },
    ["bloodvenom-post"] = {
      title = "Puesto del Veneno",
      text = {
        { "El Puesto del Veneno es el campamento de la Horda en el corazón de Frondavil, junto a las cascadas envenenadas. Sus habitantes combaten al Consejo de la Sombra en Jaedenar y a los seres corruptos del bosque. Allí espera una viuda que quiere vengarse del fúrbolg que mató a su marido." },
        { "No todos quieren sanar Frondavil. Una boticaria Renegada, Winna Hazzard, estudia el pozo de la luna corrupto de los sátiros Fuego de Jade en busca de una ventaja contra la Alianza en sus aguas. Yo vigilaría a su gata." },
      },
    },
    ["blue-dragonflight"] = {
      title = "El Vuelo Azul",
      text = {
        { "A Malygos, el Tejedor de Hechizos, se le confió la magia y su Vuelo ha pagado por ello. Cuando Alamuerte se volvió contra los demás vuelos en la Guerra de los Ancestros, el Azul fue el que más sufrió. Sobrevivieron muy pocos y Malygos no ha vuelto a ser el mismo." },
        { "Sus enclaves en estas tierras son pocos. Los dragonantes azules custodian las orillas del Lago Mennar en Azshara, y las cuevas de Mazthoril, en Cuna del Invierno, ocultan un refugio donde su matrona protectora, Haleh, recibe a quienes llevan una escama de dragón azul y pisan la runa adecuada. Los Aspectos, te dirá, insisten en que sus vuelos se mantengan fuera de los asuntos mortales. También te dirá que los hijos de Alamuerte lo ponen difícil." },
        { "Azuregos mantiene su propia vigilancia sobre las ruinas del sur de Azshara en busca de los tesoros arcanos que dejaron los Altonato. La costa lleva diez mil años arruinada y aún da trabajo a un dragón azul." },
      },
    },
    ["bolvar-fordragon"] = {
      title = "Alto señor Bolvar Fordragon",
      text = {
        { "El alto señor Bolvar Fordragon manda los ejércitos de Ventormenta y permanece junto al joven rey Anduin Wrynn mientras su padre, Varian, sigue desaparecido. Es un paladín de la vieja escuela, devoto, honrado e inamovible, y mantiene a los soldados del reino donde más falta hacen, que rara vez es donde querrían las provincias." },
        { "Es un hombre prudente, quizá demasiado. Cuando el magistrado de Villa del Lago avisó de que los orcos Roca Negra contaban con dragones, Bolvar se negó a mover tropas basándose en conjeturas y envió al mensajero a pedir consejo a lady Katrana Prestor. El alguacil Windsor, que había encontrado las pruebas, lo llamó necio: las tenía a dos pasos y no las veía. Cuando Windsor desenmascaró a la dama en el salón del trono como Onyxia, hija de Alamuerte, afirmó que hasta el alto señor había sido su marioneta, sometido por el medallón de un dragón. Al final, Bolvar se quedó con él en las manos, hecho añicos." },
        { "No es un necio. Es un hombre honrado que creyó la palabra de una dragona, y dudo que vuelva a hacerlo." },
      },
    },
    ["booty-bay"] = {
      title = "Bahía del Botín",
      text = {
        { "Bahía del Botín se aferra a los riscos de una cueva marina en el extremo sur de Tuercespina. Casas de madera, pilotes y puentes de cuerda se apiñan en su puerto. Las fauces abiertas de un tiburón enorme señalan la entrada. El barón Revilgaz lo administra para el Cártel Bonvapor, interesado en mantenerlo neutral y rentable." },
        { "Sus Asaltantes Aguasnegras también tienen aquí su hogar. Están en guerra con los Bucaneros Velasangre, que quieren muerto al barón. Un comerciante puede encontrar refugio en la bahía y un viajero armado puede encontrar empleo en la disputa de fuera. Revilgaz tiene negocios para ambos." },
      },
    },
    ["bough-shadow"] = {
      title = "Talloumbrío",
      text = {
        { "Talloumbrío, en el extremo oriental de Vallefresno, comparte una melodía con la Canción del Bosque, muy cerca, y esa melodía reaparece en algún rincón de las tres capitales de la Alianza. Talloumbrío es uno de los cuatro portales del sueño de Azeroth. Los dragonantes que lo guardan llevan ahora la corrupción de la Pesadilla, y es peor de lo que aparenta." },
      },
    },
    ["boulderslide-ravine"] = {
      title = "Barranco del Alud",
      text = {
        { "En el sureste de la Sierra Espolón hay un barranco con una cueva profunda. Sus kóbolds han excavado como poseídos tras un cristal raro al que llaman resonita. Los chamanes de Roca del Sol sintieron que algo andaba mal bajo las montañas y fueron a investigar. Al fondo de la cueva encontraron un barril de resonita y, dormido dentro, a un terráneo: un ser de piedra viva llamado Goggeroc." },
        { "Si hay que creer los discos de Uldaman, los titanes crearon a los terráneos para dar forma al mundo y son los antepasados de mi pueblo. Habría dado mucho por hablar con uno. Los chamanes de Roca del Sol lo consideran una amenaza para la tierra y quieren despertarlo y destruirlo mientras aún está débil." },
        { "No digo que se equivoquen. Yo no lo he visto. Pero me gustaría mucho saber qué hacía un terráneo dormido en un barril bajo la Sierra Espolón y quién lo puso allí." },
      },
    },
    ["brackenwall-village"] = {
      title = "Poblado Murohelecho",
      text = {
        { "El Poblado Murohelecho es el campamento de la Horda en Marjal Revolcafango, ocupado por orcos y ogros del clan Quebrantarrocas. Estos ogros son aliados de la Horda gracias al señor de las bestias Rexxar, que hizo a su señor Mok'Morokk dirigente del clan. Los ogros lo cuentan a menudo." },
        { "Vinieron a Murohelecho por necesidad. La progenie de Onyxia cayó sobre su antiguo hogar, al sur del pantano, y los expulsó con fuego. El miembro más inteligente del clan, un ogro de dos cabezas que habla mejor que la mayoría de los enanos, intenta averiguar por qué. La Horda también quiere saber por qué se interesa la hija de Alamuerte por un pequeño grupo de ogros." },
      },
    },
    ["brill"] = {
      title = "Rémol",
      text = {
        { "Rémol era un tranquilo pueblo agrícola en el camino al este de Camposanto y los Renegados lo han hecho suyo: el ayuntamiento alberga a un magistrado, el Mesón La Horca sirve bebidas extrañas a clientes extraños y, en su sótano, los guardias de la Muerte retienen a sus prisioneros, entre ellos montaraces enanos, hasta decidir qué hacer con ellos." },
        { "También es donde la Sociedad Real de Boticarios realiza buena parte de su trabajo. No diré más al respecto, salvo que ningún enano debería aceptar una bebida en Rémol." },
      },
    },
    ["bronze-dragonflight"] = {
      title = "El Vuelo Bronce",
      text = {
        { "A Nozdormu, el Atemporal, se le confió el tiempo y su Vuelo custodia sus caminos. Rara vez se los ve. Cuando ocurre, suele ser porque algo ha ido mal con el momento en que suceden las cosas." },
        { "En Andorhal, una de ellos aparece como una extraña gnoma llamada Cromi y ha convertido una habitación de la posada en ruinas en un lugar que no pertenece del todo al resto de la población. Dice que la Plaga ha estado manipulando el tiempo allí. Caza los parásitos que se alimentan de sus hilos rotos y ha ayudado a un viajero a cambiar el destino de un hombre que cayó en Villa Darrow." },
        { "En Tanaris, cerca de las Cavernas del Tiempo, espera Anacronos, que estuvo en el Muro del Escarabajo hace mil años, cuando fue sellado. El Vuelo Bronce recuerda la guerra contra Ahn'Qiraj porque luchó en ella. Pregúntales qué saben del mañana y sonreirán y dirán que tus mayores hazañas están por llegar, $gviajero:viajera;." },
      },
    },
    ["burning-blade"] = {
      title = "El Filo Ardiente",
      text = {
        { "El Filo Ardiente fue un clan orco famoso por sus maestros del acero. Algunos se liberaron de los demonios y aún sirven a Thrall. El resto del nombre ha ido a parar a un culto. El Filo Ardiente actual es una hermandad de brujos y fanáticos que adoran a los demonios que esclavizaron a su pueblo y responden ante el Consejo de la Sombra que trajo a la Horda a este mundo." },
        { "Son la vergüenza de la propia Horda, oculta en sus tierras. Ocupan las cuevas de Roca del Cráneo en Durotar, a la vista de Orgrimmar, y la Cima Calígine en Los Baldíos, donde un guardia vil vigila lo que llaman la Semilla de demonio, un vínculo con la propia Legión. En Desolace han tomado la Fortaleza del Hacha de Trueno. En las simas bajo la propia Orgrimmar conspira una rama que se llama Hoja Abrasadora. Los seguidores de Thrall los persiguen donde los encuentran." },
        { "Estuvieron más cerca de iniciar otra guerra de lo que nadie quiere admitir. Unos años después del Monte Hyjal, un demonio menor llamado Zmodlor tomó las riendas del culto y enfrentó a Durotar y Theramore: barcos atacados, incursiones atribuidas al otro bando, un traidor susurrando en el consejo de cada dirigente, incluido el chambelán de lady Jaina Valiente. Jaina y Thrall lo descubrieron juntos y la paz resistió. El culto no había terminado, como demuestra Roca del Cráneo." },
      },
    },
    ["burning-legion"] = {
      title = "La Legión Ardiente",
      text = {
        { "La Legión Ardiente es un ejército de demonios reunido por el titán caído Sargeras en mil mundos conquistados. Ha venido a por el nuestro tres veces. La primera hace diez mil años, por el Pozo de la Eternidad de los elfos de la noche. La segunda a través de los orcos, que sus sirvientes corrompieron y enviaron por el Portal Oscuro. La tercera fue la última guerra, cuando su general Archimonde cayó al pie del Árbol del Mundo, en el Monte Hyjal." },
        { "Nunca se ha ido del todo. Lord Kazzak domina Las Tierras Devastadas con una hueste de demonios alrededor del Portal Oscuro inactivo. Los brujos del Consejo de la Sombra mantienen demonios en Jaedenar, en Frondavil, donde todo el bosque se ha podrido a su alrededor. Guardias apocalípticos e infernales recorren el Barranco del Demonio de Vallefresno, donde Grom Grito Infernal mató a Mannoroth, el Aquelarre Mannoroc de Desolace y las ruinas de Azshara." },
        { "La Legión es paciente. Ha perdido tres guerras y sigue aquí. No creo que haya terminado con nosotros." },
      },
    },
    ["burning-steppes"] = {
      title = "Las Estepas Ardientes",
      text = {
        { "Las Estepas Ardientes se extienden al sur de la Montaña Roca Negra, una amplia llanura de ceniza, lava y roca negra bajo un cielo rojo. Antes de que Thaurissan despertara al Señor del Fuego, todo esto era el extremo norte de las Montañas Crestagrana. La explosión se llevó las montañas, los bosques y la propia ciudad de los Hierro Negro, y dejó esto." },
        { "Es una tierra en guerra. Los orcos Roca Negra de la Horda Oscura dominan la Cumbre y los pasos, el Vuelo Negro anida en las alturas y los ogros ocupan Roca Machacamiedo. La Alianza tiene un puesto en Vigilia de Morgan, al sureste. En Peñasco Llamarada, sobre una roca por encima de la lava, hay un pequeño enclave neutral donde cualquiera puede descansar." },
      },
    },
    ["caer-darrow"] = {
      title = "Castel Darrow",
      text = {
        { "Castel Darrow es un castillo en una isla del Lago Darrowmere, al sur de Tierras de la Peste del Oeste. Fue la sede de la Casa Barov, una de las grandes familias nobles de Lordaeron. Es un lugar tranquilo, brumoso y hermoso. Su población está llena de fantasmas." },
        { "Los Barov lo entregaron. Para conservar su fortuna cuando llegó la peste, pactaron con Kel'Thuzad y dieron su castillo al Culto de los Malditos, que excavó debajo Scholomance, la escuela de nigromancia de la Plaga. Al final, los Barov no conservaron gran cosa." },
      },
    },
    ["cairne-bloodhoof"] = {
      title = "Cairne Pezuña de Sangre",
      text = {
        { "Cairne Pezuña de Sangre es el gran jefe de los tauren, jefe de la tribu Pezuña de Sangre y el amigo más antiguo que tiene la Horda en Kalimdor. Cuando los orcos de Thrall desembarcaron, guiaba a su pueblo por las llanuras con los centauros pisándoles los talones. Los orcos lucharon a su lado. Cairne les correspondió con amistad y consejo, y los tauren forman parte de la Horda desde entonces." },
        { "Ahora es muy anciano, muy grande, y habla despacio y pocas veces. Construyó Cima del Trueno, reunió allí a las tribus y dio a los tauren un hogar por primera vez en su memoria. Su hijo Baine se ocupa del Poblado Pezuña de Sangre. Dicen que una vez los centauros lo secuestraron y que un señor de las bestias de la Horda lo devolvió." },
        { "Los orcos lo veneran y la Alianza confía en él más que en ningún otro dirigente de la Horda. Creo que ambos tienen razón." },
      },
    },
    ["camp-mojache"] = {
      title = "Campamento Mojache",
      text = {
        { "El Campamento Mojache es el campamento de la Horda en el este de Feralas: un círculo de tiendas tauren y tótems en una colina entre árboles gigantes, cerca del camino a La Masacre. Los tauren vigilan a los ogros Gordunni, cada vez más numerosos, y a sus primos Tótem Siniestro de las colinas del sur, que no son amigos de Cima del Trueno." },
        { "Los sabios del campamento tienen sus propios intereses en las ruinas. Buscan a un maestro elfo que huyó de la caída de Quel'Thalas con artefactos antiguos y creen que entró en La Masacre." },
      },
    },
    ["camp-narache"] = {
      title = "Campamento Narache",
      text = {
        { "El Campamento Narache está en la Mesa de la Nube Roja, al sur de Mulgore: un círculo de tiendas de piel y tótems alrededor de un fuego, donde comienzan los jóvenes tauren. El jefe Viento de Halcón y su familia mantienen el campamento y encargan a los jóvenes el primero de los Ritos de la Madre Tierra: el Rito de la Fuerza, que se demuestra contra los jabaespines que han entrado en el barranco de abajo." },
        { "Ante todo es un campamento de caza. Los tauren cazan por necesidad y por placer, y se espera que un joven traiga plumas y carne antes de preguntarle qué más sabe hacer." },
      },
    },
    ["camp-taurajo"] = {
      title = "Campamento Taurajo",
      text = {
        { "El Campamento Taurajo es un campamento tauren en el sur de Los Baldíos, tiendas y tótems alrededor de un fuego, el último lugar amigo en el camino a Las Mil Agujas. Sus habitantes cazan en las llanuras meridionales y vigilan a los jabaespines de los espinos de Rajacieno." },
        { "Tiene un huésped peculiar: un jabaespín llamado Quebrantadientes, cautivo de los tauren, que conoce las bendiciones del dios jabalí Agamaggan y se las enseña a quien le traiga las piedras adecuadas. Los tauren lo toleran. Según me dicen, es muy grosero." },
      },
    },
    ["captain-varothen"] = {
      title = "Capitán Varo'then",
      text = {
        { "El capitán Varo'then mandaba la guardia de la reina Azshara durante la Guerra de los Ancestros: un soldado lleno de cicatrices que se decía inmune a sus encantos y que, según los relatos, estaba perdidamente enamorado de ella. En lugar de resistirse, cumplía todos sus caprichos. Buscó el Alma demoníaca para la Legión y alimentó una enemistad con Malfurion Tempestira hasta el final." },
        { "En la última batalla sobre el Pozo dirigió a los Altonato que aún eran leales a la reina. Dijo a Malfurion que solo vivía para servirla, aunque eso supusiera el fin de Kalimdor. Fueron casi sus últimas palabras. Según el relato, Kalimdor le tomó la palabra y lo rechazó." },
        { "Su fantasma recorre las ruinas del Santuario de Cantosombrío, aún con la armadura de la guardia de la reina. Sea lo que sea lo que protege ahora, diez mil años no lo han relevado de ello." },
      },
    },
    ["caverns-of-time"] = {
      title = "Las Cavernas del Tiempo",
      text = {
        { "En el este de Tanaris, entre las rocas sobre el mar, una cueva desciende hasta las Cavernas del Tiempo, guarida del Vuelo Bronce. Su amo es Nozdormu, el Atemporal, el Aspecto Dragón que vela por el tiempo. Sus dragones protegen sus caminos para que lo que fue no pueda deshacerse." },
        { "Ningún viajero llega muy adentro. Pero en la entrada se ha visto esperar a un dragón bronce en forma mortal, Anacronos. Sabe mucho sobre la guerra contra los insectos de Silithus hace mil años y sobre el papel de su Vuelo en ella." },
      },
    },
    ["cenarion-circle"] = {
      title = "El Círculo Cenarion",
      text = {
        { "El Círculo Cenarion es la comunidad de los druidas, llamada así por el semidiós Cenarius, que enseñó al primero de ellos. Su fundador fue Malfurion Tempestira, que dirigió a los elfos de la noche contra la Legión Ardiente hace diez mil años y ahora está desaparecido. Sus compañeros druidas no saben qué fue de él. Durante casi toda su historia fue una orden de los elfos de la noche. Ahora también hay druidas tauren y el archidruida Hamuul Runatótem los representa en Cima del Trueno." },
        { "Su sede es Amparo de la Noche, en el Claro de la Luna, bajo el guardián Rémulos, hijo de Cenarius. Tanto la Alianza como la Horda pueden caminar allí en paz. Mantiene puestos donde la naturaleza está herida: en la Cima del Espolón, en los bosques envenenados de Frondavil y en el Fuerte Cenarion de Silithus, desde el que vigila las colmenas de insectos y los muros de Ahn'Qiraj." },
        { "Los druidas tienen una paciencia que ningún enano entiende y piensan en estaciones y siglos. Cuando el Círculo dice que algo va mal, los sabios escuchan." },
      },
    },
    ["cenarion-hold"] = {
      title = "Fuerte Cenarion",
      text = {
        { "El Fuerte Cenarion es la fortaleza del Círculo Cenarion en el norte de Silithus, levantada para vigilar las colmenas y la ciudad sellada del sur. Druidas de la Alianza y la Horda protegen sus muros y desde aquí se libra la guerra contra los silítidos." },
        { "Algunos de sus habitantes no son lo que parecen. Entre los druidas vive el Linaje de Nozdormu, el Vuelo Bronce en forma mortal, que recuerda la guerra librada aquí hace mil años y vigila su regreso." },
      },
    },
    ["cenarius"] = {
      title = "Cenarius",
      text = {
        { "Cenarius fue el señor de los bosques, un semidiós con cuerpo de ciervo de cintura para abajo y astas ramificadas, y el primer maestro de los elfos de la noche. Mucho antes del Gran Cataclismo tomó cariño a sus jóvenes curiosos y les enseñó los caminos del mundo vivo. Malfurion Tempestira fue su mejor alumno y entre ambos crearon el druidismo." },
        { "Combatió a la Legión en la Guerra de los Ancestros, dirigiendo a los ancestros del bosque contra los demonios. Sobrevivió al Gran Cataclismo y ayudó a Malfurion a encerrar a Illidan. Después permaneció en el Claro de la Luna del Monte Hyjal. Sus hijos, los guardianes de la arboleda, vigilaron a los elfos de la noche mientras dormían los druidas. Sus hijas, las dríades, se dejaron ver más." },
        { "En la Tercera Guerra salió del bosque para expulsar de Vallefresno a los orcos de Grom Grito Infernal, y estos, enloquecidos por la sangre demoníaca, lo mataron. Sus hijos aún caminan por los bosques de Kalimdor, desde el Refugio de la Algaba hasta la Sierra Espolón, y Rémulos conserva el Claro de la Luna en su nombre. La memoria de un guardián es larga. Yo no sacaría el tema de los orcos con uno." },
      },
    },
    ["centaurs"] = {
      title = "Los centauros",
      text = {
        { "Los centauros descienden de Zaetar, hijo de Cenarius, y Theradras, princesa de la tierra elemental. Mataron a su padre. Su madre lo enterró en Maraudon. Sus hijos aún custodian la tumba como suelo sagrado." },
        { "Entre sus clanes están los Kolkar de Los Baldíos y Desolace, los rivales Gelkis y Magram, los Galak de Las Mil Agujas y los Maraudine de la tumba. Durante generaciones persiguieron a los tauren por las llanuras de Kalimdor, hasta que Cairne y sus aliados orcos los rechazaron." },
        { "Los clanes siguen atacando. Aprende sus nombres además del sonido de sus cascos, $gviajero:viajera;. Sus disputas importan a quienes intentan vivir al alcance de sus campamentos." },
      },
    },
    ["chillwind-camp"] = {
      title = "Campamento del Orvallo",
      text = {
        { "El comandante Ashlam Puñovalor dirige el campamento de la Alianza en las colinas del sur de Tierras de la Peste del Oeste, cerca del Lago Darrowmere. Sus tiendas han atraído a soldados, exiliados y estudiosos, entre ellos Weldon Barov, último señor vivo de su casa." },
        { "Desde aquí, la Alianza ataca Andorhal y combate los calderos de peste. Al campamento le sobran pocas comodidades o provisiones. Si puedes ayudar, Puñovalor sabrá aprovecharlo, $gviajero:viajera;. Sus tiendas son un pequeño comienzo para el trabajo que les espera." },
      },
    },
    ["church-of-the-holy-light"] = {
      title = "La Iglesia de la Luz Sagrada",
      text = {
        { "La Iglesia de la Luz Sagrada enseña que la virtud, la compasión y el sacrificio permiten recurrir a un poder capaz de sanar y proteger. La fe llegó al sur desde Lordaeron y hoy tiene su sede en la Catedral de la Luz de Ventormenta, bajo el arzobispo Benedictus. Los enanos también han aprendido sus preceptos de sus vecinos humanos." },
        { "Durante la Segunda Guerra, el arzobispo Alonsus Faol fundó los Caballeros de la Mano de Plata. Aquellos primeros paladines, dirigidos por Uther el Iluminado, llevaron la Luz al campo de batalla junto con sus espadas. Desde la caída de Lordaeron, Ventormenta se ha convertido en el centro de la iglesia, y sus sacerdotes y paladines sirven por toda la Alianza." },
        { "Las cuestiones de fe pueden ocupar a una estudiosa durante años. Quien llega herido tiene un motivo más inmediato para agradecer los conocimientos de un sacerdote." },
      },
    },
    ["coldridge-valley"] = {
      title = "Valle de Crestanevada",
      text = {
        { "Yunquemar reúne a los reclutas enanos y gnomos en el Valle de Crestanevada, al sur de Kharanos. Aquí encuentran a sus instructores, reciben sus primeras órdenes y descubren el paso de montaña que los llevará al resto de Dun Morogh. Un comienzo modesto, quizá, pero todo camino tiene uno." },
        { "Las órdenes no son simples ejercicios. Los troggs Mentueso amenazan el valle, los trols Peloescarcha han acampado cerca, y Balir Martilloescarcha y Grelin Barbablanca necesitan ayuda para combatirlos. Ten el arma a mano, $gviajero:viajera;. Los reclutas ya hacen falta antes de salir del valle." },
      },
    },
    ["crystal-pylons"] = {
      title = "Los pilones de cristal",
      text = {
        { "El trabajo de J.D. Collie empieza con los cristales de colores dispersos por Un'Goro. Las noticias de grandes pilones revestidos de cristales llevan sus investigaciones a las tierras salvajes, donde se alzan tres, al norte, al este y al oeste del cráter." },
        { "Distintas combinaciones producen efectos útiles en esos pilones y Collie ha escrito un manual para continuar los experimentos. La expedición ya puede hacer algo con los cristales aunque siga ignorando el propósito de sus creadores. Hay una satisfacción honrada en un descubrimiento que llega al banco de trabajo antes que a los libros de historia." },
      },
    },
    ["cthun"] = {
      title = "C'Thun",
      text = {
        { "C'Thun yace bajo el Templo de Ahn'Qiraj, uno de los poderes antiguos llamados dioses antiguos. Un ojo inmenso y masas de tentáculos llenan su cámara. Los qiraji y sus enjambres de silítidos lo sirven." },
        { "Quienes se acercan oyen susurros en su mente, promesas y amenazas de la criatura de abajo. La expedición lo encontró y lo mató. Puedo registrar esos hechos, pero me produce poco placer describir algo capaz de responder a sus observadores dentro de sus propios pensamientos, $gviajero:viajera;." },
      },
    },
    ["cult-of-the-damned"] = {
      title = "El Culto de los Malditos",
      text = {
        { "Kel'Thuzad era archimago de Dalaran y miembro de su consejo gobernante. Buscó cosas prohibidas en las artes nigrománticas hasta que algo respondió: el Rey Exánime. Dejó el Kirin Tor, fue entre los pobres y desesperados de Lordaeron y les prometió un mundo sin reyes ni hambre. Se convirtieron en el Culto de los Malditos y le creyeron." },
        { "El trabajo del culto fue la peste. Sus miembros contaminaron los graneros de Andorhal y las aldeas del norte, y los muertos se alzaron donde se comió aquel grano. El príncipe Arthas mató allí a Kel'Thuzad, pero el Rey Exánime lo necesitaba y regresó como exánime. La Casa Barov entregó su castillo de Castel Darrow al culto. En sus cámaras mantienen su escuela de nigromancia, Scholomance." },
        { "Son hombres y mujeres vivos, lo que me parece peor que los muertos. Un necrófago no elige a quién sirve. Los nigromantes del culto eligieron." },
      },
    },
    ["daelin-proudmoore"] = {
      title = "Daelin Valiente",
      text = {
        { "Daelin Valiente, almirante de Kul Tiras, fue un héroe de la Segunda Guerra: mandó las flotas de la Alianza junto a Anduin Lothar y Uther el Iluminado, y nunca perdonó a los orcos. También tenía una hija, Jaina, que marchó a estudiar magia a Dalaran." },
        { "Zarpó de Lordaeron con su flota antes de que Arthas lo destruyera, buscando supervivientes por los mares. Tras muchos meses encontró Kalimdor y a su hija, en paz con la Horda. No lo aceptó. Desembarcó a sus infantes de marina en la costa de Durotar, levantó este fuerte y se dispuso a destruir a los orcos antes de que echaran raíces." },
        { "Jaina tuvo que elegir entre su padre y la paz, y eligió la paz. Daelin murió en los combates antes de que pudieran reconciliarse. Su flota yace destrozada frente a esta playa y algunos de sus hombres aún ocupan el fuerte, en medio de una tierra que lleva el nombre de un orco." },
      },
    },
    ["dagran-thaurissan"] = {
      title = "Emperador Dagran Thaurissan",
      text = {
        { "Dagran Thaurissan gobierna a los Hierro Negro en Ciudad Forjatiniebla, descendiente del hechicero y señor feudal que invocó a Ragnaros. Conserva el nombre de su antepasado y yo conservo su historia. Dudo que coincidiéramos en buena parte de ella. El emperador se proclama el sirviente más poderoso del Señor del Fuego. Su corona no ha liberado a su clan del poder que su antepasado atrajo sobre él." },
        { "Empuña Ferromazo y sus agentes han llegado hasta Gnomeregan. También tomó por esposa a Moira, hija del rey Magni. Magni envió campeones a matarlo y traerla a casa. Mataron al emperador. La respuesta de Moira volvió bastante menos sencillo el resto del encargo." },
      },
    },
    ["dalaran"] = {
      title = "Dalaran",
      text = {
        { "Las agujas de Dalaran se alzaron junto al Lago Lordamere durante siglos, hogar del Kirin Tor y de generaciones de estudiantes de magia. En la Tercera Guerra, la Plaga tomó la ciudad y mató a Antonidas. Después, Archimonde destruyó lo que sus defensores no habían logrado salvar." },
        { client = "classic", "Los supervivientes del Kirin Tor han levantado una gran cúpula de luz violeta sobre las ruinas y comenzado la reconstrucción. Sus magos aún trabajan en Trabalomas y Argénteos, en el antiguo campo de internamiento y en Molino Ámbar. El archimago Ansirem Tejerruna recibe a los viajeros fuera de la cúpula. Reconforta ver a una ciudad empezar de nuevo, aunque sus constructores insistan en correr las cortinas." },
        { client = "forever", "Una crisis dentro de la ciudad ha interrumpido la reconstrucción. Algo ha alterado sus líneas Ley y vuelto erráticos y destructivos a sus constructos. El consejo quiere mantener el problema en privado. Modera, cuya imagen espera junto al Lago Lordamere, ha pedido ayuda exterior. Los magos han sobrevivido a la destrucción de una ciudad. Ella no piensa dejar que su orgullo contribuya a provocar otra." },
      },
    },
    ["dalsons-tears"] = {
      title = "Llanto de Dalson",
      text = {
        { "La granja que las Tierras de la Peste llaman Llanto de Dalson pertenecía a una familia de ese nombre. Su historia está abierta sobre una mesa de la casa, de puño y letra de la señora Dalson. Su marido, Harold, se había transformado. Le costó todas sus fuerzas arrastrarlo al único lugar que encontró con cerradura, y llevaba la llave consigo." },
        { "Pensaba marcharse, pero necesitaba dinero. Sus cosas estaban en el armario y creía que Harold llevaba esa llave encima. Descansaría antes de decidirlo, escribió. Estaba muerta de cansancio. Esa es la última entrada. El diario no cuenta qué fue de ella." },
        { "Desde entonces, la Plaga ha instalado uno de sus calderos en el campo familiar. Tanto la Alianza del Orvallo como los Renegados del Baluarte envían viajeros a volver sus venenos contra ella. Granja a granja, las Tierras de la Peste están llenas de casas como esta. Aquí alguien lo dejó por escrito." },
      },
    },
    ["dark-iron-dwarves"] = {
      title = "Los enanos Hierro Negro",
      text = {
        { "El tercero de los tres martillos y el que nunca perdonó. Desde que los Hierro Negro perdieron su guerra contra Forjaz y despertaron a Ragnaros en su furia, viven en la Montaña Roca Negra bajo su emperador, Dagran Thaurissan, al servicio del Señor del Fuego que invocaron." },
        { "No se han quedado allí. Sus esclavos excavan La Caldera en La Garganta de Fuego. Sus excavadores Forjatiniebla saquean Uldaman y ocupan la Fortaleza de Angor, en Tierras Inhóspitas. Sus espías se deslizan por Dun Morogh y sus asaltantes perturban Loch Modan. En Los Humedales han hecho verdadero daño: tomaron Dun Modr y rompieron el Puente Thandol, el gran puente del norte." },
        { "Un Hierro Negro combate con fuego, pólvora y un rencor de dos siglos. Nunca le des la espalda." },
      },
    },
    ["darkshire"] = {
      title = "Villa Oscura",
      text = {
        { "Villa Oscura es la única población que queda en el Bosque del Ocaso, unas casas, un ayuntamiento y una posada tras lámparas que arden día y noche. Su alcalde, Ello Cerranegro, gobierna con un concejo y sus familiares mandan La Guardia Nocturna. Una historiadora, Sirra Von'Indi, conserva sus registros y traducirá cuanto le lleves, con tiempo." },
        { "Es una villa de gente sombría y bromas sombrías, con más historias de las que debería tener un lugar de su tamaño. Pregunta a la vieja adivina, lady Eva, por cualquiera de ellas. Ya sabe por cuál vas a preguntar." },
      },
    },
    ["darkshore"] = {
      title = "Costa Oscura",
      text = {
        { "Costa Oscura es una larga franja de costa brumosa en el extremo norte de Kalimdor, con un oscuro pinar a un lado y el mar gris al otro. Teldrassil se alza del agua al oeste. Los elfos de la noche viven aquí desde antes del Gran Cataclismo y la costa está llena de sus ruinas: torres y salones de los Altonato, la antigua nobleza de la corte de la reina Azshara, cuyos fantasmas aún los recorren." },
        { "Últimamente es una costa agitada. Grandes criaturas marinas llegan a las playas para morir, los fúrbolgs Bosque Negro se han vuelto salvajes, los nagas merodean por las orillas y el Martillo Crepuscular ha acampado en el sur. Los elfos de la noche de Auberdine están preocupados y lo dicen, que, tratándose de ellos, ya es mucho." },
      },
    },
    ["darkspear-trolls"] = {
      title = "Los trols Lanza Negra",
      text = {
        { "Los Lanza Negra son trols de la selva emparentados con los Gurubashi de Tuercespina. Cuando la flota de Thrall llegó a sus islas de camino a Kalimdor, la tribu combatía contra los múrlocs y su bruja del mar. Los orcos lucharon a su lado. El jefe Sen'jin murió y los Lanza Negra supervivientes siguieron a Thrall al otro lado del mar." },
        { "Ahora Vol'jin los dirige desde Orgrimmar, cerca del Jefe de Guerra. Sus cazadores, chamanes y médicos brujos sirven por toda la Horda y conservan a los antiguos loa de los trols mientras buscan un hogar entre nuevos aliados." },
      },
    },
    ["darnassus"] = {
      title = "Darnassus",
      text = {
        { "Darnassus se alza en la copa de Teldrassil, una nueva capital construida tras la Tercera Guerra. La luz de la luna, las cascadas y el resplandor del Templo de la Luna llenan una ciudad de pocos muros y salones crecidos entre las ramas. Una enana de Forjaz está acostumbrada a tener bastante más piedra sobre la cabeza." },
        { "Los elfos de la noche se han unido a la Alianza y abierto esta ciudad a visitantes de pueblos de los que se mantuvieron apartados mucho tiempo. Tyrande Susurravientos dirige a las sacerdotisas desde el Templo, mientras Fandral Corzocelada guía a los druidas en el Enclave Cenarion. Apréndete esos dos lugares, $gviajero:viajera;. Buena parte de los asuntos de la ciudad comienza en uno u otro." },
      },
    },
    ["darnassus-tune"] = {
      title = "Darnassus",
      text = {
        { "Darnassus, la ciudad de los elfos de la noche, crece en las ramas de Teldrassil, y su melodía se oye allí y en las aldeas de abajo. Los elfos de la noche son un pueblo paciente. No me ha parecido sensato apremiarlos." },
      },
    },
    ["darrowshire"] = {
      title = "Villa Darrow",
      text = {
        { "Villa Darrow era una aldea del sur del Bosque del Este. Cuando llegó la Plaga, sus habitantes resistieron y lucharon, con el paladín Davil Fuegoluz de la Mano de Plata y Joseph Rutagrana al frente, contra el señor necrófago Horgus y el caballero de la muerte Marduz Pozonegro. Resistieron un tiempo. Al final, Marduz arrancó y corrompió el espíritu de Rutagrana, volviéndolo contra los defensores, y la aldea murió." },
        { "La batalla sigue en Villa Darrow, entre los fantasmas. Una niña, Pamela Rutagrana, recorre las ruinas esperando que su padre vuelva a casa. Se dice que con las reliquias de la batalla puede invocarse a los espíritus para que vuelvan a librarla y que esta vez quizá se salve el alma de Joseph Rutagrana." },
        { side = "Horde", aside = true, sign = "P. F.", "Cada aldea del Bosque del Este tuvo su Joseph Rutagrana. Villa Darrow es aquella cuyos muertos aún podrían terminar la historia de otra manera. Ayúdalos si puedes." },
      },
    },
    ["dartols-rod"] = {
      title = "La vara de Dartol",
      text = {
        { "Teronis, amigo de Raene Correlobo, ayudaba a las Centinelas de Astranaar contra los fúrbolgs, y creía que una vara creada por Dartol, un hechicero malvado ya muerto, podía frenar sus ataques. Fue a buscar su gema al santuario de una isla del Lago Falathim y no volvió. Encontraron allí su cuerpo, acuchillado con hojas de múrloc, con el diario todavía encima." },
        { "Gracias al diario y a una dríade llamada Shael'dryn, la vara se reconstruyó pieza a pieza: la gema, recuperada de los múrlocs, una parte sacada de un cofre cuya llave llevaba un antárbol corrupto cerca de la frontera con Frondavil, y la última, de El Túmulo de Dor'danil, cuyos druidas habían sido asesinados poco antes. Recompuesta y recargada en un santuario oculto en las montañas, la vara de Dartol permite a quien la lleva adoptar la forma de un fúrbolg." },
        { "Con esa forma, un viajero puede llegar hasta Krolg, un fúrbolg expulsado de su tribu y todavía libre del musgovil que enloquece a los demás. Culpa a los elfos de la noche, cuyo orgullo, dice, trajo la corrupción sobre el suyo. Pero no desea ningún mal a los hijos de los elfos, y tampoco excusa a los suyos, que siguen siendo responsables de sus actos. Ran Dentesangre, a quien la corrupción solo ha hecho más fuerte, es el mal que señala, y pide al viajero con forma de fúrbolg que acabe con él: los fúrbolgs, dice, deben vigilar a los suyos. Raene puso el cráneo de Ran y la vara en un lugar de honor, por Teronis. Krolg se quedó donde estaba, al sureste del Lago Mystral, mirando de noche las fogatas de su antigua tribu." },
      },
    },
    ["deadwind-pass"] = {
      title = "Paso de la Muerte",
      text = {
        { "El Paso de la Muerte corta un valle gris entre el Bosque del Ocaso y el Pantano de las Penas. Árboles muertos, cuervos y campamentos en ruinas bordean la ruta. No hay aldeas ni granjas en funcionamiento y los ogros dan pocos motivos para demorarse." },
        { "La torre de Medivh, Karazhan, se alza en su centro sobre edificios abandonados. El paso une dos regiones habitadas sin ofrecer sus comodidades." },
      },
    },
    ["deathknell"] = {
      title = "Camposanto",
      text = {
        { "Camposanto es una cripta y una aldea en ruinas en el extremo occidental de Tirisfal. Allí despiertan los Renegados. Llevan hasta aquí a los muertos de Lordaeron que resucitan dueños de su mente, y el custodio de la cripta los recibe con unas palabras que todos recuerdan: ya no eres esclavo del Rey Exánime." },
        { "No todos los que se alzan tienen tanta suerte. El norte de la aldea está lleno de muertos sin voluntad que aún pertenecen al Rey Exánime. El primer deber de los Renegados recién despertados es destruirlos: sus antiguos hermanos y hermanas, como les recuerdan los sacerdotes de las sombras de la capilla." },
      },
    },
    ["deathstalkers"] = {
      title = "Los mortacechadores",
      text = {
        { "Los mortacechadores son los ojos y cuchillos de los Renegados: la guardia de élite de lord Varimathras, según uno de sus reclutadores, enviada por delante de los ejércitos de la Dama Oscura para ver qué les espera. Los encontrarás donde los Renegados amplían sus fronteras: explorando las granjas del norte de Argénteos, dentro del Castillo de Colmillo Oscuro vigilando a Arugal, en las colinas sobre Trabalomas y recogiendo informes de las Tierras de la Peste para Nathanos." },
        { "Entrar no es cuestión de pedirlo. Los reclutas demuestran su valía y discreción en los propios cuartos traseros de Entrañas. Uno de esos encargos descubrió que el Sindicato, los señores caídos de Alterac, tenía un amigo entre los comerciantes de la ciudad. Con la aprobación de Varimathras, presume uno, sus filas crecen." },
        { "No todos son tan sombríos como el nombre. Rane y Quinn Yorick son hermanos. Rane, con Quinn apenas recuperado de las garras de un necrófago, quiere que entreguen su informe antes que nada. Muerto, pero aún aplicado. Los Renegados están llenos de sorpresas." },
      },
    },
    ["deeprun-tram"] = {
      title = "El Tranvía Subterráneo",
      text = {
        { "El Tranvía Subterráneo lleva pasajeros de Forjaz a Ventormenta en plataformas que se desplazan bajo tierra. Ha reducido un viaje de días a unos minutos. Hasta una enana aficionada a caminar sabe apreciar semejante logro." },
        { "El túnel da una forma práctica a nuestra amistad con Ventormenta: dos capitales unidas por una ruta que ahorra a sus viajeros el largo trayecto por tierra. El ingenio gnomo ha salvado muchísimos pares de botas." },
        { "Mira por las ventanas donde el túnel atraviesa el agua, $gviajero:viajera;. Algunos pasajeros dicen haber visto algo enorme que les devolvía la mirada. Debería darte tiempo a echar un vistazo antes de que la plataforma siga su camino." },
      },
    },
    ["defias-brotherhood"] = {
      title = "La Hermandad Defias",
      text = {
        { "Cuando los orcos arrasaron Ventormenta en la Primera Guerra, fue el Gremio de Canteros, bajo un maestro llamado Edwin VanCleef, quien la levantó de nuevo. Terminadas las obras, la Casa de Nobles se negó a pagar. VanCleef encabezó a sus albañiles en una revuelta por las calles nuevas y abandonó la ciudad jurando venganza." },
        { "El gremio se convirtió en banda. En Páramos de Poniente tomaron el nombre de Hermandad Defias, se cubrieron el rostro con paños rojos y se dedicaron a arruinar las tierras que alimentan a la ciudad: quemar campos, expulsar familias y aliarse con quien los aceptara. Ingenieros goblins trabajan para ellos en las Minas de la Muerte. Su influencia llega a Elwynn, Crestagrana, el Bosque del Ocaso y la propia prisión de la ciudad, donde Bazil Thredd, lugarteniente de VanCleef, amotinó a los presos." },
        { "Los albañiles tenían un agravio por su trabajo impagado. Pero, defendiera lo que defendiera antes la Hermandad, los granjeros de Páramos de Poniente lo han pagado mucho más caro que cualquier señor de Ventormenta." },
      },
    },
    ["demon-fall-canyon"] = {
      title = "Barranco del Demonio",
      text = {
        { "Después de que Grom Grito Infernal bebiera la sangre del demonio y matara a Cenarius, Thrall y Jaina Valiente lo persiguieron y lo liberaron de la maldición. Entonces Grom fue en busca del demonio. En un barranco de Vallefresno encontró a Mannoroth, el señor del foso cuya sangre había condenado a los orcos, y lo mató con su hacha, muriendo en el intento." },
        { "Los orcos lo recuerdan como quien los liberó y dieron su nombre al gran salón de Orgrimmar. El barranco sigue siendo un lugar de demonios: lo ocupan los sirvientes de la Legión Ardiente y la tierra donde cayó Mannoroth nunca ha quedado limpia." },
      },
    },
    ["desolace"] = {
      title = "Desolace",
      text = {
        { "Desolace hace honor a su nombre: una tierra gris, seca y de aspecto muerto al oeste de la Sierra Espolón, toda roca cenicienta, árboles marchitos y huesos. Crece poco. Muere mucho: los kodos vienen aquí para hacerlo y sus esqueletos se amontonan en un gran cementerio en medio de la comarca." },
        { "Si pertenece a alguien, es a los centauros. Sus clanes luchan entre sí por toda ella y su lugar más sagrado, Maraudon, está al suroeste. El Filo Ardiente ocupa una fortaleza al norte y abre puertas a los demonios, los nagas rondan la costa y la Alianza y la Horda mantienen sendos puestos pequeños e inquietos. Nadie ama esta tierra." },
      },
    },
    ["dire-maul"] = {
      title = "La Masacre",
      text = {
        { "La Masacre fue Eldre'Thalas, una ciudad de los Altonato construida en tiempos de la reina Azshara para guardar sus secretos arcanos más preciados. Sobrevivió al Gran Cataclismo y buena parte sigue en pie: una ciudad de piedra blanca en el bosque, con salones llenos de libros y fantasmas." },
        { "Ahora está dividida en tres. Los ogros Gordok dominan el norte y coronan a un nuevo rey cada vez que matan al anterior. El sátiro Alzzin el Formaferal ocupa el este y ha corrompido el Fruto de la Fertilidad de la ciudad hasta convertirlo en una inmundicia llamada gangrevid. El oeste sigue en manos de los últimos Altonato, los Shen'dralar, alrededor de su biblioteca, por cuya lectura daría mucho." },
      },
    },
    ["dire-maul-tune"] = {
      title = "La Masacre",
      text = {
        { "En algún rincón de La Masacre, la ruina de Eldre'Thalas en Feralas, suena una pieza que no he encontrado en ningún otro sitio. Alzzin el Formaferal domina la parte este de la ciudad. Un prisionero de su príncipe caído, a quien un diablillo robó cuando huía, te pedirá que recuperes su libro de conjuros, y yo lo haría. Cambió la inmortalidad por la libertad, y un trato así no se hace dos veces." },
      },
    },
    ["dolanaar"] = {
      title = "Dolanaar",
      text = {
        { "Dolanaar está en el camino de Cañada Umbría a Darnassus, alrededor de un pozo de la luna, con una posada y edificios entre los árboles. Aquí trabajan druidas y centinelas, muy cerca de los problemas del bosque. Es una parada útil antes de continuar hacia la capital." },
        { "Últimamente se ocupan de los fúrbolgs Tuercepinos, los sátiros de las cuevas y las criaturas enfermas del bosque. El aspecto tranquilo de la aldea revela poco de ese trabajo. Escucha lo que te piden sus guardianes. Han visto cómo cambiaban las tierras de alrededor." },
      },
    },
    ["dorn-plainstalkers-tests"] = {
      title = "Las pruebas de Dorn Acechallanos",
      text = {
        { "Dorn Acechallanos, un tauren que vive en el Risco Pezuña Quebrada, sobre Las Mil Agujas, sostiene que un ser está hecho de espíritu, cuerpo y mente, y que cada uno puede ponerse a prueba. Pone a prueba a los jóvenes de cualquier tribu de la Horda que acuden a él, porque demasiados, según ha visto, salen de casa antes de estar preparados para lo que les espera fuera." },
        { "Primero viene la fe: un salto desde los tablones que dominan Las Mil Agujas, sin promesa de salir con vida. El cuerpo se prueba dos veces. La resistencia consiste en saquear la Guarida Malapluma, al oeste del Poblado Viento Libre, hasta que Grenka Aullasangre salga en persona a por el intruso. La fuerza se mide contra Rok'Alim el Aporreador, un elemental de un orden más antiguo. Los Dioses Antiguos, dice Dorn, ataban antaño a los elementales a este mundo, y cuando cayeron, la mayoría de los elementales se fue con ellos y ahora solo vuelve cuando la llama un invocador. Algunos fueron lo bastante fuertes para quedarse. Rok'Alim es uno de ellos." },
        { "La mente no le corresponde a Dorn. Envía a sus alumnos a Braug Espiritoscuro, un chamán que espera junto a El Paso del Espolón y que llama juego de niños a todo lo que han hecho hasta entonces. Braug les da un libro que leer, el Legado de los Aspectos, que está en el fondo de El Túmulo de Dor'danil, en Vallefresno, y después les pregunta por él. Luego los manda al otro lado del mar, a Entrañas, con Parqual Fintallas, que primero quiere que le roben un libro del Monasterio Escarlata y después les plantea otra pregunta. Quienes vuelven al Risco Pezuña Quebrada encuentran a Dorn esperándolos. Es el único rito de paso que conozco que manda a sus aspirantes a la biblioteca, dos veces, y lo apruebo." },
        { side = "Horde", aside = true, sign = "P. F.", "Los alumnos de Braug llegan muy seguros de sí mismos, y yo les digo que no son más que un rumor de taberna. Los que me demuestran lo contrario son los que recuerdo." },
      },
    },
    ["draenor"] = {
      title = "Draenor",
      text = {
        { "Antes de atravesar el Portal, los orcos vivían en un mundo verde propio llamado Draenor, en clanes que vagaban, cazaban y discutían como suelen hacer los clanes. Sus chamanes hablaban con los espíritus de los elementos y de los antepasados. El anciano chamán Ner'zhul era el más respetado de todos. Compartían el mundo con los draenei, exiliados de otro lugar que construían sus ciudades en los riscos y daban a los orcos pocos motivos de guerra." },
        { "El demonio Kil'jaeden les dio uno. Manipuló a Ner'zhul hasta que su pueblo empezó a tener sed de sangre. Cuando el chamán retrocedió ante el último paso, encontró a un alumno más dispuesto en su aprendiz, Gul'dan. Los chamanes se volvieron brujos. Se construyeron arenas para los combates de los clanes. Gul'dan reunió a los jefes y bebieron la sangre del señor del foso Mannoroth. Según el libro de nuestra biblioteca, solo Durotan de los Lobo Gélido se negó." },
        { "La Horda resultante casi exterminó a los draenei. La magia de los brujos empezó a matar la propia tierra, hasta que las praderas que los orcos habían recorrido durante generaciones quedaron rojas y estériles. Cuando se abrió el Portal Oscuro, quedaba poco en Draenor por lo que mereciera quedarse. Los exiliados del Puerto, en el Pantano de las Penas, dicen haber venido de aquel mundo. Yo tendría cuidado con lo que les dices de los orcos." },
      },
    },
    ["dragonmaw-clan"] = {
      title = "El clan Faucedraco",
      text = {
        { "Los Faucedraco montaron dragones rojos en la Segunda Guerra. En Grim Batol mantuvieron cautiva a Alexstrasza y obligaron a sus hijos a servir a la Horda. Su dominio del cielo se sostenía en el cautiverio de una madre y sus crías." },
        { "La liberación de los dragones quebró la fuerza del clan, pero sus restos aún ocupan las colinas de Los Humedales y asaltan los caminos. Son supervivientes de la antigua Horda, no seguidores de la nueva." },
      },
    },
    ["dragons-of-nightmare"] = {
      title = "Los Dragones de la Pesadilla",
      text = {
        { "Los dragones verdes de Ysera custodian el Sueño Esmeralda, el mundo intacto por el que viajan los druidas dormidos. Cuatro lugartenientes vigilaban sus portales de grandes árboles: Ysondre, Lethon, Emeriss y Taerar, en el Bosque del Ocaso, Tierras del Interior, Feralas y Vallefresno." },
        { "La Pesadilla se ha apoderado de ellos. Emergen deformados y atacan a quienes se acercan. Emeriss propaga podredumbre, Taerar se divide en sombras y Lethon extrae los espíritus de los caídos. Rémulos reúne fragmentos de corrupción de los portales para investigarlos. Quien llega a uno de esos árboles puede encontrar que el propio guardián que debía hacerlo seguro se ha convertido en su peligro." },
      },
    },
    ["dreadlords"] = {
      title = "Los señores del terror",
      text = {
        { "Los señores del terror, los nathrezim, son los conspiradores de la Legión Ardiente: vampíricos, pacientes, mejores corrompiendo que conquistando. Kil'jaeden los puso a vigilar a su creación más peligrosa, el Rey Exánime. Tichondrius, el más astuto, se deleitaba con la peste. Mal'Ganis esperó al príncipe Arthas en Stratholme. Anetheron combatió junto a Archimonde en el Monte Hyjal." },
        { "Cuando menguó el poder del Rey Exánime, sus carceleros intentaron tomar Lordaeron para sí. Lo perdieron ante Sylvanas y sus Renegados, que construyeron su ciudad bajo la capital en ruinas. Ahora Varimathras sirve allí a la Dama Oscura, le guste o no. Balnazzar lleva el rostro del propio dirigente de la Cruzada Escarlata en Stratholme." },
        { "Un señor del terror rara vez te muestra lo que es. Si alguien con autoridad parece empeñado en que vivos y muertos sigan matándose, merece la pena preguntar quién sale ganando, $gviajero:viajera;." },
      },
    },
    ["druids"] = {
      title = "Druidas",
      text = {
        { "El primer druida fue Malfurion Tempestira, instruido por el semidiós Cenarius antes de la Guerra de los Ancestros. Tras la destrucción del Pozo, lo siguieron los elfos de la noche que habían abandonado lo arcano. Durante miles de años, los druidas durmieron en el Sueño Esmeralda y solo despertaron cuando el mundo los necesitó." },
        { "Ahora despiertan y no son solo elfos de la noche: los tauren tienen sus propios druidas y ambos responden ante el Círculo Cenarion del Claro de la Luna. Un druida adopta formas salvajes, entre ellas oso, felino y foca, sana con la magia verde del Sueño e invoca la luna y las estrellas contra sus enemigos." },
        { client = "forever", "Los druidas cielonatos practican ahora a ambos lados de la disputa entre la Alianza y la Horda." },
        { "El propio Malfurion ha entrado en el Sueño y no ha regresado. Pese a todo el trabajo del Círculo en el mundo despierto, su mayor maestro sigue fuera del alcance de un mensajero corriente." },
      },
    },
    ["druids-of-the-fang"] = {
      title = "Los Druidas del Colmillo",
      text = {
        { "Los Druidas del Colmillo eran discípulos de Naralex, una orden de nobles druidas que entró en las Cuevas de los Lamentos para sanar Los Baldíos. La pesadilla que se apoderó de su maestro también los alcanzó. Ahora pretenden rehacer la tierra a imagen de sus sueños retorcidos y han adoptado formas y nombres de serpiente." },
        { "Tienen cuatro dirigentes: lord Cobrahn, lady Anacondra, lord Pythas y lord Serpentis. Cada uno lleva una gema del sueño. Los druidas de Cima del Trueno dicen que sus rostros los atormentan. Quieren que las gemas vuelvan a casa." },
      },
    },
    ["druids-of-the-talon"] = {
      title = "Los Druidas de la Garfa y de la Zarpa",
      text = {
        { "Los druidas de Malfurion nunca fueron una sola orden. Algunos adoptaron la forma del gran oso y se convirtieron en los Druidas de la Zarpa. Otros tomaron la forma del cuervo de tormenta y fueron los Druidas de la Garfa. Ambos mantuvieron el pacto con Ysera y durmieron durante siglos en sus túmulos mientras sus espíritus recorrían el Sueño Esmeralda. En la Tercera Guerra, Malfurion los despertó para combatir." },
        { "Algunos aún duermen. En el Túmulo de Ban'ethil de Teldrassil, los Druidas de la Garfa hibernan bajo la vigilancia de un gran celador. Los fúrbolgs Tuercepinos han irrumpido allí y uno de ellos, Ursal el Violento, ha interferido con la llamada de los durmientes hasta ponerlos en peligro de no despertar jamás. Un druida de la Zarpa perdido en el mismo túmulo ha visto cómo su propio cuerpo se volvía contra él." },
        { "No siempre es fácil despertarlos. Kerlonian Semprumbrío, un druida de la Zarpa recién vuelto del Sueño, dormita junto al camino de Costa Oscura y pide que lo despierten con su cuerno si se adormece durante el viaje. Diez mil años son mucho tiempo para llevar cansado." },
      },
    },
    ["dun-garok"] = {
      title = "Dun Garok",
      text = {
        { "Dun Garok es una fortaleza enana construida en las colinas del sureste de Trabalomas, muy lejos de casa. Su guarnición, bajo el capitán Ferrocolina, defiende los pasos y protege a los habitantes de las laderas y las minas cercanas. Es un pequeño y obstinado puesto de Forjaz en una tierra de muertos, y me enorgullece." },
        { "Los Renegados lo odian y envían asaltantes contra él. Los enanos los mandan de vuelta." },
      },
    },
    ["dun-modr"] = {
      title = "Dun Modr",
      text = {
        { "Dun Modr se construyó para proteger el extremo sur del Puente Thandol y lo hizo durante muchos años. Ahora no ondea en él ningún estandarte Barbabronce. Los Hierro Negro lo han tomado y desde sus muros atacan el puente y a cualquiera que viaje por el camino del norte." },
        { "Para un enano de Forjaz es amargo ver salones enanos ocupados por enanos contra nosotros. Nos recuerda que la Guerra de los Tres Martillos nunca terminó del todo." },
        { "Si pasas cerca, agacha la cabeza. Sus fusileros son muy buenos." },
      },
    },
    ["dun-morogh"] = {
      title = "Dun Morogh",
      text = {
        { "Dun Morogh es la región de montañas nevadas que rodea Forjaz, hogar de los enanos del clan Barbabronce y de sus vecinos gnomos." },
        { "Es nuestra, pero la compartimos, y no siempre por elección. Los trols Peloescarcha ocupan las colinas occidentales, los troggs excavan donde les place y, desde la caída de Gnomeregan, los gnomos son vecinos nuestros tanto en sus propios valles como en nuestra ciudad." },
        { "Apréndete bien sus caminos, $gviajero:viajera;. La mayoría de los enanos que conocerás dieron en ellos sus primeros pasos." },
      },
    },
    ["durnholde-keep"] = {
      title = "Castillo de Durnholde",
      text = {
        { "Durnholde controlaba los campos de internamiento orcos tras la Segunda Guerra. Su amo, Aedelas Lodonegro, crio a un niño orco como esclavo y gladiador, con la intención de que mandara un ejército obediente. El niño era Thrall. Taretha Foxton, una muchacha de la casa de Lodonegro, se hizo su amiga y lo ayudó a escapar." },
        { "Thrall acabó liberando a su pueblo. Lodonegro ha muerto y el Sindicato ocupa el castillo. Sus ambiciones sobrevivieron en otro lugar: en una mansión junto al Lago Lordamere, Aliden Perenolde planea esclavizar orcos a su vez. Su compañera Elysa lleva el colgante de Taretha." },
        { "Thrall quiere recuperarlo. Un colgante parece poca cosa junto a la caída de una fortaleza, $gviajero:viajera;. Ese colgante conserva el nombre de alguien cuya ayuda hizo posible aquella caída." },
        { side = "Horde", aside = true, sign = "P. F.", "Una muchacha de una casa de Lordaeron hizo más por los orcos que toda su Alianza. Su nombre merece figurar en más historias que esta." },
      },
    },
    ["durotan-and-draka"] = {
      title = "Durotan y Draka",
      text = {
        { "Durotan era el jefe del clan Lobo Gélido, el único jefe que se negó a beber. Cuando Gul'dan reunió a los clanes para beber la sangre de Mannoroth, Durotan se negó y advirtió a todo el que quiso escucharlo de que los brujos estaban destruyendo lo que habían sido los orcos. Gul'dan no podía matar abiertamente a un héroe tan popular, de modo que lo exilió con todo su clan al extremo del nuevo mundo: estas montañas." },
        { "Su compañera Draka marchó al exilio con él, junto a su hijo recién nacido. Durotan regresó una vez más para advertir a su viejo amigo Orgrim Martillo Maldito sobre Gul'dan. Los asesinos de Gul'dan lo siguieron a casa y lo mataron a él y a Draka. Un oficial humano, Aedelas Lodonegro, encontró a su bebé junto a ellos, lo crio como esclavo y le dio el nombre de Thrall." },
        { "Los Lobo Gélido conservan una tumba para Durotan en el Valle de Alterac. Su clarividente, Drek'Thar, escribió las palabras: el más valiente de los suyos, traicionado por quienes querían ver esclavizados a los orcos. El padre del Jefe de Guerra nunca vio en qué se convirtió su hijo, $gviajero:viajera;. Los Lobo Gélido se aseguran de que el pueblo de su hijo sepa de quién es hijo." },
      },
    },
    ["durotar"] = {
      title = "Durotar",
      text = {
        { "Durotar es una tierra dura: tierra roja, roca roja, espinas y escorpiones, abrasada por el sol y cortada por cañones secos, con el mar a un lado y las largas llanuras de Los Baldíos al otro. Los orcos la eligieron de todos modos. Thrall le dio el nombre de su padre, Durotan, jefe del clan Lobo Gélido, asesinado antes de que su hijo pudiera conocerlo." },
        { "La Horda llegó después de la última guerra, tras cruzar el mar desde los campos de Lordaeron y luchar junto a elfos de la noche y humanos en el Monte Hyjal. La paz duró poco: el almirante Daelin Valiente de Kul Tiras, padre de Jaina Valiente, llevó su flota contra los orcos y fue derrotado. Desde entonces, los orcos no han dejado de construir: Orgrimmar al norte, Cerrotajo junto al camino y el Poblado Sen'jin para sus aliados trols." },
        { "No han terminado de asegurar el territorio. Los centauros atacan desde el oeste, los jabaespines dominan el sur y, en las cuevas de Roca del Cráneo, a la vista de la capital, el Filo Ardiente adora a los demonios que esclavizaron a los orcos. Durotar es joven y lo sabe." },
      },
    },
    ["duskwood"] = {
      title = "Bosque del Ocaso",
      text = {
        { "Al sur de Elwynn, los árboles se cierran, la luz se vuelve gris y estás en el Bosque del Ocaso. Antes formaba parte del mismo bosque verde. Los humanos vivían y cultivaban aquí como en Elwynn. Después cayó sobre estos bosques una oscuridad que nunca se ha levantado. Nadie en Villa Oscura sabe decir con certeza por qué, aunque muchos miran al este, hacia las tierras muertas del Paso de la Muerte y la torre que se alza en ellas." },
        { "Lo que trajo la oscuridad está bastante claro. Los muertos se alzan del cementerio del Cerro del Cuervo, los ferocanis cazan en el bosque, las arañas alcanzan el tamaño de ponis y los ogros se han instalado en las colinas. Las granjas están abandonadas. Quienes quedan se han reunido tras las lámparas de Villa Oscura, defendidos por su propia milicia, porque Ventormenta ha retirado a sus guardias. Es un lugar para viajeros valientes y para historias junto al fuego, con la puerta atrancada." },
      },
    },
    ["dustwallow-marsh"] = {
      title = "Marjal Revolcafango",
      text = {
        { "Marjal Revolcafango es un amplio pantano húmedo de la costa oriental de Kalimdor, al sur de Los Baldíos: juncos, charcas negras, crocoliscos, raptores y mucha niebla. En una isla frente a su costa está Theramore, la ciudad humana de lady Jaina Valiente. En el sur del pantano se extiende Ciénaga de Fuego, donde Onyxia tiene su guarida." },
        { "Entre ambas están los ogros de Murohelecho, que sirven a la Horda, las ruinas quemadas de una posada sobre la que todos tienen una teoría y muchos dragones negros. Es un marjal donde la Alianza y la Horda han acordado ser vecinas y donde ambas observan con mucha atención." },
      },
    },
    ["dwarves"] = {
      title = "Los enanos de Forjaz",
      text = {
        { "Los enanos dominan Khaz Modan desde Forjaz desde antes de que alguien escribiera su historia. Durante mucho tiempo tampoco supieron de dónde venían. Los discos que la Liga recuperó en Uldaman sugieren una respuesta que los estudiosos aún discuten: que los primeros enanos fueron terráneos, hechos de piedra por los titanes y convertidos con el tiempo en carne." },
        { "Tres clanes compartían la montaña bajo un gran rey. Cuando murió, fueron a la guerra por su trono. Los Barbabronce conservaron Forjaz, los Martillo Salvaje marcharon al norte y los Hierro Negro despertaron al Señor del Fuego en el sur. Ahora gobierna el rey Magni Barbabronce. Su hermano Muradin marchó al norte con el príncipe de Lordaeron y no ha vuelto a ser visto. Su hermano Brann recorre el mundo para la Liga, que es más o menos donde esperamos que esté." },
        { "Son un pueblo robusto, prudente y generoso que conserva sus rencores tan bien como su cantería, y lo digo con cariño. Si un enano te dice que un puente aguantará, aguantará, $gviajero:viajera;. Si dice que la cerveza es buena, fórmate tu propia opinión." },
      },
    },
    ["earth-mother"] = {
      title = "La Madre Tierra",
      text = {
        { "Los tauren veneran a la Madre Tierra como origen del mundo y de su vida. Sus tradiciones enseñan a respetar los dones de la tierra y a no malgastarlos. Los chamanes hablan con sus espíritus, los videntes siguen visiones y los antepasados siguen formando parte de la vida de quienes vienen después." },
        { "Los jóvenes tauren emprenden los Ritos de la Madre Tierra antes de que los ancianos de Cima del Trueno los acepten. La fuerza se demuestra frente a los enemigos de la tribu. La visión llega mediante el Agua de los Videntes y lo que aparece en el fuego. La sabiduría exige la bendición de los antepasados en Roca Roja. El viaje termina ante el gran jefe." },
        { "Presta atención a los ritos si quieres entender a tus anfitriones, $gviajero:viajera;. La caza, la memoria y la tierra están unidas en la forma en que un joven tauren se gana su lugar entre los suyos." },
      },
    },
    ["earthen"] = {
      title = "Los terráneos",
      text = {
        { "Los terráneos fueron los canteros de los titanes, hechos de roca viva para tallar las profundidades del mundo. Cuando los titanes se marcharon, siguieron moldeándolas y custodiándolas, poco interesados en lo de arriba. El Gran Cataclismo los hirió como hirió a la propia tierra. Perdieron mucho de lo que habían sido y se encerraron en las bóvedas donde los crearon: Uldaman, Uldum y Ulduar, según las nombra el libro de nuestra biblioteca." },
        { "Después de casi ocho mil años, los terráneos de Uldaman despertaron. Encontraron sus pieles de piedra ablandadas en piel y debilitado su poder sobre la roca. Se habían vuelto mortales. Se llamaron enanos, salieron al mundo despierto y fundaron un reino bajo la mayor montaña de la comarca, Khaz Modan, la montaña de Khaz'goroth, alrededor de una forja levantada en su honor." },
        { "No todos despertaron. Aún hay terráneos de guardia en los salones de Uldaman y toda expedición de la Liga los encuentra. No parecen saber de quién somos parientes." },
      },
    },
    ["earthen-ring"] = {
      title = "El Anillo de la Tierra",
      text = {
        { "El Anillo de la Tierra es un círculo de chamanes dedicado a estudiar y preservar los elementos. Han olvidado más sobre dioses antiguos extraños, leyendas y saberes remotos de lo que la mayoría de los estudiosos conocerán jamás, dice un explorador de la Horda en Vallefresno. Cuando aparece algo de los elementos que nadie explica, se lo llevan a ellos." },
        { "Permanecen en los márgenes. Un chamán de Zoram'gar, en la costa de Vallefresno, estudia lo que el mar devuelve de Brazanegra. Otro espera en la Esperanza de la Luz, donde los muertos aprietan más. Incluso quienes dudan de sus compañías han llamado puras a sus intenciones. El Anillo tendió una mano a los Renegados y algunos en Cima del Trueno se preguntan ahora si fue prudente." },
        { "Una sociedad erudita que responde ante los elementos en vez de ante un rey. La Liga reconoce el modelo y lo envidia un poco." },
      },
    },
    ["eastern-plaguelands"] = {
      title = "Tierras de la Peste del Este",
      text = {
        { "El Bosque del Este albergaba las aldeas orientales de Lordaeron, abadías y la ciudad de Stratholme. La peste lo transformó en Tierras de la Peste del Este. Sus árboles están muertos o muriéndose, grandes hongos crecen entre ellos y el agua inmunda recorre una tierra dominada en gran parte por la Plaga." },
        { "La Capilla de la Esperanza de la Luz cobija al Alba Argenta al este. La Cruzada Escarlata conserva Mano de Tyr al sureste. Tirión Vadín vive exiliado junto al Río Thondroril y Nathanos Clamañublo ocupa su antigua granja en la Hacienda Marris. Estos habitantes dispersos tienen propósitos muy distintos." },
      },
    },
    ["echo-isles"] = {
      title = "Las Islas del Eco",
      text = {
        { "Las Islas del Eco iban a ser el nuevo hogar de los trols Lanza Negra, un grupo de islas selváticas frente a la costa de Durotar muy parecido al que habían dejado. Un médico brujo llamado Zalazane lo cambió todo. Recurrió a la magia oscura, hechizó a los suyos y los sometió a su voluntad. Los Lanza Negra leales tuvieron que huir de las islas al continente." },
        { "Zalazane aún gobierna las islas y desde ellas envía a sus trols sometidos a cruzar el agua para arrastrar a más miembros de la tribu bajo su control. Sus víctimas no siempre descansan al morir: los trols dicen que las almas de algunas están atrapadas en sus propios cráneos, en un círculo de poder de la isla mayor." },
      },
    },
    ["edwin-vancleef"] = {
      title = "Edwin VanCleef",
      text = {
        { "Edwin VanCleef era el maestro del Gremio de Canteros, el hombre que reconstruyó Ventormenta. Cuando los nobles se negaron a pagar a sus albañiles, se mantuvo al lado de quienes habían trabajado para él. Los encabezó en una revuelta por las calles que habían construido y fuera de la ciudad. En Páramos de Poniente, el gremio se convirtió en la Hermandad Defias." },
        { "La dirigió hasta el final desde su barco en las profundidades de las Minas de la Muerte, y nunca perdonó a Ventormenta. Quienes por fin llegaron hasta él hallaron en su cuerpo una carta sellada y nunca enviada al arquitecto urbano. Adónde llevó esa carta es otra historia." },
        { "He intentado escribir sobre él con justicia. Sufrió un agravio y a cambio hizo mucho daño. Los granjeros de Páramos de Poniente pagaron por ambas cosas." },
      },
    },
    ["eitrigg"] = {
      title = "Eitrigg",
      text = {
        { "Eitrigg aconseja a Thrall en Orgrimmar, un viejo guerrero con conocimientos que la nueva Horda aún necesita. Cuando el señor de la guerra Dientegore supo que Desgarro Puño Negro seguía vivo, envió a aventureros a consultar con Eitrigg sobre los Roca Negra." },
        { "La rivalidad entre los dirigentes de la Horda le había costado a sus hijos y lo había apartado de sus guerras. Cuando vivía solo cerca de Vega del Amparo, combatió con Tirión Vadín y después salvó al paladín de una torre que se derrumbaba. Más tarde, Tirión lo defendió a costa de su posición en la Mano de Plata." },
        { "Durante el ataque de Thrall contra Stratholme, Tirión liberó a Eitrigg. Fuera de la ciudad, Thrall le pidió ayuda para restaurar las antiguas costumbres de la Horda y él aceptó." },
      },
    },
    ["elementals"] = {
      title = "Los elementales",
      text = {
        { "Los elementales son los soldados más antiguos del mundo. Servían a los dioses antiguos antes de que llegaran los titanes, y cuando sus amos quedaron encadenados bajo la tierra, fueron expulsados a un plano propio, donde los señores del fuego, la tierra, el aire y el agua siguen guerreando entre sí. Lo que un viajero encuentra a este lado suele haberse colado, haber sido arrastrado o haberse quedado atrás: la roca que camina por las Tierras Inhóspitas, un torbellino suelto en Las Mil Agujas o en las arenas de Silithus, el agua inquieta de la costa de Tuercespina." },
        { "Las cortes elementales son tan aficionadas a los rangos como cualquier rey, con príncipes, duques y barones. Ragnaros el Señor del Fuego fue llamado al mundo por un thane de los Hierro Negro y no lo ha abandonado. Consumió la esencia del Príncipe Thunderaan, uno de los señores del aire, y sus lugartenientes mantienen atado lo que queda del príncipe. Los siervos de Neptulon el Cazamareas odian el fuego por encima de todo: el duque Hydraxis hace aliados entre los mortales desde su isla frente a Azshara, y un enviado del Tribunal de las Mareas en el Refugio Roca del Sol paga por cada elemental de fuego extinguido en La Vega Carbonizada de Sierra Espolón. En Maraudon vive la princesa Theradras, una fuerza elemental de la tierra que los druidas dicen emparentada con los dioses antiguos. En Silithus, el Martillo Crepuscular invoca a nobles elementales y recibe órdenes de ellos." },
        { "Algunos ya no pueden servir a nadie. La peste corrompió a los elementales de agua que los Señores del Agua enviaron a las Tierras de la Peste del Este hasta enfermarlos y enfurecerlos, y el duque Hydraxis lo llama una afrenta a su pureza. Los chamanes hablan con los elementos y obtienen respuesta. Los demás, $gviajero:viajera;, solemos recibir por respuesta un puño de piedra." },
      },
    },
    ["elune"] = {
      title = "Elune",
      text = {
        { "Elune es la diosa de la luna y la fe más antigua de los elfos de la noche. Antes del Gran Cataclismo creían que dormía de día en las profundidades del Pozo de la Eternidad y despertaba con la noche. Sus sacerdotisas cuidaban sus templos entonces y los cuidan ahora, en el Templo de la Luna de Darnassus." },
        { "Les responde. Los elfos de la noche dicen deberle a su gracia haber sobrevivido al Gran Cataclismo. Una suma sacerdotisa de Elune, Tyrande Susurravientos, los ha dirigido durante los diez mil años posteriores. Sus pozos de la luna riegan sus poblaciones y sus sacerdotisas sanan con su luz. En combate, según me dicen, pueden invocarla de forma mucho menos suave." },
        { "Un elfo de la noche rara vez te impondrá su diosa. Han tenido mucho tiempo para aprender a ser pacientes con las creencias ajenas y con los demás." },
      },
    },
    ["elwynn-forest"] = {
      title = "Bosque de Elwynn",
      text = {
        { "Elwynn es el bosque que alimenta a Ventormenta: grandes árboles antiguos, prados abiertos, granjas, viñedos y el lento río que baja hacia Páramos de Poniente. Es la comarca más apacible de las tierras humanas. Al recorrer sus caminos una mañana de verano, cuesta creer lo que ocurrió aquí." },
        { "Durante la Primera Guerra, los orcos atravesaron estos bosques. Quemaron las granjas, la abadía y los pueblos uno tras otro, y después tomaron la propia ciudad. El reino se reconstruyó tras la Segunda Guerra y los bosques vuelven a albergar granjas y poblaciones." },
        { "La paz es más frágil de lo que parece. Los kóbolds han ocupado las minas, los gnolls Zarparrío atacan desde el oeste y los Defias de máscaras rojas se han extendido desde Páramos de Poniente hasta estos bosques. Pregunta a cualquier granjero de Elwynn si los soldados del rey acuden cuando los llaman." },
      },
    },
    ["emerald-sanctuary"] = {
      title = "El Santuario Esmeralda",
      text = {
        { "El Santuario Esmeralda es una arboleda del sur de Frondavil ocupada por el Círculo Esmeralda, druidas del Círculo Cenarion que han jurado sanar el bosque. Combaten a los sátiros Fuego de Jade y al Consejo de la Sombra y estudian el ámbar de sangre de los elementales corruptos, con la esperanza de aprender a salvar a los demás." },
        { "Su paciencia es enorme. Limpian las flores del cantar y las flores del viento contaminadas una por una y purifican los espíritus de los ancestros que los sátiros ataron con magia vil. Es un trabajo lento y saben que quizá dure más que sus propias vidas. Son elfos de la noche. Bien podrían tener razón." },
      },
    },
    ["eranikus"] = {
      title = "Eranikus",
      text = {
        { "Eranikus es un dragón del Vuelo Verde de Ysera y custodio del templo hundido. Su misión era impedir que los trols volvieran a traer a su dios. Según sus propias palabras, ha fracasado, y le ha ocurrido algo peor. Mientras dormía sobre el templo quedó atrapado en algo oscuro del Sueño que le retuerce la mente." },
        { "En las profundidades del templo, su sombra yace entre el sueño y la muerte, enredada en pesadillas. Lo que queda de su voluntad pide ayuda a los viajeros. Otro dragón verde, Itharius, espera en una cueva del pantano con la esperanza de redimirlo. Le deseo suerte. La Pesadilla que retiene a Eranikus es la misma que se ha apoderado de los lugartenientes de Ysera en los grandes árboles." },
      },
    },
    ["everlook"] = {
      title = "Vista Eterna",
      text = {
        { "Vista Eterna es una población goblin en el centro de Cuna del Invierno, la escala más septentrional del Cártel Bonvapor, con muros, posada, banco y guardia de matones goblins, donde la Alianza y la Horda comercian juntas. Dentro hace más calor del que esperarías y todo es mucho más caro." },
        { "Todo el mundo pasa por Vista Eterna. El Alba Argenta mantiene aquí un representante y la Hermandad del Torio un herrero. Todos los cazadores, exploradores y estudiosos del norte se detienen a calentarse los pies." },
      },
    },
    ["excavation-site-wetlands"] = {
      title = "Excavación: Los Humedales",
      text = {
        { "El pantano del prospector Whelgar no es la única excavación de Los Humedales. Un equipo venido de Loch Modan subió a las colinas que lo dominan, a tierras que ningún enano había pisado jamás, y encontró ruinas, un segundo pantano allí arriba con raptores y hierbas más altas que todo lo que los excavadores habían visto, y debajo, algo mucho más antiguo. No todos han vuelto. Dorin Filosón, el herrero de Villa del Lago, no sabe nada de su hermano Daewyn desde que dejaron de llegar cartas, y Ardin Grassman, de Menethil, subió a buscar las hierbas y no ha vuelto." },
        { "La excavación del equipo ha sacado a la luz fragmentos de una extraña piedra compuesta que dispersa la luz como un prisma vivo, y piezas de una máquina hecha de roca. Rethiel el Guardaverde siente que una energía antigua despierta bajo aquel pantano y quiere que se deje de excavar. Tanto los ancianos de Cima del Trueno como el Anillo de la Tierra y nuestra propia Sala de los Exploradores quieren las reliquias, y supongo que cada cual verá en ellas lo que espera ver." },
        { "Otros también se han dado cuenta. El clan Faucedraco se ha instalado allí con la esperanza de que el lugar le devuelva su antiguo poder y el favor de Desgarro Puño Negro, y los mortacechadores de la Dama Oscura los vigilan. Una máquina de los titanes, un clan de domadores de dragones y los espías de los Renegados, todo en una misma colina empapada." },
      },
    },
    ["explorers-league"] = {
      title = "La Liga de Expedicionarios",
      text = {
        { "Difícilmente podía dejar fuera a la Liga. La Liga de Expedicionarios es la sociedad de historiadores, arqueólogos y excavadores de Forjaz: los enanos que prefieren leer unas ruinas a construir un salón. Una historiadora real no podría pedir mejor compañía." },
        { "Buscan la respuesta a la pregunta más antigua: de dónde venimos los enanos. Sus excavaciones en Uldaman apuntan a los titanes, los hacedores del mundo. De ser así, cada enano tendría que reconsiderar lo que sabe de sí mismo. El rey Magni se lo toma muy en serio." },
        { "Los encontrarás en la Sala de los Exploradores, bajo la dirección del alto expedicionario Magellas. Llévales cualquier cosa antigua y cualquier cosa extraña, $gviajero:viajera;. Querrán saber dónde la encontraste. Yo también." },
      },
    },
    ["fall-of-lordaeron"] = {
      title = "La caída de Lordaeron",
      text = {
        { "Lordaeron era el primero de los reinos humanos y su rey, Terenas Menethil, había guiado a la Alianza durante la Segunda Guerra. Cuando la peste llegó del norte y los muertos empezaron a alzarse, fue su hijo, el príncipe Arthas, paladín de la Mano de Plata, quien salió a combatirla." },
        { "Arthas la persiguió demasiado lejos. Pasó a cuchillo la ciudad apestada de Stratholme antes que ver a sus habitantes resucitar, siguió a los amos de la peste hasta Rasganorte y empuñó allí una hoja rúnica maldita, Agonía de Escarcha. Cuando volvió, el pueblo lo aclamó al cruzar las puertas. Entró en el salón del trono de su padre y lo mató. Tras él, el reino cayó en manos de los muertos." },
        { "Estas ruinas son el lugar donde ocurrió. Los Renegados caminan sobre ellas cada día y algunos estaban entre la multitud que lo aclamó." },
        { side = "Horde", aside = true, sign = "P. F.", "Escribe que algunos Renegados estábamos entre aquella multitud. Algunos estábamos, sí. He intentado más de una vez poner aquel día por escrito. Aún no lo he conseguido." },
      },
    },
    ["falstad-wildhammer"] = {
      title = "Falstad Martillo Salvaje",
      text = {
        { "El gran señor feudal Falstad Martillo Salvaje gobierna Pico Nidal entre sus nidos de grifos. El trabajo de sus jinetes llega mucho más allá de Tierras del Interior: cuando Brohann Barriliga busca a un piloto perdido sobre el Pantano de las Penas, envía aventureros a Falstad en busca de noticias." },
        { "Los Martillo Salvaje se gobiernan solos. Su independencia no borra su historia con la Alianza y Falstad sigue siendo un contacto útil para quienes buscan a sus jinetes de grifos. No confundas una causa compartida con el gobierno de Forjaz, $gviajero:viajera;. Su clan tiene su propio señor feudal y su propio hogar." },
      },
    },
    ["fandral-staghelm"] = {
      title = "Archidruida Fandral Corzocelada",
      text = {
        { "Fandral Corzocelada es el archidruida del Círculo Cenarion en ausencia de Malfurion Tempestira y quien dirigió a los druidas cuando hicieron crecer Teldrassil. Es anciano, orgulloso y grave, y los druidas lo siguen con algo cercano a la reverencia." },
        { "Su pueblo recuerda una pena por encima de todas. Hace mil años, durante la guerra contra el imperio insectoide de Ahn'Qiraj, su hijo Valstann cabalgó para salvar la Aldea del Viento del Sur y no regresó. Días después, el general qiraji Rajaxx salió ante el ejército de los elfos de la noche con el joven elfo entre las garras y lo despedazó ante su padre. Cuando los dragones y los druidas encerraron por fin a los qiraji tras el Muro del Escarabajo, Anacronos entregó a Fandral el cetro que permitiría volver a abrirlo. Fandral lo estrelló contra la puerta. 'Recuperaré a mi hijo', le dijo al dragón, 'aunque tarde milenios'. Se ocupa del Enclave Cenarion de Darnassus, estudia los problemas del árbol que plantó y te dirá que los tiene controlados." },
      },
    },
    ["farstrider-lodge"] = {
      title = "Cabaña del Errante",
      text = {
        { "Los cazadores se reúnen en la Cabaña del Errante, al sureste de Loch Modan. Marek Coracero comercia con carne y pieles de crocolisco, mientras Daryl el Joven propone desafíos a quien quiera demostrar su destreza. Aquí sobra trabajo para un arco y conversación sobre quién lo maneja mejor." },
        { "Vyrin Vientoveloz propone otra prueba. Quiere que maten al Viejo Sooty para dejar en evidencia las fanfarronadas de Daryl. Quizá aprendas algo sobre la caza en la cabaña, pero también aprenderás mucho sobre los cazadores, $gviajero:viajera;." },
      },
    },
    ["feathermoon-stronghold"] = {
      title = "Bastión Plumaluna",
      text = {
        { "El Bastión Plumaluna está en la Isla de Sardor, frente a la costa de Feralas, y se llega en barco desde el continente. La general Shandris Plumaluna manda a sus centinelas desde muros blancos sobre un puerto. La fortaleza lleva su nombre." },
        { "Sus soldados combaten a los nagas Crestafuria de Solarsal y vigilan a los ogros del bosque. También hay estudiosos trabajando entre las antiguas ruinas élficas de Feralas." },
      },
    },
    ["felwood"] = {
      title = "Frondavil",
      text = {
        { "Frondavil fue la parte norte del gran bosque de Vallefresno. Ahora es una tierra envenenada, con árboles negros y retorcidos, ríos verdes, fúrbolgs enloquecidos y hasta las plantas contaminadas. Lo hicieron los demonios. En la última guerra, el señor del terror Tichondrius guardó aquí la Calavera de Gul'dan y su corrupción se extendió por los bosques. Cuando Illidan Tempestira tomó para sí el poder de la Calavera, el bosque no sanó." },
        { "El Consejo de la Sombra y sus demonios dominan Jaedenar, los sátiros Fuego de Jade ocupan las antiguas ruinas y ancestros y elementales corruptos recorren los bosques. Los druidas del Círculo Esmeralda intentan sanarlo planta a planta. La Horda mantiene el Puesto del Veneno en el centro y los elfos de la noche un claro al norte, ante las puertas de los Fauces de Madera." },
      },
    },
    ["feralas"] = {
      title = "Feralas",
      text = {
        { "Feralas es una tierra de lluvia y gigantes en la costa oeste de Kalimdor: un bosque de árboles tan altos que sus copas se pierden en la niebla, con antiguas ruinas entre sus raíces. Los elfos de la noche construyeron aquí mucho antes del Gran Cataclismo. Sus piedras están por todas partes, rotas y cubiertas de vegetación. Los estudiosos de Plumaluna pasan la vida entre ellas y aún no saben decir qué fue la mitad." },
        { "Hoy el bosque pertenece a los ogros Gordunni, cuyo creciente número preocupa a los asentamientos cercanos, a gnolls, yetis, nagas de la costa y Tótem Siniestro de las colinas. Las centinelas conservan una fortaleza insular frente a la costa, la Horda un campamento al este, y en el corazón del bosque está la ciudad Altonato en ruinas que los ogros llaman La Masacre." },
      },
    },
    ["fire-plume-ridge"] = {
      title = "Cresta del Penacho en Llamas",
      text = {
        { "La Cresta del Penacho en Llamas se alza en el centro de Un'Goro, con lava en sus laderas y elementales de fuego entre las coladas. Correfuego ocupa una cueva cerca de la cima. El volcán ofrece a los exploradores del cráter un objeto de estudio difícil de pasar por alto." },
        { "Ringo fue a investigar y lo encontraron perdido y gravemente acalorado en una cueva de la ladera sur. Los estudiosos del Refugio de Marshal aún quieren saber qué hay en el corazón de la cresta. Un viajero puede compartir su curiosidad sin compartir los preparativos de Ringo." },
      },
    },
    ["forest-trolls"] = {
      title = "Los trols del bosque",
      text = {
        { "Mucho antes de que hubiera humanos en Lordaeron, los bosques del norte pertenecían a los trols del imperio Amani. Nunca han perdonado a nadie que se los quitara. Cuando los altos elfos llegaron por mar y se asentaron en Quel'Thalas, los Amani los combatieron durante generaciones, hasta que los elfos y el primer reino humano, Arathor, los quebraron juntos en las Guerras Trols. Su capital, Zul'Aman, aún está en lo profundo de los bosques orientales." },
        { "Los trols volvieron en la Segunda Guerra, cuando su señor de la guerra Zul'jin llevó a las tribus del bosque junto a la Horda contra los elfos y los humanos de Lordaeron. Volvieron a perder. Quedan tribus dispersas por las colinas: los Secacorteza de Arathi y Tierras del Interior, los Vilrama de su ciudad templo de Jintha'Alor y los Fustamusgo de los bosques de Tierras de la Peste del Este, donde muchos se pudren ahora con la peste." },
        { "Son altos, de piel verde y colmillos. Conservan a los viejos dioses trols y algunos costumbres peores. Los Sañadiente de Tierras del Interior son la excepción: han tomado partido por la Horda y sus aliados responderán por ellos." },
      },
    },
    ["foreword-dwarf"] = {
      title = "Unas palabras de la historiadora real",
      text = {
        { "$gViajero:Viajera;, te doy la bienvenida a este registro de Azeroth. He empezado por las tierras de Forjaz, donde un enano puede conocer todos los caminos y seguir teniendo preguntas sobre las piedras de sus orillas." },
        { "Las páginas siguen a nuestros clanes, las guerras que los dividieron y las obras más antiguas que la Liga intenta comprender. También siguen a otros pueblos. Nuestra historia se ha cruzado con la suya tantas veces que un libro limitado a los enanos dejaría mucho sin explicar." },
        { "Llévalo contigo y lee una página cuando un lugar te dé motivos para detenerte. Es más fácil advertir unas ruinas que la vida que albergaron. Ambas merecen un lugar en el registro." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-gnome"] = {
      title = "Unas palabras para quien viene de Gnomeregan",
      text = {
        { "$gViajero:Viajera;, he escrito esta primera página para un gnomo con especial cuidado. Gnomeregan sigue bajo Dun Morogh y tu pueblo aún no puede volver a ella. Un registro de lugares antiguos debe reconocer que algunas pérdidas todavía se están viviendo." },
        { "Forjaz ha ofrecido cobijo a tu pueblo. Habéis traído ingenio y una cantidad considerable de ruido a nuestros salones. Nos alegra vuestra compañía, con reservas ocasionales sobre el ruido. Aquí está el relato de Gnomeregan y de las tierras que sus exiliados comparten ahora." },
        { "Lee estas páginas adonde te lleve tu trabajo. Espero que algún día la entrada de tu hogar necesite una adición más feliz. Hasta entonces, su historia tiene su lugar junto a los inventos y encargos que quizá te ayuden a recuperarlo." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-human"] = {
      title = "Unas palabras para un hijo o una hija de Ventormenta",
      text = {
        { "$gViajero:Viajera;, me alegra enviar este registro a alguien de Ventormenta. Tu pueblo y el mío se han mantenido unidos desde la Segunda Guerra. En nuestros relatos de las batallas posteriores rara vez han faltado nombres de ambos." },
        { "Ventormenta fue destruida y reconstruida. Su nueva cantería es un gran logro y los albañiles impagados que la levantaron también forman parte de su historia. Encontrarás ese relato junto a las historias que tu reino tiene más motivos para celebrar." },
        { "Usa el libro en tus viajes. Poblaciones, ruinas y caminos pueden contarte cómo llegó una tierra a ser lo que encuentras, siempre que alguien conserve la memoria de quienes los hicieron." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-nightelf"] = {
      title = "Unas palabras para alguien de los kaldorei",
      text = {
        { "$gViajero:Viajera;, este registro se encuadernó para alguien de los kaldorei. Confieso que es extraño ofrecer una historia a un pueblo que recuerda diez mil años. Perdona la presunción de una enana. Nosotros contamos nuestras eras en piedra. Vosotros las contáis en la vida de los árboles." },
        { "Durante casi todos esos años, tu pueblo permaneció en sus bosques sin dejar entrar a nadie. Ahora habéis plantado un nuevo Árbol del Mundo frente a Costa Oscura y abierto las puertas a la Alianza. La Liga ha seguido su curiosidad hasta vuestras ruinas, como siempre. Agradeceré que me digas dónde nos hemos equivocado al conjeturar." },
        { "Donde se hizo historia he dejado una página para ti. Léelas junto al fuego y recuerda que toda ruina fue el hogar de alguien." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-orc"] = {
      title = "Unas palabras para alguien de la Horda",
      text = {
        { "$gViajero:Viajera;, el registro que tienes en las manos lo escribió en Forjaz Archesonus, historiadora real del rey Magni. Quizá te preguntes por qué un Renegado de Entrañas envía a un orco la historia de una enana. Fui historiador de Lordaeron antes de que me llevara la peste y reconozco un relato ecuánime al leerlo. El suyo lo es más a menudo de lo que esperaba." },
        { "En él está el camino de tu pueblo. El Portal Oscuro lo trajo aquí. La derrota lo llevó a los campos de internamiento de Lordaeron. Thrall lo sacó y lo guio por mar hasta Durotar, llamada así por su padre. Esos campos estaban en mi reino mientras yo aún vivía. Me descubro leyendo esas páginas más despacio que las demás." },
        { "Lleva el libro en tus viajes. La fuerza te llevará lejos, pero el conocimiento llega más allá. Cuanto más sepas de un lugar, más verás de él. Si tu camino te trae a Entrañas, ven a buscarme. Quizá tenga una pregunta para ti." },
        { italic = true, "Parqual Fintallas, Apothecarium, Entrañas" },
      },
    },
    ["foreword-other"] = {
      title = "Unas palabras de la historiadora real",
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, Apothecarium, Entrañas", "Este registro lo escribió en Forjaz Archesonus, su historiadora real, y te llega desde Entrañas a través de mi mesa. Escribe como una enana de la Alianza y lo reconoce. Cuando se olvide de la Horda, léela teniéndolo en cuenta, como hice yo." },
        { "$gViajero:Viajera;, te doy la bienvenida. Este registro sigue las poblaciones, ruinas y caminos de Azeroth y a las personas cuyas vidas los han dejado como los encuentras. No hace falta una ascendencia concreta para interesarse por el lugar donde pisas." },
        { "Escribo desde el Alto Trono de Forjaz, a unos pasos del trono del rey. La Liga de Expedicionarios trae a casa más de lo que podré terminar de leer. El relato de una enana tendrá intereses de enana, pero el mundo nos ha dado más que investigar que los asuntos de nuestros propios clanes." },
        { "Lee una página cuando tus viajes te lleven a su lugar. Quizá las piedras hayan sobrevivido mejor que los nombres. He intentado mantener ambos al alcance." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-skyborne"] = {
      title = "Unas palabras para un cielonato",
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, Apothecarium, Entrañas", "Este registro lo escribió en Forjaz Archesonus, su historiadora real, y te llega desde Entrañas a través de mi mesa. Sus palabras para tu pueblo eran demasiado buenas para reescribirlas, así que aquí están tal como las escribió." },
        { "$gViajero:Viajera;, este registro se encuadernó para alguien de los cielonatos. Confieso que tuve que empezarlo dos veces. Hasta que tu pueblo descendió del cielo, ningún historiador de Forjaz sabía que existíais. Vuestro propio nombre, shen'dorei, el pueblo oculto, es más acertado que cualquier cosa que hubiéramos escrito." },
        { "Conocíamos vuestros comienzos sin saber que eran vuestros. Tus antepasados vivían en Eldre'Thalas, la ciudad que los ogros llaman ahora La Masacre. Cuando su príncipe quiso someter a un demonio para alimentar la magia de su pueblo, se alzaron tras un dirigente enmascarado, el Shal'nan. Huyeron al oeste por mar, perseguidos por los barcos del príncipe, y los espíritus del viento elevaron su isla hasta Muro Celeste, fuera del mundo. La Liga de Expedicionarios conoce bien esos salones de Feralas. Ninguno imaginó que parte de la ciudad había escapado." },
        { "Ahora los espíritus se han ido, la isla falla y tu pueblo ha venido en busca de ayuda: la Orden Eminente a los magos de Dalaran, los Formavientos a los chamanes. Este registro conoce mejor el mundo al que habéis vuelto que aquel que dejasteis. Donde se hizo historia he dejado una página para ti. Léelas junto al fuego y recuerda que toda ruina fue el hogar de alguien." },
        { italic = true, "Historiadora real Archesonus, Alto Trono, Forjaz" },
      },
    },
    ["foreword-tauren"] = {
      title = "Unas palabras para alguien de los shu'halo",
      text = {
        { "$gViajero:Viajera;, tu pueblo conserva su historia en canciones y en la memoria de la tierra. El mío la guardaba en libros, y una peste puede vaciar una biblioteca tan seguro como una ciudad. Quizá las canciones fueran la elección más sabia." },
        { "Las páginas que siguen las escribió en Forjaz Archesonus, su historiadora real. Te llegan desde Entrañas a través de mi mesa. Cuentan cómo los tauren recorrieron las llanuras de Kalimdor durante generaciones bajo la presión de los centauros y cómo Cairne Pezuña de Sangre, con ayuda orca, reunió a las tribus en Mulgore. Ahora Cima del Trueno se alza sobre los pastizales como hogar de un pueblo al que durante mucho tiempo se negó uno estable." },
        { "Léelas con la atención que das a tus ancianos. Cuando una página y un anciano discrepen, agradeceré saber cuál y por qué. Un historiador colecciona esas discrepancias como otros coleccionan monedas." },
        { italic = true, "Parqual Fintallas, Apothecarium, Entrañas" },
      },
    },
    ["foreword-troll"] = {
      title = "Unas palabras para alguien de los Lanza Negra",
      text = {
        { "$gViajero:Viajera;, este registro se encuadernó para alguien de los Lanza Negra y te debo dos confesiones. Sus páginas las escribió en Forjaz Archesonus, la historiadora real de allí. Yo solo las he reenviado desde Entrañas. Y la historia trol es más antigua que cualquier cosa que guardemos en una estantería cualquiera de los dos. Los tuyos construyeron imperios en las junglas del sur y los bosques del norte mucho antes de que surgieran los reinos humanos." },
        { "Tu tribu era pequeña y estaba acosada cuando los barcos de Thrall os encontraron en vuestras islas. Desde entonces habéis sido fieles a la Horda en las costas de Durotar, bajo el nombre de Sen'jin. Mi pueblo llegó después a la Horda y por un camino más extraño. Tenemos mucho que aprender de quienes la apoyaron primero." },
        { "Donde se hizo historia, la enana ha dejado una página para ti. Cuando sus páginas no alcancen lo que podrían contar tus ancianos, confía en ellos. Después, si tienes tiempo, cuéntame lo que dijeron." },
        { italic = true, "Parqual Fintallas, Apothecarium, Entrañas" },
      },
    },
    ["foreword-undead"] = {
      title = "Unas palabras para alguien de los Renegados",
      text = {
        { "$gViajero:Viajera;, tú y yo hemos sobrevivido a nuestro reino. Fui historiador de Lordaeron antes de que me llevara la peste. Quizá recuerdes sus poblaciones como eran, cuando su capital estaba sobre tierra. Este registro solo las conoce por documentos, porque lo escribió en Forjaz Archesonus, historiadora real del rey Magni. Lo he enviado de todos modos. Es un relato ecuánime y escasean los relatos ecuánimes sobre nuestro hogar." },
        { "Los Renegados se liberaron del Rey Exánime y ahora siguen a Sylvanas bajo las ruinas de la ciudad que conocimos. Mucho de nuestra vida actual queda fuera de la comprensión de una enana. Cuando escribe de la Cruzada Escarlata, es más amable con ellos de lo que lo sería yo." },
        { "Lleva el registro si te resulta útil. Cuando un lugar te recuerde algo que estas páginas no cuentan, confía en tu memoria antes que en sus documentos y en los míos." },
        { italic = true, "Parqual Fintallas, Apothecarium, Entrañas" },
      },
    },
    ["franclorn-forgewright"] = {
      title = "Franclorn Forjador",
      text = {
        { "Franclorn Forjador fue el arquitecto jefe de los enanos Hierro Negro e inventor del método de construcción en piedra que lleva su sello. Te dirá que casi seguro has pisado algo hecho por él. La gran presa de Loch Modan debe su nombre a ese método. Ciudad Forjatiniebla, la capital de los Hierro Negro bajo la montaña, fue obra suya." },
        { "Está muerto. Su fantasma permanece en su tumba de la Montaña Roca Negra, visible solo para quienes también están muertos. Su sucesor como arquitecto, Finoso Virunegro, se ha quedado con su gran martillo, Ferrovil. Franclorn quiere que lo devuelvan a las manos de la estatua que los Hierro Negro le levantaron en el Santuario de Thaurissan. A cambio entrega la llave de las profundidades de lo que llama su ciudad maldita." },
        { "La construyó de todos modos. Un enano puede renegar de una ciudad y seguir orgulloso de su cantería, $gviajero:viajera;. He conocido a varios." },
      },
    },
    ["freewind-post"] = {
      title = "Poblado Viento Libre",
      text = {
        { "El Poblado Viento Libre es una aldea tauren construida sobre las agujas del centro del cañón: cabañas en la roca alta unidas por puentes de cuerda, a las que se llega en ascensor. Los dracoleones van y vienen y los tauren cazan en el fondo del cañón." },
        { "Sufre presión por dos lados. Los centauros Galak atacan cada vez más y los tauren Tótem Siniestro de la cercana Cumbre de la Nube Negra se han vuelto contra los suyos. Los tauren de Viento Libre dicen que llevan un tiempo comportándose de forma extraña. Es algo difícil de decir para un tauren sobre otro tauren." },
      },
    },
    ["frostmane-trolls"] = {
      title = "Los trols Peloescarcha",
      text = {
        { "Los Peloescarcha ocupan las tierras nevadas al oeste de Kharanos y mantienen campamentos hasta en el Valle de Crestanevada. Su poblado alberga cazadores de cabezas, videntes y taumaturgos de las sombras. Entre los ventisqueros, los montaraces deben vigilar algo más que puntas de lanza." },
        { "Grelin Barbablanca advierte de nuevos ataques, y los jóvenes enanos salen a combatirlos casi en cuanto dejan el hogar. La disputa se vuelve familiar muy pronto: un campamento trol más allá de la última hoguera amiga, un informe para los guardias y otra patrulla enviada a la misma nieve." },
      },
    },
    ["frostwolf-clan"] = {
      title = "El clan Lobo Gélido",
      text = {
        { "Los Lobo Gélido de Durotan rechazaron la sangre demoníaca que sometió a buena parte de la Horda. Cuando él se opuso a los brujos y a su invasión de Azeroth, Gul'dan exilió al clan. Sobrevivieron con dificultad en las Montañas de Alterac. Durotan fue asesinado, pero el clan resistió." },
        { "Su hijo Thrall los encontró tras escapar de Durnholde. Le enseñaron la vida de su pueblo y su chamán Drek'Thar le enseñó a seguir a los elementos. Cuando Thrall liberó después los campos de internamiento y llevó a la Horda al otro lado del mar, los Lobo Gélido permanecieron en su valle." },
        { "Drek'Thar, ahora ciego, aún los dirige. Quieren conservar su hogar. La expedición Pico Tormenta ha traído una reclamación de Forjaz sobre él." },
      },
    },
    ["furbolgs"] = {
      title = "Los fúrbolgs",
      text = {
        { "Los fúrbolgs pertenecen a los bosques del norte de Kalimdor, donde sus aldeas y tótems llevan eras junto a las tierras de los elfos de la noche. Combatieron a la Legión Ardiente con ellos hace diez mil años. Su historia guarda amistades antiguas, por muy feroz que sea hoy la recepción de un extraño en un campamento." },
        { "Una tribu tras otra ha sufrido la corrupción: entre ellas los Tuercepinos de Teldrassil, los Bosque Negro de Costa Oscura, los Muertobosque de Frondavil y los Nevada de Cuna del Invierno. La locura ha convertido vecinos en enemigos. En Frondavil, la tierra envenenada da a los elfos de la noche motivos de sobra para culpar a la mancha de la Legión." },
        { client = "classic", "Los Fauces de Madera han resistido ese destino. Protegen los túneles que unen Frondavil, Claro de la Luna y Cuna del Invierno, y otro bastión cerrado en Azshara. Ayudar contra sus parientes corruptos puede ganar lentamente su confianza." },
        { client = "forever", "Los Fauces de Madera siguen custodiando los túneles entre Frondavil, Claro de la Luna y Cuna del Invierno, y pueden ganarse con ayuda contra sus parientes corruptos. El Bastión Faucenegra de Azshara pertenece a otra tribu que sí ha sucumbido a la corrupción." },
      },
    },
    ["gadgetzan"] = {
      title = "Gadgetzan",
      text = {
        { "Gadgetzan es una población goblin del norte del desierto de Tanaris, administrada para el Cártel Bonvapor por Marin Tragonublo. Tiene muros, pozos, casa de subastas, posada, muchísimos ingenieros y una guardia de matones a sueldo que mantienen la paz con gran entusiasmo. La Alianza y la Horda comercian aquí y ambas se comportan, por la cuenta que les trae." },
        { "La población vive del agua. Sus ingenieros excavan los pozos y adivinan dónde abrir los siguientes, y todos los demás pagan por ello. También es donde comprar casi cualquier cosa, desde un elixir goblin que puede convertirte en esqueleto hasta huevos de aves extrañas, y enterarse de casi todo lo que ocurre en el sur." },
      },
    },
    ["gates-of-ironforge"] = {
      title = "Las puertas de Khaz Modan",
      text = {
        { "Los pasos de la Puerta Norte y la Puerta Sur comunican Dun Morogh con Loch Modan. Los montaraces mantienen avanzadas en ambas rutas. En las montañas, un camino estrecho puede exigir tanta vigilancia como una extensa frontera." },
        { "El capitán Rugelfuss explica el problema desde el lado de Loch Modan. Su regimiento debe defender la puerta en vez de perseguir a los troggs cercanos, mientras la Reserva de Forjaz está destinada al frente de la Alianza. Pide a los aventureros que defiendan las tierras que sus soldados no pueden cubrir sin abandonar sus puestos." },
      },
    },
    ["gathilzogg"] = {
      title = "Gath'Ilzogg",
      text = {
        { "Petravista se construyó para defender Crestagrana. Los guerreros Roca Negra de Gath'Ilzogg la han convertido en la fortaleza desde la que atacan Villa del Lago, llevando la guerra de la montaña a las granjas y caminos que rodean el Lago Sempiterno." },
        { "El magistrado Salomón ha ofrecido una recompensa por su cabeza. Además de matar al comandante, hay que recuperar el fuerte. La muerte de Gath'Ilzogg es solo el primer paso. Para Villa del Lago, una fortaleza en el horizonte se ha convertido en la medida de cuánta tierra propia ya no puede alcanzar." },
      },
    },
    ["ghost-howl"] = {
      title = "Aullido Fantasma",
      text = {
        { "Aullido Fantasma es un gran lobo de Mulgore cuya piel lleva una terrible herida de su lucha contra la Legión Ardiente. La cicatriz da a este trofeo de caza una historia que va más allá de la persecución por las llanuras." },
        { "Skorn Nubeblanca reconoce la piel en el Poblado Pezuña de Sangre. Ofrece al cazador una de sus armas y espera que el espíritu del lobo haya encontrado la paz." },
      },
    },
    ["gnolls"] = {
      title = "Los gnolls",
      text = {
        { "Los Zarparrío atacan Elwynn y Páramos de Poniente. Los Pellejomusgo ocupan Los Humedales. Estas manadas tienen historias distintas. El anuncio de busca y captura de Hogger advierte que es demasiado peligroso para un cazador solo, mientras el relato de Rethiel dice que los Pellejomusgo vivieron en paz con sus vecinos." },
        { "Algunas manadas sirven a otros poderes. Los Pielsombra de Crestagrana responden ante Morganth y Thule Corvozarpa manda a los Putrepellejo no-muertos de Tirisfal y Argénteos. Al otro lado del mar, los Crines Pálidas cazan en Mulgore y los Zarpaleña viven en Feralas. Pregunta a qué manada te enfrentas, $gviajero:viajera;. Su nombre te dirá más sobre el problema que tienes delante que una opinión general sobre los gnolls." },
      },
    },
    ["gnomeregan"] = {
      title = "Gnomeregan",
      text = {
        { "Gnomeregan yace bajo el oeste de Dun Morogh, la antigua capital gnoma arruinada durante la crisis de la Tercera Guerra. Los troggs invadieron sus salones. Para detenerlos, los gnomos liberaron radiación por toda su ciudad." },
        { "Los troggs sobrevivieron. Muchos gnomos murieron y otros se transformaron en los violentos supervivientes que hoy llamamos gnomos parias. Quienes escaparon encontraron refugio en Forjaz. Los salones envenenados aún muestran el precio de aquel intento." },
        { "Sicco Termochufe sigue allí. El alto mecachifle Mekkatorque lo acusa de traición y pide a los aventureros que lo maten. Si entras, recuerda que aquello fue una capital llena de hogares y talleres, $gviajero:viajera;. Su pueblo aún intenta recuperar lo que queda." },
      },
    },
    ["gnomeregan-exiles"] = {
      title = "Los exiliados de Gnomeregan",
      text = {
        { "Un pueblo sin hogar y los exiliados más alegres que conocerás. Los gnomos que escaparon de Gnomeregan viven ahora en Ciudad Manitas, en el corazón de Forjaz, y en puestos como el Almacén de Brasacerada, desde donde se ven sus antiguas puertas." },
        { "No te dejes engañar por su alegría. Cada invento que prueban y cada recluta que instruyen tienen una misma meta: el día en que vuelvan a entrar en Gnomeregan para recuperarla." },
        { "Forjaz les ha ofrecido cobijo mientras lo necesiten. La mayoría de los enanos agradecen su compañía, aunque no tanto el ruido." },
      },
    },
    ["gnomeregan-tune"] = {
      title = "Gnomeregan",
      text = {
        { "Gnomeregan, la ciudad de los gnomos en Dun Morogh, tiene una melodía que suena en algún rincón de su interior, y esa misma melodía aparece en Vista Eterna, el pueblo de los goblins en Cuna del Invierno. Los gnomos intentaron echar a los troggs de su ciudad y convirtieron a la mayoría de los suyos en gnomos leprosos. Lo dicen ellos mismos, cosa que no hace la mayoría." },
      },
    },
    ["goblins"] = {
      title = "Los goblins",
      text = {
        { "Los goblins aparecen allí donde hay dinero que ganar, es decir, casi en todas partes: regentan los puertos neutrales, excavan y talan para Ventura y Cía. y venden explosivos a cualquiera que pueda pagarlos. Su patria es la isla de Kezan, en los mares del sur, y su capital es Villabajo, donde los príncipes mercaderes que los gobiernan hacen sus negocios." },
        { "La isla no siempre fue suya. Pregunta a los trols Zandalar y oirás que Kezan fue un día un gran territorio del Imperio Zandalar, hasta que, como ellos dicen, la corrupción de los príncipes mercaderes goblins los obligó a marcharse. El relato más largo cuenta que los trols pusieron a los goblins a extraer un mineral extraño, la kaja'mita, del volcán de la isla, y que ese mineral les afiló el ingenio hasta que se quedaron con Kezan. No puedo dar fe del mineral. El resto me lo creo." },
        { "En la Segunda Guerra, los goblins vendieron a la Horda zapadores y zepelines, y cobraron por ambos. Para la Tercera Guerra habían dejado de elegir bando, y sus mercaderes, laboratorios y astilleros servían a cualquiera. Ese arreglo les sigue conviniendo. El Cártel Bonvapor mantiene sus puertos abiertos a la Alianza y a la Horda por igual, Ventura y Cía. despoja cualquier tierra que nadie le impida despojar, y un ingeniero goblin prefiere la clase de artefacto que termina en una gran explosión. Los ingenieros de Gnomeregan lo llaman una diferencia de filosofía. Sospecho que es una diferencia de paciencia." },
      },
    },
    ["goldshire"] = {
      title = "Villadorada",
      text = {
        { "Villadorada se alza en una encrucijada de Elwynn, con la Posada Orgullo de León dispuesta a recibir viajeros y el alguacil Dughan dispuesto a darles trabajo. La aldea es anterior a las guerras. Ardió cuando los orcos atravesaron Elwynn durante la Primera Guerra." },
        { "Tras la Segunda Guerra, los habitantes de Ventormenta regresaron del exilio en Lordaeron y la reconstruyeron. La herrería y el mercado vuelven a estar concurridos, y los jóvenes aventureros se detienen aquí antes de salir a hacerse un nombre. Echa un vistazo al tablón de recompensas de Dughan cuando pases, $gviajero:viajera;. La aldea se ha recuperado. Al alguacil aún le sobran preocupaciones." },
      },
    },
    ["great-masquerade"] = {
      title = "La gran mascarada",
      text = {
        { "El alguacil Reginald Windsor reunió pruebas contra la consejera del alto señor Bolvar Fordragon, pero las perdió en las mazmorras de la Montaña Roca Negra. Tras su rescate, regresó con nuevas pruebas y compañeros dispuestos a apoyarlo. Entró con unos y otras en el Castillo de Ventormenta." },
        { "Allí reveló que lady Katrana Prestor era Onyxia, hija de Alamuerte y hermana de Nefarian. Había mantenido al ejército de Ventormenta en casa mientras los orcos de su hermano amenazaban Crestagrana, y había sometido a Bolvar a su voluntad. Windsor deshizo su disfraz ante la corte. Ella huyó a su guarida en Marjal Revolcafango." },
        { "Windsor murió en el enfrentamiento. Anota su nombre si dejas constancia de la derrota de la dragona, $gviajero:viajera;. Su contribución empezó mucho antes de que nadie llegara a su guarida." },
      },
    },
    ["green-dragonflight"] = {
      title = "El Vuelo Verde",
      text = {
        { "El Vuelo de Ysera conserva el Sueño Esmeralda y los cuatro grandes árboles donde toca el mundo despierto: Seradane en Tierras del Interior, Talloumbrío en Vallefresno, Rama Oniria en Feralas y la Arboleda del Crepúsculo en el Bosque del Ocaso. Los druidas recorren el Sueño por el pacto que sus antepasados hicieron con Ysera. Los dragones rara vez recorren el mundo." },
        { "No todos están bien. Algo ha entrado en el Sueño y retorcido a algunos de los propios hijos de Ysera. Los cuatro que ahora rondan los grandes árboles tienen su propia página. Antes estuvo Eranikus, dormido sobre el templo hundido del Pantano de las Penas y atrapado en la misma pesadilla." },
        { "Itharius, otro miembro del Vuelo, espera en una cueva de ese pantano a mortales que ayuden a redimir a Eranikus. Mientras los guardianes corruptos siguen rondando los árboles, uno de sus parientes pide a extraños que traigan a un dragón a casa." },
      },
    },
    ["green-kingdoms"] = {
      title = "Los reinos verdes",
      text = {
        { "Una sola melodía sirve a los bosques de los reinos humanos, del Bosque de Elwynn y las Montañas Crestagrana a Loch Modan, las Tierras del Interior y las Laderas de Trabalomas. Los humanos cultivaron y lucharon bajo estos árboles mucho antes de que la Horda cruzara el Portal Oscuro, y la melodía ha sobrevivido a todo ello. Si quieres oírla como es debido, deja de caminar." },
      },
    },
    ["grey-hours"] = {
      title = "Horas grises",
      text = {
        { "Dos piezas breves aparecen en lugares que poco más tienen en común. La primera pertenece a Punta de Nijel, un pequeño campamento escondido en las montañas del norte de Desolace, y a El Sagrario, en las Tierras Altas de Arathi. Vuelve a aparecer en algún rincón de Pico Nidal, la Aldea Estrella Fugaz, La Masacre y las torres del Marjal Revolcafango, y recibe a quien llega al Castillo de Durnholde. La segunda espera en algún rincón de la Torre de Petravista, en las Montañas Crestagrana, y recibe a quien llega al Castillo de Nethergarde." },
      },
    },
    ["greymane-wall"] = {
      title = "La Muralla de Cringrís",
      text = {
        { "La Muralla de Cringrís cierra el sur de Argénteos desde el mar hasta el risco, con Gilneas al otro lado de su puerta. Tras la Segunda Guerra, el rey Genn Cringrís discutió con los demás gobernantes de la Alianza, entre otras cosas por el coste de mantener a los orcos derrotados en campos de internamiento. Retiró a su reino de la Alianza y lo encerró tras esta muralla." },
        { "Los refugiados del norte encuentran la puerta cerrada. De Gilneas no ha llegado noticia que explique su situación actual. La muralla se ve con toda claridad, $gviajero:viajera;. Es el país de detrás el que queda fuera de este registro." },
      },
    },
    ["grim-batol"] = {
      title = "Grim Batol",
      text = {
        { "Cuando los Martillo Salvaje fueron expulsados de Forjaz, excavaron Grim Batol en las montañas orientales. Era una fortaleza capaz de rivalizar con la propia Forjaz. Después llegaron los Hierro Negro, dirigidos por la reina Modgud. Aunque los Martillo Salvaje ganaron la batalla y la mataron, su muerte dejó una oscuridad en la piedra. No quisieron quedarse. Marcharon al norte, a Tierras del Interior, y Grim Batol quedó vacía." },
        { "No siguió vacía. Durante la Segunda Guerra, los orcos del clan Faucedraco la convirtieron en su bastión. Allí mantuvieron prisionera a Alexstrasza, reina de los dragones rojos, y obligaron a sus hijos a llevar orcos a la batalla. Al final fue liberada y los Faucedraco se dispersaron." },
        { "Los dragones rojos siguen allí. Sea lo que sea lo que protegen en Grim Batol, lo defienden ferozmente. No te acerques, $gviajero:viajera;. Los dragonantes rojos de sus accesos son advertencia suficiente." },
      },
    },
    ["grimtotem"] = {
      title = "Los Tótem Siniestro",
      text = {
        { "La mayoría de los tauren vive según la paz de la Madre Tierra. Los Tótem Siniestro no. Su tribu cree que los demás pueblos no tienen derecho alguno a Kalimdor, incluidos los tauren que no están de acuerdo, y lucha por recuperarlo sin reglas ni piedad." },
        { "Su matriarca, Magatha, la bruja anciana, vive en la propia Cima del Trueno y se sienta entre los ancianos, lo que dice algo de la paciencia de Cairne Pezuña de Sangre. Sus guerreros son menos corteses. Atacan en la Sierra Espolón, ocupan la Cumbre de la Nube Negra en Las Mil Agujas, hostigan al Poblado Viento Libre y tienen un complejo en Feralas. Pregunta a un tauren de Viento Libre qué opina de ellos y después da un paso atrás." },
      },
    },
    ["grom-hellscream"] = {
      title = "Grom Grito Infernal",
      text = {
        { "Grommash Grito Infernal, jefe de los Grito de Guerra, fue el primero de los jefes orcos que bebió la sangre de Mannoroth en Draenor y condujo a los demás a hacerlo. La fuerza que les dio sometió a los clanes al demonio cuya sangre compartían." },
        { "Cuando cayó la Horda y los clanes fueron recluidos en los campos, sus Grito de Guerra siguieron luchando desde sus escondites, y Grom siguió siendo un jefe invicto. El joven Thrall aprendió de él lo que había sido la Horda y encontró un aliado para reunir a los clanes dispersos. Los dos zarparon hacia Kalimdor como amigos, con la esperanza de un hogar más allá de los campos y las viejas guerras." },
        { "Grom no vivió para ver construido el nuevo hogar de la Horda. Thrall colocó una piedra donde cayó, en el Barranco del Demonio. 'En muchos sentidos', dice, 'la maldición de nuestro pueblo comenzó y terminó con Grom'. Su nombre significaba corazón de gigante, escribe el Jefe de Guerra, y se lo ganó cien veces." },
      },
    },
    ["gromgol-base-camp"] = {
      title = "Campamento Grom'gol",
      text = {
        { "Grom'gol es una empalizada de la Horda en la costa norte de Tuercespina, con zepelines desde Orgrimmar y Entrañas. Para los Lanza Negra, venir aquí es regresar a la tierra de sus antepasados. Sus asuntos en la jungla incluyen pérdidas que los acompañaron al partir." },
        { "Nimboya busca a Yenniku, hijo menor de su jefe, entregado de niño a los trols de Zul'Gurub según la antigua costumbre. Los Lanza Negra lo perdieron cuando se marcharon con Thrall. Nimboya sospecha primero de los Cabellesangre, pero la búsqueda revela el control mágico de Zanzil el Desarraigado sobre él y lleva a intentar liberar su alma." },
      },
    },
    ["gurubashi-arena"] = {
      title = "La Arena Gurubashi",
      text = {
        { "En mitad de la jungla se alza una gran arena de piedra, construida hace mucho por los Gurubashi para sus deportes sangrientos. Los trols se han ido, pero la lucha no: los goblins y piratas que ahora la administran celebran combates regulares. De vez en cuando dejan un cofre de tesoros en el centro y permiten que se lo lleve quien siga en pie." },
        { "Está abierta a todos, Alianza y Horda por igual, lo que significa que es el único lugar de Tuercespina donde se los anima a matarse entre sí." },
      },
    },
    ["gurubashi-empire"] = {
      title = "El imperio Gurubashi",
      text = {
        { "Los trols de la selva Gurubashi gobernaron un imperio que se extendía por el sur de los Reinos del Este y las islas del mar. Tuercespina era su corazón y la gran ciudad templo de Zul'Gurub, su centro. Sus ruinas están por toda la jungla: templos escalonados, ídolos rotos y caminos pavimentados bajo las raíces." },
        { "Su caída fue obra de sus propios sacerdotes. Los Atal'ai trajeron al mundo al dios de la sangre Hakkar el Cazador de Almas. Su hambre de sacrificios volvió al imperio contra sí mismo. Las tribus se alzaron, expulsaron a los Atal'ai y se separaron. Lo que quedó se convirtió en las tribus que conocemos: Machacacráneos y Cabellesangre en la jungla, Lanza Negra que partieron con Thrall, y otras. Los trols no han olvidado lo que fueron." },
      },
    },
    ["gustberry-lowlands-tune"] = {
      title = "Tierras Bajas de los Soplabayas",
      text = {
        { "Las Tierras Bajas de los Soplabayas, con el Huerto de los Campovento, los Establos de Buentiempo y la Torre de vigilancia del pilón del este, tienen su propia melodía. Son las granjas de la isla. La torre vigila uno de los pilones de anclaje, y en Zephras nadie se toma ese trabajo a la ligera." },
      },
    },
    ["hakkar"] = {
      title = "Hakkar el Cazador de Almas",
      text = {
        { "Hakkar el Cazador de Almas es el dios de la sangre de los trols, una serpiente alada que se alimenta de sangre y almas. Hace mucho, los Atal'ai lo trajeron al mundo. Su exigencia de sacrificios se volvió tan terrible que las tribus se alzaron contra sus sacerdotes y los expulsaron." },
        { "Ha regresado a través de Zul'Gurub. Los Zandalar advierten que su dominio se extenderá por el mundo si no lo detienen. Hasta su corazón caído conserva poder: quienes lo han combatido dicen que aún arde. Recuerda la advertencia de los Zandalar si entras en esa ciudad, $gviajero:viajera;. Saben lo que costó a su pueblo adorarlo." },
      },
    },
    ["hall-of-thanes"] = {
      title = "El Salón de los Feudales",
      text = {
        { "Bajo Forjaz se abren las cavernas de la Antigua Forjaz, y en ellas un lugar que los enanos llaman El Salón de los Feudales. Los Hierro Negro han logrado llegar hasta él. Un mapa arrebatado a sus espías en el Complejo Vetaferro muestra túneles y antiguas calzadas que convergen bajo la ciudad. Videnterra Farsen, un visitante de Pico Nidal, los siguió hasta el salón y hasta el Hierro Negro que manda allí, un tal Durgen Martillo Funesto." },
        { "Los muertos del propio salón tampoco descansan. Afadra Murocre, sabia de Forjaz, pide a los viajeros que den reposo a los espíritus de Yunquemar. Uno de ellos, Faldrim Yunquemar, parece haber conservado un viejo rencor mucho más allá de la tumba. El rey Magni quiere la cabeza del comandante. A mí me gustaría que la Liga pudiera examinar el lugar en condiciones cuando los Hierro Negro se hayan marchado." },
      },
    },
    ["hammerfall"] = {
      title = "Sentencia",
      text = {
        { "Sentencia fue un gran campo de internamiento orco tras la Segunda Guerra. Thrall y Orgrim Martillo Maldito lo abrieron juntos por la fuerza. Durante los combates, un caballero atravesó a Martillo Maldito por la espalda con una lanza y el antiguo Jefe de Guerra murió aquí." },
        { "La Horda ha reconstruido el campamento como fortaleza y le ha dado su nombre en recuerdo de él. Algunos de los orcos de su empalizada fueron prisioneros en este mismo suelo." },
      },
    },
    ["hammertoes-digsite"] = {
      title = "Excavación de Piemartillo",
      text = {
        { "La Excavación de Piemartillo es el campamento de la Liga de Expedicionarios a las puertas de Uldaman, llamado así por el prospector que lo dirigió. Ha pasado malos tiempos. Los troggs salieron de la bóveda e invadieron el yacimiento. El prospector Agmond, encargado de las excavaciones del sur, dejó de dar noticias. Cuando fueron a buscarlo, encontraron su campamento y lo que quedaba de él. Los Hierro Negro del clan Forjatiniebla capturaron al propio Piemartillo: quieren saber lo que él sabe de las obras de los titanes." },
        { "El prospector Ryedol conserva lo que queda de la excavación y no se rinde fácilmente. Espero que Piemartillo tampoco. Los Forjatiniebla buscan en Uldaman los secretos de los gólems de los titanes. Piemartillo los buscaba antes, para mantenerlos fuera del alcance de los Hierro Negro." },
      },
    },
    ["hamuul-runetotem"] = {
      title = "Archidruida Hamuul Runatótem",
      text = {
        { "El archidruida Hamuul Runatótem se encuentra en el Alto de los Ancestros de Cima del Trueno, entre los maestros y dirigentes espirituales de los tauren. Su presencia da a los druidas una voz en la ciudad además de un hogar." },
        { "Las noticias de las Cuevas de los Lamentos le traen aventureros de más allá de Mulgore. Los envía a Nara Bravacrín para continuar la investigación." },
      },
    },
    ["harpies"] = {
      title = "Las arpías",
      text = {
        { "Las arpías anidan por todo Kalimdor, cazan y lanzan hechizos, y sus alas y garras las llevan sobre el terreno. Las Viento Seco ocupan Durotar, las Viento Furioso Mulgore, las Alabruja Los Baldíos y las Furia Sangrienta la Sierra Espolón. Sus bandadas se han ganado enemigos entre los asentamientos de abajo." },
        { "Ruul Garraguilar envía cazadores contra las Viento Furioso como prueba. Los druidas de la Sierra Espolón quieren recuperar La Vega Carbonizada de las Furia Sangrienta para restaurarla. Quien pase bajo sus nidos tiene motivos prácticos para aprender qué bandada los ocupa." },
      },
    },
    ["hearthglen"] = {
      title = "Vega del Amparo",
      text = {
        { "Vega del Amparo rodea el Fuerte de Mardenholde, al norte de Tierras de la Peste del Oeste. La Cruzada Escarlata ocupa sus muros y el gran inquisidor Isillien mantiene una población verde y viva en mitad de la tierra apestada mediante métodos despiadados." },
        { "El fuerte fue la sede de Tirión Vadín. Cuando lo desterraron por defender a un orco que le había salvado la vida, su esposa dijo a su hijo Taelan que estaba muerto. Ahora Taelan conserva el hogar de su padre para la Cruzada. Tirión vive en una cabaña junto al Thondroril, reuniendo lo que puede del pasado del muchacho y buscando la forma de llegar a él." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron desterró a un paladín por perdonar a un orco. Ahora los orcos comparten su Horda con los muertos de Lordaeron y aún no he decidido qué pensar de ello." },
      },
    },
    ["helcular"] = {
      title = "Helcular",
      text = {
        { "Helcular era un mago de las colinas sobre Costasur. Estaba a punto de convertirse en un exánime cuando los habitantes de Costasur encontraron su guarida ritual y lo mataron. Lo enterraron en su propio cementerio, cabe suponer que para vigilarlo. Su aprendiz se lo tomó mal." },
        { "Los yetis ocupan ahora la guarida y tienen la vara con la que Helcular realizaba sus ritos. Había construido tres piras ceremoniales en las cuevas de estas montañas, las Llamas de Azel, Veraz y Uzel. Su aprendiz quiere recuperar la vara, cargarla en cada una y clavarla en la tumba de su maestro, en mitad del pueblo humano." },
        { "Qué surgirá entonces del cementerio de Costasur, el aprendiz no lo dice. Costasur tiene muchos enemigos, $gviajero:viajera;. Este enemigo se lo creó el propio pueblo." },
      },
    },
    ["high-elves"] = {
      title = "Los altos elfos",
      text = {
        { "Los altos elfos comenzaron como elfos de la noche: Altonato de la corte de Azshara que sobrevivieron al Gran Cataclismo y no pudieron renunciar a su magia. Cuando los druidas la prohibieron bajo pena de muerte, su dirigente Dath'Remar respondió con una tormenta de hechizos sobre Vallefresno. Los druidas no quisieron matar a tantos de los suyos. Los desterraron. El pueblo de Dath'Remar navegó al este, cruzando La Vorágine, feliz de librarse de sus prudentes primos." },
        { "Desembarcaron al norte de lo que los humanos llamarían Lordaeron. Se asentaron primero en los claros de Tirisfal hasta que, unos años después, muchos empezaron a enloquecer. Se rumoreó que algo maligno dormía bajo ese suelo, pero nunca se demostró. Separados del Pozo, perdieron la inmortalidad durante el viaje, se hicieron más bajos y pálidos y combatieron a los trols Amani por cada tramo. Por fin fundaron Quel'Thalas en lo profundo de los bosques del norte, en tierra sagrada para los trols, y lo rodearon de piedras rúnicas. Dath'Remar tomó el nombre Caminante del Sol, 'el que camina de día', y su pueblo ha sido hijo del sol desde entonces." },
        { "Quel'Thalas ha caído. Los elfos que encuentra un viajero son lo que queda: forestales que conservan el Refugio Quel'Lithien al borde de las Tierras de la Peste, elfos Vallealto de la Avanzada Quel'Danil en Tierras del Interior y errantes aquí y allá. Son orgullosos incluso en el exilio. Con lo que han perdido, me cuesta reprochárselo." },
      },
    },
    ["high-tinker-mekkatorque"] = {
      title = "Alto mecachifle Mekkatorque",
      text = {
        { "Gelbin Mekkatorque dirige a los gnomos desde Ciudad Manitas, en Forjaz. Los enanos han dado refugio a su pueblo, pero su propia capital sigue bajo Dun Morogh. Un hogar prestado por amigos no puede compensar la pérdida de Gnomeregan." },
        { "La radiación liberada contra los troggs invasores no logró exterminarlos y también devastó a los gnomos. Mekkatorque confió en su día en Sicco Termochufe. Ahora lo acusa de traicionar a la ciudad y pide a los aventureros que entren en ella y lo maten." },
      },
    },
    ["highborne"] = {
      title = "Los Altonato",
      text = {
        { "Los Altonato eran la casta superior de los elfos de la noche, sirvientes escogidos de la reina Azshara, que estudiaron el Pozo de la Eternidad hasta aprender magia y después la amaron por encima de todo. Sus hechizos atrajeron a Sargeras al mundo y su reina y su corte abrieron el camino a su Legión." },
        { "No todos compartieron su destino. Algunos sobrevivieron al Gran Cataclismo entre los demás elfos de la noche y, exiliados por aferrarse a su magia, se convirtieron en altos elfos. Otros resistieron en Eldre'Thalas, donde los Shen'dralar aún guardan sus propios asuntos. Muchos simplemente murieron y no descansaron." },
        { "Sus muertos son fáciles de encontrar: lamentándose en las ruinas de Costa Oscura, vagando por Azshara como apariciones y pequeños exánimes, sufriendo junto al lago helado de Kel'Theril en Cuna del Invierno. Diez mil años es mucho tiempo para arrepentirse, $gviajero:viajera;. Al menos uno de ellos, junto al lago, parece sentirlo de verdad." },
      },
    },
    ["highborne-ruins"] = {
      title = "Las ruinas de los Altonato",
      text = {
        { "Hace diez mil años, los Altonato, nobles hechiceros de la reina Azshara, vivían en torres de esta costa, entre ellas Ameth'Aran y Bashal'Aran, y practicaban libremente su magia. La guerra del Pozo de la Eternidad los destruyó. Las tablillas de Ameth'Aran aún cuentan su caída a quien sepa leer las antiguas runas y no huya de los espíritus." },
        { "Los muertos no se han marchado. Los fantasmas de los Altonato rondan ambas ruinas. En Ameth'Aran está el espíritu de una mujer llamada Anaia Correalba, cuyo amado Cerellean Zarpablanca le ha sobrevivido diez mil años y aún sueña con ella en Auberdine. En Bashal'Aran, otro espíritu, Asterion, está preso tras un sello colocado por uno de los más poderosos de los suyos. Los sátiros y duendes que se alimentan de la magia de las ruinas no se acercan a su santuario." },
      },
    },
    ["hillsbrad-foothills"] = {
      title = "Laderas de Trabalomas",
      text = {
        { "Las Laderas de Trabalomas son una comarca verde y ondulada entre las montañas de Alterac y el mar: huertos, granjas y pastos, la antigua villa de Trabalomas y el puerto de Costasur. Fue un rincón próspero de Lordaeron y, de algún modo, aún está vivo, que en el norte no es poca cosa." },
        { "También es un campo de batalla. Los Renegados ocupan Molino Tarren, en las colinas, y asaltan las granjas de los Campos de Trabalomas, matan a sus granjeros y queman las cosechas. Los hombres de Costasur contraatacan. El Sindicato ocupa la antigua fortaleza de Durnholde, los magos de Dalaran conservan el campo de internamiento junto al Lago Lordamere y, al este, los enanos de Dun Garok vigilan los pasos. Trabalomas tiene más ejércitos que cosechas." },
      },
    },
    ["hogger"] = {
      title = "Hogger",
      text = {
        { "El anuncio de busca y captura del Cuartel de Arroyoeste describe a Hogger como un gnoll enorme, acampado al sur, en el suroeste de Elwynn. Pertenece a los Zarparrío y los guardias de Ventormenta no han logrado capturarlo. Se ofrece una recompensa por su garra." },
        { "El anuncio recomienda ir en grupo. Hazle caso, $gviajero:viajera;. Que un guardia admita que necesita ayuda es más útil que la seguridad de un aventurero que cree no necesitarla." },
      },
    },
    ["house-of-barov"] = {
      title = "La Casa Barov",
      text = {
        { "Los Barov eran una casa noble de Lordaeron, rica y orgullosa, señores de Castel Darrow. Cuando llegó la peste pactaron con Kel'Thuzad: su castillo para el Culto de los Malditos a cambio de proteger su fortuna. Kel'Thuzad cumplió a su manera. El señor y su familia siguen en Scholomance como sirvientes de la Plaga." },
        { "Quedan dos hijos. Weldon Barov está vivo y permanece bajo protección de la Alianza en el Campamento del Orvallo. Alexi Barov no lo está y se reúne con los Renegados en El Baluarte. Ambos quieren la fortuna familiar. Ambos desean la cabeza de su hermano en una bandeja y pagan a quien la traiga. La no-muerte no ha terminado con esta disputa familiar." },
      },
    },
    ["humans"] = {
      title = "Los humanos",
      text = {
        { "El primer reino humano fue Arathor, levantado en Strom, en las tierras altas que aún llevan su nombre. Su rey Thoradin reunió a las tribus dispersas contra los trols Amani. Durante esa guerra, los altos elfos de Quel'Thalas enseñaron magia a cien humanos. De Arathor surgieron con el tiempo siete reinos: Ventormenta, Lordaeron, Gilneas, Alterac, Stromgarde, Kul Tiras y la ciudad de los magos, Dalaran." },
        { "Los orcos llegaron por el Portal Oscuro y quemaron primero Ventormenta. Sus habitantes huyeron al norte y en Lordaeron se construyó la Alianza que ganó la Segunda Guerra. Después, la peste y la Plaga tomaron la propia Lordaeron, Gilneas se encerró tras su muralla y Dalaran cayó. Ventormenta, reconstruida en piedra blanca, es la mayor ciudad humana que queda. Un niño rey ocupa su trono bajo un regente mientras su padre está desaparecido." },
        { "Son un pueblo de vida corta y obstinado, $gviajero:viajera;. Discuten entre sí más de lo que les conviene y reconstruyen más deprisa que nadie que yo conozca. La Liga ha aprendido a tomarse en serio sus mapas y con cierta cautela sus promesas de pago." },
      },
    },
    ["hunters"] = {
      title = "Cazadores",
      text = {
        { "Todo pueblo cercano a la naturaleza tiene sus cazadores. Los enanos tienen montaraces de puntería segura en cualquier pendiente y los elfos de la noche sus cazadoras y centinelas. Orcos y trols tienen rastreadores y domadores de bestias, y los tauren sus valientes, que aún siguen a las manadas como hicieron sus abuelos." },
        { "Lo que distingue a un cazador es un compañero. Un lobo, un felino, un oso, un raptor, un búho: domesticado en la naturaleza, aprende a luchar a su lado. Alimentarlo y cuidarlo forma tanta parte de la vocación como aprender a disparar. Hay que convencer a la bestia de que el nuevo acuerdo le conviene." },
        { client = "forever", "Ahora los humanos también se instruyen como cazadores y los cielonatos aportan cazadores tanto a la Alianza como a la Horda." },
        { "La Liga emplea cazadores como guías desde que existe, $gviajero:viajera;. Encuentran el camino y la cena, e impiden que ambos encuentren primero a los excavadores." },
      },
    },
    ["hydraxian-waterlords"] = {
      title = "Los Señores del Agua de Hydraxis",
      text = {
        { "En una isla de la bahía de Azshara vive el duque Hydraxis, señor de los elementales de agua. Los Señores del Agua de Hydraxis que dirige están en guerra con los demás elementos, sobre todo con el fuego. Su gran enemigo es Ragnaros, el Señor del Fuego, en su Núcleo de Magma." },
        { "No son amigos de los mortales, pero aceptan como aliados a quienes combaten a sus enemigos: los elementales de tierra y aire de los pozos de las Tierras de la Peste y de Silithus, y los señores del fuego bajo la Montaña Roca Negra. A quienes merecen su confianza les dan el agua que apaga las runas del Núcleo de Magma y una forma de invocar al mayordomo del Señor del Fuego." },
      },
    },
    ["illidan-stormrage"] = {
      title = "Illidan Tempestira",
      text = {
        { "Illidan era el hermano gemelo de Malfurion y también amaba a Tyrande. Ella eligió a Malfurion. En la Guerra de los Ancestros luchó con su hermano contra la Legión, pero nunca renunció a la magia de los Altonato. Cuando el Pozo de la Eternidad fue destruido, llevó viales de sus aguas a lo alto del Monte Hyjal y los vertió en un lago, creando otro Pozo. Lo consideró un regalo. Malfurion lo llamó crimen y, con ayuda de Cenarius, lo encerró en una prisión bajo tierra, encadenado y vigilado, durante diez mil años." },
        { "Tyrande lo liberó cuando volvió la Legión, esperando su ayuda. En estos bosques hizo otra cosa. El señor del terror Tichondrius guardaba aquí la Calavera de Gul'dan, una reliquia de brujo llena de poder vil. Illidan la tomó y absorbió su fuerza. Salió transformado en demonio, con algunos recuerdos de Gul'dan, y mató a Tichondrius. Malfurion lo desterró por ello." },
        { "El libro de nuestra biblioteca cuenta que después huyó más allá del mundo, a los restos destrozados de la patria de los orcos, con nagas y elfos de sangre a sus espaldas. Frondavil tampoco se ha recuperado de aquella noche." },
      },
    },
    ["internment-camps"] = {
      title = "Los campos de internamiento",
      text = {
        { "Tras la Segunda Guerra, la Alianza tenía un problema desconocido hasta entonces: un pueblo entero de prisioneros. Reunieron a los orcos en campos y, cuando se llenaron, construyeron otros en las llanuras al sur de estas montañas. El rey Terenas impuso tributos a los demás reinos para pagarlos. El impuesto casi rompió la Alianza." },
        { "Después, los guardianes notaron algo extraño. Los orcos dejaron de intentar escapar. Dejaron incluso de luchar entre ellos. Permanecían sentados. Algunos lo llamaron enfermedad. El archimago Antonidas de Dalaran pensaba otra cosa: los orcos se habían alimentado de magia demoníaca durante generaciones y los guardianes estaban viendo la abstinencia. Concluyó que solo podía haber una cura espiritual. Muchos en la Alianza consideraban imprudente buscar cura alguna." },
        { "El guardián jefe, Aedelas Lodonegro, gobernaba los campos desde Durnholde y tenía un esclavo orco propio, criado para ser un arma. Era Thrall. Encontró a su pueblo sentado tras estos muros y acabó regresando para abrir los campos por la fuerza. Ahora no hay orcos presos aquí. Los magos del Kirin Tor han tomado el antiguo campo para sus propios fines." },
        { side = "Horde", aside = true, sign = "P. F.", "Esos campos estaban en mi reino, por orden de mi rey. Lo cuenta con justicia." },
      },
    },
    ["ironbands-excavation-site"] = {
      title = "Excavación de Vetaferro",
      text = {
        { "Una de las excavaciones de la Liga, en las colinas del sur de Loch Modan, dirigida por el prospector Vetaferro. Me guardaré lo que esperaba encontrar allí abajo. Lo que encontró fueron troggs." },
        { "Los Rompecantos salieron en gran número por las galerías y ahora el lugar tiene más de campo de batalla que de excavación. El prospector no se ha rendido, como enano y miembro de la Liga que es, pero agradecería mucho cualquier ayuda." },
        { "A esto se refiere la Liga cuando dice que excavar es peligroso. La tierra está llena de cosas que preferirían seguir enterradas, y de algunas que preferirían no estarlo." },
      },
    },
    ["ironforge"] = {
      title = "Forjaz",
      text = {
        { "Forjaz no está construida sobre la montaña, sino dentro de ella. Sus salones se extienden por el interior de la montaña de Forjaz y en su centro arde la Gran Fundición." },
        { "La ciudad gira en torno a la fundición como una rueda. El rey Magni celebra su corte en el Alto Trono, la Sala Militar instruye a los defensores de la montaña, los magos se reúnen en la Sala Mística y, desde la caída de Gnomeregan, los exiliados gnomos han hecho suya Ciudad Manitas: ruidosa, ingeniosa y nostálgica. Bajo todo ello discurre el Tranvía Subterráneo, obra gnoma, que lleva viajeros por debajo de las montañas hasta Ventormenta." },
        { client = "forever", "Bajo la Antigua Forjaz se encuentral Salón de los Feudales. Los intrusos Hierro Negro han irrumpido en él y Magni quiere la cabeza de su comandante, Durgen Martillo Funesto. Incluso aquí, los salones más antiguos de una ciudad pueden convertirse en su problema más reciente." },
        { "Y después está la Sala de los Exploradores, donde la Liga guarda su biblioteca y sus hallazgos: reliquias de Uldaman, huesos de bestias que nadie ha visto vivas y mapas de lugares que la mayoría de los enanos solo conocerán por los libros. A mí me encontrarás en el Alto Trono, a unos pasos del trono del rey. Ven a verme. Siempre me falta gente que haya estado de verdad en algún sitio." },
        { side = "Horde", aside = true, sign = "P. F.", "Su invitación es amable. No aconsejaría aceptarla vistiendo los colores de la Horda." },
      },
    },
    ["ironforge-tune"] = {
      title = "Forjaz",
      text = {
        { "Forjaz es mi ciudad, y solo diré que su melodía suena en algún lugar de ella, pues los salones son muchos. Los Barbabronce mantienen encendida la Gran Forja bajo Magni desde hace más tiempo del que la mayoría de los reinos ha tenido nombre. Me encontrarás en la Sala de los Exploradores, si alguna vez necesitas una historiadora." },
      },
    },
    ["jaedenar"] = {
      title = "Jaedenar",
      text = {
        { "Jaedenar fue un lugar de los elfos de la noche, con ruinas y túmulos en el oeste de Frondavil. Ahora lo ocupa el Consejo de la Sombra, el antiguo culto de brujos que convirtió a los orcos en instrumentos de la Legión Ardiente. Brujos orcos y Renegados, demonios y sátiros llenan sus salas. Bajo ellos, en la Guarida Sombría, el señor de las Sombras Fel'dan sella sus pactos con la Legión." },
        { "El Círculo Esmeralda quiere destruir el Consejo. Incluso dentro, el culto está en guerra consigo mismo: sus amos conspiran unos contra otros y cada rival tiene espías junto a los demás." },
      },
    },
    ["jaina-proudmoore"] = {
      title = "Lady Jaina Valiente",
      text = {
        { "Jaina Valiente era una joven hechicera de Dalaran, hija del almirante de Kul Tiras y amiga del príncipe Arthas en días más felices. Cuando llegó la peste cabalgó a su lado, hasta Stratholme, donde se negó a seguirlo. Después, un profeta la envió al oeste por mar y condujo a los supervivientes de Lordaeron hasta Kalimdor." },
        { "Allí hizo lo que nadie en la Alianza creía posible: combatió junto a Thrall y los elfos de la noche contra la Legión Ardiente en el Monte Hyjal y después pactó la paz con la Horda. Cuando su padre, el almirante Daelin Valiente, llegó con su flota para terminar la vieja guerra, ella no se interpuso en el camino de la Horda y él murió por ello. Carga con ese peso desde entonces." },
        { "Mantener la paz no ha sido fácil. Unos años después de Hyjal, ataques y barcos hundidos casi enfrentaron de nuevo a Theramore y Durotar, hasta que Jaina, trabajando discretamente con Thrall, descubrió al Filo Ardiente detrás de todo y a su propio chambelán a sueldo del culto. La búsqueda la llevó a un rincón protegido de Durotar donde encontró a la última persona que esperaba ver viva: Aegwynn, la Guardiana, madre de Medivh, viviendo sola. Jaina aún gobierna Theramore y mantiene la paz con Thrall. Creo que es la persona más valiente de este registro." },
      },
    },
    ["jinthaalor"] = {
      title = "Jintha'Alor",
      text = {
        { "Jintha'Alor es la gran ciudad templo de los trols Vilrama en el sur de Tierras del Interior, una montaña de piedra escalonada que surge del bosque. En su cima, la sacerdotisa Vil Hexx y sus sacerdotes conservan los antiguos ritos Amani, y otros más antiguos y peores: han tomado prisioneros para sacrificarlos a Hakkar el Cazador de Almas, dios de la sangre de los trols." },
        { "Los sacerdotes Atal'ai que sirvieron a Hakkar en el sur llegan incluso hasta aquí: uno de ellos, condenado al exilio por su propio pueblo, vive entre los trols de Tierras del Interior. Por lo que entiendo, los Vilrama no lamentaron recibirlo." },
      },
    },
    ["kalaran-windblade"] = {
      title = "Kalaran Espada del Viento",
      text = {
        { "Kalaran Espada del Viento acampa en La Garganta de Fuego con un escudero y un rencor. La escoria Hierro Negro de La Caldera mató a su padre, dice, y cuando suplicó ayuda al magistrado de Ventormenta, nadie le hizo caso. Ventormenta, según él, prefiere no admitir que este rincón del mundo existe, y mucho menos enviar a su valiosa milicia a hacer justicia. Así que busca venganza, llanamente, y pregunta si existe en este mundo una causa más apasionada." },
        { "Es un solo hombre, con lo que él llama un escudero medio idiota, y espera que sea el viajero quien haga el trabajo. Las cuatro torres de vigilancia de los Hierro Negro han de arder con un fuego que ningún elemento pueda apagar, encendido con una Antorcha de Retribución de su propia mano: corazones de llama y aceite de gólem, un mango forjado con las dagas de torio de los esclavistas de La Caldera, y un soporte sacado de un Símbolo de Ragnaros arrebatado al Martillo Crepuscular, cuya magia demoníaca, dice, es justo lo que necesitaba. Quien toma la antorcha siente una corriente de odio e ira correr por sus venas." },
        { "Su escudero, Maltrake, vive para servir a su maestro, y las torres en llamas le parecen gloriosas. Kalaran promete a quienes le ayudan riquezas que jamás habrían podido imaginar, y mientras tanto no se muerde la lengua con ellos. Siento algo de simpatía por un hijo al que nadie quiso escuchar, y bastante menos por un arma hecha con el símbolo del mismísimo Señor del Fuego." },
      },
    },
    ["karazhan"] = {
      title = "Karazhan",
      text = {
        { "Karazhan fue el hogar de Medivh, último Guardián de Tirisfal. Heredó el extraordinario poder de Aegwynn y, con él, un secreto que ella no había visto: Sargeras se había ocultado en su hijo antes de que naciera. A través del Guardián que debía oponerse a la Legión, su señor ayudó a Gul'dan a abrir el Portal Oscuro." },
        { "Khadgar y Anduin Lothar mataron a Medivh en esta torre antes de que terminara la Primera Guerra. Años después regresó para advertir a Azeroth de la invasión de la Legión. Ni la muerte había conseguido poner fin a la historia del Guardián." },
        { "La aldea de abajo está en ruinas y el Sótano del Maestro se extiende bajo sus edificios abandonados. Karazhan permanece cerrada. La torre ha sobrevivido al hombre que vivía allí y a la certeza de que alguna vez estuviera del todo solo." },
      },
    },
    ["karazhan-crypts-tune"] = {
      title = "Criptas de Karazhan",
      text = {
        { "Las criptas bajo Karazhan, la torre de Medivh en el Paso de la Muerte, tienen tres piezas propias en algún rincón de su interior. Medivh fue el último Guardián de Tirisfal, y su torre le ha sobrevivido. Lo que yace debajo ha sobrevivido a mucho más." },
      },
    },
    ["kargath"] = {
      title = "Kargath",
      text = {
        { "Kargath es la fortaleza de la Horda en el noroeste de Tierras Inhóspitas, una empalizada sobre un risco que lleva el nombre de Kargath Garrafilada, jefe manco del clan Mano Destrozada en la Segunda Guerra. Es el campamento de la Fuerza Expedicionaria de Kargath y su ocupación es la guerra contra los enanos Hierro Negro de la Montaña Roca Negra, al oeste." },
        { "Los orcos tienen motivos. Los Hierro Negro del general Forjainquina masacraron una división entera de la Fuerza Expedicionaria, la centésima novena. El señor de la guerra de Kargath ha dado una orden permanente: matar a primera vista. En este asunto, un enano de Forjaz y un orco de Kargath coinciden." },
      },
    },
    ["katrana-prestor"] = {
      title = "Lady Katrana Prestor",
      text = {
        { "Lady Katrana Prestor es la consejera más cercana del alto señor y una dama muy admirada en la corte: culta, amable y bellísima. Sabe mucho de muchísimas cosas, incluidos los dragones, y Bolvar Fordragon confía plenamente en ella." },
        { "No todo el mundo comparte esa confianza. Cuando el magistrado Salomón de Villa del Lago suplicó al trono soldados contra los orcos Roca Negra, fue el consejo de lady Prestor lo que los mantuvo en casa. Hay al menos un alguacil de Ventormenta que nunca se lo ha perdonado. Solo dejo por escrito lo que se sabe. Más le vale tener plena certeza a quien escriba algo más sobre una dama de la corte." },
      },
    },
    ["keeper-remulos"] = {
      title = "Guardián Rémulos",
      text = {
        { "El guardián Rémulos es hijo de Cenarius y tiene, como su padre, la mitad inferior del cuerpo de ciervo. Los druidas acuden a su santuario del Claro de la Luna en busca de ayuda. La Pesadilla que se extiende por el Sueño Esmeralda les ha dado motivos urgentes para buscarla." },
        { "Cuando Eranikus, consorte de Ysera, fue invocado aquí, la Pesadilla vino con él. Rémulos defendió Amparo de la Noche mientras sus aliados luchaban por liberar al dragón. Tyrande llegó para redimir a Eranikus. Un viajero puede conocer el Claro de la Luna como lugar de paz. Su guardián ha tenido que combatir por esa paz en el corazón de la aldea." },
      },
    },
    ["kelthuzad"] = {
      title = "Kel'Thuzad",
      text = {
        { "Kel'Thuzad era un archimago de Dalaran y miembro de su consejo gobernante que buscó poder prohibido. Antonidas lo encontró primero en sus almacenes del norte: ratas muertas a las que intentaba mantener en movimiento. El Kirin Tor lo juzgó y confiscó su trabajo. Kel'Thuzad, con una voz amistosa en la cabeza que lo había estado ayudando, los abandonó y marchó al norte para buscar a su dueño." },
        { "En Rasganorte, un señor de la cripta, Anub'arak, le mostró un zigurat llamado Naxxramas: laboratorios, armerías y calderos donde se preparaba un fluido que convertía a los moribundos en muertos. Horrorizado, intentó huir, pero los espectros del Rey Exánime no lo dejaron. Se arrastró al pie del Trono Helado, suplicó y juró servir a su amo. El Rey Exánime respondió con una visión de Naxxramas elevándose al cielo, una fortaleza desde la que Kel'Thuzad extendería su poder." },
        { "Volvió para fundar el Culto de los Malditos entre los pobres de Lordaeron. Con ellos propagó la peste mediante el grano de Andorhal. El príncipe Arthas lo mató allí. Su cuerpo fue llevado a Quel'Thalas, a la Fuente del Sol, y su poder lo resucitó como exánime." },
        { "Condujo a la Plaga a Dalaran para invocar al propio Archimonde y permaneció junto a Arthas cuando los señores del terror se volvieron contra él. Cuando Arthas marchó al norte, al Trono Helado, Kel'Thuzad se quedó para gobernar las Tierras de la Peste en su nombre. Aún las gobierna desde Naxxramas. Ni siquiera destruido está acabado un exánime mientras dure su filacteria." },
      },
    },
    ["khans-of-desolace"] = {
      title = "Los kanes de Desolace",
      text = {
        { "Desolace es tierra de centauros y sus clanes son muchos: los Kolkar al norte, los Gelkis al suroeste, los Magram al sureste y los Maraudine que custodian la tumba sagrada. Los Gelkis y los Magram son enemigos acérrimos y ambos ofrecen encargos contra el otro." },
        { "La Alianza y la Horda han comprendido que una nación centauro unida las expulsaría de Desolace y que el odio entre los clanes es su mejor arma. Ambas juegan a lo mismo: aliarse con los Gelkis o los Magram, matar guerreros del otro clan hasta ganarse su amistad y aprender de los nuevos amigos cómo quebrar a los demás. Funciona. Me entristece un poco que funcione." },
      },
    },
    ["kharanos"] = {
      title = "Kharanos",
      text = {
        { "Kharanos está en el frío corazón de Dun Morogh, junto al camino que une los campos de instrucción del Valle de Crestanevada con las puertas de Forjaz. Es un pueblo pequeño para nuestros criterios: una herrería, unas casas robustas y el edificio que lo hace famoso, la Destilería Cebatruenos, donde la familia Cebatruenos lleva perfeccionando sus cervezas más tiempo del que nadie quiere admitir." },
        { "No confundas el calor del hogar con seguridad. Los trols Peloescarcha dominan las colinas del oeste, los troggs siguen saliendo de las profundidades y, desde la caída de Gnomeregan, sus exiliados comparten estos caminos con nosotros. Aun así, el pueblo mantiene sus puertas abiertas: un enano que rechaza a un viajero aterido no es un enano de verdad." },
      },
    },
    ["kirith-the-damned"] = {
      title = "Kirith el Maldito",
      text = {
        { "El teniente Kirith servía al héroe de la Horda cuyo fantasma espera ahora fuera de Rocal. El archimago Allistarj capturó a ambos en Las Tierras Devastadas y los encerró en una cueva. El héroe resistió. La voluntad de Kirith cedió. Desde su propia jaula, su comandante oyó los experimentos, los gritos resonando por los pasillos. Después no volvió a verlo ni a oírlo." },
        { "Lo que hicieron de él esos experimentos recorre ahora Serpiente Enroscada como Kirith el Maldito. Acaba con ello y lo que queda del teniente te hablará, e incluso sonreirá: sabe cómo se protege Razelikh el Envilecido, con tres sirvientes que llevan cada uno un tercio de un amuleto, y te envía con la noticia a su comandante. Acabar con ello es una de las pocas cosas bondadosas que han ocurrido en Las Tierras Devastadas en mucho tiempo." },
      },
    },
    ["kobolds"] = {
      title = "Los kóbolds",
      text = {
        { "Todo minero de la Alianza tiene una historia de kóbolds y casi todas terminan con un pico perdido. Son criaturas pequeñas de los túneles con cara de rata, cobardes solas y peligrosas en número, y siempre son muchas. Llevan velas en la cabeza para alumbrar la oscuridad y luchan a muerte por una vela mucho después de cuando habrían huido de una espada." },
        { "Están donde hay algo que excavar. Un clan de las Montañas Crestagrana ha llenado las minas del Bosque de Elwynn y Páramos de Poniente. Las Ratas de Túnel han excavado sobre Thelsamar, los Mostacho Seco sirven a los gigantes de Tierras Altas de Arathi y los Morrofiemo rebuscan minerales en Las Mil Agujas." },
        { "Es fácil reírse de ellos. Los granjeros de Elwynn que pierden sus reses y cosechas a sus manos no se ríen." },
      },
    },
    ["kodo-graveyard"] = {
      title = "Cementerio de Kodos",
      text = {
        { "En mitad de Desolace está el lugar donde los kodos van a morir: un vasto campo de huesos y colmillos, con grandes costillares que se arquean sobre el polvo. Entre ellos llegan despacio desde las llanuras viejos kodos para tumbarse. Nadie sabe por qué vienen aquí y los tauren tratan el lugar con respeto." },
        { "No todos lo hacen. Los fantasmas de centauros y kodos lo recorren de noche, y un goblin ha inventado un aparato que devuelve a las bestias moribundas al servicio a base de descargas para venderlas a las caravanas. No sé decidir si es ingenioso o monstruoso. Sospecho que los kodos tienen una opinión." },
      },
    },
    ["kurzen-rebellion"] = {
      title = "La rebelión de Kurzen",
      text = {
        { "El coronel Kurzen llegó a Tuercespina con reputación de soldado: un táctico brillante, considerado en otro tiempo un hombre grande y noble. En la jungla cambió. Sus seguidores se convirtieron en una fuerza leal solo a él, que asaltaba y cazaba con una crueldad inaceptable para sus antiguos camaradas." },
        { "El teniente Doren llevó a los disidentes a un Asentamiento Rebelde en las colinas. Superados diez a uno, combaten a Kurzen con las tácticas que él les enseñó. El hermano Nimetz sospecha primero de magia trol, pero su investigación lleva a Mai'Zoth, un ogro mago, y al Ojo de la Mente con el que se controlan voluntades." },
        { "Nimetz pide matar al mago y recuperar el artefacto. Ten especial cuidado con la segunda tarea, $gviajero:viajera;. Teme que dejarlo allí condene a otro soldado al destino de Kurzen." },
      },
    },
    ["lakeshire"] = {
      title = "Villa del Lago",
      text = {
        { "Villa del Lago es una población de casas de madera a orillas del Lago Sempiterno, con posada, ayuntamiento y un puente que sus vecinos aún están reconstruyendo: en la última invasión fundieron su hierro para hacer espadas, y los gnolls robaron el cargamento que debía reponerlo." },
        { "Su magistrado, Salomón, es un hombre prudente con muchísimos problemas. Los Roca Negra ocupan el fuerte del norte y mantienen a sus habitantes encerrados en la villa. Escribió a Ventormenta pidiendo ayuda y recibió por respuesta que no sobraban soldados para enviarlos basándose en conjeturas. Desde entonces ha sabido qué impulsa realmente a los orcos de Roca Negra y quién en Ventormenta no quería que lo escucharan. Sospecho que Villa del Lago no lo olvidará." },
      },
    },
    ["larkorwi"] = {
      title = "Lar'korwi",
      text = {
        { "El abrecaminos Torwa, un tauren acampado en el Cráter de Un'Goro, tiene una cuenta pendiente con Lar'korwi, el gran raptor que domina a los ravasaurios del cráter. Hace mucho tiempo, cuenta Torwa, uno de sus hermanos se llevó carne de un animal que Lar'korwi había cazado, sin saber nunca que el raptor lo vigilaba entre los árboles. Lar'korwi lo acechó durante días y arrasó todo lo que había tocado. Al final, el hermano intentó huir del cráter, y Lar'korwi lo mató no muy lejos de donde Torwa espera ahora." },
        { "El plan de Torwa es hacer que la bestia acuda a él. Quien robe carne de una presa fresca será perseguido, como lo fue su hermano. Las glándulas odoríferas de las hembras de Lar'korwi, tomadas entre los huevos de ravasaurio, sirven de cebo, y la carne robada, frotada con ellas y dejada en un sendero de montaña entre los huesos de grandes criaturas desaparecidas hace mucho, debería hacerlo salir. Torwa describe una bestia enorme con garras que cortan como cuchillas y promete la muerte a quien lo mire a los ojos." },
        { "A quien le trae su cabeza, Torwa lo alaba en nombre de la Madre Tierra y pone la hazaña a la altura de las de sus mayores ancestros. El plan era de Torwa. El robo, la recolección y la lucha se los dejó a quien pudo convencer." },
      },
    },
    ["leper-gnomes"] = {
      title = "Los gnomos parias",
      text = {
        { "No todos los gnomos escaparon de Gnomeregan. Algunos sobrevivieron a la radiación y quedaron transformados, con el cuerpo destrozado y la mente trastornada y violenta. Los enanos los llaman gnomos parias y los exiliados prefieren no hablar de ellos." },
        { "Acechan en los accesos a la antigua ciudad y en los almacenes que la rodean, rebuscando lo que pueden y atacando a quien se acerca demasiado." },
        { "Si debes combatirlos, recuerda que alguna vez fueron los vecinos de alguien, $gviajero:viajera;." },
      },
    },
    ["lights-hope-chapel"] = {
      title = "Capilla de la Esperanza de la Luz",
      text = {
        { "La Esperanza de la Luz es una pequeña capilla de piedra en suelo consagrado de las Tierras de la Peste del Este. Lord Maxwell Neófitus dirige allí al Alba Argenta. Cualquiera que combata a la Plaga puede encontrar acogida, venga de la Alianza o de la Horda." },
        { "Cuando Naxxramas apareció sobre la comarca, hasta la Cruzada Escarlata se reunió aquí con el Alba Argenta para acordar una lucha común. Más tarde llevaron a la capilla la filacteria capturada de Kel'Thuzad. A quien pasa junto a sus muros le parece demasiado modesta para un lugar donde tantos enemigos han tenido motivos para reunirse." },
        { "Korfax, Campeón de la Luz, habla allí por la Hermandad de la Luz, que describe como el Alba Argenta sin conciencia, o la Cruzada Escarlata sin el fanatismo. También habla de la primera armadura Acorator, hecha solo para el Alto señor Mograine. Con ella, dice Korfax, el Alto señor parecía una criatura del Vacío Abisal, y los de la Plaga caían por centenares a su alrededor mientras se abría camino con la Crematoria. Tras la muerte de Mograine, los caballeros de Lordaeron vistieron armaduras parecidas en su honor, y por cada uno de ellos que caía, otros retomaban la lucha. Korfax califica de polémica esa muerte, lo cual es una forma amable de decirlo." },
      },
    },
    ["linken"] = {
      title = "Linken",
      text = {
        { "Linken apareció un día en el Refugio de Marshal sin saber cómo había llegado. Nadie más lo sabe tampoco, dice alegremente. Es un secreto para todos. Es un gnomo, aunque los gnomos del campamento señalan que no comparte su interés por los artilugios, y llevaba una mochila, una espada y un golpe en la cabeza." },
        { "Los recuerdos vuelven poco a poco mientras los viajeros lo ayudan: una espada que templar en las aguas termales de Cuna del Invierno, un tótem hecho con ayuda de una amiga de Frondavil. Al final recuerda. Llegó al cráter para combatir a Correfuego, el elemental de fuego que custodia un artefacto llamado la Llama Dorada. Debía ser el último paso de un largo viaje." },
        { "No da ese paso él mismo. Ahora tú eres el héroe, dice a quien lo ha ayudado, y lo envía con la advertencia de que es peligroso ir sin compañía. Promete llevar la Llama a su patria y mantenerla lejos de manos malvadas. No he encontrado esa patria en ningún mapa. La he buscado." },
      },
    },
    ["loch-modan"] = {
      title = "Loch Modan",
      text = {
        { "Al este de las puertas está la comarca más apacible de Khaz Modan: colinas verdes, pinares y un largo lago azul, todo retenido por la gran presa de su extremo norte." },
        { "Es tierra de cultivo y caza. Los enanos que viven aquí tardan un poco más en enfadarse y bastante menos en ofrecer una bebida que sus parientes de Forjaz. Necesitan ese buen humor. Los troggs excavan en los valles del sur, los ogros dominan el noreste y se ha visto a los Hierro Negro en las colinas." },
        { "Descansa en Thelsamar, contempla la presa y visita el Valle de los Reyes. Después, mira dónde pisas." },
      },
    },
    ["loramus-thalipedes"] = {
      title = "Loramus Thalipedes",
      text = {
        { "En una isla frente a la costa de Azshara vive un cazador de demonios llamado Loramus Thalipedes, solo con sus canes manáfagos. Dice que, si quieres combatir demonios, harías bien en escuchar antes su historia." },
        { "Los viajeros llegan desde Las Tierras Devastadas, donde Razelikh el Envilecido conserva tres sirvientes que no pueden morir mientras los fragmentos de amuleto ligados a ellos permanezcan allí. Loramus sabe romper esas protecciones. Hace falta el verdadero nombre del señor demoníaco, que un dios menor de la costa de Azshara dará por un precio, y un arma forjada para llevarlo: hecha con el cristal que dejan los gigantes de los riscos del sur y trabajada por un herrero capaz de manejar fuego vil." },
        { "Se ríe de la mayoría de los que lo intentan. No los rechaza ni los detiene. Fuera cual fuera su motivo para cazar demonios, parece haber decidido hace tiempo que el mundo necesita a más gente haciéndolo." },
      },
    },
    ["lord-kazzak"] = {
      title = "Lord Kazzak",
      text = {
        { "Lord Kazzak domina Escara Impía, en el sur de Las Tierras Devastadas. Desde la Tercera Guerra, este gran guardia apocalíptico la ocupa con guardias viles y otros de su especie. Camina abiertamente entre ellos, un sirviente cornudo de la Legión Ardiente con poca necesidad de ocultarse." },
        { "Héroes de ambas facciones han ido contra él. Cada uno que mata lo fortalece. Tenlo en cuenta si te unes a ellos: un ataque fallido puede dejar al siguiente grupo ante un enemigo más fuerte, $gviajero:viajera;." },
      },
    },
    ["mages"] = {
      title = "Magos",
      text = {
        { "El arte humano de la magia empezó con cien alumnos. Durante las Guerras Trols, los altos elfos de Quel'Thalas les enseñaron a lanzar hechizos a cambio de ayuda contra los Amani. Sus herederos fundaron Dalaran y su consejo gobernante, el Kirin Tor. La ciudad se convirtió en el gran centro humano de los estudios arcanos." },
        { "Dalaran cayó en la Tercera Guerra y sus alumnos se dispersaron: a Theramore con Jaina Valiente, a Ventormenta y a Entrañas entre los Renegados, algunos de los cuales estudiaron allí en su primera vida. Gnomos y trols Lanza Negra tienen sus propios magos. Una educación del Kirin Tor es un camino hacia el arte, aunque sus graduados a veces hablen como si fuera el único." },
        { client = "forever", "También se ha visto a orcos en el oficio de mago. La Orden Eminente de los cielonatos ha descendido en busca de los conocimientos arcanos que perdió su pueblo." },
        { "Un mago conjura fuego, escarcha y fuerza arcana pura, además de mucha agua fresca. Recomiendo llevar uno a toda excavación, aunque solo sea por el agua, $gviajero:viajera;." },
      },
    },
    ["magni-bronzebeard"] = {
      title = "Rey Magni Barbabronce",
      text = {
        { "El rey Magni Barbabronce celebra su corte en el Alto Trono de Forjaz y gobierna la ciudad que su clan conserva desde la Guerra de los Tres Martillos. Es el mayor de tres hermanos. Muradin marchó al norte con el príncipe de Lordaeron durante la Tercera Guerra y desde entonces no se ha sabido de él. Brann es el explorador más famoso de la Liga y uno de los más difíciles de localizar." },
        { "Magni sigue de cerca el trabajo de la Liga. Los hallazgos de Uldaman apuntan a que los titanes dieron forma a los enanos hace mucho tiempo. Un rey de linaje tan largo tiene motivos para preguntar dónde empezó, y una historiadora que trabaja a unos pasos de su trono tiene todos los motivos para agradecer su interés." },
        { "Su hija le preocupa de forma más urgente. La princesa Moira está en la ciudad de los Hierro Negro, bajo la Montaña Roca Negra, casada con el emperador Dagran Thaurissan. Forjaz lo considera un secuestro y Magni promete una recompensa de héroe a quien la traiga a casa. Si aceptas el encargo, llevarás contigo las esperanzas de un padre además de las órdenes de un rey, $gviajero:viajera;." },
      },
    },
    ["malfurion-stormrage"] = {
      title = "Malfurion Tempestira",
      text = {
        { "Malfurion Tempestira era un joven estudioso de los elfos de la noche cuando los Altonato empezaron a cambiar y uno de los primeros en sospechar por qué. Cuando la Legión Ardiente entró por el Pozo de la Eternidad, fue con su hermano Illidan y la sacerdotisa Tyrande en busca de Cenarius, que se convirtió en su maestro. Lo que le enseñó se convirtió en el druidismo. Al final de la Guerra de los Ancestros, Malfurion comprendió que había que destruir el propio Pozo. Después vino el Gran Cataclismo." },
        { "Condujo a los supervivientes al Monte Hyjal, descubrió que Illidan había creado allí otro Pozo y encerró a su hermano en un túmulo bajo tierra. Prohibió la magia a su pueblo, pactó con los dragones sobre el Árbol del Mundo y se durmió en el Sueño Esmeralda durante siglos seguidos, dejando a Tyrande la vigilancia." },
        { "Tyrande lo despertó cuando volvió la Legión y él destruyó a Archimonde al pie del Árbol. Ahora vuelve a estar perdido en el Sueño y los druidas que duermen en estos túmulos no dicen cuándo regresará. Su pueblo está aprendiendo a envejecer sin él." },
      },
    },
    ["mannoroc-coven"] = {
      title = "Aquelarre Mannoroc",
      text = {
        { "En el sur de Desolace hay un valle abrasado donde los demonios caminan a la vista de todos: guardias apocalípticos, canes manáfagos, infernales y cosas peores entre altares rotos y fuego verde. Se llama Aquelarre Mannoroc y los demonios no llegaron por casualidad." },
        { "Los dejaron entrar. El Filo Ardiente conserva en su fortaleza del norte una reliquia llamada Mano de Iruxos. Con ella ha abierto en el valle portales al reino de los demonios. Los tauren de Cazasombras intentan cerrarlos. Cada portal cerrado es una puerta que la Legión debe volver a abrir, y la Legión es paciente." },
      },
    },
    ["maraudon"] = {
      title = "Maraudon",
      text = {
        { "Maraudon es el lugar sagrado de los centauros en el suroeste de Desolace. Su padre Zaetar está enterrado en sus inmensas cavernas y su madre Theradras habita más allá de cámaras de cristal resplandeciente. Solo los más devotos de los centauros pueden entrar." },
        { "La tumba tiene problemas. Lord Lenguavil extiende veneno por las cuevas y ha creado una criatura de podredumbre. Celebras, sobrino de Zaetar, vaga allí maldito. Una mujer del Martillo Crepuscular pide tallas de las cavernas de cristal y afirma que contienen reliquias de los dioses antiguos. Ten cuidado con los fines a los que sirve tu viaje, $gviajero:viajera;. Hay varios interesados en lo que yace bajo este suelo sagrado." },
      },
    },
    ["marsh-and-mire"] = {
      title = "Marjal y cenagal",
      text = {
        { "Los Humedales y el Marjal Revolcafango comparten una melodía, y mucho aire húmedo y largas aguas grises. Los enanos mantienen el Puerto de Menethil en uno, y Theramore se alza en el otro. Ninguno es un sitio que yo elegiría para un paseo largo con buenas botas." },
      },
    },
    ["marshal-windsor"] = {
      title = "Alguacil Windsor",
      text = {
        { "El alguacil Reginald Windsor mandaba soldados de la Alianza en Vigilia de Morgan y reunió pruebas que vinculaban a los orcos Roca Negra con el Vuelo Negro. Llegó a sospechar que alguien de Ventormenta quería que esas pruebas se perdieran. Los Hierro Negro lo capturaron, se quedaron con sus notas y empezaron a descifrar su código." },
        { "Windsor sigue preso en la prisión de Ciudad Forjatiniebla. Insiste en que Bolvar Fordragon no ve la verdad, aunque la prueba está a dos pasos. Quien lo saque de allí sabrá a qué se refiere." },
      },
    },
    ["marshals-refuge"] = {
      title = "Refugio de Marshal",
      text = {
        { "El Refugio de Marshal es un campamento en una cornisa del extremo norte del cráter donde se cobijaron los supervivientes de la expedición Marshal. Habían venido a explorar bajo Williden y Hol'anyee Marshal y subestimaron a las bestias: estas invadieron sus campamentos y tuvieron que huir a las alturas." },
        { "Siguen allí, junto a una extraña multitud de estudiosos, cazadores y exploradores perdidos que se les han unido, todos estudiando el cráter desde el único lugar donde nada se los comerá. Uno de ellos, un explorador llamado Ringo, se alejó hacia el volcán. Tengo entendido que lo encontraron." },
      },
    },
    ["masters-glaive"] = {
      title = "La Espada del Maestro",
      text = {
        { "En el sur de Costa Oscura, una hoja inmensa permanece clavada en la tierra, demasiado grande para cualquier mano que recorra hoy el mundo. Los elfos de la noche llaman al lugar La Espada del Maestro. Onus, el Anciano del Conocimiento, dice que señala el sitio donde cayó uno de los antiguos señores de la tierra, hace muchísimo tiempo." },
        { "Por eso ha venido el Martillo Crepuscular. El culto adora a aquellos antiguos señores y sus miembros se han reunido junto a la Espada y en las cuevas cercanas, con libros de nombres que no deberían pronunciarse." },
      },
    },
    ["mazthoril"] = {
      title = "Mazthoril",
      text = {
        { "Mazthoril es una gran cueva de hielo en el centro de Cuna del Invierno, profunda, fría y llena de dragones azules. Es el hogar del Vuelo Azul en Kalimdor. Las runas de cobalto de su suelo llevan a quienes saben usarlas hasta Haleh, su matrona protectora." },
        { "Los dragones azules son los guardianes de la magia y vigilan muy de cerca al Vuelo Negro. Saben lo que Nefarian cría en la Cumbre de Roca Negra y que no se puede permitir. Como no pueden alcanzarlo fácilmente en su montaña, están dispuestos a ayudar a los mortales que sí pueden." },
      },
    },
    ["mekgineer-thermaplugg"] = {
      title = "Mekigeniero Termochufe",
      text = {
        { "Sicco Termochufe sigue en Gnomeregan mientras el alto mecachifle Mekkatorque dirige a sus exiliados desde Forjaz. El alto mecachifle confió en él en otro tiempo. Esa confianza ha terminado en una acusación de traición y una petición de muerte." },
        { "La radiación liberada en la ciudad no logró exterminar a los troggs y devastó a sus habitantes gnomos. Termochufe gobierna las ruinas, entre las criaturas que aquel intento debía destruir y los supervivientes que dejó tras de sí." },
        { "Mekkatorque pide a los aventureros que lleven su sentencia hasta esos salones." },
      },
    },
    ["menethil-harbor"] = {
      title = "Puerto de Menethil",
      text = {
        { "El Puerto de Menethil está en la costa occidental de Los Humedales, un puerto de la Alianza con barcos hacia Auberdine y Theramore. El camino de Dun Algaz lo une con el interior. Una pequeña población húmeda puede ser importante cuando tantos viajes pasan por ella." },
        { "El capitán Puñorrecio necesita ayuda contra los orcos Faucedraco que amenazan el puerto. Pide destruir sus catapultas y derrotar al jefe Nek'rosh. Atiéndelo si puedes, $gviajero:viajera;. Aquí hay gente que intenta mantener abierto un puerto mientras el enemigo prepara su asedio." },
      },
    },
    ["mogrosh-ogres"] = {
      title = "Los ogros Mo'grosh",
      text = {
        { "En el noreste de Loch Modan, los ogros Mo'grosh han establecido su propia fortaleza y desafían a cualquiera a arrebatársela." },
        { "Los ogros son enormes, brutales y mucho más listos de lo que nos gusta admitir a los enanos. En particular, conviene no tomarse a la ligera a sus chamanes y místicos. Los Mo'grosh asaltan las granjas y los caminos del lago cuando les place, y hasta ahora nadie ha tenido fuerza para detenerlos de una vez por todas." },
        { "No entres en su fortaleza sin compañía, $gviajero:viajera;. No entres en absoluto, si puedes evitarlo." },
      },
    },
    ["moira-bronzebeard"] = {
      title = "Princesa Moira Barbabronce",
      text = {
        { "Moira Barbabronce es la única hija de Magni y heredera de Forjaz. Los Hierro Negro se la llevaron y se convirtió en esposa del emperador Dagran Thaurissan. Su padre creía que el emperador la había hechizado y envió campeones a liberarla." },
        { "Mataron a Thaurissan. Moira lo llamó un enano grande y honorable y les dijo que esperaba un hijo suyo. Declaró que ese hijo heredaría Forjaz, con o sin la aprobación de Magni. Puede que llevaras las órdenes de Magni, pero Moira tiene su propia respuesta, $gviajero:viajera;." },
        { "Llevo mucho tiempo conservando la historia de la casa de Magni. Este es el primer capítulo que preferiría no tener que escribir." },
      },
    },
    ["molten-core"] = {
      title = "Núcleo de Magma",
      text = {
        { "Bajo las Profundidades de Roca Negra, bajo todo, está el Núcleo de Magma, un mundo de lava en las raíces de la montaña, dominio del propio Señor del Fuego. Ragnaros vive allí desde que Thaurissan lo invocó. Lo custodian sus sirvientes: gigantes de fuego y piedra, señores caídos de las llamas y su mayordomo, Executus, el único que puede despertarlo." },
        { "Una criatura extraña a la entrada de la montaña, Lothos Levantagrietas, ve desgarros del mundo a su alrededor y enseña la entrada a quien tenga valor suficiente. Los Señores del Agua de Hydraxis, enemigos ancestrales de Ragnaros, ayudan a quien se adentra allí." },
      },
    },
    ["moonbrook"] = {
      title = "Arroyo de la Luna",
      text = {
        { "Arroyo de la Luna era la villa de mercado de las granjas de Páramos de Poniente y el hogar de sus mineros. Los orcos la quemaron en la Primera Guerra y fue reconstruida después de la Segunda. Ahora es una población Defias: sus habitantes han sido expulsados, sus casas están llenas de bandidos de máscaras rojas, y su antigua herrería y su granero ocultan el descenso a las Minas de la Muerte." },
        { "Es un lugar triste para recorrerlo y poco seguro. La Hermandad vigila el camino. Quien mire demasiado un determinado granero en las afueras probablemente descubra por qué." },
      },
    },
    ["moonglade"] = {
      title = "Claro de la Luna",
      text = {
        { "El Claro de la Luna es un valle oculto en las montañas del norte de Kalimdor, entre Frondavil y Cuna del Invierno, alrededor del Lago Elune'ara. Es el lugar más sagrado de los druidas, tanto elfos de la noche como tauren. El Círculo Cenarion tiene su hogar en la aldea de Amparo de la Noche, a orillas del lago. Es un lugar de paz, abierto a la Alianza y la Horda." },
        { "Los druidas vienen a aprender y los estudiosos del Círculo guardan aquí sus archivos. Durante el Festival Lunar, el mundo entero viene a honrar a los ancestros y a la luna." },
      },
    },
    ["morbent-fel"] = {
      title = "Morbent Vil",
      text = {
        { "Morbent Vil es el nigromante del Bosque del Ocaso, quien mantiene caminando a los muertos del Cerro del Cuervo y un aliado de los jinetes oscuros que salen del Paso de la Muerte. Vive en una casa en lo alto de Loma Inhóspita, sobre el cementerio, protegido por sus muertos y por un resguardo que desvía cualquier golpe." },
        { "Sven Yorgen, un leñador cuya esposa e hijos murieron a manos de los jinetes, lo quiere muerto, y el camino para lograrlo es largo. El diario de un Defias contó a Sven lo sucedido en su granja. El obispo Lontananza, en la catedral de Ventormenta, señaló un arma capaz de romper la protección. El hierro llegó de los pecios de la Tercera Flota, frente a Los Humedales, donde se hundió un cargamento de hierro de Forjaluz. Un herrero enano de Ventormenta lo convirtió en la Ruina de Morbent." },
        { "Son muchas molestias por un solo nigromante, $gviajero:viajera;. Sven no lo cree, y me cuesta reprochárselo." },
      },
    },
    ["morgans-vigil"] = {
      title = "Vigilia de Morgan",
      text = {
        { "Vigilia de Morgan ocupa una aldea quemada en el sureste de Las Estepas Ardientes. Una torre de mago en ruinas y unas tiendas albergan a soldados de la Alianza bajo el mariscal Maxwell. Se interponen entre las fuerzas Roca Negra y Villa del Lago, al otro lado de las montañas." },
        { "Sus informes identifican al Vuelo Negro como el poder que impulsa a los orcos. Ventormenta pidió pruebas. Lady Prestor no vio motivo de alarma. Aquí puede aprenderse tanto lo que han descubierto los soldados como la poca ayuda que ese descubrimiento les ha traído hasta ahora." },
      },
    },
    ["morganth"] = {
      title = "Morganth",
      text = {
        { "En las estribaciones orientales de Crestagrana se alza una torre solitaria, Ilgalar. En ella vive un brujo llamado Morganth, que ha sometido a los gnolls Pielsombra mediante colgantes encantados. La ley de Villa del Lago lo considera enemigo del reino y criminal a cualquiera que lo ayude." },
        { "Un mago de Elwynn, Theocritus de la Torre de Azora, ha estado escuchando a los gnolls de Morganth mediante esos mismos colgantes. Lo que ha oído lo asusta: Morganth busca una antigua reliquia élfica llamada la Guadaña de Elune y quizá la haya encontrado. Si es así, dice Theocritus, toda Ventormenta lo sentirá. En el Bosque del Ocaso se habla de esa misma reliquia, relacionada con los ferocanis. Lo anoto y no me gusta." },
      },
    },
    ["morladim"] = {
      title = "Mor'Ladim",
      text = {
        { "Morgan Ladimor era un caballero de estas tierras, conocido por defender a pobres y afligidos. Se casó joven con una muchacha llamada Lys y tuvo tres hijos. Cuando estalló la guerra en Lordaeron, marchó al norte para luchar junto a Uther el Iluminado y vio en qué se convirtió aquella guerra: la disolución de la Mano de Plata, la muerte de Uther, la peste. Lo mantuvo cuerdo la idea de volver a casa." },
        { "Volvió a un bosque oscurecido y una casa en ruinas, y por fin, en el cementerio del Cerro del Cuervo, a la tumba de su esposa. Algo se quebró en él. Cuando los cuidadores del cementerio intentaron sujetarlo, los mató. Al comprender lo que había hecho, se quitó la vida. Lo enterraron deprisa, fuera del cementerio, y a los pocos días su tumba estaba vacía. Ahora recorre el Bosque del Ocaso como Mor'Ladim y mata a quien encuentra." },
      },
    },
    ["morshan-rampart"] = {
      title = "La Empalizada de Mor'shan",
      text = {
        { "Mor'shan está en el extremo norte de Los Baldíos, donde los pastizales dan paso a Vallefresno. La Horda vigila la ruta que atraviesa la empalizada hacia las explotaciones madereras Grito de Guerra y su conflicto con las centinelas." },
        { "El muro señala una frontera que ninguno de los dos bandos considera resuelta. Los orcos necesitan madera y los elfos de la noche defienden el bosque que la proporciona." },
      },
    },
    ["mosshide-gnolls"] = {
      title = "Los gnolls Pellejomusgo",
      text = {
        { "Los Pellejomusgo habitan el pantano de Los Humedales que lleva su nombre. Rethiel el Guardaverde recuerda años en los que vivían allí en paz. Ahora ve un número creciente, vegetación aplastada y demasiada madera cortada para sus fuegos." },
        { "Pide a los viajeros que maten gnolls cerca de Dun Algaz para restaurar el equilibrio de la marisma. Su relato describe una disputa por un hogar compartido que se ha vuelto demasiado poblado y deteriorado. Las hachas y los fuegos resultan bastante familiares a una enana. Inquieta encontrarlos en la queja de otro sobre lo que le ocurre a la tierra." },
      },
    },
    ["mulgore"] = {
      title = "Mulgore",
      text = {
        { "Después del polvo rojo de Durotar y la hierba amarilla de Los Baldíos, Mulgore sorprende: llanuras verdes y onduladas, lagos y arroyos claros, manadas de kodos y zancudos, y grandes mesetas que se alzan sobre la hierba. Es la patria de los tauren y, por primera vez en su larga historia, la poseen como propia." },
        { "Durante generaciones, los tauren recorrieron las llanuras de Kalimdor, acosados por los centauros allá donde fueran. Cuando los orcos llegaron a Kalimdor, Thrall ayudó al pueblo de Cairne Pezuña de Sangre a rechazarlos y tomar estos pastizales. Desde entonces, las tribus se han reunido aquí. Aun así, Mulgore tiene problemas: los jabaespines Erizapúas atacan desde los barrancos, los gnolls Crines Pálidas cazan sus bestias y los goblins de Ventura y Cía. han excavado una mina en sus riscos y contaminado sus pozos pese a la negativa expresa de los tauren." },
      },
    },
    ["murlocs"] = {
      title = "Los múrlocs",
      text = {
        { "Cabañas y redes de pesca múrlocs bordean las orillas de ambos continentes, desde las aguas de Elwynn hasta Costa Oscura. Cazadores y oráculos ocupan sus asentamientos y a menudo atacan a quienes se acercan. Un viajero puede encontrar varias tribus sin aprender mucho de la historia de su presencia." },
        { "Una tribu tuvo un papel decisivo en el viaje de la nueva Horda. Múrlocs al servicio de una bruja del mar capturaron a trols y orcos en las islas Lanza Negra. Los seguidores de Thrall se abrieron paso luchando. Sen'jin murió y los Lanza Negra supervivientes navegaron con ellos a Kalimdor. Aquella alianza empezó junto a una orilla defendida por múrlocs, mucho antes de tener un hogar en Durotar." },
      },
    },
    ["myzrael"] = {
      title = "Myzrael",
      text = {
        { "Los Fragmentos de Myzrael dejan oír una voz bajo las Tierras Altas de Arathi. Una princesa de la tierra, prisionera, pide ayuda a un viajero para escapar. Los cristales dan al encuentro una sensación de calidez y seguridad." },
        { "Theldurin el Perdido ofrece otra versión. Teme lo que hará cuando recupere sus fuerzas y pregunta por qué la encadenaron los gigantes si es tan fácil de controlar. Su respuesta consiste en invocarla, derrotarla y volver a atar sus grilletes a los fragmentos." },
        { "Después, un grito asciende desde muy hondo. Los cristales permanecen, pero su antiguo consuelo ha desaparecido. Lo que ahora late en ellos parece odio hacia el mundo de arriba. La voz que pidió ayuda con tanta dulzura se ha convertido en lo más inquietante de la tranquila ladera." },
      },
    },
    ["naga"] = {
      title = "Los nagas",
      text = {
        { "El Gran Cataclismo arrastró a los Altonato de Azshara bajo el mar junto con su capital. Sobrevivieron transformados en seres escamosos de mitad inferior serpentina, aletas y, en algunos casos, cuatro brazos. Construyeron un reino bajo el agua. Los viejos relatos aún sitúan allí a su reina." },
        { "Volvieron a la superficie durante la Tercera Guerra, cuando lady Vashj dirigió a los nagas al servicio de Illidan. Ahora sus partidas ocupan la Ensenada de Zoram y el templo inundado de Brazanegra, las costas arruinadas de Azshara y Costa Oscura, y orillas de Feralas, Desolace y Marjal Revolcafango." },
        { "La historia de los Altonato no terminó cuando se hundieron sus ciudades, $gviajero:viajera;. Esos mismos Altonato disputan ahora lugares en las costas del continente, tan cambiados como la tierra que conocieron." },
      },
    },
    ["natalia-maralith"] = {
      title = "Natalia Mar'alith",
      text = {
        { "Natalia Mar'alith era una sacerdotisa elfa de la noche y la esposa del Comandante Mar'alith, del Fuerte Cenarion, y fue la primera del fuerte en unirse a los excavadores de la Liga cuando llegaron a Silithus. Bajaban a las colmenas en busca de artefactos perdidos. En Colmen'Regal dio con un cristal grabado con glifos, apoyó la cara en él como si alguien la llamara y se quedó inmóvil. Los excavadores la sacaron de allí y los druidas del Círculo la despertaron. Durante unas semanas pareció estar bien." },
        { "Luego volvió al campamento de los excavadores y exigió que regresaran a la colmena. Brann Barbabronce, que desde entonces ha desaparecido, se negó a volver sin un ejército: el enjambre se había triplicado. Antes de que empezara la pelea, ella ya hablaba con alguien a quien ninguno veía, en una lengua que ninguno conocía, aunque entre los cuatro, mono incluido, dice Frankal Petraponte, conocen treinta y ocho lenguas, entre ellas algo de titánico. Luchaba tanto con la mente como con las manos. Los enanos oían palabras de sombra en la cabeza y caían uno tras otro, hasta que el mono de la expedición, Glibb, vio caer a Brann y la ahuyentó. Huyó hacia Colmen'Regal, y ni un solo insecto se interpuso en su camino." },
        { "Su marido envió viajeros tras ella, con permiso para hacer lo que fuera necesario. Lo que encontraron en la colmena llevaba el título de Suma sacerdotisa de C'Thun. El comandante nunca había oído ese nombre. Dudo que lo olvide." },
      },
    },
    ["nathanos-blightcaller"] = {
      title = "Nathanos Clamañublo",
      text = {
        { "Nathanos Marris fue un señor forestal de Lordaeron, respetado por todos, y el único humano al que se permitió instruirse con los altos elfos de Quel'Thalas. Murió en las Tierras de la Peste. Aún camina por ellas como Nathanos Clamañublo, campeón de la Reina alma en pena, con sus canes añublados, en su antigua granja de la Hacienda Marris." },
        { "Da a los cazadores de la Horda sus encargos más difíciles, contra las bestias de las Tierras de la Peste, los altos elfos del Refugio Quel'Lithien y la Cruzada Escarlata, y los llama imbéciles a todos. El IS:8 envió a cinco agentes a averiguar qué había sido de él. Volvió uno y murió. La palabra que trajo fue Clamañublo. Cuando la Alianza supo la verdad, el alto señor Bolvar Fordragon pidió su cabeza." },
        { side = "Horde", aside = true, sign = "P. F.", "Llama imbécil a todo el mundo. Como historiador, debo dejar constancia de que no siempre se equivoca." },
      },
    },
    ["naxxramas"] = {
      title = "Naxxramas",
      text = {
        { "Naxxramas flota sobre las Tierras de la Peste, una ciudadela aérea de la Plaga y sede de Kel'Thuzad. De ella salieron las fuerzas de una gran invasión de las ciudades de Azeroth, que llevó al Alba Argenta a llamar a todo el que quisiera oponerse a los muertos." },
        { "Cinco años después de la última guerra, el Rey Exánime vuelve a agitarse y Kel'Thuzad reúne ejércitos para otro ataque. Abominaciones, arañas y portadores de peste ocupan la necrópolis junto a cuatro jinetes que fueron campeones de la Luz. Alza la vista al cruzar estas tierras, $gviajero:viajera;. Su comandante tiene una fortaleza que no necesita dominar el camino de abajo." },
      },
    },
    ["naxxramas-tune"] = {
      title = "Naxxramas",
      text = {
        { "Naxxramas, la necrópolis flotante de Kel'Thuzad sobre las Tierras de la Peste, guarda, en algún rincón de sus barrios, más música que cualquier otro lugar que conozca. Sus alas pertenecen a los muertos cosidos, a las arañas y a la peste, y otra más a cuatro jinetes que lucharon por la Luz antes de caer. Sapphiron y Kel'Thuzad aguardan más allá. El Alba Argenta pide a todo el que pueda que entre y destruya allí a la Plaga." },
      },
    },
    ["nefarian"] = {
      title = "Nefarian",
      text = {
        { "Nefarian es hijo de Alamuerte y hermano de Onyxia. Como su hermana, adopta forma humana: lord Víctor Nefarius manda a los orcos de la Cumbre de Roca Negra. El nombre oculta a un dragón cuyos planes van mucho más allá de la fortaleza." },
        { "Desde la Guarida de Alanegra combate a Ragnaros por el control de la montaña y cría dragones cromáticos con ayuda de la Horda Oscura. Los destina a conquistas más amplias. Se han enviado campeones de la Alianza y la Horda contra él, con la promesa de exhibir su cabeza cortada. Quien busque ese premio debe atravesar primero el ejército que ya ha reunido." },
      },
    },
    ["nekrosh"] = {
      title = "Jefe Nek'rosh",
      text = {
        { "Nek'rosh Aplastacráneos dirige lo que queda de los Faucedraco en Los Humedales y es hijo de su padre: Nekros Aplastacráneos fue el orco que mantuvo cautiva a la reina dragón en Grim Batol. Cuando los dragones se liberaron, se vengaron del clan. Nek'rosh pretende vengarse a su vez." },
        { "Está recuperando la fuerza de los Faucedraco en las colinas y ha ordenado construir catapultas para asediar el Puerto de Menethil y cortar el camino a Loch Modan." },
        { "Si eres quien lo detiene, la Liga agradecerá un relato de cómo lo hiciste, $gviajero:viajera;. Breve, si puede ser. Los relatos sobre jefes orcos tienden a alargarse." },
      },
    },
    ["nesingwarys-expedition"] = {
      title = "Expedición de Nesingwary",
      text = {
        { "El campamento de Hemet Decautela ocupa un claro en el norte de Tuercespina, bien provisto de tiendas, trofeos y armeros. El célebre cazador ha venido por panteras, tigres y raptores y para escribir Las verdes colinas de Tuercespina. Ofrece a los cazadores visitantes abundantes oportunidades de demostrar su valía." },
        { "El viento se llevó su manuscrito y sus páginas están dispersas por la jungla. Los capítulos cuentan su cacería, una vez que alguien los pone en orden. Si encuentras una página, guárdala, $gviajero:viajera;. Los autores ya dan bastante trabajo cuando saben dónde está su obra." },
      },
    },
    ["nethergarde-keep"] = {
      title = "Castillo de Nethergarde",
      text = {
        { "Khadgar impulsó la construcción de Nethergarde tras la Segunda Guerra para vigilar el Portal Oscuro. Los reinos de la Alianza lo pagaron con distintos grados de entusiasmo y Dalaran aportó a sus magos. Cuando los orcos reabrieron el Portal, asediaron el castillo. La vigilancia había hecho falta." },
        { "Ahora Nethergarde depende de las caravanas de Ventormenta. Sus magos estudian el Portal y el yermo que lo rodea. Un erudito conserva los ensayos de Khadgar sobre convergencia dimensional. En otra parte de Las Tierras Devastadas, el draenei Kum'isha busca reliquias que puedan abrirle una ruta a casa. Un viajero encontrará varias razones para estudiar un paso que ha traído tanto daño." },
      },
    },
    ["night-elves"] = {
      title = "Los elfos de la noche",
      text = {
        { "Los kaldorei son el pueblo más antiguo que ha conocido la Liga y demasiado educados como para recordárnoslo a menudo. Hace diez mil años, sus Altonato recurrieron al Pozo de la Eternidad hasta que la Legión Ardiente vino a por él. La guerra que siguió rompió el mundo. Después, los supervivientes abandonaron lo arcano, siguieron a los druidas de Malfurion Tempestira y las sacerdotisas de Elune y plantaron un Árbol del Mundo en el Monte Hyjal que les impedía envejecer." },
        { "En la Tercera Guerra, la Legión volvió a Hyjal. Para destruir al demonio Archimonde, los elfos de la noche renunciaron al Árbol y a su inmortalidad. Desde entonces, Fandral Corzocelada ha hecho crecer Teldrassil frente a Costa Oscura y Darnassus está en sus ramas. Si el nuevo Árbol tiene la bendición del antiguo, los druidas no lo dicen en voz alta." },
        { "Ahora envejecen y aprenden lo que significa, $gviajero:viajera;. Tyrande Susurravientos los dirige desde el Templo de la Luna mientras Malfurion está perdido en el Sueño. Si un elfo de la noche parece sopesar cada palabra, recuerda que hasta hace unos años tenía todo el tiempo del mundo para elegirla." },
      },
    },
    ["night-watch"] = {
      title = "La Guardia Nocturna",
      text = {
        { "La comandante Althea Cerranegro dirige La Guardia Nocturna, la milicia que Villa Oscura formó después de que Ventormenta retirase a sus guardias oficiales. Sus vecinos defienden el camino y las puertas frente a los muertos del Cerro del Cuervo, los ferocanis, los ogros y cuanto salga del bosque." },
        { "La mayoría no son soldados y son demasiado pocos. Aun así, han mantenido viva a Villa Oscura. Sarah Ladimor sirve entre ellos. La historia de su padre está en otra parte de este registro." },
      },
    },
    ["nijels-point"] = {
      title = "Punta de Nijel",
      text = {
        { "Punta de Nijel es el campamento de la Alianza en el norte de Desolace, fortificado en las colinas bajo la Sierra Espolón. Sus soldados vigilan los caminos, los clanes centauros y los demonios del Aquelarre Mannoroc. Quien quiera ayudar no encontrará escasez de trabajo." },
        { "Los capitanes han decidido aprovechar las rivalidades de los centauros, aliándose con un clan para aprender a derrotar a los demás. Es una respuesta práctica a una posición difícil, $gviajero:viajera;. La amistad que ayudas a forjar aquí puede comenzar con una petición de matar a los vecinos de otro." },
      },
    },
    ["noble-conspiracy"] = {
      title = "La conspiración de los nobles",
      text = {
        { "Una carta hallada en el cadáver de Edwin VanCleef llevó la investigación sobre los Defias al interior de Ventormenta. Condujo a Bazil Thredd, preso en Las Mazmorras, a un visitante que usaba un nombre falso y, por último, al asesino conocido como Marzon el Filo Silencioso." },
        { "Marzon trabajaba para lord Gregor Lescovar, que transmitía los secretos de la corte a la Hermandad. Las relaciones del noble dificultaban un proceso público. Los aliados del IS:8 organizaron una reunión en los jardines del castillo, donde Lescovar y Marzon murieron." },
        { "El agravio de los albañiles empezó cuando los nobles se negaron a pagar la reconstrucción de Ventormenta. Ahora Lescovar ayudaba a la rebelión que aquella negativa había contribuido a crear. La influencia de VanCleef dentro de la ciudad iba mucho más allá de quienes llevaban máscaras rojas." },
      },
    },
    ["northshire-abbey"] = {
      title = "Abadía de Villanorte",
      text = {
        { "La Abadía de Villanorte se encuentra en un valle del extremo norte de Elwynn. Sus clérigos sirvieron a Ventormenta durante la Primera Guerra, antes de que el reino cayera ante la Horda. Tras la Segunda Guerra, Alonsus Faol ayudó a reconstruir la ciudad y a reorganizar la Hermandad de Villanorte." },
        { "La abadía instruye ahora a los reclutas del reino tanto en las armas como en la fe. Ambas cosas hacen falta muy cerca: los kóbolds ocupan la mina, los lobos recorren el valle y los ladrones Defias se han apoderado de los viñedos." },
      },
    },
    ["northshire-tune"] = {
      title = "Abadía de Villanorte",
      text = {
        { "La Abadía de Villanorte, a la entrada del Bosque de Elwynn, toma prestada una de las piezas de Ventormenta, igual que el Refugio de la Zaga, en las Tierras Altas de Arathi, para quien llega allí. La pieza vuelve a aparecer en algún rincón de Forjaz y en La Basílica Escarlata. La mayoría de los jóvenes aventureros de Ventormenta empiezan aquí. La abadía guarda además una biblioteca, y su encargado, el hermano Paxton, hace meses tomó prestado un libro sobre la resistencia del hierro para copiarlo. El dueño del libro sigue esperándolo." },
      },
    },
    ["northwatch-hold"] = {
      title = "Fuerte del Norte",
      text = {
        { "Los soldados de Theramore ocupan el Fuerte del Norte sobre la Costa del Mercader, al sur de Trinquete. El capitán Thalo'thas Solbrillante acusa a sus artilleros de hundir barcos de su flota. Pide a los aventureros que silencien los cañones y maten al capitán Justamonta." },
        { "Jaina Valiente pactó la paz con Thrall, pero los combates continúan alrededor del fuerte. Quien recorre esta costa entiende por qué, al describir esa paz, hay que registrar tanto el acuerdo de un gobernante como la conducta de sus soldados." },
      },
    },
    ["ogres"] = {
      title = "Los ogros",
      text = {
        { "Los ogros llegaron a este mundo con la Horda desde la misma tierra roja que los orcos. Combatieron en la Segunda Guerra como sus grandes puños. El brujo Gul'dan los mejoró a su manera: usó el Altar de la Tempestad para concederles los poderes de los ogros magos, que aún gobiernan muchos clanes." },
        { "Tras la derrota de la Horda, los clanes ogros se establecieron en lugares salvajes y se quedaron: los Mo'grosh en Loch Modan, los Puño Destrozado en el Bosque del Ocaso, los Aplastacresta en Alterac, los Puño de Roca en Arathi, los Rotapolvo en Tierras Inhóspitas, los Mosh'Ogg en Tuercespina y los Machacamiedo junto al Portal Oscuro. Al otro lado del mar están los Gordunni de Feralas y los Machacaduna de Tanaris. Los Gordok se han instalado en las ruinas de una ciudad élfica de Feralas y coronan a quien mate a su rey." },
        { "No todos los clanes han olvidado la antigua alianza. Los Quebrantarrocas de Marjal Revolcafango luchan con la Horda en Murohelecho y los orcos hablan bien de ellos. Los demás preferirían comerte a hablar." },
      },
    },
    ["onu"] = {
      title = "Onus",
      text = {
        { "Onus, un Anciano del Conocimiento, se encuentra en El Páramo de los Ancianos, al sur de Costa Oscura. Pide a los viajeros que investiguen La Espada del Maestro, donde el Martillo Crepuscular busca entre los restos de un poder caído. Onus cree que aún puede encontrarse allí algo de su fuerza, mucho después de su muerte." },
        { "Proporciona un vial que crea un cuenco de visión y le permite hablar con quien realiza la investigación. Llévalo contigo, $gviajero:viajera;. Un ancestro no necesita caminar hasta la Espada para interesarse por lo que descubre allí el culto." },
      },
    },
    ["onyxia"] = {
      title = "Onyxia",
      text = {
        { "Onyxia, hija de Alamuerte y hermana de Nefarian, pasó años aconsejando al regente de Ventormenta como lady Katrana Prestor. Torció la voluntad del reino y mantuvo a sus tropas en casa mientras los orcos de su hermano amenazaban Crestagrana. El alguacil Windsor la desenmascaró ante la corte. Ella huyó a Marjal Revolcafango." },
        { "Su guarida es otro asunto distinto a su puesto en la corte. Es una dragona antigua y formidable, y los campeones de ambas facciones buscan cómo entrar. Quien ha conocido su nombre humano ha aprendido por qué oponerse a ella. Llegar a la cueva aún deja pendiente enfrentarse a la propia dragona." },
      },
    },
    ["onyxias-lair"] = {
      title = "Guarida de Onyxia",
      text = {
        { "Onyxia tiene su guarida en Ciénaga de Fuego, al sur de Marjal Revolcafango: una gran cueva en los riscos, con los huevos de su progenie dentro y dragonantes negros por todo el pantano cercano. Cruzar el marjal es la parte fácil." },
        { "La entrada está protegida y solo un Amuleto de Pirodraco abre el paso. Tanto la Alianza como la Horda deben seguir un largo camino para fabricarlo: por la Cumbre de Roca Negra, en busca de la sangre del general Drakkisath, que manda a sus dragones. La ruta de la Horda también pasa por el draco Brasaliza, al que hay que engañar con una ilusión, pero es el amuleto lo que permite entrar." },
      },
    },
    ["orcs"] = {
      title = "Los orcos",
      text = {
        { "Los orcos llegaron de Draenor, un mundo de clanes y chamanes, y no lo hicieron por voluntad propia. El brujo Gul'dan y su Consejo de la Sombra, al servicio del demonio Kil'jaeden, les enseñaron magia vil e hicieron beber a sus jefes la sangre de Mannoroth. La Horda que atravesó el Portal Oscuro nació de aquel pacto y quemó Ventormenta antes de que la Alianza la derrotara en la Segunda Guerra." },
        { "Los orcos vencidos fueron encerrados en campos de internamiento y quedaron apáticos al disiparse la furia de los demonios. Thrall, criado como esclavo en Durnholde, los liberó, les devolvió las antiguas costumbres del chamán y los llevó por mar a Kalimdor. En el Monte Hyjal lucharon contra la Legión junto a humanos y elfos de la noche. Cuando Grom Grito Infernal mató a Mannoroth, se rompió la maldición de la sangre." },
        { "Llamaron a su nueva tierra Durotar, por el padre de Thrall, y construyeron Orgrimmar entre sus rocas. Son un pueblo orgulloso que recuerda bien haber sido utilizado, $gviajero:viajera;. Ofrece a un orco respeto y un trato franco, y nunca vuelvas a pedirle que sirva a un amo." },
      },
    },
    ["orgrim-doomhammer"] = {
      title = "Orgrim Martillo Maldito",
      text = {
        { "Orgrim Martillo Maldito era amigo de Durotan en Draenor, un jefe del clan Roca Negra que vio lo que los brujos hacían a su pueblo y, a diferencia de Durotan, esperó su momento. Llegó en la Primera Guerra. Cuando los asesinos de Gul'dan mataron a Durotan, Martillo Maldito mató a Puño Negro, el Jefe de Guerra títere de Gul'dan, y tomó la Horda para sí. Destruyó Ventormenta y desmanteló el Consejo de la Sombra." },
        { "Durante la Segunda Guerra llevó a la Horda hasta las puertas de la capital de Lordaeron, hasta que la deserción de Gul'dan lo obligó a retroceder. Mató a Anduin Lothar en combate singular en Las Estepas Ardientes y aun así perdió la guerra. Capturado en el Portal Oscuro y llevado a Lordaeron, escapó y vivió durante años como un ermitaño." },
        { "Thrall lo encontró allí. El antiguo Jefe de Guerra, amigo de su padre, siguió al joven y cayó al liberar uno de los campos. Thrall tomó su martillo y su armadura negra y se convirtió en Jefe de Guerra. Esta población lleva su nombre, al igual que la capital de la Horda. Lo recuerdan como el Jefe de Guerra que perdió una guerra y aun así se aseguró de que quedara una Horda al terminarla." },
      },
    },
    ["orgrimmar"] = {
      title = "Orgrimmar",
      text = {
        { "Orgrimmar es la capital de la Horda, construida en un gran cañón del norte de Durotar y llamada así por Orgrim Martillo Maldito, el Jefe de Guerra que dirigió a la Horda en la Segunda Guerra y murió luchando por liberarla de los campos. Thrall aún lleva su martillo. Los goblins ayudaron a construirla, y se nota: madera, pinchos y pieles sobre la piedra, caliente como una forja y ruidosa como un campamento de guerra." },
        { "En su corazón se alza el Fuerte Grommash, llamado así por Grom Grito Infernal, que bebió la sangre del demonio Mannoroth y condenó a su pueblo, para después matar a Mannoroth con su propia hacha y liberarlo. En el Valle de los Espíritus, los chamanes y los trols mantienen sus fuegos. En el Circo de las Sombras, según me dicen, hay brujos a los que la Horda tolera más que confía." },
        { "No es una ciudad que reciba bien a los enanos. Pero es una ciudad de verdad y los orcos la levantaron de la nada en unos pocos años, que es más de lo que puede decirse de la mayoría." },
      },
    },
    ["orgrimmar-tune"] = {
      title = "Orgrimmar",
      text = {
        { "Orgrimmar lleva el nombre de Orgrim Martillo Maldito, que dirigió la Horda antes que Thrall, y Thrall levantó la ciudad sobre la tierra roja de Durotar. Su melodía suena en algún lugar entre las murallas. No pretenderé saber dónde, solo que los orcos no son nada tímidos." },
      },
    },
    ["paladins"] = {
      title = "Paladines",
      text = {
        { "Los primeros paladines fueron los Caballeros de la Mano de Plata, fundados durante la Segunda Guerra por el arzobispo Alonsus Faol para llevar la Luz Sagrada al campo de batalla. Los dirigía Uther el Iluminado y lucharon por la Alianza durante la guerra y la larga paz posterior." },
        { "La Tercera Guerra quebró la orden. El príncipe Arthas, paladín él mismo, se volvió contra todo lo que defendía y Uther cayó ante él en Andorhal. Los caballeros supervivientes se dispersaron por Ventormenta, Forjaz y las Tierras de la Peste, donde algunos sirven al Alba Argenta y otros a la idea más severa de la Luz de la Cruzada Escarlata. El mismo juramento ha conducido a sus portadores a compañías amargamente distintas." },
        { client = "classic", "Hoy solo la Alianza instruye paladines, humanos y enanos que juran a la Luz en la Catedral de la Luz o en la Sala Mística de Forjaz." },
        { client = "forever", "Humanos y enanos siguen jurando a la Luz en Ventormenta y Forjaz, mientras algunos Renegados también abrazan ahora la vocación del paladín. La muerte no les ha cerrado la Luz." },
      },
    },
    ["parqual-fintallas"] = {
      title = "Parqual Fintallas",
      text = {
        { "Antes de la peste, Parqual Fintallas era uno de los grandes historiadores de Lordaeron. Ahora es un Renegado y permanece en el Apothecarium de Entrañas, todavía estudiando, aunque sus estudios han cambiado tanto como él." },
        { "Somete a los jóvenes héroes de la Horda a una prueba de conocimientos. Antes de formular su pregunta, los envía al Monasterio Escarlata a buscar Comienzos de la amenaza de los no-muertos, un libro con el que la Cruzada prepara a sus paladines contra los suyos. Espera que lo hayan leído. Sostiene que el conocimiento vale más que la fuerza. Nunca he oído a un historiador defender lo contrario." },
        { "Nunca nos hemos conocido y es poco probable que lo hagamos. Aun así, me dicen que un ejemplar de este registro ha llegado a sus manos, por caminos que prefiero desconocer. Espero que lo encuentre ecuánime. Él sabría mejor que muchos dónde no lo es." },
        { side = "Horde", aside = true, sign = "P. F.", "Me trata con más amabilidad que los libros de la Cruzada." },
      },
    },
    ["peoples-militia"] = {
      title = "La Milicia Popular",
      text = {
        { "Cuando los soldados de Ventormenta no acudieron, los habitantes de Páramos de Poniente reunieron los suyos. La Milicia Popular son unos pocos soldados, muchos granjeros y un paladín que los dirige: Gryan Mantorrecio, que se negó a entregar Páramos de Poniente a la Hermandad." },
        { "Desde la Colina del Centinela patrullan los caminos que pueden, persiguen a gnolls y Defias, y envían exploradores a las Colinas de la Daga y las ruinas de Arroyo de la Luna. Mantorrecio tiene sus propios amigos en los bajos fondos. Por uno de ellos, un pícaro de Villa del Lago, supo quién dirige la Hermandad y dónde se oculta." },
      },
    },
    ["plague-cauldrons"] = {
      title = "Los calderos de peste",
      text = {
        { "Ocho calderos de peste se alzan en las granjas de las Tierras de la Peste, cuatro al oeste y cuatro al este. Los custodian señores de la caldera y los muertos de las granjas cercanas. Sus vapores siguen envenenando una tierra que ya ha perdido a su gente." },
        { "El poder de Kel'Thuzad impide que la Alianza y los Renegados se limiten a apagarlos. En su lugar, los trabajadores del Orvallo y del Baluarte buscan muestras para preparar antídotos. Añadidas a los calderos, esas mezclas alteran sus emisiones para debilitar a la Plaga. Hay que renovar el suministro." },
      },
    },
    ["platinum-discs"] = {
      title = "Los discos de platino",
      text = {
        { "En lo profundo de Uldaman, más allá del guardián de piedra Archaedas, cuatro discos de platino conservan un relato pronunciado por un vigía de piedra. Llama a los titanes los Creadores. Hicieron a los terráneos con la piedra de Azeroth para dar forma a sus profundidades: trabajadores fuertes, incansables y difíciles de herir." },
        { "El vigía dice que su creación falló bajo la tensión. Uno de los resultados conservó la fuerza, pero perdió la razón: los troggs, considerados un fracaso y encerrados bajo tierra. Otro conservó fuerza e inteligencia, pero perdió la piedra. Esos fueron los enanos." },
        { "Entenderás por qué la Liga valora este registro, $gviajero:viajera;. Nos da a los enanos un origen que investigar y convierte a las criaturas que perturban sus excavaciones en parte de la misma pregunta que nuestros antepasados." },
      },
    },
    ["priests"] = {
      title = "Sacerdotes",
      text = {
        { "Los sacerdotes sirven a la fe de su pueblo y cada pueblo tiene una fe distinta. En Ventormenta y Forjaz sirven a la Luz Sagrada. Las sacerdotisas de los elfos de la noche sirven a Elune, la luna, y llevan diez mil años cuidando sus templos." },
        { "En la Horda, los Lanza Negra tienen sus sacerdotes y los Renegados conservan los suyos, cuyas oraciones se inclinan hacia la Sombra con tanta facilidad como hacia la Luz. Cualquiera de ellos puede cerrar una herida, proteger a un amigo, levantar a los caídos o dirigir ese mismo poder contra un enemigo." },
        { client = "forever", "Ahora los gnomos cuentan con sacerdotes entre los suyos, una vocación más para la compañía de Ciudad Manitas." },
        { "Son la compañía más bienvenida en una excavación y la menos apreciada hasta que alguien cae por un pozo, $gviajero:viajera;." },
      },
    },
    ["prince-thunderaan"] = {
      title = "Príncipe Thunderaan",
      text = {
        { "Thunderaan el Hijo del Viento fue un príncipe de los señores elementales del aire, hasta que Ragnaros, el Señor del Fuego, consumió su esencia. Lo que quedó de él fue encerrado en las dos mitades de unas ataduras que llevan los lugartenientes del Señor del Fuego en el Núcleo de Magma." },
        { "En Silithus, un ser extraño que se hace llamar alto señor Demitrian sabe cómo devolverlo. Llévale las dos mitades, el elementium para trabajarlas y la esencia del Señor del Fuego, y el Hijo del Viento renacerá. Lo que surge de ese renacimiento no siente gratitud, pero se puede derrotar. Y de ello, dicen, puede hacerse una hoja de tormentas." },
      },
    },
    ["pyrewood-village"] = {
      title = "Aldea Piroleña",
      text = {
        { "Piroleña es una aldea cercana a la Muralla de Cringrís. De día parece cualquier otra: granjeros, un concejo, un alcalde. De noche, sus habitantes se convierten en ferocanis. El mago Arugal se lo impuso mediante grilletes encantados, y los Renegados que la han estudiado dicen que es la maldición más extraña que han visto." },
        { "Creo que los aldeanos lo saben y viven con ello como pueden. Es el lugar más triste de Argénteos, y en Argénteos no falta competencia." },
      },
    },
    ["queen-azshara"] = {
      title = "Reina Azshara",
      text = {
        { "Esta tierra lleva el nombre de la última reina de los elfos de la noche y no es un cumplido. Azshara era hermosa, talentosa y, al principio, querida por todo su pueblo. Construyó su palacio a orillas del Pozo de la Eternidad, lo llenó de sus sirvientes favoritos, los Altonato, y les encargó averiguar qué podía hacer el poder del Pozo." },
        { "Aprendieron magia y esta los cambió. Azshara se apartó de su pueblo y solo hablaba con sus Altonato. Después, las ondas de sus hechizos llegaron hasta Sargeras y la reina, deslumbrada por su propio poder, aceptó abrirle el paso. Ella y sus Altonato crearon un portal en las profundidades del Pozo y la Legión Ardiente entró por él." },
        { "Al final de la Guerra de los Ancestros, el Pozo se derrumbó y el mar se llevó su palacio, su ciudad y su corte. Los elfos de la noche dicen que la arrastró con ellos. Los nagas que rondan estas orillas fueron sus Altonato y las ruinas de esta costa son lo que quedó sobre el agua." },
      },
    },
    ["queldanil-lodge"] = {
      title = "Avanzada Quel'Danil",
      text = {
        { "La Avanzada Quel'Danil es el hogar de los elfos Vallealto en Tierras del Interior, muy al sur de Quel'Thalas. Sus forestales cazan en las colinas, combaten a los trols del bosque y se relacionan con los Martillo Salvaje. Su alianza con los enanos forma parte de una disputa mucho más antigua entre elfos y Amani." },
        { "Su patria está más allá de las Tierras de la Peste, devastada por la Plaga. Aquí la avanzada sigue siendo un lugar de comunicación, con embajadores que buscan relaciones entre otros pueblos." },
      },
    },
    ["quilboar"] = {
      title = "Los jabaespines",
      text = {
        { "En la Guerra de los Ancestros, un gran semidiós jabalí, Agamaggan, combatió a la Legión Ardiente y cayó. Donde su sangre empapó el suelo de Los Baldíos crecieron espinas colosales. Los jabaespines se instalaron entre ellas: un pueblo de hombres jabalí de púas y colmillos que considera sagrados los espinos y se llama hijo suyo. A las mayores madrigueras espinosas las llaman Rajacieno." },
        { "Las tribus se extendieron por Los Baldíos, Mulgore y Durotar: los Crines de Acero, los Erizapúas, los Rajacieno de su Horado. Combaten a centauros, tauren y orcos con la misma furia y lo hacían mucho antes de que llegara la Horda. Ahora hay noticias peores. En Zahúrda Rajacieno, la tribu Caramuerte ha pactado con la Plaga y un exánime llamado Amnennar el Gélido ocupa el corazón de los espinos de Agamaggan." },
      },
    },
    ["ragefire-chasm"] = {
      title = "Sima Ígnea",
      text = {
        { "Bajo Orgrimmar hay cavernas de fuego y roca fundida, y la Horda construyó su capital sobre ellas sin mirar, al parecer, con demasiado detenimiento. Primero subieron los troggs. Después llegó la Hoja Abrasadora: un culto del Filo Ardiente que se ha instalado en las profundidades, bajo los propios pies del Jefe de Guerra, con un demonio llamado Taragaman el Hambriento entre sus filas." },
        { "Los seguidores de Thrall han enviado a los jóvenes de la Horda a despejarlas. Se me ocurren pocas lecciones mejores sobre los cimientos de una capital." },
      },
    },
    ["ragnaros"] = {
      title = "Ragnaros",
      text = {
        { "Ragnaros, el Señor del Fuego, es un señor elemental que los Hierro Negro invocaron hace siglos con la esperanza de ganar su guerra. Los mantiene a su servicio desde entonces. Su emperador se proclama su sirviente, mientras los elementales de fuego recorren la garganta y las estepas que su llegada devastó." },
        { "Espera entre lava en el Núcleo de Magma hasta que su mayordomo lo invoque. Nefarian le disputa la montaña y los Señores del Agua de Hydraxis mantienen su antigua oposición. Los Hierro Negro viven entre esos poderes, aún sometidos a aquel al que sus antepasados pidieron ayuda." },
      },
    },
    ["ras-frostwhisper"] = {
      title = "Ras Murmuhielo",
      text = {
        { "El exánime que gobierna los salones de Scholomance fue un hombre de Stromgarde llamado Ras Murmuhielo. Cuando la Plaga llegó a Stratholme, entregó su vida en el suelo ensangrentado de la ciudad, voluntariamente y con un propósito: convertirse en uno de los inmortales. Ahora supervisa la escuela de nigromancia." },
        { "Los no-muertos temen la vida como los vivos temen la muerte, dice el magistrado Marduke. Un no-muerto consciente suele destruir todo recuerdo de quien fue. Ras pasó algo por alto. Un recuerdo de sus años mortales seguía en las ruinas de Stromgarde. Armonizado con el suelo donde murió, puede devolverle la mortalidad, al menos el tiempo suficiente para acabar con él de una vez." },
        { "Es raro deshacer a un exánime. Más raro aún que empiece por algo que olvidó tirar." },
      },
    },
    ["ratchet"] = {
      title = "Trinquete",
      text = {
        { "Trinquete es un puerto goblin en la costa de Los Baldíos, una de las poblaciones neutrales del Cártel Bonvapor. Llegan y parten barcos hacia Bahía del Botín y nadie desenvaina contra otro sin lamentarlo. Su dirigente es Gazlowe, el mismo ingeniero goblin que ayudó a Thrall a construir Orgrimmar, y lo administra como un negocio." },
        { "Sus problemas están sobre todo en el mar: los Filibusteros del Mar del Sur atacan sus barcos desde la Costa del Mercader y los artilleros de la Alianza del Fuerte del Norte, al sur, han hundido unos cuantos por error, o eso aseguran." },
      },
    },
    ["raven-hill"] = {
      title = "Cerro del Cuervo",
      text = {
        { "La aldea del Cerro del Cuervo está vacía junto a un cementerio que se ha extendido por toda la ladera. Los esqueletos recorren sus hileras, los necrófagos excavan entre las tumbas y La Guardia Nocturna no puede mantener a los muertos en reposo. El cementerio se ha vuelto más peligroso que las casas abandonadas que lo rodean." },
        { "Morbent Vil, un nigromante, vive en una casa sobre el cementerio. Un leñador cuya familia mató lo quiere muerto. Cerca, un viejo ermitaño ocupa una cabaña que domina las tumbas. Antes iba a Villa Oscura por provisiones, pero hace tiempo que no lo ven allí." },
      },
    },
    ["ravencrest-monument"] = {
      title = "Monumento Cresta Cuervo",
      text = {
        { "Las piernas rotas de una gran estatua se alzan sobre los riscos del sur de Azshara. El lugar se llama Monumento Cresta Cuervo. Los nagas ocupan las ruinas y el resto del coloso yace disperso o bajo el mar. Hasta lo que queda es un hito considerable." },
        { "Lord Kur'talos Cresta Cuervo mandó la resistencia de los elfos de la noche en la Guerra de los Ancestros desde el Torreón Grajo Negro. Su nombre recuerda a quienes se opusieron a Azshara y a la Legión. Dales también lugar en la historia de estas costas, $gviajero:viajera;. La corte de la reina no era todo el pueblo cuyo mundo fue destruido." },
      },
    },
    ["ravenholdt-manor"] = {
      title = "Mansión Ravenholdt",
      text = {
        { "La Mansión Ravenholdt está oculta en las colinas sobre Trabalomas. Desde ella, lord Jorach Ravenholdt dirige la Liga de Asesinos e instruye a los ladrones y asesinos que la casa elige. Los posibles alumnos reciben invitaciones. Presentar una solicitud sería una forma poco habitual de anunciar tus talentos aquí." },
        { "La Liga se opone desde hace mucho al Sindicato, cuyos miembros considera aficionados. Robarles sus emblemas es una parte útil de la disputa: un miembro del Sindicato que pierde el suyo puede esperar el castigo de los propios compañeros." },
      },
    },
    ["razelikh-the-defiler"] = {
      title = "Razelikh el Envilecido",
      text = {
        { "Razelikh el Envilecido es un demonio que gobierna desde una guarida en lo alto de la mayor montaña de Las Tierras Devastadas. Tiene tres lugartenientes: Grol el Destructor, lady Sevine y el archimago Allistarj. Capturaron a los guerreros del héroe caído de la Horda y ataron sus espíritus a piedras de tormento." },
        { "El héroe caído ha enviado viajeros a liberar a sus hombres, matar a los tres lugartenientes y reunir sus amuletos. Con el amuleto completo deben subir al altar de Razelikh e invocar al demonio. Su cuerno, dice, demostrará que aún existen héroes en este mundo desgarrado por la guerra." },
      },
    },
    ["razor-hill"] = {
      title = "Cerrotajo",
      text = {
        { "Cerrotajo es una población de guarnición en el camino del Valle de los Retos a Orgrimmar: un cuartel, una posada, una torre de vigilancia y una empalizada de troncos afilados sobre una colina que domina el mar. Su comandante, Gar'Thok, la defiende en nombre del Jefe de Guerra y dedica casi todos sus días a rechazar cuanto sale de los cañones o llega de la costa." },
        { "Al sur está el Fuerte de Tiragarde, donde los hombres de Kul Tiras aún se aferran a la orilla de Durotar. Los restos de la flota de su almirante se pudren frente a la playa. Los brutos de Cerrotajo vigilan ambas cosas de cerca." },
      },
    },
    ["razorfen-downs"] = {
      title = "Zahúrda Rajacieno",
      text = {
        { "Al sur del Horado hay otra de las madrigueras espinosas de Agamaggan, Zahúrda Rajacieno, donde ha ocurrido algo terrible. Los jabaespines Caramuerte que la ocupan han pactado con la Plaga. Ahora la gobierna un exánime, Amnennar el Gélido. La Plaga mantiene un embajador entre los jabaespines y los muertos caminan entre las espinas de la tumba del dios jabalí." },
        { "Nadie sabe decirme cómo han llegado tan lejos en Kalimdor los sirvientes del Rey Exánime. Que lo hayan hecho y estén estableciéndose allí basta para preocupar a todos los pueblos de Los Baldíos." },
      },
    },
    ["razorfen-downs-tune"] = {
      title = "Zahúrda Rajacieno",
      text = {
        { "La Zahúrda Rajacieno, el túmulo de los jabaespines al sur de Los Baldíos, tiene su propia melodía. Los jabaespines de allí se han unido a la Plaga, y un liche llamado Amnennar el Gélido los gobierna ahora. Responde ante Ner'zhul. Nunca he encontrado una buena razón para bajar allí, y la he buscado." },
      },
    },
    ["razorfen-kraul"] = {
      title = "Horado Rajacieno",
      text = {
        { "Charlga Filonavaja gobierna Horado Rajacieno, un gran laberinto de zarzas y túneles del sur de Los Baldíos. Los guerreros de esta chamán jabaespín guardan al jabalí Agathelos en sus profundidades. La madriguera es un bastión en el corazón de su pueblo." },
        { "El diario de Henrig Soliceja recoge su cautiverio allí junto al druida herido Heralath. Heralath le pidió que avisara a Díscolo Falfildel, en Thalanaar, del creciente poder de Charlga. Soliceja llegó al Gran Elevador, pero su cuerpo yace allí con el diario. Falfildel pide a otros que terminen su labor." },
      },
    },
    ["red-dragonflight"] = {
      title = "El Vuelo Rojo",
      text = {
        { "Alexstrasza recibe el nombre de Protectora de la Vida, reina de los dragones rojos y uno de los poderes más antiguos del mundo. Durante la Segunda Guerra, los Faucedraco la mantuvieron cautiva en Grim Batol y obligaron a sus hijos a servirlos. Desde entonces, el Vuelo ha sido liberado." },
        { "Los dragonantes rojos aún protegen los accesos a Grim Batol. Tratan a los intrusos como enemigos, sea cual sea el motivo que estos crean tener para estar allí. Mantén la distancia, $gviajero:viajera;. Saber lo que les ocurrió aquí no hace que un intruso sea bienvenido." },
      },
    },
    ["red-rocks"] = {
      title = "Roca Roja",
      text = {
        { "Al este de Cima del Trueno, entre grandes piedras rojas, se encuentra el cementerio sagrado de los tauren. Solo los más valientes descansan en Roca Roja: los guerreros que ayudaron a fundar y defender Cima del Trueno, y quienes dieron la vida por sus tribus y jefes. Dicen que los espíritus ancestrales aún caminan allí." },
        { "Los jóvenes vienen para el último de los ritos, el Rito de la Sabiduría, y reciben la bendición de esos antepasados. Últimamente, los jabaespines han estado excavando en las tumbas y el anciano sabio que las cuida ya no está para combatirlos. Si quieres ganarte la amistad de todos los tauren de Mulgore, no hay forma más rápida." },
      },
    },
    ["redridge-mountains"] = {
      title = "Montañas Crestagrana",
      text = {
        { "Crestagrana debe su nombre a la piedra rojiza bajo sus pinares. El Lago Sempiterno se extiende entre las colinas, con Villa del Lago en su orilla occidental. La madera y la pesca sostienen la comarca, pero los ejércitos la han atravesado con demasiada frecuencia: los orcos llegaron en la Primera Guerra y los Roca Negra han vuelto." },
        { "Ahora ocupan el Fuerte de Petravista y los valles que hay más allá. Los gnolls recorren los cañones, un brujo ocupa las colinas orientales y las crías de dragón negro anidan en las cuevas altas. Villa del Lago ha pedido soldados a Ventormenta una y otra vez." },
      },
    },
    ["refuge-pointe"] = {
      title = "Refugio de la Zaga",
      text = {
        { "El Refugio de la Zaga es el campamento de la Alianza en el centro de las Tierras Altas de Arathi. Lo ocupan los supervivientes de Stromgarde y los soldados que han venido a ayudarlos: unas tiendas, un establo, un maestro de vuelo y mucha determinación. Desde aquí combaten al Sindicato en las ruinas de su ciudad y a los Secacorteza en las colinas. También desde aquí cabalga la Liga de Arathor hacia la cuenca del sur." },
        { "La gente de Stromgarde es orgullosa y su reino ha quedado reducido a este campamento. No han dejado de llamarlo reino." },
      },
    },
    ["regency-of-stormwind"] = {
      title = "La regencia de Ventormenta",
      text = {
        { "El rey Varian Wrynn ha desaparecido. Era hijo del rey Llane, asesinado durante la Primera Guerra, y creció entre los refugiados de Ventormenta en Lordaeron. En la ciudad que gobernaba aún se desconoce su destino." },
        { "Su joven hijo Anduin lleva la corona. El alto señor Bolvar Fordragon gobierna el reino en su nombre, dirige sus fuerzas y protege al muchacho. La consejera real, lady Katrana Prestor, permanece al lado de Bolvar." },
        { "El ejército de Ventormenta apenas da abasto y las peticiones llegan de todas partes." },
      },
    },
    ["remtravels-excavation"] = {
      title = "Excavación de Tripirrem",
      text = {
        { "Cuando los gólems invadieron la excavación de Tripirrem en el sur de Costa Oscura, su ayudante huyó a Auberdine en busca de ayuda. El célebre prospector siguió trabajando. Hollee conserva la admiración por sus descubrimientos junto al deseo desesperado de que, de vez en cuando, se dé cuenta de lo que ocurre a su alrededor." },
        { "Su misterioso fósil ha despertado el interés del arqueólogo jefe Mostachogris. Su parecido con otro hallazgo lleva la investigación hasta Gargavino, en el Puerto de Menethil. Tripirrem ha encontrado algo que merece estudiarse. Mantenerlo vivo el tiempo suficiente para terminar de hacerlo se ha convertido en una segunda expedición por derecho propio." },
      },
    },
    ["rend-blackhand"] = {
      title = "Jefe de Guerra Desgarro Puño Negro",
      text = {
        { "Desgarro es hijo de Puño Negro el Destructor, primer Jefe de Guerra de la Horda. Él y su hermano Maim dirigieron a los Sonrisa Negra bajo Orgrim Martillo Maldito, asesino de su padre, mientras buscaban venganza y el puesto que Puño Negro había perdido." },
        { "Ahora Desgarro reclama el título de Jefe de Guerra desde la Cumbre de Roca Negra, donde sirve a Nefarian y manda a sus orcos. Thrall rechaza su pretensión y envía campeones a matarlo, con los conocimientos de Eitrigg sobre los Roca Negra para orientar la respuesta. Oirás dos reivindicaciones de la Horda, pero solo uno de estos dirigentes responde ante un dragón negro." },
      },
    },
    ["revantusk-village"] = {
      title = "Poblado Sañadiente",
      text = {
        { "Los Sañadiente ocupan una aldea en la costa oriental de Tierras del Interior. Son trols del bosque aliados con la Horda, una tribu pequeña acosada por vecinos más grandes. Los Vilrama capturaron a su anciano para sacrificarlo y la amistad de los Martillo Salvaje con los altos elfos les ofrece otro conflicto cercano." },
        { "Los Amani y los elfos de Quel'Thalas son enemigos desde que los elfos se asentaron en estas tierras. Aquella antigua hostilidad sigue viva entre los Sañadiente." },
      },
    },
    ["rexxar"] = {
      title = "Rexxar",
      text = {
        { "El gigante que recorre el camino de Desolace con un oso a su lado es Rexxar, campeón de la Horda. Es mitad orco y mitad ogro, de los Mok'Nathal, y no pertenece a ninguna población. Misha, su osa, va adonde él va." },
        { "Llegó a Durotar en sus primeros días, cuando la tierra era nueva y la Horda aún buscaba su sitio. Thrall le confió trabajos que nadie más podía hacer. Cuando el almirante Daelin Valiente desembarcó su flota para terminar la vieja guerra, Rexxar estuvo en el centro de los combates que acabaron con ella, junto a Thrall y Cairne y, así fueron las cosas, con el permiso de Jaina Valiente. La Horda le debe buena parte de su hogar." },
        { "No se quedó a disfrutarlo. Prefiere lo salvaje a las ciudades que ayudó a defender y sigue los senderos entre la Sierra Espolón y Feralas. El Jefe de Guerra aún envía viajeros a buscarlo cuando el trabajo es difícil. Él te verá antes de que tú lo veas, $gviajero:viajera;. Misha te verá primero." },
      },
    },
    ["rockjaw-troggs"] = {
      title = "Los troggs",
      text = {
        { "Los registros de los titanes de Uldaman describen a los troggs como un resultado fallido de la creación de los terráneos. Quedaron sellados bajo tierra hasta que las excavaciones enanas abrieron sus salones. Buscar nuestros comienzos liberó a criaturas cuyos orígenes estaban incómodamente cerca de ellos." },
        { "Los Mentueso ocupan las canteras y cuevas de Dun Morogh, los Rompecantos los valles de Loch Modan y los Grutacanto la propia Uldaman. Los troggs también invadieron Gnomeregan. Otros han aparecido en Costa Oscura y bajo Orgrimmar, aunque su ruta a través del mar sigue siendo incierta." },
        { "Los montaraces piden ayuda para defender caminos y asentamientos, y los gnomos aún los combaten en su capital. Quien lleve este registro encontrará a los estudiosos de Forjaz interesados en la historia de los troggs. Quienes vigilan una mina tienen una preocupación más inmediata: mantenerlos fuera." },
      },
    },
    ["rogues"] = {
      title = "Pícaros",
      text = {
        { "Toda ciudad tiene sus oficios silenciosos y los pícaros los practican todos: la cerradura que se abre sin llave, la bolsa que cambia de manos sin que su dueño lo note, la hoja por la espalda. Algunos sirven a una corona, como el IS:8 de Ventormenta. Otros solo sirven al dinero, como los Defias de Páramos de Poniente y el Sindicato de Alterac." },
        { "Entre ambos están los asesinos de Ravenholdt, en las colinas de Alterac sobre Trabalomas, de quienes se dice que eligen contratos y alumnos con el mismo cuidado. Por sus puertas pasan pícaros de todos los pueblos y pocos hablan de lo que aprendieron allí." },
        { "Un pícaro lucha con venenos, manos rápidas y sorpresa, y se marcha cuando cambian las probabilidades. La Liga ha contratado a unos cuantos para recuperar lo que otros ya le habían quitado, $gviajero:viajera;. No es el renglón más honroso de sus cuentas, pero sí uno de los más largos." },
      },
    },
    ["royal-apothecary-society"] = {
      title = "La Sociedad Real de Boticarios",
      text = {
        { "La Sociedad Real de Boticarios del maestro Faranell sirve a los Renegados con alquimia, venenos y la promesa de una nueva peste. Sylvanas ha encargado a sus miembros encontrar una enfermedad capaz de destruir la Plaga del Rey Exánime. Sus preparativos van mucho más allá de los laboratorios de Entrañas." },
        { "En Rémol y Trabalomas, los viajeros recogen sangre y otros ingredientes para experimentar con bestias, múrlocs y prisioneros. El boticario Lydon contempla los campos floridos de Trabalomas y ansía que su trabajo les traiga la muerte. Sea cual sea el enemigo declarado de la Sociedad, sus ambiciones incluyen claramente a los vivos." },
        { "Los Renegados saben mejor que casi nadie lo que significa que una peste te arrebate el hogar. Ese conocimiento no ha vuelto a todos sus boticarios reacios a infligir la misma desgracia a otros." },
      },
    },
    ["ruins-of-ahn-qiraj-tune"] = {
      title = "Ruinas de Ahn'Qiraj",
      text = {
        { "Las Ruinas de Ahn'Qiraj, tras el Muro del Escarabajo en Silithus, comparten cuatro piezas con las salas exteriores del templo. Hace mil años, los elfos de la noche y los dragones encerraron a los qiraji tras ese muro. El muro se ha vuelto a abrir, y lo que salió por él no se había suavizado con los siglos." },
      },
    },
    ["ruins-of-ahnqiraj"] = {
      title = "Ruinas de Ahn'Qiraj",
      text = {
        { "Cuando sonó el gong y se abrió el Muro del Escarabajo, los ejércitos de la Alianza y la Horda entraron en la ciudad exterior de Ahn'Qiraj, las Ruinas: templos derruidos y arena, repletos de insectos. Manda aquí el general qiraji Rajaxx, el mismo que mató a Valstann Corzocelada hace mil años. En el corazón de las Ruinas monta guardia el gran guerrero de piedra Osirio el Sinmarcas." },
        { "El Círculo Cenarion envió a sus propios campeones y, para ellos, la batalla de la ciudad fue el final de una guerra muy antigua." },
      },
    },
    ["ruins-of-eldarath"] = {
      title = "Ruinas de Eldarath",
      text = {
        { "Las ruinas Altonato de Eldarath se aferran a los riscos orientales de Azshara, sobre la Bahía de la Tempestad. Buena parte de la ciudad cayó al mar durante el Gran Cataclismo. Sus habitantes habían grabado sus conocimientos arcanos en runas y tablillas de lugares públicos. Algunas aún pueden leerse entre la piedra rota." },
        { "Los nagas del señor de la guerra Krellian dominan ahora las ruinas desde el Templo de Zin-Malor. Los elfos de la noche evitan el lugar, pero la Liga de Expedicionarios quiere calcos de las inscripciones. Si consigues pasar entre los nagas, esas tablillas quizá conserven algo que el mar aún no se ha llevado, $gviajero:viajera;." },
      },
    },
    ["ruins-of-keltheril"] = {
      title = "Las Ruinas de Kel'Theril",
      text = {
        { "Junto al helado Lago Kel'Theril están las ruinas de una población Altonato, cuyos habitantes siguen allí como fantasmas. Hace mucho robaron una reliquia sagrada de su templo, el Cristal de Zin-Malor, para absorber su poder. El ritual salió mal. El cristal se hizo añicos en una gran explosión y sus fragmentos quedaron bajo el hielo del lago." },
        { "Los Altonato fueron condenados a permanecer donde lo habían hecho, buscando los fragmentos para siempre. Cuando alguien los reunió por fin y reconstruyó el cristal, uno de los fantasmas habló: se arrepentía y sabía que nada podía cambiar el pasado, pero estaba en paz. El templo del cristal está en ruinas, así que lo llevaron al archidruida de Darnassus." },
      },
    },
    ["ruins-of-lordaeron"] = {
      title = "Las Ruinas de Lordaeron",
      text = {
        { "Sobre Entrañas, las calles de la capital de Lordaeron están menos vacías de lo que parecen desde la puerta. La Plaga aún recorre en gran número las ruinas más profundas. Una niebla impía ha invadido las calles y el viejo cementerio, provocada, según creen los guardias de la Muerte, por un nigromante llamado Rath'mael en el Mirador de Lordamere. Los Renegados envían cuantas fuerzas pueden y sus pérdidas son tales que un paladín del Barrio Real pide a los viajeros los miembros intactos que dejan los muertos." },
        { "No todos los que suben lo hacen por la Reina alma en pena. Edward Tejecorazón iba al cementerio cada semana en busca del hijo que perdió cuando Arthas arrasó la ciudad, hasta que una semana no volvió. Y entre las abominaciones cosidas allí arriba hay una a la que los boticarios llaman el Barón, conocida por ellos con otro nombre más antiguo: Othmar Garithos, el señor que se alió con Sylvanas contra la Plaga y no sobrevivió al acuerdo. El capitán Truman, que sirvió a sus órdenes, aún espera en las ruinas el regreso de su comandante." },
        { side = "Horde", aside = true, sign = "P. F.", "De todo lo que cuenta esta página, siempre vuelvo al paseo semanal de Edward Tejecorazón." },
      },
    },
    ["ruins-of-thaurissan"] = {
      title = "Las Ruinas de Thaurissan",
      text = {
        { "Estas son las ruinas de la ciudad de Thaurissan, capital del clan Hierro Negro tras abandonar Forjaz hace siglos, cuando Las Estepas Ardientes eran verdes. Cuando sus ejércitos fueron destruidos en Forjaz y Grim Batol, el hechicero y señor feudal Thaurissan y siete de sus mayores enanos descendieron para invocar a los poderes que dormían bajo el mundo y cambiar el rumbo de la guerra." },
        { "Respondió Ragnaros, el Señor del Fuego. La montaña estalló. La ciudad fue destruida, los valles ardieron y los Hierro Negro supervivientes se convirtieron en esclavos del Señor del Fuego. Las reliquias de la ciudad aún recuerdan: quienes las tocan ven a ocho enanos en un ritual y después a uno solo, arrodillado entre siete cadáveres ante una columna de llamas. He contado esta historia en el Alto Trono más veces de las que puedo recordar. Esas reliquias explican muchas cosas que hasta ahora solo había conjeturado. Un goblin de Vigilia de Morgan, Maxwort, te dirá que los Siete eran enanos de grandes conocimientos y que el conocimiento da riqueza. Goblins." },
      },
    },
    ["rustmaul-dig-site"] = {
      title = "Excavación Pico Roto",
      text = {
        { "Al borde del Desierto de Sal, unos enanos establecieron la Excavación Pico Roto en busca de lo que hubiera bajo la sal. La Horda envió una partida de guerra a expulsarlos. En mitad del combate se abrió el suelo y salieron insectos de una cueva del yacimiento: silítidos, más de los que ninguno había visto jamás, que casi los mataron a todos." },
        { "Los enanos se han ido. Los insectos no. Los cazadores de la Horda que sobrevivieron consideran ahora a los silítidos un peligro mucho mayor que cualquier equipo de excavación. Después de leer sus informes, yo también. Nadie me ha dicho qué buscaban los enanos. No estoy segura de que lo encontraran." },
      },
    },
    ["sandfury-trolls"] = {
      title = "Los trols Furiarena",
      text = {
        { "Los Furiarena son los trols del desierto de Tanaris, altos, delgados y duros como la arena en la que viven. Su capital es Zul'Farrak, al oeste del desierto, y defienden lo que queda de sus tierras contra todos: Alianza, Horda, goblins, ogros, bandidos y, sobre todo, los insectos del sur." },
        { "Son un pueblo antiguo con guerras antiguas a sus espaldas. Su mártir Theka murió luchando contra los guerreros insectoides que atacaron su ciudad. Los Furiarena dicen que sus asesinos fueron condenados a vivir como escarabajos en su santuario. Adoran a la gran hidra Gahz'rilla en su laguna sagrada y resucitan a sus muertos para que sigan trabajando cuando caen." },
      },
    },
    ["sargeras-and-the-betrayal"] = {
      title = "Sargeras y la traición",
      text = {
        { "Sargeras fue el campeón de los titanes. Cuando los demonios empezaron a salir del Vacío Abisal y entrar en los mundos que los titanes habían ordenado, el Panteón eligió a su mayor guerrero, un noble gigante de bronce fundido, para cazarlos. Lo hizo durante eras incontables. Derrotó a los eredar, hechiceros que convertían mundos enteros en demonios, y a los nathrezim, que enfrentaban a las naciones entre sí, y los encerró a ambos." },
        { "Su corrupción permaneció con él. Cayó en una desesperación sombría y después en la creencia de que el propio orden era una locura y el caos la única verdad. Al final odió a los propios titanes, a quienes culpó del fracaso de la creación. Su piel de bronce se abrió sobre un horno de furia. Rompió las prisiones que había construido y liberó a los demonios, que se inclinaron ante él." },
        { "Eligió dos lugartenientes entre los eredar: Kil'jaeden el Embaucador, para encontrar y reclutar a las razas más oscuras, y Archimonde el Profanador, para dirigir al ejército. Lo llamó la Legión Ardiente. Cuántos mundos ha quemado desde entonces, dice el libro de nuestra biblioteca, aún no está claro. Sabemos de uno que no ha conseguido terminar." },
      },
    },
    ["satyrs"] = {
      title = "Los sátiros",
      text = {
        { "Xavius ayudó a abrir la corte de la reina Azshara a la Legión Ardiente. Cuando falló a Sargeras, el señor demoníaco lo rehízo con cuernos, pezuñas y garras. El primer sátiro ofreció entonces esa transformación a otros elfos sedientos de poder y la maldición se extendió entre sus seguidores." },
        { "Sus campamentos permanecen en las antiguas tierras de los elfos de la noche, entre los bosques de Vallefresno, Frondavil y Azshara. A su alrededor, el agua se contamina, los árboles enferman y las bestias se deforman. Los elfos que intentan sanar esos bosques combaten una corrupción que arraigó primero entre su propia gente." },
        { "Diez mil años es mucho tiempo para cuidar un bosque, $gviajero:viajera;. Es un periodo amargo para descubrir a sus viejos traidores aún trabajando dentro de él." },
      },
    },
    ["scarlet-crusade"] = {
      title = "La Cruzada Escarlata",
      text = {
        { "Cuando el príncipe Arthas asesinó a su padre y Lordaeron cayó ante la peste, los paladines supervivientes de la Mano de Plata reunieron lo que pudieron y juraron quemar a los muertos hasta expulsarlos de la tierra. Tres fundaron la Cruzada: la alta general Abbendis, el alto inquisidor Isillien y el alto señor Mograine, el Crematoria. Según quienes estaban allí, al principio fue una orden noble. Se convirtieron en la Cruzada Escarlata y desde entonces no han dejado de quemar: muertos y vivos que los miran mal." },
        { "No confían en nadie. Cualquier extraño puede portar la peste, cualquier elfo o enano ser espía y los Renegados son sencillamente el enemigo. Desde el Monasterio de Tirisfal, Vega del Amparo y Mano de Tyr libran una guerra que nadie más está invitado a ganar. Su gran cruzado, Saidan Dathrohan, los gobierna desde Stratholme y su gran inquisidor, Isillien, desde Vega del Amparo." },
        { "La Cruzada combate a la Plaga, pero la corrupción de sus propias filas da otro motivo para desconfiar. Pregunta en el Monasterio por el alto señor Mograine y su espada, la Crematoria, y fíjate en quién calla. Y pregunta al Alba Argenta qué encontró al mirar de cerca al propio Gran Cruzado." },
      },
    },
    ["scarlet-enclave-tune"] = {
      title = "El Enclave Escarlata",
      text = {
        { "El Enclave Escarlata de la Cruzada comparte su música con Nuevo Avalon, en las Tierras de la Peste del Este. La Mano de Tyr, Nuevo Avalon y el Sagrario Arcano están ahora todos dentro, y a la Cruzada nunca le han faltado murallas." },
        { client = "classic", "Seis de sus piezas son prestadas de los lugares ocultos, y cinco son propias. En algún rincón de la capilla del Enclave esperan tres piezas propias más, junto a otras tres prestadas de los lugares ocultos." },
      },
    },
    ["scarlet-monastery"] = {
      title = "El Monasterio Escarlata",
      text = {
        { "La Cruzada Escarlata ocupa un monasterio sobre una colina del norte de Tirisfal, por encima del mar. Sus muros encierran una biblioteca, una armería, un cementerio y una catedral. Allí se instruyen caballeros, sacerdotes e inquisidores para una guerra que va mucho más allá de la Plaga." },
        { "Los Renegados también son enemigos, al igual que cualquier viajero que despierte las sospechas de la Cruzada. La alta inquisidora Melenablanca y el comandante Escarlata Mograine dominan la catedral, mientras se envía a campeones Renegados contra la fortaleza. El monasterio presenta el aspecto exterior de una casa de la Luz. Acércate con más cautela de la que esa descripción podría sugerir." },
        { side = "Horde", aside = true, sign = "P. F.", "Tras esos muros hay una biblioteca y en ella un libro con el que enseñan a sus paladines a destruir a los míos. Envío héroes a buscarlo y les pido que lo lean antes de traerlo." },
      },
    },
    ["scarlet-monastery-tune"] = {
      title = "Monasterio Escarlata",
      text = {
        { "En algún rincón del Monasterio Escarlata suenan dos piezas que también suenan en Forjaz, las mismas dos que lleva Yunquemar. No sabría explicar por qué un monasterio de la Cruzada Escarlata toma prestada la música de mi propia ciudad, y prefiero no preguntárselo a la Alta inquisidora Melenablanca. La Cruzada envía a sus agentes desde allí, hasta el Camposanto, en los Claros de Tirisfal." },
      },
    },
    ["scholomance"] = {
      title = "Scholomance",
      text = {
        { "Bajo Castel Darrow está Scholomance, la escuela del Culto de los Malditos, donde se instruye a los nigromantes y se estudian las artes oscuras de la Plaga. Su rector es el maestro oscuro Gandling. Sus salas están llenas de alumnos, profesores y de aquello con lo que practican. Su puerta está cerrada para quien no tenga llave." },
        { "Los Barov también están allí, o lo que queda de ellos: el señor y su esposa, resucitados por los amos a los que vendieron su hogar. Tanto la Alianza como los Renegados quieren entrar en Scholomance. Ambos han descubierto que el camino atraviesa mucha historia funesta." },
      },
    },
    ["scourge"] = {
      title = "La Plaga",
      text = {
        { "La Plaga es el ejército del Rey Exánime, un poder sentado en un trono de hielo en Rasganorte que habla en las mentes de los muertos. Llegó a Lordaeron como una peste, llevada en el grano por un culto de adoradores del Rey Exánime. Todo el que comió y murió se alzó para servirlo. El propio príncipe del reino, Arthas, terminó el trabajo y después volvió a Rasganorte, donde reclamó el Trono Helado." },
        { "Dejó las Tierras de la Peste: un reino de muertos con necrófagos en los campos, abominaciones cosidas con cadáveres y calderos de peste envenenando la tierra. Stratholme es suya bajo el barón Osahendido, al igual que Scholomance y las granjas de medio norte. Ahora una ciudadela negra flota sobre Tierras de la Peste del Este: Naxxramas, cuyo amo es el exánime Kel'Thuzad." },
        { "Los muertos no se cansan ni se detienen. El Alba Argenta, la Cruzada Escarlata y los Renegados los combaten pese a la desconfianza mutua. En la Capilla de la Esperanza de la Luz, el Alba y la Cruzada han acordado cooperar contra Naxxramas." },
      },
    },
    ["scythe-of-elune"] = {
      title = "La Guadaña de Elune",
      text = {
        { "Los ferocanis del Bosque del Ocaso no vinieron de Arugal, o no solo de él. La otra mitad de la historia empieza en Vallefresno, con una sacerdotisa de Elune llamada Velinde Cantoestelar. Rezó por un medio de vengar a sus camaradas caídos contra los demonios de Frondavil y lo recibió: la Guadaña de Elune, una rama retorcida y nudosa que quizá sea más antigua que los propios elfos de la noche." },
        { "Su diario dice que sostenerla debilitaba las paredes del mundo. A través de ella vio a los ferocanis librando su propia guerra, aprendió a hablar con ellos sin palabras y trajo una treintena a este mundo para luchar a su lado. Llegaron más. Después desaparecieron manadas, y su número siguió creciendo incluso cuando dejó de llamarlos, como si la Guadaña ya no la necesitase. Según el diario, viajó al este, cruzando el mar, en busca de un mago del Kirin Tor llamado Arugal que, según los rumores, había hecho lo mismo. Esa es la última entrada." },
        { "La Guadaña apareció en la mina al sur de Villa Oscura que los lugareños llaman Condena de Roland. Un Defias apodado Nervioso la sacó de un montón de escombros y los ferocanis brotaron de las paredes. Volvió a perderla al huir. Los registros no dicen dónde está ahora. Un regalo de una diosa, en algún lugar oscuro de una mina del Bosque del Ocaso, quizá aún abriendo puertas. Preferiría que la encontrara una sacerdotisa antes que un prospector." },
      },
    },
    ["searing-gorge"] = {
      title = "La Garganta de Fuego",
      text = {
        { "La Garganta de Fuego está al norte de la Montaña Roca Negra, una cuenca de cenizas y brasas rodeada de riscos. Las rutas de Loch Modan y Tierras Inhóspitas llegan hasta ella. Fue una comarca verde, quemada cuando Thaurissan invocó a Ragnaros. Todavía sale humo de lo que dejó el Señor del Fuego." },
        { "Los enanos Hierro Negro explotan la gran fosa llamada La Caldera con esclavos y gólems. Los elementales de fuego cruzan la escoria y el Martillo Crepuscular mantiene un altar en las colinas del noroeste. Sobre la fosa, unos Hierro Negro renegados tienen su propio campamento. Desde los riscos puede verse gran parte de la comarca, aunque pocas vistas resultan reconfortantes, $gviajero:viajera;." },
      },
    },
    ["senjin-village"] = {
      title = "Poblado Sen'jin",
      text = {
        { "El Poblado Sen'jin es el hogar de los trols Lanza Negra en la costa de Durotar, un asentamiento de cabañas y atalayas frente al estrecho de las Islas del Eco. Lleva el nombre de Sen'jin, antiguo médico brujo y jefe de los Lanza Negra, que recibió a Thrall cuando la flota orca recaló en sus islas y murió a manos de los sirvientes de una bruja del mar en los combates posteriores." },
        { "Ahora su hijo Vol'jin dirige la tribu. Los trols pensaban vivir en las Islas del Eco, pero uno de sus propios médicos brujos enloqueció allí. Desde entonces, los Lanza Negra se apiñan en esta franja costera y contemplan, al otro lado del agua, el hogar que perdieron." },
      },
    },
    ["sentinel-hill"] = {
      title = "Colina del Centinela",
      text = {
        { "La Colina del Centinela es una torre de piedra sobre una elevación en mitad de Páramos de Poniente y el último lugar de la provincia donde la ley aún significa algo. La ocupa La Milicia Popular: un puñado de soldados y muchos antiguos granjeros, bajo el paladín Gryan Mantorrecio, que prefieren luchar por su tierra antes que abandonarla." },
        { "No hay mucho aquí: la torre, unas tiendas, un establo, una posada y una buena vista de lo mal que van las cosas. Pero todo viajero que quiera ayudar a Páramos de Poniente viene primero aquí, y a la Milicia le sobra trabajo y le faltan manos." },
      },
    },
    ["sentinels"] = {
      title = "Las centinelas",
      text = {
        { "Cuando los druidas se durmieron en el Sueño Esmeralda, alguien debía cuidar los bosques. Tyrande Susurravientos, suma sacerdotisa de Elune, reunió a sus hermanas en un ejército de mujeres guerreras y las llamó centinelas. Pidió a Malfurion que no la abandonara por el Sueño. Él se marchó de todos modos y ella mantuvo la vigilancia." },
        { "La mantuvieron durante diez mil años, patrullando Vallefresno de noche mientras dormían los druidas, con los hijos de Cenarius, los guardianes de la arboleda, y sus tímidas hijas, las dríades, a quienes pedir ayuda. Tyrande nunca dejó de temer el regreso de la Legión. Al final tuvo razón." },
        { "Los druidas están despiertos y las centinelas no se han retirado. Las encontrarás en cada puesto de los elfos de la noche, desde Teldrassil hasta Plumaluna, bajo su general Shandris Plumaluna. Si una te mira como si llevara mucho tiempo de guardia, bien podría llevarlo, $gviajero:viajera;." },
      },
    },
    ["shadow-council"] = {
      title = "El Consejo de la Sombra",
      text = {
        { "La antigua Horda nunca estuvo del todo gobernada por sus jefes de guerra. Detrás estaba el Consejo de la Sombra, un círculo secreto que el demonio Kil'jaeden ayudó a Gul'dan a fundar en Draenor para dirigir a los clanes y extender entre ellos la magia de los brujos. El Consejo invocó a Mannoroth para que los jefes bebieran su sangre, puso a Puño Negro como Jefe de Guerra obediente y abrió el Portal Oscuro con Medivh." },
        { "Martillo Maldito rompió su control al matar a Puño Negro y tomar la Horda para sí. Gul'dan murió despedazado por los demonios que liberó en la Tumba de Sargeras. El nombre sobrevivió a ambos. Los brujos aún se reúnen bajo él, entre ellos orcos y Renegados, y siguen tratando con la Legión." },
        { "Su mayor bastión actual es Jaedenar, en Frondavil, donde el señor de las Sombras Fel'dan sella sus pactos en la Guarida Sombría. Mientras los druidas trabajan para limpiar el bosque, los brujos del Consejo siguen reuniéndose bajo sus raíces." },
      },
    },
    ["shadowfang-keep"] = {
      title = "Castillo de Colmillo Oscuro",
      text = {
        { "Antes de que llegara Arugal, la fortaleza sobre Piroleña pertenecía al barón Filargenta. Los ferocanis del mago la invadieron y el fantasma del barón aún ronda sus salones. El comandante Vallefont, un paladín, es otro de sus defensores no-muertos." },
        { "Arugal se refugió aquí con los ferocanis a los que llama sus hijos. La fortaleza se conoce ahora como Castillo de Colmillo Oscuro, un bastión que los Renegados quieren para su frontera sur. Sus mortacechadores entraron a explorarlo y no han regresado." },
      },
    },
    ["shadowgale-forest-tune"] = {
      title = "Bosque Ventosombra",
      text = {
        { "El Bosque Ventosombra, la Aldea Falaath y las Ruinas de Ban'aethal comparten una melodía, y ninguno de los tres es un sitio para quedarse. Los Al'Aketh han hecho suya Falaath. Ban'aethal está vacía, y lo que estuvo a punto de pasarle es la advertencia con la que vive el resto de la isla." },
      },
    },
    ["shadowglen"] = {
      title = "Cañada Umbría",
      text = {
        { "Cañada Umbría reúne a los jóvenes reclutas de los elfos de la noche alrededor de Aldrassil, un gran árbol cuyas ramas albergan a sus maestros. Druidas, sacerdotisas y centinelas cuidan de esta hondonada del bosque de Teldrassil. Su conservador enseña que el equilibrio de la naturaleza empieza por las cosas pequeñas." },
        { "Los reclutas encuentran trabajo casi de inmediato. Las arañas han crecido y los duendes y grells se han vuelto feroces. Quien comienza aquí aprende la preocupación de los guardianes por el bosque ayudándolos con lo que se ha torcido." },
      },
    },
    ["shadowprey-village"] = {
      title = "Aldea Cazasombras",
      text = {
        { "La Aldea Cazasombras es el campamento de la Horda en la costa occidental de Desolace, una aldea de trols y tauren con cabañas sobre pilotes junto al mar, última parada antes del largo camino al sur hacia Feralas. Sus habitantes cazan en la tierra muerta y vigilan tanto a centauros como a demonios." },
        { "Una tauren de Cazasombras se ha propuesto cerrar los portales demoníacos del Filo Ardiente. Cerca acampa un druida del Círculo Cenarion, a la espera de alguien lo bastante fuerte como para entrar en Maraudon. Es una aldea pequeña con problemas grandes." },
      },
    },
    ["shadra"] = {
      title = "Shadra",
      text = {
        { "Shadra es una diosa araña de los trols, una loa del veneno y las telarañas. Los Secacorteza la adoran en el altar de Shadra'Alor, en Tierras del Interior. No es un ídolo. Lee las palabras adecuadas en su altar y vendrá, tan grande como una casa." },
        { "Los Secacorteza guardan frascos de su veneno en sus aldeas. Los boticarios Renegados de Molino Tarren lo desean con ansia, lo que indica qué pretenden hacer con él. Preferiría que Shadra se quedase su veneno." },
      },
    },
    ["shady-rest-inn"] = {
      title = "La Posada Reposo Umbrío",
      text = {
        { "En el camino entre Los Baldíos y Theramore había una posada, Reposo Umbrío, donde los viajeros de ambas facciones paraban a beber sin preguntas. Ardió. Su esqueleto aún se alza junto al camino y los investigadores de ambos bandos han encontrado a su alrededor cosas que no encajan." },
        { "Hay huellas de pezuñas en el barro que se alejan. Hay un escudo de hierro negro sujeto a la chimenea. Y hay una insignia entre las cenizas, el ancla dorada de Theramore, con el nombre de un teniente: un infante de marina de Kul Tiras que cruzó el mar con lady Valiente, figura como desaparecido y parece haberse unido a una banda de desertores del pantano. No sé quién quemó Reposo Umbrío ni por qué. Sospecho que alguien quería que la Alianza y la Horda se culparan mutuamente." },
      },
    },
    ["shamans"] = {
      title = "Chamanes",
      text = {
        { "En Draenor, los chamanes orcos hablaban con los elementos y sus antepasados, hasta que los brujos de Gul'dan convirtieron a muchos a la magia vil y los espíritus callaron. Entre los Lobo Gélido de Alterac, el viejo chamán Drek'Thar mantuvo vivas las costumbres y se las enseñó a un joven esclavo fugado llamado Thrall." },
        { "Thrall devolvió el chamanismo a su pueblo. En Kalimdor encontraron a otros que nunca lo habían perdido: los tauren, que honran a la Madre Tierra, y los trols, cuyos médicos brujos conservaban el suyo. Un chamán pide ayuda a la tierra, el fuego, el agua y el aire y lleva un tótem de cada uno. Los elementos, casi siempre, responden." },
        { client = "forever", "Últimamente también se ha visto a enanos invocando la piedra y la tormenta. Los Formavientos de los cielonatos han descendido para buscar a sus espíritus del viento perdidos entre los chamanes de la Horda." },
        { "La Liga ha aprendido a pedir permiso a un chamán antes de excavar, $gviajero:viajera;. El suelo tiene opiniones y ellos las oyen." },
      },
    },
    ["shandris-feathermoon"] = {
      title = "Shandris Plumaluna",
      text = {
        { "La general Shandris Plumaluna manda a las centinelas desde el bastión que lleva su nombre. Su servicio junto a Tyrande empezó en la Guerra de los Ancestros, cuando era una niña que huía de Ara-Hinam, separada de su familia y considerada huérfana. Tyrande la acogió bajo su cuidado." },
        { "Shandris la siguió al peligro pese a las órdenes de quedarse atrás. Una de sus flechas alcanzó a Xavius. Malfurion usó la madera del astil clavado para vencer al sátiro. La niña tuvo un papel en la guerra antes de que nadie hubiera elegido dárselo." },
        { "Ha permanecido al lado de Tyrande a través del Gran Cataclismo y de las eras posteriores. Hoy su mando está lejos de Darnassus, en Feralas." },
      },
    },
    ["shen-dralas"] = {
      title = "Shen'dralas",
      text = {
        { "Shen'dralas empieza en el Valle de los Huesos, en una tierra que según los centauros ya estaba maldita mucho antes de que llegaran. Casi todo lo que sé de ella me viene de los centauros que luchan a sus puertas. Más allá del valle hay un bosque, un templo cuyo artefacto se han llevado los jabaespines Erizapúas, y nombres en los mapas, el Mirador de Sombrapar y los Jardines Desolados, que nadie me ha explicado todavía." },
        { "Lo que sí puedo contarte es quién llegó primero. Los Magram entraron en el valle y lo convirtieron en un frente. Los Gelkis los siguieron, unos para detenerlos y otros, por lo visto, para unirse a ellos. Al otro extremo se alza un campamento Magram, listo para marchar sobre el bosque, y los Erizapúas se atrincheraron igual de pronto y mantienen a raya a los Magram con lo que se llevaron del templo." },
        { "Escribiré más cuando vuelvan a contármelo los viajeros que vayan más allá del valle." },
      },
    },
    ["shendar-highlands-tune"] = {
      title = "Tierras Altas de Shen'dar",
      text = {
        { "Las Tierras Altas de Shen'dar comparten una melodía con la Aldea Shen'dar, el Lago Canzalvaje, la Torre de vigilancia del pilón del oeste y dos grupos de piedras verticales, las de Son del Viento y las del mirador. El culto atacó una vez la torre que guarda el pilón del oeste. Nadie me ha dicho qué debían señalar las piedras." },
      },
    },
    ["shendralar"] = {
      title = "Los Shen'dralar",
      text = {
        { "Los Shen'dralar permanecen en Eldre'Thalas desde antes del Gran Cataclismo. Separados del Pozo de la Eternidad, ataron al demonio Immol'thar bajo su ciudad con cinco pilones. Durante miles de años han drenado su poder para mantenerse." },
        { "El príncipe Tortheldrin aún gobierna, rodeado de salones habitados por los fantasmas de su pueblo. Algunos Shen'dralar han elegido la libertad antes que la inmortalidad. El anciano Shen'dralar pide la muerte de Tortheldrin y la paz para los espíritus, mientras los custodios del Athenaeum recompensan la ayuda con sus conocimientos. Aquí hay una biblioteca extraordinaria, pero la historia de cómo sobrevivió su gente merece tanta atención como ella." },
      },
    },
    ["shimmering-flats"] = {
      title = "El Desierto de Sal",
      text = {
        { "El Desierto de Sal es una amplia llanura salina del este de Las Mil Agujas, tan blanca que deslumbra. Goblins y gnomos han construido en ella el Circuito del Espejismo. Sus coches cohete recorren la pista ante multitudes y corredores de apuestas, con frecuentes interrupciones por accidentes." },
        { "Los restos proporcionan a Kravel Karbarbán piezas que vuelve a vender a los equipos. Los hermanos Pernolatón necesitan cascos para sus pilotos. Una carrera produce ganadores, perdedores y una cantidad útil de chatarra. Quienes trabajan junto a la pista han encontrado oficios en las tres cosas." },
      },
    },
    ["shrine-of-akir"] = {
      title = "El Santuario de Akir",
      text = {
        { "El Santuario de Akir, en Tierras Altas de Shen'dar, es el lugar sagrado de los Al'Aketh y fue la sede de su dirigente, la suma sacerdotisa Lorthuna. Para tomarlo hicieron falta la Orden Eminente, los Formavientos y los pacificadores juntos, lo que dice algo de la fuerza del culto y más de lo poco que esos tres coinciden. Valennia Puñotormenta, capitana de los pacificadores, quedó gravemente herida en el santuario interior. Lorthuna huyó por un portal a las Agujas Rohashi de arriba." },
        { "Los shen'dorei no nos han dejado por escrito lo ocurrido en las agujas. Lorthuna ya no está en Zephras y el culto ha perdido su cabeza. Pero con ella cayeron las protecciones que ocultaban la isla de Al'Akir, y el sumo anciano no pretende saber cuánto tardará el Señor del Viento en darse cuenta." },
      },
    },
    ["shrine-of-akir-tune"] = {
      title = "Santuario de Akir",
      text = {
        { "El Santuario de Akir y el Sagrario de las Tormentas comparten cuatro piezas. El culto que los ocupaba rezaba al Señor del Viento, y las dos órdenes y los pacificadores que le arrebataron el santuario apenas coinciden en nada más. Me gustaría saber qué les prometieron a los Al'Aketh en esas salas para que estuvieran tan seguros. Sospecho que la respuesta no me gustaría." },
      },
    },
    ["si-7"] = {
      title = "IS:8",
      text = {
        { "Desde el cuartel del Casco Antiguo, Mathias Shaw dirige el servicio de inteligencia de Ventormenta. El IS:8 sigue los asuntos que rara vez llegan a un anuncio público: los Defias, los secretos de los nobles y los lugares donde ambos coinciden." },
        { "La descripción del visitante de Bazil Thredd condujo a Shaw hasta un asesino que usaba el nombre de Marzon y trabajaba para lord Gregor Lescovar. La investigación terminó con ambos muertos en los jardines del castillo, fuera del alcance sencillo de la justicia ordinaria." },
        { "El cuartel da al servicio una sede discreta. Su trabajo lo lleva a salas donde los enemigos de la ciudad pueden vestir de manera muy respetable." },
      },
    },
    ["sickness-of-teldrassil"] = {
      title = "La enfermedad de Teldrassil",
      text = {
        { "Teldrassil carece de las bendiciones que Alexstrasza y Nozdormu otorgaron a Nordrassil. Los druidas de Dolanaar hablan abiertamente de ello y de los problemas del nuevo árbol: de su suelo surgen bestias extrañas y criaturas antes amistosas se han vuelto violentas." },
        { "El musgo vil se apoderó de Ursal el Violento y se extendió por su tribu Tuercepinos. El crecimiento oscuro cubre al brezomadera Musgonegro hasta tal punto que su corazón arrancado aún late bajo él. Un señor sátiro ocupa Roca Mácula. En Ban'ethil, donde los Druidas de la Garfa duermen en el Sueño Esmeralda en virtud de su pacto con Ysera, el celador ha guardado silencio." },
        { "Fandral reconoce los problemas y ofrece remedios. Otros druidas continúan investigando. Llévales lo que encuentres, $gviajero:viajera;. Un árbol lo bastante grande como para albergar a un pueblo también resulta bastante grande para que sus guardianes lo examinen." },
      },
    },
    ["silithid"] = {
      title = "Los silítidos",
      text = {
        { "Los silítidos ocupan inmensas colmenas bajo el sur de Kalimdor. Sus avispas pueden ser del tamaño de sabuesos, sus devastadores tan grandes como ogros y sus tuneladores lo bastante fuertes para derrumbar cuevas. Han aparecido colmenas en Los Baldíos, Las Mil Agujas, Feralas, Tanaris y Un'Goro. Silithus tiene la mayor concentración." },
        { "Los mandan los qiraji de Ahn'Qiraj. Hace mil años sus enjambres avanzaron al norte en la Guerra del Mar de Dunas, hasta que elfos de la noche y dragones sellaron la ciudad tras el Muro del Escarabajo. El Círculo Cenarion cree que un poder más antiguo bajo Ahn'Qiraj dirige a amos y sirvientes." },
        { "Los movimientos de las colmenas sugieren ahora preparativos para una gran expansión. El Círculo vigila de cerca. Para quien estudia estos insectos, el trabajo incluye averiguar hasta dónde llegan ya sus túneles y los propósitos de sus amos." },
      },
    },
    ["silithus"] = {
      title = "Silithus",
      text = {
        { "Silithus es un desierto de arena amarilla y grandes colmenas silítidas en el suroeste de Kalimdor. Tras el Muro del Escarabajo está Ahn'Qiraj, ciudad de los amos qiraji de los insectos. Algo aún más antiguo yace bajo su dominio." },
        { "El Círculo Cenarion vigila desde su fuerte, mientras los cultores del Martillo Crepuscular se reúnen en campamentos del desierto. Se han reunido fuerzas de la Alianza y la Horda para marchar juntas contra el muro." },
      },
    },
    ["silverpine-forest"] = {
      title = "Bosque de Argénteos",
      text = {
        { "Argénteos es un bosque de altos pinos grises en la costa al sur de Tirisfal, que se extiende hasta la gran muralla que separa Gilneas del mundo. Fue una tierra tranquila de granjas y aldeas pesqueras, parte del reino de Lordaeron. La peste lo atravesó, después los muertos y después algo peor." },
        { "Ahora es una tierra de frontera. Los Renegados dominan el norte desdel Sepulcro, los ferocanis creados por un mago demente cazan en los bosques, los gnolls apestados excavan en los campos muertos y los magos de Dalaran conservan una aldea en el este. Todos en Argénteos esperan algo, y ninguno espera nada bueno." },
      },
    },
    ["skyborne"] = {
      title = "Los cielonatos",
      text = {
        { "Los cielonatos se llaman shen'dorei, el pueblo oculto. Hasta que descendieron del cielo, la Liga no sabía que existían. Sus antepasados vivían en Eldre'Thalas, la ciudad que los ogros llaman ahora La Masacre, y se alzaron contra un príncipe que quería someter a un demonio para alimentar su magia. Guiados por el enmascarado Shal'nan, huyeron por mar y los espíritus del viento elevaron su isla fuera del mundo hasta Muro Celeste." },
        { "La Isla de Zephras permaneció allí durante eras. Ahora los espíritus se han ido, la isla falla y los cielonatos han descendido en busca de ayuda. La Orden Eminente busca los conocimientos arcanos que perdió su pueblo y acude a los magos de Dalaran. Los Formavientos buscan a sus espíritus desaparecidos y acuden a los chamanes de la Horda." },
        { "Son pocos y lo saben, $gviajero:viajera;. Un cielonato que parece cuidar de cada vida, incluida la propia, está calculando cuántos de los suyos quedan por perder." },
      },
    },
    ["sons-of-lothar"] = {
      title = "Los Hijos de Lothar",
      text = {
        { "Cinco estatuas se alzan a las puertas de Ventormenta y todas sus placas terminan igual: presuntamente fallecido. Son los mandos de la Expedición de la Alianza, que atravesaron el Portal Oscuro hacia el propio mundo de los orcos tras la Segunda Guerra, cuando Ner'zhul y los últimos clanes volvieron a cruzarlo." },
        { "Los dirigía Khadgar, antiguo aprendiz de Medivh, con el general Turalyon a su lado. La forestal elfa Alleria Brisaveloz exploraba para ellos, Kurdran Martillo Salvaje mandaba a los jinetes de grifos y Danath Aterratrols, de Stromgarde, los asesoraba. No pudieron impedir que Ner'zhul abriera sus portales a otros mundos y, mientras Draenor se desgarraba, decidieron destruir el Portal Oscuro desde el otro lado para que no arrastrara a Azeroth consigo. Lo consiguieron. Si alguno logró escapar, dice el libro de nuestra biblioteca, aún está por verse." },
        { "Lee las propias placas. Cada una la escribió alguien que conocía al héroe: Falstad para Kurdran, Uther para Turalyon, Thoras Aterratrols para su sobrino y Antonidas para Khadgar, deseándole lo mejor dondequiera que esté. La de Alleria la escribió su hermana Sylvanas, general forestal de Quel'Thalas, antes de convertirse en lo que es ahora." },
      },
    },
    ["southsea-freebooters"] = {
      title = "Los Filibusteros del Mar del Sur",
      text = {
        { "Los Filibusteros del Mar del Sur son piratas de los mares cálidos de Kalimdor y atacan sobre todo a los goblins, porque son quienes tienen más cosas que merece la pena robar. Ocupan campamentos en la Costa del Mercader de Los Baldíos, al sur de Trinquete, y en las calas de Tanaris. Sus barcos esperan cuanto salga de un puerto Bonvapor." },
        { "Su capitán de la Costa del Mercader es el barón Longavera. Gazlowe de Trinquete paga por su cabeza. Los goblins de Gadgetzan pagan igual de bien por los piratas de Tanaris. No hay detrás una gran historia, ningún rey exiliado ni causa perdida. Son ladrones con barcos y el mar es ancho." },
      },
    },
    ["southshore"] = {
      title = "Costasur",
      text = {
        { "Costasur es un pueblo pesquero y un puerto en la costa de Trabalomas, con posada, ayuntamiento y una guarnición que combate a los Renegados de Molino Tarren. Sigue siendo un bastión de los vivos en una tierra donde esa distinción importa." },
        { "Kundric Zanden conserva su historia, y los maestros de historia de Ventormenta envían estudiosos a través de la villa hacia las bibliotecas arruinadas de Alterac. Me alegra encontrar registros en un lugar así. Aquí un viajero puede conseguir provisiones, pero también aprender algo sobre la tierra por la que tendrán que sostenerlo." },
        { side = "Horde", aside = true, sign = "P. F.", "Kundric Zanden conserva la historia de Costasur y yo conservo lo que queda de la de Lordaeron. Dudo que coincidiéramos en el último capítulo." },
      },
    },
    ["splintertree-post"] = {
      title = "Puesto del Hachazo",
      text = {
        { "El Puesto del Hachazo es el fuerte de la Horda en el extremo oriental de Vallefresno, una empalizada de madera recién cortada donde acampan los leñadores y jinetes Grito de Guerra. Las centinelas lo atacan constantemente y los orcos devuelven cada golpe." },
        { "Los orcos dicen que necesitan la madera: Durotar es una tierra de roca roja y un pueblo tiene que construir. Los elfos de la noche dicen que cada árbol de este bosque es más antiguo que la Horda. Ambos tienen razón, y eso lo hace tan difícil." },
      },
    },
    ["stalvan-mistmantle"] = {
      title = "Stalvan Mantoniebla",
      text = {
        { "Stalvan Mantoniebla fue maestro en Arroyo de la Luna y preceptor de familias del campo. Imaginó que su alumna Tilloa correspondía a su afecto. Cuando ella presentó a un pretendiente y llamó a su maestro un amable tío viejo, su propio relato se volvió furioso. Después llegaron los asesinatos." },
        { "Cartas y diarios siguen sus pasos por Páramos de Poniente y Ventormenta hasta la mansión al noreste de Villa Oscura, donde la oscuridad del Bosque del Ocaso lo ha cambiado aún más. Los presagios de lady Eva inician la búsqueda, pero las palabras del propio Stalvan la impulsan en buena medida." },
        { "Es una historia espantosa que recuperar de papeles tan corrientes. Una plaza de maestro, la correspondencia de una familia, el nombre de una alumna: lo que debería haber pertenecido a una vida tranquila queda entre los rastros de aquellos a quienes destruyó." },
      },
    },
    ["starfall-village"] = {
      title = "Aldea Estrella Fugaz",
      text = {
        { "La Aldea Estrella Fugaz es un pequeño asentamiento de los elfos de la noche entre las nieves de Cuna del Invierno, donde druidas y estudiosos viven entre los árboles. Estudian la tierra, sus criaturas y las viejas ruinas junto al lago." },
        { "Fue un estudioso de Estrella Fugaz quien descubrió qué son los lechúcicos de Cuna del Invierno: no bestias, sino criaturas de Elune, la diosa de la luna. El archidruida de Darnassus se interesó mucho. Yo también." },
      },
    },
    ["steamwheedle-cartel"] = {
      title = "El Cártel Bonvapor",
      text = {
        { "El Cártel Bonvapor comercia con la Alianza y la Horda. Sus goblins han descubierto que quienes quieren luchar entre sí siguen necesitando provisiones y que merece la pena aceptar las monedas de ambos. Sus poblaciones ofrecen un lugar para hacer negocios." },
        { "Bahía del Botín, Gadgetzan, Trinquete y Vista Eterna abarcan jungla, desierto, costa y nieve. Los matones imponen la paz dentro. Revilgaz supervisa Bahía del Botín, mientras Gazlowe tiene trabajo para los visitantes de Trinquete. Cada puerto tiene problemas que el comercio solo no resolverá." },
        { "Un viajero puede comprar provisiones, encontrar empleo y conocer a la otra facción sin recurrir de inmediato a un arma. El cártel cobra por mucho de lo que ofrece, pero una parada neutral tiene valor en un mundo cuyos caminos atraviesan tantas guerras." },
      },
    },
    ["stonard"] = {
      title = "Rocal",
      text = {
        { "Rocal es la fortaleza de la Horda en el Pantano de las Penas: un fuerte bajo de piedra y unas cabañas sobre una elevación del lodo, ocupados por orcos que vigilan Las Tierras Devastadas al sur y los caminos de la Alianza al norte." },
        { "Es un lugar sombrío, húmedo y leal. Sus habitantes envían guerreros al templo del pantano y a las tierras demoníacas de más allá sin hacerse muchas ilusiones sobre cuántos volverán. Fuera de sus muros, un fantasma espera órdenes que nunca llegaron." },
      },
    },
    ["stonefields-and-maclures"] = {
      title = "Los Pedregosa y los Maclure",
      text = {
        { "Los Pedregosa y los Maclure cultivan sus tierras a ambos lados de la Mina Abisal, al sur de Villadorada. Las dos familias llevan enfrentadas más tiempo del que nadie se molesta en explicar. Naturalmente, Maybell Maclure está enamorada de Tommy Joe Pedregosa. Él espera sus cartas junto al río, al oeste de la granja familiar. Ella espera una oportunidad para escaparse." },
        { "La abuela de los Pedregosa está de parte de los jóvenes. Envía una nota a su viejo amigo William Mortero, en Villadorada, que puede preparar un licor de invisibilidad si alguien le trae algas de cristal de los múrlocs del Lago de Cristal. Con él, Maybell podrá salir de los viñedos familiares sin que la vean. Dice que le sabe mal engañarlos, pero no lo bastante como para quedarse." },
        { "La disputa continúa a su alrededor: una tía Pedregosa acusa al pequeño Billy Maclure de robarle el collar, y La vieja Pedregosa jura matar a la cerda premiada de los Brackwell por comerse sus verduras. Elwynn ha visto ir y venir a los Defias, los kóbolds y los gnolls. La riña, por ahora, ha durado más que todos ellos." },
      },
    },
    ["stonetalon-mountains"] = {
      title = "Sierra Espolón",
      text = {
        { "La Sierra Espolón se alza entre Vallefresno y Los Baldíos: altas cumbres grises, valles profundos y bosques antiguos, el hogar ancestral de las arpías, con la cumbre sagrada de los druidas en su corazón. Los chamanes de la Horda dicen que los espíritus de estas montañas están furiosos. Tienen motivos." },
        { "Los goblins de Ventura y Cía. han venido a talar, quemar y excavar, y con ellos han desaparecido valles enteros. Sus máquinas arrasaron La Vega Carbonizada, al sur. Las arpías Furia Sangrienta ocupan las alturas, los Tótem Siniestro atacan aldeas tauren y, en medio de todo, los druidas de la cumbre y los chamanes de Roca del Sol intentan sanar lo que pueden." },
      },
    },
    ["stonetalon-peak"] = {
      title = "Cima del Espolón",
      text = {
        { "La Cima del Espolón es la mayor cumbre de la sierra y un lugar sagrado para los druidas de los elfos de la noche. La protegen junto a los espíritus del bosque que llaman hijos e hijas de Cenarius. Allí está El Cubil del Espolón, donde guardan objetos de poder bajo cerraduras de su propia invención. Al menos uno de ellos, el hermano Roblecuervo, duerme en forma de oso y los protege en sueños." },
        { "Los guardianes de la cumbre contemplan con dolor las montañas de abajo: la vega quemada, los bosques talados, las arpías que no les permiten pasar para volver a plantar. Son pacientes, como los druidas, y están perdiendo." },
      },
    },
    ["stonewatch-keep"] = {
      title = "Fuerte de Petravista",
      text = {
        { "El Fuerte de Petravista protegía el acceso norte de Crestagrana. Los Roca Negra descendieron por ese acceso y lo tomaron. Ahora sus asaltantes atacan las granjas sobre Villa del Lago y sus emboscadores vigilan el camino entre la población y el fuerte. Una fortificación sirve a quien ocupa sus muros." },
        { "Un regimiento de soldados de Ventormenta fue aniquilado entre las torres derruidas. Se dice que unos pocos supervivientes están presos en las cuevas. El señor de la guerra Gath'Ilzogg ocupa el propio fuerte, con un precio sobre su cabeza ofrecido por el magistrado Salomón. Examina bien el terreno, $gviajero:viajera;. Villa del Lago ya ha perdido hombres intentando recuperarlo." },
      },
    },
    ["stonewrought-dam"] = {
      title = "La Presa de las Tres Cabezas",
      text = {
        { "La Presa de las Tres Cabezas cierra el extremo norte de Loch Modan. Su muro y su cascada son dos de las grandes vistas de Khaz Modan. Dedícales un rato, $gviajero:viajera;. Darte ese paisaje llevó muchísimo trabajo." },
        { "El ingeniero jefe Hinderweir ha descubierto un complot de los Hierro Negro contra la presa. Su investigación lleva a un barril explosivo y a la mezcla necesaria para desactivarlo. Los enanos vigilan de cerca esta obra, con razón. Hay gente que depende de que el muro aguante, y Hinderweir se juega bastante más que el orgullo de un ingeniero." },
      },
    },
    ["storm-shadowhoofs-trials"] = {
      title = "Las pruebas de Ventisca Pezuña Umbría",
      text = {
        { "El camino del cazador, tal como lo enseñan los tauren, empieza pronto y llega lejos. El viejo Skorn Nubeblanca envía a los más entusiastas a Melor Pezuñapétrea, en el Alto de los Cazadores de Cima del Trueno, y Melor los manda lejos. A través de Los Baldíos con Sergra Espinoscura. A Las Mil Agujas, tras Metaleador, una hiena tirana que no cuenta con la bendición de la Madre Tierra. A las nieves de Alterac, a por Faucehielo, un yeti que rara vez se deja ver. Al Marjal Revolcafango, para poner fin al dolor de Lodomuerto, un anciano crocolisco cuyo gran espíritu es torturado por su propio cuerpo viejo. Tal es el camino del cazador, les dice Melor: al final los llevará por todas las tierras de la Madre Tierra." },
        { "En Cuna del Invierno el camino llega hasta Ventisca Pezuña Umbría, que no sale de Vista Eterna y encarga tres cacerías. Ursius de los osos dentoesquirla, en las colinas al noroeste del pueblo, es tan astuto que quienes lo cazan pronto se convierten en su presa. Brumerán de los Venfresco planea entre las quimeras del sur, grácil y veloz, y quien se cruza con ella lo paga muy caro, a menudo con su vida. Shi-Rotam es la matriarca de los sables de hielo que se reúnen en la Roca Sable de Hielo, y acude furiosa a su piedra cuando se deja allí la carne de los suyos." },
        { "La última prueba es volver a casa. Ventisca le entrega al cazador una señal para Melor, que se acordará de él desde el comienzo del camino, hace ya tanto tiempo. Yo no nombraría a Shi-Rotam ante las Centinelas que crían sables de invierno en esa misma roca." },
      },
    },
    ["stormpike-guard"] = {
      title = "La Guardia de Pico Tormenta",
      text = {
        { "La Guardia de Pico Tormenta llegó al Valle de Alterac para extraer minerales y buscar reliquias del origen de los enanos. La Liga de Expedicionarios acompañaba a la expedición. Dicen que los Lobo Gélido atacaron sin provocación. Los Lobo Gélido cuentan lo mismo cambiando los nombres." },
        { "Vanndar Pico Tormenta manda la Guardia y el rey Magni le ha ordenado tomar el valle para Forjaz. Los Lobo Gélido ya viven allí y se resisten a la orden. Sirvo al rey que la dio, pero el interés de la Liga por lo que hay bajo tierra no resuelve los derechos de quienes viven encima." },
      },
    },
    ["stormrage-barrow-dens"] = {
      title = "El Túmulo de Tempestira",
      text = {
        { "Los druidas duermen bajo las colinas del Claro de la Luna mientras sus espíritus recorren el Sueño Esmeralda, a veces durante años. Estos túmulos llevan el nombre de Malfurion Tempestira y recuerdan al primer druida y la larga práctica de sus seguidores." },
        { "Durante la Tercera Guerra, Tyrande llamó a los druidas dormidos para enfrentarse a la Legión. Ahora Malfurion ha desaparecido y los druidas desconocen su destino. Con la Pesadilla extendiéndose, los custodios de los túmulos y Rémulos tienen motivos para temer por quienes están en el Sueño. Pisa con cuidado, $gviajero:viajera;. La quietud sobre los druidas dormidos dice poco de lo que pueden estar afrontando sus espíritus." },
      },
    },
    ["stormwind-city"] = {
      title = "Ciudad de Ventormenta",
      text = {
        { "Ventormenta es la mayor ciudad de los humanos y la segunda Ventormenta que se alza en este lugar. La primera fue saqueada por la Horda durante la Primera Guerra y arrasada por las llamas. El rey Llane fue asesinado y su pueblo huyó al norte, a Lordaeron, con el campeón Anduin Lothar. Cuando ganaron la Segunda Guerra, volvieron a casa y la levantaron de nuevo." },
        { "Los albañiles del Gremio de Canteros la construyeron en piedra blanca, más hermosa que antes: la Catedral de la Luz, los canales y el castillo que los domina. Después, la Casa de Nobles se negó a pagarles. El agravio de los albañiles se ha convertido desde entonces en la Hermandad Defias, de modo que la ciudad más hermosa de la Alianza es también la que despierta recuerdos más amargos." },
        { client = "classic", "Es una ciudad de comercio y soldados, de sacerdotes y espías, y de una corte que susurra. El niño del trono es su rey. Los hombres y las mujeres que lo rodean la gobiernan." },
        { client = "forever", "Es una ciudad de comercio y soldados, con barcos en su puerto, de sacerdotes y espías, y de una corte que susurra. El niño del trono es su rey. Los hombres y las mujeres que lo rodean la gobiernan." },
      },
    },
    ["stormwind-tune"] = {
      title = "Ventormenta",
      text = {
        { "Ventormenta tiene su propia melodía, que suena entre los canales y las catedrales de la capital humana. La Horda quemó la ciudad en la primera guerra, y los humanos la reconstruyeron más grande y más orgullosa que antes. Observo que es una ciudad levantada por gente que esperaba ser atacada de nuevo." },
      },
    },
    ["stranglethorn-vale"] = {
      title = "Vega de Tuercespina",
      text = {
        { "Tuercespina es una jungla, la mayor de los Reinos del Este: calor, lluvia, lianas, panteras, raptores y gorilas, ruinas devoradas por el verdor y una larga costa de playas y calas. Fue el corazón de los Gurubashi, el imperio trol que dominó el sur mucho antes de los reinos humanos. Las ruinas de sus templos están por todas partes." },
        { "Todos vienen por algo. Los cazadores por trofeos, los goblins por oro y madera, los piratas por botín y los soldados de la Alianza y la Horda para combatir a trols, ogros y entre sí. Tarde o temprano, la jungla se traga a la mayoría." },
      },
    },
    ["stratholme"] = {
      title = "Stratholme",
      text = {
        { "Stratholme era la segunda ciudad de Lordaeron, su joya del norte. Cuando la peste llegó en carros de grano, el príncipe Arthas acudió con Uther y Jaina y encontró a toda la ciudad enferma y transformándose. Ordenó purgarla. Uther se negó y Jaina lo abandonó. Arthas pasó Stratholme a cuchillo, casa por casa, antes de que se alzaran los muertos, y el señor del terror Mal'Ganis lo esperaba al final. Ahora lo llaman la Matanza y fue el comienzo de la caída de Arthas." },
        { "Desde entonces ha visto traiciones peores. Un mago de Stromgarde llamado Ras Murmuhielo entregó voluntariamente su vida a la Plaga sobre su suelo ensangrentado y se alzó como exánime de Scholomance. Aquí también el alto señor Mograine, el Crematoria, fue conducido a una emboscada por su propio hijo y asesinado con su propia hoja." },
        { "La ciudad sigue ardiendo. La Plaga ocupa una mitad bajo el barón Osahendido y la Cruzada Escarlata la otra, desde su bastión, bajo el Gran Cruzado. Los muertos a los que no mataron aún recorren sus calles. Algunos, los fantasmas, desearían mucho ser liberados." },
        { side = "Horde", aside = true, sign = "P. F.", "Aún hay quien dice que el príncipe hizo lo correcto en Stratholme. Yo no soy uno de ellos." },
      },
    },
    ["stromgarde-keep"] = {
      title = "Castillo de Stromgarde",
      text = {
        { "Stromgarde ocupa el lugar de Strom, la primera ciudad humana. Sus gobernantes Aterratrols llevaban la corona más antigua de los reinos humanos. Lord Ignaeus combatió a los trols con la espada llamada Trol'kalar, la matatrols, y el apellido de la familia recuerda aquella guerra." },
        { "La ciudad actual está dividida. El Sindicato de lord Cresta de Halcón domina sus torres, los ogros ocupan un barrio y los defensores de Stromgarde conservan otro. Otros supervivientes luchan desde el Refugio de la Zaga por recuperar su hogar. Trol'kalar permanece en la tumba de Aterratrols, tras resguardos que pueden abrirse reuniendo los sigilos." },
      },
    },
    ["sun-rock-retreat"] = {
      title = "Refugio Roca del Sol",
      text = {
        { "Tauren y orcos comparten el Refugio Roca del Sol, entre los riscos del centro de la Sierra Espolón. Sus chamanes recogen semillas para repoblar las tierras quemadas. Los cazadores buscan vengar al Campamento Aparaje, la aldea tauren casi destruida por los Tótem Siniestro. El trabajo del campamento incluye restauración y represalias." },
        { "Un brujo alojado aquí tiene otro propósito. Sirve a un amo de Jaedenar y paga por ayuda contra los druidas de la cumbre, a quienes acusa de ahogar la magia. Escucha con atención quién ofrece cada encargo, $gviajero:viajera;. Compartir campamento no da a sus habitantes las mismas intenciones." },
      },
    },
    ["swamp-of-sorrows"] = {
      title = "Pantano de las Penas",
      text = {
        { "El Pantano de las Penas está al este del Bosque del Ocaso, bajo un cielo siempre gris: sauces y mangles, agua negra, niebla y muchísimo barro. Se gana su nombre. Los crocoliscos acechan en las charcas, los nagas rondan la costa y en mitad del fango hay una laguna donde un templo trol se hundió hace mucho, con dragones dormidos encima." },
        { "La Horda tiene aquí una población, Rocal, y algunas almas quebradas de otro mundo viven al este del pantano. Hay pocos motivos para venir. Los que hay suelen ser muy antiguos o muy peligrosos, y normalmente ambas cosas." },
      },
    },
    ["sylvanas-windrunner"] = {
      title = "Lady Sylvanas Brisaveloz",
      text = {
        { "Sylvanas Brisaveloz era la general forestal de Lunargenta, la mejor arquera de los altos elfos y la comandante de sus forestales. Combatió al príncipe Arthas a cada paso cuando llevó a la Plaga hasta Quel'Thalas. Cuando por fin se abrió camino, la mató y, como castigo por su resistencia, no le permitió descansar: la alzó como alma en pena y la obligó a servirlo." },
        { "Cuando flaqueó el poder del Rey Exánime, Sylvanas se liberó. Reunió a los no-muertos que habían despertado con ella, sometió a un señor del terror y tomó para sí las ruinas de la capital de Lordaeron. Los Renegados la llaman la Dama Oscura y la seguirían a cualquier parte." },
        { "Procede de una familia de forestales. Su hermana mayor, Alleria, cruzó el Portal Oscuro con la Expedición de la Alianza y nunca regresó. Fue Sylvanas quien escribió las palabras de su placa a las puertas de Ventormenta. La menor, Vereesa, también era forestal de Quel'Thalas." },
        { "Quiere ver muerto a Arthas. Más allá de eso, guarda sus propósitos para sí, y sus ojos no revelan nada." },
        { side = "Horde", aside = true, sign = "P. F.", "Nos devolvió nuestras mentes, que es más de lo que consiguió la Luz. Lo que piensa hacer con nosotros después, no lo ha dicho." },
      },
    },
    ["syndicate"] = {
      title = "El Sindicato",
      text = {
        { "Alterac fue el reino que vendió la Alianza a la Horda en la Segunda Guerra. Cuando esta terminó, le arrebataron sus tierras y despojaron a sus nobles de sus títulos. Algunos nunca lo han aceptado. Se llaman el Sindicato y son ladrones y degolladores bajo el estandarte de un señor." },
        { "Su dirigente era lord Aliden Perenolde, hijo del rey traidor. Soñaba con volver a encadenar a los orcos como en los campos de internamiento. Sus seguidores ocupan la ruinosa Strahnbrad en Alterac y el Castillo de Durnholde en Trabalomas, desde donde asaltan los caminos de Costasur y conspiran contra su magistrado. En Arathi, lord Cresta de Halcón ha tomado las ruinas de la propia Stromgarde." },
        { "Son muchos y no demasiado buenos. Los asesinos de Ravenholdt, que llevan años combatiéndolos, los llaman aficionados. Los Renegados pagan por cada cabeza. Pero muchos ladrones pueden hacer mucho daño, y el Sindicato lo hace." },
      },
    },
    ["taelan-fordring"] = {
      title = "Taelan Vadín",
      text = {
        { "Taelan Vadín creció creyendo que su padre estaba muerto. Cuando Tirión perdió sus tierras por cumplir su palabra con un orco, la madre de Taelan se quedó y eso fue lo que contó al niño. Él se unió a la Cruzada Escarlata, ascendió bajo el Gran Cruzado, derribó el estandarte de la Mano de Plata en Vallenorte y se convirtió en alto señor de la Cruzada en Vega del Amparo." },
        { "Dice que nunca dejó de soñar con su padre: con Tirión a su lado el día en que lo nombraran caballero, con combatir juntos a la Plaga, con honrar a Lordaeron. Cuando los viajeros le llevan lo que Tirión guardó para él y la verdad sobre aquello en lo que se ha convertido la Cruzada, rompe con ella y cabalga en busca de su padre." },
        { "No llega lejos. El gran inquisidor Isillien lo mata fuera de Vega del Amparo, a la vista del hombre al que iba a encontrar. Tirión mata a Isillien sobre el cuerpo de su hijo. La Orden de la Mano de Plata, dice después, ha renacido. Le costó su hijo recordar para qué existía." },
      },
    },
    ["talaanis-shadowsong"] = {
      title = "Talaanis Cantosombrío",
      text = {
        { "Talaanis Cantosombrío es el sumo anciano de la Isla de Zephras y su pueblo habla bien de él. Un buen hombre, dicen, muy querido, algo que la Liga ha aprendido a no dar por sentado en un gobernante. Gobierna desde Valanaar con los demás ancianos de la isla, entre ellos Aetheen de los Vendavales." },
        { "Sus años de gobierno no han sido fáciles. Los pilones fallan, las dos órdenes de su pueblo apenas coinciden en nada y el culto Al'Aketh atacó la atalaya occidental y mató a su propio sobrino, un pacificador. Cuando por fin expulsaron a la suma sacerdotisa del culto, no lo llamó victoria. Las protecciones que ocultaban Zephras de Al'Akir habían caído y solo pudo decir que quizá pasarían años, incluso décadas, antes de que el Señor del Viento volviese la mirada hacia ellos." },
      },
    },
    ["talonbranch-glade"] = {
      title = "Claro Ramaespolón",
      text = {
        { "El Claro Ramaespolón es un pequeño puesto de los elfos de la noche en el norte de Frondavil, con un pozo de la luna y unas casas entre los árboles corruptos, justo al sur del Bastión Fauces de Madera, el túnel fúrbolg que lleva al Claro de la Luna y Cuna del Invierno." },
        { "Es una pequeña isla de suelo limpio en un bosque enfermo. Las centinelas que lo mantienen protegen el camino del norte para todo viajero que deba atravesar Frondavil." },
      },
    },
    ["talvashs-necklace"] = {
      title = "El collar de Talvash",
      text = {
        { "Talvash del Kissel es un joyero gnomo de Forjaz, de gran renombre hasta hace poco, y el collar es una de sus mejores obras. Lo hizo para un paladín que se había propuesto limpiar Uldaman de su mancha maligna, con tres gemas para atar su magia y, en el reverso, el sello de la ciudad y sus propias iniciales. El paladín murió en Uldaman. Entonces un rival del oficio hizo correr la voz de que el collar había maldecido al paladín, y desde entonces apenas le llegan encargos." },
        { "Las gemas se quedaron abajo. El diario del paladín, hallado junto a sus restos, dice dónde: el rubí tras las barricadas de los enanos Forjatiniebla, el topacio en una urna de los troggs cerca de unos enanos de la Alianza, nada menos, el zafiro en manos de Grimlok, el jefe de los troggs. Para despertar el collar, Talvash necesitaba una fuente de energía, y el ensamblaje más poderoso del lugar tenía una. El collar restaurado fue para quien lo trajo todo de vuelta, con el ruego de mencionar a su creador en voz alta y a menudo, y de añadir que no está maldito." },
        { "La Horda lo cuenta de otra manera. Los de Rescates Droffers e Hijos, en Orgrimmar, oyeron hablar del collar del paladín muerto y enviaron a alguien a buscarlo, y Jarkal Musgofusión, un trol de Kargath con un hechizo para la lengua de los humanos, tradujo el diario a cambio de poder estudiar el collar mientras tanto. Se quedó con la fuente de energía, sacó de ella dos collares, uno para él y otro para quien se lo había traído todo, y le queda bastante para al menos tres más. Los Droffers no saben nada. Talvash, sospecho, tampoco. No seré yo quien se lo diga." },
      },
    },
    ["tanaris"] = {
      title = "Tanaris",
      text = {
        { "Tanaris es el gran desierto del sur de Kalimdor, un océano de dunas y roca rota entre Las Mil Agujas y el mar. Aquí el agua vale más que el oro y los goblins que administran su única población lo saben." },
        { "Pese a su vacío, es un desierto concurrido. Los trols Furiarena ocupan su ciudad al oeste, los bandidos Deambuladores recorren las dunas, los piratas dominan la costa sur, los ogros el sur y los silítidos se agitan en la Sima Abierta. Y en el extremo sur, tras puertas selladas, hay una obra de los propios titanes en la que la Liga de Expedicionarios daría sus barbas por entrar." },
      },
    },
    ["tarren-mill"] = {
      title = "Molino Tarren",
      text = {
        { "En otro tiempo, molineros y granjeros habitaban Molino Tarren. Ahora los Renegados lo ocupan como bastión del sur, con guardias de la Muerte al servicio de un sumo ejecutor que responde ante Varimathras. Costasur está a un breve trayecto a caballo." },
        { "Darthalia ordena ataques contra las granjas de Trabalomas y llama plaga a sus habitantes humanos. Pretende someterlos mientras los boticarios terminan su nueva peste. La guerra entre estas poblaciones va mucho más allá de sus guardias: los granjeros y sus cosechas figuran en las órdenes." },
        { side = "Horde", aside = true, sign = "P. F.", "Nos dicen que la nueva peste de los boticarios está destinada a la Plaga. La última peste me mató. Me gustaría verlo por escrito." },
      },
    },
    ["tauren"] = {
      title = "Los tauren",
      text = {
        { "Los tauren están entre los pueblos más antiguos de las llanuras de Kalimdor. Durante generaciones, sus tribus vagaron siguiendo a las manadas y los caminos de la Madre Tierra, mientras los centauros los acosaban de un campamento a otro. Cairne Pezuña de Sangre reunió a muchas tribus. Cuando desembarcaron los orcos de Thrall, los ayudaron a rechazar a los centauros y llegar a los pastizales de Mulgore." },
        { "Allí levantaron Cima del Trueno sobre sus mesetas y se asentaron, aunque conservan hábitos del camino. Honran a la Madre Tierra, cuyos ojos son An'she, el sol, y Mu'sha, la luna. Sus chamanes hablan con los espíritus y sus druidas recorren el Sueño con el Círculo Cenarion. No todas las tribus siguen a Cairne. Los Tótem Siniestro guardan sus propios planes y rencores." },
        { "Tardan en enfadarse y cuesta muchísimo detenerlos una vez enfadados, $gviajero:viajera;. Los arqueólogos de la Liga los consideran los anfitriones más pacientes de Kalimdor, siempre que nadie excave donde están enterrados sus antepasados." },
      },
    },
    ["teldrassil"] = {
      title = "Teldrassil",
      text = {
        { "Teldrassil es un árbol, y escribo esa frase sabiendo lo absurda que suena. Se alza en el mar frente a la costa norte de Costa Oscura, tan enorme que en sus ramas crecen bosques y corren ríos. Los elfos de la noche viven en su copa. Su nombre significa 'corona de la tierra'." },
        { "Los elfos de la noche tuvieron otro árbol semejante, Nordrassil, en el Monte Hyjal, y mientras se mantuvo en pie no envejecieron. Al final de la última guerra permitieron que fuera destruido para acabar con el demonio Archimonde y renunciaron con él a su inmortalidad. Terminada la guerra, los druidas de Fandral Corzocelada hicieron crecer Teldrassil para sustituirlo." },
        { "El viejo árbol tenía la bendición de los grandes dragones. El nuevo no, y sus propios guardianes admiten que su crecimiento no ha estado libre de defectos. Hablaré de ello en otro lugar. Por ahora, toma un barco desde Auberdine, cruza el portal de Rut'theran y contémplalo: no hay nada igual en el mundo." },
      },
    },
    ["temple-of-ahn-qiraj-tune"] = {
      title = "Templo de Ahn'Qiraj",
      text = {
        { "En algún rincón profundo del Templo de Ahn'Qiraj suena una docena de piezas que no he encontrado en ningún otro sitio. Los qiraji sirven a C'Thun, un dios antiguo cuya malicia ya estaba aquí antes de que el mundo tomara forma, y el templo es su morada. Quienes han salido de su última cámara traen el ojo de la criatura que allí reinaba, y lo tomo por prueba suficiente de que nada ahí dentro es demasiado viejo para morir." },
      },
    },
    ["temple-of-ahnqiraj"] = {
      title = "Templo de Ahn'Qiraj",
      text = {
        { "Los emperadores gemelos Vek'lor y Vek'nilash gobiernan a los qiraji desde el Templo de Ahn'Qiraj. Entre sus sirvientes están los enjambres silítidos y los grandes gusanos de sus salones. Los dragones bronce miran este lugar con temor." },
        { "Bajo los emperadores yace C'Thun. El templo y el imperio que lo rodea sirven a este dios antiguo, no a los gobernantes que el viajero encuentra primero. Los emperadores celebran su corte sobre la cámara de su propio amo." },
      },
    },
    ["thandol-span"] = {
      title = "El Puente Thandol",
      text = {
        { "El Puente Thandol llevaba el camino del norte desde Khaz Modan hasta Arathi y los reinos humanos de más allá. Sus dos grandes puentes enanos sirvieron a esa ruta durante generaciones. Un ingeniero te pediría que admirases la cantería. Quienes dependían del paso también tenían motivos para admirarla." },
        { "Los Hierro Negro casi han destruido uno de los puentes. Los soldados enanos conservan el otro y el camino sigue abierto bajo su vigilancia. Es más fácil elogiar una gran obra de ingeniería cuando otro se ocupa de mantenerla en pie." },
        { "Mira hacia el tramo roto al pasar, $gviajero:viajera;. Ambos puentes se construyeron para llevar gente sobre el agua. Solo uno puede hacerlo todavía." },
      },
    },
    ["the-agamands"] = {
      title = "Los Agamand",
      text = {
        { "Los Agamand eran la familia más rica de Tirisfal y estos molinos les pertenecían. Cuando llegó la Plaga, fortificaron la casa y ordenaron a todos sus empleados que se quedaran a defenderla. Los jornaleros se quedaron. Eran leales, dice ahora uno de ellos, y unos necios." },
        { "Nada resistió. La familia y sus trabajadores murieron juntos y se alzaron juntos, y los Agamand aún recorren los molinos al servicio del Rey Exánime: Gregor, el padre, Nissa, su esposa, y sus hijos. Su cripta está en el extremo norte de la finca, entre la Plaga." },
        { "Algunos trabajadores se liberaron y ahora son Renegados. Coleman Lontananza, que trabajaba en los molinos, envía viajeros a destruir lo que queda de la familia y saquear las reliquias de su cripta. La venganza, dice, tiene un sabor dulce. Espera que conocieran el miedo antes del final. Admite que es una esperanza insensata. La conserva de todos modos." },
      },
    },
    ["the-al-aketh"] = {
      title = "Los Al'Aketh",
      text = {
        { "Los Al'Aketh son un culto shen'dorei reconocible por sus túnicas grises y cabezas rapadas, que adora a Al'Akir, el Señor del Viento, como legítimo gobernante de Muro Celeste. Sus predicadores cuentan una historia sencilla: los shen'dorei se volvieron orgullosos y dieron por sentada la generosidad de los vientos, y por ello los espíritus los abandonaron. En una isla que se deshace, encuentra oyentes." },
        { "Ocupan la Aldea Falaath, en Tierras Altas de Shen'dar, y el Santuario de Akir bajo su suma sacerdotisa Lorthuna. Han atacado las atalayas de los pilones, asaltado a los druidas Garranoche para conseguir un pilón propio, enviado espías a las aldeas y encontrado al menos un traidor en Valanaar. Un antiguo pacificador, Belguilos, llamado el Rompedor, manda a sus combatientes." },
      },
    },
    ["the-ashbringer"] = {
      title = "La Crematoria",
      text = {
        { "El nombre de la Crematoria perteneció a un hombre antes que a una espada. El alto señor Mograine fundó la Cruzada Escarlata con la alta general Abbendis y el alto inquisidor Isillien, cuando aún era una orden noble. Lo llamaban el Crematoria por lo que hacía a los ejércitos del Rey Exánime: entraba entre batallones enteros de no-muertos y salía al otro lado sin dejar más que cenizas. La hoja tomó su nombre de él." },
        { "El alto inquisidor Ribalimpia, que estaba presente, cuenta cómo terminó. El Gran Cruzado pactó con Kel'Thuzad y el propio hijo de Mograine, Renault, lo condujo a una emboscada en Stratholme. Mientras la Plaga los cercaba y la hoja comenzaba a brillar, Renault la recogió y se la hundió a su padre por la espalda. '¿Qué has hecho, Renault?' fueron las últimas palabras del alto señor. El hombre y la hoja habían sido uno, y el asesinato corrompió a ambos. Mograine se alzó como caballero de la muerte de Kel'Thuzad." },
        { "Ribalimpia escapó de Stratholme tras pasar dos días entre los muertos y contó la historia a quien quisiera escucharlo en el Monasterio. Por ello lo asesinaron y lo ocultaron en su catedral. Pero algunos lo oyeron, dice, y así nació El Alba Argenta. Ahora Renault dirige el Monasterio como comandante Escarlata." },
      },
    },
    ["the-badlands"] = {
      title = "Tierras Inhóspitas",
      text = {
        { "Al sur de Loch Modan, el terreno se abre en Tierras Inhóspitas: roca roja, cañones secos, mesetas y polvo, sin apenas árboles ni arroyos. Los buitres dan vueltas, los coyotes merodean, los ogros del clan Rotapolvo dominan las colinas y los dragones negros anidan en el Barranco Lethlor, al este." },
        { "Los enanos vienen de todos modos, porque bajo Tierras Inhóspitas está Uldaman, la bóveda de los titanes. La Liga de Expedicionarios lleva años excavando ante sus puertas. También los Hierro Negro, desde su fortaleza de Angor, y los troggs que salieron de ella. La Horda tiene aquí un campamento, en Kargath, para vigilar a los Hierro Negro. Es un yermo concurrido." },
      },
    },
    ["the-barrens"] = {
      title = "Los Baldíos",
      text = {
        { "Los Baldíos son la gran sabana del corazón de Kalimdor: un mar de hierba amarilla y árboles espinosos bajo un cielo inmenso, con manadas de cebras y kodos, leones y raptores, y unos pocos oasis preciosos donde todo lo que vive aquí acude a beber. Es una tierra calurosa, seca y enorme que pertenece, hasta donde puede decirse, a quien domine el siguiente abrevadero." },
        { "Eso son muchísimos grupos. La Horda ocupal Cruce, en su centro, y los caminos cercanos. Los goblins dominan Trinquete, en la costa. La Alianza conserva el Fuerte del Norte al este y una excavación enana al sur. Los centauros atacan desde las colinas, los jabaespines ocupan las madrigueras espinosas del sur, las arpías anidan en las quebradas y el Filo Ardiente y Ventura y Cía. tienen sus campamentos. El viajero de Los Baldíos aprende a beber cuando puede y a dormir con un ojo abierto." },
      },
    },
    ["the-battle-of-mount-hyjal"] = {
      title = "La batalla del Monte Hyjal",
      text = {
        { "Cuando volvió la Legión Ardiente, vino por el Árbol del Mundo. Archimonde, que había dirigido sus huestes diez mil años antes, fue invocado de nuevo en Dalaran y siguió a la Plaga por mar hasta Kalimdor, decidido a alcanzar Nordrassil en la cima del Monte Hyjal." },
        { "Un profeta se adelantó: Medivh, último Guardián, vuelto de más allá de la muerte para reparar sus faltas. Instó a humanos y orcos a zarpar juntos al oeste. Como ninguno quiso oírlo, los llevó por separado, con profecías y engaños. La Horda de Thrall cruzó Los Baldíos y encontró aliados en los tauren de Cairne Pezuña de Sangre. Jaina Valiente trajo a los supervivientes de Lordaeron. En los bosques encontraron a los elfos de la noche, cuya sacerdotisa Tyrande Susurravientos había despertado a Malfurion Tempestira y a sus druidas de su largo sueño." },
        { "En la montaña, tres pueblos que nunca habían confiado unos en otros lucharon juntos, cediendo terreno despacio mientras Malfurion preparaba su trampa. Cuando Archimonde alcanzó el Árbol del Mundo, los espíritus del bosque lo rodearon y el poder del propio Árbol se consumió para destruirlo. Perdida su bendición, los elfos de la noche perdieron la inmortalidad que habían tenido durante diez mil años." },
        { "La paz de Hyjal aún se mantiene en Durotar y Theramore, aunque no todos a ambos lados se alegran de ello." },
      },
    },
    ["the-battlefields"] = {
      title = "Los campos de batalla",
      text = {
        { "Tres piezas de batalla pertenecen a los lugares donde siempre hay alguien luchando: la Mina Pedrusco en Los Baldíos, la Fortaleza del Hacha de Trueno en Desolace, el Castillo de Fenris en el Bosque de Argénteos, las Ruinas de Alterac, el Bastión Machacamiedo en Las Tierras Devastadas y toda la Cuenca de Arathi, entre otros lugares. El Filo Ardiente guarda en la Fortaleza del Hacha de Trueno la reliquia que abre sus portales demoníacos en el Aquelarre Mannoroc. En la Cuenca de Arathi, la Liga de Arathor y los Rapiñadores se disputan cada granja y cada mina." },
      },
    },
    ["the-broken-alliance"] = {
      title = "La Alianza quebrada",
      text = {
        { "La Alianza de Lordaeron ganó la Segunda Guerra y no sobrevivió a la paz. La Horda había arrasado Khaz Modan, la mitad de las provincias de Lordaeron y los límites de Quel'Thalas. Había que reconstruir lo que quedaba y mantener en algún lugar a los orcos rendidos. El rey Terenas eligió la clemencia y construyó campos para ellos. Algunos reyes habrían preferido ejecutarlos y todos pagaron impuestos para mantenerlos." },
        { "Después escapó Martillo Maldito y cada reino sospechó de la incompetencia de los demás. Un noble llamado lord Prestor llegó a la corte de Terenas ofreciendo ayuda, enfrentó a los señores entre sí y casi consiguió con sus palabras el trono vacío de Alterac. Era Alamuerte y, cuando se supo, el daño estaba hecho." },
        { "Uno a uno, los reinos siguieron su camino. Gilneas se encerró tras la Muralla de Cringrís. Stromgarde se retiró. Los altos elfos de Quel'Thalas, a quienes la guerra nunca había importado demasiado, abandonaron por completo la Alianza. Pocos seguían fieles a Terenas cuando llegó la peste y para entonces podía pedirles poco." },
      },
    },
    ["the-bulwark"] = {
      title = "El Baluarte",
      text = {
        { "El Baluarte es el muro que los Renegados han levantado en el extremo oriental de Tirisfal, donde terminan los claros y empiezan las Tierras de la Peste. Se defiende día y noche frente a la Plaga. Los guardias de la Muerte custodian su puerta y los oficiales del Alba Argenta también mantienen un puesto allí, lo que indica cuánto temen ambos lo que hay más allá." },
        { "En El Baluarte hay cosas más extrañas. Alexi Barov, el último de una casa noble de Lordaeron que vendió su castillo al Culto de los Malditos, se reúne allí con los Renegados. Tiene opiniones sobre la fortuna familiar que comparte de buen grado." },
      },
    },
    ["the-burning-lands"] = {
      title = "Las tierras ardientes",
      text = {
        { "La Montaña Roca Negra, las Estepas Ardientes y la Garganta de Fuego son el mismo fuego visto desde tres lados. Los enanos Hierro Negro tienen la Garganta de Fuego, y Ragnaros tiene el corazón de la montaña. No me quedaría mucho rato en ninguno de ellos." },
      },
    },
    ["the-cauldron"] = {
      title = "La Caldera",
      text = {
        { "La Caldera es la gran mina a cielo abierto de los Hierro Negro en La Garganta de Fuego, rodeada de máquinas excavadoras y explotada en el calor con trabajo esclavo. Algunos cautivos han sido llevados a tal locura que atacan incluso a quienes intentan liberarlos." },
        { "La Excavación de Limugre, menor, está al sureste. Bajo la gran fosa, el sobrestante Maltorius manda en La Fosa de la Escoria, tras abandonar la Hermandad del Torio para volver con sus antiguos amos. En Limugre también hay una letrina con llave. Los asuntos de un viajero en estas tierras pueden implicar encierros de tipos muy distintos." },
      },
    },
    ["the-charger"] = {
      title = "El destrero",
      text = {
        { "El destrero de un paladín no se compra ni se cría. Hay que recuperarlo. Lord Grisillo Quiebrasombras, que guía a los caballeros de la orden hasta sus destreros desde el Distrito de la Catedral de Ventormenta, les advierte de que la tarea pondrá a prueba dos cosas por encima de todo, el sacrificio y el juicio, y de que nada de ello es un ejercicio de escuela: su futuro compañero está en manos del mal contra el que han luchado toda la vida." },
        { "El sacrificio empieza con monedas, pagadas al Sumo Sacerdote Rohan de Forjaz por su incensario de exorcismo. El juicio empieza en el Valle del Terror, en las Tierras de la Peste del Este, adonde se lleva el incensario, sazonado con una pizca de la tierra corrupta del lugar, para recorrer con él a los espíritus atormentados y expulsarlos. La barda viene de Grimand Elmore, del Distrito de los Enanos de Ventormenta, uno de los mejores armeros vivos según Grisillo, y el mejor según él mismo. La bendición la da un Antiguo espíritu equino al que el antárbol corrupto Tendris Alabeo retiene en La Masacre. Una vez muerto el antárbol, aún hay que alimentar al espíritu antes de que la conceda." },
        { "El destrero en sí está en Scholomance. Sus huesos yacen en el Gran Osario, y el Caballero de la Muerte Atracoscuro cabalga lo que queda de su alma. Un arúspice construido en torno al mismo incensario hace surgir allí a los espíritus, y tras ellos al caballero de la muerte, y cuando este cae, el paladín le devuelve al destrero su alma. De todas las monturas que he registrado, es la única a la que primero hay que salvar." },
      },
    },
    ["the-chromatic-flight"] = {
      title = "El Vuelo Cromático",
      text = {
        { "Vaelastrasz, que se presenta a los viajeros de la Cumbre de Roca Negra como Vaelan, cuenta que antes de su destierro Alamuerte intentaba criar una descendencia propia: mestizos inmunes a los poderes de los Aspectos y sometidos por completo a su control. Fracasó. Su hijo Nefarian, a juzgar por lo que se arrastra por la parte alta de la Cumbre, lo ha logrado al menos en parte. Las abominaciones salieron a la luz gracias a Ysera, el Aspecto de los Sueños, y ella no dejó que los dragones se quedaran de brazos cruzados." },
        { "Awbee, una joven cría del Vuelo Azul que sus captores retienen en la Cumbre, sabe cómo los hacen. Unos jinetes montados en dragones negros, cuenta, caían de noche sobre los nidos y se llevaban a crías como él. Vio a sus propios hermanos acabar en los experimentos de Nefarian, y fue su esencia la que dio origen al Vuelo Cromático. Nefarian quería ver muertos cuanto antes a los que no le servían. Sus guardianes se divertían antes con ellos, y lo que quedaba acababa en la lava o en manos de la legión que aguardaba abajo." },
        { "Lo que resultó de aquello puede hallarse en la parte alta de la Cumbre y en la guarida que hay sobre ella: crías y dragauros con los colores de todos los vuelos, dracónidos criados a partir de cada uno de los cinco, y Chromaggus, el mayor de todos, en lo más hondo de la Guarida de Alanegra. La sangre de los cinco vuelos se usó para esta progenie, y solo el Vuelo Negro tuvo voz en ello." },
      },
    },
    ["the-crossroads"] = {
      title = "El Cruce",
      text = {
        { "Los grandes caminos de Los Baldíos se encuentran en El Cruce: al norte hacia Orgrimmar, al oeste hacia Mulgore, al este hacia Trinquete y al sur hacia Las Mil Agujas. La Horda mantiene aquí una empalizada, una posada y un posadero de dracoleones, con una guarnición al servicio del tránsito entre ellos." },
        { "La actividad de los centauros y los suministros robados dan trabajo a esa guarnición más allá de sus muros. Sergra Espinoscura también ofrece pruebas de caza." },
      },
    },
    ["the-crusades-fallen"] = {
      title = "Los caídos de la Cruzada",
      text = {
        { "El Monasterio Escarlata entierra a sus héroes en su propio cementerio y sus lápidas dicen más de la Cruzada que sus sermones. Léelas y descubrirás que nunca fue solo una orden humana de Lordaeron: un gran mago y una capitana forestal de Quel'Thalas, asesinos de Dalaran, un guerrero de Alterac, un señor de las Cavernas Rojas, un almirante de Kul Tiras." },
        { "Sigue leyendo y verás hasta dónde llegó. Orman de Stromgarde, su primer capitán general, desapareció en la entrada del Glaciar Corona de Hielo. El gran almirante de la Flota Escarlata se perdió frente a la costa helada de Rasganorte, y el primer asesino jefe, en sus orillas. La Cruzada llevó la guerra hasta la puerta del Rey Exánime. Lo que volvió fueron estas lápidas." },
        { "Otros cayeron más cerca de casa: un alto abad muerto defendiendo el propio Monasterio, un defensor que murió al matar a un señor del terror, un elfo atrapado en un combate interminable con un nigromante. Sea lo que sea aquello en lo que se ha convertido la Cruzada, estas fueron las personas que creyeron en ella primero, $gviajero:viajera;." },
        { side = "Horde", aside = true, sign = "P. F.", "También he leído esas lápidas. Mi interpretación fue menos generosa." },
      },
    },
    ["the-dark-portal"] = {
      title = "El Portal Oscuro",
      text = {
        { "El Portal Oscuro es una gran puerta de piedra entre nuestro mundo y Draenor, el mundo de los orcos. El brujo Gul'dan lo abrió desde el otro lado y el Guardián Medivh lo ayudó desde el nuestro. Por él llegó la Horda hace unos veinticinco años. La Primera Guerra, la Segunda y todo lo que vino después entraron por esa puerta." },
        { "Tras la Segunda Guerra fue destruido y Ner'zhul lo abrió de nuevo en busca de mundos que conquistar. Una expedición de la Alianza, bajo Khadgar y Turalyon, lo atravesó hacia Draenor para acabar con la amenaza y destruyó el Portal desde el otro lado, cortando su regreso a Azeroth. Su gran armazón de piedra sigue en mitad del yermo, con el paso inactivo y demonios reunidos alrededor." },
      },
    },
    ["the-dark-woods"] = {
      title = "Los bosques sombríos",
      text = {
        { "El Bosque del Ocaso, el Paso de la Muerte, los Claros de Tirisfal y el Bosque de Argénteos comparten una sola melodía, y ninguno de ellos es un lugar cómodo donde quedarse. Tirisfal era la campiña de Lordaeron antes de que llegara la plaga, y hoy la guardan los Renegados. Nunca he discutido a los Renegados la elección de su hogar." },
      },
    },
    ["the-deadmines"] = {
      title = "Las Minas de la Muerte",
      text = {
        { "Las Minas de la Muerte abastecían de oro a Ventormenta. Abandonadas cuando llegaron los orcos, se convirtieron en la guarida de un ogro durante la Primera Guerra. Sir Anduin Lothar entró para recuperar un libro sagrado robado en Villanorte y acabó prisionero. Los soldados de Ventormenta rescataron tanto al caballero como al libro." },
        { "Desde entonces, los Defias han excavado más hondo. En sus galerías hay ingenieros goblins, una fundición y una trituradora. Bajo los antiguos pozos, una cala oculta alberga un gran buque de guerra en construcción. Los planes de VanCleef van mucho más allá de robar en las granjas. Si bajas, prepárate para algo bastante mayor que una mina abandonada, $gviajero:viajera;." },
      },
    },
    ["the-dreadsteeds-of-xoroth"] = {
      title = "Los corceles nefastos de Xoroth",
      text = {
        { "Los corceles nefastos viven en otro mundo, las llanuras ardientes de Xoroth, que Hel'nurath, un señor de los demonios, considera suyas, y el brujo que quiera uno tiene que abrirse paso hasta allí y tomarlo. Mor'zul Sangredoble, que acampa junto al Altar de la Tempestad en Las Estepas Ardientes, vende ese saber a un precio que se paga en sangre, sudor y buena cantidad de oro." },
        { "Los glifos se escriben con la sangre de las lechubestias de Cuna del Invierno, enloquecidas por los demonios de la Garganta Negro Rumor. El sirviente de Mor'zul, Gorzeeki Ojosalvajes, un alquimista goblin que prefiere la sangre todavía caliente dentro de un roedor, hace el resto con lo que el brujo le trae: una campana que lleva el nombre del difunto brujo Dethmoora Darkeyes, una rueda y una vela para el círculo y una piedra imán de arcanita que lo sostenga todo. El pergamino necesita polvo estelar xorotiano, que solo el señor del terror Pesadilla, en la sede del Consejo de la Sombra en Jaedenar, puede proporcionar, y no a cambio de nada. Quería el corazón de su propio sirviente Ulathek, que espiaba para Hel'nurath. Pensaba comérselo cuando llevara una semana pudriéndose. Después, el polvo pasa al papel gracias a un diablillo en un tarro, al que se suelta en el laboratorio de alquimia de Scholomance." },
        { "El ritual se celebra en La Masacre: un Círculo de invocación superior, el pergamino, un portal a Xoroth, y por él llega algo que hay que vencer antes de que su espíritu se doblegue. Un señor demoníaco, un señor del terror, el Consejo de la Sombra y ese diablillo tienen parte en ello. Lo dejo escrito porque es verdad, $gviajero:viajera;, no porque lo recomiende." },
      },
    },
    ["the-dry-caves"] = {
      title = "Las cuevas secas",
      text = {
        { "La Cueva Viento Seco en Durotar, la Guarida Malapluma en Las Mil Agujas, la Guarida de Shalzaru en Feralas: una sola melodía para los agujeros de la tierra seca y para quien se haya instalado en ellos. En la Guarida de Shalzaru fueron los naga, que cavaban en busca de una reliquia que su Lord Shalzaru encontró antes de que nadie pudiera detenerlo." },
      },
    },
    ["the-dry-lands"] = {
      title = "Las tierras secas",
      text = {
        { "Polvo y espinos, de los Baldíos a las Tierras Inhóspitas, y de ahí a las Tierras Devastadas, Desolace y la Sierra Espolón: una sola melodía para todo. Los orcos hicieron suyos los Baldíos después de la guerra de la Horda, y las Tierras Devastadas aún llevan la cicatriz del Portal Oscuro. Es una comarca disputada más a menudo que la mayoría." },
      },
    },
    ["the-embalmer"] = {
      title = "El Embalsamador",
      text = {
        { "Los niños de Villa Oscura conocen la historia del Embalsamador: un alquimista bondadoso cuya esposa, Eliza, murió, y que se negó a dejarla ir. Con magia oscura puso su propio corazón en el pecho de ella y la devolvió a la vida con hambre de carne humana, por lo que tuvo que mantenerla enterrada." },
        { "No es un cuento infantil. El Embalsamador es el viejo ermitaño Abercrombie, que vive en una cabaña sobre el Cerro del Cuervo, y su esposa aún espera en su tumba. Su último regalo a Villa Oscura fue Puntos, un monstruo cosido con los muertos, enviado a tambalearse por el camino hasta la villa. La Guardia Nocturna recuerda la noche en que llegó." },
      },
    },
    ["the-emerald-dream"] = {
      title = "El Sueño Esmeralda",
      text = {
        { "El Sueño Esmeralda es un mundo espiritual fuera del de la vigilia, inmenso y cambiante, desde el que Ysera la Soñadora guía el crecimiento de todo ser salvaje. Los druidas lo recorren por un pacto antiguo, posterior al Gran Cataclismo, cuando los elfos de la noche plantaron un Árbol del Mundo en el Monte Hyjal." },
        { "Tres dragones bendijeron aquel árbol. Alexstrasza puso la bellota en las aguas del nuevo Pozo de la Eternidad. Nozdormu prometió que, mientras siguiera en pie, los elfos de la noche no envejecerían ni enfermarían. Ysera lo vinculó a su Sueño. El precio era el sueño de los druidas. Malfurion y sus seguidores aceptaron hibernar durante siglos mientras sus espíritus recorrían los caminos del Sueño y cumplieron el pacto." },
        { "Por eso los túmulos del Claro de la Luna están llenos de durmientes y un druida que ha recorrido el Sueño puede despertar con el aspecto de un viajero que vuelve de muy lejos. Últimamente han despertado inquietos. Algo oscuro ha entrado en el Sueño y Rémulos, custodio del Claro de la Luna, no dice qué." },
      },
    },
    ["the-fall-of-quelthalas"] = {
      title = "La caída de Quel'Thalas",
      text = {
        { "Durante miles de años, los altos elfos conservaron su reino en los bosques al norte de Lordaeron, tras un anillo de piedras rúnicas, con la Fuente del Sol en su corazón. En la Tercera Guerra, el príncipe Arthas llegó al frente de la Plaga." },
        { "Venía por un cadáver. El espíritu de Kel'Thuzad le dijo que solo podía resucitar al nigromante en las aguas de la Fuente del Sol, así que Arthas asedió Quel'Thalas. Sylvanas Brisaveloz, general forestal de Lunargenta, lo combatió con todo lo que tenían los elfos y perdió. Arthas la alzó como alma en pena para servirlo, se abrió paso hasta la Fuente y hundió en ella los restos de Kel'Thuzad. El exánime se alzó. Las aguas quedaron contaminadas." },
        { "Cuando la Plaga volvió al sur, dice el libro, no quedaba un solo elfo vivo en Quel'Thalas. No es del todo cierto: unos pocos aún conservan el Refugio Quel'Lithien en el borde de las Tierras de la Peste y otros mantienen una avanzada en Tierras del Interior. Pero está lo bastante cerca de la verdad como para que yo no discutiera el detalle con ellos." },
      },
    },
    ["the-fallen-hero"] = {
      title = "El héroe caído",
      text = {
        { "Fuera de Rocal está el fantasma de un héroe de la Horda que espera órdenes. En vida condujo a sus guerreros a Las Tierras Devastadas sin esperarlas y encontró lo que las órdenes le habrían advertido: el demonio Razelikh y sus lugartenientes, que capturaron a sus hombres y ataron sus espíritus a piedras de tormento." },
        { "Se culpa de todo y cuenta su historia a quien se detenga a escucharla. Quiere liberar a sus hombres y destruir a Razelikh, y ayudará a cualquier viajero que lo intente, de la Horda o de la Alianza. Es lo único que aún puede hacer." },
      },
    },
    ["the-fel-woods"] = {
      title = "Los bosques viles",
      text = {
        { "Frondavil, el Barranco del Demonio en Vallefresno y el Aquelarre Mannoroc en Desolace comparten una melodía y una historia. Los demonios llegaron a Kalimdor y dejaron su marca en la tierra, y en Frondavil los sátiros Fuego de Jade y los cultores de Jaedenar la mantienen viva. El monumento de Grom Grito Infernal se alza en el Barranco del Demonio. Se enfrentó solo a Mannoroth, y la Horda ve en su sacrificio el fin de la maldición de los orcos." },
      },
    },
    ["the-felstones"] = {
      title = "Los Piedra Mácula",
      text = {
        { "El fantasma de Janice Piedra Mácula ronda un rincón del piso de arriba de su casa, en el Campo de Piedramácula, presa de un pánico que dura ya cuatro años. Tenía un paquete que enviar y pensaba salir a caballo con él, y la peste llegó antes. El paquete seguía en el granero, donde había estado su caballo, polvoriento y con la dirección escrita a toda prisa. Contenía sus objetos personales y la escritura de la granja." },
        { "Adónde fue depende de quién lo llevara. Según la Alianza, iba dirigido a su hermana Emma, en Ventormenta, y el censo la encontró allí: la Vieja Emma, que vaga por la ciudad hablando sola y llevaba años sin oír su propio nombre. Según la Horda, iba para su hermano Jeremiah, en Lordaeron, que murió, se levantó y hoy vende cucarachas cerca del banco de Entrañas con el nombre de Payson. Tengo los dos relatos y he dejado de intentar conciliarlos. En cualquier caso, en el paquete iba la mitad de un talismán de la suerte, y su hermano o su hermana se la devolvió." },
        { "Janice tenía una mitad y su marido John la otra. Todavía lo llama. La otra mitad apareció en la granja, en uno de los necrófagos. Cuando las dos mitades se unieron y se las pusieron a ella en la mano, miró por primera vez a quien se las tendía y dijo que era libre. No he preguntado qué necrófago era." },
        { side = "Horde", aside = true, sign = "P. F.", "Jeremiah Payson vende sus cucarachas a buen precio y sin trampa. Lo que fuera antes es asunto suyo, y le pido a la historiadora de la Alianza que le deje el nombre que eligió." },
      },
    },
    ["the-fire-below"] = {
      title = "El fuego de las profundidades",
      text = {
        { "La Roca Machacamiedo, la Fosa de la Escoria en La Garganta de Fuego, el Cubil de la Llama en el Marjal Revolcafango y las profundidades de la Montaña Roca Negra: esta es la melodía de los lugares ardientes bajo tierra. Los ogros ocupan varios, lo que dice mucho de los ogros. Los orcos de Kargath mandan gente a la Roca Machacamiedo en busca de un aro de nariz, lo que dice mucho de los orcos." },
      },
    },
    ["the-first-war"] = {
      title = "La Primera Guerra",
      text = {
        { "Los orcos llegaron por el Portal Oscuro unos pocos clanes cada vez a los pantanos al este de Ventormenta. Durante años, el reino solo los conoció por sus incursiones. El rey Llane no creía que esas criaturas pudieran tomar su ciudad. Su campeón Anduin Lothar, último del linaje Arathi, estaba menos seguro, y aún menos de su viejo amigo Medivh, cuya torre de Karazhan se había vuelto muy oscura." },
        { "Lothar actuó según sus dudas. Con Khadgar, joven aprendiz de Medivh, asaltó Karazhan y mató al Guardián. Descubrió que Medivh había estado detrás de la invasión desde el principio. No salvó al reino. La Horda, bajo un nuevo Jefe de Guerra, Orgrim Martillo Maldito, asedió el Castillo de Ventormenta. Garona, asesina semiorca del Consejo de la Sombra, mató a Llane dentro de sus propios muros." },
        { "Lothar volvió a una ciudad en ruinas humeantes y juró con los hombres que le quedaban recuperarla. Condujo a los supervivientes de Azeroth por mar a Lordaeron para pedir ayuda a los demás reinos humanos. La alianza que formaron libraría la Segunda Guerra. Ventormenta fue reconstruida después. Su pueblo no ha vuelto a subestimar a un enemigo." },
      },
    },
    ["the-five-aspects"] = {
      title = "Los cinco Aspectos",
      text = {
        { "Antes de abandonar el mundo, los titanes eligieron a cinco vuelos de dragones para vigilarlo y dieron a sus dirigentes una parte de su propio poder. Esos cinco dragones se convirtieron en los Aspectos." },
        { "Aman'Thul confió al bronce Nozdormu el cuidado del propio tiempo: es el Atemporal. Eonar dio a la roja Alexstrasza el cuidado de todo ser vivo y, con él, la corona de su especie. A la hermana menor de Alexstrasza, la verde Ysera, le dio los lugares salvajes. Ysera cayó en un trance desde el que aún los vigila, en el Sueño Esmeralda. Norgannon dio al azul Malygos el cuidado de la magia. Khaz'goroth, hacedor del mundo, dio al negro Neltharion la tierra y sus profundidades. El Guardián de la Tierra era el mayor apoyo de Alexstrasza." },
        { "Sabrás cómo acabó ese último. Neltharion forjó el Alma demoníaca para dominar a los demás vuelos y la volvió contra ellos en la Guerra de los Ancestros. Desde entonces, el mundo lo llama Alamuerte. El Vuelo de Malygos casi fue exterminado. Eras después, el mismo disco encadenó a la propia Reina de los Dragones en Grim Batol." },
        { "Cinco guardianes fueron puestos sobre el mundo, $gviajero:viajera;. Uno se convirtió en aquello de lo que lo protegen los demás." },
      },
    },
    ["the-forsaken"] = {
      title = "Los Renegados",
      text = {
        { "Cuando flaqueó el control del Rey Exánime sobre sus muertos, algunos despertaron. Seguían muertos, pero volvían a ser dueños de su mente y recordaban lo que habían sido y lo que les habían hecho. Se llaman los Renegados y siguen a quien los liberó: Sylvanas Brisaveloz, la Reina alma en pena." },
        { "Han recuperado las ruinas de la capital de su reino y construido una ciudad debajo. Libran su propia guerra contra la Plaga que los creó. Se han unido a la Horda, que necesitaba aliados contra la Alianza, y la Horda los ha aceptado, algo que los Renegados necesitaban aún más. No es una amistad cálida." },
        { "No fingiré que los Renegados sean una compañía sencilla. La mayoría fueron hombres y mujeres de Lordaeron que recuerdan sus antiguas vidas y no pueden volver a ellas. Qué quieren ahora, más allá de vengarse del Rey Exánime, nadie fuera de Entrañas puede decirlo." },
        { side = "Horde", aside = true, sign = "P. F.", "Nadie fuera de Entrañas puede decir qué queremos, escribe. La mayoría de los de dentro tampoco. Yo quiero saber qué nos hicieron y dejarlo debidamente por escrito." },
      },
    },
    ["the-furbolg-dens"] = {
      title = "Los poblados furbolg",
      text = {
        { "Frondavil y Vallefresno tienen sus poblados furbolg, la Aldea Muertobosque, el Poblado Zarpavil y el Poblado Piel de Cardo, y todos comparten una melodía. La magia vil corrompió a la mayoría de los furbolg de estos bosques. Los Fauces de Madera se libraron de él, y defienden su bastión entre Frondavil y Claro de la Luna de sus propios parientes caídos." },
      },
    },
    ["the-graveyards"] = {
      title = "Los cementerios",
      text = {
        { "El Cementerio del Cerro del Cuervo y el Cementerio del Jardín Sereno en el Bosque del Ocaso, Rémol y los Molinos de Agamand en Tirisfal, la Tumba de Uther y las Ruinas de Andorhal: esta melodía no se aleja de los lugares donde se entierra a los muertos, ni de algunos donde no se quedaron enterrados. Los Agamand de Tirisfal son un buen ejemplo. He leído una de sus cartas, y prefiero no cruzarme con la familia." },
      },
    },
    ["the-great-hunts"] = {
      title = "Las grandes cacerías",
      text = {
        { "Los tauren dan nombre a las grandes bestias de Los Baldíos, y cazar una es tanto una lección como una prueba. Sergra Espinoscura pone a los viajeros en ese camino en El Cruce, y Jorn Vidente del Cielo, en el Campamento Taurajo, y Mahren Videncielo, en la costa al sur de Trinquete, los llevan más allá. Lo sé por quienes lo recorrieron y por los propios nombres tauren, que dicen más de lo que dirían nuestros nombres." },
        { "Echeyakee, Albineblina, es el rey de los felinos de la sabana, tan sigiloso al cazar que sus presas no tienen tiempo de sentir miedo ni dolor: muerte y misericordia a la vez, dicen los tauren. Tiene su guarida entre los huesos de kodos gigantes, al noreste de El Cruce, y acude al sonido de un cuerno. Ishamuhale, Dientarpón, es el más feroz de los raptores solescama de las llanuras, que mata porque matar es su naturaleza, y acude a los despojos frescos de una astacebra dejados junto a un árbol muerto. Lakota'mani, Sacuditerra, es un gran kodo cuyos pasos retumban como el trueno. Washte Pawne, Muerdespíritu, es un halcón trueno cuya muerte puede traer gran fortuna o una terrible condena, y cuya pluma duele al tocarla. Isha Awak, la Condena Abisal, es el señor de las aguas frente a la costa, y los humanos de esa costa tienen buenos motivos para temerlo." },
        { "Lo que trae el cazador es un colmillo, una pezuña, una pluma o un corazón, y con ello, dicen Jorn y Mahren, algo de la bestia: la fuerza de la sutileza y el honor de la misericordia, una fuerza contenida por la templanza, el valor, la sabiduría en que se convierte el remordimiento, y unos ojos que, algún día, aprenderán a ver. Los enanos cazamos para comer y para presumir. No estoy segura de que se nos haya ocurrido nunca preguntarle al jabalí qué tenía que enseñarnos." },
      },
    },
    ["the-guardians-of-tirisfal"] = {
      title = "Los Guardianes de Tirisfal",
      text = {
        { "Dalaran aprendió pronto el precio de la magia. Sus jóvenes magos gastaban poder sin medida y cuanto más gastaban, más delgado se volvía el mundo alrededor de la ciudad, hasta que pequeños demonios de la Legión Ardiente empezaron a filtrarse. Los magócratas que la gobernaban ocultaron lo que pudieron. Cuando el pueblo empezó a hablar de revolución, acudieron a los elfos de Quel'Thalas en busca de ayuda." },
        { "Los elfos les explicaron qué era la Legión y lo que ya había hecho al mundo. El Consejo de Lunargenta y los magócratas sellaron un pacto secreto: un campeón mortal, dotado de la fuerza combinada de la magia élfica y humana, combatiría a los agentes de la Legión en una guerra de la que nadie debía saber nada. Un consejo oculto, reunido en los claros de Tirisfal donde los elfos se asentaron por primera vez en Lordaeron, elegía a cada Guardián. Cuando envejecía o se cansaba, transmitía el poder bajo su cuidadoso control." },
        { "Funcionó durante generaciones. Después eligieron a Aegwynn, que no tenía interés en ser controlada. Derrotó al avatar del propio Sargeras en el norte helado y creyó haber acabado con él. Casi novecientos años después, negándose a que el Consejo nombrara a su sucesor, tuvo un hijo para que heredara su poder. Lo llamó Medivh, 'guardián de los secretos' en la lengua de los altos elfos. Lo que guardó se cuenta en Karazhan." },
        { "Una orden que mantiene su guerra en secreto para todo el mundo difícilmente puede ser corregida cuando se equivoca, $gviajero:viajera;. El Consejo lo aprendió demasiado tarde." },
      },
    },
    ["the-haunted-rooms"] = {
      title = "Las salas encantadas",
      text = {
        { "Esta pieza espera en algún rincón de tres edificios que no comparten nada más: el Mesón Aguahonda en el Puerto de Menethil, el Mesón La Horca en Rémol y Las Reservas en la Vega de Tuercespina. También recibe a quien llega a la Finca de Olsen, en el Bosque de Argénteos, y a Jaedenar, en Frondavil. He buscado lo que los une, y no lo he encontrado." },
      },
    },
    ["the-hidden-places"] = {
      title = "Los lugares ocultos",
      text = {
        { "Esta melodía aparece en lugares que tienen poco en común: el Pico Nidal de los enanos Martillo Salvaje, el templo Vilrama de Jintha'Alor, La Grieta en Teldrassil, la orilla de Loch Modan. Otro es la Torre de Ilgalar, en las Montañas Crestagrana, donde vive el mago Morganth. Su rival lo llama cruel, y no he ido a comprobarlo." },
      },
    },
    ["the-high-mountains"] = {
      title = "Las altas montañas",
      text = {
        { "Dun Morogh, las Tierras Altas de Arathi y Cuna del Invierno comparten todas esta melodía, y confieso que no soy imparcial con la primera. Las Tierras Altas de Arathi albergaron en otro tiempo la capital de Thoradin, cuando Arathor gobernaba las tierras humanas. Cuna del Invierno no guarda más que nieve y mucha paciencia." },
      },
    },
    ["the-high-order"] = {
      title = "La Orden Eminente",
      text = {
        { "La Orden Eminente reúne a los shen'dorei fieles a lo arcano y a su ascendencia entre los eruditos Altonato de Eldre'Thalas. Cuando se marcharon los espíritus del viento, extrajeron una dura lección: su pueblo había dependido tanto de sus protectores elementales que sin ellos estaba indefenso. La Orden quiere recuperar los conocimientos perdidos de sus antepasados y sostenerse por sí misma. Su magíster supremo, Elaadrin Vendaval del Atardecer, mira al Kirin Tor de Dalaran para aprender cómo." },
        { "Los Formavientos los llaman imprudentes y arrogantes. La Orden Eminente lo llama hipocresía. Han pagado por su confianza. Elaadrin envió a Belathaan Deseo Claro a negociar con los Al'Aketh en el Santuario de Akir y Belathaan no regresó. El culto devolvió su lengua en una caja, bañada en plata. Después, Elaadrin admitió que los Formavientos habían tenido razón." },
      },
    },
    ["the-hinterlands"] = {
      title = "Tierras del Interior",
      text = {
        { "Al norte de Arathi están Tierras del Interior: altas colinas verdes, valles profundos, cascadas y bosque antiguo, una tierra salvaje que ningún rey ha gobernado de verdad. Aquí viven los enanos Martillo Salvaje, en Pico Nidal, con sus grifos. También los trols del bosque del antiguo imperio Amani, cuyos templos en ruinas coronan media comarca y cuyas tribus vivas aún dominan el resto." },
        { "Es una tierra hermosa y peligrosa. Lechubestias en los bosques, mocos en los pantanos, trols Secacorteza y Vilrama en las ruinas y, sobre el gran templo de Jintha'Alor, sacerdotes que aún sacrifican al dios de la sangre. Los jinetes de grifos de Pico Nidal lo vigilan todo desde el aire." },
      },
    },
    ["the-horde-outposts"] = {
      title = "Los puestos de la Horda",
      text = {
        { "El Cruce, el Campamento Grom'gol, el Puesto del Hachazo, el Aserradero Grito de Guerra y el Refugio Roca del Sol comparten una melodía. Son los fuertes de la Horda en los caminos, levantados allí donde hacía falta un muro, un maestro de vuelo y un cocinero. El Cruce está donde se juntan los caminos de Los Baldíos, y tarde o temprano todo el que anda por la región pasa por él." },
      },
    },
    ["the-inns"] = {
      title = "Las tabernas",
      text = {
        { "La Destilería Cebatruenos en Kharanos y la Pensión La Cebada en Loch Modan comparten una melodía, y el Mesón La Horca de los Renegados, en Rémol, tiene la suya. La primera vuelve a aparecer en algún rincón de Ventormenta, Forjaz, Villa del Lago, Dun Modr y el Mesón Aguahonda. Los Cebatruenos hacen buena cerveza, y a sus rivales se les ha visto colar un barril propio en su bodega. La Guardia de la Muerte de Rémol encierra a sus prisioneros en la bodega del Mesón La Horca, lo que es una excelente razón para beber en la planta de arriba." },
      },
    },
    ["the-jungle"] = {
      title = "La jungla",
      text = {
        { "La misma melodía cubre la Vega de Tuercespina, Feralas y las ruinas trol de Zul'Gurub y del Templo de Atal'Hakkar. Los trols Gurubashi gobernaron en otro tiempo esta jungla desde su gran ciudad. Su imperio ha desaparecido, los árboles no." },
      },
    },
    ["the-keeps"] = {
      title = "Las fortalezas",
      text = {
        { "El Castillo de Stromgarde en las Tierras Altas de Arathi, el Fuerte de Tiragarde en la costa de Durotar y el Cuartel de Arroyoeste en el Bosque de Elwynn llevan piezas de la música de Ventormenta, y Stromgarde saluda cada llegada con una más. Stromgarde fue el reino de los Aterratrols, y una tumba de los Aterratrols sigue en el castillo. Tiragarde es un fuerte de Kul Tiras levantado en la misma costa de los orcos. La Horda lo tomó una vez, y los hombres del almirante Valiente lo han recuperado." },
      },
    },
    ["the-lich-king"] = {
      title = "El Rey Exánime",
      text = {
        { "El Rey Exánime comenzó como un orco. Ner'zhul, el viejo chamán que primero condujo a su pueblo a la Legión, huyó al Vacío Abisal después de la última guerra de los orcos y Kil'jaeden lo esperaba. El demonio despedazó su cuerpo mientras mantenía vivo su espíritu y después le ofreció un último trato. Ner'zhul aceptó. Su espíritu quedó sellado en un bloque de hielo de los confines del Vacío y nació el Rey Exánime. Sus caballeros de la muerte y seguidores fueron rehechos como exánimes para servirlo." },
        { "Kil'jaeden arrojó el hielo al mundo. Cayó en el glaciar de Corona de Hielo, en Rasganorte, y quedó en forma de trono. Desde el Trono Helado, el Rey Exánime alcanzó las mentes del norte, primero trols de hielo y wendigos, y después una aldea humana al borde del Cementerio de Dragones, donde probó la peste destinada a Lordaeron. Los señores del terror lo vigilaban. Kil'jaeden no confiaba en nadie, menos aún en un prisionero." },
        { "Lo que vino después llena la mitad de este registro. El libro de nuestra biblioteca termina con el príncipe Arthas ascendiendo al Trono Helado y poniéndose el yelmo de Ner'zhul, fundiéndose ambos en uno. Dice que se rumorea que reconstruye la ciudadela de Corona de Hielo y que Kel'Thuzad gobierna las Tierras de la Peste en su nombre. La Liga no tiene ninguna expedición en Rasganorte y no veo motivos para iniciarla, $gviajero:viajera;." },
      },
    },
    ["the-living-forest"] = {
      title = "El bosque vivo",
      text = {
        { "La melodía de Teldrassil, el gran árbol que los elfos de la noche llaman hogar, continúa por los bosques de Vallefresno. Ambos pertenecen a un pueblo que cuenta sus años en milenios y que recorría estos bosques antes de que los enanos aprendieran a excavar." },
      },
    },
    ["the-lost-dwarves"] = {
      title = "Los enanos desaparecidos",
      text = {
        { "Cuando los troggs salieron de Uldaman, llegaron tan deprisa que parte de la gente de Forjaz quedó atrapada tras sus líneas. Baelog era uno de ellos. Amigo del prospector Pico Tormenta, de la Liga de Expedicionarios, había llevado a una pequeña cuadrilla al fondo de la excavación justo antes del ataque, y Pico Tormenta envió viajeros a averiguar si alguno seguía con vida." },
        { "Seguían vivos, y de buen humor. Olaf había apostado a que la barba le llegaría a las rodillas antes de que volvieran a ver un alma viva, y cuando llegó la ayuda aún le quedaba un buen trecho. Eric, llamado el Suave, era el tercero. Atrapado o no, Baelog no se había quedado de brazos cruzados. Su diario describe el camino hasta la cámara de Khaz'mul, tras una enorme puerta cerrada: tomar el medallón de Gni'kiv del cofre de Baelog, arrebatarle al trogg Revelosh el bastón de Tsol, unir ambos en el Bastón de Prehistoria y usarlo en el cuarto de mapas. Haz todo esto, escribió, y la cámara será tuya." },
        { "Baelog está seguro de que la cámara existe. Uldaman era de Forjaz antes de que llegaran los troggs, y la Liga de Expedicionarios no ha renunciado a recuperarla. A los viajeros de la Horda, la cuadrilla de Baelog los recibe con bastante menos alegría." },
      },
    },
    ["the-lost-ones"] = {
      title = "Los Perdidos",
      text = {
        { "Los exiliados del Puerto se llaman draenei. Con pezuñas, tentáculos y piel gris azulada, no se parecen a los demás pueblos que suele encontrarse un viajero en Azeroth. Dicen que llegaron del mundo de los orcos después de un viaje terrible. Los del Puerto siguen siendo amables y dispuestos a hablar." },
        { "Otros viven en Retiro Fangoso y reciben el nombre de Los Perdidos. Los exiliados dicen que el viaje quebró a sus antiguos hermanos. Atacan a quien se acerca y han robado cristales que los exiliados consideran sagrados. Estos relatos locales dicen poco de su vida anterior o de lo ocurrido antes de llegar aquí. Prefiero dejar abierta esa parte de la página a darles un pasado que no han descrito." },
      },
    },
    ["the-missing-diplomat"] = {
      title = "El diplomático desaparecido",
      text = {
        { "Ventormenta dice que su rey ha desaparecido. Unos pocos saben algo más, y la pista que siguieron empieza nada menos que en una quesería. El obispo DeLavey, del Castillo de Ventormenta, dio a entender con discreción que un diplomático enviado a reunirse con Lady Jaina Valiente en Theramore nunca había llegado, y que sospechaba de los Defias. Su viejo amigo Jorgen, en el Valle de los Héroes, pasó el asunto a Elling Trias, un quesero del Distrito de Mercaderes con una red de contactos asombrosamente amplia." },
        { "La pista pasó por una reunión de los Defias en la Granja de Addle, en el Bosque del Ocaso, y por un pendenciero del Casco Antiguo llamado Dashel Puñopiedra, y siguió al norte hasta el Puerto de Menethil, donde un antiguo agente metido a tabernero señaló a un hombre que escuchaba demasiado de cerca. Tapoke Jahn, al que llaman El Flaco, contó el resto en cuanto le dieron una paliza. Los Defias no se habían llevado a un diplomático. Se habían llevado al rey, de camino a una reunión secreta en Theramore. El papel de El Flaco había sido subir a su hombre a bordo del barco del rey mientras este estaba en el puerto: un tal soldado Hendel, uno de los hombres de la propia guarnición de Theramore. Y los Defias, dijo, trabajaban con alguien más grande que ellos." },
        { "A Hendel lo encontraron de guardia en el pantano, a las afueras de Theramore, y se lo llevaron de vuelta a la isla para interrogarlo. Ahí termina el relato. El rey no ha aparecido, y nadie ha dicho para quién trabajaban los Defias. Ventormenta sigue teniendo un niño en el trono y un regente a su lado." },
      },
    },
    ["the-moonwells"] = {
      title = "Los pozos de la luna",
      text = {
        { "La Poza de la Luna, en Vallefresno, y El Santuario de Aessina comparten esta melodía, que vuelve a aparecer en algún rincón de Darnassus y de Ventormenta. Aessina es uno de los espíritus de la naturaleza de los elfos de la noche. Su santuario está en lo hondo de Vallefresno, y Therysil espera allí noticias de su hermana." },
      },
    },
    ["the-ogre-mounds"] = {
      title = "Los túmulos de los ogros",
      text = {
        { "El Túmulo de Vul'Gol en el Bosque del Ocaso y el Poblado Murohelecho en el Marjal Revolcafango comparten una melodía y muchísimos ogros. Los Puñastilla de Vul'Gol atacan a quien se acerque. En el Poblado Murohelecho, los ogros Quebrantarrocas sirven al Señor Supremo Mok'Morkk, título que le dio Rexxar. Los dragones negros de la progenie de Onyxia los echaron de su antiguo hogar, y no todos los ogros de allí han perdonado a Mok'Morkk que huyera." },
      },
    },
    ["the-open-plains"] = {
      title = "Las llanuras abiertas",
      text = {
        { "Las granjas de los Páramos de Poniente, las colinas rojas de Durotar, la hierba de Mulgore y las Mil Agujas comparten una sola melodía, lo cual es pedir mucho a una sola canción para tantos pueblos. Los humanos aran los Páramos de Poniente, los orcos hicieron de Durotar su patria bajo Thrall, y los tauren recorren Mulgore desde mucho antes que unos y otros." },
      },
    },
    ["the-ordering"] = {
      title = "La ordenación de Azeroth",
      text = {
        { "El relato más antiguo de la biblioteca de la Liga empieza antes de que hubiera nadie para conservar uno. Los titanes, dice, iban de mundo en mundo poniéndolos en orden y llegaron por fin a este. Lo encontraron dominado por elementales que servían a amos más antiguos: los dioses antiguos." },
        { "El Panteón de los titanes les hizo la guerra. Cuatro grandes señores de los elementos dirigieron los ejércitos de los dioses antiguos: Ragnaros, el Señor del Fuego, Therazane, la Madre Pétrea, Al'Akir, el Señor del Viento, y Neptulon, el Cazamareas. Cayeron uno a uno. Las ciudadelas de los dioses antiguos fueron destruidas y los propios dioses, cinco, encadenados muy hondo bajo tierra. Sin sus amos, los elementales fueron desterrados a un plano propio para combatir entre sí eternamente." },
        { "Después trabajaron los titanes. Crearon terráneos de piedra viva para tallar las profundidades y gigantes marinos para alzar la tierra del mar. Al terminar había un continente, Kalimdor, y en su corazón un lago de poder brillante al que llamaron Pozo de la Eternidad." },
        { "Aún desenterramos sus obras en Uldaman y en los bancales de Tierras Inhóspitas. De vez en cuando también vuelve algo que enterraron: un Señor del Fuego bajo Roca Negra, un dios en las arenas de Silithus. Sospecho que los titanes dejaron el mundo más ordenado de lo que lo encontraron, pero no terminado." },
      },
    },
    ["the-plagued-lands"] = {
      title = "Las tierras de la plaga",
      text = {
        { "Las Tierras de la Peste del Oeste y las Tierras de la Peste del Este comparten esta melodía con el Monasterio Escarlata. La plaga empezó en el grano de Andorhal, y lo que hizo a las granjas del norte de Lordaeron aún se lee sobre el terreno. La Cruzada Escarlata es, a su manera, otro rostro de la misma herida." },
      },
    },
    ["the-sands"] = {
      title = "Las arenas",
      text = {
        { "Tanaris, Silithus y la ciudad trol de Zul'Farrak comparten una melodía, y mucha arena y mucho sol. En Silithus se alzan además las Puertas de Ahn'Qiraj, lo cual es una mala razón para visitarla y una excelente razón para escribir sobre ella." },
      },
    },
    ["the-scarab-wall"] = {
      title = "El Muro del Escarabajo",
      text = {
        { "Hace mil años, los qiraji y sus enjambres silítidos salieron de Ahn'Qiraj y cayeron sobre Kalimdor. Los elfos de la noche los combatieron en la Guerra del Mar de Dunas. No podían ganarla solos. Fandral Corzocelada, que los dirigía, perdió a su hijo Valstann ante los qiraji: lo capturaron y mataron ante sus ojos." },
        { "Los dragones los salvaron. Llegaron los vuelos Bronce, Rojo, Azul y Verde y rechazaron a los insectos hasta su ciudad. Con su magia, los elfos de la noche levantaron un gran muro de piedra y una barrera en el sur de Silithus, el Muro del Escarabajo, y los encerraron. Los muertos de aquella guerra yacen fuera, en Sosiego del Valor." },
      },
    },
    ["the-scarred-places"] = {
      title = "Los lugares marcados",
      text = {
        { "La Guarida de Onyxia en el Marjal Revolcafango, la Escara Impía en Las Tierras Devastadas, el Barranco Rompesombras en Desolace, La Vega de Cristal en Silithus y los Acantilados Tormentosos comparten una pieza tomada de Los Baldíos. Cada lugar tiene sus problemas: un dragón negro en el primero, Lord Kazzak y sus demonios en el segundo, los invocadores del Filo Ardiente en el tercero. En el cuarto, el Alto Señor Demitrian espera a quien tenga el valor de alzar Trueno Furioso." },
      },
    },
    ["the-scepter-of-the-shifting-sands"] = {
      title = "El Cetro del Mar de Dunas",
      text = {
        { "Para sellar Ahn'Qiraj, el dragón bronce Anacronos hizo un cetro, el Cetro del Mar de Dunas. Con él cerró el Muro del Escarabajo y colocó un gong en un estrado ante él. Solo golpear el gong con el cetro puede volver a abrirlo. Se lo entregó a Fandral Corzocelada." },
        { "Fandral no lo quería. Pensando en su hijo, rompió el cetro contra el suelo y dijo que no deseaba volver a verlo jamás. Sus fragmentos quedaron al cuidado de los vuelos. Mil años después, una lágrima cristalina en el desierto del sur aún muestra ese recuerdo a quien mira dentro, y los dragones bronce buscan a alguien que reúna de nuevo el cetro." },
      },
    },
    ["the-second-war"] = {
      title = "La Segunda Guerra",
      text = {
        { "En Lordaeron, Lothar encontró a los reyes humanos dispuestos a escuchar, por una vez. Acordaron unirse como Alianza de Lordaeron, la primera vez en casi tres mil años que los herederos de Arathor se reunían bajo un estandarte, y nombraron comandante supremo a Lothar. Uther el Iluminado, el almirante Daelin Valiente y Turalyon sirvieron bajo él. Forjaz se unió y, con más reservas, unos pocos altos elfos que debían una deuda al linaje Arathi." },
        { "Martillo Maldito trajo ogros de Draenor y trols Amani de los bosques, invadió Khaz Modan y marchó al norte. La Horda había encontrado el Alma demoníaca y esclavizado con ella a la Reina de los Dragones, de modo que los dragones rojos combatieron por los orcos. Ardieron las fronteras de Quel'Thalas, lo que resolvió las dudas de los elfos, y las poblaciones de Lordaeron fueron arrasadas una a una." },
        { "La Horda estaba a las puertas de la capital de Lordaeron cuando Gul'dan desertó con la mitad de sus fuerzas para alzar del mar la Tumba de Sargeras. Dentro solo encontró demonios enloquecidos. Martillo Maldito tuvo que retroceder para castigarlo. La Alianza lo empujó al sur hasta la Cumbre de Roca Negra, donde Lothar cayó al pie de la montaña. Turalyon reunió al ejército, quebró a la Horda y destruyó el Portal Oscuro tras ella. Los orcos supervivientes fueron recluidos en campos." },
        { "Observo que la Cumbre vuelve a estar llena de orcos." },
      },
    },
    ["the-sepulcher"] = {
      title = "El Sepulcro",
      text = {
        { "El Sepulcro es un conjunto de criptas y mausoleos en Argénteos, ocupado por guardias de la Muerte y mortacechadores Renegados. Desde este bastión pretenden asegurar el bosque. Las órdenes de la Reina alma en pena van más lejos: Varimathras tiene el encargo de conquistar las tierras humanas y enanas del sur." },
        { "Por ahora, los ferocanis de Arugal, los gnolls Putrepellejo y los magos de Molino Ámbar mantienen a sus fuerzas ocupadas cerca de casa. Los Renegados quieren, sobre todo, deshacer la obra de Arugal." },
      },
    },
    ["the-seven-kingdoms"] = {
      title = "Los siete reinos",
      text = {
        { "Arathor no terminó con una guerra. Se fue separando. Strom siguió siendo el corazón del imperio mientras surgían nuevas ciudades por el norte. Dalaran era donde los magos iban a practicar con más libertad. Gilneas y Alterac llevaron sus ejércitos a las montañas de Khaz Modan y conocieron a los enanos de Forjaz. Kul Tiras, en su isla, se enriqueció con la pesca y el comercio y construyó una flota para llevar ambos." },
        { "Después, los señores de Strom se cansaron del sur seco. Marcharon al norte y levantaron una ciudad nueva, Lordaeron, que con el tiempo dio nombre a todo el continente. Los últimos del linaje de Thoradin, que habían defendido no abandonar Strom, fueron en la dirección contraria, al sur de las montañas, y fundaron Ventormenta en un valle fértil de la tierra que llamaron Azeroth. Unos pocos guerreros se quedaron a vigilar los muros antiguos y Strom se convirtió en Stromgarde." },
        { "Siete reinos, pues, cada uno con sus costumbres y rencores, sin que ninguno gobernara a los demás. Hizo falta una invasión de otro mundo para reunirlos bajo un estandarte casi tres mil años después, y ese estandarte apenas sobrevivió a la guerra que lo alzó. A la Liga siempre le ha resultado más fácil seguir la historia de los enanos." },
      },
    },
    ["the-shalnan"] = {
      title = "El Shal'nan",
      text = {
        { "Los shen'dorei recuerdan al dirigente que los sacó de Eldre'Thalas solo como el Shal'nan, el Velado, por la máscara dorada sin rasgos que ocultaba su rostro. Cuando las ambiciones del príncipe Tortheldrin se oscurecieron, los rebeldes del Shal'nan rompieron la red de focos de cristal de la que dependía y huyeron. Fue el Shal'nan quien pactó con los espíritus del viento y llevó a su pueblo a Muro Celeste." },
        { "Los gobernó durante más de un siglo, un dirigente a su pesar según sus propios relatos. Después cedió la autoridad a un consejo de las provincias, una vez fundados los santuarios insulares. Un cristal guardado en lo alto del gran árbol de Thendal cuenta su historia. No dice qué fue de él. Hasta ahora, los shen'dorei tampoco." },
      },
    },
    ["the-silence-of-the-winds"] = {
      title = "El silencio de los vientos",
      text = {
        { "Durante miles de años, los espíritus del viento mantuvieron en el aire la Isla de Zephras y cuidaron de los shen'dorei. Hace algunos siglos se marcharon. Nada de lo que han intentado desde entonces los shen'dorei ha logrado traerlos de vuelta ni explicar por qué. Los duendes que aún juegan sobre la isla son ecos sin las mentes de los espíritus que antes hablaban con ellos." },
        { "Lo que dejaron los espíritus se desgasta. Sus pilones de anclaje mantienen unida la isla, pero su magia va y viene. Las líneas Ley han empezado a aflorar como cicatrices. Se recogen y estudian con empeño piedras de viento que contienen el poder bruto de los vientos. Cada facción tiene su respuesta: los Formavientos quieren encontrar a los espíritus y traerlos a casa, la Orden Eminente quiere aprender a vivir sin ellos y los Al'Aketh prefieren arrodillarse ante el Señor del Viento." },
      },
    },
    ["the-sorrowful-swamp"] = {
      title = "El pantano de las penas",
      text = {
        { "El Pantano de las Penas y el Cráter de Un'Goro, dos lugares sin nada más en común, tienen la misma melodía. El primero guarda la aldea orca de Rocal y el templo hundido de Atal'Hakkar. El segundo guarda una enorme cantidad de dinosaurios, algo que ninguna de mis historias ha logrado explicar." },
      },
    },
    ["the-stockade"] = {
      title = "Las Mazmorras",
      text = {
        { "La prisión de Ventormenta está bajo sus canales, excavada en la roca que sostiene la ciudad. Entre los Defias encarcelados allí estaba Bazil Thredd, lugarteniente de Edwin VanCleef. Bajo su mando, los presos se alzaron y tomaron el control de las celdas." },
        { "El alcaide pidió aventureros para sofocar la revuelta. Thredd no era el único preso peligroso: el orco Targor el Pavoroso también estaba entre los amotinados. Resulta incómodo tener un bastión enemigo bajo las calles de tu propia capital." },
      },
    },
    ["the-sundering"] = {
      title = "El Gran Cataclismo",
      text = {
        { "Hace diez mil años, los elfos de la noche gobernaban Kalimdor desde las orillas del Pozo de la Eternidad, un lago de magia pura en el corazón del mundo. Su reina era Azshara, la más hermosa de todos, y sus Altonato extraían sin límite el poder del Pozo. Su magia atrajo la mirada de Sargeras, señor de la Legión Ardiente. Azshara y sus Altonato le abrieron el camino creyendo que los demonios harían perfecto el mundo." },
        { "Los elfos de la noche que no se sometieron combatieron a la Legión en la Guerra de los Ancestros. Al principio los dirigía lord Kur'talos Cresta Cuervo, que creía a su reina prisionera de sus propios consejeros, hasta que un asesino enviado por su capitán de la guardia lo mató en el campo de batalla. El mando acabó en manos de un joven oficial, Jarod Cantosombrío, que hizo lo que Cresta Cuervo se había negado a hacer: llamar a los otros pueblos, terráneos, tauren y fúrbolgs, y a los semidioses del bosque, entre ellos Cenarius. El joven druida Malfurion Tempestira y la sacerdotisa Tyrande lucharon en el centro de todo. Illidan, hermano de Malfurion, se pasó a los Altonato y el dragón Neltharion se volvió contra los demás vuelos." },
        { "Al final, Malfurion comprendió que el propio Pozo era la puerta de la Legión y el Pozo de la Eternidad fue destruido. Se desgarró y se llevó consigo el corazón del continente. El mar se precipitó en el hueco. Azshara y sus Altonato se hundieron con su palacio. Desde esta orilla, La Playa Arrasada, contemplas el lugar donde se rompió el mundo." },
      },
    },
    ["the-suntara-stones"] = {
      title = "Las piedras de Suntara",
      text = {
        { "Las piedras de Suntara eran un rumor de excavadores hasta que Dorius Tienrroca fue a buscarlas a La Garganta de Fuego. Un viajero lo encontró en el camino de vuelta, malherido, suplicando que lo llevaran a casa, a Forjaz. Le dispararon antes de que llegaran. Dejó una carta para su hermano, el comisario Torio de la Sala de los Exploradores. Las piedras existían, decía, las tenían los Hierro Negro, y su jefe, Lathoric el Negro, usaba su poder para esclavizar al equipo de excavación de Dorius. A los excavadores se los habían llevado a La Caldera, donde trabajaban noche y día en algo llamado Obsidion. Ayúdalos, pedía la carta. Iba firmada como la última voluntad de un hombre muerto." },
        { "Torio se secó los ojos y juró que el deseo de su hermano se cumpliría. Los excavadores aparecieron en La Fosa de la Escoria, trabajando todavía cuando sus cuerpos ya no daban más, atados a la tarea por las piedras hasta que alguien colocó sobre el altar de Suntara una reliquia que custodiaba el Martillo Crepuscular. Uno de ellos vivió lo suficiente para decir que todo había sido una trampa y para pedir que mataran al responsable, por Torio." },
        { "La cabeza de Lathoric el Negro, cuando la llevaron a la Sala, era la de Dorius. Había fingido su propia muerte en el camino, y la carta formaba parte de la farsa. Torio culpó al Señor del Fuego y a los dioses antiguos, cuyo poder sigue siendo fuerte en aquella tierra. Si un enano tan honorable como su hermano había caído bajo la voluntad de Ragnaros, dijo, nadie estaba a salvo." },
        { "Vuelve a leer la carta sabiendo quién la escribió, $gviajero:viajera;. Casi todas sus líneas son ciertas. Solo miente la firma." },
      },
    },
    ["the-tablets-of-mosharu"] = {
      title = "Las tablillas de Mosh'aru",
      text = {
        { "Yeh'kinya, un trol de Puerto Bonvapor, sabe mucho de Hakkar el Cazador de Almas y dice no creer nada de ello. Entre los trols hay una profecía, explica, según la cual el dios muerto volverá algún día, para gloria de los trols o para el fin de todas las cosas. Un mito, lo llama. Pero la esencia del dios encierra un gran poder, y ese poder debe mantenerse lejos de quienes abusarían de él." },
        { "Así que reúne. Primero los espíritus de los estridadores del valle de Feralas, primos de un viejo dios. Luego las dos tablillas de la profecía de Mosh'aru, llevadas hace mucho a Zul'Farrak, una en poder de Theka el Mártir, muerto hace tiempo, entre los escarabajos en los que fueron convertidos sus perseguidores, y la otra en manos de la hidromántica Velratha, junto a la poza sagrada de Gahz'rilla. Después un huevo antiguo, sacado de una cueva detrás del anfiteatro de Jintha'Alor. Y por último la esencia del avatar de Hakkar, arrancada en el Templo Sumergido y sellada en el huevo. Has tocado una leyenda, le dice al viajero que se lo trae. He conocido a eruditos que decían no creer nada de lo que estudiaban. Ninguno lo coleccionaba con tanto cuidado." },
        { "El prospector Ferrobota, un enano del mismo puerto, había hecho sus propias lecturas. Había seis tablillas de Mosh'aru, no dos. Las cuatro que Yeh'kinya nunca pidió, dos en manos de los trols Fustamusgo de las Tierras de la Peste del Este y dos en las de los Espina Ahumada de la Cumbre de Roca Negra, revelan para qué sirve el huevo. No retiene a Hakkar. Lo trae de vuelta. Cuando el viajero se lo echó en cara, Yeh'kinya ni se molestó en negarlo. El Cazador de Almas había renacido, dijo, en el antiguo reino trol de Zul'Gurub, y dio las gracias al viajero por acelerar su regreso. Ferrobota lo envió después a ver a los trols Zandalar de la Isla Yojamba, que quizá supieran cómo detenerlo." },
      },
    },
    ["the-temple-of-atalhakkar"] = {
      title = "El Templo de Atal'Hakkar",
      text = {
        { "Cuando los Gurubashi se alzaron contra los sacerdotes que habían traído a Hakkar al mundo, los Atal'ai huyeron a este pantano, construyeron un templo a su dios y siguieron intentando invocarlo. Los dragones verdes de Ysera los encontraron. Hundieron el templo bajo el pantano y Ysera encargó a algunos de los suyos que lo custodiaran, para que Hakkar nunca volviera a entrar por él." },
        { "Los Atal'ai siguen dentro, bajo el agua. Su profeta Jammal'an les ha prometido que, cuando Hakkar regrese, les dará vida eterna. Casi lo han conseguido. Los dragones que vigilan el templo ya no son lo que fueron, y tanto la Horda de Rocal como la Alianza quieren detener a los Atal'ai antes de que vuelva a caminar el Cazador de Almas." },
      },
    },
    ["the-third-fleet"] = {
      title = "La Tercera Flota",
      text = {
        { "Los pecios de la costa norte de Los Humedales fueron la Tercera Flota de Kul Tiras. En su último viaje, dragones rojos, montados por orcos, la sorprendieron frente a esta costa y la incendiaron y hundieron allí mismo. Los de Kul Tiras la llaman la Flota Condenada." },
        { "Un hombre salió con vida: Fitzsimmons, antiguo primer oficial de la Señora de las Olas, que bebe en el Puerto de Menethil y cuenta la historia por una jarra. No todos sus compañeros descansan. Algo viajaba a bordo del Intrépido, encerrado en la caja fuerte del capitán, y su poder mantiene a las tripulaciones ahogadas caminando por las cubiertas podridas. El capitán Halyndor aún recorre su barco con la llave." },
        { "La caja contenía un Ojo de Paleth, uno de los orbes creados por sacerdotes humanos para brillar, ennegrecido por la maldición de lo que vio aquella noche. Los sacerdotes de Menethil no pudieron purificarlo. El arzobispo de Ventormenta sí. Una flota no siempre muere de una sola vez, $gviajero:viajera;. A veces hacen falta un sacerdote y un primer oficial obstinado para zanjar el asunto." },
      },
    },
    ["the-troll-villages"] = {
      title = "Los poblados trols",
      text = {
        { "El Poblado Sen'jin en Durotar, Malaka'jin en la Sierra Espolón, la Aldea Cazasombras en Desolace y la Avanzada de Zoram'gar en Vallefresno comparten una melodía, y los trols de la Horda han hecho su hogar en casi todos. La tribu Lanza Negra se marchó con Thrall, y el Poblado Sen'jin, en la costa de Durotar, es hoy su hogar. Los Cabellesangre de Tuercespina todavía cuentan a los Lanza Negra entre sus enemigos." },
      },
    },
    ["the-twilight-shores"] = {
      title = "Las costas del crepúsculo",
      text = {
        { "Costa Oscura, Claro de la Luna, las aldeas del Bosque de Argénteos y la costa de Los Humedales comparten esta melodía. Auberdine mira al Mar de la Bruma, y los druidas cuidan el Santuario de Remulos en Claro de la Luna. La Aldea Piroleña, en el Bosque de Argénteos, es otra historia. Sus vecinos son humanos de día y huargen Furia Lunar de noche, y la culpa es del encantamiento de Arugal." },
      },
    },
    ["the-valley-of-bones"] = {
      title = "El Valle de los Huesos",
      text = {
        { "El Valle de los Huesos está lleno de muertos: huesos y cuerpos, los esqueletos de los Goliats Gemelos y cosas que caminan cuando deberían descansar. Un poder nigromántico ha impregnado el lugar, y los Magram, el primer clan que se atrevió a entrar, han decidido que esa magia es suya. Nadie, por lo que veo, les preguntó a los muertos. Los que no luchan con espada o mazo aprenden a levantar a los muertos, y ya tienen Necrokhans." },
        { "Los Gelkis llegaron después. Algunos Gelkis siguieron a los Magram al valle y se entregaron al mismo arte, en un retorcido intento, según uno de sus prisioneros, de pasarse a ellos, y el clan los ha condenado a todos al exilio. Al explorador Gelkis Nerlokh le repugnó otra cosa. Los esqueletos andan sobre dos piernas, no sobre cuatro. No son muertos centauros, sino quienes yacían en esa tierra mucho antes de que Desolace perteneciera a los centauros. Nerlokh no podía imaginar cómo justificaban los Magram dar la espalda a la Madre Theradras para levantarlos." },
        { "Los Magram quieren tomar el valle, reunir allí un ejército y poner de rodillas a los demás clanes. Orgrul, que da las órdenes en su campamento, ha tomado la costumbre de preguntar a los reclutas si están tan ansiosos como él por gobernar toda Desolace." },
      },
    },
    ["the-veiled-blade"] = {
      title = "La Hoja Velada",
      text = {
        { "La Cumbre de Roca Negra tuvo un señor antes que Drakkisath: Valthalak, un noble dracónido y además brujo, y de los poderosos. La Hoja Velada lo mató. Era una compañía de mercenarios a las órdenes de Anthion Harmon, contratada por Gremnik Saltatrabas, un contrabandista goblin de Bahía del Botín aficionado a la hechicería, para que le llevaran el libro de hechizos de Valthalak. Llegaron a la parte alta de la Cumbre, mataron a Valthalak en su guarida y se llevaron el libro. Entonces Kormok, el nigromante ogro de dos cabezas de la compañía, le arrancó el amuleto del cuello al señor muerto." },
        { "Nadie sabía aún que el amuleto guardaba buena parte del espíritu de Valthalak. La compañía se peleó por él, lo partió en tres y se jugó los pedazos a los dados, y el fantasma de Valthalak se alzó entre ellos con sus asesinos espectrales. Huyeron, y Mor Pezuña Gris, un druida tauren, cayó, o lo empujaron, a la parte baja de la Cumbre, donde lo atraparon los trols. La compañía se disolvió y sus miembros murieron uno a uno. Los asesinos remataron a Mor mientras el Maestro de guerra Voone lo torturaba. Isalien murió al entrar en La Masacre, y los hermanos Jarien y Sothos, devotos de la Cruzada, a manos del propio Gran Cruzado. Kormok murió en Scholomance ante Ras Murmuhielo. Gremnik, que los había contratado, murió también, y Anthion cayó a las puertas de Stratholme intentando liberar a su esposa. Los asesinos de Valthalak encontraron a algunos, y el mundo se ocupó del resto." },
        { "Bodley, un gnomo de la compañía que murió intentando volver a la Cumbre, sigue rondando la Montaña Roca Negra, visible solo a través del aparato revelafantasmas de un goblin. Fue Bodley quien se propuso deshacer todo lo ocurrido. Los pedazos se recuperaron de quienes los tenían, Valthalak fue traído de vuelta en lo que hoy es la cámara de la Bestia y muerto por segunda vez, y se le devolvió su amuleto entero. Perdonó a quien se lo había llevado, retiró a sus asesinos y prometió a los supervivientes que estaban a salvo, por ahora. Bodley lo dejó todo escrito después en el manual de un blandón. Es el relato más alegre de una matanza que he leído." },
      },
    },
    ["the-veiled-sea"] = {
      title = "El Mar de la Bruma",
      text = {
        { "Esta pieza pertenece a las aguas abiertas del Mar de la Bruma frente a Costa Oscura, y recibe a quien llega a la Cima del Espolón y a Claro de la Luna. He cruzado esas aguas más veces de las que querría. El mar nunca ha tenido prisa." },
      },
    },
    ["the-war-of-the-spider"] = {
      title = "La Guerra de la Araña",
      text = {
        { "Mientras Thrall liberaba a su pueblo de los campos, el Rey Exánime levantaba una ciudadela sobre el glaciar de Corona de Hielo. Un reino de Rasganorte lo rechazó. Azjol-Nerub estaba bajo tierra, gobernado por los nerubianos, señores araña cuyos túneles recorrían medio continente. Eran inmunes a su peste y a su voz en sus mentes. Atacaban sus bastiones y desaparecían antes de que pudiera responder." },
        { "Ganó por desgaste. Con los señores del terror y un suministro interminable de muertos, invadió Azjol-Nerub y derribó sus templos sobre los señores araña. La peste no podía tomarlos vivos, pero su nigromancia podía alzarlos muertos. Así sirvieron los nerubianos al amo que habían combatido. También admiraba sus edificios: las fortalezas de la Plaga están hechas a su estilo." },
        { "Puedes ver ambas cosas en las Tierras de la Peste. Los malignos de la cripta que reptan entre la Plaga son nerubianos, o lo que queda de ellos. Los zigurats de los muertos son arquitectura de los señores araña. El Rey Exánime guarda cerca sus trofeos." },
      },
    },
    ["the-webbed-dark"] = {
      title = "La oscuridad tejida",
      text = {
        { "La Hoya Nocturácnidas en Tirisfal, la Penumbra de las Celerácnidas en el Bosque de Argénteos, la Gruta Narácnida en Teldrassil y las minas de los Páramos de Poniente y de Loch Modan comparten una melodía. A las arañas les gustan los agujeros oscuros, y los mineros los cavan. Unos y otras se encuentran más a menudo de lo que querrían." },
      },
    },
    ["the-windshapers"] = {
      title = "Los Formavientos",
      text = {
        { "Los Formavientos son los shen'dorei que mantienen su fe en los espíritus del viento. Descienden de los primeros que recibieron el don de la visión celeste y cuidaron de los instrumentos y constructos que los espíritus dejaron en la isla. Han jurado pagar aquella vieja deuda: adentrarse en el plano elemental, encontrar a sus mentores desaparecidos y traerlos a casa. Su gran vidente del cielo, Ayessa Cantoalba, cree que el camino está abajo, en Azeroth, y los chamanes del Anillo de la Tierra los han apoyado." },
        { "No son gente que perdone. Ayessa respondió a la violencia del culto con sangre por sangre, y los Formavientos dicen de sí mismos que no perdonan ni olvidan. No quieren paz con los Al'Aketh y consideran la magia de la Orden Eminente en sus lugares sagrados un peligro para una isla que ya se está deshaciendo." },
      },
    },
    ["the-winterfall-firewater"] = {
      title = "La piroagua de los Nevada",
      text = {
        { "Donova Cubilnevado vino a Cuna del Invierno a estudiar los Baños de Fuego de Escarcha. En esta tierra no hay volcanes, así que ella cree que los demonios de la Garganta Negro Rumor, al sur, calientan el agua. Con lo que no contaba era con los Nevada. No suelen ser una tribu agresiva, pero habían empezado a vigilar los manantiales más grandes con el mismo empeño con que ella quería estudiarlos, y llevaban frasquitos de un líquido verde que casi brillaba." },
        { "La pista condujo, pasando por el Bastión Fauces de Madera, hasta los Muertobosque, los fúrbolgs de Frondavil a quienes la vileza ha enloquecido. En un caldero de los Muertobosque burbujeaba la misma sustancia verde, y Donova averiguó de dónde salía: materia tóxica recogida de los elementales corruptos del Bosque de Troncoferro. Sola, es veneno. Mezclada con el agua de las fuentes termales, pierde su toxicidad y conserva solo su poder sobre quien la bebe. Por eso los Nevada protegen las fuentes, y por eso sus corredores hacen el largo camino hasta Frondavil y vuelta. Los enanos sabemos algo de cerveza, y nunca he oído hablar de una cervecería parecida. Donova se preguntaba si el brebaje los volvía más agresivos. Los Nevada, desde luego, parecían mucho más grandes." },
        { "Creía que, muerto el Gran Jefe Nevada, la tribu no empeoraría, aunque nada podía deshacer el daño ya hecho. El diario del Gran Jefe está escrito con signos tan toscos que Donova no pudo sacar nada en claro. Kelek Guardacielo, del Círculo Esmeralda, druidas que trabajan para sanar Frondavil, lo tiene ahora y ha prometido dar noticias en cuanto consiga leerlo. De los Nevada en sí, admite Kelek, se sabe muy poco." },
      },
    },
    ["theldurin-the-lost"] = {
      title = "Theldurin el Perdido",
      text = {
        { "Theldurin el Perdido malvive en las Tierras Inhóspitas y habla solo, y parte de lo que dice merece ser escuchado. En otro tiempo fue miembro del Martillo Crepuscular. Según el propio culto, perdió la cabeza, desdeñó sus enseñanzas y huyó llevándose el pergamino capaz de llamar a Myzrael a la superficie. Según Theldurin, lo que hizo fue recobrar el juicio. Algo aguarda bajo la tierra: los poderes que su antigua orden llama los moradores del subsuelo, y se niega a pronunciar sus nombres por miedo a que lo oigan." },
        { "Lo que quiere ahora es entenderlos lo bastante para mantenerlos abajo. Envía a los viajeros a Uldaman en busca de una tablilla guardada en un cofre más antiguo que cualquier obra de los enanos, y después en busca del Compendio de Yagyin, un viejo libro que su antigua orden guarda en muchos lugares para que lo estudien sus más eruditos. Un ejemplar está en una tienda de La Caverna Abandonada, en Forjaz, en manos de un enano llamado Gerrig Agarrahueso que saluda el emblema del culto con alabanzas a los moradores del subsuelo. Otro lo guarda en Entrañas el vigilante Bel'dugur." },
        { "Preferiría que ese primer ejemplar estuviera en cualquier parte menos aquí. Su tienda ha vendido libros de nombres impronunciables y sacrificios vivos bajo la montaña de nuestro rey. Agarrahueso y, por la Horda, Zaruk en Sentencia mandan a los viajeros tras Theldurin con las mismas palabras: \"nuestra orden, el Martillo Crepuscular\". Dicen que está loco. Después de ver lo que su antigua orden guarda en sus estantes, casi lo tengo por el miembro más cuerdo que ha tenido nunca. Si los moradores del subsuelo llegan a liberarse, dice, todos seremos alimento de gusanos. En eso, la historiadora real y el loco están de acuerdo." },
        { side = "Horde", aside = true, sign = "P. F.", "El vigilante Bel'dugur reúne las obras de Ur para la Dama Oscura, según dice, y guarda el Compendio de Yagyin para otro. Un guardián de libros debería saber para quién llena los estantes." },
      },
    },
    ["thelsamar"] = {
      title = "Thelsamar",
      text = {
        { "Thelsamar es el corazón de Loch Modan: una aldea de casas de piedra en el camino entre Forjaz y Los Humedales, con forja, una buena posada y un maestro de grifos para quienes tienen prisa." },
        { "Es de esos lugares donde todos se conocen y las noticias viajan más deprisa que los grifos. Pregunta en la posada por cualquier cosa que ocurra en la comarca del lago y la oirás tres veces, cada versión mejor que la anterior." },
        { "Los montaraces no dan abasto. Si tienes un brazo fuerte y una tarde libre, te encontrarán algo que hacer." },
      },
    },
    ["thendal-tune"] = {
      title = "Thendal",
      text = {
        { "Thendal, la Arboleda Thendal y las Piedras verticales de Thendal comparten una melodía. La aldea guarda su historia en lo alto de su gran árbol, lo que me parece un lugar sensato en una isla que ya tuvo que vaciar una aldea entera en una sola noche. De todos los archivos que conozco, es el más difícil de alcanzar, y aun así haría la subida." },
      },
    },
    ["theramore-isle"] = {
      title = "Isla de Theramore",
      text = {
        { "Theramore es la ciudad que Jaina Valiente construyó al guiar a los supervivientes de Lordaeron por mar hasta Kalimdor: un puerto fortificado de piedra blanca en una isla frente a Marjal Revolcafango. Es el bastión más fuerte de la Alianza en el continente y el único lugar del mundo donde una gobernante humana ha logrado una paz duradera con la Horda." },
        { "Muchos soldados cruzaron el mar con lady Valiente, incluidos infantes de marina de Kul Tiras, y no todos se han reconciliado con esa paz. Theramore mantiene atalayas por el pantano y un fuerte en Los Baldíos. Sus capitanes tienen más misterios sobre la mesa de los que les gustaría." },
      },
    },
    ["thoradins-wall"] = {
      title = "Muralla de Thoradin",
      text = {
        { "Hace mucho, Thoradin fue el jefe de la tribu Arathi que, por conquista o persuasión, unió a las tribus humanas dispersas del norte en una sola nación, el imperio de Arathor, y construyó su capital en Strom. Cuando los trols del imperio Amani hicieron la guerra a los elfos de Quel'Thalas, Thoradin llevó a los humanos a luchar junto a ellos. Los magos humanos que los elfos formaron en aquella guerra fueron el principio de toda la magia humana." },
        { "Su muralla aún cruza las colinas entre Arathi y Trabalomas, rota y cubierta de maleza, pero todavía grandiosa. Los hombres que la construyeron desaparecieron hace mucho y el imperio con ellos, pero todos los reyes humanos se han proclamado sus herederos." },
      },
    },
    ["thorium-brotherhood"] = {
      title = "La Hermandad del Torio",
      text = {
        { "La Hermandad del Torio está formada por enanos Hierro Negro que abandonaron a su emperador. Sus herreros trabajan en el Puesto del Torio, sobre La Caldera, y comercian con quienes los ayudan contra las fuerzas de Thaurissan. A un Barbabronce le cuesta poco admirar su oficio. El acuerdo político exige algo más de explicación." },
        { "Saben forjar las armas y armaduras del Señor del Fuego, siempre que alguien traiga los materiales del interior de la montaña. Uno de ellos incluso comercia en la taberna de Ciudad Forjatiniebla, ante las propias narices del emperador. Si buscas su trabajo, lleva lo que necesitan, $gviajero:viajera;. Su disputa con sus antiguos parientes no ha mermado su habilidad." },
      },
    },
    ["thousand-needles"] = {
      title = "Las Mil Agujas",
      text = {
        { "Al sur de Los Baldíos, un gran elevador desciende hasta Las Mil Agujas: un cañón profundo lleno de enormes pilares de piedra, cientos de ellos, que se alzan del polvo como los huesos de la tierra. Los tauren viven arriba, los centauros del clan Galak en el fondo y los dracoleones y las arpías entre unos y otros." },
        { "Al este, el cañón se abre al Desierto de Sal, un lecho blanco y seco donde el calor hace temblar el aire sobre el suelo. Los goblins y los gnomos han construido un circuito de carreras. Me dicen que es algo natural para goblins y gnomos cuando encuentran un desierto." },
      },
    },
    ["thrall"] = {
      title = "Thrall",
      text = {
        { "Thrall es el Jefe de Guerra de la Horda y su vida parece una balada que nadie creería. Hijo de Durotan, jefe de los Lobo Gélido, lo encontraron siendo un bebé junto a sus padres asesinados. El amo del Castillo de Durnholde, lord Aedelas Lodonegro, lo crio como esclavo y gladiador, con la intención de convertirlo en general de un ejército de orcos domesticados. Le dieron el nombre de Thrall, que significa esclavo, y lo conservó." },
        { "Escapó con ayuda de una muchacha humana que había trabado amistad con él, encontró al clan de su padre en las montañas de Alterac y aprendió las costumbres del chamán. Después, junto a Grom Grito Infernal y al antiguo Jefe de Guerra Orgrim Martillo Maldito, abrió los campos de internamiento y liberó a su pueblo. Martillo Maldito cayó en aquella guerra y dejó la Horda y su martillo a Thrall." },
        { "Llevó a la Horda por mar hasta Kalimdor, combatió junto a los elfos de la noche y los humanos contra la Legión Ardiente y fundó Durotar. Quiere la paz con la Alianza y la ha alcanzado con Jaina Valiente de Theramore. Que el resto de la Alianza la quiera es otra cuestión." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron lo hizo esclavo y aun así encontró sitio en su Horda para los muertos de Lordaeron. No estoy seguro de que yo lo hubiera hecho." },
      },
    },
    ["thule-ravenclaw"] = {
      title = "Thule Corvozarpa",
      text = {
        { "Thule Corvozarpa era un joven mago muy prometedor antes de la Tercera Guerra. Cuando surgió el Rey Exánime, traicionó a los suyos para servir a la Plaga. Los Renegados, algunos de los cuales estudiaron con él en vida, no sabían que seguía vivo hasta que encontraron su obra." },
        { "Domina la Isla de Fenris, en el Lago Lordamere, junto a Argénteos. Los gnolls del clan Putrepellejo le pertenecen: seres muertos, resucitados y empapados en sus inmundos icores, que desentierran las tumbas de Tirisfal y le llevan los cuerpos. Los Renegados preferirían no descubrir por las malas qué hace con ellos." },
      },
    },
    ["thunder-bluff"] = {
      title = "Cima del Trueno",
      text = {
        { "Cima del Trueno se alza sobre las mesetas de Mulgore y se alcanza mediante grandes ascensores o un dracoleón. Los puentes de cuerda unen sus altos. Un enano de Forjaz acostumbrado a suelos sólidos quizá prefiera mirar dónde pisa antes de admirar las vistas." },
        { "Cairne construyó este refugio después de que tauren y orcos rechazaran a los centauros. Las tribus, acostumbradas durante tanto tiempo a vagar, se reunieron aquí. Comerciantes y artesanos lo comparten ahora con cazadores, con los druidas del Alto de los Ancestros y con los chamanes y videntes del Alto de los Espíritus." },
        { "Cairne sigue siendo el gran jefe en su centro. Los Tótem Siniestro se cuentan entre quienes se oponen a su liderazgo. El viajero ve a un pueblo que por fin tiene una ciudad, aunque un hogar permanente no haya terminado con los desacuerdos entre sus tribus." },
      },
    },
    ["thunder-bluff-tune"] = {
      title = "Cima del Trueno",
      text = {
        { "La Cima del Trueno se alza sobre las altas mesetas de Mulgore, hogar de los tauren y de Cairne Pezuña de Sangre, su jefe. Su melodía suena en las peñas y en las aldeas de las llanuras de abajo. Los tauren construyen como viven, despacio y al aire libre." },
      },
    },
    ["timber"] = {
      title = "Maderero",
      text = {
        { "Los cazadores de Kharanos lo llaman Maderero: un lobo más grande que los demás, con un conocimiento de las trampas bastante molesto. Dicen que elige el terreno y vuelve sobre sus propias huellas. La presa ha sobrevivido a todos los cazadores enviados tras ella." },
        { "Los lobos rara vez merecen una mención en una historia real. Este ha presentado un argumento bastante sólido para incluirlo, aunque dudo que aprecie la distinción." },
        { "Si lo has matado, deja por escrito lo ocurrido mientras lo recuerdes, $gviajero:viajera;. Los cazadores no tardarán en tener su propia versión." },
      },
    },
    ["timbermaw"] = {
      title = "Los Fauces de Madera",
      text = {
        { "De todas las tribus fúrbolgs del norte, solo los Fauces de Madera han conservado la razón. La corrupción que se filtró de Frondavil convirtió a los Muertobosque y los Nevada en las criaturas gruñentes de los caminos, y los Fauces de Madera tuvieron que verlo ocurrir a sus parientes. Resistieron en sus túneles bajo las montañas entre Frondavil, Claro de la Luna y Cuna del Invierno, defendiéndolos de todos." },
        { "Tienen razones para ser cautos. La mayoría de los viajeros mata ahora a cualquier fúrbolg a primera vista sin preguntar su tribu, de modo que confían en muy pocos. Ayúdalos contra las tribus corruptas y empezarán, despacio, a dejarte cruzar su bastión. Se encontró a un demonio en el origen de la locura de los Nevada. Matarlo dio a esa tribu, en palabras de los Fauces de Madera, una oportunidad de sobrevivir." },
        { "No disfrutan luchando contra sus hermanos. Uno de sus exploradores pide a quienes combaten por él que le ahorren los detalles. Gánate toda su confianza y enviarán una ofrenda de paz a tu propio rey. Es el gesto más civilizado que un pueblo sitiado ha ofrecido a nadie en este registro." },
      },
    },
    ["tiragarde-keep"] = {
      title = "Fuerte de Tiragarde",
      text = {
        { "El Fuerte de Tiragarde es una fortaleza de Kul Tiras en la costa de Durotar que no debería estar aquí. Una vez asentada la Horda en su nueva tierra, el almirante Daelin Valiente, señor del reino insular de Kul Tiras, trajo su flota para terminar la guerra que su pueblo nunca perdonó, desafiando la paz que su propia hija había pactado con Thrall en el Monte Hyjal. Fue derrotado y muerto, y su flota yace destrozada frente a esta playa." },
        { "El fuerte cayó con él. Pero algunos de sus hombres se quedaron y, bajo el teniente Benedict y un comandante de la guardia llamado Zalaphil, lo han recuperado y fortificado: un puñado de ciudadanos de Kul Tiras en pleno hogar de la Horda. Los orcos de Cerrotajo los llaman traidores. Los de Kul Tiras dirían algo muy parecido de Theramore." },
      },
    },
    ["tirion-fordring"] = {
      title = "Tirión Vadín",
      text = {
        { "Puedes encontrar a Tirión Vadín en una pequeña cabaña junto al Río Thondroril. Fue señor del Fuerte de Mardenholde, en Vega del Amparo, y paladín de la Mano de Plata. Poco en su alojamiento actual sugiere cualquiera de esas distinciones." },
        { "El orco Eitrigg le salvó la vida. Tirión se opuso a su captura y, en su juicio de Stratholme, se negó a abandonar el juramento que le había hecho. Le quitaron títulos y posesiones y lo enviaron al exilio. Su esposa dijo a su hijo Taelan que estaba muerto." },
        { "Ahora Taelan dirige la Cruzada Escarlata en Vega del Amparo. Tirión pide a los viajeros que recuperen un martillo de juguete que le regaló de niño, el estandarte de la Mano de Plata que Taelan derribó en Vallenorte y un cuadro oculto en Stratholme. Espera llegar a su hijo con esas cosas. Si te confía el encargo, recuerda que intenta traer a Taelan a casa, $gviajero:viajera;." },
      },
    },
    ["tirisfal-glades"] = {
      title = "Claros de Tirisfal",
      text = {
        { "Tirisfal era el corazón del reino de Lordaeron: campos ondulados, huertos y molinos alrededor de la capital, la comarca más rica del norte. También es tierra antigua en otros sentidos. Los claros dieron nombre a la orden secreta de magos, los Guardianes de Tirisfal, que velaron por el mundo durante siglos." },
        { "Ahora es una tierra gris. La peste se llevó Lordaeron, los muertos caminaron y la capital cayó. Las granjas están vacías o peor, los árboles no tienen hojas y la luz siempre es tenue. Los Renegados gobiernan desde debajo de la ciudad en ruinas, la Cruzada Escarlata desde su monasterio del norte, y la Plaga aún vaga por los campos que los separan." },
      },
    },
    ["tower-of-althalaxx"] = {
      title = "La Torre de Althalaxx",
      text = {
        { "Balthule Golpesombra vigila la ruinosa Torre de Althalaxx, al noreste de Auberdine. Permanece en su puesto antes que arriesgarse a perder una pista. La actividad de los alrededores conduce a la Hebra Oscura, un culto de elfos de la noche que practica la magia de los brujos. Su pueblo tiene motivos de sobra para recordar lo que pueden traer esas artes." },
        { "La investigación se extiende al sur, hasta Vallefresno, donde hay un brujo orco en el Santuario de la Escara. Delgren el Purificador, del Alba Argenta, continúa la búsqueda allí." },
      },
    },
    ["treason-of-alterac"] = {
      title = "La traición de Alterac",
      text = {
        { "El rey Aiden Perenolde calculó que la Horda ganaría la Segunda Guerra. Mientras los demás reinos humanos luchaban juntos, Alterac abrió un paso a los orcos y les facilitó los planes de la Alianza. Cuando la Alianza ganó, Lordaeron impuso la ley marcial. Después, los gobernantes discutieron qué debía hacerse con el reino." },
        { "La capital de Alterac está en ruinas y sus bibliotecas, dispersas. Ventormenta envía estudiosos para recuperar los libros. Aliden, hijo de Perenolde, ha buscado otra herencia: dirige el Sindicato, entre cuyos miembros hay antiguos nobles de Alterac, y planea esclavizar a los orcos como pretendía su mentor Lodonegro. Aquí se intentan rescatar varias cosas, $gviajero:viajera;. La que yo recomendaría es la de los estudiosos." },
        { side = "Horde", aside = true, sign = "P. F.", "Me alegra que alguien salve los libros de Alterac. Que alguno llegue a Entrañas es otro asunto." },
      },
    },
    ["twilights-hammer"] = {
      title = "El Martillo Crepuscular",
      text = {
        { "El Martillo Crepuscular de Cho'gall comenzó como un clan orco de la Segunda Guerra, dirigido por un ogro mago de dos cabezas. Luchaba creyendo que el mundo debía terminar. La derrota de la antigua Horda dejó vivo ese propósito en un culto con seguidores de muchos pueblos." },
        { "El culto adora a los dioses antiguos, poderes remotos bajo la tierra. Sus miembros sirven a un horror en las Cavernas de Brazanegra, se reúnen ante ídolos de La Garganta de Fuego e invocan señores elementales en Silithus." },
      },
    },
    ["tyrande-whisperwind"] = {
      title = "Tyrande Susurravientos",
      text = {
        { "Tyrande Susurravientos dirige a los elfos de la noche como suma sacerdotisa de Elune. Hace diez mil años era una joven sacerdotisa que luchaba contra la Legión junto a Malfurion e Illidan Tempestira. Amaba a Malfurion. El amor que Illidan sentía por ella no era correspondido. Fue quien convenció a los demás de que Malfurion tenía razón y el Pozo debía destruirse. Antes del final, los sátiros de Azshara la hicieron prisionera. En el camino acogió a una joven arquera huérfana, Shandris Plumaluna, que ahora manda a las centinelas como general." },
        { "Mientras los druidas dormían en el Sueño Esmeralda, sus sacerdotisas y centinelas protegieron los bosques durante largas eras. En la Tercera Guerra reunió a los elfos de la noche, despertó a Malfurion y estuvo en Hyjal cuando cayó Archimonde." },
        { "Ahora Malfurion ha desaparecido y los druidas desconocen su destino. Tyrande dirige desde el Templo de la Luna de Darnassus mientras Fandral Corzocelada encabeza a los druidas. Recibe su bienvenida con respeto, $gviajero:viajera;. La sacerdotisa que saluda a los visitantes ha guiado a su pueblo en guerras mucho más antiguas que nuestros reinos." },
      },
    },
    ["tyrs-hand"] = {
      title = "Mano de Tyr",
      text = {
        { "Mano de Tyr es una ciudad fortificada al sureste de las Tierras de la Peste, junto a la Bahía de Tyr, llena de iglesias y uno de los lugares santos más antiguos de Lordaeron. Ya conoció la guerra: durante la Segunda, los espías de Alterac incitaron a sus campesinos a rebelarse para ocultar una mina orca y enviaron a la Mano de Plata a mantener la paz. En la Tercera resistió a la Plaga y aún resiste para la Cruzada Escarlata." },
        { "La gobierna el señor cruzado Valdemar, la alta general Abbendis manda a sus soldados y una vidente a la que llaman el Oráculo Escarlata aconseja al Gran Cruzado. Los mensajeros cabalgan cada día por las Tierras de la Peste entre Mano de Tyr y Stratholme. Los Renegados los vigilan a todos." },
      },
    },
    ["uldaman"] = {
      title = "Uldaman",
      text = {
        { "Uldaman yace bajo Tierras Inhóspitas, una bóveda de los titanes de salones tallados y grandes guardianes de piedra. Las excavaciones de la Liga abrieron una entrada. Los troggs salieron en tropel y dieron a sus excavadores una respuesta poco grata a una pregunta antigua sobre esas criaturas." },
        { "Ahora los troggs ocupan los salones exteriores y los Hierro Negro Forjatiniebla buscan los secretos del interior. La Liga se enfrenta a ambos. Más allá de Archaedas, último guardián de la bóveda, están los Discos de Norgannon y su relato del trabajo de los titanes. La Liga tiene buenas razones para seguir excavando, incluso después de descubrir qué más puede liberar." },
      },
    },
    ["uldum"] = {
      title = "Uldum",
      text = {
        { "Las puertas selladas de Uldum están en el Valle de los Vigías, en el extremo sur de Tanaris. Acerca los discos de platino de Uldaman y despertará el Vigía de piedra de Norgannon. Protege la entrada y exige las Placas de Uldum antes de admitir a nadie." },
        { "El Vigía describe un centro de investigación de los titanes dedicado a la vida de este mundo. No dice dónde están las placas necesarias. La Liga tiene un nombre, un propósito y una puerta cerrada que investigar, $gviajero:viajera;. Nos gustaría mucho añadir una forma de atravesarla." },
      },
    },
    ["undercity"] = {
      title = "Entrañas",
      text = {
        { "La capital de Lordaeron yace en ruinas sobre la ciudad de los Renegados. Tras sus muros derruidos están el salón del trono destrozado y los patios sin vida. Debajo, las viejas criptas y catacumbas se han convertido en Entrañas, dispuesta alrededor de anillos de cieno verde. Sylvanas celebra su corte en el Barrio Real." },
        { "Mercaderes, instructores y guardias ocupan los otros barrios, y la Sociedad Real de Boticarios trabaja en el Apothecarium. Los Renegados han creado una capital en funcionamiento bajo los restos de la que conocieron en vida. Quien solo mirase las ruinas de arriba no vería dónde se atienden ahora los asuntos que le quedan al reino." },
        { side = "Horde", aside = true, sign = "P. F.", "Lo que dice del Apothecarium es correcto, hasta donde llega. Me encontrarás allí, en el puente sur de los dos que tiene, donde formulo preguntas a los héroes que creen que basta con la fuerza. Ven a examinarte, $gviajero:viajera;." },
      },
    },
    ["undercity-tune"] = {
      title = "Entrañas",
      text = {
        { "Entrañas se extiende bajo las ruinas de la capital de Lordaeron, y los Renegados de Sylvanas la guardan. Su melodía suena en algún lugar de los salones de abajo. Es la única ciudad que conozco cuyos habitantes tomarían la palabra acogedora por un insulto." },
      },
    },
    ["ungoro-crater"] = {
      title = "Cráter de Un'Goro",
      text = {
        { "Un'Goro es una cuenca verde y humeante hundida entre los desiertos de Tanaris y Silithus. Los demosaurios avanzan por su jungla, estegodones y grandes simios habitan la cuenca, y los pterrordáctilos vuelan sobre ella. Los tauren que viajan aquí hablan de criaturas más nobles que sus semejantes del exterior y de la conexión del cráter con la Madre Tierra." },
        { "Fosas de alquitrán, aguas termales y la Cresta del Penacho en Llamas dividen el bosque, con una colmena silítida al sur. En el Refugio de Marshal, la expedición estudia una tierra que parece haber conservado otra era. Los experimentos de J.D. Collie con los cristales de colores han empezado a revelar sus usos. Su origen sigue siendo una pregunta mayor." },
        { client = "forever", "El Bancal del Creador ha dado a esa pregunta un lugar por donde empezar." },
      },
    },
    ["uthers-tomb"] = {
      title = "Tumba de Uther",
      text = {
        { "Uther el Iluminado fue el primero de los paladines, ungido por el arzobispo Faol, comandante de los Caballeros de la Mano de Plata, maestro del príncipe Arthas y el mayor campeón humano que ha tenido la Luz. Se negó a participar en la purga de Stratholme y Arthas lo destituyó por ello. Cuando Arthas volvió de Rasganorte con su espada maldita, Uther se enfrentó a él para proteger la urna con las cenizas del rey Terenas. Dijo a su antiguo alumno que esperaba que hubiera un lugar especial en el infierno reservado para él. Arthas lo mató." },
        { "Su tumba está en la Colina de las Penas sobre el Lago Darrowmere, un salón de piedra blanca con su estatua dentro, en mitad de la tierra muerta. Allí hay una calma que no se encuentra en ninguna otra parte de las Tierras de la Peste. Quienes aún creen en la Luz vienen a presentar sus respetos." },
        { side = "Horde", aside = true, sign = "P. F.", "Terenas fue mi rey y Uther murió protegiendo sus cenizas. Me gustaría ver esa tumba." },
      },
    },
    ["vaelastrasz"] = {
      title = "Vaelastrasz",
      text = {
        { "Vaelastrasz es un dragón rojo del Vuelo de la Reina de los Dragones. Hace mil años se le confió un fragmento del cetro que selló Ahn'Qiraj. En la Cumbre de Roca Negra aparece a los mortales como Vaelan, con una forma que, como él dice, pueden soportar mirar. Ayuda a los valientes a forjar el Sello de Ascensión que abre la ciudadela superior." },
        { "Ha visto a los dragones al borde de la extinción, cuenta: por el ataque de la Legión Ardiente y el Alma demoníaca, por la división de los Aspectos y el ascenso de Alamuerte, y por los Faucedraco, que esclavizaron a su propia reina, Alexstrasza. Alamuerte fue en su día Neltharion, el Aspecto de la fuerza del mundo, que recibió del titán Khaz'goroth su poder sobre él, y con engaños convenció a los otros cuatro Aspectos de que entregaran sus poderes al Alma demoníaca, lo que los dejó débiles y divididos. Ahora su hijo Nefarian domina la Cumbre y continúa la obra de su padre, tras unas protecciones antiguas que ningún dragón de otro vuelo puede cruzar. Un mortal con el Sello sí puede." },
        { "La forja exige gemas de tres generales de la Cumbre y el aliento de un draco negro cuya voluntad ha sido quebrada. Al Vuelo Rojo nunca le ha importado tomar prestado el fuego del enemigo." },
        { "Nefarian acabó atrapándolo. Espera en la Guarida de Alanegra, retorcido por la corrupción del dragón negro, y suplica a quienes llegan que recuperen el fragmento del cetro antes de que sea destruido. 'Demasiado tarde, amigos', dice, y se vuelve contra ellos. A quienes lo derrotan se les dice después que su alma descansa. Eso espero." },
      },
    },
    ["valanaar"] = {
      title = "Valanaar",
      text = {
        { "Valanaar es la capital de la Isla de Zephras, en su extremo sureste, y la sede del sumo anciano. En sus muelles atracan los cortacielos: pequeños barcos voladores que antes viajaban entre las islas shen'dorei y ahora, por primera vez, descienden a Azeroth, a Dalaran para la Orden Eminente y a Mulgore para los Formavientos." },
        { "El relato que los propios shen'dorei hacen de su rebelión en Eldre'Thalas no se guarda en la capital. Se conserva en cuatro partes, guardadas en más de un lugar de la isla, y una de ellas está en la Aldea Falaath, que ahora ocupan los Al'Aketh. No conozco nada más antiguo que dé voz a los shen'dorei, y daría mucho por tener las cuatro." },
      },
    },
    ["valanaar-tune"] = {
      title = "Valanaar",
      text = {
        { "Valanaar tiene tres piezas propias. El sumo anciano gobierna desde allí, y de sus muelles aéreos parten los shen'dorei cuando bajan a Azeroth, así que por ella pasan más viajeros suyos que por ningún otro lugar de la isla. Es lo primero que la mayoría de los visitantes ve de Zephras, y lo último." },
      },
    },
    ["valley-of-kings"] = {
      title = "El Valle de los Reyes",
      text = {
        { "En el suroeste de Loch Modan montan guardia dos grandes reyes de piedra: Madoran Barbabronce y Khardros Martillo Salvaje, que dirigieron a sus clanes en la Guerra de los Tres Martillos." },
        { "Sus hijos levantaron estas estatuas tras su muerte para honrarlos y advertir a quien subiera por aquel camino de que los reinos enanos no serían conquistados. Los Hierro Negro estaban al sur entonces, como ahora. El mensaje no ha cambiado." },
        { "Detente y alza la vista, $gviajero:viajera;. Barbabronce y Martillo Salvaje están aquí uno junto al otro, como rara vez lo han estado en otro lugar desde entonces." },
      },
    },
    ["valley-of-trials"] = {
      title = "El Valle de los Retos",
      text = {
        { "En el Valle de los Retos se pone a prueba a los jóvenes de la Horda, orcos y trols por igual, enviados entre los jabalíes y escórpidos del cañón para demostrar de qué están hechos. Es un lugar estrecho y abrasado por el sol al sur de Cerrotajo, y sus pruebas están hechas para ser duras." },
        { "No todos sus peligros son bestias. En las cuevas del valle, el Filo Ardiente ha ocultado a sus cultores y diablillos, insultantemente cerca de los propios jóvenes de la Horda. La primera lección que aprenden muchos orcos es que el enemigo más antiguo de su pueblo a veces lleva rostro de orco." },
      },
    },
    ["varimathras"] = {
      title = "Varimathras",
      text = {
        { "Cuando Arthas partió hacia Rasganorte, Varimathras y sus compañeros señores del terror gobernaban las ruinas de Lordaeron. Sylvanas, recién liberada del control del Rey Exánime, lo derrotó y le dio a elegir entre servirla o morir. Eligió servir y después la ayudó a volverse contra sus hermanos." },
        { "Ahora permanece junto a la Reina alma en pena en Entrañas. Es una asociación imponente, aunque sus comienzos ofrecen pocas garantías sobre la lealtad de cualquiera de los dos. Varimathras encontró la forma de sobrevivir a un cambio de amo. Sylvanas lo mantiene donde puede verlo." },
        { side = "Horde", aside = true, sign = "P. F.", "Pasamos junto a él en el Barrio Real y no decimos nada. Tengo menos claro que la Dama Oscura que mantenerlo cerca equivalga a mantenerlo leal." },
      },
    },
    ["venture-company"] = {
      title = "Ventura y Cía.",
      text = {
        { "Si algo puede excavarse, talarse o bombearse del suelo, Ventura y Cía. ya está allí con una trituradora. Es una empresa goblin, una compañía comercial sin lealtad a nadie salvo a su junta. Su negocio consiste en tomar lo ajeno y venderlo antes de que el dueño se dé cuenta." },
        { "En Kalimdor están por todas partes. Arrasan los bosques de la Sierra Espolón, han abierto minas en los riscos de Mulgore contra la negativa expresa de los tauren y contaminado los pozos de paso. En Los Baldíos han bombeado el Fangal hasta convertirlo en una charca negra de petróleo. Al otro lado del mar talan la jungla de Tuercespina y excavan sus colinas." },
        { "Los suyos los tienen en poca estima. Los goblins del Cártel Bonvapor, que mantienen los puertos neutrales, pagan buen dinero a quien complique la vida a la compañía. Imagino que también lo haría todo tauren de Mulgore." },
      },
    },
    ["voljin"] = {
      title = "Vol'jin",
      text = {
        { "Vol'jin dirige a los Lanza Negra y es un cazador de las Sombras, uno de sus sacerdotes guerreros que caminan con los loa. Su padre Sen'jin murió durante los combates en las islas donde la flota de Thrall encontró a la tribu. Vol'jin ha mantenido la promesa que su padre hizo a la Horda." },
        { "Permanece cerca de Thrall en Orgrimmar mientras su pueblo conserva el Poblado Sen'jin y mira hacia la recuperación de las Islas del Eco. Por eso, quien busque al líder de los Lanza Negra lo encontrará en la capital, aún preocupado por el hogar perdido de su tribu." },
      },
    },
    ["wailing-caverns"] = {
      title = "Cuevas de los Lamentos",
      text = {
        { "El vapor suena como un lamento en las cavernas bajo Los Baldíos, donde los ríos atraviesan un laberinto de roca. Naralex vio en sus aguas un medio para sanar la tierra seca de arriba. Esperaba volver verdes Los Baldíos vinculándolas al Sueño Esmeralda." },
        { "Descendió con sus discípulos y durmió. El sueño se convirtió en pesadilla. Naralex no ha despertado, las criaturas de las cavernas han cambiado y casi todos sus seguidores han caído con él. Un discípulo aún busca ayuda para llegar hasta su maestro y realizar un ritual que lo despierte." },
      },
    },
    ["war-of-the-three-hammers"] = {
      title = "La Guerra de los Tres Martillos",
      text = {
        { "Hace unos dos siglos y medio, Forjaz pertenecía a tres clanes a la vez. Los Barbabronce, los Martillo Salvaje y los Hierro Negro vivían bajo un único gran rey, Modimus Yunquemar. Cuando murió, no lograron ponerse de acuerdo sobre quién debía sucederlo." },
        { "La disputa se convirtió en una guerra bajo la montaña. Los Barbabronce conservaron la ciudad. Los Martillo Salvaje, dirigidos por el señor feudal Khardros, fueron expulsados y levantaron su propia fortaleza en Grim Batol. Los Hierro Negro del hechicero y señor feudal Thaurissan se retiraron a las montañas del sur." },
        { "Los Hierro Negro no habían terminado. Marcharon contra Forjaz y Grim Batol a la vez y perdieron ambas batallas. Furioso, Thaurissan recurrió a un poder mucho más antiguo que cualquier clan y despertó a Ragnaros, el Señor del Fuego. El sur ardió. La Garganta de Fuego y Las Estepas Ardientes son lo que quedó, y desde entonces los Hierro Negro sirven al Señor del Fuego en la Montaña Roca Negra." },
        { "Los Martillo Salvaje tampoco permanecieron en Grim Batol. La muerte de la reina Modgud, abatida ante sus puertas, dejó una oscuridad en la piedra, y buscaron un nuevo hogar en Pico Nidal, en Tierras del Interior. Forjaz aún recuerda qué clan se quedó." },
      },
    },
    ["warlocks"] = {
      title = "Brujos",
      text = {
        { "Gul'dan introdujo la magia de los brujos en la Horda orca. Él y su Consejo de la Sombra la aprendieron de Kil'jaeden y con ella convirtieron a su pueblo en armas de la Legión Ardiente. Los brujos de la Horda resucitaron a los muertos, invocaron demonios y quemaron tierras enteras. Su arte sobrevivió a sus amos." },
        { "Ahora hay estudiantes a ambos lados. El Filo Ardiente aún sirve a la Legión en Durotar. Los brujos de Ventormenta se reúnen en el sótano del Cordero Degollado. Gnomos y Renegados también la estudian. Un brujo somete demonios, lanza maldiciones y paga el poder con su propia vida cuando no queda otra cosa." },
        { client = "forever", "Los Lanza Negra también cuentan ahora con brujos entre sus hechiceros." },
        { "La mayoría de las ciudades tolera a los brujos sin confiar en ellos, y los brujos parecen preferirlo así, $gviajero:viajera;." },
      },
    },
    ["warriors"] = {
      title = "Guerreros",
      text = {
        { "No hay una única orden de guerreros, solo un oficio tan antiguo como la primera disputa, $gviajero:viajera;. Los soldados de Lordaeron y caballeros de Ventormenta, los brutos orcos que derribaron esos mismos muros, los valientes tauren de las llanuras y los cazadores Lanza Negra de las islas aprendieron las mismas lecciones por caminos distintos." },
        { "Aun así, el oficio tiene sus escuelas. Un guerrero aprende a adoptar tres actitudes. La de batalla sirve para golpear primero y fuerte. La defensiva mantiene la línea tras un escudo. La furia rabiosa gasta las fuerzas del cuerpo sin medida y pide que se devuelvan después. Casi todo el trabajo consiste en aprender cuál exige el momento." },
        { "Toda capital tiene un salón donde los guerreros instruyen a los jóvenes. La Liga contrata a muchos como escoltas y aún no he conocido a ninguno que no tuviera una opinión sobre dónde deberían excavar los excavadores." },
      },
    },
    ["warsong-gulch"] = {
      title = "Garganta Grito de Guerra",
      text = {
        { "En la Garganta Grito de Guerra, en el extremo sur de Vallefresno, los elfos de la noche se han plantado contra el avance de la tala de los Grito de Guerra. Las Centinelas Ala de Plata ocupan un extremo del valle y la Escolta Grito de Guerra, el otro. Sus combatientes cruzan entre ambos campamentos para apoderarse del estandarte enemigo." },
        { "La Horda lo considera la defensa de una explotación maderera. La Alianza considera esa explotación una invasión. Ambas envían combatientes desde mucho más allá de Vallefresno." },
      },
    },
    ["warsong-gulch-tune"] = {
      title = "Garganta Grito de Guerra",
      text = {
        { "La Garganta Grito de Guerra tiene cinco piezas propias. Las Centinelas Ala de Plata luchan allí contra la Escolta Grito de Guerra por las hachas de los orcos y por los árboles que estos talan. Los elfos de la noche sostienen que este bosque es lo que hace defendible Vallefresno, y que Astranaar caería poco después que él." },
      },
    },
    ["warsong-lumber-camp"] = {
      title = "El Aserradero Grito de Guerra",
      text = {
        { "Cuando los orcos desembarcaron en Kalimdor, Thrall envió a Grom Grito Infernal y su clan Grito de Guerra a Vallefresno en busca de madera. Los guardianes del bosque no los querían allí, y el semidiós Cenarius, señor del propio bosque, se alzó contra ellos." },
        { "Grom no pudo vencerlo. Así que hizo lo que los orcos habían jurado no repetir: bebió la sangre del demonio Mannoroth. Con esa fuerza, los Grito de Guerra mataron a Cenarius en su propio bosque. La maldición del demonio volvió a caer sobre ellos. Los aserraderos Grito de Guerra siguen aquí y siguen talando. Los elfos de la noche tienen mucha memoria." },
      },
    },
    ["wendigos"] = {
      title = "Los wendigos",
      text = {
        { "El Cubil Pardo ofrece cobijo frente a la nieve de Dun Morogh, siempre que convenzas a sus wendigos de compartirlo. Un mensajero que huyó de ellos abandonó un cargamento de munición. Las criaturas defendieron mejor su postura." },
        { "El piloto Roscapiedra quiere sus crines para una alfombra dentro de su máquina de asedio, el Arado Trol. Hasta la maquinaria necesita cierta comodidad en estas tierras, $gviajero:viajera;. Tanto recuperar la munición como amueblar la máquina exige acercarse a un wendigo bastante más de lo que aquel mensajero estaba dispuesto a hacer." },
      },
    },
    ["western-plaguelands"] = {
      title = "Tierras de la Peste del Oeste",
      text = {
        { "Las Tierras de la Peste del Oeste fueron fértiles campos de Lordaeron. El grano infectado llevó la no-muerte a sus aldeas. Campos grises, graneros podridos y árboles enfermos rodean ahora a los muertos que aún los recorren. Un veneno verde se cierne sobre la tierra que alimentaba al reino." },
        { "El Campamento del Orvallo alberga a la Alianza y al Alba Argenta al sur, los Renegados conservan El Baluarte al oeste y la Cruzada Escarlata mantiene Vega del Amparo al norte. Entre esos enclaves están Andorhal, los calderos de peste y Scholomance en el lago. La ruta del viajero por estas tierras se mide por los lugares donde los vivos aún conservan terreno." },
      },
    },
    ["westfall"] = {
      title = "Páramos de Poniente",
      text = {
        { "Páramos de Poniente era el granero de Ventormenta: amplios campos dorados, molinos y granjas que descendían hasta el mar. Los orcos lo quemaron durante las guerras, y los granjeros regresaron y volvieron a sembrar. Lo que los orcos no pudieron terminar lo han hecho los Defias." },
        { "La Hermandad se adueñó de Páramos de Poniente. Expulsó a las familias de sus tierras, granja por granja, tomó Arroyo de la Luna como población y las antiguas minas de debajo como fortaleza, y el ejército del rey nunca llegó. 'Ventormenta nos ha abandonado', te dirán los hombres de la Colina del Centinela, y cuesta rebatirlos. Ahora los campos están secos, los gnolls Zarparrío asaltan las granjas y los gólems de la cosecha acechan en los surcos. Los múrlocs ocupan la costa y hasta el faro está embrujado." },
        { "Algunos granjeros obstinados se han quedado. Pregunta al granjero Saldean por qué y te dirá que es su tierra." },
      },
    },
    ["wetlands"] = {
      title = "Los Humedales",
      text = {
        { "Al norte de las montañas, el suelo se ablanda y el aire se vuelve gris. Estás en Los Humedales: marismas, juncos y lluvia, desde el paso de Dun Algaz hasta el mar en el Puerto de Menethil." },
        { "Antes era tierra enana, unida a los reinos humanos por el Puente Thandol. Ahora es un cruce de guerras ajenas. Los orcos Faucedraco dominan las colinas, los Hierro Negro han tomado nuestra fortaleza de Dun Modr, gnolls y múrlocs llenan las marismas y, al este, Grim Batol se cierne sobre todo ello." },
        { "Sigue el camino, mantén seca la pólvora y no te entretengas después de anochecer." },
      },
    },
    ["whelgars-excavation-site"] = {
      title = "Excavación de Whelgar",
      text = {
        { "Otra excavación de la Liga, esta en las marismas de Los Humedales, bajo el prospector Whelgar. La marisma conserva lo que se traga, y la Liga tenía grandes esperanzas en lo que yacía debajo." },
        { "Después llegaron los raptores. Se instalaron en la excavación y trataron a los excavadores como presas. Los miembros de la Liga tuvieron que retirarse a una cresta sobre el yacimiento, donde algunos aún esperan a que se marchen las bestias." },
        { "Si pasas por allí, ve a verlos. Les alegrará mucho ver a alguien con un arma." },
      },
    },
    ["whitemane-and-mograine"] = {
      title = "Melenablanca y Mograine",
      text = {
        { "La alta inquisidora Sally Melenablanca y el comandante Escarlata Renault Mograine dominan la catedral del Monasterio Escarlata. Él manda a sus caballeros. Ella guía su fe. Su dominio de la Luz le permite levantarlo cuando cae, por lo que vencer al comandante resulta menos definitivo de lo que un viajero podría esperar." },
        { "Renault es hijo del alto señor Alexandros Mograine, el Crematoria, un gran campeón de la Mano de Plata contra la Plaga. Su padre ha muerto. Ribalimpia, otro alto inquisidor oculto en la catedral, afirma saber cómo murió y asegura que Renault estaba allí. La Cruzada preferiría que guardase silencio. Quienes lleven la hoja del alto señor podrán oír el relato que no quiere que se cuente. La página de la Crematoria en este registro recoge sus palabras." },
        { side = "Horde", aside = true, sign = "P. F.", "Melenablanca resucita a su comandante y la Cruzada nos quema a los demás por menos." },
      },
    },
    ["wildhammer-clan"] = {
      title = "El clan Martillo Salvaje",
      text = {
        { "Los Martillo Salvaje fueron uno de los tres martillos del antiguo reino de Khaz Modan. Tras la guerra que los separó, establecieron su hogar en Grim Batol. Cuando la reina Hierro Negro Modgud murió allí, dejó una oscuridad en la piedra. Los Martillo Salvaje se marcharon al norte, a Tierras del Interior. Desde entonces viven al aire libre, montan grifos y conservan las antiguas costumbres de los espíritus." },
        { "Son orgullosos, fieros, muy independientes y creen que los de Forjaz llevamos demasiado tiempo bajo tierra. Durante la Segunda Guerra, sus jinetes de grifos lucharon por la Alianza y fueron el terror de los dragones de la Horda. Ahora deciden por sí mismos y eligen a sus amigos, entre ellos los altos elfos Vallealto, algo que los trols de Tierras del Interior resienten." },
      },
    },
    ["wildkin"] = {
      title = "Los lechúcicos",
      text = {
        { "A los grandes osos búho del norte los llaman lechúcicos o lechúcicos lunares. Los elfos de la noche los tratan con una reverencia que no todos los viajeros comparten. Se rumorea que los creó la propia Elune y algunos dicen que fueron sus mascotas. Un estudioso elfo que examina sus plumas encuentra en ellas una magia que las criaturas no manejan tanto como llevan consigo, parte de su propia naturaleza." },
        { "Pueden mostrar gran dulzura y gran ferocidad, sobre todo si se amenaza algo que les importa. En Cuna del Invierno se dice que custodian secretos de los elfos de la noche. Algunos han enloquecido allí, según los informes, por pasar demasiado tiempo junto a aquello que protegen." },
        { "Últimamente hay menos mansos. Los lechúcicos de Costa Oscura se sienten atraídos por un gran cristal rojo de las colinas orientales y las centinelas de Auberdine ya no los consideran inofensivos. Yo dejaría bastante espacio a cualquier oso búho y más aún a uno enloquecido, $gviajero:viajera;." },
      },
    },
    ["windshear-crag"] = {
      title = "Risco Cortaviento",
      text = {
        { "El Risco Cortaviento es el gran campamento maderero y minero de Ventura y Cía. en el norte de la Sierra Espolón: un valle de tocones, sierras, ruedas hidráulicas y trituradoras, esas máquinas con forma humana que talan más deprisa que cualquier cuadrilla. Por encima de todo, cerca de la gran rueda, vive su capataz, Gerenzo Silbillave, un goblin que a estas alturas tiene más metal que carne." },
        { "La Vega Carbonizada, al sur, es lo que deja la compañía: un bosque entero quemado. Los druidas quieren volver a plantarlo, los chamanes quieren detener las máquinas y hasta algunos ingenieros de la propia compañía han renunciado, asqueados." },
      },
    },
    ["wintersaber-trainers"] = {
      title = "Los instructores de sableinvernales",
      text = {
        { "En lo alto de Roca Sable de Hielo, al norte de Cuna del Invierno, unos pocos elfos de la noche crían los sables blancos del norte. Su dirigente, Rivern Ventogélido, permanece apartado. Dice que la mayoría no nota su presencia, y eso le conviene." },
        { "No es fácil ganarse uno de esos felinos. Rivern empieza enviando a quien lo quiere a buscar carne de quimeras y osos dentoesquirla para alimentar a los jóvenes sables en formación. Después pide ayuda contra los fúrbolgs Nevada que perturban la roca. Es un aprendizaje largo y pocos lo terminan." },
        { "Quienes lo hacen salen de Cuna del Invierno sobre un sable de hielo que, según me dicen, vale cada encargo. Los felinos, por su parte, parecen creer que el acuerdo fue idea suya." },
      },
    },
    ["winterspring"] = {
      title = "Cuna del Invierno",
      text = {
        { "Cuna del Invierno es el alto valle nevado al norte de Frondavil y al este del Claro de la Luna, una tierra de nieve profunda, lagos helados y aguas termales que humean en el frío. Aquí cazan sables de hielo, y hay búhos, yetis, gigantes y lechúcicos. Los elfos de la noche crían sus sables de hielo en Roca Sable de Hielo y los druidas mantienen una aldea en Estrella Fugaz." },
        { "Los fúrbolgs de la tribu Nevada beben aguardiente corrupto traído de Frondavil y enloquecen con él. Los dragones azules tienen su guarida en las cuevas de Mazthoril y los goblins de Vista Eterna venden de todo a todos en la encrucijada." },
      },
    },
    ["worgen"] = {
      title = "Los ferocanis",
      text = {
        { "Arugal invocó ferocanis de otro mundo mientras los defensores de Dalaran caían ante la Plaga. Los hombres lobo atacaron a los muertos y después se volvieron contra los vivos. El mago se retiró al Castillo de Colmillo Oscuro, los llamó sus hijos y maldijo a Piroleña, cuyos habitantes son humanos de día y ferocanis de noche." },
        { "El Bosque del Ocaso ofrece otro rastro. La Guardia Nocturna informa de su aparición repentina en una mina al sur de Villa Oscura. Los relatos apuntan a la Guadaña de Elune, una antigua reliquia élfica llevada al bosque por alguien que no comprendía su poder." },
        { "Las criaturas son fuertes, astutas y capaces de correr a cuatro patas pese a su forma erguida. Mantén separados los dos rastros, $gviajero:viajera;. Saber quién las trajo a un bosque no ha explicado su aparición en el otro." },
      },
    },
    ["zaetar-and-theradras"] = {
      title = "Zaetar y Theradras",
      text = {
        { "Zaetar era hijo de Cenarius, un ser del bosque. Theradras era una princesa de la tierra elemental. De su unión nacieron los centauros, que mataron a su propio padre. Theradras lo sepultó en las cavernas de Maraudon, donde sus hijos aún lo veneran y custodian su tumba." },
        { "Un druida del Círculo Cenarion espera cerca de Cazasombras a alguien capaz de enfrentarse a Theradras y recuperar los restos de Zaetar. El suelo sagrado de los centauros también es el lugar de reposo de un miembro de la familia de Cenarius." },
      },
    },
    ["zamael-lunthistle"] = {
      title = "Zamael Cardolún",
      text = {
        { "En una jaula, entre los campamentos del Martillo Crepuscular en La Garganta de Fuego, está el espíritu de un elfo de la noche, y agradece la compañía. Hace muchos años que no recibe visitantes, dice Zamael Cardolún." },
        { "Cuando era un joven elfo de la noche en Costa Oscura, se cruzó con el Martillo Crepuscular. Algunos de ellos entablaron amistad con él y, para su vergüenza, él perdió la fe en Elune, abrazó el rencor del culto y sus dioses antiguos, e hizo mucho daño en el mundo por su causa. Entonces tuvo una visión procedente de Elune que lo despertó. Arrepentido, empezó a componer una oración para la diosa y grabó su arrepentimiento, su vergüenza, su pesar y su tristeza en una tablilla de oro puro. El culto encontró la tablilla, lo llamó blasfemo y lo ejecutó con la oración sin terminar. Su espíritu sigue atado a este mundo, y la jaula lo retiene aquí como advertencia para cualquiera que traicione al Martillo." },
        { "Ha aceptado la jaula. Lo que pide es que alguien encuentre la oración entre los idólatras del Martillo y la lleve a Astarii Buscaestelar, en Darnassus, para que sea escuchada. La absolución, dice, es lo último que espera." },
      },
    },
    ["zandalar-tribe"] = {
      title = "La Tribu Zandalar",
      text = {
        { "Los Zandalar se describen como la tribu trol más antigua, de la que descienden las demás. Sus sacerdotes y estudiosos conservan la memoria de su pueblo y sus dioses. Rara vez intervienen en los asuntos de otros pueblos, pero el regreso de Hakkar los ha traído a la Isla Yojamba, frente a Tuercespina." },
        { "Su líder, Molthor, colaborará con cualquiera dispuesto a oponerse al Cazador de Almas. La invitación incluye a personas a las que los trols normalmente tendrían pocos motivos para recibir." },
      },
    },
    ["zanzil-the-outcast"] = {
      title = "Zanzil el Desarraigado",
      text = {
        { "Zanzil el Desarraigado domina las Ruinas de Jubuwal y las Ruinas de Aboraz, en la costa al noreste de la Bahía del Botín, rodeado de seguidores que no parecen del todo dueños de sí. Era médico brujo hasta que los líderes de su propia tribu empezaron a temerle y lo expulsaron. Su arte es una mezcla de plantas de la jungla que anula la voluntad y fortalece el cuerpo, y sus zombis, cazadores y médicos brujos están todos impregnados de ella." },
        { "Los Lanza Negra tienen un agravio especial contra él. Por una vieja costumbre entregaron a Yenniku, el hijo menor de su jefe, a los Gurubashi de Zul'Gurub, y lo perdieron cuando se marcharon con Thrall. Nimboya volvió desde la lejana Orgrimmar para encontrar al muchacho y supo que Zanzil lo dominaba en cuerpo y alma. Hizo falta el Ojo de la mente, una joya arrebatada al mago ogro Mai'Zoth y convertida en una gema de alma, para sacar el alma de Yenniku del poder de Zanzil." },
        { "Su mezcla tiene compradores. Loquillo Pinchabujas, en la Bahía del Botín, paga por las muestras, y algo más por la discreción. Los trols que desterraron a Zanzil temían lo que podía hacer con la mente de los demás." },
      },
    },
    ["zephras-isle"] = {
      title = "Isla de Zephras",
      text = {
        { "La Isla de Zephras es una isla que vuela. Está suspendida en Muro Celeste, el plano elemental del aire, adonde los espíritus del viento llevaron a los shen'dorei hace mucho. Es el hogar de los cielonatos que han descendido hasta nosotros hace poco. Su gente vive en Valanaar, al sureste, en las aldeas de Tierras Altas de Shen'dar y en Thendal, y en las granjas de Tierras Bajas de los Soplabayas." },
        { "Los espíritus que mantenían unida la isla se marcharon hace algunos siglos. Sus grandes pilones de anclaje aún sostienen Zephras, pero su magia es inestable. Una noche, Ban'aethal empezó a caer al cielo y tuvieron que evacuarlo antes del amanecer. Hace tiempo que ningún cortacielos cruza a las otras islas, Anvilas y Siroccas. Algunos shen'dorei temen ser todo lo que queda de su pueblo." },
        { "Nunca he estado allí y te envidio un poco, $gviajero:viajera;. Mantente lejos de los bordes." },
      },
    },
    ["zephras-isle-tune"] = {
      title = "Isla de Zephras",
      text = {
        { "Buena parte de la Isla de Zephras comparte una melodía, desde los Muelles Aéreos de Valanaar y las Agujas Rohashi hasta la Guarida de Chilladoras y la Caverna Garranoche. Donde una aldea o un lugar sagrado tiene música propia, esa toma el relevo, y donde termina vuelve esta. Pocas cosas en la isla son tan fiables hoy en día." },
      },
    },
    ["zul-gurub-tune"] = {
      title = "Zul'Gurub",
      text = {
        { "Los trols Zandalar han acampado en la Isla Yojamba, frente a la costa de la Vega de Tuercespina, y la misma pieza suena en el Foso de las Llamas de Sangre, dentro de Zul'Gurub. Los Zandalar han venido a detener a Hakkar el Cazador de Almas, el dios de la sangre, antes de que su reinado se extienda por todo Azeroth. No les da vergüenza pedir ayuda, y poco les importa lo que creas." },
      },
    },
    ["zulfarrak"] = {
      title = "Zul'Farrak",
      text = {
        { "Zul'Farrak es la ciudad de los trols Furiarena, una ciudad amurallada de arenisca al oeste de Tanaris, con pirámides, santuarios y una laguna sagrada donde se invoca desde las profundidades a la hidra Gahz'rilla. La gobierna el jefe Ukorz Cabellarena y dentro de sus muros está el santuario del mártir Theka." },
        { "Muchos vienen por lo que guardan los trols. Las tablillas de la profecía de Mosh'aru hablan de una forma de contener la esencia del dios Hakkar. También hay una hoja legendaria y el agente de temple de los trols, muy apreciado por los herreros. Y hay tesoros, que atraen a goblins y necios por igual. La mayoría nunca sale." },
      },
    },
    ["zulgurub"] = {
      title = "Zul'Gurub",
      text = {
        { "Zul'Gurub fue la ciudad templo del corazón del imperio Gurubashi. Tras siglos de silencio, vuelve a ser la ciudad de Hakkar. Los sumos sacerdotes enviados contra él han caído bajo su poder y los Zandalar deben buscar ayuda más allá de su pueblo." },
        { "Los sacerdotes cautivos adoptan las formas de los antiguos dioses animales: murciélago, pantera, tigre, serpiente y araña. El sacrificio alimenta el altar del Cazador de Almas. Los Zandalar advierten que su creciente poder amenaza a todo Azeroth. Si entras, recuerda por qué te han pedido ir: hasta quienes fueron a detenerlo se convirtieron en instrumentos de su dominio." },
      },
    },
  },
})
